on conflict do nothing;

insert into private.task_solutions (task_id, correct_option_ids, explanation, solution_files)
select t.id, v.correct_option_ids, v.explanation, v.solution_files from (values
  ('ng-computed-signal', array['b']::text[], '{"en":"`computed` tracks the signals it reads. When `count` changes, `double` is marked stale and recomputes lazily the next time it''s read, so it returns 10. Computed signals are read-only, but reading them is always allowed.","uk":"`computed` відстежує сигнали, які читає. Коли `count` змінюється, `double` позначається застарілим і ліниво перераховується при наступному читанні, тож повертає 10. Обчислювані сигнали лише для читання, але читати їх можна завжди."}'::jsonb, null::jsonb),
  ('ng-outside-zone', array['a']::text[], '{"en":"zone.js triggers change detection when async work that started inside the Angular zone finishes. Libraries initialised outside the zone (often on purpose, with `runOutsideAngular`, for performance) call back without Angular knowing. Re-enter the zone with `ngZone.run()`, or update a signal, which schedules change detection by itself.","uk":"zone.js запускає виявлення змін, коли завершується асинхронна робота, розпочата в зоні Angular. Бібліотеки, ініціалізовані поза зоною (часто навмисно, через `runOutsideAngular`, заради швидкодії), викликають колбеки без відома Angular. Поверніться в зону через `ngZone.run()` або оновіть сигнал — він сам запланує виявлення змін."}'::jsonb, null::jsonb),
  ('ng-effect-batching', array['b']::text[], '{"en":"Setting a signal only marks its dependents dirty. Effects are scheduled and run later, as part of change detection, not synchronously inside `set()`. By then the value is 2, so the effect runs once and logs `2`. Don''t use effects to observe every intermediate value; they see the latest state.","uk":"Встановлення сигналу лише позначає залежних як «брудних». Ефекти плануються й виконуються пізніше, у межах виявлення змін, а не синхронно всередині `set()`. На той момент значення вже 2, тож ефект виконається один раз і виведе `2`. Не використовуйте ефекти, щоб спостерігати кожне проміжне значення: вони бачать останній стан."}'::jsonb, null::jsonb),
  ('ng-highlight-directive', null::text[], '{"en":"An attribute directive changes the behaviour or look of an existing element. `@HostListener` subscribes to the host''s events (and runs change detection afterwards), and `@HostBinding(\"style.backgroundColor\")` keeps the style in sync with a property, so the directive never queries or mutates the DOM itself, which keeps it safe for server rendering. Keeping `hovered` and `focused` as separate flags and deriving the colour in one `update()` method, also called from `ngOnChanges`, makes input changes take effect immediately. In modern Angular you''d write the same with `host: { ''(mouseenter)'': ''…'', ''[style.backgroundColor]'': ''background()'' }` and `input()` signals in a standalone directive.","uk":"Атрибутна директива змінює поведінку чи вигляд наявного елемента. `@HostListener` підписується на події хост-елемента (і після них запускає виявлення змін), а `@HostBinding(\"style.backgroundColor\")` синхронізує стиль із властивістю, тож директива ніколи сама не шукає й не змінює DOM, і це робить її безпечною для серверного рендеру. Окремі прапорці `hovered` і `focused` та обчислення кольору в одному методі `update()`, який викликається й з `ngOnChanges`, змушують зміни вхідних даних діяти одразу. У сучасному Angular те саме пишуть через `host: { ''(mouseenter)'': ''…'', ''[style.backgroundColor]'': ''background()'' }` і сигнали `input()` у standalone-директиві."}'::jsonb, '{"/src/app/highlight.directive.ts":"import { Directive, HostBinding, HostListener, Input, OnChanges } from \"@angular/core\";\n\n@Directive({ selector: \"[appHighlight]\" })\nexport class HighlightDirective implements OnChanges {\n  @Input() appHighlight = \"\";\n  @Input() highlightDisabled = false;\n\n  /** Bound to the host element''s style.backgroundColor. */\n  @HostBinding(\"style.backgroundColor\") background = \"\";\n\n  private hovered = false;\n  private focused = false;\n\n  @HostListener(\"mouseenter\") onMouseEnter() {\n    this.hovered = true;\n    this.update();\n  }\n  @HostListener(\"mouseleave\") onMouseLeave() {\n    this.hovered = false;\n    this.update();\n  }\n  // Keyboard users get the same feedback as mouse users.\n  @HostListener(\"focusin\") onFocusIn() {\n    this.focused = true;\n    this.update();\n  }\n  @HostListener(\"focusout\") onFocusOut() {\n    this.focused = false;\n    this.update();\n  }\n\n  // Inputs can change while the element is highlighted (new colour, disabled).\n  ngOnChanges() {\n    this.update();\n  }\n\n  private update() {\n    const active = (this.hovered || this.focused) && !this.highlightDisabled;\n    this.background = active ? this.appHighlight || \"yellow\" : \"\";\n  }\n}\n"}'::jsonb),
  ('ng-if-role-directive', null::text[], '{"en":"The `*` is sugar: Angular wraps the element in an `<ng-template>` and passes the expression to the `appIfRole` input and `else denied` to `appIfRoleElse` (the selector name plus the capitalised keyword). The directive receives that template as a `TemplateRef` and decides what to stamp into its `ViewContainerRef`. Tracking which view is currently shown and returning early when nothing changes avoids destroying and recreating DOM (and any component state inside) on every emission. Subscribing in `ngOnInit` and unsubscribing in `ngOnDestroy` prevents leaks when the directive''s host disappears. Today you might implement the same check as a route guard or with `@if (canEdit())` and a computed signal, but structural directives remain the way to package reusable template logic.","uk":"`*` є синтаксичним цукром: Angular загортає елемент в `<ng-template>` і передає вираз у вхідні дані `appIfRole`, а `else denied` у `appIfRoleElse` (назва селектора плюс ключове слово з великої літери). Директива отримує цей шаблон як `TemplateRef` і вирішує, що вставити у свій `ViewContainerRef`. Відстеження поточного показаного подання й ранній вихід, коли нічого не змінилося, запобігають знищенню й повторному створенню DOM (і будь-якого стану компонентів усередині) на кожне значення. Підписка в `ngOnInit` і відписка в `ngOnDestroy` запобігають витокам, коли хост директиви зникає. Сьогодні ту саму перевірку можна реалізувати як guard маршруту чи через `@if (canEdit())` з обчислюваним сигналом, але структурні директиви лишаються способом пакувати багаторазову логіку шаблонів."}'::jsonb, '{"/src/app/if-role.directive.ts":"import { Directive, Input, OnDestroy, OnInit, TemplateRef, ViewContainerRef } from \"@angular/core\";\nimport { Subscription } from \"rxjs\";\nimport { AuthService, Role } from \"./auth.service\";\n\n@Directive({ selector: \"[appIfRole]\" })\nexport class IfRoleDirective implements OnInit, OnDestroy {\n  private allowed: Role[] = [];\n  private elseTemplate: TemplateRef<unknown> | null = null;\n  private role: Role | null = null;\n  private shown: \"then\" | \"else\" | \"none\" | null = null;\n  private subscription?: Subscription;\n\n  constructor(\n    private template: TemplateRef<unknown>,\n    private container: ViewContainerRef,\n    private auth: AuthService,\n  ) {}\n\n  @Input() set appIfRole(roles: Role | Role[]) {\n    this.allowed = Array.isArray(roles) ? roles : [roles];\n    this.render();\n  }\n\n  @Input() set appIfRoleElse(template: TemplateRef<unknown> | null) {\n    this.elseTemplate = template;\n    this.shown = null; // the else view may need replacing\n    this.render();\n  }\n\n  ngOnInit() {\n    this.subscription = this.auth.role$.subscribe((role) => {\n      this.role = role;\n      this.render();\n    });\n  }\n\n  ngOnDestroy() {\n    if (this.subscription) this.subscription.unsubscribe();\n  }\n\n  private render() {\n    if (this.role === null) return;\n    const next = this.allowed.includes(this.role) ? \"then\" : this.elseTemplate ? \"else\" : \"none\";\n    if (next === this.shown) return; // nothing changed: keep the existing view (and its DOM and state)\n    this.container.clear();\n    if (next === \"then\") this.container.createEmbeddedView(this.template);\n    if (next === \"else\" && this.elseTemplate) this.container.createEmbeddedView(this.elseTemplate);\n    this.shown = next;\n  }\n}\n"}'::jsonb),
  ('ng-file-size-pipe', null::text[], '{"en":"A pipe is a pure function exposed to templates. Pipes are **pure** by default: Angular calls `transform` again only when the input reference or an argument changes, so formatting in a pipe is cheaper than calling a method from the template, which runs on every change detection. (An impure pipe, `pure: false`, runs every time, which is needed only for things like the `async` pipe.) The implementation divides by 1024 until the value fits, rounds with `Math.round(value * 10 ** digits) / 10 ** digits` and lets number-to-string conversion drop trailing zeros, then handles the edge case where rounding itself reaches the next unit. In modern Angular the pipe would be `standalone: true` (the default since v19) and imported directly by the components that use it.","uk":"Pipe є чистою функцією, доступною в шаблонах. Pipe за замовчуванням **чисті**: Angular знову викликає `transform`, лише коли змінюється посилання на вхідне значення чи аргумент, тож форматування в pipe дешевше за виклик методу з шаблону, що виконується під час кожного виявлення змін. (Нечиста pipe, `pure: false`, виконується щоразу, і це потрібно лише для таких речей, як pipe `async`.) Реалізація ділить на 1024, доки значення не вміститься, округлює через `Math.round(value * 10 ** digits) / 10 ** digits` і дає перетворенню числа на рядок відкинути нулі в кінці, а потім обробляє крайній випадок, коли саме округлення доходить до наступної одиниці. У сучасному Angular pipe була б `standalone: true` (за замовчуванням з v19) й імпортувалася б напряму компонентами, що її використовують."}'::jsonb, '{"/src/app/file-size.pipe.ts":"import { Pipe, PipeTransform } from \"@angular/core\";\n\nconst UNITS = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\"];\n\n// A pure pipe (the default): Angular only re-runs it when the input value or an argument changes.\n@Pipe({ name: \"fileSize\" })\nexport class FileSizePipe implements PipeTransform {\n  transform(bytes: number | null | undefined, digits = 1): string {\n    if (typeof bytes !== \"number\" || !Number.isFinite(bytes) || bytes < 0) return \"—\";\n    let unit = 0;\n    let value = bytes;\n    while (value >= 1024 && unit < UNITS.length - 1) {\n      value /= 1024;\n      unit++;\n    }\n    if (unit === 0) return Math.round(value) + \" B\";\n    const factor = 10 ** digits;\n    let rounded = Math.round(value * factor) / factor;\n    // 1023.99 KB rounds to 1024 KB: show it as 1 MB instead.\n    if (rounded >= 1024 && unit < UNITS.length - 1) {\n      unit++;\n      rounded = Math.round((value / 1024) * factor) / factor;\n    }\n    return rounded + \" \" + UNITS[unit]; // number → string drops trailing zeros (1.0 → \"1\")\n  }\n}\n"}'::jsonb),
  ('ng-hierarchical-di', null::text[], '{"en":"Angular resolves a dependency by walking up the **element injector** tree (component and directive `providers` along the template hierarchy) and then the module/root injector. `providedIn: ''root''` creates one app-wide singleton, which is right for `ClickLogger` and wrong for per-counter state; listing `CounterService` in the component''s `providers` gives every `app-counter` its own instance. An `InjectionToken` provides non-class values like numbers or configuration, injected with `@Inject(COUNTER_STEP)`. Because projected content resolves its injector from where it sits in the template, a component''s `providers` (unlike `viewProviders`) are visible to the content placed inside it, which is how `app-fast-zone` overrides the step for its children. In modern Angular you''d write `private step = inject(COUNTER_STEP)` instead of constructor parameters; the injector hierarchy is the same.","uk":"Angular знаходить залежність, ідучи вгору деревом **інжекторів елементів** (`providers` компонентів і директив уздовж ієрархії шаблонів), а потім інжектором модуля/кореня. `providedIn: ''root''` створює один синглтон на весь застосунок, що правильно для `ClickLogger` і неправильно для стану окремого лічильника; перелік `CounterService` у `providers` компонента дає кожному `app-counter` власний екземпляр. `InjectionToken` надає значення, що не є класами, як-от числа чи конфігурацію, і впроваджується через `@Inject(COUNTER_STEP)`. Оскільки спроєктований вміст знаходить свій інжектор за місцем у шаблоні, `providers` компонента (на відміну від `viewProviders`) видимі для вмісту, розміщеного всередині нього, і саме так `app-fast-zone` перевизначає крок для своїх дочірніх елементів. У сучасному Angular замість параметрів конструктора пишуть `private step = inject(COUNTER_STEP)`; ієрархія інжекторів та сама."}'::jsonb, '{"/src/app/counter.service.ts":"import { Inject, Injectable } from \"@angular/core\";\nimport { ClickLogger } from \"./click-logger.service\";\nimport { COUNTER_STEP } from \"./tokens\";\n\n// Not providedIn root: each component that lists it in providers gets its own instance.\n@Injectable()\nexport class CounterService {\n  value = 0;\n\n  constructor(@Inject(COUNTER_STEP) private step: number, private logger: ClickLogger) {}\n\n  increment(label: string) {\n    this.value += this.step;\n    this.logger.record(label);\n  }\n}\n","/src/app/counter.component.ts":"import { Component, Input } from \"@angular/core\";\nimport { CounterService } from \"./counter.service\";\n\n@Component({\n  selector: \"app-counter\",\n  template: `\n    <p>\n      {{ label }}: <span [attr.data-testid]=\"''count-'' + label\">{{ counter.value }}</span>\n      <button type=\"button\" [attr.aria-label]=\"''Add to '' + label\" (click)=\"counter.increment(label)\">Add</button>\n    </p>\n  `,\n  providers: [CounterService], // one CounterService per app-counter\n})\nexport class CounterComponent {\n  @Input() label = \"\";\n  constructor(public counter: CounterService) {}\n}\n","/src/app/fast-zone.component.ts":"import { Component } from \"@angular/core\";\nimport { COUNTER_STEP } from \"./tokens\";\n\n// providers (not viewProviders) are visible to projected content, like the app-counter placed inside.\n@Component({\n  selector: \"app-fast-zone\",\n  template: `<fieldset><legend>Fast zone</legend><ng-content></ng-content></fieldset>`,\n  providers: [{ provide: COUNTER_STEP, useValue: 10 }],\n})\nexport class FastZoneComponent {}\n","/src/app/app.module.ts":"import { NgModule } from \"@angular/core\";\nimport { BrowserModule } from \"@angular/platform-browser\";\nimport { AppComponent } from \"./app.component\";\nimport { CounterComponent } from \"./counter.component\";\nimport { FastZoneComponent } from \"./fast-zone.component\";\nimport { COUNTER_STEP } from \"./tokens\";\n\n@NgModule({\n  declarations: [AppComponent, CounterComponent, FastZoneComponent],\n  imports: [BrowserModule],\n  providers: [{ provide: COUNTER_STEP, useValue: 1 }],\n  bootstrap: [AppComponent],\n})\nexport class AppModule {}\n"}'::jsonb),
  ('ng-signup-reactive-form', null::text[], '{"en":"Reactive forms describe the form in code: `FormBuilder.group` takes, for each control, `[initial value, sync validators, async validators]`, plus options for the group. Validators are plain functions returning `null` or an error map, so `hasDigit` and the cross-field `passwordsMatch` (on the **group**, because it needs two controls) are easy to write and test. Async validators run only after the sync ones pass, and Angular unsubscribes from the previous run on every keystroke, so a `timer(300)` inside works as a debounce. While one is running the form is `pending`, which the submit button must respect. Showing errors only after `dirty || touched` avoids shouting at users who haven''t typed yet. In modern Angular the same form is typed (`FormGroup<{ username: FormControl<string> … }>`), and the new Signal Forms API builds on the same validator ideas.","uk":"Реактивні форми описують форму в коді: `FormBuilder.group` приймає для кожного елемента керування `[початкове значення, синхронні валідатори, асинхронні валідатори]` плюс параметри для групи. Валідатори є звичайними функціями, що повертають `null` чи мапу помилок, тож `hasDigit` і міжпольовий `passwordsMatch` (на **групі**, бо йому потрібні два елементи) легко писати й тестувати. Асинхронні валідатори виконуються лише після проходження синхронних, а Angular відписується від попереднього запуску на кожне натискання клавіші, тож `timer(300)` усередині працює як debounce. Поки такий валідатор виконується, форма перебуває в стані `pending`, і кнопка надсилання має це враховувати. Показ помилок лише після `dirty || touched` не кричить на користувачів, які ще нічого не ввели. У сучасному Angular та сама форма типізована (`FormGroup<{ username: FormControl<string> … }>`), а новий API Signal Forms спирається на ті самі ідеї валідаторів."}'::jsonb, '{"/src/app/signup.component.ts":"import { Component, EventEmitter, Output } from \"@angular/core\";\nimport { AsyncValidatorFn, FormBuilder, ValidatorFn, Validators } from \"@angular/forms\";\nimport { of, timer } from \"rxjs\";\nimport { map, switchMap } from \"rxjs/operators\";\nimport { UsernameService } from \"./username.service\";\n\ntype Field = \"username\" | \"email\" | \"password\" | \"confirm\";\n\nexport const hasDigit: ValidatorFn = (control) => (/\\d/.test(control.value || \"\") ? null : { digit: true });\n\n/** A group-level validator: it can see several controls at once. */\nexport const passwordsMatch: ValidatorFn = (group) => {\n  const password = group.get(\"password\");\n  const confirm = group.get(\"confirm\");\n  return password && confirm && confirm.value && password.value !== confirm.value ? { mismatch: true } : null;\n};\n\n/** Async validators run only after the sync ones pass; the timer debounces typing. */\nexport function usernameAvailable(service: UsernameService): AsyncValidatorFn {\n  return (control) =>\n    !control.value\n      ? of(null)\n      : timer(300).pipe(\n          switchMap(() => service.isTaken(control.value)),\n          map((taken) => (taken ? { taken: true } : null)),\n        );\n}\n\nconst REQUIRED: Record<Field, string> = {\n  username: \"Username is required\",\n  email: \"Email is required\",\n  password: \"Password is required\",\n  confirm: \"Please confirm your password\",\n};\n\n@Component({\n  selector: \"app-signup\",\n  template: `\n    <form [formGroup]=\"form\" (ngSubmit)=\"submit()\" novalidate>\n      <label for=\"username\">Username</label>\n      <input id=\"username\" formControlName=\"username\" autocomplete=\"username\" />\n      <p class=\"error\" *ngIf=\"errorFor(''username'') as message\">{{ message }}</p>\n\n      <label for=\"email\">Email</label>\n      <input id=\"email\" type=\"email\" formControlName=\"email\" autocomplete=\"email\" />\n      <p class=\"error\" *ngIf=\"errorFor(''email'') as message\">{{ message }}</p>\n\n      <label for=\"password\">Password</label>\n      <input id=\"password\" type=\"password\" formControlName=\"password\" autocomplete=\"new-password\" />\n      <p class=\"error\" *ngIf=\"errorFor(''password'') as message\">{{ message }}</p>\n\n      <label for=\"confirm\">Confirm password</label>\n      <input id=\"confirm\" type=\"password\" formControlName=\"confirm\" autocomplete=\"new-password\" />\n      <p class=\"error\" *ngIf=\"errorFor(''confirm'') as message\">{{ message }}</p>\n\n      <button type=\"submit\" [disabled]=\"form.invalid || form.pending\">Create account</button>\n    </form>\n  `,\n})\nexport class SignupComponent {\n  @Output() created = new EventEmitter<{ username: string; email: string }>();\n\n  form = this.fb.group(\n    {\n      username: [\"\", [Validators.required, Validators.minLength(3)], [usernameAvailable(this.usernames)]],\n      email: [\"\", [Validators.required, Validators.email]],\n      password: [\"\", [Validators.required, Validators.minLength(8), hasDigit]],\n      confirm: [\"\", Validators.required],\n    },\n    { validators: passwordsMatch },\n  );\n\n  constructor(private fb: FormBuilder, private usernames: UsernameService) {}\n\n  errorFor(field: Field): string | null {\n    const control = this.form.get(field);\n    if (!control || !(control.dirty || control.touched)) return null; // don''t shout before the user has typed\n    const errors = control.errors;\n    if (!errors) return field === \"confirm\" && this.form.hasError(\"mismatch\") ? \"Passwords don''t match\" : null;\n    if (errors.required) return REQUIRED[field];\n    if (errors.minlength) return \"At least \" + errors.minlength.requiredLength + \" characters\";\n    if (errors.email) return \"Enter a valid email\";\n    if (errors.digit) return \"Include a number\";\n    if (errors.taken) return \"Username is taken\";\n    return null;\n  }\n\n  submit() {\n    if (this.form.invalid || this.form.pending) return;\n    const { username, email } = this.form.value;\n    this.created.emit({ username, email }); // never pass passwords around\n    this.form.reset();\n  }\n}\n"}'::jsonb),
  ('ng-rating-control-value-accessor', null::text[], '{"en":"`ControlValueAccessor` is the bridge between the forms API and any UI: the `NG_VALUE_ACCESSOR` provider (with `useExisting` and `forwardRef`, because the class is referenced inside its own decorator) tells `formControlName` to talk to this component instead of a native input. Data flows both ways through four methods: `writeValue` (model → view), the callbacks saved from `registerOnChange` and `registerOnTouched` (view → model), and `setDisabledState`. Because the component implements the contract, it works with reactive forms, template-driven `ngModel`, validators and `touched`/`dirty` state for free. The same pattern still applies in current Angular, and the newer signal-based `model()` inputs cover simpler two-way bindings that don''t need the forms API.","uk":"`ControlValueAccessor` є мостом між API форм і будь-яким інтерфейсом: провайдер `NG_VALUE_ACCESSOR` (з `useExisting` і `forwardRef`, бо клас згадується у власному декораторі) каже `formControlName` спілкуватися з цим компонентом замість нативного поля введення. Дані йдуть в обидва боки через чотири методи: `writeValue` (модель → подання), колбеки, збережені з `registerOnChange` і `registerOnTouched` (подання → модель), і `setDisabledState`. Оскільки компонент реалізує цей контракт, він безкоштовно працює з реактивними формами, `ngModel` з шаблонних форм, валідаторами й станом `touched`/`dirty`. Той самий шаблон досі діє в сучасному Angular, а новіші вхідні дані-сигнали `model()` покривають простіші двосторонні прив''язки, яким не потрібен API форм."}'::jsonb, '{"/src/app/rating.component.ts":"import { Component, forwardRef, HostListener } from \"@angular/core\";\nimport { ControlValueAccessor, NG_VALUE_ACCESSOR } from \"@angular/forms\";\n\n@Component({\n  selector: \"app-rating\",\n  template: `\n    <div role=\"group\" aria-label=\"Rating\">\n      <button\n        type=\"button\"\n        *ngFor=\"let star of stars\"\n        [attr.aria-label]=\"''Rate '' + star\"\n        [attr.aria-pressed]=\"star <= value\"\n        [disabled]=\"disabled\"\n        (click)=\"select(star)\"\n      >{{ star <= value ? \"★\" : \"☆\" }}</button>\n    </div>\n  `,\n  // Registers this component as the value accessor for formControlName / formControl / ngModel on it.\n  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => RatingComponent), multi: true }],\n})\nexport class RatingComponent implements ControlValueAccessor {\n  stars = [1, 2, 3, 4, 5];\n  value = 0;\n  disabled = false;\n\n  private onChange: (value: number) => void = () => {};\n  private onTouched: () => void = () => {};\n\n  /** Model → view: the form sets a value. */\n  writeValue(value: number | null) {\n    this.value = value || 0;\n  }\n  /** View → model: call fn whenever the user changes the value. */\n  registerOnChange(fn: (value: number) => void) {\n    this.onChange = fn;\n  }\n  registerOnTouched(fn: () => void) {\n    this.onTouched = fn;\n  }\n  setDisabledState(disabled: boolean) {\n    this.disabled = disabled;\n  }\n\n  select(star: number) {\n    if (this.disabled) return;\n    this.value = star;\n    this.onChange(star);\n    this.onTouched();\n  }\n\n  @HostListener(\"keydown\", [\"$event\"])\n  onKeydown(event: KeyboardEvent) {\n    if (this.disabled) return;\n    if (event.key === \"ArrowRight\") this.select(Math.min(5, this.value + 1));\n    if (event.key === \"ArrowLeft\") this.select(Math.max(1, this.value - 1));\n  }\n}\n"}'::jsonb),
  ('ng-rxjs-typeahead', null::text[], '{"en":"Each requirement maps to an operator: `debounceTime` waits for a pause, `map(trim)` plus `distinctUntilChanged` drops repeats, and `switchMap` is the key one. When a new term arrives it **unsubscribes** from the previous inner observable, so a slow, stale response is discarded instead of overwriting newer results (`mergeMap` would let them race, and `concatMap` would queue them). Short terms map to `of([])` inside the same `switchMap`, which also cancels any request in flight. Collecting subscriptions in a `Subscription` and unsubscribing in `ngOnDestroy` prevents leaks; with the `async` pipe or, in modern Angular, `toSignal(...)` and `takeUntilDestroyed()`, that cleanup happens automatically.","uk":"Кожна вимога відповідає оператору: `debounceTime` чекає паузи, `map(trim)` разом із `distinctUntilChanged` відкидає повтори, а ключовим є `switchMap`. Коли надходить новий термін, він **відписується** від попереднього внутрішнього observable, тож повільна застаріла відповідь відкидається, а не перезаписує новіші результати (`mergeMap` дав би їм змагатися, а `concatMap` поставив би їх у чергу). Короткі терміни перетворюються на `of([])` у тому самому `switchMap`, що також скасовує будь-який поточний запит. Збирання підписок в `Subscription` і відписка в `ngOnDestroy` запобігають витокам; з pipe `async` або, в сучасному Angular, з `toSignal(...)` і `takeUntilDestroyed()` це очищення відбувається автоматично."}'::jsonb, '{"/src/app/search.component.ts":"import { Component, OnDestroy, OnInit } from \"@angular/core\";\nimport { of, Subject, Subscription } from \"rxjs\";\nimport { debounceTime, distinctUntilChanged, map, switchMap, tap } from \"rxjs/operators\";\nimport { SearchService } from \"./search.service\";\n\nconst HINT = \"Type at least 2 characters\";\nconst SEARCHING = \"Searching…\";\n\n@Component({\n  selector: \"app-search\",\n  template: `\n    <label for=\"search\">Search libraries</label>\n    <input id=\"search\" type=\"search\" autocomplete=\"off\" (input)=\"terms.next($any($event.target).value)\" />\n    <p data-testid=\"status\">{{ status }}</p>\n    <ul>\n      <li *ngFor=\"let name of results\">{{ name }}</li>\n    </ul>\n  `,\n})\nexport class SearchComponent implements OnInit, OnDestroy {\n  readonly terms = new Subject<string>();\n  results: string[] = [];\n  status = HINT;\n  private subscription = new Subscription();\n\n  constructor(private search: SearchService) {}\n\n  ngOnInit() {\n    this.subscription.add(\n      this.terms\n        .pipe(\n          debounceTime(250), // wait until typing pauses\n          map((term) => term.trim()),\n          distinctUntilChanged(), // \"react \" is still \"react\": don''t search again\n          tap((term) => (this.status = term.length < 2 ? HINT : SEARCHING)),\n          // switchMap unsubscribes from the previous request, so a slow stale answer can''t overwrite a newer one\n          switchMap((term) => (term.length < 2 ? of([]) : this.search.search(term))),\n        )\n        .subscribe((results) => {\n          this.results = results;\n          if (this.status === SEARCHING) this.status = results.length ? results.length + \" results\" : \"No results\";\n        }),\n    );\n  }\n\n  ngOnDestroy() {\n    this.subscription.unsubscribe();\n  }\n}\n"}'::jsonb),
  ('ng-onpush-immutable', null::text[], '{"en":"An `OnPush` component is checked only when one of its `@Input` **references** changes, an event fires inside it, an `async` pipe emits, or it''s explicitly marked for check. Pushing into the same array or flipping `done` on the same object changes nothing Angular compares, so the list stays stale (toggling from inside the child still works, because the child''s own event marks it dirty). Immutable updates (`[...todos, newTodo]`, `map` returning `{ ...todo, done }` only for changed items) give the child new references, and unchanged objects keep their identity. `trackBy: trackById` then tells `ngFor` that a replaced object is the same row, so it updates the existing `<li>` instead of destroying and recreating it. In modern Angular, signals give the same precision (`todos = signal<Todo[]>([])` with `update(...)`), and `@for (todo of todos(); track todo.id)` makes tracking mandatory.","uk":"Компонент `OnPush` перевіряється, лише коли змінюється **посилання** в одному з його `@Input`, усередині нього спрацьовує подія, pipe `async` видає значення, або його явно позначено для перевірки. Додавання в той самий масив чи перемикання `done` в тому самому об''єкті не змінює нічого, що порівнює Angular, тож список лишається застарілим (перемикання зсередини дочірнього компонента все одно працює, бо власна подія позначає його брудним). Незмінні оновлення (`[...todos, newTodo]`, `map`, що повертає `{ ...todo, done }` лише для змінених елементів) дають дочірньому компоненту нові посилання, а незмінені об''єкти зберігають свою ідентичність. `trackBy: trackById` потім каже `ngFor`, що замінений об''єкт є тим самим рядком, тож він оновлює наявний `<li>`, а не знищує й не створює його заново. У сучасному Angular таку саму точність дають сигнали (`todos = signal<Todo[]>([])` з `update(...)`), а `@for (todo of todos(); track todo.id)` робить відстеження обов''язковим."}'::jsonb, '{"/src/app/app.component.ts":"import { Component } from \"@angular/core\";\nimport { Todo } from \"./todo\";\n\n@Component({\n  selector: \"app-root\",\n  template: `\n    <label for=\"title\">New todo</label>\n    <input id=\"title\" #title (keydown.enter)=\"add(title)\" />\n    <button type=\"button\" (click)=\"add(title)\">Add</button>\n    <button type=\"button\" (click)=\"completeAll()\">Complete all</button>\n    <app-todo-list [todos]=\"todos\" (toggle)=\"toggle($event)\"></app-todo-list>\n  `,\n})\nexport class AppComponent {\n  todos: Todo[] = [\n    { id: 1, title: \"Write tests\", done: false },\n    { id: 2, title: \"Ship it\", done: false },\n  ];\n  private nextId = 3;\n\n  // Every change produces a new array (and new objects only for the todos that changed),\n  // so the OnPush list sees a new @Input reference and re-renders.\n  add(input: HTMLInputElement) {\n    const title = input.value.trim();\n    if (!title) return;\n    this.todos = [...this.todos, { id: this.nextId++, title, done: false }];\n    input.value = \"\";\n  }\n\n  toggle(id: number) {\n    this.todos = this.todos.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo));\n  }\n\n  completeAll() {\n    this.todos = this.todos.map((todo) => (todo.done ? todo : { ...todo, done: true }));\n  }\n}\n","/src/app/todo-list.component.ts":"import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from \"@angular/core\";\nimport { Todo } from \"./todo\";\n\n@Component({\n  selector: \"app-todo-list\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <p data-testid=\"remaining\">{{ remaining }} left</p>\n    <ul>\n      <li *ngFor=\"let todo of todos; trackBy: trackById\" [class.done]=\"todo.done\">\n        <label><input type=\"checkbox\" [checked]=\"todo.done\" (change)=\"toggle.emit(todo.id)\" /> {{ todo.title }}</label>\n      </li>\n    </ul>\n  `,\n})\nexport class TodoListComponent {\n  @Input() todos: Todo[] = [];\n  @Output() toggle = new EventEmitter<number>();\n\n  /** Rows are matched by id, so replacing a todo object updates its row instead of re-creating it. */\n  trackById(index: number, todo: Todo) {\n    return todo.id;\n  }\n\n  get remaining() {\n    return this.todos.filter((todo) => !todo.done).length;\n  }\n}\n"}'::jsonb),
  ('ng-tabs-content-children', null::text[], '{"en":"`<ng-content>` projects the `app-tab` elements the parent template placed inside `app-tabs`, and `@ContentChildren(TabComponent)` gives a live `QueryList` of them, which updates when an `*ngIf` adds or removes a tab, so `*ngFor` over it renders the buttons. Instead of storing an `active` flag in every child (which means pushing state down during change detection and risking `ExpressionChangedAfterItHasBeenChecked` errors), each `TabComponent` injects its parent `TabsComponent` through the element injector and **derives** `active` from the parent''s `activeTab` getter. That getter also implements the fallback: if the selected tab is gone, the first tab wins. Roving `tabindex` and arrow keys follow the WAI-ARIA tabs pattern. In modern Angular this would be `contentChildren(TabComponent)` (a signal) and `computed()` for the active tab, with the same design.","uk":"`<ng-content>` проєктує елементи `app-tab`, які батьківський шаблон розмістив усередині `app-tabs`, а `@ContentChildren(TabComponent)` дає живий `QueryList` цих елементів, що оновлюється, коли `*ngIf` додає чи прибирає вкладку, тож `*ngFor` по ньому рендерить кнопки. Замість зберігати прапорець `active` у кожному дочірньому компоненті (а це означає записувати стан униз під час виявлення змін і ризикувати помилками `ExpressionChangedAfterItHasBeenChecked`), кожен `TabComponent` впроваджує свого батька `TabsComponent` через інжектор елемента й **обчислює** `active` із гетера `activeTab` батька. Цей гетер також реалізує запасний варіант: якщо вибраної вкладки немає, перемагає перша. Рухомий `tabindex` і клавіші-стрілки відповідають шаблону вкладок WAI-ARIA. У сучасному Angular це був би `contentChildren(TabComponent)` (сигнал) і `computed()` для активної вкладки, з тим самим дизайном."}'::jsonb, '{"/src/app/tabs.component.ts":"import { Component, ContentChildren, EventEmitter, forwardRef, Input, Output, QueryList } from \"@angular/core\";\n\n@Component({\n  selector: \"app-tabs\",\n  template: `\n    <div role=\"tablist\" (keydown)=\"onKeydown($event)\">\n      <button\n        type=\"button\"\n        role=\"tab\"\n        *ngFor=\"let tab of tabs\"\n        [attr.aria-selected]=\"tab === activeTab\"\n        [attr.tabindex]=\"tab === activeTab ? 0 : -1\"\n        (click)=\"select(tab)\"\n      >{{ tab.title }}</button>\n    </div>\n    <ng-content></ng-content>\n  `,\n})\nexport class TabsComponent {\n  // forwardRef: TabComponent is declared below this class.\n  @ContentChildren(forwardRef(() => TabComponent)) tabs!: QueryList<TabComponent>;\n  @Output() selectedChange = new EventEmitter<string>();\n\n  private selected: TabComponent | null = null;\n\n  /** Derived, not stored: if the selected tab disappears, the first tab becomes active. */\n  get activeTab(): TabComponent | null {\n    const list = this.tabs ? this.tabs.toArray() : [];\n    if (this.selected && list.indexOf(this.selected) >= 0) return this.selected;\n    return list.length ? list[0] : null;\n  }\n\n  select(tab: TabComponent) {\n    if (tab === this.activeTab) return;\n    this.selected = tab;\n    this.selectedChange.emit(tab.title);\n  }\n\n  onKeydown(event: KeyboardEvent) {\n    if (event.key !== \"ArrowRight\" && event.key !== \"ArrowLeft\") return;\n    const list = this.tabs.toArray();\n    const active = this.activeTab;\n    if (!active) return;\n    const step = event.key === \"ArrowRight\" ? 1 : -1;\n    this.select(list[(list.indexOf(active) + step + list.length) % list.length]);\n  }\n}\n\n@Component({\n  selector: \"app-tab\",\n  template: `<div role=\"tabpanel\" *ngIf=\"active\" [attr.aria-label]=\"title\"><ng-content></ng-content></div>`,\n})\nexport class TabComponent {\n  @Input() title = \"\";\n\n  // A tab asks its parent (found through the element injector) whether it''s the active one.\n  constructor(private tabs: TabsComponent) {}\n\n  get active() {\n    return this.tabs.activeTab === this;\n  }\n}\n"}'::jsonb),
  ('ng-binding-syntax', array['b']::text[], '{"en":"Parentheses bind to events (view → class). Square brackets bind properties (class → view), interpolation renders text, and `*` marks structural directives.","uk":"Круглі дужки прив''язують події (вигляд → клас). Квадратні дужки прив''язують властивості (клас → вигляд), інтерполяція виводить текст, а `*` позначає структурні директиви."}'::jsonb, null::jsonb),
  ('ng-oninit-vs-constructor', array['a']::text[], '{"en":"The constructor is for DI and simple field setup. Angular sets inputs after construction and then calls `ngOnChanges` and `ngOnInit`, so logic that depends on inputs (like loading by `id`) belongs in `ngOnInit`.","uk":"Конструктор призначений для DI та простого налаштування полів. Angular встановлює вхідні дані після створення, а потім викликає `ngOnChanges` і `ngOnInit`, тож логіка, що залежить від вхідних даних (як-от завантаження за `id`), належить до `ngOnInit`."}'::jsonb, null::jsonb),
  ('ng-onpush-mutation', array['a']::text[], '{"en":"OnPush checks a component when an input gets a new reference (or for its own events, async pipe emissions and `markForCheck`). Mutating the array keeps the reference, so the child is skipped. Use `this.items = [...this.items, item]`.","uk":"OnPush перевіряє компонент, коли вхідні дані отримують нове посилання (а також для власних подій, значень async pipe і `markForCheck`). Мутація масиву зберігає посилання, тож дитину пропускають. Використовуйте `this.items = [...this.items, item]`."}'::jsonb, null::jsonb),
  ('ng-provider-scope', array['b']::text[], '{"en":"Component-level providers create a new injector per component instance, so each instance (and its children) gets its own service. `providedIn: \"root\"` creates one app-wide singleton instead.","uk":"Провайдери на рівні компонента створюють новий інжектор для кожного екземпляра, тож кожен екземпляр (і його нащадки) отримує власний сервіс. `providedIn: \"root\"` натомість створює один синглтон на весь застосунок."}'::jsonb, null::jsonb),
  ('ng-async-pipe', array['a', 'b']::text[], '{"en":"The async pipe subscribes, unsubscribes on destroy and calls `markForCheck`, so it works well with OnPush. Each `| async` is a separate subscription, though: a cold HTTP observable used twice fires two requests unless you share it (e.g. `shareReplay`). Errors still need handling.","uk":"async pipe підписується, відписується при знищенні й викликає `markForCheck`, тож добре працює з OnPush. Але кожен `| async` є окремою підпискою: холодний HTTP-observable, використаний двічі, зробить два запити, якщо його не поділити (наприклад, `shareReplay`). Помилки все одно треба обробляти."}'::jsonb, null::jsonb),
  ('ng-quantity-stepper', null::text[], '{"en":"The stepper is a controlled component: it only emits the requested value, and the parent writes it back through `[value]`. `[disabled]` bindings reflect the limits, and clamping in `change()` guards against out-of-range emits.","uk":"Лічильник є керованим компонентом: він лише надсилає бажане значення, а батько повертає його через `[value]`. Прив''язки `[disabled]` відображають межі, а обмеження в `change()` захищає від значень поза діапазоном."}'::jsonb, '{"/src/app/stepper.component.ts":"import { Component, EventEmitter, Input, Output } from \"@angular/core\";\n\n@Component({\n  selector: \"app-stepper\",\n  template: `\n    <button type=\"button\" aria-label=\"Decrease\" (click)=\"change(-1)\" [disabled]=\"value <= min\">−</button>\n    <span data-testid=\"value\">{{ value }}</span>\n    <button type=\"button\" aria-label=\"Increase\" (click)=\"change(1)\" [disabled]=\"value >= max\">+</button>\n  `,\n})\nexport class StepperComponent {\n  @Input() value = 0;\n  @Input() min = 0;\n  @Input() max = 10;\n  @Output() valueChange = new EventEmitter<number>();\n\n  change(delta: number) {\n    const next = Math.min(this.max, Math.max(this.min, this.value + delta));\n    if (next !== this.value) this.valueChange.emit(next);\n  }\n}\n"}'::jsonb),
  ('anim-fixed-step-reason', array['a']::text[], '{"en":"If position changes by `speed * frameTime`, a slow device moves things in bigger jumps and can tunnel through walls, and two machines disagree about what happened. Advancing in fixed steps and rendering the in-between state (the `alpha` factor) keeps simulation identical everywhere while still looking smooth.","uk":"Якщо позиція змінюється на `швидкість * час_кадру`, на повільному пристрої об''єкти стрибають більшими кроками і можуть пройти крізь стіну, а дві машини по-різному описують одну й ту саму подію. Просування фіксованими кроками і малювання проміжного стану (коефіцієнт `alpha`) тримають симуляцію однаковою всюди і при цьому плавною."}'::jsonb, null::jsonb),
  ('anim-fixed-timestep', null::text[], '{"en":"The accumulator is the whole trick: real time goes in, whole steps come out, and the remainder waits for the next frame. Because the simulation only ever advances in `stepMs` increments, the result depends on how much time has passed, not on how it was split into frames. The cap guards against the \"spiral of death\", where a slow frame causes many steps, which makes the next frame even slower. Rendering with `alpha` interpolates between the last two simulation states, which hides the difference between step size and display refresh.","uk":"Акумулятор — це весь трюк: реальний час заходить, повні кроки виходять, а залишок чекає наступного кадру. Оскільки симуляція просувається лише кроками по `stepMs`, результат залежить від того, скільки часу минуло, а не від того, як він розбитий на кадри. Обмеження захищає від «спіралі смерті», коли повільний кадр породжує багато кроків, і це робить наступний кадр ще повільнішим. Рендер з `alpha` інтерполює між двома останніми станами симуляції, що приховує різницю між розміром кроку і частотою оновлення екрана."}'::jsonb, '{"/src/loop.ts":"export type FixedLoopOptions = {\n  stepMs: number;\n  update: (stepMs: number) => void;\n  maxFrameMs?: number;\n};\n\nexport function createFixedLoop({ stepMs, update, maxFrameMs = 250 }: FixedLoopOptions) {\n  let accumulator = 0;\n  return {\n    advance(frameMs: number): number {\n      accumulator += Math.min(Math.max(frameMs, 0), maxFrameMs);\n      let steps = 0;\n      while (accumulator >= stepMs) {\n        update(stepMs);\n        accumulator -= stepMs;\n        steps++;\n      }\n      return steps;\n    },\n    alpha(): number {\n      return accumulator / stepMs;\n    },\n  };\n}\n"}'::jsonb),
  ('arr-fill-shared', array['b']::text[], '{"en":"`fill([])` evaluates `[]` once and puts the same array reference in every slot, so pushing into one row changes all of them. Create a new array per slot with `Array.from({ length: 3 }, () => [])`.","uk":"`fill([])` обчислює `[]` один раз і кладе те саме посилання в кожну комірку, тож додавання в один рядок змінює всі. Створюйте новий масив для кожної комірки: `Array.from({ length: 3 }, () => [])`."}'::jsonb, null::jsonb),
  ('arr-holes-map', array['c']::text[], '{"en":"`Array(3)` creates a sparse array with length 3 but no elements. `map`, `forEach` and `filter` skip holes, so the callback never runs and the result is still sparse. Use `Array.from({ length: 3 }, (_, i) => i)` or `[...Array(3).keys()]`.","uk":"`Array(3)` створює розріджений масив довжиною 3 без елементів. `map`, `forEach` і `filter` пропускають «дірки», тож колбек не викликається, а результат лишається розрідженим. Використовуйте `Array.from({ length: 3 }, (_, i) => i)` або `[...Array(3).keys()]`."}'::jsonb, null::jsonb),
  ('arr-splice-in-foreach', array['b']::text[], '{"en":"`forEach` walks indexes 0, 1, 2… over the live array. Removing 2 at index 0 shifts 4 into index 0, but the next visit is index 1 (now 6), so 4 is never checked. Removing 6 shifts 7 to index 1, and the loop ends because the length is now 2. Use `nums = nums.filter((n) => n % 2 !== 0)`, or loop backwards if you must mutate.","uk":"`forEach` проходить індекси 0, 1, 2… живого масиву. Видалення 2 з індексу 0 зсуває 4 на індекс 0, але наступний відвіданий індекс — 1 (тепер це 6), тож 4 не перевіряється. Видалення 6 зсуває 7 на індекс 1, і цикл завершується, бо довжина тепер 2. Використовуйте `nums = nums.filter((n) => n % 2 !== 0)` або, якщо мусите змінювати масив, ідіть з кінця."}'::jsonb, null::jsonb),
  ('str-run-length', null::text[], '{"en":"Encoding uses two pointers: `j` scans to the end of the current run, and the run length is `j - i`. Decoding reads a letter followed by an optional number. A regex with `matchAll` handles multi-digit counts cleanly, and `repeat` expands each run. Building a string with `+=` is fine here; for very large inputs, push parts into an array and `join` once.","uk":"Кодування використовує два вказівники: `j` доходить до кінця поточної серії, а довжина серії — `j - i`. Декодування читає літеру й необов''язкове число після неї. Регулярний вираз із `matchAll` охайно обробляє багатозначні лічильники, а `repeat` розгортає кожну серію. Побудова рядка через `+=` тут підходить; для дуже великих даних збирайте частини в масив і один раз робіть `join`."}'::jsonb, '{"/src/rle.ts":"export function encode(text: string): string {\n  let out = \"\";\n  for (let i = 0; i < text.length; ) {\n    let j = i;\n    while (j < text.length && text[j] === text[i]) j++;\n    const run = j - i;\n    out += text[i] + (run > 1 ? String(run) : \"\");\n    i = j;\n  }\n  return out;\n}\n\nexport function decode(encoded: string): string {\n  let out = \"\";\n  for (const [, letter, count] of encoded.matchAll(/([a-zA-Z])(\\d*)/g)) {\n    out += letter.repeat(count ? Number(count) : 1);\n  }\n  return out;\n}\n"}'::jsonb),
  ('arr-default-sort', array['b']::text[], '{"en":"Without a comparator, elements are converted to strings and compared by UTF-16 code units, so \"10\" < \"100\" < \"5\". Use `(a, b) => a - b` for numbers.","uk":"Без компаратора елементи перетворюються на рядки й порівнюються за кодами UTF-16, тому \"10\" < \"100\" < \"5\". Для чисел використовуйте `(a, b) => a - b`."}'::jsonb, null::jsonb),
  ('arr-mutating-methods', array['a', 'c', 'e']::text[], '{"en":"`sort`, `splice` and `reverse` change the array in place. `toSorted` and `slice` return new arrays and leave the original untouched, which is what you want for React or Redux state.","uk":"`sort`, `splice` і `reverse` змінюють масив на місці. `toSorted` і `slice` повертають нові масиви й не чіпають вихідний, що й потрібно для стану React чи Redux."}'::jsonb, null::jsonb),
  ('arr-reduce-initial', array['c']::text[], '{"en":"Without an initial value, `reduce` uses the first element as the accumulator, which doesn''t exist for an empty array, so it throws. Always pass one: `reduce((s, x) => s + x.price, 0)`.","uk":"Без початкового значення `reduce` бере перший елемент як акумулятор, а в порожньому масиві його немає, тож метод кидає помилку. Завжди передавайте значення: `reduce((s, x) => s + x.price, 0)`."}'::jsonb, null::jsonb),
  ('arr-dedupe-complexity', array['a']::text[], '{"en":"`indexOf` inside `filter` is O(n²). A Set keeps insertion order and gives O(1) membership, so `[...new Set(items)]` is O(n). Sorting first is O(n log n), loses the original order and mutates `items`.","uk":"`indexOf` усередині `filter` дає O(n²). Set зберігає порядок вставки й перевіряє наявність за O(1), тож `[...new Set(items)]` працює за O(n). Попереднє сортування дає O(n log n), втрачає початковий порядок і змінює `items`."}'::jsonb, null::jsonb),
  ('str-emoji-reverse', array['a']::text[], '{"en":"Characters outside the Basic Multilingual Plane take two UTF-16 code units. `split(\"\")` separates them, and reversing swaps the halves into invalid sequences. `[...s]` (or `Array.from(s)`) iterates by code points. Grapheme clusters such as flags or skin tones need `Intl.Segmenter`.","uk":"Символи поза базовою багатомовною площиною займають дві кодові одиниці UTF-16. `split(\"\")` розділяє їх, а розворот міняє половинки місцями й дає некоректні послідовності. `[...s]` (або `Array.from(s)`) ітерує за кодовими точками. Для графемних кластерів, як-от прапорів чи відтінків шкіри, потрібен `Intl.Segmenter`."}'::jsonb, null::jsonb),
  ('str-group-anagrams', null::text[], '{"en":"Map each word to a canonical signature: its lower-cased letters, sorted. A Map from signature to group preserves insertion order, so groups come out in first-appearance order. Sorting each word costs O(k log k), so the total is O(n·k log k). A 26-letter count vector would make it O(n·k).","uk":"Зіставте кожне слово з канонічним підписом: його літери в нижньому регістрі, відсортовані. Map від підпису до групи зберігає порядок вставки, тож групи йдуть у порядку першої появи. Сортування кожного слова коштує O(k log k), разом O(n·k log k). Вектор лічильників із 26 літер дав би O(n·k)."}'::jsonb, '{"/src/anagrams.ts":"function signature(word: string) {\n  return [...word.toLowerCase().replace(/[^\\p{L}]/gu, \"\")].sort().join(\"\");\n}\n\nexport function groupAnagrams(words: string[]): string[][] {\n  const groups = new Map<string, string[]>();\n  for (const word of words) {\n    const key = signature(word);\n    const group = groups.get(key);\n    if (group) group.push(word);\n    else groups.set(key, [word]);\n  }\n  return [...groups.values()];\n}\n"}'::jsonb),
  ('cxl-race-doesnt-cancel', array['a']::text[], '{"en":"`Promise.race` settles with the first input to settle, but it has no way to stop the others: promises represent results, not operations. The slow work keeps running and finishes anyway (a real request would still use bandwidth and might still change data). To actually stop it, pass an `AbortSignal` to the operation and abort it on timeout.","uk":"`Promise.race` завершується з першим вхідним промісом, що завершився, але не може зупинити інші: проміси представляють результати, а не операції. Повільна робота продовжується й усе одно завершується (справжній запит і далі використовував би трафік і міг би змінити дані). Щоб справді її зупинити, передайте операції `AbortSignal` і скасуйте його за тайм-аутом."}'::jsonb, null::jsonb),
  ('cxl-abort-once', array['a']::text[], '{"en":"`abort()` without an argument stores a `DOMException` named `AbortError` as `signal.reason`. A signal aborts only once: later `abort` calls don''t change the reason and don''t fire `abort` again. So it''s safe to call `abort()` in several cleanup paths.","uk":"`abort()` без аргументу зберігає як `signal.reason` `DOMException` на ім''я `AbortError`. Сигнал скасовується лише один раз: пізніші виклики `abort` не змінюють причину й не запускають `abort` повторно. Тож `abort()` безпечно викликати в кількох шляхах очищення."}'::jsonb, null::jsonb),
  ('cxl-throw-if-aborted', array['a']::text[], '{"en":"`signal.throwIfAborted()` throws `signal.reason` itself if the signal is aborted, so a custom reason (here an `Error` with message `stop`) comes through unchanged. Call it at the start of an abortable function and between steps of long work, to bail out early without extra checks.","uk":"`signal.throwIfAborted()` кидає саму `signal.reason`, якщо сигнал скасовано, тож власна причина (тут `Error` з повідомленням `stop`) проходить без змін. Викликайте його на початку скасовуваної функції й між кроками тривалої роботи, щоб вийти раніше без додаткових перевірок."}'::jsonb, null::jsonb),
  ('cxl-listener-signal', array['a']::text[], '{"en":"`addEventListener` accepts `{ signal }`: when the signal aborts, the listener is removed. One controller can remove many listeners at once (for example all of a component''s handlers on unmount) without keeping references to each handler for `removeEventListener`.","uk":"`addEventListener` приймає `{ signal }`: коли сигнал скасовується, слухача видаляють. Один контролер може видалити багато слухачів одразу (наприклад, усі обробники компонента під час демонтування), не зберігаючи посилань на кожен обробник для `removeEventListener`."}'::jsonb, null::jsonb),
  ('cxl-timeout-signal', array['a']::text[], '{"en":"`AbortSignal.timeout(ms)` aborts by itself after `ms` with a `DOMException` named `TimeoutError` (not `AbortError`), so handlers can tell \"too slow\" from \"cancelled by the user\". `fetch(url, { signal: AbortSignal.timeout(5000) })` is the shortest way to put a deadline on a request.","uk":"`AbortSignal.timeout(ms)` скасовується сам через `ms` з `DOMException` на ім''я `TimeoutError` (а не `AbortError`), тож обробники можуть відрізнити «занадто повільно» від «скасовано користувачем». `fetch(url, { signal: AbortSignal.timeout(5000) })` є найкоротшим способом задати запиту крайній термін."}'::jsonb, null::jsonb),
  ('cxl-any-signal', array['a']::text[], '{"en":"`AbortSignal.any([...])` returns a signal that aborts as soon as **any** input does, with that input''s reason. That''s how you combine \"the user closed the dialog\" with \"give up after 1 second\" for one operation, and the reason tells you which one happened.","uk":"`AbortSignal.any([...])` повертає сигнал, що скасовується, щойно скасовується **будь-який** вхідний сигнал, з причиною цього сигналу. Так поєднують «користувач закрив діалог» і «здатися через 1 секунду» для однієї операції, а причина каже, що саме сталося."}'::jsonb, null::jsonb),
  ('cxl-stale-response', array['a']::text[], '{"en":"Both requests run concurrently, and whichever finishes **last** writes `shown`. The request for \"re\" is slower, so the stale result overwrites the correct one. Fix it by aborting the previous request when a new one starts (latest wins), or by ignoring results that aren''t from the most recent request.","uk":"Обидва запити виконуються одночасно, і `shown` записує той, що завершився **останнім**. Запит для «re» повільніший, тож застарілий результат перезаписує правильний. Виправлення: скасовуйте попередній запит, коли починається новий (перемагає останній), або ігноруйте результати, що не належать найновішому запиту."}'::jsonb, null::jsonb),
  ('cxl-cancel-vs-failure', array['a']::text[], '{"en":"An aborted `fetch` rejects with the signal''s reason, which by default is a `DOMException` named `AbortError` (or `TimeoutError` for `AbortSignal.timeout`). Cancellation is intentional, so don''t show an error message or send it to error monitoring; treat it as a quiet exit. Network failures are `TypeError`s, and HTTP error statuses don''t reject at all.","uk":"Скасований `fetch` відхиляється з причиною сигналу, якою за замовчуванням є `DOMException` на ім''я `AbortError` (чи `TimeoutError` для `AbortSignal.timeout`). Скасування навмисне, тож не показуйте повідомлення про помилку й не надсилайте його в моніторинг помилок; вважайте це тихим виходом. Збої мережі є `TypeError`, а HTTP-статуси помилок узагалі не відхиляють проміс."}'::jsonb, null::jsonb),
  ('cxl-strategy-payment', array['a']::text[], '{"en":"The second click is a duplicate, not a new intent, so it should be ignored while the first request is in flight (`exhaustMap` in RxJS); disable the button too. Latest-wins is dangerous here: aborting the client request doesn''t guarantee the server didn''t charge. Queue and parallel would charge twice. Also send an idempotency key so the server can deduplicate retries.","uk":"Друге натискання є дублікатом, а не новим наміром, тож його треба ігнорувати, поки перший запит триває (`exhaustMap` у RxJS); також вимкніть кнопку. «Перемагає останній» тут небезпечний: скасування запиту на клієнті не гарантує, що сервер не списав кошти. Черга й паралельне виконання спишуть гроші двічі. Також надсилайте ключ ідемпотентності, щоб сервер міг прибрати дублікати повторів."}'::jsonb, null::jsonb),
  ('cxl-strategy-autosave', array['a']::text[], '{"en":"Parallel requests can reach the server out of order, so an older text could overwrite a newer one. Exhaust would silently drop the latest edits. Aborting on the client doesn''t stop a request the server is already processing, so ordering still isn''t guaranteed. A queue (`concatMap`) applies saves in order; a refinement is to coalesce queued saves so only the newest pending text is sent.","uk":"Паралельні запити можуть дійти до сервера не по порядку, тож старіший текст може перезаписати новіший. Exhaust мовчки відкине останні зміни. Скасування на клієнті не зупиняє запит, який сервер уже обробляє, тож порядок усе одно не гарантовано. Черга (`concatMap`) застосовує збереження по порядку; удосконалення: об''єднувати збереження в черзі, щоб надсилався лише найновіший текст, що очікує."}'::jsonb, null::jsonb),
  ('cxl-react-effect', array['a']::text[], '{"en":"React runs the cleanup before the next effect (when `query` changes) and on unmount. Aborting there cancels the outdated request, so its response can''t call `setUsers` after a newer one; a boolean `ignore` flag set in the cleanup works too, but doesn''t save bandwidth. Data-fetching libraries like TanStack Query do this for you via the `signal` they pass to query functions.","uk":"React виконує функцію очищення перед наступним ефектом (коли змінюється `query`) і під час демонтування. Скасування там зупиняє застарілий запит, тож його відповідь не може викликати `setUsers` після новішої; булевий прапорець `ignore`, що встановлюється в очищенні, теж працює, але не економить трафік. Бібліотеки отримання даних на кшталт TanStack Query роблять це за вас через `signal`, який вони передають функціям запитів."}'::jsonb, null::jsonb),
  ('cxl-channel-backpressure', array['a']::text[], '{"en":"A bounded channel applies **backpressure**: when it''s full, `send` returns a promise that settles only after the consumer makes room, so a fast producer can''t fill memory. (How many sends finish immediately depends on whether a consumer is already waiting.) Unbounded queues hide this problem until memory runs out. Streams (`ReadableStream`, Node streams) use the same idea with a high-water mark.","uk":"Обмежений канал застосовує **зворотний тиск** (backpressure): коли він заповнений, `send` повертає проміс, що завершується лише після того, як споживач звільнить місце, тож швидкий виробник не може заповнити пам''ять. (Скільки надсилань завершиться одразу, залежить від того, чи вже чекає споживач.) Необмежені черги приховують цю проблему, доки не скінчиться пам''ять. Потоки (`ReadableStream`, потоки Node) використовують ту саму ідею з high-water mark."}'::jsonb, null::jsonb),
  ('cxl-abortable', null::text[], '{"en":"Each function follows the same pattern: check `aborted` up front, listen for `abort` with `{ once: true }`, and clean up on both paths (clear the timer when aborting, remove the listener when finishing), so nothing keeps running or leaks. `anySignal` forwards the first reason and detaches from the other signals, which matters when one of them is long-lived (like a page-level controller). `withTimeout` passes a combined signal into the task so it can stop its own work (fetches, nested sleeps), and also rejects on abort itself, so a task that ignores the signal can''t hold the caller past the deadline.","uk":"Кожна функція дотримується того самого шаблону: перевірити `aborted` на початку, слухати `abort` з `{ once: true }` і прибирати на обох шляхах (очистити таймер при скасуванні, видалити слухача при завершенні), тож ніщо не продовжує працювати й не витікає. `anySignal` передає першу причину й від''єднується від інших сигналів, і це важливо, коли один із них довгоживучий (як контролер рівня сторінки). `withTimeout` передає поєднаний сигнал у задачу, щоб вона могла зупинити власну роботу (fetch, вкладені sleep), а також сама відхиляється при скасуванні, тож задача, що ігнорує сигнал, не може затримати того, хто викликає, після крайнього терміну."}'::jsonb, '{"/src/abortable.ts":"export function sleep(ms: number, { signal }: { signal?: AbortSignal } = {}): Promise<void> {\n  return new Promise((resolve, reject) => {\n    if (signal?.aborted) {\n      reject(signal.reason);\n      return;\n    }\n    const onAbort = () => {\n      clearTimeout(id);\n      reject(signal!.reason);\n    };\n    const id = setTimeout(() => {\n      signal?.removeEventListener(\"abort\", onAbort);\n      resolve();\n    }, ms);\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n\nexport function anySignal(signals: AbortSignal[]): AbortSignal {\n  const controller = new AbortController();\n  const cleanups: Array<() => void> = [];\n  const abort = (reason: unknown) => {\n    controller.abort(reason);\n    for (const cleanup of cleanups) cleanup(); // don''t keep listeners on long-lived signals\n  };\n  for (const signal of signals) {\n    if (signal.aborted) {\n      abort(signal.reason);\n      break;\n    }\n    const onAbort = () => abort(signal.reason);\n    signal.addEventListener(\"abort\", onAbort, { once: true });\n    cleanups.push(() => signal.removeEventListener(\"abort\", onAbort));\n  }\n  return controller.signal;\n}\n\nexport async function withTimeout<T>(task: (signal: AbortSignal) => Promise<T>, ms: number, { signal }: { signal?: AbortSignal } = {}): Promise<T> {\n  const timeout = new AbortController();\n  const id = setTimeout(() => timeout.abort(new DOMException(\"Timed out after \" + ms + \" ms\", \"TimeoutError\")), ms);\n  const combined = signal ? anySignal([signal, timeout.signal]) : timeout.signal;\n  try {\n    combined.throwIfAborted();\n    return await new Promise<T>((resolve, reject) => {\n      // Settle on abort even if the task ignores its signal.\n      combined.addEventListener(\"abort\", () => reject(combined.reason), { once: true });\n      task(combined).then(resolve, reject);\n    });\n  } finally {\n    clearTimeout(id);\n  }\n}\n"}'::jsonb),
  ('cxl-concurrency-strategies', null::text[], '{"en":"Each strategy is a closure holding one piece of state. `latest` keeps the current `AbortController`: a new call aborts it, and wrapping the task in a promise that also rejects on `abort` guarantees a stale result can never be delivered. `exhaust` keeps the in-flight promise and clears it in `finally`, so failures don''t lock it forever. `queue` keeps a promise chain tail: each call runs after the previous one settles, and the tail swallows errors (`catch(() => {})`) so one failure doesn''t reject everything after it, while each caller still gets its own rejection.","uk":"Кожна стратегія є замиканням з одним елементом стану. `latest` тримає поточний `AbortController`: новий виклик скасовує його, а загортання задачі в проміс, що також відхиляється на `abort`, гарантує, що застарілий результат ніколи не буде доставлено. `exhaust` тримає поточний проміс і очищає його у `finally`, тож збої не блокують його назавжди. `queue` тримає хвіст ланцюжка промісів: кожен виклик виконується після завершення попереднього, а хвіст ковтає помилки (`catch(() => {})`), тож один збій не відхиляє все, що після нього, хоча кожен, хто викликав, усе одно отримує власне відхилення."}'::jsonb, '{"/src/strategies.ts":"export function latest<A extends unknown[], R>(task: (signal: AbortSignal, ...args: A) => Promise<R>) {\n  let current: AbortController | null = null;\n  return (...args: A): Promise<R> => {\n    current?.abort(new DOMException(\"Superseded by a newer call\", \"AbortError\"));\n    const controller = new AbortController();\n    current = controller;\n    return new Promise<R>((resolve, reject) => {\n      // Reject as soon as we''re superseded, even if the task ignores its signal and finishes later.\n      controller.signal.addEventListener(\"abort\", () => reject(controller.signal.reason), { once: true });\n      task(controller.signal, ...args).then(resolve, reject);\n    }).finally(() => {\n      if (current === controller) current = null;\n    });\n  };\n}\n\nexport function exhaust<A extends unknown[], R>(task: (...args: A) => Promise<R>) {\n  let inFlight: Promise<R> | null = null;\n  return (...args: A): Promise<R> => {\n    if (!inFlight) {\n      inFlight = Promise.resolve()\n        .then(() => task(...args))\n        .finally(() => {\n          inFlight = null;\n        });\n    }\n    return inFlight;\n  };\n}\n\nexport function queue<A extends unknown[], R>(task: (...args: A) => Promise<R>) {\n  let tail: Promise<unknown> = Promise.resolve();\n  return (...args: A): Promise<R> => {\n    const result = tail.then(() => task(...args));\n    // The next call waits for this one to settle either way, so one failure doesn''t block the rest.\n    tail = result.catch(() => {});\n    return result;\n  };\n}\n"}'::jsonb),
  ('async-fn-returns-promise', array['a']::text[], '{"en":"An `async` function always returns a promise. A returned value (`42`) becomes the fulfilment value, and a thrown error becomes a rejection. To get `42`, the caller must `await getAnswer()` or use `.then`.","uk":"`async`-функція завжди повертає проміс. Повернене значення (`42`) стає значенням виконання, а кинута помилка стає відхиленням. Щоб отримати `42`, викликач має написати `await getAnswer()` або використати `.then`."}'::jsonb, null::jsonb),
  ('async-missing-return', array['a']::text[], '{"en":"A `then` callback''s **return value** becomes the next step''s input. With braces and no `return`, the callback returns `undefined`, so the next `then` runs immediately with `undefined` while `fetchPosts` continues unobserved (and its errors go unhandled). Write `.then((user) => fetchPosts(user.id))` or use `async`/`await`.","uk":"**Повернене значення** колбека `then` стає вхідним для наступного кроку. З фігурними дужками й без `return` колбек повертає `undefined`, тож наступний `then` виконується одразу з `undefined`, а `fetchPosts` працює далі без нагляду (і його помилки лишаються необробленими). Пишіть `.then((user) => fetchPosts(user.id))` або використовуйте `async`/`await`."}'::jsonb, null::jsonb),
  ('async-race-loser', array['a']::text[], '{"en":"Promises are results, not handles to the work, so `Promise.race` can''t cancel anything: it only settles with whichever finishes first. The slow operation keeps running and finishes later. To really stop it (and save bandwidth), pass an `AbortSignal` to the operation, e.g. `fetch(url, { signal: AbortSignal.timeout(10) })`.","uk":"Проміси є результатами, а не керуванням роботою, тож `Promise.race` нічого не скасовує: він лише завершується з тим, що закінчилося першим. Повільна операція працює далі й завершується пізніше. Щоб справді її зупинити (і заощадити трафік), передайте операції `AbortSignal`, наприклад `fetch(url, { signal: AbortSignal.timeout(10) })`."}'::jsonb, null::jsonb),
  ('async-catch-then', array['a']::text[], '{"en":"A rejection skips `then` callbacks without a rejection handler until it reaches a `catch`. Once `catch` handles it (and doesn''t rethrow), the chain is fulfilled again with the handler''s return value, so the following `then` runs. Put `catch` at the end if later steps shouldn''t run after an error.","uk":"Відхилення пропускає колбеки `then` без обробника відхилення, доки не дійде до `catch`. Щойно `catch` його обробив (і не кинув помилку знову), ланцюжок знову виконаний зі значенням, яке повернув обробник, тож наступний `then` виконується. Ставте `catch` у кінці, якщо наступні кроки не мають виконуватися після помилки."}'::jsonb, null::jsonb),
  ('async-finally-value', array['a']::text[], '{"en":"`finally` is for cleanup: its callback gets no arguments and its return value is ignored, so the original value (`1`) or rejection passes through. The one exception is an error thrown (or a rejected promise returned) inside `finally`, which replaces the original outcome, so the caller sees `b`, not `a`.","uk":"`finally` призначений для прибирання: його колбек не отримує аргументів, а повернене значення ігнорується, тож початкове значення (`1`) чи відхилення проходить далі. Єдиний виняток: помилка, кинута всередині `finally` (або повернений відхилений проміс), замінює початковий результат, тож викликач бачить `b`, а не `a`."}'::jsonb, null::jsonb),
  ('async-empty-combinators', array['a']::text[], '{"en":"`all([])` and `allSettled([])` fulfil immediately with `[]` (every one of zero inputs is done). `any([])` rejects with an `AggregateError` (no input can fulfil). `race([])` waits for the first input to settle, and there is none, so it stays pending forever. Guard against empty lists before racing.","uk":"`all([])` і `allSettled([])` одразу виконуються з `[]` (кожен із нуля входів завершений). `any([])` відхиляється з `AggregateError` (жоден вхід не може виконатися). `race([])` чекає, поки завершиться перший вхід, а його немає, тож лишається в очікуванні назавжди. Перевіряйте список на порожність перед перегонами."}'::jsonb, null::jsonb),
  ('async-return-without-await', array['a']::text[], '{"en":"`return fetchData()` hands the pending promise to the caller and leaves the `try` block immediately. When it later rejects, there''s no `catch` around it any more. `return await fetchData()` waits **inside** the `try`, so the rejection is thrown there and the fallback is returned. Outside `try/catch`, plain `return` is fine.","uk":"`return fetchData()` передає проміс, що очікує, викликачу й одразу виходить із блоку `try`. Коли він пізніше відхиляється, навколо вже немає `catch`. `return await fetchData()` чекає **всередині** `try`, тож відхилення кидається там і повертається запасне значення. Поза `try/catch` звичайний `return` цілком підходить."}'::jsonb, null::jsonb),
  ('async-lost-update', array['a']::text[], '{"en":"Both deposits read `100` before either writes, then each writes its own result: `110`, then `120`. One deposit is lost. Single-threaded JavaScript still has race conditions whenever an `await` sits between reading and writing shared state. Fix it by serialising the critical section (a mutex or queue), making the update atomic on the server (`UPDATE … SET balance = balance + 10`), or using optimistic concurrency with a version check.","uk":"Обидва поповнення читають `100`, перш ніж хтось запише, а потім кожне записує свій результат: `110`, потім `120`. Одне поповнення втрачено. Однопотоковий JavaScript усе одно має стан гонитви, щойно між читанням і записом спільного стану стоїть `await`. Виправлення: серіалізувати критичну секцію (м''ютекс чи черга), зробити оновлення атомарним на сервері (`UPDATE … SET balance = balance + 10`) або використати оптимістичну конкурентність із перевіркою версії."}'::jsonb, null::jsonb),
  ('async-combinators', null::text[], '{"en":"Each combinator wraps a new promise around a counter. Storing results by index (not by push) keeps input order, `Promise.resolve(item)` normalises values and thenables, and passing `reject` directly gives fail-fast behaviour because a promise settles only once. `allSettled` maps each input to a promise that always fulfils and reuses `all`; `any` mirrors `all` with the roles of success and failure swapped.","uk":"Кожен комбінатор обгортає новий проміс навколо лічильника. Збереження результатів за індексом (а не через push) зберігає порядок входу, `Promise.resolve(item)` уніфікує значення й thenable, а передача `reject` напряму дає швидку відмову, бо проміс завершується лише раз. `allSettled` перетворює кожен вхід на проміс, що завжди виконується, і використовує `all`; `any` дзеркалить `all`, міняючи ролі успіху й невдачі."}'::jsonb, '{"/src/combinators.ts":"export function promiseAll<T>(values: Iterable<T | PromiseLike<T>>): Promise<Awaited<T>[]> {\n  return new Promise((resolve, reject) => {\n    const items = Array.from(values);\n    const results = new Array<Awaited<T>>(items.length);\n    let remaining = items.length;\n    if (remaining === 0) return resolve(results);\n    items.forEach((item, i) => {\n      // Promise.resolve also accepts plain values and foreign thenables.\n      Promise.resolve(item).then((value) => {\n        results[i] = value as Awaited<T>; // store by index: settle order doesn''t matter\n        if (--remaining === 0) resolve(results);\n      }, reject); // the first rejection wins; later calls to reject are ignored\n    });\n  });\n}\n\nexport function promiseAllSettled<T>(values: Iterable<T | PromiseLike<T>>): Promise<PromiseSettledResult<Awaited<T>>[]> {\n  return promiseAll(\n    Array.from(values, (item) =>\n      Promise.resolve(item).then(\n        (value): PromiseSettledResult<Awaited<T>> => ({ status: \"fulfilled\", value: value as Awaited<T> }),\n        (reason): PromiseSettledResult<Awaited<T>> => ({ status: \"rejected\", reason }),\n      ),\n    ),\n  );\n}\n\nexport function promiseAny<T>(values: Iterable<T | PromiseLike<T>>): Promise<Awaited<T>> {\n  return new Promise((resolve, reject) => {\n    const items = Array.from(values);\n    const errors: unknown[] = new Array(items.length);\n    let remaining = items.length;\n    if (remaining === 0) return reject(new AggregateError([], \"All promises were rejected\"));\n    items.forEach((item, i) => {\n      Promise.resolve(item).then(\n        (value) => resolve(value as Awaited<T>),\n        (error) => {\n          errors[i] = error;\n          if (--remaining === 0) reject(new AggregateError(errors, \"All promises were rejected\"));\n        },\n      );\n    });\n  });\n}\n"}'::jsonb),
  ('async-mutex', null::text[], '{"en":"The mutex is just a promise chain: each call attaches its task to the tail of the previous one, so tasks start in call order and only after the previous task settles. The tail is a version of the result with errors swallowed, so one failure doesn''t poison the queue, while the caller still receives the real rejection. `try/finally` keeps `locked` accurate even when `fn` throws.","uk":"М''ютекс є просто ланцюжком промісів: кожен виклик чіпляє свою задачу до хвоста попередньої, тож задачі стартують у порядку викликів і лише після завершення попередньої. Хвіст є версією результату з проковтнутими помилками, тож одна невдача не отруює чергу, а викликач усе одно отримує справжнє відхилення. `try/finally` тримає `locked` точним, навіть коли `fn` кидає помилку."}'::jsonb, '{"/src/mutex.ts":"export interface Mutex {\n  runExclusive<T>(fn: () => T | Promise<T>): Promise<T>;\n  readonly locked: boolean;\n  readonly pending: number;\n}\n\nexport function createMutex(): Mutex {\n  // Each task chains onto the previous one, so they run strictly one after another.\n  let tail: Promise<unknown> = Promise.resolve();\n  let running = false;\n  let waiting = 0;\n\n  return {\n    get locked() {\n      return running;\n    },\n    get pending() {\n      return waiting;\n    },\n    runExclusive<T>(fn: () => T | Promise<T>): Promise<T> {\n      waiting++;\n      const result = tail.then(async () => {\n        waiting--;\n        running = true;\n        try {\n          return await fn();\n        } finally {\n          running = false;\n        }\n      });\n      // A failure must not block the queue: later tasks wait for completion, not success.\n      tail = result.catch(() => undefined);\n      return result;\n    },\n  };\n}\n"}'::jsonb),
  ('async-return-value', array['b']::text[], '{"en":"An `async` function always returns a Promise. A returned value becomes the fulfilment value, and a thrown error becomes a rejection. Read the value with `await getAnswer()` or `.then()`.","uk":"`async`-функція завжди повертає Promise. Повернене значення стає значенням виконання, а кинута помилка — відхиленням. Отримайте значення через `await getAnswer()` або `.then()`."}'::jsonb, null::jsonb),
  ('async-all-fail-fast', array['b']::text[], '{"en":"`Promise.all` rejects as soon as any input rejects, but promises are not cancellable: the other requests continue and their results are dropped. `Promise.all` subscribes to every input, so their later rejections are not reported as unhandled. To actually stop the work, pass an `AbortSignal` and abort it in a `catch`.","uk":"`Promise.all` відхиляється, щойно відхиляється будь-який вхід, але проміси не скасовуються: решта запитів триває, а їхні результати відкидаються. `Promise.all` підписується на кожен вхід, тож пізніші відхилення не стають необробленими. Щоб справді зупинити роботу, передайте `AbortSignal` і скасуйте його в `catch`."}'::jsonb, null::jsonb),
  ('async-return-promise-ticks', array['b']::text[], '{"en":"Resolving the async function''s promise with another promise isn''t immediate: it schedules a job that calls the inner promise''s `then`, which takes extra microtask ticks before the outer promise settles. `Promise.resolve(\"b\").then` needs only one tick, so `b` wins. `return await` or returning a plain value avoids the extra ticks, but don''t build logic on tick counting.","uk":"Виконання промісу async-функції іншим промісом не миттєве: планується завдання, що викликає `then` внутрішнього промісу, і це займає додаткові мікрозавдання, перш ніж зовнішній проміс завершиться. `Promise.resolve(\"b\").then` потребує лише одного такту, тож `b` перший. `return await` або повернення звичайного значення прибирає зайві такти, але не будуйте логіку на підрахунку тактів."}'::jsonb, null::jsonb),
  ('async-retry-backoff', null::text[], '{"en":"A loop with `try { return await task(attempt) }` keeps the code flat: `return await` is needed so a rejection lands in this `catch`. After attempt n the wait is `base · 2^(n-1)`. Rethrowing the caught error preserves the last failure. In production, add random jitter so many clients don''t retry in lockstep, and only retry errors that can succeed later (timeouts, 429, 5xx).","uk":"Цикл із `try { return await task(attempt) }` тримає код пласким: `return await` потрібен, щоб відхилення потрапило в цей `catch`. Після спроби n затримка — `base · 2^(n-1)`. Повторне кидання впійманої помилки зберігає останню невдачу. У продакшні додайте випадковий розкид, щоб багато клієнтів не повторювали синхронно, і повторюйте лише помилки, що можуть минути (тайм-аути, 429, 5xx)."}'::jsonb, '{"/src/retry.ts":"export type RetryOptions = {\n  retries: number;\n  baseDelayMs: number;\n  shouldRetry?: (error: unknown) => boolean;\n};\n\nconst sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));\n\nexport async function retry<T>(task: (attempt: number) => Promise<T>, options: RetryOptions): Promise<T> {\n  const { retries, baseDelayMs, shouldRetry = () => true } = options;\n  for (let attempt = 1; ; attempt++) {\n    try {\n      return await task(attempt);\n    } catch (error) {\n      if (attempt > retries || !shouldRetry(error)) throw error;\n      await sleep(baseDelayMs * 2 ** (attempt - 1));\n    }\n  }\n}\n"}'::jsonb),
  ('async-event-loop-order', array['b']::text[], '{"en":"Synchronous code runs first (1, 4). Then all microtasks run (the promise callback: 3), and only then the next macrotask (the timer: 2).","uk":"Спершу виконується синхронний код (1, 4). Потім усі мікрозадачі (колбек промісу: 3), і лише тоді наступна макрозадача (таймер: 2)."}'::jsonb, null::jsonb),
  ('async-all-settled', array['b']::text[], '{"en":"`allSettled` waits for every promise and reports `{status, value|reason}` for each, so one failure doesn''t hide the others. `all` rejects on the first error; `race`/`any` give you only one result.","uk":"`allSettled` чекає на кожен проміс і повертає `{status, value|reason}` для всіх, тож одна помилка не приховує решту. `all` відхиляється на першій помилці; `race`/`any` дають лише один результат."}'::jsonb, null::jsonb),
  ('async-foreach-await', array['a']::text[], '{"en":"Each callback is async and returns a promise that `forEach` drops. Use `await Promise.all(files.map(upload))` for parallel uploads, or `for (const f of files) await upload(f)` for sequential ones.","uk":"Кожен колбек асинхронний і повертає проміс, який `forEach` відкидає. Використовуйте `await Promise.all(files.map(upload))` для паралельних завантажень або `for (const f of files) await upload(f)` для послідовних."}'::jsonb, null::jsonb),
  ('async-sequential-vs-parallel', array['b']::text[], '{"en":"The second request starts only after the first finishes. Starting both before awaiting overlaps the network waits: `const [user, orders] = await Promise.all([getUser(), getOrders()])`. A single thread doesn''t matter, because the waiting happens in the network stack.","uk":"Другий запит стартує лише після завершення першого. Якщо запустити обидва до `await`, очікування мережі перекриваються: `const [user, orders] = await Promise.all([getUser(), getOrders()])`. Один потік не заважає, бо очікування відбувається в мережевому стеку."}'::jsonb, null::jsonb),
  ('async-promise-any', array['b']::text[], '{"en":"`race` settles with whichever promise settles first, including a fast failure. `any` waits for the first fulfilment and only rejects (with `AggregateError`) when every promise rejected.","uk":"`race` завершується тим промісом, що завершився першим, навіть швидкою помилкою. `any` чекає першого успіху й відхиляється (з `AggregateError`) лише коли відхилено всі проміси."}'::jsonb, null::jsonb),
  ('async-map-with-concurrency', null::text[], '{"en":"Start `limit` workers. Each one repeatedly claims the next index and awaits `fn`. Because JavaScript runs on one thread, `next++` can''t race. Writing into `results[index]` keeps the input order, and `Promise.all(workers)` rejects as soon as any worker throws.","uk":"Запустіть `limit` воркерів. Кожен по черзі забирає наступний індекс і чекає на `fn`. Оскільки JavaScript працює в одному потоці, `next++` не має гонки. Запис у `results[index]` зберігає порядок вхідних даних, а `Promise.all(workers)` відхиляється, щойно будь-який воркер кидає помилку."}'::jsonb, '{"/src/mapWithConcurrency.ts":"export async function mapWithConcurrency<T, R>(\n  items: T[],\n  limit: number,\n  fn: (item: T, index: number) => Promise<R>,\n): Promise<R[]> {\n  const results = new Array<R>(items.length);\n  let next = 0;\n\n  async function worker() {\n    while (next < items.length) {\n      const index = next++; // claimed synchronously: no two workers take the same index\n      results[index] = await fn(items[index], index);\n    }\n  }\n\n  const workers = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, worker);\n  await Promise.all(workers);\n  return results;\n}\n"}'::jsonb),
  ('auth-authn-vs-authz', array['a']::text[], '{"en":"Authentication establishes identity (\"who are you?\"); failures there are `401 Unauthorized`. Authorisation decides what an identified user may do; failures there are `403 Forbidden`. Both must be enforced on the server; the UI hiding an admin link is only a convenience.","uk":"Автентифікація встановлює особу («хто ви?»); невдачі там дають `401 Unauthorized`. Авторизація вирішує, що може робити встановлений користувач; невдачі там дають `403 Forbidden`. Обидві треба забезпечувати на сервері; приховане в інтерфейсі посилання на адмінку є лише зручністю."}'::jsonb, null::jsonb),
  ('auth-jwt-readable', array['a']::text[], '{"en":"A JWS-signed token proves the issuer created it and nobody changed it, but its header and payload are plain base64url-encoded JSON. Never put secrets or personal data in it. Keep claims minimal (an ID, roles, expiry), and validate signature, algorithm, `exp`, `iss` and `aud` on every request.","uk":"Підписаний (JWS) токен доводить, що його створив видавець і ніхто не змінив, але заголовок і вміст є звичайним JSON у base64url. Ніколи не кладіть туди секрети чи особисті дані. Тримайте твердження мінімальними (ID, ролі, термін дії) й перевіряйте підпис, алгоритм, `exp`, `iss` і `aud` при кожному запиті."}'::jsonb, null::jsonb),
  ('auth-token-storage', array['a']::text[], '{"en":"`localStorage` is per-origin (other sites can''t read it) and persistent, but every script on your page can read it, so one XSS bug or compromised dependency steals a long-lived credential. An `HttpOnly` cookie can''t be read by scripts, and an in-memory access token expires quickly. You still need XSS prevention and CSRF protection.","uk":"`localStorage` прив''язаний до origin (інші сайти його не читають) і постійний, але кожен скрипт на вашій сторінці може його прочитати, тож одна XSS-вразливість чи зламана залежність краде довгоживучі облікові дані. Cookie з `HttpOnly` скрипти не читають, а access-токен у пам''яті швидко спливає. Захист від XSS і CSRF усе одно потрібен."}'::jsonb, null::jsonb),
  ('auth-pkce', array['a']::text[], '{"en":"Public clients (SPAs, mobile apps) can''t keep a client secret. PKCE binds the code to the app instance: it sends a hash of a random verifier when starting the flow and must present the verifier itself when redeeming the code. The separate `state` parameter protects against CSRF on the redirect. The old implicit flow is deprecated in favour of this.","uk":"Публічні клієнти (SPA, мобільні застосунки) не можуть тримати клієнтський секрет. PKCE прив''язує код до екземпляра застосунку: на початку потоку той надсилає хеш випадкового верифікатора й мусить пред''явити сам верифікатор під час обміну коду. Окремий параметр `state` захищає від CSRF на перенаправленні. Старий implicit flow застарів на користь цього."}'::jsonb, null::jsonb),
  ('auth-idor', array['a']::text[], '{"en":"Being authenticated isn''t the same as being allowed to see this object. Every lookup must be scoped to the caller (`WHERE id = $1 AND customer_id = $2`, or row-level security). Unguessable IDs make enumeration harder but aren''t authorisation, since IDs leak through links, logs and shared screens.","uk":"Бути автентифікованим не означає мати право бачити цей об''єкт. Кожен пошук треба обмежувати викликачем (`WHERE id = $1 AND customer_id = $2` або row-level security). Невгадувані ID ускладнюють перебір, але не є авторизацією, бо ID витікають через посилання, журнали й спільні екрани."}'::jsonb, null::jsonb),
  ('auth-refresh-rotation', array['a']::text[], '{"en":"With rotation, each refresh token should be used exactly once. Reuse means two parties hold the same token: a copy was stolen. Since the server can''t tell which party is legitimate, revoking the session family limits the damage. Rotation plus reuse detection is the recommended practice for refresh tokens held by browsers.","uk":"З ротацією кожен refresh-токен має використовуватися рівно один раз. Повторне використання означає, що той самий токен мають дві сторони: копію викрали. Оскільки сервер не знає, хто законний, відкликання всієї родини сесії обмежує шкоду. Ротація з виявленням повторного використання є рекомендованою практикою для refresh-токенів у браузерах."}'::jsonb, null::jsonb),
  ('auth-refresh-client', null::text[], '{"en":"Storing the in-flight refresh promise makes concurrent callers await the same refresh instead of starting their own (which, with rotating refresh tokens, would invalidate each other). Remembering which token each request used lets late 401s simply retry with the newer token. Clearing the promise in `finally` allows a future refresh, and capping retries at one prevents infinite loops when the session is truly over.","uk":"Збереження промісу поточного оновлення змушує одночасних викликачів чекати на те саме оновлення, а не запускати власні (що з ротацією refresh-токенів анулювало б одне одного). Запам''ятовування токена, з яким пішов кожен запит, дає пізнім 401 просто повторити з новішим токеном. Очищення промісу у `finally` дозволяє майбутнє оновлення, а обмеження одним повтором запобігає нескінченним циклам, коли сесія справді завершилася."}'::jsonb, '{"/src/client.ts":"export type ApiResponse = { status: number; body?: unknown };\nexport type Fetcher = (url: string, init: { headers: Record<string, string> }) => Promise<ApiResponse>;\nexport type AuthClientOptions = {\n  fetcher: Fetcher;\n  /** Exchanges the refresh cookie for a new access token. Rejects if the session is over. */\n  refresh: () => Promise<string>;\n  initialToken: string;\n  onLogout?: () => void;\n};\n\nexport function createAuthClient({ fetcher, refresh, initialToken, onLogout }: AuthClientOptions) {\n  let token = initialToken;\n  let refreshing: Promise<string> | null = null;\n\n  const send = (url: string, t: string) => fetcher(url, { headers: { Authorization: \"Bearer \" + t } });\n\n  /** Single flight: every caller during a refresh shares the same promise. */\n  function refreshOnce(): Promise<string> {\n    if (!refreshing) {\n      refreshing = refresh()\n        .then(\n          (next) => {\n            token = next;\n            return next;\n          },\n          (error) => {\n            onLogout?.();\n            throw error;\n          },\n        )\n        .finally(() => {\n          refreshing = null;\n        });\n    }\n    return refreshing;\n  }\n\n  return {\n    get token() {\n      return token;\n    },\n    async request(url: string): Promise<ApiResponse> {\n      const used = token;\n      const first = await send(url, used);\n      if (first.status !== 401) return first;\n      // If someone already refreshed while this request was in flight, just retry with the new token.\n      const next = token !== used ? token : await refreshOnce();\n      const second = await send(url, next);\n      if (second.status === 401) {\n        onLogout?.();\n        throw new Error(\"Unauthorized\");\n      }\n      return second;\n    },\n  };\n}\n"}'::jsonb),
  ('bigo-two-inputs', array['c']::text[], '{"en":"The inner loop runs m times for each of the n outer iterations: O(n · m). Calling it O(n²) hides that the inputs are independent; if there are only a few coupons, this is effectively linear in n. Putting the coupon codes in a `Set` first would make it O(n + m).","uk":"Внутрішній цикл виконується m разів для кожної з n зовнішніх ітерацій: O(n · m). Назва O(n²) приховує, що входи незалежні; якщо купонів лише кілька, це фактично лінійно за n. Якщо спершу покласти коди купонів у `Set`, вийде O(n + m)."}'::jsonb, null::jsonb),
  ('bigo-recurrence', array['b']::text[], '{"en":"The work per level is n + n/2 + n/4 + …, a geometric series that sums to less than 2n, so T(n) = O(n). Compare merge sort, T(n) = 2T(n/2) + n: there each level does n work in total across log n levels, giving O(n log n). Quickselect''s average case follows the T(n/2) + n pattern.","uk":"Робота на рівнях — n + n/2 + n/4 + …, геометрична прогресія із сумою менше 2n, тож T(n) = O(n). Порівняйте з сортуванням злиттям, T(n) = 2T(n/2) + n: там кожен рівень загалом виконує n роботи на log n рівнях, що дає O(n log n). Середній випадок quickselect відповідає шаблону T(n/2) + n."}'::jsonb, null::jsonb),
  ('bigo-output-size', array['b']::text[], '{"en":"There are 2ⁿ subsets, and the function materialises each one as an array: `[...s, item]` copies up to n elements, so the total work (and output size) is O(n · 2ⁿ). When the output itself is large, the complexity can never be lower than the size of the output.","uk":"Існує 2ⁿ підмножин, і функція створює кожну як масив: `[...s, item]` копіює до n елементів, тож загальна робота (і розмір виходу) — O(n · 2ⁿ). Коли вихід сам великий, складність не може бути меншою за його розмір."}'::jsonb, null::jsonb),
  ('bigo-nearby-duplicate', null::text[], '{"en":"Remember the most recent index of each value in a `Map`. For each position, a single O(1) average lookup tells you whether the same value appeared within the last k positions; keeping only the latest index is enough, because it is always the closest one. That''s O(n) time and O(n) space. A sliding-window `Set` of the last k values works too and uses O(k) memory.","uk":"Запам''ятовуйте останній індекс кожного значення в `Map`. Для кожної позиції один пошук за O(1) у середньому каже, чи траплялося те саме значення в межах останніх k позицій; достатньо зберігати лише останній індекс, бо він завжди найближчий. Це O(n) часу й O(n) пам''яті. Підходить і ковзне вікно `Set` з останніх k значень, що використовує O(k) пам''яті."}'::jsonb, '{"/src/nearby.ts":"export function hasNearbyDuplicate(values: number[], k: number): boolean {\n  const lastIndex = new Map<number, number>();\n  for (let i = 0; i < values.length; i++) {\n    const previous = lastIndex.get(values[i]);\n    if (previous !== undefined && i - previous <= k) return true;\n    lastIndex.set(values[i], i);\n  }\n  return false;\n}\n"}'::jsonb),
  ('bigo-nested-loops', array['c']::text[], '{"en":"The inner loop runs up to n times for each of the n outer iterations: about n²/2 comparisons, which is O(n²), since constants are dropped.","uk":"Внутрішній цикл виконується до n разів для кожної з n зовнішніх ітерацій: близько n²/2 порівнянь, тобто O(n²), бо константи відкидаються."}'::jsonb, null::jsonb),
  ('bigo-includes-in-loop', array['b']::text[], '{"en":"`includes` scans the whole array, so it''s O(m) per user and O(n·m) overall. A Set gives O(1) average membership: O(m) to build it plus O(n) to filter.","uk":"`includes` переглядає весь масив, тобто O(m) на кожного користувача й O(n·m) загалом. Set дає перевірку наявності в середньому за O(1): O(m) на побудову плюс O(n) на фільтрацію."}'::jsonb, null::jsonb),
  ('bigo-halving', array['b']::text[], '{"en":"`n` halves every iteration, so the loop runs about log₂(n) times before reaching 0, the same reason binary search is O(log n).","uk":"`n` зменшується вдвічі на кожній ітерації, тож цикл виконується приблизно log₂(n) разів, доки не дійде до 0. З тієї самої причини бінарний пошук має O(log n)."}'::jsonb, null::jsonb),
  ('bigo-amortized-push', array['a']::text[], '{"en":"When capacity runs out, the engine allocates a bigger buffer (typically growing geometrically) and copies the elements. Those rare O(n) steps are spread over many cheap pushes, so n pushes cost O(n) in total.","uk":"Коли місткість закінчується, рушій виділяє більший буфер (зазвичай зі зростанням у геометричній прогресії) і копіює елементи. Ці рідкісні кроки O(n) розподіляються між багатьма дешевими push, тож n push разом коштують O(n)."}'::jsonb, null::jsonb),
  ('bigo-space-recursion', array['d']::text[], '{"en":"The recursion is n deep, and each live frame holds its own slice of size n−k, so the total memory is n + (n−1) + … = O(n²) (time is O(n²) too). Passing an index instead of slicing brings it to O(n) stack, or O(1) as a loop.","uk":"Глибина рекурсії n, і кожен активний кадр тримає власний зріз розміру n−k, тож загалом пам''ять n + (n−1) + … = O(n²) (час теж O(n²)). Передача індексу замість зрізу дає O(n) стеку, а цикл дає O(1)."}'::jsonb, null::jsonb),
  ('browser-intersection-observer', array['b']::text[], '{"en":"`IntersectionObserver` lets the browser compute visibility asynchronously and calls you only when the sentinel crosses the threshold. `rootMargin: \"400px\"` starts loading before the user actually reaches the end. Scroll handlers that read layout run on every scroll event and can force synchronous layout.","uk":"`IntersectionObserver` дозволяє браузеру асинхронно обчислювати видимість і викликає вас лише тоді, коли маркер перетинає поріг. `rootMargin: \"400px\"` починає завантаження ще до того, як користувач дійде до кінця. Обробники прокрутки, що читають розмітку, виконуються на кожну подію й можуть змушувати синхронний перерахунок макета."}'::jsonb, null::jsonb),
  ('browser-storage-event', array['c']::text[], '{"en":"The `storage` event fires in other documents of the same origin that share the storage area, never in the one that made the change. That makes it a simple cross-tab sync channel (log out everywhere, theme changes). For richer messaging, use `BroadcastChannel`.","uk":"Подія `storage` спрацьовує в інших документах того самого походження, що мають спільне сховище, але ніколи в тому, який зробив зміну. Тож це простий канал синхронізації між вкладками (вихід усюди, зміна теми). Для багатшого обміну повідомленнями використовуйте `BroadcastChannel`."}'::jsonb, null::jsonb),
  ('browser-sw-waiting', array['b']::text[], '{"en":"A new service worker installs in the background and then waits while any client is still controlled by the old one. A reload doesn''t release the client, because the old page stays alive until the new one commits. Show an \"Update available\" prompt that calls `skipWaiting()` (then reload on `controllerchange`), or call `skipWaiting()` if your caches are backwards compatible.","uk":"Новий service worker встановлюється у фоні й чекає, доки хоч один клієнт ще керується старим. Перезавантаження не звільняє клієнта, бо стара сторінка живе, доки нова не завантажиться. Покажіть підказку «Доступне оновлення», що викликає `skipWaiting()` (і перезавантажте на `controllerchange`), або викликайте `skipWaiting()`, якщо ваші кеші зворотно сумісні."}'::jsonb, null::jsonb),
  ('browser-build-url', null::text[], '{"en":"`new URL(base)` parses the existing query into `url.searchParams`, which handles all the encoding (`application/x-www-form-urlencoded`, so spaces become `+`). `delete` and then `append` gives replace-then-repeat semantics for arrays, and `set` replaces a single value. String concatenation breaks as soon as a value contains `&`, `#` or `=`.","uk":"`new URL(base)` розбирає наявний запит у `url.searchParams`, що бере на себе все кодування (`application/x-www-form-urlencoded`, тож пробіли стають `+`). `delete`, а потім `append` дають для масивів семантику «замінити, потім повторити», а `set` замінює одне значення. Конкатенація рядків ламається, щойно значення містить `&`, `#` або `=`."}'::jsonb, '{"/src/build-url.ts":"export type QueryValue = string | number | boolean | null | undefined | (string | number)[];\n\nexport function buildUrl(base: string, params: Record<string, QueryValue>): string {\n  const url = new URL(base);\n  for (const [key, value] of Object.entries(params)) {\n    if (value === undefined || value === null) continue;\n    url.searchParams.delete(key);\n    if (Array.isArray(value)) {\n      for (const item of value) url.searchParams.append(key, String(item));\n    } else {\n      url.searchParams.set(key, String(value));\n    }\n  }\n  return url.toString();\n}\n"}'::jsonb),
  ('api-fetch-404', array['b']::text[], '{"en":"fetch only rejects on network failure, CORS blocks or abort. Any HTTP response, including 404 and 500, resolves. Check `response.ok` (status 200–299) and throw yourself if needed.","uk":"fetch відхиляється лише при збої мережі, блокуванні CORS або скасуванні. Будь-яка HTTP-відповідь, включно з 404 і 500, вирішується. Перевіряйте `response.ok` (статус 200–299) і за потреби кидайте помилку самі."}'::jsonb, null::jsonb),
  ('api-localstorage-types', array['b']::text[], '{"en":"localStorage stores strings, so `1` becomes `\"1\"`. `getItem` returns `\"1\"`, and `\"1\" + 2` concatenates to `\"12\"`. Store JSON and parse it back (or use `Number(...)`).","uk":"localStorage зберігає рядки, тож `1` стає `\"1\"`. `getItem` повертає `\"1\"`, а `\"1\" + 2` конкатенується в `\"12\"`. Зберігайте JSON і розбирайте його назад (або використайте `Number(...)`)."}'::jsonb, null::jsonb),
  ('api-abort-stale', array['a']::text[], '{"en":"Responses can arrive out of order. Aborting the previous request (or ignoring responses whose query is no longer current) guarantees only the latest result is applied, and debouncing reduces the number of requests.","uk":"Відповіді можуть приходити в довільному порядку. Скасування попереднього запиту (або ігнорування відповідей, чий запит уже неактуальний) гарантує, що застосовується лише останній результат, а debounce зменшує кількість запитів."}'::jsonb, null::jsonb),
  ('api-intersection-observer', array['a']::text[], '{"en":"IntersectionObserver computes visibility off the main thread''s hot path and calls back only when thresholds are crossed. Scroll handlers with layout reads run on every scroll event and can cause jank. For images, native `loading=\"lazy\"` also works.","uk":"IntersectionObserver обчислює видимість поза гарячим шляхом головного потоку й викликає колбек лише при перетині порогів. Обробники scroll з читанням геометрії виконуються на кожну подію прокрутки й можуть спричиняти ривки. Для зображень також працює нативний `loading=\"lazy\"`."}'::jsonb, null::jsonb),
  ('api-token-storage', array['c']::text[], '{"en":"Injected scripts can read anything JavaScript can read: localStorage, sessionStorage and variables. An `HttpOnly` cookie is sent by the browser but is invisible to scripts, `Secure` limits it to HTTPS, and `SameSite` mitigates CSRF. XSS can still make requests, so prevent XSS too.","uk":"Впроваджені скрипти можуть прочитати все, до чого має доступ JavaScript: localStorage, sessionStorage і змінні. Cookie з `HttpOnly` браузер надсилає, але скрипти його не бачать, `Secure` обмежує його HTTPS, а `SameSite` пом''якшує CSRF. XSS усе одно може робити запити, тож запобігайте й самій XSS."}'::jsonb, null::jsonb),
  ('api-storage-with-ttl', null::text[], '{"en":"Wrap every value in an envelope `{ v, e }` with an optional expiry timestamp and store it as JSON, which preserves types and falsy values. `get` checks the expiry against the injected clock and deletes stale entries. `try/catch` guards both parsing and quota errors. Injecting `storage` and `now` makes the module easy to test.","uk":"Загортайте кожне значення в конверт `{ v, e }` з необов''язковою позначкою часу завершення й зберігайте як JSON, що зберігає типи й хибні значення. `get` порівнює термін дії з підставленим годинником і видаляє застарілі записи. `try/catch` захищає і розбір, і помилки переповнення. Підстановка `storage` і `now` робить модуль легким для тестування."}'::jsonb, '{"/src/store.ts":"type Options = { prefix: string; storage?: Storage; now?: () => number };\ntype Entry = { v: unknown; e: number | null };\n\nexport function createStore({ prefix, storage = localStorage, now = Date.now }: Options) {\n  const k = (key: string) => prefix + key;\n\n  return {\n    set(key: string, value: unknown, ttlMs?: number): boolean {\n      const entry: Entry = { v: value, e: ttlMs == null ? null : now() + ttlMs };\n      try {\n        storage.setItem(k(key), JSON.stringify(entry));\n        return true;\n      } catch {\n        return false; // quota exceeded or storage unavailable\n      }\n    },\n    get<T>(key: string): T | undefined {\n      const raw = storage.getItem(k(key));\n      if (raw == null) return undefined;\n      try {\n        const entry = JSON.parse(raw) as Entry;\n        if (entry.e != null && now() > entry.e) {\n          storage.removeItem(k(key));\n          return undefined;\n        }\n        return entry.v as T;\n      } catch {\n        return undefined;\n      }\n    },\n    remove(key: string): void {\n      storage.removeItem(k(key));\n    },\n  };\n}\n"}'::jsonb),
  ('closure-retained-memory', array['b']::text[], '{"en":"A closure keeps the variables it uses alive for as long as the function itself is reachable. `window` references the listener, the listener references `rows`, so nothing can be collected. Remove the listener when it''s no longer needed (or use an `AbortController` signal), or keep only the data the closure really needs.","uk":"Замикання тримає живими змінні, які використовує, доки сама функція досяжна. `window` посилається на обробник, обробник — на `rows`, тож нічого не може бути зібрано. Знімайте обробник, коли він більше не потрібен (або використовуйте сигнал `AbortController`), чи зберігайте лише ті дані, які замиканню справді потрібні."}'::jsonb, null::jsonb),
  ('closure-let-loop-copy', array['b']::text[], '{"en":"A `let` loop creates a new binding for each iteration, copying the current value into it before the increment runs. The first closure''s binding is incremented to 1 by the `i++` inside the body. The next iteration starts from a copy of 1, the loop''s `i++` makes it 2, the second closure captures that binding, and the body''s `i++` makes it 3. So the closures see 1 and 3.","uk":"Цикл із `let` створює нову прив''язку для кожної ітерації, копіюючи в неї поточне значення перед інкрементом. Прив''язку першого замикання `i++` у тілі збільшує до 1. Наступна ітерація починає з копії 1, `i++` циклу робить її 2, друге замикання захоплює цю прив''язку, а `i++` у тілі робить її 3. Тож замикання бачать 1 і 3."}'::jsonb, null::jsonb),
  ('closure-memoize-async', array['b']::text[], '{"en":"Caching the result only after `await` leaves a window where both calls miss the cache and fire two requests. Caching the promise immediately makes the second caller share the in-flight request. Without deleting rejected promises, a single network error is cached forever. (A `WeakMap` can''t use numbers as keys.)","uk":"Якщо кешувати результат лише після `await`, лишається проміжок, коли обидва виклики не знаходять кеш і роблять два запити. Кешування промісу одразу дає другому викликачу спільний запит у процесі. Без видалення відхилених промісів одна мережева помилка кешується назавжди. (`WeakMap` не може мати числа як ключі.)"}'::jsonb, null::jsonb),
  ('closure-curry', null::text[], '{"en":"Each call returns a new closure over the arguments collected so far. Building a fresh array (`[...args, ...more]`) instead of pushing into a shared one is what keeps partial applications independent. Regular `function` expressions (not arrows) let `this` flow through `apply` to `fn`.","uk":"Кожен виклик повертає нове замикання над уже зібраними аргументами. Створення нового масиву (`[...args, ...more]`) замість додавання до спільного — саме те, що робить часткові застосування незалежними. Звичайні вирази `function` (не стрілкові) дозволяють `this` пройти через `apply` до `fn`."}'::jsonb, '{"/src/curry.js":"export function curry(fn) {\n  return function curried(...args) {\n    if (args.length >= fn.length) return fn.apply(this, args);\n    return function (...more) {\n      return curried.apply(this, [...args, ...more]);\n    };\n  };\n}\n"}'::jsonb),
  ('closure-var-loop', array['b']::text[], '{"en":"`var` creates one function-scoped `i` shared by all callbacks. The timers run after the loop ends, when `i` is 3. With `let`, each iteration gets its own binding and you''d see `0 1 2`.","uk":"`var` створює один `i` в області функції, спільний для всіх колбеків. Таймери спрацьовують після завершення циклу, коли `i` дорівнює 3. З `let` кожна ітерація має власну прив''язку, і виведеться `0 1 2`."}'::jsonb, null::jsonb),
  ('closure-tdz', array['c']::text[], '{"en":"The inner `let name` is hoisted to the top of the function, so it shadows the outer variable for the whole block. Reading it before the declaration line is inside the temporal dead zone, which throws a `ReferenceError`.","uk":"Внутрішній `let name` піднімається на початок функції, тож затіняє зовнішню змінну в усьому блоці. Читання до рядка оголошення потрапляє в temporal dead zone, що кидає `ReferenceError`."}'::jsonb, null::jsonb),
  ('closure-independent-counters', array['b']::text[], '{"en":"Each call to `makeCounter` creates a new `count` variable, captured only by that counter''s function. `a` was called twice (2), `b` once (1).","uk":"Кожен виклик `makeCounter` створює нову змінну `count`, яку захоплює лише функція цього лічильника. `a` викликали двічі (2), `b` один раз (1)."}'::jsonb, null::jsonb),
  ('closure-stale-interval', array['a']::text[], '{"en":"With `[]` dependencies the effect runs once, and its callback keeps reading `count` from that render, so it sets 0 + 1 every second. The updater form reads the latest state without re-creating the interval.","uk":"З залежностями `[]` ефект виконується один раз, і його колбек постійно читає `count` з того рендеру, тож щосекунди встановлює 0 + 1. Форма з функцією-оновлювачем читає актуальний стан без перестворення інтервалу."}'::jsonb, null::jsonb),
  ('closure-memoize-falsy', array['b']::text[], '{"en":"The cached value is 0 (0² = 0), so `if (cache.get(arg))` is false and the function runs again. Testing membership with `has` works for every value, including 0, \"\", false and undefined.","uk":"Закешоване значення дорівнює 0 (0² = 0), тож `if (cache.get(arg))` хибне, і функція виконується знову. Перевірка через `has` працює для будь-якого значення, включно з 0, \"\", false і undefined."}'::jsonb, null::jsonb),
  ('closure-once-and-memoize', null::text[], '{"en":"Both helpers keep private state in a closure. `once` stores a flag and the first result, and uses `fn.apply(this, args)` to forward `this`. `memoize` keeps a Map and checks membership with `has`, so falsy results are cached too.","uk":"Обидві функції зберігають приватний стан у замиканні. `once` зберігає прапорець і перший результат та передає `this` через `fn.apply(this, args)`. `memoize` тримає Map і перевіряє наявність через `has`, тож хибні результати теж кешуються."}'::jsonb, '{"/src/fn.js":"export function once(fn) {\n  let called = false;\n  let result;\n  return function (...args) {\n    if (!called) {\n      called = true;\n      result = fn.apply(this, args);\n    }\n    return result;\n  };\n}\n\nexport function memoize(fn) {\n  const cache = new Map();\n  return function (arg, ...rest) {\n    if (!cache.has(arg)) cache.set(arg, fn.call(this, arg, ...rest));\n    return cache.get(arg);\n  };\n}\n"}'::jsonb),
  ('conc-worker-pool', null::text[], '{"en":"The pool is a queue plus a counter: `active` counts running tasks, and `pump()` starts queued work whenever a slot frees up, both when a task is added and when one finishes. Wrapping each task in its own promise means every caller gets its own outcome, and `finally` releases the slot whether the task succeeded or failed, which is what stops one bad task from wedging the pool. `drain` waits on a list of resolvers that is woken when the pool goes idle. Promise libraries ship this pattern (`p-limit`, `p-queue`), and the same idea bounds connection pools and thread pools in other runtimes.","uk":"Пул — це черга плюс лічильник: `active` рахує задачі, що виконуються, а `pump()` запускає чергові задачі щойно звільняється слот, і коли додано задачу, і коли задача завершилась. Загортання кожної задачі у власний проміс дає кожному викликачу його результат, а `finally` звільняє слот незалежно від успіху чи збою задачі, і це не дає одній поганій задачі заблокувати пул. `drain` чекає на список резольверів, які будяться, коли пул стає вільним. Бібліотеки промісів постачають цей шаблон (`p-limit`, `p-queue`), а та сама ідея обмежує пули з''єднань і пули потоків в інших середовищах."}'::jsonb, '{"/src/pool.ts":"export function createPool(limit: number) {\n  if (!(limit >= 1)) throw new RangeError(\"limit must be at least 1\");\n  let active = 0;\n  const queue: Array<() => void> = [];\n  const idleWaiters: Array<() => void> = [];\n\n  // Starts queued tasks while there are free slots, and wakes drain() callers when everything is finished.\n  const pump = (): void => {\n    if (active === 0 && queue.length === 0) {\n      for (const wake of idleWaiters.splice(0)) wake();\n      return;\n    }\n    while (active < limit && queue.length > 0) {\n      const start = queue.shift()!;\n      start();\n    }\n  };\n\n  return {\n    run<T>(task: () => Promise<T>): Promise<T> {\n      return new Promise<T>((resolve, reject) => {\n        queue.push(() => {\n          active++;\n          // Promise.resolve().then(task) also turns a synchronous throw into a rejection.\n          Promise.resolve()\n            .then(task)\n            .then(resolve, reject)\n            .finally(() => {\n              active--;\n              pump();\n            });\n        });\n        pump();\n      });\n    },\n    drain(): Promise<void> {\n      return new Promise<void>((resolve) => {\n        if (active === 0 && queue.length === 0) resolve();\n        else idleWaiters.push(resolve);\n      });\n    },\n    get active(): number {\n      return active;\n    },\n    get pending(): number {\n      return queue.length;\n    },\n  };\n}\n"}'::jsonb),
  ('css-margin-collapse', array['b']::text[], '{"en":"Adjacent vertical margins of block boxes in normal flow collapse into one margin equal to the larger of them, so the gap is 30px, not 50px. Margins don''t collapse inside flex or grid containers, which is one reason many layouts use `gap` instead.","uk":"Сусідні вертикальні відступи блокових елементів у звичайному потоці схлопуються в один, що дорівнює більшому з них, тож проміжок — 30px, а не 50px. Усередині flex- і grid-контейнерів відступи не схлопуються — одна з причин, чому багато макетів використовують `gap`."}'::jsonb, null::jsonb),
  ('css-where-specificity', array['b']::text[], '{"en":"`:where()` always contributes zero specificity, so `:where(#nav) a` is (0,0,1), the same as `a`. With equal specificity the later rule wins: blue. `:is(#nav) a` would take the specificity of its most specific argument, (1,0,1), and win. Libraries use `:where()` so their defaults are easy to override.","uk":"`:where()` завжди додає нульову специфічність, тож `:where(#nav) a` має (0,0,1), як і `a`. За рівної специфічності перемагає пізніше правило: синій. `:is(#nav) a` отримав би специфічність найспецифічнішого аргументу, (1,0,1), і переміг би. Бібліотеки використовують `:where()`, щоб їхні типові стилі легко перевизначались."}'::jsonb, null::jsonb),
  ('css-fixed-containing-block', array['b']::text[], '{"en":"An ancestor with `transform`, `filter`, `perspective`, `contain: paint` or `will-change: transform` becomes the containing block for `position: fixed` descendants, so they are positioned and clipped relative to it instead of the viewport. Render modals in a portal at the end of `<body>`, or use `<dialog>`, which goes into the top layer.","uk":"Предок із `transform`, `filter`, `perspective`, `contain: paint` або `will-change: transform` стає контейнувальним блоком для нащадків із `position: fixed`, тож вони позиціонуються й обрізаються відносно нього, а не вікна. Рендерте модальні вікна через портал у кінці `<body>` або використовуйте `<dialog>`, що потрапляє у верхній шар."}'::jsonb, null::jsonb),
  ('css-specificity', array['b']::text[], '{"en":"Specificities: `#nav a` = (1,0,1), `.menu .link` = (0,2,0), `a.link` = (0,1,1), `nav a` = (0,0,2). The id selector wins regardless of source order.","uk":"Специфічності: `#nav a` = (1,0,1), `.menu .link` = (0,2,0), `a.link` = (0,1,1), `nav a` = (0,0,2). Селектор з id перемагає незалежно від порядку в коді."}'::jsonb, null::jsonb),
  ('css-box-sizing', array['c']::text[], '{"en":"content-box: width covers only the content, so 200 + 2×20 padding + 2×2 border = 244px. With `border-box` it would be exactly 200px.","uk":"content-box: ширина охоплює лише вміст, тож 200 + 2×20 padding + 2×2 рамки = 244px. З `border-box` було б рівно 200px."}'::jsonb, null::jsonb),
  ('css-flex-vs-grid', array['a']::text[], '{"en":"Grid is two-dimensional: columns stay aligned across rows, and `auto-fill` + `minmax` creates as many columns as fit. Wrapped flex items size row by row, so the last row''s items stretch or misalign. Tables are for tabular data.","uk":"Grid двовимірний: колонки вирівнюються між рядками, а `auto-fill` + `minmax` створює стільки колонок, скільки вміщується. Flex-елементи з перенесенням розраховуються рядок за рядком, тож в останньому рядку вони розтягуються або зсуваються. Таблиці призначені для табличних даних."}'::jsonb, null::jsonb),
  ('css-stacking-context', array['a']::text[], '{"en":"z-index values are compared only within the same stacking context. If an ancestor with `transform`, `opacity < 1`, `filter` or a positioned z-index forms a context below the header, nothing inside can rise above it. Render modals in a portal at the end of `<body>`.","uk":"Значення z-index порівнюються лише в межах одного контексту накладання. Якщо предок із `transform`, `opacity < 1`, `filter` або позиціюванням із z-index утворює контекст нижче шапки, ніщо всередині не підніметься вище. Рендерте модальні вікна через портал у кінці `<body>`."}'::jsonb, null::jsonb),
  ('css-visually-hidden', array['c']::text[], '{"en":"`display: none` and `visibility: hidden` remove content from the accessibility tree too. The \"visually hidden\" pattern keeps it in the tree while taking no visible space. Zero-height tricks are unreliable across screen readers.","uk":"`display: none` і `visibility: hidden` прибирають вміст і з дерева доступності. Патерн «візуально прихований» залишає його в дереві, не займаючи видимого місця. Трюки з нульовою висотою ненадійні в різних зчитувачах."}'::jsonb, null::jsonb),
  ('css-dashboard-layout', null::text[], '{"en":"Flexbox handles the one-dimensional toolbar (`justify-content` on the main axis, `align-items` on the cross axis). Grid with `repeat(auto-fill, minmax(160px, 1fr))` makes responsive columns. An absolutely positioned badge needs a positioned ancestor (`position: relative` on the card). The visually-hidden pattern clips the label to 1px while keeping it in the accessibility tree.","uk":"Flexbox обробляє одновимірну панель (`justify-content` на головній осі, `align-items` на поперечній). Grid з `repeat(auto-fill, minmax(160px, 1fr))` дає адаптивні колонки. Абсолютно позиціонованому бейджу потрібен позиціонований предок (`position: relative` на картці). Патерн visually-hidden обрізає мітку до 1px, залишаючи її в дереві доступності."}'::jsonb, '{"/styles.css":"* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: system-ui, sans-serif;\n  background: #f7f5ef;\n}\n\n.toolbar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 16px;\n  background: #0b5a43;\n  color: white;\n}\n\n.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));\n  gap: 16px;\n  list-style: none;\n  margin: 0;\n  padding: 16px;\n}\n\n.card {\n  position: relative;\n  background: white;\n  border-radius: 12px;\n  padding: 16px;\n}\n\n.badge {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  background: #c9a227;\n  border-radius: 999px;\n  padding: 2px 8px;\n  font-size: 12px;\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n"}'::jsonb),
  ('d3-linear-scale', null::text[], '{"en":"A scale is just a linear function with its inputs and outputs swapped in meaning: `pixel = r0 + (value - d0) * (r1 - r0) / (d1 - d0)`, and `invert` is the same equation solved backwards, which is what makes mouse-to-value lookups work. Ticks need a \"nice\" step so people read round numbers: taking the raw step and rounding it up to 1, 2, 5 or 10 times a power of ten gives steps that always look sensible. The floating-point detail matters more than it looks: `k * 0.1` is not exact in binary, so the ticks are rounded with `toPrecision` before they reach the axis. Also notice that the tick loop only uses integers `k`, which keeps the values exact multiples of the step.","uk":"Шкала — це просто лінійна функція, у якій вхід і вихід міняються місцями: `піксель = r0 + (значення − d0) * (r1 − r0) / (d1 − d0)`, а `invert` — це те саме рівняння, розв''язане назад, через що працює пошук значення за позицією миші. Поділкам потрібен «гарний» крок, щоб люди бачили круглі числа: сирий крок, округлений вгору до 1, 2, 5 або 10 помножених на степінь десяти, завжди дає правдоподібні кроки. Деталь з плаваючою комою важливіша, ніж здається: `k * 0.1` не точно в двійковій системі, тож поділки округлюються через `toPrecision` до того, як потраплять на вісь. Також зверніть увагу, що цикл поділок використовує лише цілі `k`, тож значення є точними кратними кроку."}'::jsonb, '{"/src/scale.ts":"export type Scale = {\n  (value: number): number;\n  invert(pixel: number): number;\n  ticks(count?: number): number[];\n};\n\nexport function niceStep(min: number, max: number, count: number): number {\n  if (!(count >= 1)) throw new RangeError(\"count must be at least 1\");\n  const raw = Math.abs(max - min) / count;\n  const magnitude = 10 ** Math.floor(Math.log10(raw));\n  const normalized = raw / magnitude;\n  // Round the raw step up to the nearest 1, 2, 5 or 10 times a power of ten.\n  const factor = normalized <= 1 ? 1 : normalized <= 2 ? 2 : normalized <= 5 ? 5 : 10;\n  return factor * magnitude;\n}\n\nexport function linearScale(domain: [number, number], range: [number, number]): Scale {\n  const [d0, d1] = domain;\n  const [r0, r1] = range;\n  if (d0 === d1) throw new RangeError(\"Domain must not be empty\");\n\n  const scale = (value: number) => r0 + ((value - d0) * (r1 - r0)) / (d1 - d0);\n  const invert = (pixel: number) => d0 + ((pixel - r0) * (d1 - d0)) / (r1 - r0);\n  const ticks = (count = 5): number[] => {\n    const lo = Math.min(d0, d1);\n    const hi = Math.max(d0, d1);\n    const step = niceStep(lo, hi, count);\n    const out: number[] = [];\n    for (let k = Math.ceil(lo / step); k <= Math.floor(hi / step); k++) {\n      // toPrecision removes the floating-point noise of k * step (3 * 0.1 is 0.30000000000000004).\n      out.push(Number((k * step).toPrecision(12)));\n    }\n    return out;\n  };\n  return Object.assign(scale, { invert, ticks });\n}\n"}'::jsonb),
  ('ds-map-vs-object', array['a', 'b', 'c']::text[], '{"en":"`Map` accepts any key type, tracks `size`, keeps insertion order (objects reorder integer-like keys) and has no prototype keys to collide with. It is also optimised for frequent additions and deletions. But `JSON.stringify(new Map(...))` gives `{}`; convert with `Object.fromEntries(map)` first.","uk":"`Map` приймає ключі будь-якого типу, відстежує `size`, зберігає порядок вставки (об''єкти переставляють ключі, схожі на цілі числа) і не має ключів прототипу, з якими можна конфліктувати. Також він оптимізований для частих додавань і видалень. Але `JSON.stringify(new Map(...))` дає `{}`; спершу перетворіть через `Object.fromEntries(map)`."}'::jsonb, null::jsonb),
  ('ds-trie-autocomplete', array['c']::text[], '{"en":"A trie walks one node per typed character, so finding the prefix node costs O(prefix length), independent of the number of names, and everything below it is a match. A hash set only answers exact lookups, and a scan is O(n) per keystroke. A sorted array with binary search for the prefix range is a good, more memory-efficient alternative.","uk":"Префіксне дерево проходить по одному вузлу на кожен введений символ, тож пошук вузла префікса коштує O(довжина префікса) незалежно від кількості назв, а все під ним — збіги. Хеш-множина відповідає лише на точні запити, а перебір — O(n) на кожне натискання. Відсортований масив із бінарним пошуком діапазону префікса — хороша й економніша за пам''яттю альтернатива."}'::jsonb, null::jsonb),
  ('ds-union-find', array['b']::text[], '{"en":"Union-find stores a parent pointer per element. `find` follows pointers to the group''s root, and path compression flattens the path as it goes. With union by rank, both `union` and `find` cost amortised O(α(n)), effectively constant. BFS per query is O(V + E), and an adjacency matrix needs O(n²) memory.","uk":"Union-find зберігає вказівник на батька для кожного елемента. `find` іде вказівниками до кореня групи, а стиснення шляхів вирівнює шлях дорогою. З об''єднанням за рангом і `union`, і `find` коштують амортизовано O(α(n)), тобто фактично сталий час. BFS на кожен запит — O(V + E), а матриця суміжності потребує O(n²) пам''яті."}'::jsonb, null::jsonb),
  ('ds-min-heap', null::text[], '{"en":"In an array heap the children of index i are 2i+1 and 2i+2, and its parent is ⌊(i−1)/2⌋. `push` appends and sifts the item up while it is smaller than its parent. `pop` takes the root, moves the last item to the root and sifts it down towards the smaller child. Both touch one root-to-leaf path: O(log n). The starter''s `shift()` was O(n) and didn''t keep heap order at all.","uk":"У купі на масиві діти індексу i — це 2i+1 і 2i+2, а батько — ⌊(i−1)/2⌋. `push` додає в кінець і піднімає елемент, доки він менший за батька. `pop` бере корінь, переносить останній елемент у корінь і опускає його до меншої дитини. Обидві операції проходять один шлях від кореня до листка: O(log n). `shift()` у заготовці був O(n) і взагалі не підтримував порядок купи."}'::jsonb, '{"/src/priority-queue.ts":"export class PriorityQueue<T> {\n  private items: T[] = [];\n\n  constructor(private compare: (a: T, b: T) => number) {}\n\n  get size() {\n    return this.items.length;\n  }\n\n  peek(): T | undefined {\n    return this.items[0];\n  }\n\n  push(item: T) {\n    const items = this.items;\n    items.push(item);\n    let i = items.length - 1;\n    while (i > 0) {\n      const parent = (i - 1) >> 1;\n      if (this.compare(items[i], items[parent]) >= 0) break;\n      [items[i], items[parent]] = [items[parent], items[i]];\n      i = parent;\n    }\n  }\n\n  pop(): T | undefined {\n    const items = this.items;\n    if (items.length === 0) return undefined;\n    const top = items[0];\n    const last = items.pop()!;\n    if (items.length > 0) {\n      items[0] = last;\n      let i = 0;\n      for (;;) {\n        const left = 2 * i + 1;\n        const right = left + 1;\n        let smallest = i;\n        if (left < items.length && this.compare(items[left], items[smallest]) < 0) smallest = left;\n        if (right < items.length && this.compare(items[right], items[smallest]) < 0) smallest = right;\n        if (smallest === i) break;\n        [items[i], items[smallest]] = [items[smallest], items[i]];\n        i = smallest;\n      }\n    }\n    return top;\n  }\n}\n"}'::jsonb),
  ('ds-stack-brackets', array['b']::text[], '{"en":"The most recently opened bracket must close first, which is last-in, first-out. Push openers and pop on each closer, checking that it matches. The string is balanced if the stack ends empty.","uk":"Остання відкрита дужка має закритися першою, тобто «останнім прийшов, першим вийшов». Додавайте відкривальні дужки в стек і на кожній закривальній знімайте вершину, перевіряючи відповідність. Рядок збалансований, якщо стек у кінці порожній."}'::jsonb, null::jsonb),
  ('ds-queue-shift', array['a']::text[], '{"en":"Removing the first element moves every other element down one index. Keep a `head` index into the array (`queue[head++]`), or use a linked list or ring buffer for O(1) dequeues.","uk":"Видалення першого елемента зсуває всі інші на одну позицію. Тримайте індекс `head` у масиві (`queue[head++]`) або використайте зв''язний список чи кільцевий буфер для вилучення за O(1)."}'::jsonb, null::jsonb),
  ('ds-two-sum-map', array['a']::text[], '{"en":"For each `x`, check whether `target - x` is already in the Map (O(1) average). If not, store `x → index`. One pass gives O(n) time and O(n) space. Sorting plus two pointers is O(n log n) and loses the original indexes.","uk":"Для кожного `x` перевірте, чи є `target - x` у Map (у середньому O(1)). Якщо немає, збережіть `x → індекс`. Один прохід дає O(n) часу й O(n) пам''яті. Сортування з двома вказівниками коштує O(n log n) і втрачає початкові індекси."}'::jsonb, null::jsonb),
  ('ds-heap-topk', array['b']::text[], '{"en":"A min-heap of the current top 100 exposes the smallest of them at the root. Each new score is compared with the root and replaces it if larger, at O(log k) per item. Memory stays O(k).","uk":"Min-купа поточних топ-100 тримає найменшу з них у корені. Кожну нову оцінку порівнюють із коренем і замінюють його, якщо вона більша, за O(log k) на елемент. Пам''ять залишається O(k)."}'::jsonb, null::jsonb),
  ('ds-bst-degenerate', array['c']::text[], '{"en":"Every new value is larger than the last, so each node only has a right child: the tree degenerates into a linked list of height n. Self-balancing trees (AVL, red-black) keep the height O(log n).","uk":"Кожне нове значення більше за попереднє, тож у кожного вузла лише правий нащадок: дерево вироджується в зв''язний список висоти n. Самобалансовані дерева (AVL, червоно-чорні) тримають висоту O(log n)."}'::jsonb, null::jsonb),
  ('ds-lru-cache', null::text[], '{"en":"A Map iterates in insertion order. Deleting and re-inserting a key moves it to the end (most recent), and the first key is always the least recently used. Every operation is O(1). The classic language-agnostic version pairs a hash map with a doubly linked list.","uk":"Map ітерується в порядку вставки. Видалення й повторна вставка ключа переносить його в кінець (найсвіжіший), а перший ключ завжди найдавніше використаний. Кожна операція працює за O(1). Класична незалежна від мови версія поєднує хеш-таблицю з двозв''язним списком."}'::jsonb, '{"/src/lru.ts":"export class LRUCache<K, V> {\n  private map = new Map<K, V>();\n\n  constructor(private capacity: number) {}\n\n  get(key: K): V | undefined {\n    if (!this.map.has(key)) return undefined;\n    const value = this.map.get(key)!;\n    // Re-insert to move the key to the \"most recent\" end.\n    this.map.delete(key);\n    this.map.set(key, value);\n    return value;\n  }\n\n  set(key: K, value: V): void {\n    if (this.map.has(key)) this.map.delete(key);\n    this.map.set(key, value);\n    if (this.map.size > this.capacity) {\n      const oldest = this.map.keys().next().value as K;\n      this.map.delete(oldest);\n    }\n  }\n\n  get size(): number {\n    return this.map.size;\n  }\n}\n"}'::jsonb),
  ('date-month-overflow', array['a']::text[], '{"en":"Months in the `Date` constructor are zero-based, so `1` is February. February 2024 has 29 days, and `Date` doesn''t reject day 30: it **rolls over** to March 1. `getMonth()` is zero-based too, so March prints as `2`. Overflow is handy for arithmetic, but it means invalid input never fails loudly.","uk":"Місяці в конструкторі `Date` рахуються з нуля, тож `1` означає лютий. Лютий 2024 року має 29 днів, і `Date` не відхиляє 30-те число: воно **переноситься** на 1 березня. `getMonth()` теж рахує з нуля, тож березень виводиться як `2`. Переповнення зручне для арифметики, але через нього некоректні дані ніколи не дають гучної помилки."}'::jsonb, null::jsonb),
  ('date-days-in-month', array['a']::text[], '{"en":"`new Date(y, m + 1, 0)` asks for day 0 of the following month, which rolls back to the **last day of month `m`**. So `getDate()` is the length of the month: 29 for February 2024 (a leap year), 28 for February 2023 and 31 for December (month 12 rolls over into January of the next year, day 0 is December 31).","uk":"`new Date(y, m + 1, 0)` запитує нульовий день наступного місяця, що переноситься назад на **останній день місяця `m`**. Тож `getDate()` дає довжину місяця: 29 для лютого 2024 року (високосного), 28 для лютого 2023 і 31 для грудня (місяць 12 переноситься на січень наступного року, а нульовий день є 31 грудня)."}'::jsonb, null::jsonb),
  ('date-parse-date-only', array['a']::text[], '{"en":"ISO strings with only a date are parsed as **midnight UTC**, which is 19:00 on January 14 in New York, so `getDate()` is 14: the classic \"birthday shows a day early\" bug. A date-time string **without** an offset is parsed as **local** time, so it''s midnight in New York (05:00 UTC). Always include `Z` or an offset in timestamps, and treat calendar dates as plain `YYYY-MM-DD` strings.","uk":"Рядки ISO лише з датою розбираються як **північ за UTC**, а це 19:00 14 січня в Нью-Йорку, тож `getDate()` дає 14: класична помилка «день народження показується на день раніше». Рядок дата-час **без** зсуву розбирається як **локальний** час, тож це північ у Нью-Йорку (05:00 UTC). Завжди додавайте `Z` чи зсув до часових позначок, а календарні дати обробляйте як звичайні рядки `YYYY-MM-DD`."}'::jsonb, null::jsonb),
  ('date-dst-24h', array['a']::text[], '{"en":"March 31 in Kyiv is only 23 hours long. Adding 24 hours of milliseconds moves the **instant** forward 24 real hours, which lands at 13:00 local time. `setDate(getDate() + 1)` moves the **calendar day** and keeps the wall-clock time at 12:00, so the two dates are only 23 hours apart. Use calendar arithmetic for \"same time tomorrow\" and millisecond arithmetic for durations (\"in 24 hours\").","uk":"31 березня в Києві триває лише 23 години. Додавання 24 годин у мілісекундах зсуває **момент** на 24 реальні години вперед, і це дає 13:00 за місцевим часом. `setDate(getDate() + 1)` зсуває **календарний день** і зберігає настінний час 12:00, тож дві дати розділяють лише 23 години. Для «того самого часу завтра» використовуйте календарну арифметику, а для тривалостей («через 24 години») арифметику в мілісекундах."}'::jsonb, null::jsonb),
  ('date-invalid', array['a']::text[], '{"en":"Constructing a `Date` from an unparseable string doesn''t throw: you get a real `Date` object whose time value is `NaN`, which prints as `Invalid Date`. It only throws later, for example in `toISOString()` (`RangeError`). Validate with `Number.isNaN(d.getTime())` right after parsing user input.","uk":"Створення `Date` з рядка, який не вдається розібрати, не кидає помилку: ви отримуєте справжній об''єкт `Date` зі значенням часу `NaN`, що виводиться як `Invalid Date`. Помилку він кидає лише пізніше, наприклад у `toISOString()` (`RangeError`). Перевіряйте через `Number.isNaN(d.getTime())` одразу після розбору введення користувача."}'::jsonb, null::jsonb),
  ('date-compare', array['a']::text[], '{"en":"`===` compares object identity, so two `Date` objects for the same instant aren''t equal. Relational operators (`<=`, `>=`) and unary `+` convert dates to numbers via `valueOf`, so they compare the timestamps and work. Compare with `a.getTime() === b.getTime()` for equality, which states the intent clearly.","uk":"`===` порівнює ідентичність об''єктів, тож два об''єкти `Date` для того самого моменту не рівні. Оператори порівняння (`<=`, `>=`) і унарний `+` перетворюють дати на числа через `valueOf`, тож вони порівнюють часові позначки й працюють. Для рівності порівнюйте `a.getTime() === b.getTime()`, що чітко показує намір."}'::jsonb, null::jsonb),
  ('date-mutable', array['a']::text[], '{"en":"`setDate` mutates the `Date` in place, and the function returns the same object, so the \"start\" date moved too and both variables point to one object. Helpers should copy first (`const result = new Date(date)`) or use immutable APIs: date-fns returns new dates, and Temporal types can''t be mutated at all.","uk":"`setDate` змінює `Date` на місці, а функція повертає той самий об''єкт, тож дата «початку» теж зсунулася, і обидві змінні вказують на один об''єкт. Помічники мають спершу копіювати (`const result = new Date(date)`) або використовувати незмінні API: date-fns повертає нові дати, а типи Temporal узагалі не можна змінити."}'::jsonb, null::jsonb),
  ('date-intl-zones', array['a']::text[], '{"en":"A `Date` is one instant; `Intl.DateTimeFormat` with `timeZone` shows its wall-clock time anywhere, regardless of the machine''s own zone. In July, Kyiv is on summer time (UTC+3) and New York on EDT (UTC−4); India uses UTC+5:30 all year. Store the instant in UTC and convert only for display.","uk":"`Date` є одним моментом; `Intl.DateTimeFormat` з `timeZone` показує його настінний час будь-де, незалежно від власного поясу машини. У липні Київ живе за літнім часом (UTC+3), а Нью-Йорк за EDT (UTC−4); Індія використовує UTC+5:30 цілий рік. Зберігайте момент в UTC і перетворюйте лише для показу."}'::jsonb, null::jsonb),
  ('date-relative-time', array['a']::text[], '{"en":"`RelativeTimeFormat` turns a signed number and a unit into localised text, so you don''t hand-write plural rules or word order for every language. With `numeric: \"auto\"`, it uses words like \"yesterday\" and \"today\" where the language has them; the default `numeric: \"always\"` would say \"1 day ago\" and \"in 0 days\". Choosing the unit (minutes vs hours vs days) is still up to you.","uk":"`RelativeTimeFormat` перетворює число зі знаком і одиницю на локалізований текст, тож не треба вручну писати правила множини чи порядку слів для кожної мови. З `numeric: \"auto\"` він використовує слова на кшталт «вчора» й «сьогодні», де вони є в мові; типове `numeric: \"always\"` сказало б «1 day ago» і «in 0 days». Вибір одиниці (хвилини, години чи дні) все одно лишається за вами."}'::jsonb, null::jsonb),
  ('date-store-birthday', array['a']::text[], '{"en":"A birthday is the same calendar day everywhere; it isn''t a moment in time. Converting it to an instant ties it to some time zone''s midnight, so users in other zones see it shifted by a day (local midnight in Kyiv is still the previous day in UTC). Keep it as a date-only value end to end (`DATE` column, `\"YYYY-MM-DD\"` in JSON, `Temporal.PlainDate` in code).","uk":"День народження є тим самим календарним днем усюди; це не момент у часі. Перетворення на момент прив''язує його до півночі якогось часового поясу, тож користувачі в інших поясах бачать його зсунутим на день (локальна північ у Києві за UTC ще попередній день). Тримайте його значенням лише з датою від початку до кінця (стовпець `DATE`, `\"YYYY-MM-DD\"` у JSON, `Temporal.PlainDate` у коді)."}'::jsonb, null::jsonb),
  ('date-recurring-meeting', array['a']::text[], '{"en":"Kyiv switches between UTC+2 and UTC+3, so a fixed UTC time or a fixed offset puts the meeting at 10:00 or 08:00 for half the year. Future events defined in wall-clock time must keep the **zone name** and compute instants per occurrence (which also follows law changes to DST rules). Past events, like logs and payments, are instants and belong in UTC.","uk":"Київ перемикається між UTC+2 і UTC+3, тож фіксований час UTC чи фіксований зсув ставить зустріч на 10:00 чи 08:00 на пів року. Майбутні події, визначені настінним часом, мають зберігати **назву поясу** й обчислювати моменти для кожного повторення (так вони ще й враховують зміни законів про літній час). Минулі події, як-от журнали й платежі, є моментами й належать до UTC."}'::jsonb, null::jsonb),
  ('date-temporal', array['a', 'b']::text[], '{"en":"Temporal fixes `Date`''s design problems: values are immutable, months are 1-based, parsing is strict, and there are separate types for separate ideas: `Instant` (exact time), `PlainDate`/`PlainTime`/`PlainDateTime` (wall-clock values without a zone), `ZonedDateTime` (an instant plus an IANA time zone and calendar, so DST-aware arithmetic works) and `Duration`.","uk":"Temporal виправляє вади дизайну `Date`: значення незмінні, місяці рахуються з одиниці, розбір суворий, а для різних ідей є окремі типи: `Instant` (точний час), `PlainDate`/`PlainTime`/`PlainDateTime` (настінні значення без поясу), `ZonedDateTime` (момент плюс часовий пояс IANA і календар, тож арифметика враховує літній час) і `Duration`."}'::jsonb, null::jsonb),
  ('date-plain-dates', null::text[], '{"en":"The trick is to do all the arithmetic on UTC midnight, where every day is exactly 24 hours long and nothing depends on the runtime''s zone: `Date.UTC` plus the `getUTC*`/`setUTC*` methods, and `timeZone: \"UTC\"` when formatting. `Date`''s overflow does the hard work of crossing month and year boundaries, and a round-trip check turns that same overflow into validation. Month arithmetic counts months as `year * 12 + month` and clamps the day with the \"day 0 of the next month\" trick. `setUTCFullYear` avoids `Date.UTC`''s legacy mapping of years 0–99 to the 1900s.","uk":"Хитрість у тому, щоб виконувати всю арифметику над північчю UTC, де кожен день триває рівно 24 години й ніщо не залежить від поясу середовища: `Date.UTC` плюс методи `getUTC*`/`setUTC*` і `timeZone: \"UTC\"` під час форматування. Переповнення `Date` виконує важку роботу з переходом через межі місяців і років, а перевірка туди й назад перетворює те саме переповнення на валідацію. Арифметика місяців рахує місяці як `year * 12 + month` і обмежує день прийомом «нульовий день наступного місяця». `setUTCFullYear` уникає застарілого перетворення `Date.UTC` років 0–99 на 1900-ті."}'::jsonb, '{"/src/plain-date.ts":"export type PlainDate = { year: number; month: number; day: number };\n\n// Every calculation happens in UTC, so the runtime''s time zone and DST can never shift a day.\nconst toUTC = (d: PlainDate) => {\n  const date = new Date(Date.UTC(2000, d.month - 1, d.day));\n  date.setUTCFullYear(d.year); // Date.UTC maps years 0–99 to 1900–1999\n  return date;\n};\nconst fromUTC = (date: Date): PlainDate => ({\n  year: date.getUTCFullYear(),\n  month: date.getUTCMonth() + 1,\n  day: date.getUTCDate(),\n});\nconst DAY_MS = 24 * 60 * 60 * 1000;\n\nexport function parsePlainDate(text: string): PlainDate {\n  const match = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(text);\n  if (!match) throw new RangeError(\"Expected YYYY-MM-DD: \" + text);\n  const d = { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };\n  // Date silently rolls Feb 30 over to Mar 1, so check that nothing rolled over.\n  const roundTrip = fromUTC(toUTC(d));\n  if (roundTrip.year !== d.year || roundTrip.month !== d.month || roundTrip.day !== d.day) {\n    throw new RangeError(\"Not a real date: \" + text);\n  }\n  return d;\n}\n\nexport function toISODate(d: PlainDate): string {\n  return String(d.year).padStart(4, \"0\") + \"-\" + String(d.month).padStart(2, \"0\") + \"-\" + String(d.day).padStart(2, \"0\");\n}\n\nexport function addDays(d: PlainDate, days: number): PlainDate {\n  const date = toUTC(d);\n  date.setUTCDate(date.getUTCDate() + days); // overflow handles month and year changes\n  return fromUTC(date);\n}\n\nexport function addMonths(d: PlainDate, months: number): PlainDate {\n  const total = d.year * 12 + (d.month - 1) + months;\n  const year = Math.floor(total / 12);\n  const month = total - year * 12 + 1;\n  const lastDay = new Date(Date.UTC(2000, month, 0)); // day 0 of the next month\n  lastDay.setUTCFullYear(year, month, 0);\n  return { year, month, day: Math.min(d.day, lastDay.getUTCDate()) };\n}\n\nexport function daysBetween(a: PlainDate, b: PlainDate): number {\n  return Math.round((toUTC(b).getTime() - toUTC(a).getTime()) / DAY_MS);\n}\n\nexport function dayOfWeek(d: PlainDate): number {\n  return toUTC(d).getUTCDay() || 7; // getUTCDay: 0 = Sunday\n}\n\nexport function formatPlainDate(d: PlainDate, locale: string, options: Intl.DateTimeFormatOptions = { dateStyle: \"long\" }): string {\n  return new Intl.DateTimeFormat(locale, { ...options, timeZone: \"UTC\" }).format(toUTC(d));\n}\n"}'::jsonb),
  ('date-zones-relative', null::text[], '{"en":"`Intl.DateTimeFormat` knows every zone''s rules (it ships the IANA time zone database), so you never hard-code offsets: formatting the instant in the zone gives its wall-clock time, and the difference between that wall time read as UTC and the real instant is the offset. `hourCycle: \"h23\"` avoids `24` appearing for midnight. `formatInZone` is just a formatter with `timeZone`. For relative times, a table of units with thresholds keeps the logic declarative, and `RelativeTimeFormat` handles wording, plurals and words like \"yesterday\" in each language.","uk":"`Intl.DateTimeFormat` знає правила кожного поясу (він містить базу часових поясів IANA), тож зсуви ніколи не треба жорстко прописувати: форматування моменту в поясі дає його настінний час, а різниця між цим настінним часом, прочитаним як UTC, і справжнім моментом є зсувом. `hourCycle: \"h23\"` не дає з''явитися `24` для півночі. `formatInZone` є просто форматувальником із `timeZone`. Для відносного часу таблиця одиниць із порогами тримає логіку декларативною, а `RelativeTimeFormat` дбає про формулювання, множину й слова на кшталт «вчора» в кожній мові."}'::jsonb, '{"/src/zones.ts":"export function zoneOffsetMinutes(date: Date, timeZone: string): number {\n  // Format the instant as wall-clock time in the zone, read that wall time as if it were UTC,\n  // and the difference from the real instant is the zone''s offset at that moment.\n  const parts = new Intl.DateTimeFormat(\"en-US\", {\n    timeZone,\n    hourCycle: \"h23\",\n    year: \"numeric\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    second: \"2-digit\",\n  }).formatToParts(date);\n  const get = (type: string) => Number(parts.find((p) => p.type === type)!.value);\n  const wallAsUTC = Date.UTC(get(\"year\"), get(\"month\") - 1, get(\"day\"), get(\"hour\"), get(\"minute\"), get(\"second\"));\n  const instant = date.getTime() - date.getUTCMilliseconds();\n  return Math.round((wallAsUTC - instant) / 60_000);\n}\n\nexport function formatInZone(date: Date, timeZone: string, locale = \"en-GB\"): string {\n  return new Intl.DateTimeFormat(locale, { dateStyle: \"medium\", timeStyle: \"short\", timeZone }).format(date);\n}\n\nconst UNITS: Array<[Intl.RelativeTimeFormatUnit, number, number]> = [\n  // unit, seconds per unit, use this unit while |diff| is below this many seconds\n  [\"second\", 1, 45],\n  [\"minute\", 60, 45 * 60],\n  [\"hour\", 3600, 22 * 3600],\n  [\"day\", 86_400, 26 * 86_400],\n  [\"month\", 30 * 86_400, 320 * 86_400],\n  [\"year\", 365 * 86_400, Infinity],\n];\n\nexport function formatRelative(date: Date, now: Date = new Date(), locale = \"en\"): string {\n  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: \"auto\" });\n  const seconds = (date.getTime() - now.getTime()) / 1000;\n  if (Math.abs(seconds) < 45) return rtf.format(0, \"second\"); // \"now\"\n  const [unit, size] = UNITS.find(([, , limit]) => Math.abs(seconds) < limit)!;\n  return rtf.format(Math.round(seconds / size), unit);\n}\n"}'::jsonb),
  ('pattern-factory', array['a']::text[], '{"en":"A factory hides the decision of which concrete class to instantiate behind one function, so callers depend on the shared interface (`send`) instead of on every implementation. Adding a channel changes the factory, not the callers.","uk":"Фабрика ховає рішення, який конкретний клас створити, за однією функцією, тож викликачі залежать від спільного інтерфейсу (`send`), а не від кожної реалізації. Новий канал змінює фабрику, а не викликачів."}'::jsonb, null::jsonb),
  ('pattern-builder', array['a']::text[], '{"en":"Builder replaces long positional constructors with named, chainable steps (`.get(url).timeout(5000).retries(3).build()`) and validates once at the end. In JavaScript an options object often does the same job; a builder shines when construction is multi-step, conditional, or reused from a shared base (if each step returns a new builder).","uk":"Builder замінює довгі позиційні конструктори іменованими кроками, які можна з''єднувати в ланцюжок (`.get(url).timeout(5000).retries(3).build()`), і перевіряє все один раз наприкінці. У JavaScript часто те саме робить об''єкт параметрів; будівельник корисний, коли створення багатокрокове, умовне чи починається зі спільної основи (якщо кожен крок повертає новий будівельник)."}'::jsonb, null::jsonb),
  ('pattern-facade', array['a']::text[], '{"en":"A facade puts a simple interface in front of a complex subsystem. Callers don''t need to know the steps or their order, and the subsystem can change behind it. An adapter, by contrast, converts one existing interface into another expected one.","uk":"Фасад ставить простий інтерфейс перед складною підсистемою. Викликачам не треба знати кроки чи їхній порядок, а підсистема може змінюватися за ним. Адаптер натомість перетворює один наявний інтерфейс на інший, очікуваний."}'::jsonb, null::jsonb),
  ('pattern-iterator', array['a']::text[], '{"en":"Implementing `[Symbol.iterator]` (here as a generator method) makes `Range` work with spread, `for…of`, destructuring and `Array.from`: the Iterator pattern built into the language. Each spread calls `[Symbol.iterator]()` again and gets a fresh generator, so the range can be iterated any number of times.","uk":"Реалізація `[Symbol.iterator]` (тут як метод-генератор) робить `Range` сумісним зі spread, `for…of`, деструктуризацією й `Array.from`: це патерн Iterator, вбудований у мову. Кожен spread знову викликає `[Symbol.iterator]()` і отримує новий генератор, тож діапазон можна перебирати скільки завгодно разів."}'::jsonb, null::jsonb),
  ('pattern-state', array['a']::text[], '{"en":"When behaviour depends on a status, scattered conditionals make illegal transitions easy. Modelling states explicitly (a transition table like `paid: { SHIP: \"shipped\", REFUND: \"refunded\" }`, state objects, or a library such as XState) makes impossible transitions impossible and puts the rules where they can be read and tested in one place.","uk":"Коли поведінка залежить від статусу, розкидані умови роблять недопустимі переходи легкими. Явне моделювання станів (таблиця переходів на кшталт `paid: { SHIP: \"shipped\", REFUND: \"refunded\" }`, об''єкти станів або бібліотека як XState) робить неможливі переходи справді неможливими й збирає правила в одному місці, де їх легко читати й тестувати."}'::jsonb, null::jsonb),
  ('pattern-composite', array['a']::text[], '{"en":"Composite lets single objects (leaves) and groups of objects (composites) share one interface, so tree-shaped data is processed recursively without type checks. The DOM, React component trees, menus and file systems all follow it.","uk":"Composite дає одиночним об''єктам (листкам) і групам об''єктів (композитам) спільний інтерфейс, тож деревоподібні дані обробляються рекурсивно без перевірок типу. За ним побудовані DOM, дерева компонентів React, меню й файлові системи."}'::jsonb, null::jsonb),
  ('pattern-template-method', array['a']::text[], '{"en":"Template Method keeps the fixed order of steps in the base class and lets subclasses fill in the variable parts. It''s simple, but ties every format to an inheritance hierarchy. Strategy gets the same flexibility through composition: `exportWith({ header, rows, footer })` takes the steps as an object, so formats can be mixed and tested without subclasses.","uk":"Template Method тримає незмінний порядок кроків у базовому класі й дає підкласам заповнити змінні частини. Це просто, але прив''язує кожен формат до ієрархії успадкування. Strategy дає ту саму гнучкість через композицію: `exportWith({ header, rows, footer })` приймає кроки як об''єкт, тож формати можна комбінувати й тестувати без підкласів."}'::jsonb, null::jsonb),
  ('pattern-mediator', array['a']::text[], '{"en":"With N components wired to each other you get up to N² dependencies. A mediator (a parent component, a store, a form controller) centralises the interaction rules: components only know the mediator, so they stay reusable and the flow is readable in one place. \"Lift state up\" in React is the same idea.","uk":"Коли N компонентів пов''язані між собою, виникає до N² залежностей. Посередник (батьківський компонент, стор, контролер форми) зосереджує правила взаємодії: компоненти знають лише посередника, тож лишаються повторно використовуваними, а потік видно в одному місці. «Підняття стану» в React є тією самою ідеєю."}'::jsonb, null::jsonb),
  ('pattern-decorator-order', array['a']::text[], '{"en":"Each decorator wraps the function inside it. In `withLog(withDouble(square))` the logger is outermost, so it sees the original argument `3`; doubling happens inside, giving `36`. In `withDouble(withLog(square))` the doubling runs first, so the logger sees `6`. The result is the same here, but what each wrapper observes depends on the order, which matters for logging, caching and retries.","uk":"Кожен декоратор обгортає функцію всередині себе. У `withLog(withDouble(square))` логер найзовнішній, тож бачить початковий аргумент `3`; подвоєння відбувається всередині й дає `36`. У `withDouble(withLog(square))` спершу виконується подвоєння, тож логер бачить `6`. Результат тут однаковий, але те, що бачить кожна обгортка, залежить від порядку, і це важливо для логування, кешування й повторних спроб."}'::jsonb, null::jsonb),
  ('pattern-memento', array['a']::text[], '{"en":"A memento captures state without exposing internals, and restoring it is trivial. With immutable data and structural sharing (as in Redux or Immer) snapshots are cheaper than they sound, which is why Redux DevTools can time-travel. Commands store only the change, but each one must implement a perfect inverse, and a buggy `undo` corrupts the history.","uk":"Знімок фіксує стан, не відкриваючи внутрішню будову, а відновлення тривіальне. З незмінними даними й спільним використанням структури (як у Redux чи Immer) знімки дешевші, ніж здається, тому Redux DevTools і вміють «подорожувати в часі». Команди зберігають лише зміну, але кожна мусить мати бездоганну обернену дію, і помилковий `undo` псує історію."}'::jsonb, null::jsonb),
  ('pattern-async-singleton', array['a']::text[], '{"en":"Both calls check `instance` before either `await connect()` finishes, so both see `undefined` and both connect. Storing the **promise** synchronously on the first call (`dbPromise ??= connect()`; then `return dbPromise`) makes every concurrent caller share one in-flight connection. Clear it on failure if you want later calls to retry.","uk":"Обидва виклики перевіряють `instance`, перш ніж хоч один `await connect()` завершиться, тож обидва бачать `undefined` і обидва з''єднуються. Синхронне збереження **промісу** під час першого виклику (`dbPromise ??= connect()`; потім `return dbPromise`) змушує всіх одночасних викликачів ділити одне з''єднання в процесі. Скидайте його при помилці, якщо хочете, щоб пізніші виклики повторювали спробу."}'::jsonb, null::jsonb),
  ('pattern-state-machine', null::text[], '{"en":"All behaviour lives in data: the current state''s `on` table is the only place that decides what an event does, so illegal transitions simply don''t exist. Validating targets up front turns typos into immediate errors instead of a machine stuck in an unknown state. Running `exit` before `entry` and notifying subscribers after the state changes mirrors libraries like XState.","uk":"Уся поведінка живе в даних: таблиця `on` поточного стану є єдиним місцем, що вирішує, що робить подія, тож недопустимих переходів просто не існує. Перевірка цілей наперед перетворює описки на негайні помилки, а не на автомат, що застряг у невідомому стані. Виконання `exit` перед `entry` і сповіщення підписників після зміни стану відтворює поведінку бібліотек на кшталт XState."}'::jsonb, '{"/src/machine.ts":"export type StateConfig<S extends string, E extends string> = {\n  /** event → next state */\n  on?: Partial<Record<E, S>>;\n  entry?: () => void;\n  exit?: () => void;\n};\nexport type MachineConfig<S extends string, E extends string> = {\n  initial: S;\n  states: Record<S, StateConfig<S, E>>;\n};\nexport type Listener<S, E> = (state: S, event: E) => void;\n\nexport function createMachine<S extends string, E extends string>(config: MachineConfig<S, E>) {\n  const names = Object.keys(config.states) as S[];\n  if (!names.includes(config.initial)) throw new Error(\"Unknown initial state: \" + config.initial);\n  for (const name of names) {\n    for (const [event, target] of Object.entries(config.states[name].on ?? {})) {\n      if (!names.includes(target as S)) throw new Error(\"Unknown target \" + String(target) + \" for \" + name + \".\" + event);\n    }\n  }\n\n  let state = config.initial;\n  const listeners = new Set<Listener<S, E>>();\n  config.states[state].entry?.();\n\n  return {\n    get state() {\n      return state;\n    },\n    can(event: E): boolean {\n      return Boolean(config.states[state].on?.[event]);\n    },\n    send(event: E): S {\n      const target = config.states[state].on?.[event];\n      if (!target) return state; // events that aren''t valid here are ignored\n      config.states[state].exit?.();\n      state = target;\n      config.states[state].entry?.();\n      for (const listener of [...listeners]) listener(state, event);\n      return state;\n    },\n    subscribe(listener: Listener<S, E>): () => void {\n      listeners.add(listener);\n      return () => {\n        listeners.delete(listener);\n      };\n    },\n  };\n}\n"}'::jsonb),
  ('pattern-composite-tree', null::text[], '{"en":"Every `Folder` method delegates to its children through the shared `Node` interface, and recursion happens naturally because a child may itself be a folder. No `instanceof` checks are needed, so new node types (symlinks, archives) can be added without touching `Folder`. Passing the path prefix down while searching avoids storing parent pointers.","uk":"Кожен метод `Folder` делегує дітям через спільний інтерфейс `Node`, а рекурсія виникає природно, бо дитина сама може бути папкою. Перевірки `instanceof` не потрібні, тож нові типи вузлів (символьні посилання, архіви) можна додати, не чіпаючи `Folder`. Передавання префікса шляху вниз під час пошуку позбавляє потреби зберігати посилання на батьків."}'::jsonb, '{"/src/tree.ts":"export interface Node {\n  readonly name: string;\n  /** Total bytes. */\n  size(): number;\n  /** Number of files. */\n  count(): number;\n  /** Paths (\"root/src/a.ts\") of files matching the predicate. */\n  find(predicate: (file: File) => boolean, prefix?: string): string[];\n  /** Indented tree, two spaces per level. */\n  print(indent?: number): string;\n}\n\nexport class File implements Node {\n  constructor(readonly name: string, readonly bytes: number) {\n    if (!Number.isFinite(bytes) || bytes < 0) throw new RangeError(\"File size must be a non-negative number\");\n  }\n  size() {\n    return this.bytes;\n  }\n  count() {\n    return 1;\n  }\n  find(predicate: (file: File) => boolean, prefix = \"\"): string[] {\n    return predicate(this) ? [prefix + this.name] : [];\n  }\n  print(indent = 0) {\n    return \"  \".repeat(indent) + this.name + \" (\" + this.bytes + \" B)\";\n  }\n}\n\nexport class Folder implements Node {\n  private children: Node[] = [];\n\n  constructor(readonly name: string, children: Node[] = []) {\n    children.forEach((child) => this.add(child));\n  }\n\n  add(child: Node): this {\n    if (this.children.some((c) => c.name === child.name)) throw new Error(\"Duplicate name: \" + child.name);\n    this.children.push(child);\n    return this;\n  }\n\n  // A folder answers every question by asking its children, whether they are files or folders.\n  size() {\n    return this.children.reduce((sum, child) => sum + child.size(), 0);\n  }\n  count() {\n    return this.children.reduce((sum, child) => sum + child.count(), 0);\n  }\n  find(predicate: (file: File) => boolean, prefix = \"\"): string[] {\n    return this.children.flatMap((child) => child.find(predicate, prefix + this.name + \"/\"));\n  }\n  print(indent = 0) {\n    const line = \"  \".repeat(indent) + this.name + \"/ (\" + this.size() + \" B)\";\n    return [line, ...this.children.map((child) => child.print(indent + 1))].join(\"\\n\");\n  }\n}\n"}'::jsonb),
  ('pattern-request-builder', null::text[], '{"en":"Each step copies the state into a new builder (`with(patch)`), so a configured base like `api = create().header(\"Authorization\", …)` can safely branch into many requests. Normalising header names and encoding query values happen in one place, and `build()` is the single point where the whole combination is validated and turned into a plain object. A private constructor plus a static `create()` keeps callers from building half-initialised instances.","uk":"Кожен крок копіює стан у новий будівельник (`with(patch)`), тож налаштована основа на кшталт `api = create().header(\"Authorization\", …)` може безпечно розгалужуватися на багато запитів. Нормалізація назв заголовків і кодування параметрів запиту відбуваються в одному місці, а `build()` є єдиною точкою, де вся комбінація перевіряється й перетворюється на звичайний об''єкт. Приватний конструктор зі статичним `create()` не дає викликачам створювати напівініціалізовані екземпляри."}'::jsonb, '{"/src/request.ts":"export type Method = \"GET\" | \"POST\" | \"PUT\" | \"DELETE\";\nexport type RequestSpec = {\n  method: Method;\n  url: string;\n  headers: Record<string, string>;\n  body?: string;\n  timeout: number;\n};\n\ntype State = {\n  method?: Method;\n  url?: string;\n  headers: Record<string, string>;\n  query: [string, string][];\n  body?: unknown;\n  timeout: number;\n};\n\nexport class RequestBuilder {\n  private constructor(private readonly state: State) {}\n\n  static create(): RequestBuilder {\n    return new RequestBuilder({ headers: {}, query: [], timeout: 10000 });\n  }\n\n  /** Every step returns a new builder, so a configured base can be shared safely. */\n  private with(patch: Partial<State>): RequestBuilder {\n    return new RequestBuilder({ ...this.state, ...patch });\n  }\n\n  get(url: string) {\n    return this.with({ method: \"GET\", url, body: undefined });\n  }\n  post(url: string, body?: unknown) {\n    return this.with({ method: \"POST\", url, body });\n  }\n  put(url: string, body?: unknown) {\n    return this.with({ method: \"PUT\", url, body });\n  }\n  delete(url: string) {\n    return this.with({ method: \"DELETE\", url, body: undefined });\n  }\n  header(name: string, value: string) {\n    return this.with({ headers: { ...this.state.headers, [name.toLowerCase()]: value } });\n  }\n  query(name: string, value: string | number | boolean) {\n    return this.with({ query: [...this.state.query, [name, String(value)]] });\n  }\n  timeout(ms: number) {\n    if (!Number.isInteger(ms) || ms <= 0) throw new RangeError(\"timeout must be a positive integer\");\n    return this.with({ timeout: ms });\n  }\n\n  build(): RequestSpec {\n    const { method, url, headers, query, body, timeout } = this.state;\n    if (!method || !url) throw new Error(\"Call get(), post(), put() or delete() before build()\");\n    const qs = query.map(([k, v]) => encodeURIComponent(k) + \"=\" + encodeURIComponent(v)).join(\"&\");\n    const spec: RequestSpec = {\n      method,\n      url: qs ? url + (url.includes(\"?\") ? \"&\" : \"?\") + qs : url,\n      headers: { ...headers },\n      timeout,\n    };\n    if (body !== undefined) {\n      spec.body = JSON.stringify(body);\n      if (!spec.headers[\"content-type\"]) spec.headers[\"content-type\"] = \"application/json\";\n    }\n    return spec;\n  }\n}\n"}'::jsonb),
  ('pattern-observer', array['a']::text[], '{"en":"In the Observer pattern a subject keeps a list of subscribers and notifies them when something happens. Each of these APIs also returns or accepts a way to unsubscribe, which you need to call to avoid memory leaks.","uk":"У патерні Observer суб''єкт тримає список підписників і сповіщає їх, коли щось стається. Кожен із цих API також повертає або приймає спосіб відписатися, і його треба викликати, щоб уникнути витоків пам''яті."}'::jsonb, null::jsonb),
  ('pattern-module-singleton', array['a']::text[], '{"en":"ES modules are cached: the module body runs once and every import gets the same bindings, so this is a singleton without any ceremony. The cost is coupling: code that imports `api` directly can''t easily get a fake in tests, and state leaks between tests. Passing the client in (dependency injection) avoids both.","uk":"Модулі ES кешуються: тіло модуля виконується один раз, і кожен імпорт отримує ті самі прив''язки, тож це синглтон без жодних церемоній. Ціна в зв''язності: код, що імпортує `api` напряму, важко забезпечити фейком у тестах, а стан протікає між тестами. Передача клієнта ззовні (впровадження залежностей) усуває обидві проблеми."}'::jsonb, null::jsonb),
  ('pattern-strategy', array['a']::text[], '{"en":"Strategy puts interchangeable algorithms behind one interface and picks one at runtime. Adding a shipping method becomes adding an entry, not editing a branchy function (the open/closed principle).","uk":"Strategy ховає взаємозамінні алгоритми за одним інтерфейсом і обирає потрібний під час виконання. Новий спосіб доставки означає новий запис, а не редагування розгалуженої функції (принцип відкритості/закритості)."}'::jsonb, null::jsonb),
  ('pattern-decorator', array['a']::text[], '{"en":"A decorator wraps an object or function with the same interface and adds behaviour before or after delegating. Because every wrapper accepts and returns the same shape, they stack in any order and number. Inheritance fixes one combination per class, so three features would need up to seven subclasses. The original `fetchJson` stays untouched.","uk":"Декоратор обгортає об''єкт чи функцію з тим самим інтерфейсом і додає поведінку до або після делегування. Оскільки кожна обгортка приймає й повертає ту саму форму, їх можна складати в будь-якому порядку й кількості. Успадкування фіксує одну комбінацію на клас, тож трьом можливостям знадобилося б до семи підкласів. Початкова `fetchJson` лишається незмінною."}'::jsonb, null::jsonb),
  ('pattern-adapter-vs-facade', array['a']::text[], '{"en":"An adapter translates between two existing interfaces so callers don''t change. A facade has a different goal: it offers a simpler entry point to something complicated (many calls behind one), whether or not interfaces mismatch.","uk":"Адаптер перекладає між двома наявними інтерфейсами, щоб викликачі не змінювалися. Фасад має іншу мету: дає простішу точку входу до чогось складного (багато викликів за одним), незалежно від того, чи збігаються інтерфейси."}'::jsonb, null::jsonb),
  ('pattern-proxy-set-trap', array['a']::text[], '{"en":"A `Proxy` intercepts operations on the target. When the `set` trap returns `false`, the assignment fails: in sloppy mode silently, in strict mode (all modules and classes) with a `TypeError`. That''s how validation proxies and reactivity systems (Vue 3, MobX) hook into plain property writes.","uk":"`Proxy` перехоплює операції над цільовим об''єктом. Коли пастка `set` повертає `false`, присвоєння не вдається: у нестрогому режимі мовчки, у строгому (усі модулі й класи) з `TypeError`. Так проксі з валідацією і системи реактивності (Vue 3, MobX) втручаються у звичайний запис властивостей."}'::jsonb, null::jsonb),
  ('pattern-dependency-injection', array['a']::text[], '{"en":"When a class creates its own collaborators it''s welded to them. Dependency injection inverts that: the caller (or a DI container, as in Angular) provides them, so tests can pass a fake with canned responses, and production can swap implementations without editing the class.","uk":"Коли клас сам створює співпрацівників, він намертво з ними зв''язаний. Впровадження залежностей це перевертає: їх надає викликач (або DI-контейнер, як в Angular), тож тести можуть передати фейк із заготовленими відповідями, а продакшен може змінити реалізацію, не редагуючи клас."}'::jsonb, null::jsonb),
  ('pattern-observer-skip', array['a']::text[], '{"en":"Listener `a` removes itself with `splice` while `forEach` is at index 0, so `b` shifts into index 0 and `forEach` moves on to index 1, which is now `c`: `b` is skipped for the first event. Emitters should iterate over a copy (`[...this.listeners].forEach(...)`) so subscription changes take effect from the next emit.","uk":"Слухач `a` видаляє себе через `splice`, поки `forEach` на індексі 0, тож `b` зсувається на індекс 0, а `forEach` переходить до індексу 1, де тепер `c`: для першої події `b` пропущено. Емітери мають перебирати копію (`[...this.listeners].forEach(...)`), щоб зміни підписок діяли з наступного emit."}'::jsonb, null::jsonb),
  ('pattern-undo-redo', null::text[], '{"en":"Each command knows how to apply and reverse itself, so `History` only moves commands between two stacks. A new command invalidates the redo stack because those \"futures\" were built on a state that no longer exists. `deleteText` captures the removed text inside `execute`, so it works even if the document changed between creating and running the command.","uk":"Кожна команда знає, як застосувати й скасувати себе, тож `History` лише перекладає команди між двома стеками. Нова команда робить стек повтору недійсним, бо ті «майбутні» зміни будувалися на стані, якого вже немає. `deleteText` запам''ятовує видалений текст усередині `execute`, тож працює, навіть якщо документ змінився між створенням і виконанням команди."}'::jsonb, '{"/src/history.ts":"export interface Command {\n  label: string;\n  execute(): void;\n  undo(): void;\n}\n\nexport class History {\n  private done: Command[] = [];\n  private undone: Command[] = [];\n\n  constructor(private readonly limit = 100) {}\n\n  run(command: Command): void {\n    command.execute();\n    this.done.push(command);\n    if (this.done.length > this.limit) this.done.shift();\n    // A new action makes the old \"future\" meaningless.\n    this.undone = [];\n  }\n\n  undo(): boolean {\n    const command = this.done.pop();\n    if (!command) return false;\n    command.undo();\n    this.undone.push(command);\n    return true;\n  }\n\n  redo(): boolean {\n    const command = this.undone.pop();\n    if (!command) return false;\n    command.execute();\n    this.done.push(command);\n    return true;\n  }\n\n  get canUndo(): boolean {\n    return this.done.length > 0;\n  }\n\n  get canRedo(): boolean {\n    return this.undone.length > 0;\n  }\n\n  get labels(): string[] {\n    return this.done.map((c) => c.label);\n  }\n}\n\nexport class TextDoc {\n  constructor(public text = \"\") {}\n}\n\nexport function insertText(doc: TextDoc, index: number, value: string): Command {\n  return {\n    label: \"insert\",\n    execute: () => {\n      doc.text = doc.text.slice(0, index) + value + doc.text.slice(index);\n    },\n    undo: () => {\n      doc.text = doc.text.slice(0, index) + doc.text.slice(index + value.length);\n    },\n  };\n}\n\nexport function deleteText(doc: TextDoc, index: number, length: number): Command {\n  let removed = \"\";\n  return {\n    label: \"delete\",\n    execute: () => {\n      // Capture what is removed at execution time, not when the command is created.\n      removed = doc.text.slice(index, index + length);\n      doc.text = doc.text.slice(0, index) + doc.text.slice(index + length);\n    },\n    undo: () => {\n      doc.text = doc.text.slice(0, index) + removed + doc.text.slice(index);\n    },\n  };\n}\n"}'::jsonb),
  ('pattern-middleware-compose', null::text[], '{"en":"`dispatch(i)` runs middleware `i` and hands it `() => dispatch(i + 1)` as `next`, so the chain unrolls recursively and each `await next()` waits for everything downstream. Wrapping the call in `Promise.resolve` and `try/catch` normalises sync and async middlewares and their errors. Tracking the highest index already dispatched catches a middleware that calls `next()` twice.","uk":"`dispatch(i)` запускає middleware `i` і передає йому `() => dispatch(i + 1)` як `next`, тож ланцюжок розгортається рекурсивно, а кожен `await next()` чекає на все, що далі. Обгортка виклику в `Promise.resolve` і `try/catch` уніфікує синхронні й асинхронні middleware та їхні помилки. Відстеження найбільшого вже запущеного індексу ловить middleware, що викликає `next()` двічі."}'::jsonb, '{"/src/compose.ts":"export type Next = () => Promise<void>;\nexport type Middleware<C> = (ctx: C, next: Next) => Promise<void> | void;\n\nexport function compose<C>(middlewares: Middleware<C>[]): (ctx: C, last?: Next) => Promise<void> {\n  return (ctx, last) => {\n    let current = -1;\n\n    function dispatch(i: number): Promise<void> {\n      if (i <= current) return Promise.reject(new Error(\"next() called multiple times\"));\n      current = i;\n      if (i === middlewares.length) return last ? Promise.resolve().then(last) : Promise.resolve();\n      try {\n        // Promise.resolve handles sync middlewares; try/catch turns sync throws into rejections.\n        return Promise.resolve(middlewares[i](ctx, () => dispatch(i + 1)));\n      } catch (err) {\n        return Promise.reject(err);\n      }\n    }\n\n    return dispatch(0);\n  };\n}\n"}'::jsonb),
  ('dom-capture-order', array['b']::text[], '{"en":"An event travels down from the window to the target (capture phase), runs the target''s listeners, then travels back up (bubble phase). Listeners registered with `true` or `{ capture: true }` run on the way down, so the parent''s capture listener fires first even though it was added second.","uk":"Подія спускається від window до цілі (фаза перехоплення), виконує обробники цілі, а потім піднімається назад (фаза спливання). Обробники, зареєстровані з `true` або `{ capture: true }`, спрацьовують на шляху вниз, тож обробник перехоплення батька виконується першим, хоч доданий другим."}'::jsonb, null::jsonb),
  ('dom-focus-delegation', array['a', 'b']::text[], '{"en":"`focus` and `blur` don''t bubble, so a listener on an ancestor never sees them in the bubble phase. `focusin`/`focusout` are the bubbling equivalents, and a capture-phase listener sees every event on its way down to the target. Making the form focusable only lets the form itself take focus.","uk":"`focus` і `blur` не спливають, тож обробник на предку не бачить їх у фазі спливання. `focusin`/`focusout` — їхні аналоги, що спливають, а обробник у фазі перехоплення бачить кожну подію на шляху до цілі. Якщо зробити форму фокусованою, фокус зможе отримати лише сама форма."}'::jsonb, null::jsonb),
  ('dom-composed-events', array['b']::text[], '{"en":"`bubbles` lets an event travel up the tree, but `composed` decides whether it crosses the shadow boundary into the light DOM. Without it, propagation ends at the shadow root. Composed events are retargeted, so outside listeners see the host element as `event.target`, keeping the internals encapsulated.","uk":"`bubbles` дозволяє події підніматися деревом, а `composed` визначає, чи перетне вона межу тіньового дерева у світлий DOM. Без нього поширення закінчується на shadow root. Composed-події перенацілюються, тож зовнішні обробники бачать хост-елемент як `event.target`, а внутрішня будова лишається інкапсульованою."}'::jsonb, null::jsonb),
  ('dom-click-outside', null::text[], '{"en":"Listen on the document and use `element.contains(target)`, which is true for the element itself and every descendant. Registering `pointerdown` in the capture phase means a `stopPropagation()` elsewhere on the page can''t hide the click. The cleanup must pass the same function references (and the same `capture` flag) to `removeEventListener`.","uk":"Слухайте на document і використовуйте `element.contains(target)` — це true для самого елемента й усіх нащадків. Реєстрація `pointerdown` у фазі перехоплення означає, що `stopPropagation()` деінде на сторінці не приховає клік. Очищення має передати в `removeEventListener` ті самі посилання на функції (і той самий прапорець `capture`)."}'::jsonb, '{"/src/click-outside.ts":"export function onClickOutside(element: HTMLElement, handler: (event: Event) => void): () => void {\n  const onPointerDown = (event: Event) => {\n    if (!element.contains(event.target as Node)) handler(event);\n  };\n  const onKeyDown = (event: KeyboardEvent) => {\n    if (event.key === \"Escape\") handler(event);\n  };\n\n  document.addEventListener(\"pointerdown\", onPointerDown, true);\n  document.addEventListener(\"keydown\", onKeyDown);\n\n  return () => {\n    document.removeEventListener(\"pointerdown\", onPointerDown, true);\n    document.removeEventListener(\"keydown\", onKeyDown);\n  };\n}\n"}'::jsonb),
  ('dom-target-vs-current', array['c']::text[], '{"en":"`currentTarget` is the element whose listener is currently running (the `<ul>`). `target` is where the event originated, the `<span>`. Delegation uses `target.closest(...)` to find the item.","uk":"`currentTarget` є елементом, чий обробник зараз виконується (`<ul>`). `target` є місцем, звідки подія почалася, тобто `<span>`. Делегування використовує `target.closest(...)`, щоб знайти елемент."}'::jsonb, null::jsonb),
  ('dom-prevent-vs-stop', array['a']::text[], '{"en":"The two are independent: `preventDefault` cancels the browser''s default action (navigation for a submit), and `stopPropagation` prevents other listeners up the tree from receiving the event.","uk":"Це незалежні речі: `preventDefault` скасовує дію браузера за замовчуванням (для submit це навігація), а `stopPropagation` не дає іншим обробникам вище за деревом отримати подію."}'::jsonb, null::jsonb),
  ('dom-delegation-benefits', array['a', 'b']::text[], '{"en":"One listener on the container covers current and future children, which saves memory and setup work. It relies on bubbling, so non-bubbling events need their bubbling variants (`focusin`) or capture. XSS is unrelated.","uk":"Один обробник на контейнері охоплює поточних і майбутніх нащадків, що заощаджує пам''ять і роботу з налаштування. Він покладається на спливання, тож для подій, що не спливають, потрібні їхні спливні варіанти (`focusin`) або фаза занурення. До XSS це стосунку не має."}'::jsonb, null::jsonb),
  ('dom-textcontent-xss', array['a']::text[], '{"en":"`innerHTML` doesn''t execute `<script>` tags, but event-handler attributes like `onerror` do run. Insert untrusted text with `textContent`, or sanitise rich HTML (e.g. DOMPurify) and add a Content-Security-Policy.","uk":"`innerHTML` не виконує теги `<script>`, але атрибути-обробники на кшталт `onerror` спрацьовують. Вставляйте неперевірений текст через `textContent` або санітизуйте форматований HTML (наприклад, DOMPurify) і додайте Content-Security-Policy."}'::jsonb, null::jsonb),
  ('dom-layout-thrashing', array['a']::text[], '{"en":"Interleaving writes (`style.width = …`) and layout reads (`offsetWidth`) forces the browser to recalculate layout on every iteration. Batch the reads, then the writes (or use `requestAnimationFrame`) so the layout is computed once.","uk":"Чергування записів (`style.width = …`) і читань геометрії (`offsetWidth`) змушує браузер перераховувати розкладку на кожній ітерації. Згрупуйте спершу читання, потім записи (або використайте `requestAnimationFrame`), щоб розкладка обчислювалася один раз."}'::jsonb, null::jsonb),
  ('dom-event-delegation', null::text[], '{"en":"Listen once on the root and let events bubble up to it. `event.target.closest(selector)` finds the nearest matching ancestor, so clicks on inner icons count. `root.contains(match)` rejects matches that live above the root. Keep a reference to the listener so the returned function can remove it.","uk":"Слухайте один раз на корені й дозвольте подіям спливати до нього. `event.target.closest(selector)` знаходить найближчого предка, що відповідає селектору, тож кліки по внутрішніх іконках теж рахуються. `root.contains(match)` відкидає збіги, що лежать вище за корінь. Збережіть посилання на обробник, щоб повернена функція могла його зняти."}'::jsonb, '{"/src/delegate.js":"export function delegate(root, selector, type, handler) {\n  function listener(event) {\n    const start = event.target instanceof Element ? event.target : event.target.parentElement;\n    const match = start && start.closest(selector);\n    if (match && root.contains(match)) handler(event, match);\n  }\n  root.addEventListener(type, listener);\n  return () => root.removeEventListener(type, listener);\n}\n"}'::jsonb),
  ('react-use-transition', array['a']::text[], '{"en":"A transition tells React that a state update can be interrupted. Urgent updates (typing into the input) run first, and the expensive list render can be paused and resumed. `useDeferredValue` gives the same effect from the value''s side. Neither makes the render itself faster.","uk":"Перехід повідомляє React, що оновлення стану можна перервати. Термінові оновлення (набір у полі) виконуються першими, а дорогий рендер списку можна призупинити і відновити. `useDeferredValue` дає той самий ефект із боку значення. Жоден з них не прискорює сам рендер."}'::jsonb, null::jsonb),
  ('react-uncontrolled-forms', array['a']::text[], '{"en":"A controlled input stores its value in React state, so every keystroke is a state update and a render. Uncontrolled inputs keep the value in the DOM and read it when needed, which is cheaper for large forms. Controlled inputs remain the better choice when other UI must react to every change.","uk":"Керований елемент зберігає значення в стані React, тож кожне натискання — це оновлення стану і рендер. Некеровані поля тримають значення в DOM і читають його за потреби, що дешевше для великих форм. Керовані поля лишаються кращим вибором, коли інший інтерфейс має реагувати на кожну зміну."}'::jsonb, null::jsonb),
  ('css-logical-properties', array['a']::text[], '{"en":"Physical properties (left, right) describe fixed screen sides, which breaks in right-to-left layouts and vertical writing modes. Logical properties (inline-start, block-end) are relative to the writing mode, so one stylesheet serves every language.","uk":"Фізичні властивості (left, right) описують фіксовані сторони екрана, що ламається в макетах справа наліво і у вертикальних режимах письма. Логічні властивості (inline-start, block-end) відносні до режиму письма, тож одна таблиця стилів обслуговує всі мови."}'::jsonb, null::jsonb),
  ('css-media-print', array['a']::text[], '{"en":"Print styles are a media query like any other. A `@media print` block applies only when the page is printed or saved as PDF, so the same HTML serves both screen and paper without scripts or duplicate markup.","uk":"Стилі друку — це медіазапит, як і будь-який інший. Блок `@media print` застосовується лише тоді, коли сторінку друкують або зберігають як PDF, тож однакова HTML-розмітка працює і на екрані, і на папері без скриптів і дубльованої розмітки."}'::jsonb, null::jsonb),
  ('css-custom-properties', array['a']::text[], '{"en":"A preprocessor replaces `$brand` with its value while compiling, so the browser never sees a variable. A custom property is part of the live style tree: a dark theme can redefine `--brand` on one container, and `var(--brand, #333)` falls back when the property is missing.","uk":"Препроцесор замінює `$brand` на його значення під час компіляції, тож браузер ніколи не бачить змінної. Користувацька властивість є частиною живого дерева стилів: темна тема може перевизначити `--brand` на одному контейнері, а `var(--brand, #333)` використає запасне значення, коли властивості немає."}'::jsonb, null::jsonb),
  ('js-fetch-http-errors', array['a']::text[], '{"en":"A 404 is a valid HTTP response, so `fetch` resolves and leaves the decision to the caller. Forgetting to check `response.ok` (or `status`) is one of the most common bugs in front-end code, and an error thrown by `fetch` itself means the request never completed.","uk":"Статус 404 — це коректна HTTP-відповідь, тож `fetch` розв''язується і залишає рішення викликачеві. Забуття перевірити `response.ok` (або `status`) — одна з найпоширеніших помилок у фронтенд-коді, а помилка, кинута самим `fetch`, означає, що запит так і не завершився."}'::jsonb, null::jsonb),
  ('http-mime-nosniff', array['a']::text[], '{"en":"Browsers historically guessed types from content when the declared `Content-Type` looked wrong, which let an attacker''s text file run as JavaScript. The header tells the browser to trust the declared MIME type, and serving user uploads from a separate domain is the other standard defence.","uk":"Браузери історично вгадували типи за вмістом, якщо оголошений `Content-Type` здавався неправильним, і це дозволяло текстовому файлу зловмисника виконатися як JavaScript. Заголовок змушує браузер довіряти оголошеному MIME-типу, а віддавати завантаження користувачів з окремого домену — інший стандартний захист."}'::jsonb, null::jsonb),
  ('web-jsonp-obsolete', array['a']::text[], '{"en":"A script tag is allowed to load from any origin, which made JSONP work, but it also means the server controls executable code on your page. CORS lets the server declare which origins may read a response with ordinary `fetch`, without running anything it sends.","uk":"Тег script може завантажуватися з будь-якого походження, що й робило JSONP працездатним, але це означає, що сервер контролює виконуваний код на вашій сторінці. CORS дає серверу оголосити, які походження можуть читати відповідь через звичайний `fetch`, без виконання того, що він надсилає."}'::jsonb, null::jsonb),
  ('redux-flux-one-way', array['a']::text[], '{"en":"One direction makes state changes traceable: every change has an action that caused it, and the same actions replay to the same state. Two-way bindings are convenient, but they make it hard to say which part of the UI changed the data.","uk":"Один напрям робить зміни стану прослідковуваними: кожна зміна має дію, яка її спричинила, і ті самі дії відтворюють той самий стан. Двосторонні прив''язки зручні, але важко сказати, яка частина інтерфейсу змінила дані."}'::jsonb, null::jsonb),
  ('dp-two-properties', array['a']::text[], '{"en":"Optimal substructure means the best answer is built from best answers to subproblems; overlapping subproblems means a naive recursion solves the same subproblem again and again. DP stores each answer once. Without overlap (e.g. merge sort), plain divide and conquer is enough.","uk":"Оптимальна підструктура означає, що найкраща відповідь будується з найкращих відповідей для підзадач; перекриття означає, що наївна рекурсія знову й знову розв''язує ту саму підзадачу. DP зберігає кожну відповідь один раз. Без перекриття (наприклад, сортування злиттям) достатньо звичайного «розділяй і володарюй»."}'::jsonb, null::jsonb),
  ('dp-climb-stairs', array['a']::text[], '{"en":"The last move onto step `n` was either a 1-step from `n - 1` or a 2-step from `n - 2`, so `ways(n) = ways(n - 1) + ways(n - 2)` with `ways(0) = ways(1) = 1`. That gives 1, 1, 2, 3, 5, 8: the Fibonacci sequence, which a DP table computes in O(n).","uk":"Останній крок на сходинку `n` був або кроком на 1 з `n - 1`, або на 2 з `n - 2`, тож `ways(n) = ways(n - 1) + ways(n - 2)`, де `ways(0) = ways(1) = 1`. Виходить 1, 1, 2, 3, 5, 8: послідовність Фібоначчі, яку таблиця DP обчислює за O(n)."}'::jsonb, null::jsonb),
  ('dp-top-down-bottom-up', array['a']::text[], '{"en":"Both compute the same states and answers. Bottom-up iterates in dependency order, so there''s no call stack to overflow (deep recursion fails around ~10,000 frames in browsers) and you can often keep only the previous row. Top-down''s advantage is the reverse: it computes only the states actually needed, which helps when most of the table is irrelevant.","uk":"Обидва підходи обчислюють ті самі стани й відповіді. Підхід знизу вгору йде в порядку залежностей, тож немає стеку викликів, що може переповнитися (глибока рекурсія ламається десь на ~10 000 кадрах у браузерах), і часто можна тримати лише попередній рядок. Перевага згори вниз протилежна: обчислюються лише справді потрібні стани, що допомагає, коли більша частина таблиці не потрібна."}'::jsonb, null::jsonb),
  ('dp-greedy-coins', array['a']::text[], '{"en":"Taking the largest coin first (4) leaves 2, which needs two 1s: 3 coins. Two 3s make 6 with 2 coins. Greedy happens to be optimal for some coin systems (like US or euro coins) but not in general; DP over amounts (`dp[a] = min(dp[a - c] + 1)`) is always correct.","uk":"Якщо спершу взяти найбільшу монету (4), лишається 2, а це дві одиниці: 3 монети. Дві трійки дають 6 двома монетами. Жадібний підхід випадково оптимальний для деяких систем монет (як-от монети США чи євро), але не загалом; DP за сумами (`dp[a] = min(dp[a - c] + 1)`) завжди правильне."}'::jsonb, null::jsonb),
  ('dp-grid-paths', array['a']::text[], '{"en":"Each cell can be entered from the left or from above, so its count is the sum of those two; the first row and column have exactly one path. For a 3 × 3 grid that''s the binomial coefficient C(4, 2) = 6: choose which 2 of the 4 moves go down.","uk":"У кожну клітинку можна потрапити зліва або згори, тож її значення є сумою цих двох; перший рядок і стовпець мають рівно один шлях. Для сітки 3 × 3 це біноміальний коефіцієнт C(4, 2) = 6: оберіть, які 2 з 4 кроків ідуть вниз."}'::jsonb, null::jsonb),
  ('dp-space-optimisation', array['a']::text[], '{"en":"When state `i` depends only on state `i - 1`, older rows can be discarded. Here one array works: `row[c] += row[c - 1]` adds the value from the left (already updated for this row) to the value from above (still the old one). The same trick takes edit distance and knapsack from O(n·m) to O(m) memory.","uk":"Коли стан `i` залежить лише від стану `i - 1`, старіші рядки можна викинути. Тут достатньо одного масиву: `row[c] += row[c - 1]` додає значення зліва (уже оновлене для цього рядка) до значення згори (ще старе). Той самий прийом зменшує пам''ять для відстані редагування й рюкзака з O(n·m) до O(m)."}'::jsonb, null::jsonb),
  ('dp-memo-key-bug', array['a']::text[], '{"en":"Memoisation is only correct if the key identifies the subproblem completely. Keying by `r` alone means `paths(1, 1)` reuses the cached `paths(1, 2)`, and every later call with the same `r` returns a stale value. Use a key with every argument, e.g. `memo.get(r + \",\" + c)`, or a 2D table.","uk":"Мемоізація коректна, лише якщо ключ повністю визначає підзадачу. Ключ лише за `r` означає, що `paths(1, 1)` бере закешоване `paths(1, 2)`, а кожен наступний виклик із тим самим `r` повертає застаріле значення. Використовуйте ключ з усіма аргументами, наприклад `memo.get(r + \",\" + c)`, або двовимірну таблицю."}'::jsonb, null::jsonb),
  ('dp-knapsack', array['a']::text[], '{"en":"B + D (weight 5) and A + C (weight 5) both give 6, and nothing heavier fits. Greedy by value per weight takes B (1.33), then can''t fit C, then takes A: value 5. The DP `dp[w] = max(dp[w], dp[w - weight] + value)`, looping capacities downwards for each item, explores every combination in O(items × capacity).","uk":"B + D (вага 5) і A + C (вага 5) обидва дають 6, а важче нічого не влазить. Жадібний підхід за цінністю на одиницю ваги бере B (1,33), потім не вміщує C, потім бере A: цінність 5. DP `dp[w] = max(dp[w], dp[w - weight] + value)` з перебором місткостей згори вниз для кожного предмета перевіряє всі комбінації за O(предмети × місткість)."}'::jsonb, null::jsonb),
  ('dp-coin-loop-order', array['a']::text[], '{"en":"With coins in the outer loop, each coin is \"introduced\" once, so a multiset like {1, 1, 2} is counted once: {1,1,1,1}, {1,1,2}, {2,2} = 3 combinations. With amounts in the outer loop, every order counts separately (1+1+2, 1+2+1, 2+1+1, …), giving 5 sequences. Pick the loop order that matches whether order matters.","uk":"Коли монети в зовнішньому циклі, кожна монета «вводиться» один раз, тож мультимножина на кшталт {1, 1, 2} рахується один раз: {1,1,1,1}, {1,1,2}, {2,2} = 3 комбінації. Коли суми в зовнішньому циклі, кожен порядок рахується окремо (1+1+2, 1+2+1, 2+1+1, …), і виходить 5 послідовностей. Обирайте порядок циклів залежно від того, чи важливий порядок."}'::jsonb, null::jsonb),
  ('dp-edit-distance', array['a']::text[], '{"en":"kitten → sitten (replace k) → sittin (replace e) → sitting (insert g): 3. flaw → law (delete f) → lawn (insert n): 2; comparing position by position would wrongly give 4. The DP `dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + (a[i] ≠ b[j]))` finds this in O(n·m).","uk":"kitten → sitten (заміна k) → sittin (заміна e) → sitting (вставка g): 3. flaw → law (видалення f) → lawn (вставка n): 2; посимвольне порівняння за позиціями хибно дало б 4. DP `dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + (a[i] ≠ b[j]))` знаходить це за O(n·m)."}'::jsonb, null::jsonb),
  ('dp-coin-change', null::text[], '{"en":"`minCoins` fills `dp[a]` for every amount up to the target, trying each coin as the last one: O(amount × coins) time, O(amount) memory. `countWays` loops over coins on the outside so each combination is built in one canonical order and counted once. Both tables start from the base case `dp[0]` and only read smaller amounts, so a simple forward loop computes them in dependency order.","uk":"`minCoins` заповнює `dp[a]` для кожної суми до цільової, пробуючи кожну монету як останню: час O(сума × монети), пам''ять O(сума). `countWays` перебирає монети в зовнішньому циклі, тож кожна комбінація будується в одному канонічному порядку й рахується один раз. Обидві таблиці починаються з базового випадку `dp[0]` і читають лише менші суми, тож простий цикл уперед обчислює їх у порядку залежностей."}'::jsonb, '{"/src/coins.ts":"function check(amount: number) {\n  if (!Number.isInteger(amount) || amount < 0) throw new RangeError(\"amount must be a non-negative integer\");\n}\n\nexport function minCoins(coins: number[], amount: number): number {\n  check(amount);\n  // dp[a] = fewest coins for amount a\n  const dp = new Array<number>(amount + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let a = 1; a <= amount; a++) {\n    for (const coin of coins) {\n      if (coin <= a && dp[a - coin] + 1 < dp[a]) dp[a] = dp[a - coin] + 1;\n    }\n  }\n  return dp[amount] === Infinity ? -1 : dp[amount];\n}\n\nexport function countWays(coins: number[], amount: number): number {\n  check(amount);\n  // dp[a] = combinations for amount a. Coins in the outer loop, so each combination is counted once.\n  const dp = new Array<number>(amount + 1).fill(0);\n  dp[0] = 1;\n  for (const coin of coins) {\n    for (let a = coin; a <= amount; a++) dp[a] += dp[a - coin];\n  }\n  return dp[amount];\n}\n"}'::jsonb),
  ('dp-edit-distance-suggest', null::text[], '{"en":"`dp[i][j]` is the distance between the first `i` characters of `a` and the first `j` of `b`; each cell is the cheapest of deleting, inserting, or replacing (free when the characters match). Row `i` only reads row `i - 1`, so two arrays suffice, and swapping the strings keeps the row length at the shorter one: O(n·m) time, O(min(n, m)) memory. Comparing positions directly fails on any insertion, because everything after it shifts.","uk":"`dp[i][j]` є відстанню між першими `i` символами `a` і першими `j` символами `b`; кожна клітинка є найдешевшим із видалення, вставки чи заміни (безкоштовної, коли символи збігаються). Рядок `i` читає лише рядок `i - 1`, тож достатньо двох масивів, а обмін рядків місцями тримає довжину рядка таблиці за коротшим: час O(n·m), пам''ять O(min(n, m)). Порівняння за позиціями ламається на будь-якій вставці, бо все після неї зсувається."}'::jsonb, '{"/src/edit.ts":"export function editDistance(a: string, b: string): number {\n  if (a.length < b.length) [a, b] = [b, a]; // keep the row as short as possible\n  // prev[j] = distance between the first i-1 chars of a and the first j chars of b\n  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);\n  for (let i = 1; i <= a.length; i++) {\n    const curr = [i];\n    for (let j = 1; j <= b.length; j++) {\n      const replace = prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1);\n      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, replace); // delete, insert, replace/keep\n    }\n    prev = curr;\n  }\n  return prev[b.length];\n}\n\nexport function suggest(word: string, dictionary: string[], maxDistance = 2): string[] {\n  const target = word.toLowerCase();\n  return dictionary\n    .map((entry) => ({ entry, d: editDistance(target, entry.toLowerCase()) }))\n    .filter((x) => x.d <= maxDistance)\n    .sort((x, y) => x.d - y.d || x.entry.toLowerCase().localeCompare(y.entry.toLowerCase()))\n    .map((x) => x.entry);\n}\n"}'::jsonb),
  ('dv-many-to-many', array['b']::text[], '{"en":"A single lookup can point from many contacts to one account, but not from one contact to several. Both sides being \"many\" needs a many-to-many relationship, which Dataverse stores in an intersect table linking the two.","uk":"Один пошуковий стовпець може вказувати з багатьох контактів на один обліковий запис, але не з одного контакту на кілька. Коли обидві сторони — «багато», потрібен зв''язок багато-до-багатьох, який Dataverse зберігає в проміжній таблиці, що з''єднує їх."}'::jsonb, null::jsonb),
  ('dv-paging', array['a']::text[], '{"en":"Results above one page come with a link to the next page, which carries a token the server needs. Following links reads everything correctly even when rows change between requests, while offsets can skip or repeat rows.","uk":"Результати понад одну сторінку мають посилання на наступну сторінку з токеном, який потрібен серверу. Перехід за посиланнями читає все коректно навіть тоді, коли рядки змінюються між запитами, тоді як зсуви можуть пропустити або повторити рядки."}'::jsonb, null::jsonb),
  ('dv-privilege-depth', array['a']::text[], '{"en":"Security roles grant privileges with a depth, and depth decides which records a privilege covers: the user''s own records, the business unit, or the unit and its children. Field-level security hides columns rather than rows, and separate environments are a costly way to do what a role already does.","uk":"Ролі безпеки надають привілеї з глибиною, а глибина визначає, які записи покриває привілей: власні записи користувача, бізнес-підрозділ або підрозділ з дочірніми. Безпека на рівні полів приховує стовпці, а не рядки, а окремі середовища — дорогий спосіб зробити те, що вже робить роль."}'::jsonb, null::jsonb),
  ('dv-plugin-stage', array['a']::text[], '{"en":"A synchronous pre-operation plug-in runs inside the save''s transaction, so throwing an exception stops the change. An asynchronous plug-in runs after the save and can''t cancel it, and a business rule only runs in the form, not on the API.","uk":"Синхронний плагін до операції виконується всередині транзакції збереження, тож кидок виключення зупиняє зміну. Асинхронний плагін виконується після збереження і не може його скасувати, а бізнес-правило працює лише на формі, а не в API."}'::jsonb, null::jsonb),
  ('dv-odata-query-builder', null::text[], '{"en":"An OData query is text, so any user value that reaches it can change its meaning. Two rules close the gap. Values are always written as typed literals: strings are quoted and any inner quote is doubled, so the value can''t end the literal early. Column names, which can''t be escaped that way, are restricted to a pattern, because they are identifiers rather than data. The filter and order are URL-encoded as whole strings, so characters such as `&` or `#` inside a value can''t split the query. The same discipline applies to every API that builds queries from user input, not only Dataverse.","uk":"Запит OData — це текст, тож будь-яке значення користувача, що потрапляє в нього, може змінити його сенс. Два правила закривають цю щілину. Значення завжди записуються як типізовані літерали: рядки беруться в лапки, а внутрішні лапки подвоюються, тож значення не може достроково завершити літерал. Назви стовпців, які так не екрануються, обмежуються шаблоном, бо це ідентифікатори, а не дані. Фільтр і сортування кодуються в URL цілими рядками, тож символи на кшталт `&` чи `#` у значенні не можуть розбити запит. Та сама дисципліна потрібна для кожного API, що будує запити з вхідних даних користувача, а не лише для Dataverse."}'::jsonb, '{"/src/odata.ts":"export type Condition = {\n  field: string;\n  op: \"eq\" | \"ne\" | \"gt\" | \"ge\" | \"lt\" | \"le\" | \"contains\";\n  value: string | number | boolean | null;\n};\nexport type QueryOptions = {\n  select?: string[];\n  filter?: Condition[];\n  orderby?: Array<{ field: string; desc?: boolean }>;\n  top?: number;\n};\n\n// Logical names in Dataverse are lowercase letters, digits and underscores. Anything else would\n// let a value smuggle extra query syntax into the URL, so names are checked before use.\nconst NAME = /^[a-z][a-z0-9_]*$/;\nconst checkName = (name: string): string => {\n  if (!NAME.test(name)) throw new RangeError(\"Invalid column name: \" + name);\n  return name;\n};\n\n/** A string literal in OData: single quotes, with each inner quote doubled. */\nexport function escapeString(value: string): string {\n  return \"''\" + value.replace(/''/g, \"''''\") + \"''\";\n}\n\nfunction formatValue(op: string, value: Condition[\"value\"]): string {\n  if (value === null) {\n    if (op !== \"eq\" && op !== \"ne\") throw new TypeError(\"null can only be compared with eq or ne\");\n    return \"null\";\n  }\n  if (typeof value === \"string\") return escapeString(value);\n  if (typeof value === \"boolean\") return String(value);\n  if (!Number.isFinite(value)) throw new TypeError(\"Numbers must be finite\");\n  return String(value);\n}\n\nexport function buildFilter(conditions: Condition[]): string {\n  return conditions\n    .map((c) => {\n      const field = checkName(c.field);\n      if (c.op === \"contains\") {\n        if (typeof c.value !== \"string\") throw new TypeError(\"contains needs a string\");\n        return \"contains(\" + field + \",\" + escapeString(c.value) + \")\";\n      }\n      return field + \" \" + c.op + \" \" + formatValue(c.op, c.value);\n    })\n    .join(\" and \");\n}\n\nexport function buildUrl(baseUrl: string, entitySet: string, options: QueryOptions = {}): string {\n  const params: string[] = [];\n  if (options.select && options.select.length > 0) {\n    params.push(\"$select=\" + options.select.map(checkName).join(\",\"));\n  }\n  if (options.filter && options.filter.length > 0) {\n    params.push(\"$filter=\" + encodeURIComponent(buildFilter(options.filter)));\n  }\n  if (options.orderby && options.orderby.length > 0) {\n    const order = options.orderby.map((o) => checkName(o.field) + (o.desc ? \" desc\" : \" asc\")).join(\",\");\n    params.push(\"$orderby=\" + encodeURIComponent(order));\n  }\n  if (options.top !== undefined) {\n    if (!Number.isInteger(options.top) || options.top < 1) throw new RangeError(\"$top must be a positive integer\");\n    params.push(\"$top=\" + options.top);\n  }\n  const base = baseUrl.replace(/\\/+$/, \"\");\n  return base + \"/\" + checkName(entitySet) + (params.length > 0 ? \"?\" + params.join(\"&\") : \"\");\n}\n\nexport function nextLink(body: unknown): string | null {\n  if (typeof body !== \"object\" || body === null) return null;\n  const link = (body as Record<string, unknown>)[\"@odata.nextLink\"];\n  return typeof link === \"string\" ? link : null;\n}\n"}'::jsonb),
  ('err-json-parse', array['a']::text[], '{"en":"JSON requires double quotes, so single-quoted keys are invalid and `JSON.parse` throws a `SyntaxError`. Wrap parsing of untrusted input (API responses, `localStorage`, files) in `try/catch` and treat failures as expected input errors.","uk":"JSON вимагає подвійних лапок, тож ключі в одинарних лапках некоректні, і `JSON.parse` кидає `SyntaxError`. Загортайте розбір ненадійних даних (відповідей API, `localStorage`, файлів) у `try/catch` і обробляйте збої як очікувані помилки вхідних даних."}'::jsonb, null::jsonb),
  ('err-throw-string', array['a']::text[], '{"en":"JavaScript lets you throw any value, but a string has no `message` and, worse, no `stack`, so you lose where the problem happened. Handlers that read `err.message` break too. Always throw `Error` objects (or subclasses).","uk":"JavaScript дозволяє кинути будь-яке значення, але рядок не має `message` і, гірше, не має `stack`, тож ви втрачаєте місце виникнення проблеми. Обробники, що читають `err.message`, теж ламаються. Завжди кидайте об''єкти `Error` (чи підкласи)."}'::jsonb, null::jsonb),
  ('err-cause', array['a']::text[], '{"en":"The `cause` option (ES2022) attaches the original error to a new one without changing either message. You get a high-level message with context plus the low-level error, with its own type and stack, which DevTools and Node print as a chain. It''s better than concatenating messages or losing the original.","uk":"Параметр `cause` (ES2022) прикріплює початкову помилку до нової, не змінюючи жодного повідомлення. Ви отримуєте високорівневе повідомлення з контекстом і низькорівневу помилку з власним типом і стеком, які DevTools і Node виводять як ланцюжок. Це краще, ніж склеювати повідомлення чи втрачати оригінал."}'::jsonb, null::jsonb),
  ('err-finally-return', array['a']::text[], '{"en":"`finally` runs after the `try` block''s `return` value has been computed, and a `return` in `finally` replaces it. Linters flag this (`no-unsafe-finally`) because it silently changes results; keep `finally` for cleanup only.","uk":"`finally` виконується після того, як обчислено значення `return` з блоку `try`, а `return` у `finally` його замінює. Лінтери позначають це (`no-unsafe-finally`), бо воно непомітно змінює результати; використовуйте `finally` лише для очищення."}'::jsonb, null::jsonb),
  ('err-finally-swallows', array['a']::text[], '{"en":"A `return` in `finally` doesn''t just replace a return value: it also **discards an in-flight exception**. The error disappears without a trace, which makes bugs very hard to find. Never return (or `break`/`continue`) out of a `finally` block.","uk":"`return` у `finally` не лише замінює значення, що повертається: він ще й **відкидає виняток, що саме летить**. Помилка зникає без сліду, і через це помилки дуже важко знайти. Ніколи не виходьте з блоку `finally` через `return` (чи `break`/`continue`)."}'::jsonb, null::jsonb),
  ('err-return-before-finally', array['a']::text[], '{"en":"`return x` evaluates `x` (to `1`) before `finally` runs, so reassigning the variable afterwards doesn''t change the result. But `return o` returns a **reference**, and mutating the object in `finally` is visible to the caller.","uk":"`return x` обчислює `x` (у `1`) до виконання `finally`, тож повторне присвоєння змінній після того результат не змінює. Але `return o` повертає **посилання**, і зміна об''єкта у `finally` видима для того, хто викликав."}'::jsonb, null::jsonb),
  ('err-async-callback-escapes', array['a']::text[], '{"en":"`try/catch` only covers code that runs **while the `try` block is on the stack**. The callback runs later, from the event loop, when that `try` is long gone, so its exception is uncaught. Handle errors inside the callback, or wrap the async operation in a promise and `await` it inside `try`.","uk":"`try/catch` охоплює лише код, що виконується, **поки блок `try` є в стеку**. Колбек виконується пізніше з циклу подій, коли того `try` давно немає, тож його виняток неперехоплений. Обробляйте помилки всередині колбека або загорніть асинхронну операцію в проміс і чекайте на неї через `await` усередині `try`."}'::jsonb, null::jsonb),
  ('err-instanceof-order', array['a']::text[], '{"en":"A `ValidationError` **is also** an `Error`, so the first branch matches and the specific branch is never reached. Check the most specific types first (like `catch` clauses in Java or C#), or branch on a `code` field instead.","uk":"`ValidationError` **також є** `Error`, тож збігається перша гілка, а до конкретної справа не доходить. Перевіряйте спершу найконкретніші типи (як блоки `catch` у Java чи C#) або розгалужуйтеся за полем `code`."}'::jsonb, null::jsonb),
  ('err-all-keeps-running', array['a']::text[], '{"en":"`Promise.all` rejects as soon as one input rejects, but it can''t stop the other operations: they keep running, and their results (or failures) are ignored. If the remaining work has side effects or costs money, cancel it with an `AbortSignal`, or use `Promise.allSettled` when you need every outcome.","uk":"`Promise.all` відхиляється, щойно відхиляється один із вхідних промісів, але не може зупинити інші операції: вони продовжують виконуватися, а їхні результати (чи збої) ігноруються. Якщо решта роботи має побічні ефекти чи коштує грошей, скасуйте її через `AbortSignal` або використайте `Promise.allSettled`, коли потрібен кожен результат."}'::jsonb, null::jsonb),
  ('err-aggregate', array['a']::text[], '{"en":"`Promise.any` fulfils with the first success; if every input rejects, it rejects with an `AggregateError` whose `errors` array holds all the reasons, in input order. `AggregateError` is also useful in your own code when a batch operation has several independent failures.","uk":"`Promise.any` виконується з першим успіхом; якщо відхиляються всі вхідні проміси, він відхиляється з `AggregateError`, масив `errors` якої містить усі причини в порядку вхідних даних. `AggregateError` корисна і у власному коді, коли пакетна операція має кілька незалежних збоїв."}'::jsonb, null::jsonb),
  ('err-what-to-retry', array['a', 'b']::text[], '{"en":"Retry **transient** failures of **idempotent** operations: timeouts and `502`/`503`/`504` (respecting `Retry-After`), and `429` after the indicated delay. A `400` will fail the same way every time. A timed-out non-idempotent `POST` may have succeeded on the server, so retrying could charge the customer twice; retry it only with an idempotency key the server deduplicates on.","uk":"Повторюйте **тимчасові** збої **ідемпотентних** операцій: тайм-аути та `502`/`503`/`504` (з урахуванням `Retry-After`), а `429` після вказаної затримки. `400` щоразу падатиме однаково. Неідемпотентний `POST`, що завершився тайм-аутом, міг виконатися на сервері, тож повтор може списати гроші з клієнта двічі; повторюйте його лише з ключем ідемпотентності, за яким сервер прибирає дублікати."}'::jsonb, null::jsonb),
  ('err-swallowed', array['a']::text[], '{"en":"Catching just to log turns a clear failure (\"request for user 7 failed: 503\") into `Cannot read properties of undefined (reading ''name'')` somewhere else. Handle an error where you can actually do something about it; otherwise add context and rethrow, or return a result type (`{ ok: false, error }`) that forces callers to deal with the failure. Here `return await` is correct: it makes rejections land in this `catch`.","uk":"Перехоплення лише для журналювання перетворює зрозумілий збій («запит користувача 7 не вдався: 503») на `Cannot read properties of undefined (reading ''name'')` деінде. Обробляйте помилку там, де справді можете щось із нею зробити; інакше додайте контекст і киньте знову або поверніть тип результату (`{ ok: false, error }`), що змушує того, хто викликає, обробити збій. Тут `return await` правильний: через нього відхилення потрапляють у цей `catch`."}'::jsonb, null::jsonb),
  ('err-http-errors', null::text[], '{"en":"Subclasses only override field defaults, and `this.name = new.target.name` in the base constructor names every subclass correctly without repeating code. Passing `options` to `super` lets the built-in `Error` store `cause`. Walking the cause chain with a `Set` of visited errors handles cycles, and finding the first `AppError` lets handlers wrap domain errors with extra context without changing the HTTP status. The `expose` flag makes \"safe to show\" an explicit decision, so database messages, stack traces and secrets stay in the logs (with the `requestId` to find them).","uk":"Підкласи лише перевизначають значення полів за замовчуванням, а `this.name = new.target.name` у базовому конструкторі правильно називає кожен підклас без повторення коду. Передавання `options` у `super` дає вбудованому `Error` зберегти `cause`. Обхід ланцюжка причин із `Set` відвіданих помилок обробляє цикли, а пошук першої `AppError` дає обробникам загортати помилки предметної області з додатковим контекстом, не змінюючи HTTP-статус. Прапорець `expose` робить «безпечно показати» явним рішенням, тож повідомлення бази даних, стеки викликів і секрети лишаються в журналах (з `requestId`, щоб їх знайти)."}'::jsonb, '{"/src/errors.ts":"export type ErrorResponse = {\n  status: number;\n  body: { error: { code: string; message: string; requestId: string; fields?: Record<string, string> } };\n};\n\nexport class AppError extends Error {\n  status = 500;\n  code = \"INTERNAL\";\n  /** Whether the message is safe to show to clients. */\n  expose = false;\n  constructor(message: string, options?: { cause?: unknown }) {\n    super(message, options);\n    this.name = new.target.name; // \"NotFoundError\" etc. for every subclass\n  }\n}\n\nexport class ValidationError extends AppError {\n  status = 400;\n  code = \"VALIDATION\";\n  expose = true;\n  constructor(public fields: Record<string, string>, options?: { cause?: unknown }) {\n    super(\"Invalid input\", options);\n  }\n}\n\nexport class NotFoundError extends AppError {\n  status = 404;\n  code = \"NOT_FOUND\";\n  expose = true;\n  constructor(resource: string, id: string | number, options?: { cause?: unknown }) {\n    super(resource + \" \" + id + \" not found\", options);\n  }\n}\n\nfunction causes(err: unknown): unknown[] {\n  const chain: unknown[] = [];\n  const seen = new Set<unknown>();\n  let current = err;\n  while (current !== undefined && current !== null && !seen.has(current)) {\n    seen.add(current);\n    chain.push(current);\n    current = current instanceof Error ? current.cause : undefined;\n  }\n  return chain;\n}\n\nexport function errorChain(err: unknown): string[] {\n  return causes(err).map((e) => (e instanceof Error ? e.message : String(e)));\n}\n\nexport function toHttpResponse(err: unknown, requestId: string): ErrorResponse {\n  // A handler may wrap a domain error for context; the first AppError in the chain decides the response.\n  const appError = causes(err).find((e): e is AppError => e instanceof AppError);\n  if (!appError) {\n    return { status: 500, body: { error: { code: \"INTERNAL\", message: \"Something went wrong\", requestId } } };\n  }\n  const error: ErrorResponse[\"body\"][\"error\"] = {\n    code: appError.code,\n    message: appError.expose ? appError.message : \"Something went wrong\",\n    requestId,\n  };\n  if (appError instanceof ValidationError) error.fields = appError.fields;\n  return { status: appError.status, body: { error } };\n}\n"}'::jsonb),
  ('err-circuit-breaker', null::text[], '{"en":"Storing only `openedAt` and deriving `open` vs `half-open` from the clock keeps the state machine small and testable with an injected `now`. `call` captures the state once at the start, so the outcome of a trial call is attributed correctly even if time passes while it runs, and a `#trialRunning` flag released in `finally` guarantees a single probe. Errors are always rethrown: the breaker changes **when** you call the dependency, not what callers see. Failing fast gives the dependency time to recover and keeps your own threads, sockets and users from waiting on timeouts.","uk":"Зберігання лише `openedAt` і обчислення `open` чи `half-open` за годинником тримає скінченний автомат малим і придатним до тестування з підміненим `now`. `call` фіксує стан один раз на початку, тож результат пробного виклику правильно враховується, навіть якщо за час його виконання минає час, а прапорець `#trialRunning`, що знімається у `finally`, гарантує одну спробу. Помилки завжди кидаються далі: запобіжник змінює те, **коли** ви звертаєтеся до залежності, а не те, що бачить той, хто викликає. Швидка відмова дає залежності час відновитися й не змушує ваші потоки, сокети й користувачів чекати на тайм-аути."}'::jsonb, '{"/src/breaker.ts":"export class CircuitOpenError extends Error {\n  name = \"CircuitOpenError\";\n}\n\nexport type BreakerOptions = {\n  failureThreshold?: number;\n  resetMs?: number;\n  now?: () => number;\n  isFailure?: (error: unknown) => boolean;\n};\n\nexport class CircuitBreaker {\n  #failures = 0;\n  #openedAt: number | null = null;\n  #trialRunning = false;\n  #threshold: number;\n  #resetMs: number;\n  #now: () => number;\n  #isFailure: (error: unknown) => boolean;\n\n  constructor({ failureThreshold = 3, resetMs = 1000, now = () => Date.now(), isFailure = () => true }: BreakerOptions = {}) {\n    this.#threshold = failureThreshold;\n    this.#resetMs = resetMs;\n    this.#now = now;\n    this.#isFailure = isFailure;\n  }\n\n  get state(): \"closed\" | \"open\" | \"half-open\" {\n    if (this.#openedAt === null) return \"closed\";\n    return this.#now() - this.#openedAt >= this.#resetMs ? \"half-open\" : \"open\";\n  }\n\n  async call<T>(fn: () => Promise<T>): Promise<T> {\n    const state = this.state;\n    if (state === \"open\") throw new CircuitOpenError(\"Circuit is open\");\n    if (state === \"half-open\") {\n      if (this.#trialRunning) throw new CircuitOpenError(\"Circuit is half-open: a trial call is in progress\");\n      this.#trialRunning = true;\n    }\n    try {\n      const result = await fn();\n      this.#failures = 0;\n      this.#openedAt = null;\n      return result;\n    } catch (error) {\n      if (this.#isFailure(error)) {\n        this.#failures++;\n        if (state === \"half-open\" || this.#failures >= this.#threshold) this.#openedAt = this.#now();\n      } else if (state === \"half-open\") {\n        // The dependency answered (e.g. a 404): it''s healthy again.\n        this.#failures = 0;\n        this.#openedAt = null;\n      }\n      throw error;\n    } finally {\n      if (state === \"half-open\") this.#trialRunning = false;\n    }\n  }\n}\n"}'::jsonb),
  ('esm-named-default', array['b']::text[], '{"en":"A default export is imported without braces, under any name you choose. Named exports are imported inside braces with their exact names (or renamed with `as`). One statement can do both: `import sum, { PI } from ...`.","uk":"Типовий експорт імпортується без фігурних дужок під будь-яким ім''ям. Іменовані експорти імпортуються у фігурних дужках з точними іменами (або перейменовуються через `as`). Одна інструкція може робити обидва: `import sum, { PI } from ...`."}'::jsonb, null::jsonb),
  ('esm-top-level-await', array['b']::text[], '{"en":"A module with top-level `await` becomes asynchronous: modules that import it (directly or indirectly) wait for it to finish evaluating before they run. The thread isn''t blocked, and unrelated parts of the graph can still evaluate. Use it for real initialisation, because a slow await delays everything that depends on the module.","uk":"Модуль з `await` на верхньому рівні стає асинхронним: модулі, що його імпортують (прямо чи опосередковано), чекають завершення його виконання. Потік не блокується, і незалежні частини графа все одно можуть виконуватися. Використовуйте це для справжньої ініціалізації, бо повільний await затримує все, що залежить від модуля."}'::jsonb, null::jsonb),
  ('esm-cjs-interop', array['b']::text[], '{"en":"When ESM imports CommonJS, the default import is always `module.exports`. Named imports only exist for names that Node''s static analysis (cjs-module-lexer) can detect, such as `exports.parse = ...`. Exports built in a loop aren''t detectable, so linking fails with \"does not provide an export named ''parse''\". Use the default import and destructure it.","uk":"Коли ESM імпортує CommonJS, типовий імпорт — це завжди `module.exports`. Іменовані імпорти існують лише для імен, які може виявити статичний аналіз Node (cjs-module-lexer), наприклад `exports.parse = ...`. Експорти, створені в циклі, не виявляються, тож зв''язування падає з \"does not provide an export named ''parse''\". Використайте типовий імпорт і деструктуризуйте його."}'::jsonb, null::jsonb),
  ('esm-evaluation-order', null::text[], '{"en":"This is a depth-first post-order traversal. Marking a module as visited **before** walking its imports both deduplicates shared dependencies and breaks cycles: when `b` imports `a` while `a` is still loading, `a` is skipped, which is exactly why a circular import can see uninitialised bindings. `hasOwnProperty` avoids treating names like `toString` as modules.","uk":"Це обхід у глибину з post-order. Позначення модуля відвіданим **до** обходу його імпортів і прибирає дублі спільних залежностей, і розриває цикли: коли `b` імпортує `a`, поки `a` ще завантажується, `a` пропускається — саме тому циклічний імпорт може бачити неініціалізовані прив''язки. `hasOwnProperty` не дає сприйняти імена на кшталт `toString` як модулі."}'::jsonb, '{"/src/order.ts":"export type ModuleGraph = Record<string, string[]>;\n\nexport function evaluationOrder(graph: ModuleGraph, entry: string): string[] {\n  const order: string[] = [];\n  const visited = new Set<string>();\n\n  const visit = (name: string) => {\n    if (visited.has(name)) return; // already evaluated, or in progress (a cycle)\n    if (!Object.prototype.hasOwnProperty.call(graph, name)) {\n      throw new Error(\"Cannot find module ''\" + name + \"''\");\n    }\n    visited.add(name);\n    for (const dependency of graph[name]) visit(dependency);\n    order.push(name);\n  };\n\n  visit(entry);\n  return order;\n}\n"}'::jsonb),
  ('esm-live-binding', array['b']::text[], '{"en":"ES module imports are live, read-only bindings to the exporting module''s variables. After `inc()` runs, `count` in `main.js` reflects the new value, 1. CommonJS would have copied the value 0.","uk":"Імпорти ES-модулів є живими прив''язками лише для читання до змінних модуля, що експортує. Після `inc()` змінна `count` у `main.js` показує нове значення 1. CommonJS скопіював би значення 0."}'::jsonb, null::jsonb),
  ('esm-tree-shaking', array['a']::text[], '{"en":"`import`/`export` must be top-level with literal specifiers, so a bundler can build the dependency graph statically and drop unused exports. `require` can be called conditionally with computed paths, and `module.exports` can be mutated at runtime.","uk":"`import`/`export` мають бути на верхньому рівні з літеральними шляхами, тож збирач може статично побудувати граф залежностей і прибрати невикористані експорти. `require` можна викликати умовно з обчисленими шляхами, а `module.exports` змінювати під час виконання."}'::jsonb, null::jsonb),
  ('esm-evaluate-once', array['a']::text[], '{"en":"A module is evaluated once per module graph (realm), and every importer receives the same module instance. That''s why module-level state behaves like a singleton.","uk":"Модуль виконується один раз на граф модулів (realm), і кожен імпортер отримує той самий екземпляр. Тому стан на рівні модуля поводиться як синглтон."}'::jsonb, null::jsonb),
  ('esm-dynamic-import', array['a']::text[], '{"en":"`import()` returns a promise for the module namespace object (`{ default, ...named }`). Bundlers turn it into a separate chunk, so heavy features like editors or charts load only when needed.","uk":"`import()` повертає проміс об''єкта простору імен модуля (`{ default, ...named }`). Збирачі виносять його в окремий чанк, тож важкі функції, як-от редактори чи графіки, завантажуються лише за потреби."}'::jsonb, null::jsonb),
  ('esm-circular', array['b']::text[], '{"en":"Dependencies are evaluated before the importer, so `b.js` runs while `a.js` is still uninitialised. Reading a `let`/`const` export at that moment throws. Fix it by moving the shared value into a third module, or by only accessing it lazily inside functions.","uk":"Залежності виконуються раніше за імпортера, тож `b.js` працює, поки `a.js` ще не ініціалізовано. Читання експорту `let`/`const` у цей момент кидає помилку. Виправлення: винесіть спільне значення в третій модуль або звертайтеся до нього ліниво, лише всередині функцій."}'::jsonb, null::jsonb),
  ('evt-sync-dispatch', array['a']::text[], '{"en":"`emit` calls every listener **synchronously**, in the order they were added, before it returns. Events are a way to decouple code, not to make it asynchronous. If listeners do slow work, the emitter waits for them; schedule work explicitly (`queueMicrotask`, `setImmediate`) when you need it deferred.","uk":"`emit` викликає кожного слухача **синхронно** в порядку додавання, до свого повернення. Події є способом роз''єднати код, а не зробити його асинхронним. Якщо слухачі виконують повільну роботу, емітер чекає на них; плануйте роботу явно (`queueMicrotask`, `setImmediate`), коли її треба відкласти."}'::jsonb, null::jsonb),
  ('evt-remove-during-emit', array['a']::text[], '{"en":"`emit` iterates over a **copy** of the listener list taken when it starts, so removing `b` inside `a` doesn''t affect the emit already in progress: `b` still runs once. The removal takes effect from the next emit. Adding a listener during an emit works the same way: it isn''t called until the next one.","uk":"`emit` перебирає **копію** списку слухачів, зроблену на початку, тож видалення `b` усередині `a` не впливає на emit, що вже триває: `b` усе одно виконується один раз. Видалення діє з наступного emit. Додавання слухача під час emit працює так само: його не викличуть до наступного разу."}'::jsonb, null::jsonb),
  ('evt-once-off', array['a']::text[], '{"en":"`once` registers a wrapper that removes itself before calling your function, but the emitter remembers the original, so `off(event, fn)` with the function you passed still finds and removes it. Custom emitters often get this wrong by storing only the wrapper, which leaves no way to cancel a pending `once`.","uk":"`once` реєструє обгортку, що видаляє себе перед викликом вашої функції, але емітер пам''ятає оригінал, тож `off(event, fn)` з переданою функцією все одно знаходить і видаляє її. Власні емітери часто роблять це неправильно, зберігаючи лише обгортку, і тоді скасувати `once`, що очікує, неможливо."}'::jsonb, null::jsonb),
  ('evt-error-event', array['a']::text[], '{"en":"Emitting an event nobody listens to just returns `false`, except for `\"error\"`: with no `\"error\"` listener, `emit` **throws** the error. In a stream or socket that throw happens asynchronously, outside any `try/catch`, and crashes the process. Always attach an `\"error\"` handler to streams, sockets, child processes and other emitters.","uk":"Випромінення події, яку ніхто не слухає, просто повертає `false`, крім `\"error\"`: без слухача `\"error\"` `emit` **кидає** помилку. У потоці чи сокеті це стається асинхронно, поза будь-яким `try/catch`, і аварійно завершує процес. Завжди додавайте обробник `\"error\"` потокам, сокетам, дочірнім процесам та іншим емітерам."}'::jsonb, null::jsonb),
  ('evt-listener-throws', array['a']::text[], '{"en":"Because dispatch is synchronous, an exception in one listener propagates straight out of `emit` to its caller, and the listeners after it **never run**. One subscriber can break all the others. If listeners are independent, wrap each one in `try/catch` (or have the emitter do it). The DOM''s `EventTarget` behaves differently: it reports the error and keeps calling the other listeners.","uk":"Оскільки доставка синхронна, виняток в одному слухачі виходить прямо з `emit` до того, хто його викликав, а слухачі після нього **ніколи не виконуються**. Один підписник може зламати всіх інших. Якщо слухачі незалежні, загорніть кожного в `try/catch` (або доручіть це емітеру). `EventTarget` у DOM поводиться інакше: він повідомляє про помилку й продовжує викликати інших слухачів."}'::jsonb, null::jsonb),
  ('evt-duplicates', array['a']::text[], '{"en":"`EventEmitter` keeps a plain list, so the same function added twice is called twice. `EventTarget` ignores a second `addEventListener` with the same type, function and capture flag. Knowing which semantics you have matters when components subscribe in a render or effect that runs more than once.","uk":"`EventEmitter` тримає звичайний список, тож та сама функція, додана двічі, викликається двічі. `EventTarget` ігнорує повторний `addEventListener` з тим самим типом, функцією й прапорцем capture. Знати, яка семантика у вас, важливо, коли компоненти підписуються в рендері чи ефекті, що виконується не раз."}'::jsonb, null::jsonb),
  ('evt-custom-event', array['a']::text[], '{"en":"`EventTarget` delivers `Event` objects, and `CustomEvent` is the standard way to attach data, in its `detail` property. Any class can extend `EventTarget` to become an event source, in browsers and in Node, without a library. Custom events on DOM elements can also bubble if you pass `bubbles: true`.","uk":"`EventTarget` доставляє об''єкти `Event`, а `CustomEvent` є стандартним способом додати дані у властивості `detail`. Будь-який клас може розширити `EventTarget` і стати джерелом подій, у браузерах і в Node, без бібліотек. Власні події на елементах DOM також можуть спливати, якщо передати `bubbles: true`."}'::jsonb, null::jsonb),
  ('evt-events-once', array['a']::text[], '{"en":"`events.once(emitter, name)` returns a promise that resolves with an **array** of the event''s arguments (since events can carry several), and removes its listener afterwards. It also rejects if the emitter emits `\"error\"` first, and accepts `{ signal }` for cancellation. It''s the idiomatic way to wait for `\"ready\"`, `\"listening\"` or `\"close\"` with `await`.","uk":"`events.once(emitter, name)` повертає проміс, що розв''язується **масивом** аргументів події (бо подія може нести кілька) і потім видаляє свого слухача. Він також відхиляється, якщо емітер спершу випромінює `\"error\"`, і приймає `{ signal }` для скасування. Це ідіоматичний спосіб чекати на `\"ready\"`, `\"listening\"` чи `\"close\"` через `await`."}'::jsonb, null::jsonb),
  ('evt-max-listeners', array['a']::text[], '{"en":"The default limit of 10 listeners per event is a heuristic leak detector: the 11th listener is still added, but Node warns, because the usual cause is subscribing in a loop or per operation and never unsubscribing. Each forgotten listener keeps its closure (and whatever it captured) alive. Fix the subscription lifecycle; only raise the limit with `setMaxListeners` when many listeners are genuinely intended.","uk":"Типове обмеження в 10 слухачів на подію є евристичним детектором витоків: 11-й слухач усе одно додається, але Node попереджає, бо зазвичай причина в підписці в циклі чи на кожну операцію без відписки. Кожен забутий слухач тримає живим своє замикання (і все, що воно захопило). Виправте життєвий цикл підписки; підвищуйте обмеження через `setMaxListeners`, лише коли багато слухачів справді задумано."}'::jsonb, null::jsonb),
  ('evt-global-bus', array['a']::text[], '{"en":"Pub/sub decouples senders from receivers, which is great at true boundaries (plugins, cross-cutting concerns like analytics). Used for core data flow, it makes behaviour hard to trace: there''s no call graph, listeners depend on emit order, a misspelled event name never fires, and nobody unsubscribes. Typed event maps help; for shared state, a store with explicit actions or direct calls is usually clearer.","uk":"Pub/sub роз''єднує відправників і отримувачів, і це чудово на справжніх межах (плагіни, наскрізні задачі на кшталт аналітики). Для основного потоку даних воно ускладнює відстеження поведінки: графа викликів немає, слухачі залежать від порядку emit, подія з одруком у назві ніколи не спрацьовує, а відписуватися ніхто не відписується. Типізовані мапи подій допомагають; для спільного стану сховище з явними діями чи прямі виклики зазвичай зрозуміліші."}'::jsonb, null::jsonb),
  ('evt-node-emitter', null::text[], '{"en":"Storing each event''s listeners in an array that''s **replaced, never mutated** (copy-on-write) gives snapshot semantics for free: `emit` iterates the array it read at the start, while `on`/`off` install new arrays. Each entry keeps the original function plus a `once` flag instead of a wrapper function, so `off(original)` and `listeners()` behave like Node, and removing the specific entry before calling it makes `once` safe against re-entrant emits. The `\"error\"` rule and the one-time leak warning are small checks with large practical value in Node services.","uk":"Зберігання слухачів кожної події в масиві, що **замінюється, а не змінюється** (copy-on-write), безкоштовно дає семантику знімка: `emit` перебирає масив, прочитаний на початку, а `on`/`off` встановлюють нові масиви. Кожен запис зберігає початкову функцію й прапорець `once` замість функції-обгортки, тож `off(original)` і `listeners()` поводяться як у Node, а видалення конкретного запису перед викликом робить `once` безпечним щодо повторних вкладених emit. Правило `\"error\"` і одноразове попередження про витік є невеликими перевірками з великою практичною цінністю в сервісах на Node."}'::jsonb, '{"/src/emitter.ts":"type Listener = (...args: any[]) => void;\ntype Entry = { listener: Listener; once: boolean };\ntype EventName = string | symbol;\n\nexport class Emitter {\n  // Lists are replaced, never mutated (copy-on-write), so an emit in progress keeps iterating its own snapshot.\n  #events = new Map<EventName, Entry[]>();\n  #maxListeners = 10;\n  #warned = new Set<EventName>();\n  #onWarning: (message: string) => void;\n\n  constructor({ onWarning = (message: string) => console.warn(message) }: { onWarning?: (message: string) => void } = {}) {\n    this.#onWarning = onWarning;\n  }\n\n  #add(event: EventName, listener: Listener, once: boolean, prepend: boolean): this {\n    if (typeof listener !== \"function\") throw new TypeError(\"The listener must be a function\");\n    const list = this.#events.get(event) ?? [];\n    const entry = { listener, once };\n    const next = prepend ? [entry, ...list] : [...list, entry];\n    this.#events.set(event, next);\n    if (this.#maxListeners > 0 && next.length > this.#maxListeners && !this.#warned.has(event)) {\n      this.#warned.add(event);\n      this.#onWarning(\"Possible memory leak: \" + next.length + \" \" + String(event) + \" listeners added. Use setMaxListeners() to raise the limit.\");\n    }\n    return this;\n  }\n\n  #remove(event: EventName, match: (entry: Entry) => boolean): boolean {\n    const list = this.#events.get(event);\n    if (!list) return false;\n    // Node removes the most recently added matching listener.\n    for (let i = list.length - 1; i >= 0; i--) {\n      if (match(list[i])) {\n        const next = [...list.slice(0, i), ...list.slice(i + 1)];\n        if (next.length > 0) this.#events.set(event, next);\n        else this.#events.delete(event);\n        return true;\n      }\n    }\n    return false;\n  }\n\n  on(event: EventName, listener: Listener): this {\n    return this.#add(event, listener, false, false);\n  }\n  addListener(event: EventName, listener: Listener): this {\n    return this.on(event, listener);\n  }\n  prependListener(event: EventName, listener: Listener): this {\n    return this.#add(event, listener, false, true);\n  }\n  once(event: EventName, listener: Listener): this {\n    return this.#add(event, listener, true, false);\n  }\n  off(event: EventName, listener: Listener): this {\n    this.#remove(event, (entry) => entry.listener === listener);\n    return this;\n  }\n  removeListener(event: EventName, listener: Listener): this {\n    return this.off(event, listener);\n  }\n  removeAllListeners(event?: EventName): this {\n    if (event === undefined) this.#events.clear();\n    else this.#events.delete(event);\n    return this;\n  }\n\n  emit(event: EventName, ...args: unknown[]): boolean {\n    const list = this.#events.get(event);\n    if (!list) {\n      if (event === \"error\") {\n        const error = args[0];\n        throw error instanceof Error ? error : new Error(\"Unhandled error: \" + String(error));\n      }\n      return false;\n    }\n    for (const entry of list) {\n      // once listeners are removed before they run, so a nested emit can''t call them again.\n      if (entry.once) this.#remove(event, (e) => e === entry);\n      entry.listener.apply(this, args);\n    }\n    return true;\n  }\n\n  listenerCount(event: EventName): number {\n    return this.#events.get(event)?.length ?? 0;\n  }\n  listeners(event: EventName): Listener[] {\n    return (this.#events.get(event) ?? []).map((entry) => entry.listener);\n  }\n  eventNames(): EventName[] {\n    return [...this.#events.keys()];\n  }\n  setMaxListeners(n: number): this {\n    this.#maxListeners = n;\n    return this;\n  }\n}\n"}'::jsonb),
  ('evt-wait-for', null::text[], '{"en":"A promise can only settle once, but the listeners, the error listener, the timer and the abort listener all keep running unless you remove them, so the heart of the solution is a single `cleanup` that every exit path calls before settling. Without it, each call leaks listeners (exactly what the max-listeners warning catches) and stray timers. Detecting the source type by its API (`on` vs `addEventListener`) lets one helper serve Node emitters, DOM elements, `WebSocket`s and `AbortSignal`s alike.","uk":"Проміс може завершитися лише один раз, але слухачі, слухач помилок, таймер і слухач скасування продовжують працювати, якщо їх не видалити, тож серцем розв''язку є одна функція `cleanup`, яку кожен шлях виходу викликає перед завершенням. Без неї кожен виклик спричиняє витік слухачів (саме це ловить попередження про кількість слухачів) і залишає зайві таймери. Визначення типу джерела за його API (`on` проти `addEventListener`) дає одному помічнику обслуговувати емітери Node, елементи DOM, `WebSocket` і `AbortSignal`."}'::jsonb, '{"/src/wait-for.ts":"export type WaitOptions<A extends unknown[]> = {\n  signal?: AbortSignal;\n  timeout?: number;\n  filter?: (...args: A) => boolean;\n};\n\ntype EmitterLike = { on(event: string, fn: (...args: any[]) => void): unknown; off(event: string, fn: (...args: any[]) => void): unknown };\n\nexport function waitFor(target: EmitterLike | EventTarget, event: string, { signal, timeout, filter }: WaitOptions<any[]> = {}): Promise<any> {\n  return new Promise((resolve, reject) => {\n    if (signal?.aborted) {\n      reject(signal.reason);\n      return;\n    }\n    const isEmitter = typeof (target as EmitterLike).on === \"function\";\n    let timer: ReturnType<typeof setTimeout> | undefined;\n\n    // One cleanup for every way this can end, so no listener or timer outlives the promise.\n    const cleanup = () => {\n      if (isEmitter) {\n        (target as EmitterLike).off(event, onEvent);\n        if (event !== \"error\") (target as EmitterLike).off(\"error\", onError);\n      } else {\n        (target as EventTarget).removeEventListener(event, onEvent);\n      }\n      clearTimeout(timer);\n      signal?.removeEventListener(\"abort\", onAbort);\n    };\n    const finish = (settle: () => void) => {\n      cleanup();\n      settle();\n    };\n\n    function onEvent(...args: any[]) {\n      try {\n        if (filter && !filter(...args)) return;\n      } catch (error) {\n        finish(() => reject(error));\n        return;\n      }\n      finish(() => resolve(isEmitter ? args : args[0]));\n    }\n    function onError(error: unknown) {\n      finish(() => reject(error));\n    }\n    function onAbort() {\n      finish(() => reject(signal!.reason));\n    }\n\n    if (isEmitter) {\n      (target as EmitterLike).on(event, onEvent);\n      // Like events.once in Node: an \"error\" event rejects (unless we''re waiting for \"error\" itself).\n      if (event !== \"error\") (target as EmitterLike).on(\"error\", onError);\n    } else {\n      (target as EventTarget).addEventListener(event, onEvent);\n    }\n    if (timeout !== undefined) {\n      timer = setTimeout(() => finish(() => reject(new DOMException(\"Timed out waiting for \" + event, \"TimeoutError\"))), timeout);\n    }\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n"}'::jsonb),
  ('promise-finally-passthrough', array['b']::text[], '{"en":"`finally` is for cleanup. Its callback receives no argument and its return value is ignored, so the settled value or error flows through unchanged. The exceptions are a thrown error or a rejected promise returned from the callback, which replaces the outcome.","uk":"`finally` призначений для очищення. Його колбек не отримує аргументів, а результат ігнорується, тож завершене значення або помилка передаються далі без змін. Винятки: помилка, що викинута в колбеку, або відхилений проміс, що ним повернено, замінюють результат."}'::jsonb, null::jsonb),
  ('promise-then-non-function-passthrough', array['b']::text[], '{"en":"When `then` receives something that is not a function, it is ignored and the value passes through to the next link. So the chain prints 1. This is why `.then(null)` is harmless but also useless.","uk":"Коли `then` отримує не функцію, він ігнорується, а значення передається далі по ланцюжку. Тому ланцюжок виводить 1. Тому `.then(null)` безпечний, але й марний."}'::jsonb, null::jsonb),
  ('promise-rejection-skips-then', array['b']::text[], '{"en":"A rejection skips every `then` callback until it reaches a handler for errors (`catch`, or the second argument of `then`). Here the `then` callback is skipped and `catch` runs, so only B is printed.","uk":"Відхилення пропускає кожен колбек `then`, доки не дійде до обробника помилок (`catch` або другого аргументу `then`). Тут колбек `then` пропускається, а виконується `catch`, тож виводиться лише B."}'::jsonb, null::jsonb),
  ('promise-resolve-with-promise-timing', array['c']::text[], '{"en":"Resolving a promise with another promise is not instant. Adopting the inner promise takes a job to call its `then`, and then one more job to settle the outer promise. The chain of three `then` calls advances one step per job, so 2 lands after 4. Each `then` is a separate microtask; the exact order depends on when each is queued, which is why interviewers use this case.","uk":"Резолв промісу іншим промісом не відбувається миттєво. Перейняття внутрішнього промісу займає одну чергову задачу на виклик його `then`, а потім ще одну, щоб завершити зовнішній проміс. Ланцюжок із трьох `then` просувається по одному кроку за задачу, тож 2 з''являється після 4. Кожен `then` це окрема мікрозадача, і порядок залежить від того, коли вона ставиться в чергу."}'::jsonb, null::jsonb),
  ('node-nexttick-vs-promise', array['b']::text[], '{"en":"Node drains the `process.nextTick` queue before the promise microtask queue, and both run after the current synchronous script. So `tick` prints first, every time, when both are scheduled from the main module. `nextTick` is Node-only, which is why it does not exist in the browser.","uk":"Node спершу виконує чергу `process.nextTick`, а вже потім мікрозадачі промісів. Обидві виконуються після поточного синхронного скрипта. Тому `tick` виводиться першим завжди, якщо обидва поставлено в чергу з головного модуля. `nextTick` існує лише в Node, тому в браузері його немає."}'::jsonb, null::jsonb),
  ('queuemicrotask-order', array['b']::text[], '{"en":"`s` is synchronous, so it prints first. `queueMicrotask` and the promise callback are both microtasks, and they run in the order they were queued, so `m` comes before `p`. The timer is a macrotask and runs last. `queueMicrotask` is a direct way to add a microtask without wrapping a promise.","uk":"`s` синхронний, тож виводиться першим. `queueMicrotask` і колбек промісу це мікрозадачі, які виконуються в порядку постановки в чергу, тому `m` раніше за `p`. Таймер це макрозадача і йде останнім. `queueMicrotask` це прямий спосіб додати мікрозадачу без обгортки в проміс."}'::jsonb, null::jsonb),
  ('el-settimeout-zero', array['a']::text[], '{"en":"JavaScript runs to completion on one thread, so a timer can''t interrupt running code. A 0 ms timer queues a task that runs after the current task and its microtasks, behind any tasks already queued. Browsers also clamp deeply nested timers to about 4 ms.","uk":"JavaScript виконує код до кінця в одному потоці, тож таймер не може перервати код, що виконується. Таймер на 0 мс ставить у чергу задачу, що виконається після поточної задачі та її мікрозадач, позаду вже доданих задач. Браузери також обмежують глибоко вкладені таймери приблизно до 4 мс."}'::jsonb, null::jsonb),
  ('el-executor-sync', array['a']::text[], '{"en":"The function passed to `new Promise` runs synchronously, and calling `resolve` doesn''t stop it, so `1` and `2` print first. `then` callbacks always run as microtasks, after the current synchronous code (`4`), even when the promise is already resolved.","uk":"Функція, передана в `new Promise`, виконується синхронно, і виклик `resolve` її не зупиняє, тож спершу виводяться `1` і `2`. Колбеки `then` завжди виконуються як мікрозадачі, після поточного синхронного коду (`4`), навіть якщо проміс уже виконаний."}'::jsonb, null::jsonb),
  ('el-await-splits', array['a']::text[], '{"en":"Calling an async function runs its body synchronously up to the first `await` (`b`). `await` then returns control to the caller (`c`), and the rest of the function (`d`) continues in a microtask, even when awaiting a non-promise value like `null`.","uk":"Виклик async-функції виконує її тіло синхронно до першого `await` (`b`). Потім `await` повертає керування викликачу (`c`), а решта функції (`d`) продовжується в мікрозадачі, навіть якщо очікується не проміс, а значення на кшталт `null`."}'::jsonb, null::jsonb),
  ('el-try-catch-timer', array['a']::text[], '{"en":"`try/catch` only covers code that runs synchronously inside the `try` block. The timer callback runs later, in its own task, when the `try` has long finished, so the error escapes to the global handler. Catch inside the callback, or wrap the timer in a promise and `await` it inside `try`.","uk":"`try/catch` охоплює лише код, що виконується синхронно всередині блоку `try`. Колбек таймера виконується пізніше, в окремій задачі, коли `try` давно завершився, тож помилка потрапляє до глобального обробника. Перехоплюйте всередині колбека або загорніть таймер у проміс і чекайте на нього через `await` усередині `try`."}'::jsonb, null::jsonb),
  ('el-nested-microtasks', array['a']::text[], '{"en":"Initially the microtask queue holds the `then` callback and the `queueMicrotask` callback, in that order. Running `p1` queues `p2` at the **back** of the queue, behind `q`. The loop drains the whole microtask queue, including newly added jobs, before it runs the timer task.","uk":"Спочатку в черзі мікрозадач колбек `then` і колбек `queueMicrotask`, саме в такому порядку. Виконання `p1` додає `p2` у **кінець** черги, позаду `q`. Цикл вичерпує всю чергу мікрозадач, зокрема щойно додані, перш ніж виконати задачу таймера."}'::jsonb, null::jsonb),
  ('el-interleaved-chains', array['a']::text[], '{"en":"Each `then` callback is queued only when the previous promise in its chain settles. The first round of microtasks runs `1` and `3`; each of them resolves the next promise in its chain and queues `2` and `4` for the next round. Chains interleave step by step instead of running one after the other.","uk":"Кожен колбек `then` стає в чергу лише тоді, коли завершується попередній проміс у його ланцюжку. Перший раунд мікрозадач виконує `1` і `3`; кожна з них виконує наступний проміс свого ланцюжка й додає `2` і `4` до наступного раунду. Ланцюжки чергуються крок за кроком, а не виконуються один за одним."}'::jsonb, null::jsonb),
  ('el-microtask-between-timers', array['a']::text[], '{"en":"Each timer callback is a separate task, and the microtask queue is drained after every task. The promise queued inside `t2` therefore runs right after `t2` and before the `t3` task, not after all timers.","uk":"Кожен колбек таймера є окремою задачею, а чергу мікрозадач вичерпують після кожної задачі. Тому проміс, доданий усередині `t2`, виконується одразу після `t2` і до задачі `t3`, а не після всіх таймерів."}'::jsonb, null::jsonb),
  ('el-starvation', array['a']::text[], '{"en":"After a task, the event loop runs microtasks until the queue is empty. `viaPromise` adds a new microtask each time, so that never happens and the page hangs like a `while (true)` loop. `viaTimeout` queues a new *task* each time, and the loop can handle input and render between tasks (wasteful, but responsive).","uk":"Після задачі цикл подій виконує мікрозадачі, доки черга не спорожніє. `viaPromise` щоразу додає нову мікрозадачу, тож цього не стається, і сторінка зависає, як від `while (true)`. `viaTimeout` щоразу додає нову *задачу*, і між задачами цикл може обробляти введення й рендерити (марнотратно, але чуйно)."}'::jsonb, null::jsonb),
  ('el-async-classic', array['a']::text[], '{"en":"Synchronous part: `script start`, then `a1` runs until its `await` (`a1 start`, and `a2` runs synchronously), then the promise executor (`p1`) and `script end`. The `await` continuation was queued before `.then(p2)`, so microtasks print `a1 end` then `p2`. The timer task comes last.","uk":"Синхронна частина: `script start`, потім `a1` виконується до свого `await` (`a1 start`, а `a2` виконується синхронно), потім виконавець промісу (`p1`) і `script end`. Продовження після `await` потрапило в чергу раніше за `.then(p2)`, тож мікрозадачі виводять `a1 end`, потім `p2`. Задача таймера йде останньою."}'::jsonb, null::jsonb),
  ('el-await-thenable', array['a']::text[], '{"en":"`await` wraps a non-promise thenable in a new promise, which calls the thenable''s `then` in a separate microtask (a resolve-thenable job), not synchronously. So `then-called` runs in the first microtask round together with `p`; calling `resolve(\"x\")` then queues the async function''s continuation, which runs one round later. Awaiting a native promise skips that extra job.","uk":"`await` загортає не нативний thenable у новий проміс, який викликає `then` цього thenable в окремій мікрозадачі (завдання resolve-thenable), а не синхронно. Тож `then-called` виконується в першому раунді мікрозадач разом із `p`; виклик `resolve(\"x\")` потім ставить у чергу продовження async-функції, яке виконується раундом пізніше. Очікування нативного промісу обходиться без цього додаткового завдання."}'::jsonb, null::jsonb),
  ('el-loop-simulator', null::text[], '{"en":"The simulator mirrors the real model: the script is a task; after each task the microtask queue is drained with a `while` loop, so microtasks added during draining still run before the next task; timers are picked by due time with a sequence number as a tie-breaker. Computing `due` when a timer is scheduled (from the current `now`) is what makes nested timers fire at the right simulated time.","uk":"Симулятор відтворює справжню модель: скрипт є задачею; після кожної задачі черга мікрозадач вичерпується циклом `while`, тож мікрозадачі, додані під час вичерпування, теж виконуються до наступної задачі; таймери обираються за часом спрацювання з порядковим номером для рівних випадків. Обчислення `due` в момент планування (від поточного `now`) змушує вкладені таймери спрацьовувати у правильний змодельований час."}'::jsonb, '{"/src/loop.ts":"export type Callback = () => void;\n\nexport interface Loop {\n  readonly now: number;\n  setTimeout(cb: Callback, delay?: number): number;\n  clearTimeout(id: number): void;\n  queueMicrotask(cb: Callback): void;\n  run(main: Callback): void;\n}\n\ntype Timer = { id: number; due: number; seq: number; cb: Callback };\n\nexport function createLoop(): Loop {\n  let now = 0;\n  let nextId = 1;\n  let seq = 0;\n  let timers: Timer[] = [];\n  const microtasks: Callback[] = [];\n\n  // Drain completely: microtasks queued by microtasks run in the same pass.\n  const drainMicrotasks = () => {\n    while (microtasks.length) microtasks.shift()!();\n  };\n\n  return {\n    get now() {\n      return now;\n    },\n    setTimeout(cb, delay = 0) {\n      const id = nextId++;\n      timers.push({ id, due: now + Math.max(0, delay || 0), seq: seq++, cb });\n      return id;\n    },\n    clearTimeout(id) {\n      timers = timers.filter((t) => t.id !== id);\n    },\n    queueMicrotask(cb) {\n      microtasks.push(cb);\n    },\n    run(main) {\n      main(); // the script is the first task\n      drainMicrotasks();\n      while (timers.length) {\n        // Earliest due time first; ties keep scheduling order.\n        let next = timers[0];\n        for (const t of timers) if (t.due < next.due || (t.due === next.due && t.seq < next.seq)) next = t;\n        timers = timers.filter((t) => t !== next);\n        now = Math.max(now, next.due);\n        next.cb(); // one task…\n        drainMicrotasks(); // …then all microtasks\n      }\n    },\n  };\n}\n"}'::jsonb),
  ('el-chunked-work', null::text[], '{"en":"Awaiting a 0 ms timeout ends the current task, so the browser can handle input and paint before the next chunk; awaiting a resolved promise would only yield to microtasks and still block rendering. Checking the signal before each chunk makes cancellation cheap. `scheduler.yield()` is a newer alternative that keeps the continuation at a higher priority.","uk":"Очікування таймера на 0 мс завершує поточну задачу, тож браузер може обробити введення й відмалювати кадр до наступної частини; очікування виконаного промісу поступилося б лише мікрозадачам і все одно блокувало б рендеринг. Перевірка сигналу перед кожною частиною робить скасування дешевим. `scheduler.yield()` є новішою альтернативою, що зберігає продовженню вищий пріоритет."}'::jsonb, '{"/src/chunks.ts":"export type ChunkOptions = {\n  chunkSize?: number;\n  signal?: AbortSignal;\n  yieldToLoop?: () => Promise<void>;\n};\n\nconst nextTask = () => new Promise<void>((resolve) => setTimeout(resolve, 0));\n\nexport async function processInChunks<T, R>(items: T[], fn: (item: T, index: number) => R, options: ChunkOptions = {}): Promise<R[]> {\n  const { chunkSize = 100, signal, yieldToLoop = nextTask } = options;\n  if (!Number.isInteger(chunkSize) || chunkSize < 1) throw new RangeError(\"chunkSize must be a positive integer\");\n\n  const results: R[] = [];\n  for (let start = 0; start < items.length; start += chunkSize) {\n    // A new task (not a microtask) lets input, timers and rendering run between chunks.\n    if (start > 0) await yieldToLoop();\n    if (signal?.aborted) throw signal.reason ?? new DOMException(\"Aborted\", \"AbortError\");\n    const end = Math.min(start + chunkSize, items.length);\n    for (let i = start; i < end; i++) results.push(fn(items[i], i));\n  }\n  return results;\n}\n"}'::jsonb),
  ('express-error-arity', array['a']::text[], '{"en":"There is no separate registration for error handlers: a middleware with four parameters is skipped for normal requests and run only after `next(err)` or a thrown error. That''s why dropping the unused `next` parameter silently turns your error handler into a normal middleware that never sees errors.","uk":"Окремої реєстрації для обробників помилок немає: middleware з чотирма параметрами пропускається для звичайних запитів і виконується лише після `next(err)` або кинутої помилки. Тому, якщо прибрати невикористаний параметр `next`, обробник помилок мовчки стане звичайним middleware, який помилок не бачить."}'::jsonb, null::jsonb),
  ('express-mini-app', null::text[], '{"en":"Express is a list of layers and a cursor. `step()` walks the list from the current position, skipping layers that don''t match the method or path, and calls the first one that fits. `next()` is just `step()` again, which is why calling it from inside a handler continues the same walk. Errors change which layers are eligible: `failed` decides between normal handlers and error handlers, and the arity check (`handler.length === 4`) is the same trick Express uses. Wrapping each call in `try/catch` turns a thrown error into the same state as `next(error)`. Stopping the loop with `return` after a handler is what makes a handler that answers without calling `next()` end the request, just as in Express.","uk":"Express — це список шарів і курсор. `step()` іде списком від поточної позиції, пропускає шари, що не збігаються з методом чи шляхом, і викликає перший, що підходить. `next()` — це просто знову `step()`, тому виклик з обробника продовжує той самий прохід. Помилки змінюють, які шари можна викликати: `failed` вирішує між звичайними обробниками й обробниками помилок, а перевірка кількості параметрів (`handler.length === 4`) — той самий прийом, що використовує Express. Обгортання кожного виклику в `try/catch` перетворює кинуту помилку на той самий стан, що й `next(error)`. Зупинка циклу через `return` після обробника — це те, через що обробник, який відповів без `next()`, завершує запит, як і в Express."}'::jsonb, '{"/src/app.ts":"export type Req = { method: string; path: string; params: Record<string, string>; body?: unknown; [key: string]: unknown };\nexport type Res = { status: number; body: unknown };\nexport type Next = (error?: unknown) => void;\nexport type Handler = (req: Req, res: Res, next: Next) => void;\nexport type ErrorHandler = (error: unknown, req: Req, res: Res, next: Next) => void;\n\ntype Layer = { method?: string; path?: string; handler: Handler | ErrorHandler };\n\n/** Matches \"/users/:id\" against \"/users/42\"; returns the named params, or null when the path doesn''t match. */\nfunction matchPath(pattern: string, path: string): Record<string, string> | null {\n  const want = pattern.split(\"/\");\n  const got = path.split(\"/\");\n  if (want.length !== got.length) return null;\n  const params: Record<string, string> = {};\n  for (let i = 0; i < want.length; i++) {\n    if (want[i].startsWith(\":\")) params[want[i].slice(1)] = got[i];\n    else if (want[i] !== got[i]) return null;\n  }\n  return params;\n}\n\nexport function createApp() {\n  const layers: Layer[] = [];\n\n  return {\n    use(handler: Handler | ErrorHandler): void {\n      layers.push({ handler });\n    },\n    get(path: string, handler: Handler): void {\n      layers.push({ method: \"GET\", path, handler });\n    },\n    handle(method: string, path: string, body?: unknown): Res {\n      const req: Req = { method, path, params: {}, body };\n      const res: Res = { status: 0, body: undefined };\n      let failed = false;\n      let error: unknown;\n      let index = 0;\n\n      const step = (): void => {\n        while (index < layers.length) {\n          const layer = layers[index++];\n          if (layer.method !== undefined && layer.method !== method) continue;\n          if (layer.path !== undefined) {\n            const params = matchPath(layer.path, path);\n            if (params === null) continue;\n            req.params = params;\n          }\n          // Express tells error handlers apart by their arity: four parameters.\n          const takesError = layer.handler.length === 4;\n          // Error handlers run only while there is an error, and normal handlers only without one.\n          if (takesError !== failed) continue;\n          try {\n            if (takesError) (layer.handler as ErrorHandler)(error, req, res, next);\n            else (layer.handler as Handler)(req, res, next);\n          } catch (thrown) {\n            failed = true;\n            error = thrown;\n            continue;\n          }\n          return; // the handler either answered or called next(), which resumes the loop\n        }\n      };\n\n      const next: Next = (err?: unknown) => {\n        failed = err !== undefined;\n        if (failed) error = err;\n        step();\n      };\n\n      step();\n      if (res.status === 0) {\n        res.status = failed ? 500 : 404;\n        res.body = failed ? \"Internal error\" : \"Not found\";\n      }\n      return res;\n    },\n  };\n}\n"}'::jsonb),
  ('sass-use-vs-import', array['a']::text[], '{"en":"With `@use`, a file is evaluated once and its members are reached through a namespace such as `colors.$primary`, so two partials can define the same name without clashing. `@import` puts every member in one global scope and evaluates the file again each time it is imported. `@forward` lets an index file re-export a module''s members to its own users.","uk":"З `@use` файл обчислюється один раз, а його члени доступні через простір імен, наприклад `colors.$primary`, тож два частини можуть визначити однакову назву без конфлікту. `@import` поміщає всі члени в одну глобальну область і обчислює файл знову при кожному імпорті. `@forward` дозволяє файлу-індексу передавати члени модуля далі для його користувачів."}'::jsonb, null::jsonb),
  ('css-bem-naming', array['a']::text[], '{"en":"BEM names describe structure in the class itself: a block is a standalone component, `__` introduces an element inside it, and `--` a modifier that changes its look or state. Because every class name carries its place in the hierarchy, styles stay flat and don''t depend on how the markup happens to be nested.","uk":"Назви BEM описують структуру в самому класі: блок — це самостійний компонент, `__` позначає елемент всередині нього, а `--` — модифікатор, що змінює вигляд або стан. Оскільки кожна назва класу несе своє місце в ієрархії, стилі лишаються плоскими і не залежать від того, як випадково вкладено розмітку."}'::jsonb, null::jsonb),
  ('react-virtual-dom-purpose', array['a']::text[], '{"en":"Touching the real DOM is comparatively expensive, and rebuilding it wholesale is wasteful. A virtual DOM is a cheap description of the UI as plain objects; diffing two descriptions yields a short list of changes that the renderer applies, typically in one batch. The diff is an optimisation, not a promise of speed: keys and memoisation still decide how much work each update does.","uk":"Робота з реальним DOM відносно дорога, а повна перебудова — марнотратна. Віртуальний DOM — це недорогий опис інтерфейсу у вигляді звичайних об''єктів; порівняння двох описів дає короткий список змін, які рендерер застосовує, як правило, одним пакетом. Порівняння — це оптимізація, а не гарантія швидкості: ключі й мемоїзація все ще визначають, скільки роботи виконує кожне оновлення."}'::jsonb, null::jsonb),
  ('crdt-offline-merge', array['a']::text[], '{"en":"A CRDT (conflict-free replicated data type) is designed so that merging is mathematically well-behaved: order and repetition of updates don''t change the result. That lets every replica accept local edits immediately and merge later without coordination. Locking, or a last-write-wins server, gives up either availability or the user''s edits, which is why real collaborative editors use CRDT-like or operational-transform techniques.","uk":"CRDT (conflict-free replicated data type, безконфліктний реплікований тип даних) спроєктовано так, що злиття математично коректне: порядок і повтор оновлень не змінюють результат. Це дозволяє кожній репліці одразу приймати локальні правки і зливати їх пізніше без координації. Блокування або сервер «останній запис перемагає» жертвують або доступністю, або правками користувачів, тому справжні редактори спільної роботи використовують техніки, близькі до CRDT, або операційні перетворення."}'::jsonb, null::jsonb),
  ('react-vdom-diff', null::text[], '{"en":"The diff is a recursive walk that stops as soon as two nodes can''t be reconciled in place. Different tags or text against an element force a replace, because there is nothing to patch. Matching children by position is simple and fast, but it''s the reason React asks for `key`s on lists: without keys, inserting an item at the start looks like changing every item. Removals go from the highest index down so each recorded index still refers to the node that was there when the patch was made. The attribute patch uses `null` to mean \"remove\", which keeps the patch format a single object per element.","uk":"Порівняння — це рекурсивний обхід, що зупиняється, щойно два вузли неможливо узгодити на місці. Різні теги або текст проти елемента вимагають заміни, бо патчити нічого. Зіставлення дочірніх вузлів за позицією просте й швидке, але саме через це React просить `key` у списків: без ключів вставка елемента на початок виглядає як зміна кожного елемента. Видалення йдуть від найбільшого індексу до найменшого, щоб кожен записаний індекс досі вказував на вузол, який був там під час створення патча. Патч атрибутів використовує `null` як «видалити», тож формат патча — це один об''єкт на елемент."}'::jsonb, '{"/src/vdom.ts":"export type VNode = { type: string; props: Record<string, string>; children: Array<VNode | string> };\nexport type Patch =\n  | { type: \"REPLACE\"; path: number[]; node: VNode | string }\n  | { type: \"PROPS\"; path: number[]; props: Record<string, string | null> }\n  | { type: \"APPEND\"; path: number[]; node: VNode | string }\n  | { type: \"REMOVE\"; path: number[]; index: number };\n\nconst has = (object: object, key: string) => Object.prototype.hasOwnProperty.call(object, key);\n\nexport function diff(oldNode: VNode | string, newNode: VNode | string, path: number[] = []): Patch[] {\n  // Text and elements, or elements with different tags, can''t be patched in place: replace them.\n  if (typeof oldNode === \"string\" || typeof newNode === \"string\") {\n    return oldNode === newNode ? [] : [{ type: \"REPLACE\", path, node: newNode }];\n  }\n  if (oldNode.type !== newNode.type) return [{ type: \"REPLACE\", path, node: newNode }];\n\n  const patches: Patch[] = [];\n\n  // Attributes: changed or added values are set; attributes that disappeared are marked null.\n  const props: Record<string, string | null> = {};\n  for (const key of Object.keys(newNode.props)) {\n    if (!has(oldNode.props, key) || oldNode.props[key] !== newNode.props[key]) props[key] = newNode.props[key];\n  }\n  for (const key of Object.keys(oldNode.props)) {\n    if (!has(newNode.props, key)) props[key] = null;\n  }\n  if (Object.keys(props).length > 0) patches.push({ type: \"PROPS\", path, props });\n\n  // Children are matched by position. Extra new children are appended; extra old ones are removed from the end.\n  const shared = Math.min(oldNode.children.length, newNode.children.length);\n  for (let i = 0; i < shared; i++) {\n    patches.push(...diff(oldNode.children[i], newNode.children[i], [...path, i]));\n  }\n  for (let i = oldNode.children.length; i < newNode.children.length; i++) {\n    patches.push({ type: \"APPEND\", path, node: newNode.children[i] });\n  }\n  // Remove from the highest index down, so each index still refers to the node that was there.\n  for (let i = oldNode.children.length - 1; i >= newNode.children.length; i--) {\n    patches.push({ type: \"REMOVE\", path, index: i });\n  }\n  return patches;\n}\n"}'::jsonb),
  ('virtual-window-math', null::text[], '{"en":"A virtual list needs only arithmetic: the scroll position tells you which row is first on screen (`floor(top / rowHeight)`), the viewport height tells you how many rows fit, and a few extra rows on each side hide the gaps while scrolling. The spacer (`totalHeight`) keeps the scrollbar the length of the full list, and `offsetTop` moves the rendered slice into place. Clamping `scrollTop` matters because a stale or overshooting value would otherwise produce an empty or misaligned window.","uk":"Віртуалізація списку це арифметика: позиція прокрутки показує, який рядок першим на екрані (`floor(top / rowHeight)`), висота viewport показує, скільки рядків вміщується, а кілька додаткових рядків з кожного боку приховують порожнечі під час прокрутки. Розтяжка (`totalHeight`) робить смугу прокрутки такою, як весь список, а `offsetTop` ставить відрендерений фрагмент на місце. Обмеження `scrollTop` важливе, бо застаріле або завелике значення дало б порожнє чи зміщене вікно."}'::jsonb, '{"/src/virtual-list.ts":"export interface VirtualOptions {\n  itemCount: number;\n  rowHeight: number;\n  viewportHeight: number;\n  scrollTop: number;\n  /** Extra rows rendered above and below the viewport. Defaults to 3. */\n  overscan?: number;\n}\n\nexport interface VirtualWindow {\n  /** First row to render (inclusive). */\n  start: number;\n  /** Row to stop before (exclusive). */\n  end: number;\n  /** Pixel offset of the first rendered row inside the scroll container. */\n  offsetTop: number;\n  /** Height of the spacer that gives the scrollbar its real length. */\n  totalHeight: number;\n}\n\nexport function getVirtualWindow({ itemCount, rowHeight, viewportHeight, scrollTop, overscan = 3 }: VirtualOptions): VirtualWindow {\n  if (itemCount <= 0 || rowHeight <= 0) return { start: 0, end: 0, offsetTop: 0, totalHeight: 0 };\n\n  const totalHeight = itemCount * rowHeight;\n  const maxScroll = Math.max(0, totalHeight - viewportHeight);\n  const top = Math.min(Math.max(0, scrollTop), maxScroll);\n\n  const firstVisible = Math.floor(top / rowHeight);\n  const lastVisible = Math.ceil((top + viewportHeight) / rowHeight); // exclusive\n\n  const start = Math.max(0, firstVisible - overscan);\n  const end = Math.min(itemCount, lastVisible + overscan);\n\n  return { start, end, offsetTop: start * rowHeight, totalHeight };\n}\n"}'::jsonb),
  ('undo-redo-history', null::text[], '{"en":"Keep three things: the present value, a stack of past values and a stack of future values. Undo moves the present onto the future stack and pops the last past value back into place; redo does the reverse. A new edit invalidates the future, which is why `push` clears it. Storing immutable snapshots (or never mutating the values you push) keeps these stacks trustworthy.","uk":"Тримайте три речі: поточне значення, стек минулих значень і стек майбутніх. Скасування переносить поточне значення у стек майбутніх, а останнє минуле значення повертає на місце; повтор робить навпаки. Нова зміна робить майбутнє недійсним, тому `push` його очищає. Зберігання незмінних знімків (або ніколи не мутування переданих значень) тримає стеки надійними."}'::jsonb, '{"/src/history.ts":"export interface History<T> {\n  readonly present: T;\n  readonly canUndo: boolean;\n  readonly canRedo: boolean;\n  push(next: T): void;\n  undo(): T;\n  redo(): T;\n}\n\nexport function createHistory<T>(initial: T, limit = Infinity): History<T> {\n  if (limit < 1) throw new RangeError(\"limit must be at least 1\");\n\n  let present = initial;\n  let past: T[] = [];\n  let future: T[] = [];\n\n  const remember = (value: T) => {\n    past.push(value);\n    if (past.length > limit) past.shift();\n  };\n\n  return {\n    get present() {\n      return present;\n    },\n    get canUndo() {\n      return past.length > 0;\n    },\n    get canRedo() {\n      return future.length > 0;\n    },\n    push(next) {\n      if (Object.is(next, present)) return;\n      remember(present);\n      present = next;\n      future = [];\n    },\n    undo() {\n      if (past.length > 0) {\n        future.push(present);\n        present = past.pop() as T;\n      }\n      return present;\n    },\n    redo() {\n      if (future.length > 0) {\n        remember(present);\n        present = future.pop() as T;\n      }\n      return present;\n    },\n  };\n}\n"}'::jsonb),
  ('react-nested-region-table', null::text[], '{"en":"A table''s columns are a shared resource: every row has to line up, so a row with fewer cells must span the rest with `colSpan`. Deriving the column count from the data with `reduce` keeps the markup correct when the data changes, and the `Math.max(…, 1)` guard avoids a zero span when there are no districts at all. Give each `tbody` a stable key (the region id) rather than the array index.","uk":"Колонки таблиці спільні: кожен рядок мусить збігатися, тож рядок з меншою кількістю клітинок має розтягнутися через `colSpan`. Обчислення кількості колонок з даних через `reduce` тримає розмітку правильною, коли дані змінюються, а `Math.max(…, 1)` не дає нульового розтягу, коли районів немає взагалі. Кожному `tbody` дайте стабільний ключ (id регіону), а не індекс масиву."}'::jsonb, '{"/App.tsx":"export interface District {\n  id: number;\n  name: string;\n}\n\nexport interface Region {\n  id: string;\n  name: string;\n  districts: District[];\n}\n\nexport const REGIONS: Region[] = [\n  { id: \"n\", name: \"North\", districts: [{ id: 1, name: \"Alpha\" }, { id: 2, name: \"Beta\" }, { id: 3, name: \"Gamma\" }] },\n  { id: \"s\", name: \"South\", districts: [{ id: 4, name: \"Delta\" }] },\n  { id: \"e\", name: \"East\", districts: [] },\n];\n\nfunction RegionTable({ regions }: { regions: Region[] }) {\n  const columns = regions.reduce((max, region) => Math.max(max, region.districts.length), 0);\n  const span = Math.max(columns, 1);\n\n  return (\n    <table>\n      {regions.map((region) => (\n        <tbody key={region.id} data-testid={\"region-\" + region.id}>\n          <tr>\n            <th colSpan={span}>{region.name}</th>\n          </tr>\n          <tr>\n            {region.districts.length > 0 ? (\n              region.districts.map((district) => <td key={district.id}>{district.name}</td>)\n            ) : (\n              <td colSpan={span}>No districts</td>\n            )}\n          </tr>\n        </tbody>\n      ))}\n    </table>\n  );\n}\n\nexport default function App() {\n  return <RegionTable regions={REGIONS} />;\n}\n"}'::jsonb),
  ('streaming-latency-hls-vs-webrtc', array['b']::text[], '{"en":"Segmented streaming splits video into chunks (typically a few seconds each) and the player keeps a buffer of several chunks so playback survives network jitter. That buffer is latency. WebRTC is built for real-time media: it sends small packets over a transport that favours timeliness and keeps its playout buffer short.","uk":"Сегментоване стримінгове відео ділиться на шматки (зазвичай по кілька секунд), а плеєр тримає буфер з кількох шматків, щоб відтворення витримувало мережеві коливання. Цей буфер і є затримкою. WebRTC створено для реального часу: він надсилає дрібні пакети транспортом, який надає перевагу своєчасності, і тримає короткий буфер відтворення."}'::jsonb, null::jsonb),
  ('hover-hit-testing-canvas-svg', array['b']::text[], '{"en":"A canvas is a single bitmap: the browser knows nothing about the shapes you drew, so you must hit-test coordinates yourself (for example with a spatial index or by redrawing an offscreen picking buffer). SVG shapes are elements in the DOM, so `pointerenter` or `mouseover` on a shape tells you exactly which one was hit.","uk":"Canvas це один растровий образ: браузер не знає про намальовані фігури, тож перевірку попадання доводиться робити самому (наприклад, просторовим індексом або перемальовуванням буфера вибору). Фігури SVG є елементами DOM, тому `pointerenter` або `mouseover` на фігурі точно повідомляють, яку з них зачепили."}'::jsonb, null::jsonb),
  ('annotation-coordinate-space', array['b']::text[], '{"en":"Image coordinates do not change when the user zooms or pans, so the stored data stays valid and you only apply a view transform (scale and offset) when drawing. Screen-space coordinates would need rewriting on every zoom or resize, and they break if the image is shown at a different size on another device.","uk":"Координати зображення не змінюються під час зуму чи панорамування, тож збережені дані лишаються правильними, а при малюванні застосовується лише трансформація вигляду (масштаб і зсув). Координати екрана треба переписувати при кожному зумі чи зміні розміру, і вони ламаються, коли зображення показують іншого розміру на іншому пристрої."}'::jsonb, null::jsonb),
  ('device-pixel-ratio-canvas', array['b']::text[], '{"en":"`window.devicePixelRatio` is the number of physical device pixels per CSS pixel. A canvas''s drawing buffer is measured in device pixels, so the buffer must be multiplied by that ratio, while the CSS size stays the same. Then scale the context so your drawing code can keep using CSS units.","uk":"`window.devicePixelRatio` це кількість фізичних пікселів пристрою на один CSS-піксель. Буфер малювання canvas вимірюється у пікселях пристрою, тож його треба помножити на це співвідношення, а CSS-розмір лишається тим самим. Потім масштабуйте контекст, щоб код малювання міг далі працювати в CSS-одиницях."}'::jsonb, null::jsonb),
  ('undo-redo-stack-design', array['a']::text[], '{"en":"Undo has to remember where it came from so that Redo can get back. Moving the present onto `future` keeps the step reversible, and taking the last `past` entry restores the earlier state. The opposite assignment in option B is exactly what Redo does, which is why mixing the two stacks breaks history.","uk":"Скасування має пам''ятати, звідки прийшло, щоб повтор міг повернути назад. Перенесення поточного значення у `future` робить крок оборотним, а взяття останнього елемента `past` відновлює попередній стан. Протилежне призначення у варіанті B саме те, що робить повтор, тому змішування двох стеків ламає історію."}'::jsonb, null::jsonb),
  ('service-worker-offline-cache', array['b']::text[], '{"en":"A Service Worker sits between the page and the network. It can respond to `fetch` events from the cache, and it runs even when the page is closed. Web Workers run code in parallel but do not intercept network requests, and `localStorage` is synchronous and small (roughly 5 MB), so it is a poor place for large binary assets like video or images.","uk":"Service Worker стоїть між сторінкою та мережею. Він може відповідати на події `fetch` з кешу і працює навіть тоді, коли сторінку закрито. Web Workers виконують код паралельно, але не перехоплюють мережеві запити, а `localStorage` синхронний і малий (близько 5 МБ), тому він не підходить для великих бінарних ресурсів на кшталт відео чи зображень."}'::jsonb, null::jsonb),
  ('useref-no-rerender', array['b']::text[], '{"en":"A ref is a mutable box that persists across renders. Writing to it is invisible to React, so it does not trigger a render. Use state for anything that should appear in the UI, and a ref for values you need to read or update without re-rendering, such as timers, previous values or DOM handles.","uk":"Ref це змінна «коробка», яка зберігається між рендерами. React не бачить запису в неї, тож він не викликає рендер. Для всього, що має з''явитися в UI, використовуйте стан, а ref для значень, які треба читати чи змінювати без повторного рендеру, наприклад таймери, попередні значення або посилання на DOM."}'::jsonb, null::jsonb),
  ('server-component-data-list', array['b']::text[], '{"en":"Server Components render on the server, so they can read data directly and send only the resulting markup. Hooks such as `useState` and `useEffect` need the client, so mark a component `\"use client\"` only when it needs interactivity or browser APIs. Keeping read-only lists on the server also cuts the JavaScript sent to the browser.","uk":"Server Components рендеряться на сервері, тож можуть читати дані напряму і надсилати лише готову розмітку. Хуки на кшталт `useState` і `useEffect` потребують клієнта, тому позначайте компонент `\"use client\"` лише тоді, коли йому потрібна інтерактивність або браузерні API. Списки лише для читання на сервері також зменшують JavaScript, який відправляється в браузер."}'::jsonb, null::jsonb),
  ('typescript-runtime-validation', array['b']::text[], '{"en":"TypeScript types only exist at compile time. Data from `fetch` or `response.json()` is `any` at runtime, whatever you annotated. A runtime schema (for example Zod, or a hand-written guard) checks the shape where data enters your app and gives you a typed value, or a clear error.","uk":"Типи TypeScript існують лише під час компіляції. Дані з `fetch` або `response.json()` під час виконання мають тип `any`, незалежно від анотацій. Схема часу виконання (наприклад Zod або власна функція-перевірка) перевіряє форму даних на вході в застосунок і дає типізоване значення або зрозумілу помилку."}'::jsonb, null::jsonb),
  ('sequential-ids-enumeration', array['b']::text[], '{"en":"Predictable IDs let an attacker walk through neighbours (`1041`, `1043`) to find records they should not see, which is an insecure direct object reference. The real defence is an authorization check on every request. Random IDs make enumeration harder, but they are defence in depth, not a substitute.","uk":"Передбачувані ID дозволяють зловмиснику переходити від сусідніх значень (`1041`, `1043`) і знаходити записи, які він не повинен бачити, тобто небезпечне пряме посилання на об''єкт. Справжній захист це перевірка авторизації на кожному запиті. Випадкові ID ускладнюють перебір, але це додатковий рівень захисту, а не заміна."}'::jsonb, null::jsonb),
  ('virtualized-table-spacer', array['b']::text[], '{"en":"Virtualization keeps the DOM small. A spacer with the full height gives the scrollbar its true length, and only the rows in the viewport (plus a small overscan) are rendered and absolutely positioned. Hiding rows with `display: none` still leaves all 10,000 nodes in the DOM, which is the main cost.","uk":"Віртуалізація тримає DOM малим. Розтяжка з повною висотою дає смузі прокрутки справжню довжину, а відрендерюються й абсолютно позиціонуються лише рядки у viewport (плюс невеликий overscan). Приховування рядків через `display: none` лишає всі 10 000 вузлів у DOM, і саме це головна ціна."}'::jsonb, null::jsonb),
  ('react-memo-stable-props', array['b']::text[], '{"en":"`React.memo` compares props shallowly. A callback or object literal created inline is a new reference every render, so the comparison fails. Stabilize them with `useCallback` or `useMemo`, but only where the memoized child is actually expensive; memoizing everything has its own cost.","uk":"`React.memo` порівнює пропси поверхнево. Колбек або об''єкт, створений інлайн, є новим посиланням при кожному рендері, тож порівняння не проходить. Стабілізуйте їх через `useCallback` або `useMemo`, але лише там, де дочірній мемоізований компонент справді дорогий; мемоізація всього має власну ціну."}'::jsonb, null::jsonb),
  ('fp-pure-function', array['a']::text[], '{"en":"A pure function depends only on its arguments and changes nothing outside itself. `stamp` reads the clock, `addTag` mutates its argument, and `withTax` reads mutable outside state (`config`), so the same input can give different results. Pass time and configuration in as arguments to make such functions pure.","uk":"Чиста функція залежить лише від своїх аргументів і нічого не змінює поза собою. `stamp` читає годинник, `addTag` змінює свій аргумент, а `withTax` читає змінний зовнішній стан (`config`), тож однакові вхідні дані можуть дати різні результати. Передавайте час і конфігурацію аргументами, щоб такі функції стали чистими."}'::jsonb, null::jsonb),
  ('fp-map-parseint', array['a']::text[], '{"en":"`map` calls its callback with `(item, index, array)`, and `parseInt` takes `(string, radix)`. So the calls are `parseInt(\"1\", 0)` (radix 0 means \"guess\": `1`), `parseInt(\"2\", 1)` (radix 1 is invalid: `NaN`) and `parseInt(\"3\", 2)` (`3` isn''t a binary digit: `NaN`). Pass a function with the arity you mean: `map(Number)` or `map((s) => parseInt(s, 10))`.","uk":"`map` викликає колбек з `(item, index, array)`, а `parseInt` приймає `(string, radix)`. Тож виклики такі: `parseInt(\"1\", 0)` (основа 0 означає «вгадати»: `1`), `parseInt(\"2\", 1)` (основа 1 недопустима: `NaN`) і `parseInt(\"3\", 2)` (`3` не є двійковою цифрою: `NaN`). Передавайте функцію з потрібною кількістю аргументів: `map(Number)` або `map((s) => parseInt(s, 10))`."}'::jsonb, null::jsonb),
  ('fp-curried-add', array['a']::text[], '{"en":"`add` is curried: each call takes one argument and returns a function waiting for the next. `add(2)(3)` is a function that remembers `a = 2` and `b = 3` in its closure, so calling it with `4` gives `9`. Each chain creates its own closures, so `add(1)(1)(1)` is unaffected and gives `3`.","uk":"`add` каррована: кожен виклик приймає один аргумент і повертає функцію, що чекає наступного. `add(2)(3)` є функцією, яка пам''ятає `a = 2` і `b = 3` у своєму замиканні, тож виклик із `4` дає `9`. Кожен ланцюжок створює власні замикання, тож `add(1)(1)(1)` від цього не залежить і дає `3`."}'::jsonb, null::jsonb),
  ('fp-immutable-update', array['a']::text[], '{"en":"Spread copies only the objects along the changed path (`state` and `state.user`) and keeps references to everything else, which is structural sharing. Option two mutates the old `user` before copying the top level, so both versions share the changed object. `Object.assign(state.user, …)` mutates in place, and the last option sets a different field.","uk":"Spread копіює лише об''єкти вздовж зміненого шляху (`state` і `state.user`) і зберігає посилання на все інше: це спільне використання структури. Другий варіант змінює старий `user` перед копіюванням верхнього рівня, тож обидві версії ділять змінений об''єкт. `Object.assign(state.user, …)` змінює на місці, а останній варіант встановлює інше поле."}'::jsonb, null::jsonb),
  ('fp-pipe-vs-compose', array['a']::text[], '{"en":"`pipe` applies functions left to right: `double(inc(5))` = `12`. `compose` applies them right to left, like mathematical composition: `inc(double(5))` = `11`. `pipe` usually reads more naturally for data transformations; `compose` matches how wrappers nest (`withA(withB(Component))`).","uk":"`pipe` застосовує функції зліва направо: `double(inc(5))` = `12`. `compose` застосовує їх справа наліво, як математична композиція: `inc(double(5))` = `11`. `pipe` зазвичай природніше читається для перетворень даних; `compose` відповідає тому, як вкладаються обгортки (`withA(withB(Component))`)."}'::jsonb, null::jsonb),
  ('fp-reduce-initial', array['a']::text[], '{"en":"Without an initial value, `reduce` uses the first element as the accumulator, which works for a non-empty sum. On an empty array there is nothing to start from, so it throws a `TypeError`. Passing an initial value (`[]`, `0`) makes `reduce` total and also fixes the accumulator''s type.","uk":"Без початкового значення `reduce` бере перший елемент як акумулятор, і для непорожньої суми це працює. Для порожнього масиву почати нема з чого, тож він кидає `TypeError`. Початкове значення (`[]`, `0`) робить `reduce` визначеним для будь-якого входу й фіксує тип акумулятора."}'::jsonb, null::jsonb),
  ('fp-mutating-sort', array['a']::text[], '{"en":"`sort` sorts **in place** and returns the same array, so `original` is changed and `sorted === original`. That''s a classic React bug: sorting state or props directly mutates them and the reference doesn''t change. `toReversed`, `toSorted`, `toSpliced` and `with` (ES2023) return new arrays and leave the original alone.","uk":"`sort` сортує **на місці** й повертає той самий масив, тож `original` змінено, а `sorted === original`. Це класичний баг у React: пряме сортування стану чи пропсів їх мутує, а посилання не змінюється. `toReversed`, `toSorted`, `toSpliced` і `with` (ES2023) повертають нові масиви й не чіпають оригінал."}'::jsonb, null::jsonb),
  ('fp-lazy-generators', array['a']::text[], '{"en":"Generators are lazy: each stage pulls one value at a time from the previous one. `take` returns right after yielding the second item, so `naturals` is never asked for a third value, and the infinite loop is harmless. Eager array methods (`.map`, `.filter`) would need the whole list first. The logs appear before the result because spreading must finish before `console.log` runs.","uk":"Генератори ліниві: кожен етап бере по одному значенню з попереднього. `take` завершується одразу після другого елемента, тож у `naturals` ніхто не просить третє значення, і нескінченний цикл нешкідливий. «Жадібним» методам масивів (`.map`, `.filter`) спершу потрібен увесь список. Записи з''являються перед результатом, бо spread має завершитися до виклику `console.log`."}'::jsonb, null::jsonb),
  ('fp-reduce-spread-cost', array['a']::text[], '{"en":"Spreading `acc` copies every key collected so far, so step *k* costs *k* and the total is about n²/2 copies. Immutability matters for values other code can see; the accumulator is created inside this expression and nobody else holds it, so mutating it (`acc[item.id] = item; return acc;`) keeps the function pure from the outside. `Object.fromEntries` or a `Map` are clean O(n) alternatives.","uk":"Spread `acc` копіює всі зібрані досі ключі, тож крок *k* коштує *k*, а загалом виходить близько n²/2 копіювань. Незмінність важлива для значень, які бачить інший код; акумулятор створюється всередині цього виразу й більше ніхто його не тримає, тож його зміна (`acc[item.id] = item; return acc;`) лишає функцію чистою ззовні. `Object.fromEntries` або `Map` є охайними альтернативами за O(n)."}'::jsonb, null::jsonb),
  ('fp-pipe-curry', null::text[], '{"en":"`pipe` and `compose` are a single `reduce`/`reduceRight` over the functions, with the input as the initial value (so an empty list is the identity). `curry` returns a function that either calls `fn` once enough arguments have arrived, or returns a new function closing over the arguments so far. Because nothing is stored in shared variables, every partial application is its own closure.","uk":"`pipe` і `compose` є одним `reduce`/`reduceRight` по функціях із вхідним значенням як початковим (тож порожній список дає тотожну функцію). `curry` повертає функцію, яка або викликає `fn`, щойно аргументів достатньо, або повертає нову функцію, що замикає вже отримані аргументи. Оскільки нічого не зберігається в спільних змінних, кожне часткове застосування є окремим замиканням."}'::jsonb, '{"/src/fn.ts":"type Fn = (x: any) => any;\n\nexport function pipe(...fns: Fn[]): Fn {\n  return (x) => fns.reduce((value, f) => f(value), x);\n}\n\nexport function compose(...fns: Fn[]): Fn {\n  return (x) => fns.reduceRight((value, f) => f(value), x);\n}\n\nexport function curry(fn: (...args: any[]) => any): any {\n  // Each call returns a new function that remembers the arguments so far,\n  // so partially applied versions never share state.\n  const curried = (...args: any[]): any => (args.length >= fn.length ? fn(...args) : (...more: any[]) => curried(...args, ...more));\n  return curried;\n}\n"}'::jsonb),
  ('fp-set-in', null::text[], '{"en":"Recursing one key at a time means each level copies just its own container and plugs in the updated child, so siblings are shared for free. Checking `Object.is(current, next)` on the way back up returns original references when nothing changed, which keeps `===` comparisons (and memoised selectors) meaningful. This is the core of what Immer and Redux Toolkit do for you.","uk":"Рекурсія по одному ключу означає, що кожен рівень копіює лише власний контейнер і вставляє оновлену дитину, тож сусідні гілки спільні без зусиль. Перевірка `Object.is(current, next)` на зворотному шляху повертає початкові посилання, коли нічого не змінилося, що зберігає сенс порівнянь `===` (і мемоізованих селекторів). Саме це в основі того, що за вас роблять Immer і Redux Toolkit."}'::jsonb, '{"/src/immutable.ts":"export type Path = (string | number)[];\n\nexport function updateIn<T>(obj: T, path: Path, fn: (value: any) => any): T {\n  if (path.length === 0) return fn(obj);\n  const [key, ...rest] = path;\n  // Create missing containers: an array if the key is a number, otherwise an object.\n  const container: any = obj ?? (typeof key === \"number\" ? [] : {});\n  const current = container[key];\n  const next = updateIn(current, rest, fn);\n  // Nothing changed below: keep the original reference (no allocations, === still true).\n  if (Object.is(current, next) && obj != null) return obj;\n  const copy = Array.isArray(container) ? container.slice() : { ...container };\n  copy[key] = next;\n  return copy;\n}\n\nexport function setIn<T>(obj: T, path: Path, value: unknown): T {\n  return updateIn(obj, path, () => value);\n}\n"}'::jsonb),
  ('git-fetch-pull', array['a']::text[], '{"en":"`git fetch` is always safe: it updates `origin/*` without touching your working tree, so you can inspect incoming changes (`git log HEAD..origin/main`) first. `git pull` = fetch + integrate. Setting `pull.rebase` or `pull.ff=only` controls how it integrates.","uk":"`git fetch` завжди безпечний: він оновлює `origin/*`, не чіпаючи робочої копії, тож можна спершу переглянути вхідні зміни (`git log HEAD..origin/main`). `git pull` = fetch + інтеграція. Налаштування `pull.rebase` або `pull.ff=only` визначають, як саме відбувається інтеграція."}'::jsonb, null::jsonb),
  ('git-revert-merge', array['a']::text[], '{"en":"A merge commit has two parents, so Git needs to know which side is the mainline to keep. Parent 1 is the branch you merged into (`main`), so `-m 1` undoes the feature''s changes. Rewriting shared history with a force push is the wrong tool on `main`. Note: to re-merge the feature later, you must first revert the revert.","uk":"Коміт злиття має двох батьків, тож Git має знати, яку сторону вважати основною. Батько 1 — гілка, в яку зливали (`main`), тож `-m 1` скасовує зміни функції. Переписування спільної історії примусовим push — неправильний інструмент для `main`. Зауважте: щоб потім злити функцію знову, спершу потрібно скасувати цей revert."}'::jsonb, null::jsonb),
  ('git-ours-theirs-rebase', array['b']::text[], '{"en":"During a rebase, Git replays your commits on top of `main`, so \"ours\" is the branch being built (`main` plus already replayed commits) and \"theirs\" is the commit being replayed, which is yours. That is the reverse of a merge. Then `git add config.ts` and `git rebase --continue`.","uk":"Під час rebase Git перевідтворює ваші коміти поверх `main`, тож «ours» — гілка, що будується (`main` плюс уже перенесені коміти), а «theirs» — коміт, що переноситься, тобто ваш. Це протилежно до merge. Далі `git add config.ts` і `git rebase --continue`."}'::jsonb, null::jsonb),
  ('git-semver-bump', null::text[], '{"en":"Parse each header with one regex: type, optional `(scope)`, optional `!`, then `: `. Requiring `: ` right after the type is what rejects look-alikes such as `feature:` or `fixup!`. Each commit maps to a bump level, and the release takes the maximum. A multiline regex (`/m`) finds `BREAKING CHANGE:` at the start of any body line. Real tools such as semantic-release also treat 0.x versions specially.","uk":"Розбирайте кожен заголовок одним регулярним виразом: тип, необов''язкова `(область)`, необов''язковий `!`, потім `: `. Вимога `: ` одразу після типу відсікає схожі варіанти, як-от `feature:` чи `fixup!`. Кожен коміт дає рівень підвищення, а реліз бере максимум. Багаторядковий вираз (`/m`) знаходить `BREAKING CHANGE:` на початку будь-якого рядка тіла. Справжні інструменти, як-от semantic-release, ще й особливо обробляють версії 0.x."}'::jsonb, '{"/src/semver.ts":"type Bump = 0 | 1 | 2 | 3; // none, patch, minor, major\n\nconst HEADER = /^(\\w+)(\\([^)]*\\))?(!)?: /;\n\nfunction bumpFor(message: string): Bump {\n  const header = HEADER.exec(message);\n  if (!header) return 0;\n  const type = header[1].toLowerCase();\n  if (header[3] || /^BREAKING[ -]CHANGE: /m.test(message)) return 3;\n  if (type === \"feat\") return 2;\n  if (type === \"fix\" || type === \"perf\") return 1;\n  return 0;\n}\n\nexport function nextVersion(current: string, commits: string[]): string {\n  const [major, minor, patch] = current.split(\".\").map(Number);\n  const bump = commits.reduce<Bump>((max, message) => Math.max(max, bumpFor(message)) as Bump, 0);\n  if (bump === 3) return major + 1 + \".0.0\";\n  if (bump === 2) return major + \".\" + (minor + 1) + \".0\";\n  if (bump === 1) return major + \".\" + minor + \".\" + (patch + 1);\n  return current;\n}\n"}'::jsonb),
  ('git-merge-base', null::text[], '{"en":"Git''s history is a directed acyclic graph, so the first step is the set of ancestors of each commit: a graph walk along parent links. The common ancestors are the intersection of those sets. Not all of them are useful: if one common ancestor descends from another, the older one is already implied, so the best base is the one nothing else in the intersection builds on. Real git uses a smarter walk ordered by commit date, but the definition is the same. Note that merge commits give a second parent, which is why a plain \"walk the first parent\" approach fails on histories with merges, and why this walk follows every parent.","uk":"Історія Git є спрямованим ациклічним графом, тож перший крок — множина предків кожного коміту: обхід графа за посиланнями на батьків. Спільні предки — перетин цих множин. Не всі вони корисні: якщо один спільний предок є нащадком іншого, старший уже мається на увазі, тож найкраща база та, на яку ніщо інше в перетині не спирається. Справжній git використовує розумніший обхід за датою коміту, але визначення те саме. Зверніть увагу, що коміти злиття мають другого батька, тому простий обхід лише першого батька ламається на історіях зі злиттями, а цей обхід іде за всіма батьками."}'::jsonb, '{"/src/merge-base.ts":"export type Graph = Record<string, string[]>;\n\n/** Every commit reachable from start, including start itself. */\nfunction ancestors(graph: Graph, start: string): Set<string> {\n  if (!Object.prototype.hasOwnProperty.call(graph, start)) throw new Error(\"Unknown commit: \" + start);\n  const seen = new Set<string>();\n  const stack = [start];\n  while (stack.length > 0) {\n    const commit = stack.pop()!;\n    if (seen.has(commit)) continue;\n    seen.add(commit);\n    for (const parent of graph[commit]) stack.push(parent);\n  }\n  return seen;\n}\n\nexport function mergeBase(graph: Graph, a: string, b: string): string | null {\n  const fromA = ancestors(graph, a);\n  const fromB = ancestors(graph, b);\n  const common = [...fromA].filter((commit) => fromB.has(commit));\n  // A \"best\" base is a common ancestor that no other common ancestor descends from.\n  const best = common.filter((c) => !common.some((d) => d !== c && ancestors(graph, d).has(c)));\n  // Criss-cross merges can leave several best bases: return the smallest id, so the answer is stable.\n  return best.length > 0 ? best.sort()[0] : null;\n}\n"}'::jsonb),
  ('git-staging', array['a']::text[], '{"en":"The staging area decides what goes into the next commit. `git add <file>` (or `git add -p` for parts of a file) stages exactly what you want. `commit -a` would include every tracked modified file.","uk":"Індекс визначає, що потрапить у наступний коміт. `git add <file>` (або `git add -p` для частин файлу) додає саме те, що потрібно. `commit -a` включив би всі змінені відстежувані файли."}'::jsonb, null::jsonb),
  ('git-revert-vs-reset', array['a']::text[], '{"en":"`revert` adds a new commit that inverts the changes, so history stays intact and teammates aren''t affected. Resetting and force-pushing rewrites shared history and breaks everyone who already pulled.","uk":"`revert` додає новий коміт, що скасовує зміни, тож історія лишається цілою й колеги не постраждають. Reset з force-push переписує спільну історію й ламає роботу всім, хто вже отримав зміни."}'::jsonb, null::jsonb),
  ('git-rebase-golden-rule', array['a']::text[], '{"en":"Rebasing creates new commits. Anyone who based work on the old ones now has a history Git sees as different, which leads to duplicated commits and painful merges. Rebase private branches; merge or revert on shared ones.","uk":"Rebase створює нові коміти. Кожен, хто працював на основі старих, тепер має історію, яку Git вважає іншою, що призводить до дубльованих комітів і болісних злиттів. Робіть rebase приватних гілок, а для спільних використовуйте merge чи revert."}'::jsonb, null::jsonb),
  ('git-reflog', array['a']::text[], '{"en":"The reflog records where HEAD and branches pointed recently, including commits no longer reachable from any branch. They stay recoverable until garbage collection (typically 30+ days).","uk":"Reflog записує, куди нещодавно вказували HEAD і гілки, включно з комітами, недосяжними з жодної гілки. Їх можна відновити, доки їх не прибере збирач сміття (зазвичай 30+ днів)."}'::jsonb, null::jsonb),
  ('git-bisect', array['a']::text[], '{"en":"Bisect is a binary search over history: each good/bad answer halves the range, so log₂(1000) ≈ 10 steps. With `git bisect run <test-script>` it can be fully automated.","uk":"Bisect є бінарним пошуком по історії: кожна відповідь good/bad вдвічі звужує діапазон, тож потрібно log₂(1000) ≈ 10 кроків. З `git bisect run <test-script>` процес можна повністю автоматизувати."}'::jsonb, null::jsonb),
  ('gql-what-it-solves', array['a']::text[], '{"en":"GraphQL lets the client describe the shape of the data, so there''s no over-fetching (unused fields) and no under-fetching (extra round trips for related data). It doesn''t make the database faster, it usually returns JSON, and HTTP caching is actually harder because queries are typically POSTed to one endpoint.","uk":"GraphQL дає клієнту змогу описати форму даних, тож немає зайвих полів і немає додаткових запитів за пов''язаними даними. Він не робить базу швидшою, зазвичай повертає JSON, а HTTP-кешування навіть складніше, бо запити зазвичай надсилають через POST на один ендпоінт."}'::jsonb, null::jsonb),
  ('gql-schema-nullability', array['a']::text[], '{"en":"`!` after a type means non-null. The inner `!` applies to each item, the outer one to the list. An empty list `[]` is still a valid non-null list. `[Post]` (no `!`) would allow both a `null` list and `null` items.","uk":"`!` після типу означає «не null». Внутрішній `!` стосується кожного елемента, зовнішній самого списку. Порожній список `[]` теж є дійсним ненульовим списком. `[Post]` (без `!`) дозволив би і `null` замість списку, і `null` серед елементів."}'::jsonb, null::jsonb),
  ('gql-errors-200', array['a']::text[], '{"en":"In GraphQL a request can partly succeed: fields that resolved appear in `data`, and failures are listed in `errors` with a `path` to the failing field, typically with HTTP 200. Status codes mostly signal transport problems (malformed request, auth at the gateway). Always handle `errors`, and decide per screen whether partial data is usable.","uk":"У GraphQL запит може вдатися частково: розв''язані поля з''являються в `data`, а невдачі перелічені в `errors` зі шляхом (`path`) до поля, зазвичай зі статусом HTTP 200. Коди статусу здебільшого сигналізують про проблеми транспорту (неправильний запит, автентифікація на шлюзі). Завжди обробляйте `errors` і вирішуйте для кожного екрана, чи придатні часткові дані."}'::jsonb, null::jsonb),
  ('gql-n-plus-one', array['a']::text[], '{"en":"GraphQL runs `Post.author` once per post, and each call queries the database separately: 1 + N queries. DataLoader collects the `load(id)` calls made while resolving one level, deduplicates the ids, and runs a single `WHERE id IN (…)` query, with a per-request cache. An index makes each query faster but doesn''t reduce their number.","uk":"GraphQL виконує `Post.author` для кожного допису, і кожен виклик окремо звертається до бази: 1 + N запитів. DataLoader збирає виклики `load(id)`, зроблені під час розв''язання одного рівня, прибирає дублікати й виконує один запит `WHERE id IN (…)` з кешем на запит. Індекс пришвидшує кожен запит, але не зменшує їхню кількість."}'::jsonb, null::jsonb),
  ('gql-variables', array['a']::text[], '{"en":"Splicing input into the query text is the GraphQL version of injection: a crafted value can add fields or arguments. Variables are sent separately as JSON and checked against the declared types (`$id: ID!`). Because the text never changes, clients can use persisted queries (sending only a hash) and servers can cache parsed documents.","uk":"Вставлення даних у текст запиту є GraphQL-версією ін''єкції: підготовлене значення може додати поля чи аргументи. Змінні надсилаються окремо як JSON і перевіряються за оголошеними типами (`$id: ID!`). Оскільки текст не змінюється, клієнти можуть використовувати збережені запити (надсилаючи лише хеш), а сервери кешувати розібрані документи."}'::jsonb, null::jsonb),
  ('gql-null-bubbling', array['a']::text[], '{"en":"`name` is non-null, so it can''t be replaced by `null`. The `null` propagates to the nearest nullable parent, which is `user: User`, so the whole user (including `email`) is `null`. If `user` were also non-null, it would bubble up to `data`. Choosing nullability is a trade-off between strong guarantees and resilience to partial failures.","uk":"`name` є обов''язковим, тож його не можна замінити на `null`. `null` піднімається до найближчого батька, що допускає null, тобто `user: User`, тож увесь користувач (разом з `email`) стає `null`. Якби `user` теж був обов''язковим, null піднявся б до `data`. Вибір обов''язковості є компромісом між сильними гарантіями й стійкістю до часткових збоїв."}'::jsonb, null::jsonb),
  ('gql-normalized-cache', array['a']::text[], '{"en":"Every object is stored once under its `__typename` and `id`, and queries hold references to it, so returning the updated `{ id, name }` refreshes every view of that project. A brand-new object has no references yet: deciding that it belongs at the top of \"my projects\" is application logic. Add it in the mutation''s `update` function, or use `refetchQueries` for the affected list.","uk":"Кожен об''єкт зберігається один раз за своїм `__typename` та `id`, а запити тримають посилання на нього, тож повернення оновленого `{ id, name }` оновлює кожне відображення цього проєкту. Зовсім новий об''єкт ще не має посилань: рішення, що він має з''явитися на початку «моїх проєктів», є логікою застосунку. Додайте його у функції `update` мутації або використайте `refetchQueries` для відповідного списку."}'::jsonb, null::jsonb),
  ('gql-query-cost', array['a', 'b', 'c']::text[], '{"en":"One GraphQL request can ask for millions of nodes (`posts { author { posts { author { … } } } }`), so counting requests alone doesn''t bound the work. Reject queries that are too deep or too costly before execution, cap and paginate lists, and, for first-party apps, allow only known persisted queries. GET vs POST changes caching, not cost.","uk":"Один GraphQL-запит може попросити мільйони вузлів (`posts { author { posts { author { … } } } }`), тож підрахунок лише кількості запитів не обмежує обсяг роботи. Відхиляйте занадто глибокі чи дорогі запити до виконання, обмежуйте й пагінуйте списки, а для власних застосунків дозволяйте лише відомі збережені запити. GET чи POST впливає на кешування, а не на вартість."}'::jsonb, null::jsonb),
  ('gql-dataloader', null::text[], '{"en":"`load` doesn''t fetch; it registers a pending promise in a queue and schedules one dispatch for later. Because the dispatch waits for the next task, every resolver at the same level of the query, even after its own `await`s, has added its key by then. The cache stores promises (not values), so concurrent requests for the same key share one in-flight load. Mapping results back by position and rejecting per key keeps one bad id from failing the whole list.","uk":"`load` нічого не завантажує одразу; він реєструє проміс, що очікує, у черзі й планує одне надсилання на потім. Оскільки надсилання чекає наступної задачі, кожен резолвер того самого рівня запиту, навіть після власних `await`, на той момент уже додав свій ключ. Кеш зберігає проміси (а не значення), тож одночасні запити того самого ключа ділять одне завантаження. Зіставлення результатів за позицією й відхилення окремих ключів не дає одному поганому id зіпсувати весь список."}'::jsonb, '{"/src/dataloader.ts":"export type BatchFn<K, V> = (keys: readonly K[]) => Promise<readonly (V | Error)[]>;\n\ntype Pending<V> = { resolve: (value: V) => void; reject: (error: unknown) => void };\n\nexport class DataLoader<K, V> {\n  private cache = new Map<K, Promise<V>>();\n  private queue = new Map<K, Pending<V>>(); // a Map deduplicates keys and keeps first-request order\n  private scheduled = false;\n\n  constructor(private readonly batchFn: BatchFn<K, V>, private readonly options: { maxBatchSize?: number } = {}) {}\n\n  load(key: K): Promise<V> {\n    const cached = this.cache.get(key);\n    if (cached) return cached;\n    const promise = new Promise<V>((resolve, reject) => this.queue.set(key, { resolve, reject }));\n    this.cache.set(key, promise);\n    if (!this.scheduled) {\n      this.scheduled = true;\n      // Wait for the current task (and its microtasks) so resolvers awaiting other data join the batch.\n      setTimeout(() => this.dispatch(), 0);\n    }\n    return promise;\n  }\n\n  loadMany(keys: readonly K[]): Promise<V[]> {\n    return Promise.all(keys.map((key) => this.load(key)));\n  }\n\n  clear(key: K): this {\n    this.cache.delete(key);\n    return this;\n  }\n\n  private dispatch() {\n    this.scheduled = false;\n    const entries = [...this.queue.entries()];\n    this.queue.clear();\n    const size = this.options.maxBatchSize ?? Infinity;\n    for (let i = 0; i < entries.length; i += size) void this.runBatch(entries.slice(i, i + size));\n  }\n\n  private async runBatch(batch: [K, Pending<V>][]) {\n    const fail = (key: K, pending: Pending<V>, error: unknown) => {\n      this.cache.delete(key); // don''t cache failures, so a later load can retry\n      pending.reject(error);\n    };\n    const keys = batch.map(([key]) => key);\n    let results: readonly (V | Error)[];\n    try {\n      results = await this.batchFn(keys);\n      if (!Array.isArray(results) || results.length !== keys.length) {\n        throw new Error(\"batchFn must return an array with one result per key\");\n      }\n    } catch (error) {\n      for (const [key, pending] of batch) fail(key, pending, error);\n      return;\n    }\n    batch.forEach(([key, pending], i) => {\n      const result = results[i];\n      if (result instanceof Error) fail(key, pending, result);\n      else pending.resolve(result);\n    });\n  }\n}\n"}'::jsonb),
  ('graph-representation', array['a']::text[], '{"en":"With V = 10⁶, a matrix needs 10¹² cells, almost all empty. An adjacency list stores only existing edges (about 2 × 10⁸ entries) and iterates a user''s friends in O(degree). Matrices only make sense for small or dense graphs, or when O(1) edge lookups dominate.","uk":"За V = 10⁶ матриця потребує 10¹² клітинок, майже всі порожні. Список суміжності зберігає лише наявні ребра (близько 2 × 10⁸ записів) і перебирає друзів користувача за O(степінь). Матриці мають сенс лише для малих чи щільних графів або коли домінують перевірки ребра за O(1)."}'::jsonb, null::jsonb),
  ('graph-dfs-bfs-order', array['a']::text[], '{"en":"DFS follows one branch to the end before backtracking: A → B → D, then back to C (D is already seen). BFS visits all neighbours of A (B, C) before moving one level further (D). The shared `seen` set stops D from being visited twice.","uk":"DFS проходить одну гілку до кінця, перш ніж повернутися: A → B → D, потім назад до C (D уже побачено). BFS відвідує всіх сусідів A (B, C), перш ніж перейти на рівень далі (D). Спільна множина `seen` не дає відвідати D двічі."}'::jsonb, null::jsonb),
  ('graph-topological-use', array['a']::text[], '{"en":"A topological order lists nodes so every edge points forward, which is exactly \"dependencies first\". It exists only when there''s no cycle: if A needs B and B needs A, neither can go first. Bundlers, `tsc --build`, Nx and Turborepo all order work this way and report cycles as errors.","uk":"Топологічний порядок перелічує вершини так, що кожне ребро веде вперед, а це й означає «спершу залежності». Він існує лише за відсутності циклів: якщо A потребує B, а B потребує A, жоден не може бути першим. Бандлери, `tsc --build`, Nx і Turborepo впорядковують роботу саме так і повідомляють про цикли як про помилки."}'::jsonb, null::jsonb),
  ('graph-cycle-false-positive', array['a']::text[], '{"en":"Reaching an already visited node is only a cycle if that node is still **on the current DFS path** (a back edge). Here D was fully explored via B, so reaching it again via C is just a second route. Use two sets (or colours): \"visiting\" for the current path and \"done\" for finished nodes.","uk":"Досягнення вже відвіданої вершини є циклом, лише якщо ця вершина досі **на поточному шляху DFS** (зворотне ребро). Тут D повністю оброблено через B, тож повторне досягнення через C є просто другим маршрутом. Використовуйте дві множини (або кольори): «відвідується» для поточного шляху й «завершено» для оброблених вершин."}'::jsonb, null::jsonb),
  ('graph-components', array['a']::text[], '{"en":"The components are {1, 2, 3}, {4, 5}, {6, 7} and {8}: an isolated node is a component on its own. To count them, start a BFS/DFS from every node that hasn''t been seen yet and count the starts (O(V + E)), or merge edges with union-find.","uk":"Компоненти: {1, 2, 3}, {4, 5}, {6, 7} і {8}: ізольована вершина сама є компонентою. Щоб їх порахувати, запускайте BFS/DFS із кожної ще не побаченої вершини й рахуйте запуски (O(V + E)) або об''єднуйте ребра через union-find."}'::jsonb, null::jsonb),
  ('graph-dijkstra-negative', array['a']::text[], '{"en":"Dijkstra''s correctness relies on paths only getting longer as you add edges. With a negative edge, a node already taken from the queue could be reached more cheaply later. Bellman-Ford relaxes every edge V − 1 times (O(V·E)) and can also detect negative cycles, where no shortest path exists.","uk":"Коректність Дейкстри спирається на те, що шляхи лише довшають із додаванням ребер. З від''ємним ребром до вершини, вже взятої з черги, згодом можна дістатися дешевше. Беллман-Форд релаксує кожне ребро V − 1 разів (O(V·E)) і також виявляє від''ємні цикли, коли найкоротшого шляху не існує."}'::jsonb, null::jsonb),
  ('graph-bfs-mark-when', array['a']::text[], '{"en":"Between being discovered and being dequeued, a node can be discovered again by every other neighbour, so the queue may hold up to O(E) entries instead of O(V). Distances stay correct (the first copy dequeued has the smallest level), but the work and memory blow up. Mark nodes as seen at the moment you enqueue them.","uk":"Між виявленням і вийманням із черги вершину можуть знову виявити всі інші сусіди, тож черга може містити до O(E) записів замість O(V). Відстані лишаються правильними (перша вийнята копія має найменший рівень), але робота й пам''ять різко зростають. Позначайте вершини як побачені в момент додавання в чергу."}'::jsonb, null::jsonb),
  ('graph-kahn-order', array['a']::text[], '{"en":"Initially only `db` and `utils` have no dependencies; alphabetically `db` goes first. It releases nothing yet (`api` still needs `utils`). Then `utils` releases both `ui` and `api`; alphabetically `api` comes first, then `ui`, and finally `app`, whose dependencies are now all done.","uk":"Спочатку лише `db` і `utils` не мають залежностей; за алфавітом першим іде `db`. Він ще нічого не вивільняє (`api` досі потребує `utils`). Потім `utils` вивільняє і `ui`, і `api`; за алфавітом спершу `api`, потім `ui`, і нарешті `app`, усі залежності якого вже готові."}'::jsonb, null::jsonb),
  ('graph-dfs-postorder', array['a']::text[], '{"en":"Post-order guarantees that by the time a package is appended, every package it depends on has already been appended. Pre-order would list `app` before `react`. (If edges point the other way, from a dependency to its dependents, you''d reverse the post-order instead.) Add a \"visiting\" set to report cycles.","uk":"Post-order гарантує, що на момент додавання пакета кожен пакет, від якого він залежить, уже додано. Pre-order вивів би `app` раніше за `react`. (Якщо ребра напрямлені навпаки, від залежності до залежних, post-order треба розвернути.) Додайте множину «відвідується», щоб повідомляти про цикли."}'::jsonb, null::jsonb),
  ('graph-build-order', null::text[], '{"en":"Kahn''s algorithm counts unmet dependencies, starts from packages with none, and releases dependents as their counts reach zero; sorting the ready list makes ties deterministic. Packages that are never released are exactly those on or behind a cycle, so a DFS that tracks the current path over the remaining packages finds and reports one. Total cost is O(V + E) plus the sorting of ready packages.","uk":"Алгоритм Кана рахує незадоволені залежності, починає з пакетів без них і вивільняє залежні пакети, коли їхні лічильники доходять до нуля; сортування списку готових робить нічиї детермінованими. Пакети, які так і не вивільнилися, лежать на циклі або за ним, тож DFS із відстеженням поточного шляху по решті пакетів знаходить і повідомляє цикл. Загальна вартість O(V + E) плюс сортування готових пакетів."}'::jsonb, '{"/src/order.ts":"export class CycleError extends Error {\n  constructor(readonly cycle: string[]) {\n    super(\"Dependency cycle: \" + cycle.join(\" -> \"));\n    this.name = \"CycleError\";\n  }\n}\n\nexport function buildOrder(deps: Record<string, string[]>): string[] {\n  // Every package, including ones that only appear as dependencies.\n  const nodes = new Set<string>();\n  for (const [pkg, list] of Object.entries(deps)) {\n    nodes.add(pkg);\n    list.forEach((d) => nodes.add(d));\n  }\n\n  // Kahn''s algorithm: count unmet dependencies, release packages when they reach zero.\n  const unmet = new Map<string, number>();\n  const dependents = new Map<string, string[]>();\n  for (const n of nodes) {\n    unmet.set(n, 0);\n    dependents.set(n, []);\n  }\n  for (const [pkg, list] of Object.entries(deps)) {\n    for (const d of new Set(list)) {\n      unmet.set(pkg, unmet.get(pkg)! + 1);\n      dependents.get(d)!.push(pkg);\n    }\n  }\n\n  const ready = [...nodes].filter((n) => unmet.get(n) === 0);\n  const order: string[] = [];\n  while (ready.length) {\n    ready.sort(); // deterministic: alphabetical among packages that are ready\n    const next = ready.shift()!;\n    order.push(next);\n    for (const dependent of dependents.get(next)!) {\n      const left = unmet.get(dependent)! - 1;\n      unmet.set(dependent, left);\n      if (left === 0) ready.push(dependent);\n    }\n  }\n\n  if (order.length < nodes.size) throw new CycleError(findCycle(deps, new Set(order)));\n  return order;\n}\n\n/** DFS that tracks the current path: reaching a node already on the path closes a cycle. */\nfunction findCycle(deps: Record<string, string[]>, done: Set<string>): string[] {\n  const state = new Map<string, \"visiting\" | \"visited\">();\n  const path: string[] = [];\n  const visit = (node: string): string[] | null => {\n    if (state.get(node) === \"visiting\") return [...path.slice(path.indexOf(node)), node];\n    if (state.get(node) === \"visited\" || done.has(node)) return null;\n    state.set(node, \"visiting\");\n    path.push(node);\n    for (const d of deps[node] ?? []) {\n      const cycle = visit(d);\n      if (cycle) return cycle;\n    }\n    path.pop();\n    state.set(node, \"visited\");\n    return null;\n  };\n  for (const node of Object.keys(deps).sort()) {\n    const cycle = visit(node);\n    if (cycle) return cycle;\n  }\n  return [];\n}\n"}'::jsonb),
  ('graph-shortest-route', null::text[], '{"en":"Dijkstra always expands the closest unfinished node, taken from a min-heap, and relaxes its edges; with non-negative weights the first time a node is popped its distance is final. Instead of a decrease-key operation, it pushes duplicates and skips entries whose key is larger than the best known distance. Predecessors recorded during relaxation rebuild the path. Cost: O((V + E) log V).","uk":"Дейкстра завжди розширює найближчу незавершену вершину, взяту з мін-купи, і релаксує її ребра; з невід''ємними вагами відстань вершини стає остаточною, щойно її вперше вийнято. Замість операції зменшення ключа алгоритм додає дублікати й пропускає записи, чий ключ більший за найкращу відому відстань. Попередники, записані під час релаксації, відновлюють шлях. Вартість: O((V + E) log V)."}'::jsonb, '{"/src/route.ts":"export type Edge = [from: string, to: string, weight: number];\nexport type Route = { distance: number; path: string[] };\n\nclass MinHeap<T> {\n  private items: { key: number; value: T }[] = [];\n  get size() {\n    return this.items.length;\n  }\n  push(key: number, value: T) {\n    const a = this.items;\n    a.push({ key, value });\n    let i = a.length - 1;\n    while (i > 0) {\n      const parent = (i - 1) >> 1;\n      if (a[parent].key <= a[i].key) break;\n      [a[parent], a[i]] = [a[i], a[parent]];\n      i = parent;\n    }\n  }\n  pop() {\n    const a = this.items;\n    const top = a[0];\n    const last = a.pop()!;\n    if (a.length) {\n      a[0] = last;\n      let i = 0;\n      for (;;) {\n        const l = 2 * i + 1;\n        const r = l + 1;\n        let m = i;\n        if (l < a.length && a[l].key < a[m].key) m = l;\n        if (r < a.length && a[r].key < a[m].key) m = r;\n        if (m === i) break;\n        [a[m], a[i]] = [a[i], a[m]];\n        i = m;\n      }\n    }\n    return top;\n  }\n}\n\nexport function shortestPath(edges: Edge[], start: string, end: string, options: { directed?: boolean } = {}): Route | null {\n  const graph = new Map<string, [string, number][]>();\n  const link = (a: string, b: string, w: number) => {\n    if (!graph.has(a)) graph.set(a, []);\n    graph.get(a)!.push([b, w]);\n  };\n  for (const [a, b, w] of edges) {\n    if (!(w >= 0)) throw new RangeError(\"Dijkstra needs non-negative weights: \" + a + \" - \" + b + \" = \" + w);\n    link(a, b, w);\n    if (!options.directed) link(b, a, w);\n  }\n  if (start === end) return { distance: 0, path: [start] };\n\n  const dist = new Map<string, number>([[start, 0]]);\n  const prev = new Map<string, string>();\n  const heap = new MinHeap<string>();\n  heap.push(0, start);\n  while (heap.size) {\n    const { key: d, value: node } = heap.pop();\n    if (d > (dist.get(node) ?? Infinity)) continue; // stale entry: a shorter route was found later\n    if (node === end) break;\n    for (const [next, w] of graph.get(node) ?? []) {\n      const candidate = d + w;\n      if (candidate < (dist.get(next) ?? Infinity)) {\n        dist.set(next, candidate);\n        prev.set(next, node);\n        heap.push(candidate, next);\n      }\n    }\n  }\n\n  if (!dist.has(end)) return null;\n  const path = [end];\n  while (path[0] !== start) path.unshift(prev.get(path[0])!);\n  return { distance: dist.get(end)!, path };\n}\n"}'::jsonb),
  ('html-dialog-modal', array['a', 'b', 'c']::text[], '{"en":"`showModal()` opens the dialog in the top layer with a `::backdrop`, makes everything else inert and closes it on Escape (firing `cancel`). `show()` opens a non-modal dialog in normal flow, without any of that. Forms with `method=\"dialog\"` close the dialog on submit; nothing is submitted automatically.","uk":"`showModal()` відкриває діалог у верхньому шарі з `::backdrop`, робить решту сторінки інертною й закриває його за Escape (з подією `cancel`). `show()` відкриває немодальний діалог у звичайному потоці без усього цього. Форми з `method=\"dialog\"` закривають діалог під час надсилання; нічого не надсилається автоматично."}'::jsonb, null::jsonb),
  ('html-preload-lcp', array['a']::text[], '{"en":"An `<img>` in the HTML is found by the preload scanner immediately, and `fetchpriority=\"high\"` moves it ahead of other images. If it must stay a background, `rel=\"preload\"` makes it discoverable early. Lazy-loading the LCP image delays it further, `prefetch` is a low-priority hint for future navigations, and moving the CSS causes unstyled flashes.","uk":"`<img>` у HTML одразу знаходить сканер попереднього завантаження, а `fetchpriority=\"high\"` ставить його попереду інших зображень. Якщо зображення мусить лишатися фоном, `rel=\"preload\"` робить його видимим браузеру рано. Ліниве завантаження LCP-зображення ще більше його затримає, `prefetch` — низькопріоритетна підказка для майбутніх переходів, а перенесення CSS спричинить спалахи нестилізованого вмісту."}'::jsonb, null::jsonb),
  ('html-srcset-sizes', array['c']::text[], '{"en":"`sizes` says the image is 50vw wide on this viewport, so the slot is 500 CSS px. At DPR 2 the browser needs about 1000 device pixels and picks the smallest candidate that covers it: `hero-960.jpg` is too small, so it takes `hero-1440.jpg`. Without `sizes`, the browser would assume 100vw and need 2000 pixels. Only one file is downloaded.","uk":"`sizes` каже, що на цьому вікні зображення має ширину 50vw, тобто слот — 500 CSS-пікселів. За DPR 2 браузеру потрібно близько 1000 фізичних пікселів, і він бере найменшого кандидата, що їх покриває: `hero-960.jpg` замалий, тож буде `hero-1440.jpg`. Без `sizes` браузер вважав би ширину 100vw і потребував би 2000 пікселів. Завантажується лише один файл."}'::jsonb, null::jsonb),
  ('html-button-vs-div', array['a']::text[], '{"en":"A native button gets keyboard focus, the `button` role for assistive technology, Enter/Space activation and form submission semantics for free. A div needs `role`, `tabindex` and key handlers to approximate that.","uk":"Нативна кнопка безкоштовно отримує фокус клавіатури, роль `button` для допоміжних технологій, активацію Enter/Space і семантику надсилання форми. Div потребує `role`, `tabindex` і обробників клавіш, щоб лише наблизитися до цього."}'::jsonb, null::jsonb),
  ('html-defer-async', array['b']::text[], '{"en":"Deferred scripts download in parallel and execute after parsing, in document order. Async scripts run as soon as each one arrives, so their order isn''t guaranteed. Plain scripts block the parser.","uk":"Відкладені (defer) скрипти завантажуються паралельно й виконуються після розбору в порядку документа. Async-скрипти виконуються, щойно кожен надійде, тож порядок не гарантовано. Звичайні скрипти блокують розбір."}'::jsonb, null::jsonb),
  ('html-button-default-type', array['a']::text[], '{"en":"Buttons in forms submit by default. Add `type=\"button\"` to buttons that aren''t meant to submit, or call `preventDefault()` in the submit handler.","uk":"Кнопки у формах за замовчуванням надсилають форму. Додайте `type=\"button\"` кнопкам, які не повинні надсилати, або викликайте `preventDefault()` в обробнику submit."}'::jsonb, null::jsonb),
  ('html-label-association', array['a', 'b', 'd']::text[], '{"en":"An explicit `for`/`id` pair, a wrapping label and `aria-label` all name the field. A placeholder is only a fallback hint: it vanishes while typing, often has poor contrast, and shouldn''t replace a label.","uk":"Явна пара `for`/`id`, обгортальна мітка й `aria-label` дають полю ім''я. Placeholder є лише запасною підказкою: зникає під час введення, часто має слабкий контраст і не повинен замінювати мітку."}'::jsonb, null::jsonb),
  ('html-heading-order', array['b']::text[], '{"en":"Heading levels describe the outline, not the visual size. Skipping from h1 to h4 confuses screen-reader navigation and the document outline. Use the correct level and adjust its look with CSS.","uk":"Рівні заголовків описують структуру, а не візуальний розмір. Перехід від h1 одразу до h4 плутає навігацію зчитувачів екрана й структуру документа. Використайте правильний рівень і змініть вигляд через CSS."}'::jsonb, null::jsonb),
  ('html-semantic-signup-form', null::text[], '{"en":"Semantic elements carry their meaning to browsers and assistive technology: `<main>` and `<h1>` structure the page, each `<label>` names its control, the input types and `autocomplete` give the right keyboard and autofill, `required`/`minlength` add native validation, and a `<button type=\"submit\">` submits the form with the keyboard too.","uk":"Семантичні елементи передають своє значення браузерам і допоміжним технологіям: `<main>` і `<h1>` структурують сторінку, кожен `<label>` дає ім''я своєму полю, типи полів і `autocomplete` дають правильну клавіатуру й автозаповнення, `required`/`minlength` додають нативну валідацію, а `<button type=\"submit\">` надсилає форму й з клавіатури."}'::jsonb, '{"/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Sign up</title>\n</head>\n<body>\n  <main>\n    <h1>Create your account</h1>\n    <form>\n      <label for=\"email\">Email</label>\n      <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required />\n\n      <label for=\"password\">Password</label>\n      <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" required />\n\n      <label>\n        <input type=\"checkbox\" name=\"terms\" required />\n        I accept the terms\n      </label>\n\n      <button type=\"submit\">Create account</button>\n    </form>\n  </main>\n\n  <script src=\"index.js\"></script>\n</body>\n</html>\n"}'::jsonb),
  ('http-put-patch', array['b']::text[], '{"en":"`PUT` replaces the whole resource with the body, so sending only the email would, strictly, clear the other fields. `PATCH` applies a partial update. Changing state with `GET` is never acceptable: it must be safe, and it gets cached, prefetched and logged.","uk":"`PUT` замінює весь ресурс тілом запиту, тож надсилання лише email, строго кажучи, очистило б інші поля. `PATCH` застосовує часткове оновлення. Змінювати стан через `GET` неприпустимо: він має бути безпечним, а ще його кешують, завантажують наперед і логують."}'::jsonb, null::jsonb),
  ('http-if-match', array['b']::text[], '{"en":"This is optimistic concurrency control. The `ETag` identifies the version the editor loaded. With `If-Match`, the server applies the write only if the current version still matches, and otherwise returns 412, so the client can reload and merge. `If-None-Match: *` is the opposite guard: create only if the resource doesn''t exist yet.","uk":"Це оптимістичне керування конкурентністю. `ETag` ідентифікує версію, яку завантажив редактор. З `If-Match` сервер застосовує запис, лише якщо поточна версія досі збігається, інакше повертає 412, і клієнт може перезавантажити й об''єднати зміни. `If-None-Match: *` — протилежна умова: створити, лише якщо ресурсу ще немає."}'::jsonb, null::jsonb),
  ('http-idempotency-key', array['b']::text[], '{"en":"The client generates a unique key per logical operation and sends it with every attempt. The server records the key with the outcome (atomically, handling concurrent duplicates) and replays the stored response for repeats, turning a non-idempotent POST into a safely retryable one. This is how payment APIs such as Stripe work. Waiting doesn''t remove the ambiguity.","uk":"Клієнт генерує унікальний ключ на кожну логічну операцію й надсилає його з кожною спробою. Сервер записує ключ разом із результатом (атомарно, з обробкою одночасних дублів) і повертає збережену відповідь на повтори — так неідемпотентний POST стає безпечним для повторів. Так працюють платіжні API, як-от Stripe. Очікування не прибирає невизначеності."}'::jsonb, null::jsonb),
  ('http-paginate-link', null::text[], '{"en":"Split the header into comma-separated links, then pull the URL out of `<...>` and the `rel` value from its parameter (a `rel` can list several space-separated names). `fetchAll` is a loop, not recursion: request, check `ok`, append, then read the next URL from the response. The page cap protects against a server that links a page to itself. Splitting on commas is fine for typical APIs; a URL that contains a comma needs a real parser.","uk":"Розбийте заголовок на посилання, розділені комами, потім витягніть URL з `<...>` і значення `rel` з його параметра (`rel` може містити кілька імен через пробіл). `fetchAll` — цикл, а не рекурсія: запит, перевірка `ok`, додавання, потім читання наступного URL з відповіді. Обмеження кількості сторінок захищає від сервера, що посилається сторінкою на саму себе. Розбиття за комами підходить для типових API; URL із комою потребує справжнього парсера."}'::jsonb, '{"/src/paginate.ts":"export type PageResponse = {\n  ok: boolean;\n  status: number;\n  headers: { get(name: string): string | null };\n  json(): Promise<unknown>;\n};\nexport type Fetcher = (url: string) => Promise<PageResponse>;\n\nconst MAX_PAGES = 50;\n\nexport function parseLink(header: string | null): Record<string, string> {\n  const links: Record<string, string> = {};\n  if (!header) return links;\n  for (const part of header.split(\",\")) {\n    const url = /<([^>]*)>/.exec(part)?.[1];\n    const rel = /rel=\"?([^\";]+)\"?/.exec(part)?.[1];\n    if (url && rel) for (const name of rel.trim().split(/\\s+/)) links[name] = url;\n  }\n  return links;\n}\n\nexport async function fetchAll<T>(url: string, fetcher: Fetcher): Promise<T[]> {\n  const items: T[] = [];\n  let next: string | undefined = url;\n  for (let page = 0; next && page < MAX_PAGES; page++) {\n    const response = await fetcher(next);\n    if (!response.ok) throw new Error(\"HTTP \" + response.status + \" for \" + next);\n    items.push(...((await response.json()) as T[]));\n    next = parseLink(response.headers.get(\"link\")).next;\n  }\n  return items;\n}\n"}'::jsonb),
  ('http-401-vs-403', array['b']::text[], '{"en":"401 means \"we don''t know who you are\": missing or invalid credentials. 403 means \"we know who you are, but you''re not allowed\". Some APIs return 404 to hide that a resource exists at all, a deliberate trade-off.","uk":"401 означає «ми не знаємо, хто ви»: облікові дані відсутні чи недійсні. 403 означає «ми знаємо, хто ви, але вам не дозволено». Деякі API повертають 404, щоб приховати саме існування ресурсу; це свідомий компроміс."}'::jsonb, null::jsonb),
  ('http-idempotent-methods', array['a', 'c', 'd']::text[], '{"en":"Repeating GET, PUT (replace with the same representation) or DELETE leaves the server in the same state as doing it once, so clients can retry them safely. POST may create a new resource each time; use an idempotency key for safe retries.","uk":"Повторення GET, PUT (заміна тим самим представленням) чи DELETE залишає сервер у тому ж стані, що й одне виконання, тож клієнти можуть безпечно повторювати їх. POST може щоразу створювати новий ресурс; для безпечних повторів використовуйте ключ ідемпотентності."}'::jsonb, null::jsonb),
  ('http-cors-preflight', array['a']::text[], '{"en":"PUT and a JSON content type are not \"simple\", so the browser asks first with `OPTIONS` (including `Access-Control-Request-Method`/`-Headers`). The server must reply with matching `Access-Control-Allow-*` headers. The fix belongs on the server, not in the client.","uk":"PUT і тип вмісту JSON не є «простими», тож браузер спершу питає дозволу через `OPTIONS` (з `Access-Control-Request-Method`/`-Headers`). Сервер має відповісти відповідними заголовками `Access-Control-Allow-*`. Виправлення робиться на сервері, а не в клієнті."}'::jsonb, null::jsonb),
  ('http-cache-control', array['b']::text[], '{"en":"A content hash means the URL changes whenever the file changes, so the response can be cached for a year without revalidation. The HTML that references it should use `no-cache` so users pick up new hashes.","uk":"Хеш вмісту означає, що URL змінюється разом із файлом, тож відповідь можна кешувати рік без перевірки. HTML, що на неї посилається, має використовувати `no-cache`, щоб користувачі отримували нові хеші."}'::jsonb, null::jsonb),
  ('http-rest-create', array['b']::text[], '{"en":"201 signals that a resource was created, and `Location` tells the client its URL. Returning the representation saves an extra GET.","uk":"201 повідомляє, що ресурс створено, а `Location` повідомляє клієнту його URL. Повернення представлення в тілі заощаджує додатковий GET."}'::jsonb, null::jsonb),
  ('i18n-plural-categories', array['a']::text[], '{"en":"Plural rules come from CLDR, and they differ by language: Arabic has six categories, Polish has one, few, many and other, and Ukrainian uses the last two digits of the number. Use `Intl.PluralRules` (or an ICU message library) and provide a form for each category the language needs.","uk":"Правила множини беруться з CLDR і відрізняються між мовами: в арабській шість категорій, у польській one, few, many і other, а в українській вирішують останні дві цифри числа. Використовуйте `Intl.PluralRules` (або бібліотеку ICU-повідомлень) і подавайте форму для кожної категорії, яку потребує мова."}'::jsonb, null::jsonb),
  ('i18n-plural-forms', null::text[], '{"en":"Hard-coding `count === 1` works for English and breaks for most other languages, so the rule has to come from data. `Intl.PluralRules` ships the CLDR rules for every locale, which is also why the translator writes one string per category instead of computing grammar in code. `Intl.NumberFormat` handles the number itself, including grouping separators (a non-breaking space in Ukrainian) that a string template can''t guess. The fallback to `other` keeps the app readable when a translation is incomplete. For sentences with several variables, an ICU MessageFormat library does the same job with one message per language.","uk":"Жорстко записане `count === 1` працює для англійської й ламається для більшості інших мов, тож правило має походити з даних. `Intl.PluralRules` містить правила CLDR для кожної локалі, тому перекладач пише один рядок на категорію, а не обчислює граматику в коді. `Intl.NumberFormat` обробляє саме число, включно з роздільниками розрядів (нерозривний пробіл в українській), які шаблон рядка вгадати не може. Запасний варіант `other` тримає застосунок читабельним, коли переклад неповний. Для речень з кількома змінними ту саму роботу виконує бібліотека ICU MessageFormat з одним повідомленням на мову."}'::jsonb, '{"/src/plural.ts":"export type Forms = {\n  zero?: string;\n  one?: string;\n  two?: string;\n  few?: string;\n  many?: string;\n  other: string;\n};\n\nexport function plural(locale: string, count: number, forms: Forms): string {\n  // Intl.PluralRules knows each language''s categories (e.g. Ukrainian has one, few, many and other).\n  const category = new Intl.PluralRules(locale).select(count) as keyof Forms;\n  // A form the language needs but the translator didn''t write falls back to \"other\".\n  const template = forms[category] ?? forms.other;\n  return template.replace(\"{count}\", new Intl.NumberFormat(locale).format(count));\n}\n"}'::jsonb),
  ('imm-const-mutation', array['a']::text[], '{"en":"`const` makes the **binding** constant: the variable can''t be pointed at a different value, so reassigning it throws a `TypeError`. It says nothing about the object the binding refers to, which stays fully mutable. For a read-only object, use `Object.freeze` (or TypeScript''s `readonly`/`as const`).","uk":"`const` робить сталим **зв''язування**: змінну не можна спрямувати на інше значення, тож повторне присвоєння кидає `TypeError`. Про об''єкт, на який посилається зв''язування, воно нічого не каже, і той лишається повністю змінним. Для об''єкта лише для читання використовуйте `Object.freeze` (чи `readonly`/`as const` у TypeScript)."}'::jsonb, null::jsonb),
  ('imm-pass-by-sharing', array['a']::text[], '{"en":"The function receives a copy of the **reference**, so `push(\"x\")` mutates the caller''s array. `list = []` only points the local parameter at a new array; the caller''s variable still refers to the original, so `\"y\"` goes into an array nobody else sees. JavaScript is pass-by-value, and for objects that value is a reference (sometimes called \"pass by sharing\").","uk":"Функція отримує копію **посилання**, тож `push(\"x\")` змінює масив того, хто викликав. `list = []` лише спрямовує локальний параметр на новий масив; змінна того, хто викликав, досі посилається на оригінал, тож `\"y\"` потрапляє в масив, якого більше ніхто не бачить. JavaScript передає за значенням, а для об''єктів це значення є посиланням (іноді це називають «передаванням через спільний доступ»)."}'::jsonb, null::jsonb),
  ('imm-sort-mutates', array['a']::text[], '{"en":"`sort` sorts **in place** and returns the same array, so `sorted === scores` and the original order is gone, which is a classic bug when sorting props or state. `toSorted` (ES2023) returns a new sorted array and leaves the original alone, as do `toReversed`, `toSpliced` and `with`.","uk":"`sort` сортує **на місці** й повертає той самий масив, тож `sorted === scores`, а початковий порядок втрачено, і це класична помилка під час сортування props чи стану. `toSorted` (ES2023) повертає новий відсортований масив і не чіпає оригінал, як і `toReversed`, `toSpliced` і `with`."}'::jsonb, null::jsonb),
  ('imm-with', array['a']::text[], '{"en":"`arr.with(index, value)` is the immutable version of `arr[index] = value`: it returns a copy with one element replaced. Unlike assignment, it can''t grow the array: an index outside the array throws a `RangeError` (negative indexes count from the end, like `at`).","uk":"`arr.with(index, value)` є незмінною версією `arr[index] = value`: вона повертає копію з одним заміненим елементом. На відміну від присвоєння, вона не може збільшити масив: індекс поза масивом кидає `RangeError` (від''ємні індекси рахуються з кінця, як в `at`)."}'::jsonb, null::jsonb),
  ('imm-shared-defaults', array['a']::text[], '{"en":"`Object.assign(target, …sources)` copies into its **first argument** and returns it. Here the target is the shared `DEFAULTS` object, so every client mutates it and gets the same object back: the first call''s `retries: 5` leaks into all later clients. Merge into a fresh object: `{ ...DEFAULTS, ...opts }` or `Object.assign({}, DEFAULTS, opts)`.","uk":"`Object.assign(target, …sources)` копіює у свій **перший аргумент** і повертає його. Тут ціллю є спільний об''єкт `DEFAULTS`, тож кожен клієнт змінює його й отримує той самий об''єкт: `retries: 5` з першого виклику просочується в усіх наступних клієнтів. Зливайте в новий об''єкт: `{ ...DEFAULTS, ...opts }` чи `Object.assign({}, DEFAULTS, opts)`."}'::jsonb, null::jsonb),
  ('imm-structured-clone-limits', array['a']::text[], '{"en":"`structuredClone` deep-copies data, including `Date` and `Map`, but not behaviour: class instances come back as **plain objects**, so `instanceof Point` is false and the `double` getter, which lived on the prototype, is gone. Functions throw a `DataCloneError`. If you need class instances back, rehydrate them (`Object.assign(new Point(), copy)`) or write a custom clone.","uk":"`structuredClone` глибоко копіює дані, зокрема `Date` і `Map`, але не поведінку: екземпляри класів повертаються **звичайними об''єктами**, тож `instanceof Point` хибне, а гетер `double`, що жив у прототипі, зникає. Функції кидають `DataCloneError`. Якщо потрібні екземпляри класів, відновлюйте їх (`Object.assign(new Point(), copy)`) або напишіть власне клонування."}'::jsonb, null::jsonb),
  ('imm-structured-clone-function', array['a']::text[], '{"en":"Functions can''t be cloned by the structured clone algorithm (they close over scopes that can''t be copied to another realm), so `structuredClone` throws a `DOMException` named `DataCloneError` instead of silently dropping them like `JSON.stringify` does. The same algorithm is used by `postMessage` to workers and by IndexedDB, so the same error appears there.","uk":"Алгоритм структурного клонування не може клонувати функції (вони замикають області видимості, які не можна скопіювати в інше середовище), тож `structuredClone` кидає `DOMException` на ім''я `DataCloneError`, а не мовчки відкидає їх, як робить `JSON.stringify`. Той самий алгоритм використовують `postMessage` до воркерів і IndexedDB, тож там з''являється та сама помилка."}'::jsonb, null::jsonb),
  ('imm-json-roundtrip', array['a']::text[], '{"en":"`JSON.stringify` drops properties whose value is `undefined`, turns a `Date` into an ISO string (via `toJSON`), writes `NaN` as `null`, and serialises a `Set` (which has no enumerable own properties) as `{}`. After parsing, the types are lost. Use `structuredClone` for data copies, and keep JSON for actual serialisation.","uk":"`JSON.stringify` відкидає властивості зі значенням `undefined`, перетворює `Date` на рядок ISO (через `toJSON`), записує `NaN` як `null` і серіалізує `Set` (що не має власних перелічуваних властивостей) як `{}`. Після розбору типи втрачено. Для копій даних використовуйте `structuredClone`, а JSON лишіть для справжньої серіалізації."}'::jsonb, null::jsonb),
  ('imm-structural-sharing', array['a']::text[], '{"en":"Only the objects on the path to the change are copied: the root and `user`. `settings` and `user.tags` are reused as-is (structural sharing), so they''re `===` to the old ones, and the old state still has the old name. That''s what lets `React.memo`, selectors and `OnPush` skip work with a cheap reference check.","uk":"Копіюються лише об''єкти на шляху до зміни: корінь і `user`. `settings` і `user.tags` використовуються повторно як є (структурне спільне використання), тож вони `===` старим, а старий стан досі має старе ім''я. Саме це дає `React.memo`, селекторам і `OnPush` пропускати роботу після дешевої перевірки посилань."}'::jsonb, null::jsonb),
  ('imm-react-mutation', array['a']::text[], '{"en":"React compares the new state with the old one using `Object.is`. A mutated array is the same object, so React bails out and the UI shows stale data (and memoised children and effects keyed on `items` won''t update even if something else re-renders). Always create a new array or object; the updater form also avoids stale closures when updates are batched.","uk":"React порівнює новий стан зі старим через `Object.is`. Змінений масив є тим самим об''єктом, тож React нічого не робить, а інтерфейс показує застарілі дані (і мемоїзовані дочірні компоненти й ефекти із залежністю від `items` не оновляться, навіть якщо щось інше перерендериться). Завжди створюйте новий масив чи об''єкт; форма з функцією оновлення ще й уникає застарілих замикань, коли оновлення групуються."}'::jsonb, null::jsonb),
  ('imm-deep-clone', null::text[], '{"en":"A `WeakMap` from originals to copies does double duty: it stops infinite recursion on cycles, and it makes shared references map to one shared copy. The copy must be registered in the map **before** recursing into children, or a cycle would recurse forever. `Object.create(Object.getPrototypeOf(v))` keeps class behaviour, and copying `Reflect.ownKeys` with full property descriptors brings along symbol keys, non-enumerable properties and accessors, cloning only data values. Built-ins with internal slots (Date, RegExp, Map, Set) have to be reconstructed explicitly, because their data isn''t stored in properties.","uk":"`WeakMap` від оригіналів до копій виконує подвійну роль: зупиняє нескінченну рекурсію на циклах і робить так, що спільні посилання відповідають одній спільній копії. Копію треба зареєструвати в мапі **до** рекурсії в дочірні значення, інакше цикл рекурсувався б вічно. `Object.create(Object.getPrototypeOf(v))` зберігає поведінку класу, а копіювання `Reflect.ownKeys` з повними дескрипторами властивостей переносить ключі-символи, неперелічувані властивості й аксесори, клонуючи лише значення-дані. Вбудовані типи з внутрішніми слотами (Date, RegExp, Map, Set) треба відтворювати явно, бо їхні дані не зберігаються у властивостях."}'::jsonb, '{"/src/clone.ts":"export function deepClone<T>(value: T): T {\n  const seen = new WeakMap<object, unknown>();\n\n  const clone = (v: any): any => {\n    if (typeof v !== \"object\" || v === null) return v; // primitives and functions are shared\n    if (seen.has(v)) return seen.get(v); // cycles and shared references keep their shape\n\n    if (v instanceof Date) return new Date(v.getTime());\n    if (v instanceof RegExp) {\n      const re = new RegExp(v.source, v.flags);\n      re.lastIndex = v.lastIndex;\n      return re;\n    }\n    if (v instanceof Map) {\n      const out = new Map();\n      seen.set(v, out);\n      for (const [k, val] of v) out.set(clone(k), clone(val));\n      return out;\n    }\n    if (v instanceof Set) {\n      const out = new Set();\n      seen.set(v, out);\n      for (const val of v) out.add(clone(val));\n      return out;\n    }\n\n    // Arrays and objects: same prototype, every own key (strings and symbols), descriptors preserved.\n    const out = Array.isArray(v) ? new Array(v.length) : Object.create(Object.getPrototypeOf(v));\n    seen.set(v, out);\n    for (const key of Reflect.ownKeys(v)) {\n      if (Array.isArray(v) && key === \"length\") continue;\n      const desc = Object.getOwnPropertyDescriptor(v, key)!;\n      if (\"value\" in desc) desc.value = clone(desc.value);\n      Object.defineProperty(out, key, desc);\n    }\n    return out;\n  };\n\n  return clone(value);\n}\n"}'::jsonb),
  ('imm-produce', null::text[], '{"en":"Each draft is a `Proxy` with a small state record: the base object, a lazily created shallow copy, and the child drafts it has handed out. Reads return child drafts on demand, so only visited objects get proxies. The first write makes a shallow copy (copy-on-write) and marks every ancestor as changed, so all objects on the path get copied and nothing else does. Finalising walks the result: untouched drafts collapse back to their base objects (structural sharing), changed ones become their frozen copies, and new objects created in the recipe are scanned for drafts they contain. Using an empty object or array as the proxy target keeps `Array.isArray` working and avoids proxy invariant errors when the base is frozen.","uk":"Кожна чернетка є `Proxy` з невеликим записом стану: базовий об''єкт, ліниво створена поверхнева копія й видані дочірні чернетки. Читання повертають дочірні чернетки на вимогу, тож проксі отримують лише відвідані об''єкти. Перший запис робить поверхневу копію (copy-on-write) і позначає кожного предка як зміненого, тож копіюються всі об''єкти на шляху й нічого більше. Фіналізація обходить результат: незачеплені чернетки згортаються назад у свої базові об''єкти (структурне спільне використання), змінені стають своїми замороженими копіями, а нові об''єкти, створені в recipe, скануються на наявність чернеток усередині. Порожній об''єкт чи масив як ціль проксі зберігає роботу `Array.isArray` і запобігає помилкам інваріантів проксі, коли базовий об''єкт заморожений."}'::jsonb, '{"/src/produce.ts":"type DraftState = {\n  base: any;\n  copy: any | null; // created on the first write (copy-on-write)\n  parent: DraftState | null;\n  children: Map<PropertyKey, any>; // drafts handed out for nested objects\n  finalized: boolean;\n};\n\nconst isObject = (v: unknown): v is object => typeof v === \"object\" && v !== null;\n\nexport function produce<T>(base: T, recipe: (draft: T) => T | void): T {\n  const states = new WeakMap<object, DraftState>(); // draft proxy → its state\n  const latest = (s: DraftState) => s.copy ?? s.base;\n\n  const markChanged = (s: DraftState) => {\n    if (s.copy) return;\n    s.copy = Array.isArray(s.base) ? [...s.base] : { ...s.base };\n    for (const [key, child] of s.children) s.copy[key] = child;\n    if (s.parent) markChanged(s.parent); // a changed child means every ancestor changes too\n  };\n\n  const createDraft = (value: any, parent: DraftState | null): any => {\n    const state: DraftState = { base: value, copy: null, parent, children: new Map(), finalized: false };\n    // A fresh empty target: Array.isArray works, and frozen bases don''t trip proxy invariants.\n    const proxy = new Proxy(Array.isArray(value) ? [] : {}, {\n      get(_t, key) {\n        const source = latest(state);\n        const v = source[key];\n        if (!isObject(v) || !Object.prototype.hasOwnProperty.call(source, key)) return v;\n        if (state.children.has(key)) return state.children.get(key);\n        if (v !== state.base[key]) return v; // a new object assigned in this recipe: no draft needed\n        const child = createDraft(v, state);\n        state.children.set(key, child);\n        if (state.copy) state.copy[key] = child;\n        return child;\n      },\n      set(_t, key, v) {\n        const source = latest(state);\n        if (Object.prototype.hasOwnProperty.call(source, key) && Object.is(source[key], v)) return true; // no-op write\n        markChanged(state);\n        state.copy[key] = v;\n        state.children.delete(key);\n        return true;\n      },\n      deleteProperty(_t, key) {\n        if (!Object.prototype.hasOwnProperty.call(latest(state), key)) return true;\n        markChanged(state);\n        delete state.copy[key];\n        state.children.delete(key);\n        return true;\n      },\n      has: (_t, key) => key in latest(state),\n      ownKeys: () => Reflect.ownKeys(latest(state)),\n      getOwnPropertyDescriptor(target, key) {\n        const desc = Reflect.getOwnPropertyDescriptor(latest(state), key);\n        if (!desc) return undefined;\n        const configurable = Array.isArray(target) && key === \"length\" ? false : true;\n        return { ...desc, writable: true, configurable };\n      },\n    });\n    states.set(proxy, state);\n    return proxy;\n  };\n\n  const seen = new WeakSet<object>();\n  const finalize = (value: any): any => {\n    if (!isObject(value)) return value;\n    const state = states.get(value);\n    if (state) {\n      if (!state.copy) return state.base; // untouched: share the original\n      if (state.finalized) return state.copy;\n      state.finalized = true;\n      for (const key of Reflect.ownKeys(state.copy)) state.copy[key] = finalize(state.copy[key]);\n      return Object.freeze(state.copy);\n    }\n    // A new object created in the recipe may contain drafts (e.g. draft.list = draft.list.filter(...)).\n    if (seen.has(value) || Object.isFrozen(value)) return value;\n    seen.add(value);\n    for (const key of Reflect.ownKeys(value)) {\n      const finalized = finalize(value[key]);\n      if (finalized !== value[key]) value[key] = finalized;\n    }\n    return value;\n  };\n\n  if (!isObject(base)) {\n    const result = recipe(base);\n    return result === undefined ? base : (result as T);\n  }\n  const root = createDraft(base, null);\n  const returned = recipe(root);\n  return finalize(returned === undefined ? root : returned);\n}\n"}'::jsonb),
  ('load-json-result-type', null::text[], '{"en":"Separating the three failure points (the request, the status, and the parse) gives the caller a precise, typed reason instead of an unhandled exception. Keep the `try` blocks narrow so that only the awaited call is guarded, and check `ok` yourself: `fetch` resolves even for 404 and 500 responses, so a missing check silently treats an error page as data.","uk":"Розділення трьох місць відмови (запит, статус і розбір) дає викликачу точну типізовану причину замість необробленого винятку. Тримайте блоки `try` вузькими, щоб охоплювався лише очікуваний виклик, і перевіряйте `ok` самі: `fetch` успішно завершується навіть для відповідей 404 і 500, тож без перевірки сторінка помилки сприймалася б як дані."}'::jsonb, '{"/src/load.ts":"export interface FetchResponse {\n  ok: boolean;\n  status: number;\n  json(): Promise<unknown>;\n}\n\nexport type Fetcher = (url: string) => Promise<FetchResponse>;\n\nexport type LoadResult = { ok: true; data: unknown } | { ok: false; error: string };\n\nexport async function loadJson(fetcher: Fetcher, url: string): Promise<LoadResult> {\n  let res: FetchResponse;\n  try {\n    res = await fetcher(url);\n  } catch (err) {\n    const message = err instanceof Error ? err.message : String(err);\n    return { ok: false, error: \"network: \" + message };\n  }\n\n  if (!res.ok) return { ok: false, error: \"HTTP \" + res.status };\n\n  try {\n    return { ok: true, data: await res.json() };\n  } catch {\n    return { ok: false, error: \"invalid json\" };\n  }\n}\n"}'::jsonb),
  ('debounce-injected-scheduler', null::text[], '{"en":"Debounce keeps one pending timer and resets it on every call, so a burst of keystrokes results in one request. Injecting the scheduler (instead of calling `setTimeout` directly) makes the behaviour testable without real waiting. Clearing the previous handle is what stops old arguments from firing; resetting the stored handle after the call lets the next burst start cleanly.","uk":"Debounce тримає один відкладений таймер і скидає його при кожному виклику, тож серія натискань клавіш дає один запит. Передача планувальника ззовні (замість прямого `setTimeout`) робить поведінку тестованою без реального очікування. Скасування попереднього таймера не дає старим аргументам спрацювати, а скидання збереженого handle після виклику дозволяє наступній серії початися коректно."}'::jsonb, '{"/src/debounce.ts":"export interface Scheduler {\n  set(fn: () => void, ms: number): unknown;\n  clear(handle: unknown): void;\n}\n\nexport function debounce<A extends unknown[]>(fn: (...args: A) => void, ms: number, scheduler: Scheduler): (...args: A) => void {\n  let handle: unknown = undefined;\n\n  return (...args: A) => {\n    if (handle !== undefined) scheduler.clear(handle);\n    handle = scheduler.set(() => {\n      handle = undefined;\n      fn(...args);\n    }, ms);\n  };\n}\n"}'::jsonb),
  ('delegate-click-actions', null::text[], '{"en":"Clicks bubble, so one listener on a stable parent handles buttons that do not exist yet. `closest` walks up from the clicked node, which is why a click on a span inside a button still finds the button. The containment check keeps the handler from acting on a matching element outside the root, and the cleanup function prevents leaked listeners when the list is torn down.","uk":"Кліки спливають, тож один слухач на стабільному батькові обробляє кнопки, яких ще немає. `closest` піднімається від клікнутого вузла, тому клік по span всередині кнопки все одно знаходить кнопку. Перевірка належності не дає обробити відповідний елемент поза коренем, а функція очищення запобігає витокам слухачів, коли список знищують."}'::jsonb, '{"/src/delegate.ts":"export function delegateActions(root: HTMLElement, onAction: (action: string, el: HTMLElement) => void): () => void {\n  const handler = (event: Event) => {\n    const target = event.target as Element | null;\n    const el = target ? target.closest<HTMLElement>(\"[data-action]\") : null;\n    if (!el || !root.contains(el)) return;\n    onAction(el.dataset.action as string, el);\n  };\n\n  root.addEventListener(\"click\", handler);\n  return () => root.removeEventListener(\"click\", handler);\n}\n"}'::jsonb),
  ('react-key-index-reorder', array['b']::text[], '{"en":"A key tells React which element is which across renders. With an index, the key for the first row is always 0, even after the first item moves away, so React reuses the old row''s input value or checkbox state for the new item. Use a stable id from the data.","uk":"Ключ повідомляє React, який елемент який між рендерами. Із індексом ключ першого рядка завжди 0, навіть коли перший елемент переміщено, тож React повторно використовує стан старого рядка (значення поля або checkbox) для нового елемента. Використовуйте стабільний id з даних."}'::jsonb, null::jsonb),
  ('react-effect-cleanup-return', array['c']::text[], '{"en":"An effect may return a cleanup function, and React calls it before the effect runs again and on unmount. Returning anything other than a function (or nothing) is a mistake, and nothing closes a socket automatically.","uk":"Effect може повернути функцію очищення, і React викликає її перед повторним запуском effect і при розмонтуванні. Повертати щось інше, крім функції або нічого, помилка, а сокет сам автоматично не закривається."}'::jsonb, null::jsonb),
  ('react-stale-state-updates', array['a']::text[], '{"en":"Each call reads `count` from the render in which the handler was created, so all three compute 0 + 1. The fix is an updater function, `setCount(c => c + 1)`, which receives the latest queued value and gives 3 after three calls.","uk":"Кожен виклик читає `count` з рендеру, у якому створено обробник, тож усі три обчислюють 0 + 1. Виправлення це функція-оновлювач `setCount(c => c + 1)`, яка отримує останнє значення в черзі й після трьох викликів дає 3."}'::jsonb, null::jsonb),
  ('react-strict-mode-effects', array['d']::text[], '{"en":"The double run is intentional and happens only in development. If an effect subscribes without a matching cleanup, the second mount reveals the leak. Production builds run each effect once.","uk":"Подвійний запуск навмисний і відбувається лише в режимі розробки. Якщо effect підписується без відповідного очищення, другий монтаж показує витік. Продакшн-збірки запускають кожен effect один раз."}'::jsonb, null::jsonb),
  ('ts-unknown-json-parse', array['b']::text[], '{"en":"`any` turns off checking, so mistakes pass silently. `unknown` forces you to narrow the value (with `typeof`, `in`, or a validator) before using it. `object` still does not guarantee the properties exist.","uk":"`any` вимикає перевірку, тож помилки проходять непоміченими. `unknown` змушує звузити значення (через `typeof`, `in` або валідатор) перед використанням. `object` все одно не гарантує наявність властивостей."}'::jsonb, null::jsonb),
  ('ts-discriminated-union-narrowing', array['c']::text[], '{"en":"A literal-typed field that differs between members is a discriminant. Comparing it narrows the union, so `data` is only accessible in the `ok` branch. `typeof` on a string gives `string`, `instanceof` does not apply to plain objects, and assertions bypass the check.","uk":"Поле з літеральним типом, що відрізняється між членами union, є дискримінантом. Його порівняння звужує union, тож `data` доступне лише в гілці `ok`. `typeof` для рядка дає `string`, `instanceof` не працює з простими об''єктами, а приведення типів обходять перевірку."}'::jsonb, null::jsonb),
  ('http-status-permission-403', array['b']::text[], '{"en":"401 means the request lacks valid credentials (authentication). Here the user is identified, but not allowed to act on this resource (authorization), so 403 is correct. Some APIs return 404 to hide a resource''s existence, but that is a deliberate choice, not the default.","uk":"401 означає, що запиту бракує дійсних облікових даних (автентифікація). Тут користувача ідентифіковано, але йому не дозволено діяти з цим ресурсом (авторизація), тож правильний 403. Деякі API повертають 404, щоб приховати існування ресурсу, але це свідомий вибір, а не типовий."}'::jsonb, null::jsonb),
  ('http-put-idempotent', array['c']::text[], '{"en":"Sending the same full representation with PUT twice leaves the server in the same state, so retries are safe. POST usually creates a new resource each time. GET reads and does not replace. CONNECT opens a tunnel and is unrelated to resource updates.","uk":"Надсилання тієї самої повної репрезентації через PUT двічі залишає сервер у тому самому стані, тож повтори безпечні. POST зазвичай щоразу створює новий ресурс. GET читає й нічого не замінює. CONNECT відкриває тунель і не стосується оновлення ресурсів."}'::jsonb, null::jsonb),
  ('dom-delegation-quiz-list', array['a']::text[], '{"en":"Clicks bubble up, so one listener on a stable parent covers current and future children. Per-item listeners need to be bound and removed as items change, and polling wastes time and still misses fast interactions.","uk":"Кліки спливають вгору, тож один слухач на стабільному батькові охоплює поточні й майбутні дочірні елементи. Слухачі для кожного елемента треба прив''язувати й знімати при змінах списку, а опитування марнує час і все одно пропускає швидкі взаємодії."}'::jsonb, null::jsonb),
  ('a11y-button-element', array['d']::text[], '{"en":"A native button gives keyboard focus, activation with Enter and Space, and a ''button'' role for screen readers for free. A div with a click handler needs tabindex, key handlers, and a role added by hand, and it is easy to forget one.","uk":"Нативна кнопка дає фокус із клавіатури, активацію через Enter і Space та роль ''button'' для екранних читачів без додаткової роботи. Div з обробником кліків потребує вручну доданих tabindex, обробників клавіш і ролі, і щось легко пропустити."}'::jsonb, null::jsonb),
  ('test-debounce-time', array['c']::text[], '{"en":"Real waiting makes the suite slow and flaky under load. A fake clock lets the test decide exactly when time passes, so the check is deterministic. Injecting the scheduler, as in the debounce practice, achieves the same effect without global mocks.","uk":"Реальне очікування робить набір тестів повільним і нестабільним під навантаженням. Фейковий годинник дає тесту змогу визначити, коли минає час, тож перевірка детермінована. Передача планувальника, як у практиці з debounce, дає той самий ефект без глобальних моків."}'::jsonb, null::jsonb),
  ('git-rebase-shared-branch', array['b']::text[], '{"en":"Rebasing replays your commits on top of the latest `main`, which gives a straight line of history. It rewrites commit ids, so avoid it on branches that other people have based work on.","uk":"Rebase відтворює ваші коміти поверх останнього `main`, що дає пряму лінію історії. Він переписує id комітів, тож не робіть цього з гілками, на яких уже працюють інші."}'::jsonb, null::jsonb),
  ('parse-query-string', null::text[], '{"en":"Parse in three passes: strip the optional `?`, split on `&`, then split each part on the first `=` only, since values may contain `=`. Decode the `+` to a space before `decodeURIComponent`, otherwise a literal plus would be lost. Keys that repeat turn into arrays, which is how multi-select filters are usually sent.","uk":"Розбирайте у три проходи: зніміть необов''язковий `?`, розділіть за `&`, потім кожну частину ділите лише за першим `=`, бо значення можуть містити `=`. Перетворіть `+` на пробіл до `decodeURIComponent`, інакше знак плюс зникне. Ключі, що повторюються, стають масивами, так зазвичай передають мульти-вибір у фільтрах."}'::jsonb, '{"/src/query.ts":"const decode = (s: string) => decodeURIComponent(s.replace(/\\+/g, \" \"));\n\nexport function parseQuery(search: string): Record<string, string | string[]> {\n  const out: Record<string, string | string[]> = {};\n  const body = search.startsWith(\"?\") ? search.slice(1) : search;\n  if (body === \"\") return out;\n\n  for (const part of body.split(\"&\")) {\n    if (part === \"\") continue;\n    const eq = part.indexOf(\"=\");\n    const key = decode(eq === -1 ? part : part.slice(0, eq));\n    const value = decode(eq === -1 ? \"\" : part.slice(eq + 1));\n\n    const existing = out[key];\n    if (existing === undefined) out[key] = value;\n    else if (Array.isArray(existing)) existing.push(value);\n    else out[key] = [existing, value];\n  }\n  return out;\n}\n"}'::jsonb),
  ('lru-cache', null::text[], '{"en":"A `Map` remembers insertion order, so moving an entry to the end on each use keeps the least recently used key at the front. Eviction is then one line: take the first key. `has` must not reorder, or a simple presence check would quietly change which entry gets evicted next.","uk":"`Map` пам''ятає порядок вставки, тож переміщення запису в кінець при кожному використанні тримає найдавніше використаний ключ на початку. Витіснення тоді це один рядок: взяти перший ключ. `has` не повинен змінювати порядок, інакше звичайна перевірка наявності тихо змінила б, який запис видалиться далі."}'::jsonb, '{"/src/lru.ts":"export interface LruCache<K, V> {\n  readonly size: number;\n  get(key: K): V | undefined;\n  set(key: K, value: V): void;\n  has(key: K): boolean;\n}\n\nexport function createLru<K, V>(capacity: number): LruCache<K, V> {\n  if (!(capacity >= 1)) throw new RangeError(\"capacity must be at least 1\");\n\n  // A Map keeps insertion order, so the first key is always the least recently used.\n  const map = new Map<K, V>();\n\n  return {\n    get size() {\n      return map.size;\n    },\n    has(key) {\n      return map.has(key);\n    },\n    get(key) {\n      if (!map.has(key)) return undefined;\n      const value = map.get(key) as V;\n      map.delete(key);\n      map.set(key, value);\n      return value;\n    },\n    set(key, value) {\n      if (map.has(key)) map.delete(key);\n      map.set(key, value);\n      if (map.size > capacity) {\n        const oldest = map.keys().next().value as K;\n        map.delete(oldest);\n      }\n    },\n  };\n}\n"}'::jsonb),
  ('map-limit-concurrency', null::text[], '{"en":"Instead of starting everything at once, start a fixed number of lanes that each pull the next index from a shared counter. Writing results by index keeps the output ordered no matter which worker finishes first. `Promise.all` rejects on the first failure, but it does not cancel the other lanes, so real code would also stop claiming new work after an error.","uk":"Замість запуску всього одразу, запускайте фіксовану кількість «доріжок», які кожна бере наступний індекс зі спільного лічильника. Запис результатів за індексом зберігає порядок, незалежно від того, який worker завершиться першим. `Promise.all` відхиляється при першій помилці, але не скасовує інші доріжки, тож у реальному коді після помилки також варто перестати брати нову роботу."}'::jsonb, '{"/src/limit.ts":"export async function mapLimit<T, R>(items: T[], limit: number, worker: (item: T, index: number) => Promise<R>): Promise<R[]> {\n  if (!(limit >= 1)) throw new RangeError(\"limit must be at least 1\");\n\n  const results: R[] = new Array(items.length);\n  let next = 0;\n\n  // Each lane takes the next unclaimed index until none are left.\n  const runLane = async () => {\n    while (next < items.length) {\n      const index = next++;\n      results[index] = await worker(items[index], index);\n    }\n  };\n\n  const lanes = Array.from({ length: Math.min(limit, items.length) }, () => runLane());\n  await Promise.all(lanes);\n  return results;\n}\n"}'::jsonb),
  ('http-no-store-vs-no-cache', array['b']::text[], '{"en":"`no-cache` lets the browser store the response but requires revalidation before every reuse. `max-age=0` makes it stale immediately, which still leaves a stored copy. `no-store` is the only one that tells caches not to keep the response, which matters for private data.","uk":"`no-cache` дозволяє браузеру зберігати відповідь, але вимагає перевірки перед кожним повторним використанням. `max-age=0` одразу робить її застарілою, але копія все одно лишається. `no-store` єдине, що вказує кешам не зберігати відповідь, це важливо для приватних даних."}'::jsonb, null::jsonb),
  ('http-etag-not-modified', array['b']::text[], '{"en":"The ETag identifies a version. When it matches, the server answers 304 with no body, and the client reuses its cached copy. This saves bandwidth without changing the response the page sees.","uk":"ETag визначає версію. Коли вона збігається, сервер відповідає 304 без тіла, а клієнт використовує свою копію з кешу. Це економить трафік і не змінює відповідь, яку бачить сторінка."}'::jsonb, null::jsonb),
  ('react-controlled-input-pattern', array['c']::text[], '{"en":"A controlled input''s value comes from React state, and every change flows through `onChange` back into that state. The first and second options are uncontrolled: React does not own the value. Changing `key` remounts the input and is a separate, rarely right, tool.","uk":"Значення керованого поля береться зі стану React, і кожна зміна проходить через `onChange` назад у цей стан. Перші два варіанти некеровані: React не контролює значення. Зміна `key` перемонтовує поле і є окремим, рідко правильним інструментом."}'::jsonb, null::jsonb),
  ('react-lazy-suspense-fallback', array['b']::text[], '{"en":"`React.lazy` suspends rendering until the module arrives, and the nearest `Suspense` boundary shows its fallback meanwhile. An error boundary catches failures such as a failed chunk download, but it does not show loading UI.","uk":"`React.lazy` призупиняє рендер, доки не прийде модуль, а найближча межа `Suspense` тим часом показує свій fallback. Error boundary ловить помилки, наприклад невдале завантаження частини коду, але не показує інтерфейс завантаження."}'::jsonb, null::jsonb),
  ('ts-as-const-literal-tuple', array['b']::text[], '{"en":"`as const` is a compile-time instruction: the types become literal and readonly, and the value is not frozen at runtime. A common pattern is deriving a union type from the array. The other options describe runtime changes or the opposite of what happens.","uk":"`as const` це інструкція часу компіляції: типи стають літеральними й readonly, а значення не заморожується в час виконання. Типовий приклад це вивести з масиву union-тип. Інші варіанти описують зміни часу виконання або протилежне до того, що відбувається."}'::jsonb, null::jsonb),
  ('ts-indexed-access-union', array['b']::text[], '{"en":"An indexed access type with a union of keys returns the union of the property types. Here that is `number` from `id` and `string` from `name`. The key union is what you get from `keyof`, not the result of indexing.","uk":"Індексований тип доступу з union ключів повертає union типів властивостей. Тут це `number` з `id` і `string` з `name`. Union ключів отримують через `keyof`, а не через індексування."}'::jsonb, null::jsonb),
  ('css-custom-property-override', array['b']::text[], '{"en":"Custom properties are inherited like other values, and `var()` is resolved on the element where it appears. A child can override the variable for its subtree, which is how theming works without rewriting every rule.","uk":"Custom properties наслідуються, як і інші значення, а `var()` обчислюється на елементі, де вона з''являється. Дочірній елемент може перевизначити змінну для свого піддерева, так працює теми без переписування кожного правила."}'::jsonb, null::jsonb),
  ('css-sticky-not-sticking', array['b']::text[], '{"en":"A sticky element needs a threshold such as `top: 0` to know when to stick. It also sticks only within its parent, so a parent that is not tall enough gives it no room. An ancestor with `overflow` other than `visible` becomes the scrolling box, which can prevent sticking to the page.","uk":"Липкий елемент потребує порогу, наприклад `top: 0`, щоб знати, коли прилипати. Він прилипає лише в межах батька, тож занадто низький батько не дає місця. Предок із `overflow`, відмінним від `visible`, стає скролюваною рамкою, і це може завадити прилипанню до сторінки."}'::jsonb, null::jsonb),
  ('a11y-live-region-toast', array['b']::text[], '{"en":"A live region tells assistive technology to announce changes to its content. `polite` waits for a pause, `assertive` interrupts. A visual-only change like color or a hover tooltip is invisible to screen readers.","uk":"Live-регіон повідомляє допоміжним технологіям, щоб вони оголошували зміни його вмісту. `polite` чекає паузи, `assertive` перериває. Лише візуальна зміна, як колір або підказка при наведенні, невидима для екранних читачів."}'::jsonb, null::jsonb),
  ('git-reset-soft-keep-staged', array['b']::text[], '{"en":"`--soft` moves the branch back one commit and leaves the index and working tree alone, so the changes remain staged. `--hard` discards them. `git checkout -- .` throws away unstaged edits. `git revert` creates a new commit that undoes the old one, which keeps history but does not un-commit.","uk":"`--soft` переміщує гілку на один коміт назад і не чіпає індекс та робоче дерево, тож зміни лишаються в індексі. `--hard` їх відкидає. `git checkout -- .` викидає незастейджені правки. `git revert` створює новий коміт, що скасовує старий: історія зберігається, але коміт не знімається."}'::jsonb, null::jsonb),
  ('js-weakmap-garbage-collection', array['b']::text[], '{"en":"A normal `Map` holds its keys strongly, so a removed element would stay in memory as long as the map exists. A `WeakMap` does not prevent collection of its keys, which makes it a good fit for metadata attached to objects you do not own the lifetime of. It is not iterable, and it does not persist anything.","uk":"Звичайний `Map` тримає ключі сильно, тож видалений елемент лишався б у пам''яті, поки існує мапа. `WeakMap` не заважає збирати свої ключі, тому він підходить для метаданих, прикріплених до об''єктів, життя яких ви не контролюєте. Його не можна ітерувати, і він нічого не зберігає між сесіями."}'::jsonb, null::jsonb),
  ('ig-iterable', array['a']::text[], '{"en":"That''s the iteration protocol. Array-likes with `length` and numeric keys work with `Array.from`, but not with `for…of` or spread unless they also implement `Symbol.iterator`. Generators are the simplest way to implement it: `*[Symbol.iterator]() { yield …; }`.","uk":"Це протокол ітерації. Масивоподібні об''єкти з `length` і числовими ключами працюють з `Array.from`, але не з `for…of` чи spread, якщо не реалізують `Symbol.iterator`. Найпростіше реалізувати його генератором: `*[Symbol.iterator]() { yield …; }`."}'::jsonb, null::jsonb),
  ('ig-lazy-start', array['a']::text[], '{"en":"Calling a generator function only creates the generator object; no code in the body runs yet. Each `next()` resumes execution until the next `yield`, so the logs interleave with the consumer''s: the body runs in slices, on demand.","uk":"Виклик функції-генератора лише створює об''єкт-генератор; жоден рядок тіла ще не виконується. Кожен `next()` продовжує виконання до наступного `yield`, тож записи чергуються із записами споживача: тіло виконується частинами, на вимогу."}'::jsonb, null::jsonb),
  ('ig-next-value', array['a']::text[], '{"en":"The first `next()` only starts the generator, running it to the first `yield`; there''s no paused `yield` to receive its argument, so `10` is lost. The argument of each later `next(x)` becomes the result of the `yield` the generator was paused at: `a = 2`, `b = 3`, so it returns `5`.","uk":"Перший `next()` лише запускає генератор до першого `yield`; немає призупиненого `yield`, що отримав би його аргумент, тож `10` губиться. Аргумент кожного наступного `next(x)` стає результатом того `yield`, на якому генератор стоїть: `a = 2`, `b = 3`, тож повертається `5`."}'::jsonb, null::jsonb),
  ('ig-return-value', array['a']::text[], '{"en":"A generator''s `return` value is delivered in the final result with `done: true`. Spread, `Array.from` and `for…of` stop as soon as they see `done: true` and ignore its value; only manual `next()` calls (or `yield*`, which evaluates to it) see the `3`.","uk":"Значення з `return` генератора приходить в останньому результаті з `done: true`. Spread, `Array.from` і `for…of` зупиняються, щойно бачать `done: true`, і ігнорують його значення; `3` бачать лише ручні виклики `next()` (або `yield*`, що обчислюється в нього)."}'::jsonb, null::jsonb),
  ('ig-yield-star', array['a']::text[], '{"en":"`yield* inner()` yields every value of `inner` (`\"a\"`) and then evaluates to inner''s **return** value (`\"r\"`), which the outer generator yields explicitly. `yield* [1, 2]` works with any iterable and yields its items one by one, unlike `yield [1, 2]`, which would yield the array itself.","uk":"`yield* inner()` видає всі значення `inner` (`\"a\"`), а потім обчислюється в **повернене** значення inner (`\"r\"`), яке зовнішній генератор видає явно. `yield* [1, 2]` працює з будь-яким ітерованим об''єктом і видає його елементи по одному, на відміну від `yield [1, 2]`, що видав би сам масив."}'::jsonb, null::jsonb),
  ('ig-for-await', array['a']::text[], '{"en":"An `async function*` can `await` between yields, and `for await…of` waits for each value before running the loop body, so pages arrive one after another. The spread inside `push` flattens each page. This is the natural shape for paginated APIs and streams.","uk":"`async function*` може робити `await` між yield, а `for await…of` чекає на кожне значення перед виконанням тіла циклу, тож сторінки надходять одна за одною. Spread усередині `push` розгортає кожну сторінку. Це природна форма для API з пагінацією й потоків."}'::jsonb, null::jsonb),
  ('ig-break-closes', array['a']::text[], '{"en":"When `for…of` exits early it calls the iterator''s `return()` method. Generators have one, so `g` is closed for good and spreads to `[]`. Array iterators have no `return()`, so the loop only consumed `1`, and the same iterator still yields `2` and `3` afterwards.","uk":"Коли `for…of` завершується достроково, він викликає метод `return()` ітератора. Генератори його мають, тож `g` закрито назавжди, і spread дає `[]`. Ітератори масивів не мають `return()`, тож цикл забрав лише `1`, і той самий ітератор потім і далі видає `2` і `3`."}'::jsonb, null::jsonb),
  ('ig-finally-cleanup', array['a']::text[], '{"en":"`break` makes `for…of` call the generator''s `return()`, which resumes it at the paused `yield` as if a `return` statement were there, so pending `finally` blocks run. That''s the place to release resources (close a connection, remove a listener) that the generator acquired.","uk":"`break` змушує `for…of` викликати `return()` генератора, що продовжує його в місці призупиненого `yield` так, ніби там стоїть інструкція `return`, тож блоки `finally`, що очікують, виконуються. Саме там слід звільняти ресурси (закривати з''єднання, знімати слухачів), які генератор отримав."}'::jsonb, null::jsonb),
  ('ig-coroutine-runner', array['a']::text[], '{"en":"The runner calls `next()`, waits for whatever was yielded (`Promise.resolve` also accepts plain values), and resumes the generator with the result, so `a = 2` and `b = 3`. Generator code then reads like synchronous code that pauses on `yield`, which is exactly what `async` functions do with `await`. Libraries like `co` worked this way before ES2017.","uk":"Виконавець викликає `next()`, чекає на видане значення (`Promise.resolve` приймає й звичайні значення) і продовжує генератор із результатом, тож `a = 2`, а `b = 3`. Код генератора тоді читається як синхронний, що зупиняється на `yield`, а це саме те, що роблять `async`-функції з `await`. Бібліотеки на кшталт `co` працювали так до ES2017."}'::jsonb, null::jsonb),
  ('ig-throw-into', array['a']::text[], '{"en":"`it.throw(\"boom\")` raises the error at the paused `yield 1`, inside the `try`, so the generator catches it and runs on to its next `yield`, whose value `throw()` returns. The next `next()` reaches `yield 3`, and the one after that finishes the generator. If the generator hadn''t caught it, `throw()` would have rethrown to the caller and closed the generator.","uk":"`it.throw(\"boom\")` кидає помилку в місці призупиненого `yield 1`, всередині `try`, тож генератор її перехоплює й працює до наступного `yield`, чиє значення повертає `throw()`. Наступний `next()` доходить до `yield 3`, а ще один завершує генератор. Якби генератор її не перехопив, `throw()` перекинув би помилку викликачу й закрив генератор."}'::jsonb, null::jsonb),
  ('ig-lazy-pipeline', null::text[], '{"en":"Each helper is a generator that pulls from its source only when its own consumer pulls, so whole pipelines run one item at a time and infinite sources are fine. `take` checks the count **after** yielding, so it never requests an extra value, and returning from a `for…of` closes the source. `zip` manages two iterators by hand, so it calls `return()` itself in `finally`, mirroring what `for…of` does automatically.","uk":"Кожен помічник є генератором, що бере з джерела лише тоді, коли бере його власний споживач, тож цілі конвеєри обробляють по одному елементу, і нескінченні джерела не проблема. `take` перевіряє лічильник **після** видачі значення, тож ніколи не просить зайвого, а вихід із `for…of` закриває джерело. `zip` керує двома ітераторами вручну, тож сам викликає `return()` у `finally`, повторюючи те, що `for…of` робить автоматично."}'::jsonb, '{"/src/lazy.ts":"export function* range(start = 0, end = Infinity, step = 1): Generator<number> {\n  if (step === 0 || !Number.isFinite(step)) throw new RangeError(\"step must be a non-zero finite number\");\n  for (let x = start; step > 0 ? x < end : x > end; x += step) yield x;\n}\n\nexport function* map<T, U>(iterable: Iterable<T>, fn: (value: T, index: number) => U): Generator<U> {\n  let i = 0;\n  for (const x of iterable) yield fn(x, i++);\n}\n\nexport function* filter<T>(iterable: Iterable<T>, pred: (value: T, index: number) => boolean): Generator<T> {\n  let i = 0;\n  for (const x of iterable) if (pred(x, i++)) yield x;\n}\n\nexport function* take<T>(iterable: Iterable<T>, n: number): Generator<T> {\n  if (n <= 0) return; // don''t even start the source\n  let count = 0;\n  for (const x of iterable) {\n    yield x;\n    if (++count >= n) return; // stop right after the n-th value: no extra pull\n  }\n}\n\nexport function* chunk<T>(iterable: Iterable<T>, size: number): Generator<T[]> {\n  if (!Number.isInteger(size) || size < 1) throw new RangeError(\"size must be a positive integer\");\n  let buffer: T[] = [];\n  for (const x of iterable) {\n    buffer.push(x);\n    if (buffer.length === size) {\n      yield buffer;\n      buffer = [];\n    }\n  }\n  if (buffer.length) yield buffer;\n}\n\nexport function* zip<A, B>(a: Iterable<A>, b: Iterable<B>): Generator<[A, B]> {\n  const ia = a[Symbol.iterator]();\n  const ib = b[Symbol.iterator]();\n  try {\n    while (true) {\n      const ra = ia.next();\n      if (ra.done) return;\n      const rb = ib.next();\n      if (rb.done) return;\n      yield [ra.value, rb.value];\n    }\n  } finally {\n    // Like for…of on early exit: give both sources a chance to clean up.\n    ia.return?.();\n    ib.return?.();\n  }\n}\n"}'::jsonb),
  ('ig-coroutine', null::text[], '{"en":"A single `step(method, input)` function resumes the generator with either `next` (a result) or `throw` (an error), wrapped in `try/catch` so synchronous failures become rejections. Each yielded value goes through `Promise.resolve` (arrays through `Promise.all`), and its outcome schedules the next step. This is, almost line for line, how transpilers turned `async`/`await` into generators before engines supported it.","uk":"Одна функція `step(method, input)` продовжує генератор або через `next` (результат), або через `throw` (помилка), обгорнута в `try/catch`, щоб синхронні збої ставали відхиленнями. Кожне видане значення проходить через `Promise.resolve` (масиви через `Promise.all`), а його результат планує наступний крок. Майже рядок у рядок так транспілятори перетворювали `async`/`await` на генератори, доки рушії їх не підтримували."}'::jsonb, '{"/src/run.ts":"export function run<T>(genFn: (...args: any[]) => Generator<unknown, T, any>, ...args: unknown[]): Promise<T> {\n  return new Promise<T>((resolve, reject) => {\n    let it: Generator<unknown, T, any>;\n    try {\n      it = genFn(...args);\n    } catch (error) {\n      return reject(error);\n    }\n\n    const step = (method: \"next\" | \"throw\", input?: unknown) => {\n      let result: IteratorResult<unknown, T>;\n      try {\n        result = it[method](input); // resume the generator with a value, or throw into it\n      } catch (error) {\n        return reject(error); // the generator didn''t handle it\n      }\n      if (result.done) return resolve(result.value);\n      const value = Array.isArray(result.value) ? Promise.all(result.value) : result.value;\n      Promise.resolve(value).then(\n        (v) => step(\"next\", v),\n        (e) => step(\"throw\", e),\n      );\n    };\n\n    step(\"next\");\n  });\n}\n"}'::jsonb),
  ('js-nan-includes', array['a']::text[], '{"en":"`includes` uses the SameValueZero algorithm, which treats `NaN` as equal to itself. `indexOf` uses strict equality (`===`), and `NaN === NaN` is `false`, so it returns -1. Use `Number.isNaN` or `includes` when you need to find `NaN`.","uk":"`includes` використовує алгоритм SameValueZero, для якого `NaN` дорівнює собі. `indexOf` використовує строгу рівність (`===`), а `NaN === NaN` дає `false`, тож повертає -1. Щоб знайти `NaN`, використовуйте `Number.isNaN` або `includes`."}'::jsonb, null::jsonb),
  ('js-key-order', array['b']::text[], '{"en":"Own property order is specified: integer-like keys first in ascending numeric order, then string keys in insertion order, then symbols (which `Object.keys` skips). Don''t rely on insertion order for numeric-looking keys; use a `Map` if order matters.","uk":"Порядок власних властивостей визначено: спершу ключі-цілі числа за зростанням, потім рядкові ключі в порядку вставки, потім символи (їх `Object.keys` пропускає). Не покладайтеся на порядок вставки для ключів, схожих на числа; якщо порядок важливий, використовуйте `Map`."}'::jsonb, null::jsonb),
  ('js-structured-clone', array['a', 'c', 'd']::text[], '{"en":"`structuredClone` uses the structured clone algorithm (the same as `postMessage`). It handles `Map`, `Set`, `Date`, typed arrays and cycles, but throws a `DataCloneError` for functions and DOM nodes. Class instances come back as plain objects: the prototype, getters and methods are lost.","uk":"`structuredClone` використовує алгоритм структурного клонування (той самий, що й `postMessage`). Він обробляє `Map`, `Set`, `Date`, типізовані масиви й цикли, але кидає `DataCloneError` для функцій і DOM-вузлів. Екземпляри класів повертаються як звичайні об''єкти: прототип, гетери й методи втрачаються."}'::jsonb, null::jsonb),
  ('js-deep-equal', null::text[], '{"en":"Handle the cheap cases first: `Object.is` covers identical references, primitives and `NaN`. Anything that isn''t a non-null object is then unequal. Special-case `Date`, then make sure both sides are arrays or both are objects before comparing items or keys. Checking key counts plus `hasOwnProperty` catches `{ a: undefined }` vs `{}`. The recursion depth equals the nesting depth of the data.","uk":"Спершу прості випадки: `Object.is` покриває однакові посилання, примітиви й `NaN`. Усе, що не є ненульовим об''єктом, далі нерівне. Окремо обробіть `Date`, потім переконайтеся, що обидві сторони — масиви або обидві — об''єкти, і лише тоді порівнюйте елементи чи ключі. Перевірка кількості ключів разом із `hasOwnProperty` ловить `{ a: undefined }` проти `{}`. Глибина рекурсії дорівнює глибині вкладеності даних."}'::jsonb, '{"/src/deep-equal.ts":"type Dict = Record<string, unknown>;\n\nexport function deepEqual(a: unknown, b: unknown): boolean {\n  if (Object.is(a, b)) return true;\n  if (typeof a !== \"object\" || typeof b !== \"object\" || a === null || b === null) return false;\n\n  if (a instanceof Date || b instanceof Date) {\n    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();\n  }\n\n  if (Array.isArray(a) !== Array.isArray(b)) return false;\n  if (Array.isArray(a) && Array.isArray(b)) {\n    return a.length === b.length && a.every((item, i) => deepEqual(item, b[i]));\n  }\n\n  const keysA = Object.keys(a);\n  const keysB = Object.keys(b);\n  if (keysA.length !== keysB.length) return false;\n  return keysA.every((key) => Object.prototype.hasOwnProperty.call(b, key) && deepEqual((a as Dict)[key], (b as Dict)[key]));\n}\n"}'::jsonb),
  ('js-typeof-null', array['b']::text[], '{"en":"A long-standing bug from the first JavaScript implementation that can''t be fixed without breaking the web. Check for null with `value === null`.","uk":"Давня помилка першої реалізації JavaScript, яку не можна виправити, не зламавши веб. Перевіряйте null через `value === null`."}'::jsonb, null::jsonb),
  ('js-reference-equality', array['b']::text[], '{"en":"Objects are compared by reference. `a` and `b` are two distinct objects, so `a === b` is false. `c` points at the same object as `a`, so `a === c` is true.","uk":"Об''єкти порівнюються за посиланням. `a` і `b` є двома різними об''єктами, тому `a === b` дає false. `c` вказує на той самий об''єкт, що й `a`, тому `a === c` дає true."}'::jsonb, null::jsonb),
  ('js-falsy-values', array['a', 'd', 'e']::text[], '{"en":"The falsy values are `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` and `NaN`. Non-empty strings like `\"0\"` and every object, including empty arrays, are truthy.","uk":"Хибні значення: `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` і `NaN`. Непорожні рядки на кшталт `\"0\"` і будь-які об''єкти, зокрема порожні масиви, є істинними."}'::jsonb, null::jsonb),
  ('js-this-callback', array['b']::text[], '{"en":"`this` depends on the call site. `setTimeout` calls the function on its own, not as `counter.inc()`, so `this` is `undefined` in strict mode, and reading `this.count` throws. Fix it with `setTimeout(() => counter.inc())` or `counter.inc.bind(counter)`.","uk":"`this` залежить від місця виклику. `setTimeout` викликає функцію окремо, а не як `counter.inc()`, тож у strict mode `this` дорівнює `undefined`, і читання `this.count` кидає помилку. Виправлення: `setTimeout(() => counter.inc())` або `counter.inc.bind(counter)`."}'::jsonb, null::jsonb),
  ('js-prototype-lookup', array['a']::text[], '{"en":"`delete child.kind` removes the own property, so the lookup continues up the prototype chain and finds `kind` on `base`. Deleting never touches the prototype.","uk":"`delete child.kind` видаляє власну властивість, тож пошук продовжується ланцюжком прототипів і знаходить `kind` у `base`. Видалення ніколи не зачіпає прототип."}'::jsonb, null::jsonb),
  ('js-group-by', null::text[], '{"en":"One pass with an accumulator object: compute the key, create the bucket on first use (`??=`), push the item. It runs in O(n). Modern runtimes also ship `Object.groupBy`, which has the same semantics.","uk":"Один прохід з об''єктом-акумулятором: обчислюємо ключ, створюємо «кошик» при першому використанні (`??=`) і додаємо елемент. Складність O(n). Сучасні середовища також мають `Object.groupBy` з такою самою семантикою."}'::jsonb, '{"/src/groupBy.js":"export function groupBy(items, keyFn) {\n  const result = {};\n  for (const item of items) {\n    const key = keyFn(item);\n    (result[key] ??= []).push(item);\n  }\n  return result;\n}\n"}'::jsonb),
  ('cls-tdz', array['a']::text[], '{"en":"Class declarations are hoisted like `let` and `const`: the name exists for the whole scope but stays in the **temporal dead zone** until the declaration runs, so using it earlier throws a `ReferenceError`. Function declarations, by contrast, are fully hoisted and can be called before they appear.","uk":"Оголошення класів спливають як `let` і `const`: ім''я існує в усій області видимості, але лишається в **тимчасовій мертвій зоні**, доки не виконається оголошення, тож використання раніше кидає `ReferenceError`. Оголошення функцій, натомість, спливають повністю, і їх можна викликати до того, як вони з''являються в коді."}'::jsonb, null::jsonb),
  ('cls-methods-not-enumerable', array['a']::text[], '{"en":"`for…in` lists enumerable properties, own and inherited. `x` is an own property set in the constructor; `move` lives on `Point.prototype` and class methods are **non-enumerable**, so it''s skipped (a method assigned as `Point.prototype.move = …` would show up). `typeof` a class is `\"function\"`: classes are constructor functions with extra rules.","uk":"`for…in` перелічує перелічувані властивості, власні й успадковані. `x` є власною властивістю, заданою в конструкторі; `move` живе в `Point.prototype`, а методи класу **неперелічувані**, тож він пропускається (метод, присвоєний як `Point.prototype.move = …`, з''явився б). `typeof` класу дає `\"function\"`: класи є функціями-конструкторами з додатковими правилами."}'::jsonb, null::jsonb),
  ('cls-this-before-super', array['a']::text[], '{"en":"In a derived class, the object is created by the **base** constructor, so `this` doesn''t exist until `super()` returns. Touching it earlier throws a `ReferenceError` at run time. It''s not a `SyntaxError` because the engine can''t know statically whether `super()` was called on every path.","uk":"У похідному класі об''єкт створює **базовий** конструктор, тож `this` не існує, доки не поверне `super()`. Звернення до нього раніше кидає `ReferenceError` під час виконання. Це не `SyntaxError`, бо рушій не може статично знати, чи `super()` викликано на кожному шляху."}'::jsonb, null::jsonb),
  ('cls-extends-error', array['a']::text[], '{"en":"`class … extends Error` creates real errors: they pass `instanceof Error`, have a stack trace and keep the message. The default `name` is inherited from `Error.prototype` (`\"Error\"`), so set it yourself; `String(e)` (and most loggers) print `name: message`.","uk":"`class … extends Error` створює справжні помилки: вони проходять `instanceof Error`, мають стек викликів і зберігають повідомлення. Типовий `name` успадковується з `Error.prototype` (`\"Error\"`), тож задайте його самі; `String(e)` (і більшість журналів) виводять `name: message`."}'::jsonb, null::jsonb),
  ('cls-arrow-field', array['a']::text[], '{"en":"Methods live once on the prototype and can be reached with `super`. A field like `greet = () => …` is created **on every instance** (so it''s an own property, not on `A.prototype`). That gives a bound `this` for callbacks, but costs a function per instance and can''t be called through `super.greet()` from a subclass.","uk":"Методи живуть один раз у прототипі, і до них можна дістатися через `super`. Поле на кшталт `greet = () => …` створюється **на кожному екземплярі** (тож це власна властивість, а не в `A.prototype`). Це дає прив''язаний `this` для колбеків, але коштує по функції на екземпляр і не викликається через `super.greet()` з підкласу."}'::jsonb, null::jsonb),
  ('cls-static-inheritance', array['a']::text[], '{"en":"`extends` links two prototype chains: instances (`User.prototype → Model.prototype`) and the constructors themselves (`User → Model`). So `User.table` is found on `Model`, and inside the static method `this` is `User`, the class it was called on, so `new this()` creates a `User`. That''s how static factories like `Model.create()` work for every subclass.","uk":"`extends` пов''язує два ланцюжки прототипів: екземплярів (`User.prototype → Model.prototype`) і самих конструкторів (`User → Model`). Тож `User.table` знаходиться в `Model`, а всередині статичного методу `this` є `User`, класом, на якому його викликали, тож `new this()` створює `User`. Саме так статичні фабрики на кшталт `Model.create()` працюють для кожного підкласу."}'::jsonb, null::jsonb),
  ('cls-private-brand-check', array['a']::text[], '{"en":"Private fields are installed by the constructor on the object itself; they''re **not** inherited through the prototype. `Object.create(Point.prototype)` makes an object that looks like a `Point` (it passes `instanceof`) but never ran the constructor, so it has no `#x`. `#x in obj` checks for it safely, while reading `this.#x` on such an object throws a `TypeError`.","uk":"Приватні поля встановлює конструктор на самому об''єкті; вони **не** успадковуються через прототип. `Object.create(Point.prototype)` створює об''єкт, схожий на `Point` (він проходить `instanceof`), але конструктор для нього не виконувався, тож `#x` у нього немає. `#x in obj` безпечно це перевіряє, а читання `this.#x` на такому об''єкті кидає `TypeError`."}'::jsonb, null::jsonb),
  ('cls-init-order', array['a']::text[], '{"en":"`this.describe()` dispatches to `Child`''s override, because the object is already a `Child`. But `Child`''s fields are initialised only **after** `super()` returns, and the base constructor is still running, so `this.label` is `undefined`. Avoid calling overridable methods from constructors, or move that work to an explicit `init()` step.","uk":"`this.describe()` переходить до перевизначення в `Child`, бо об''єкт уже є `Child`. Але поля `Child` ініціалізуються лише **після** повернення з `super()`, а базовий конструктор ще виконується, тож `this.label` дорівнює `undefined`. Не викликайте перевизначувані методи з конструкторів або перенесіть цю роботу в явний крок `init()`."}'::jsonb, null::jsonb),
  ('cls-field-define-semantics', array['a']::text[], '{"en":"Class fields are created with **define** semantics (like `Object.defineProperty`), not assignment. So `value = 1` adds an own data property that shadows the inherited accessor, and `A`''s setter never runs. With TypeScript''s legacy `useDefineForClassFields: false` it would have been an assignment that calls the setter, a real difference when migrating code.","uk":"Поля класу створюються із семантикою **визначення** (як `Object.defineProperty`), а не присвоєння. Тож `value = 1` додає власну властивість-дані, що затінює успадкований аксесор, і сетер `A` ніколи не виконується. Зі застарілим налаштуванням TypeScript `useDefineForClassFields: false` це було б присвоєння, що викликає сетер, і це реальна відмінність під час міграції коду."}'::jsonb, null::jsonb),
  ('cls-array-subclass', array['a']::text[], '{"en":"Built-ins can be subclassed with `class`, and array methods that create new arrays (`filter`, `map`, `slice`) use `Symbol.species`, which defaults to the subclass. So `evens` (actually the odd numbers `[1, 3]`) is a `Stack` and has `peek`, and `Stack.from` builds a `Stack` too. `length` stays magic in subclasses.","uk":"Вбудовані типи можна наслідувати через `class`, а методи масивів, що створюють нові масиви (`filter`, `map`, `slice`), використовують `Symbol.species`, що за замовчуванням є підкласом. Тож `evens` (насправді непарні числа `[1, 3]`) є `Stack` і має `peek`, а `Stack.from` теж будує `Stack`. `length` у підкласах лишається «магічним»."}'::jsonb, null::jsonb),
  ('cls-private-proxy', array['a']::text[], '{"en":"`c.inc` is found through the proxy''s default `get`, but it''s then called with `this` = the **proxy**. Private fields aren''t properties and can''t be forwarded by traps; they live only on the original instance. So `this.#n` on the proxy throws a `TypeError`. This is why Vue and MobX can''t make classes with `#private` fields reactive without workarounds (like binding methods to the raw object).","uk":"`c.inc` знаходиться через типовий `get` проксі, але потім викликається з `this` = **проксі**. Приватні поля не є властивостями, і пастки не можуть їх перенаправити; вони живуть лише на початковому екземплярі. Тож `this.#n` на проксі кидає `TypeError`. Тому Vue і MobX не можуть зробити реактивними класи з полями `#private` без обхідних шляхів (як-от прив''язування методів до сирого об''єкта)."}'::jsonb, null::jsonb),
  ('cls-mixins', null::text[], '{"en":"Because `extends` accepts any expression, each mixin is just `(Base) => class extends Base { … }`, and stacking them builds an ordinary prototype chain, so `super`, `instanceof` and constructor arguments keep working. `#listeners` keeps listener storage private per instance. `fromJSON` uses `this` in a static method, which refers to the class it was called on, so subclasses get the right instances. Since every application of a mixin creates a new class, `hasMixin` can''t compare classes directly: `defineMixin` records each produced class in a `WeakSet`, and `hasMixin` walks the object''s prototype chain looking for one.","uk":"Оскільки `extends` приймає будь-який вираз, кожен міксин є просто `(Base) => class extends Base { … }`, а їхнє накладання будує звичайний ланцюжок прототипів, тож `super`, `instanceof` і аргументи конструктора й далі працюють. `#listeners` тримає сховище слухачів приватним для кожного екземпляра. `fromJSON` використовує `this` у статичному методі, що посилається на клас, на якому його викликали, тож підкласи отримують правильні екземпляри. Оскільки кожне застосування міксину створює новий клас, `hasMixin` не може порівнювати класи напряму: `defineMixin` записує кожен створений клас у `WeakSet`, а `hasMixin` проходить ланцюжок прототипів об''єкта в пошуку такого класу."}'::jsonb, '{"/src/mixins.ts":"export type Ctor<T = object> = new (...args: any[]) => T;\n\n// For each mixin, the set of classes it has produced. Weak, so unused classes can be collected.\nconst produced = new WeakMap<Function, WeakSet<Function>>();\n\nexport function defineMixin<F extends (Base: Ctor) => Ctor>(factory: F): F {\n  const classes = new WeakSet<Function>();\n  const mixin = ((Base: Ctor) => {\n    const Mixed = factory(Base);\n    classes.add(Mixed);\n    return Mixed;\n  }) as F;\n  produced.set(mixin, classes);\n  return mixin;\n}\n\nexport function hasMixin(obj: unknown, mixin: Function): boolean {\n  const classes = produced.get(mixin);\n  if (!classes || typeof obj !== \"object\" || obj === null) return false;\n  for (let proto = Object.getPrototypeOf(obj); proto; proto = Object.getPrototypeOf(proto)) {\n    if (classes.has(proto.constructor)) return true;\n  }\n  return false;\n}\n\nexport const Timestamped = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  createdAt = Date.now();\n  updatedAt = this.createdAt;\n  touch() {\n    this.updatedAt = Date.now();\n    return this;\n  }\n});\n\nexport const Observable = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  #listeners = new Map<string, Set<(payload?: unknown) => void>>();\n  on(event: string, fn: (payload?: unknown) => void) {\n    if (!this.#listeners.has(event)) this.#listeners.set(event, new Set());\n    this.#listeners.get(event)!.add(fn);\n    return () => {\n      this.#listeners.get(event)?.delete(fn);\n    };\n  }\n  emit(event: string, payload?: unknown) {\n    for (const fn of [...(this.#listeners.get(event) ?? [])]) fn(payload);\n  }\n});\n\nexport const Serializable = defineMixin(<B extends Ctor>(Base: B) => class extends Base {\n  toJSON() {\n    const data: Record<string, unknown> = { type: this.constructor.name };\n    for (const [key, value] of Object.entries(this)) {\n      if (typeof value !== \"function\") data[key] = value;\n    }\n    return data;\n  }\n  static fromJSON<T>(this: new () => T, json: Record<string, unknown>): T {\n    const { type: _type, ...data } = json;\n    // \"this\" is the class fromJSON was called on, so subclasses get instances of themselves.\n    return Object.assign(new this(), data);\n  }\n});\n"}'::jsonb),
  ('cls-shape-registry', null::text[], '{"en":"`new.target` holds the class that `new` was called with, so the base constructor can reject direct instantiation while allowing subclasses. A `static #registry` keeps the type map private to `Shape`, and `static { Shape.register(this); }` runs once while each subclass is defined, so adding a shape needs no central switch statement (the open/closed principle). `toJSON` combines the static `type` (looked up via `this.constructor`) with each class''s `data()`, so private fields stay hidden but serialisation still works, and `from` reverses it.","uk":"`new.target` містить клас, з яким викликали `new`, тож базовий конструктор може відхилити пряме створення, дозволяючи підкласи. `static #registry` тримає мапу типів приватною для `Shape`, а `static { Shape.register(this); }` виконується один раз під час визначення кожного підкласу, тож додавання фігури не потребує центрального `switch` (принцип відкритості/закритості). `toJSON` поєднує статичний `type` (знайдений через `this.constructor`) з `data()` кожного класу, тож приватні поля лишаються прихованими, а серіалізація все одно працює, і `from` виконує зворотне перетворення."}'::jsonb, '{"/src/shapes.ts":"export type ShapeData = { type: string; [key: string]: unknown };\ntype ShapeClass = (new (data: any) => Shape) & { type: string };\n\nexport class Shape {\n  static type = \"shape\";\n  static #registry = new Map<string, ShapeClass>();\n\n  static register(cls: ShapeClass) {\n    Shape.#registry.set(cls.type, cls);\n  }\n  static from(data: ShapeData): Shape {\n    const cls = Shape.#registry.get(data?.type);\n    if (!cls) throw new TypeError(\"Unknown shape type: \" + String(data?.type));\n    return new cls(data);\n  }\n  static get types(): string[] {\n    return [...Shape.#registry.keys()];\n  }\n\n  constructor() {\n    if (new.target === Shape) throw new TypeError(\"Shape is abstract\");\n  }\n  get area(): number {\n    throw new Error(\"area is not implemented\");\n  }\n  protected data(): Record<string, unknown> {\n    return {};\n  }\n  toJSON() {\n    return { type: (this.constructor as ShapeClass).type, ...this.data() };\n  }\n}\n\nfunction positive(name: string, value: unknown): number {\n  if (typeof value !== \"number\" || !Number.isFinite(value) || value <= 0) {\n    throw new RangeError(name + \" must be a positive number\");\n  }\n  return value;\n}\n\nexport class Circle extends Shape {\n  static type = \"circle\";\n  static {\n    Shape.register(this);\n  }\n  #radius = 0;\n  constructor({ radius }: { radius: number }) {\n    super();\n    this.radius = radius;\n  }\n  get radius() {\n    return this.#radius;\n  }\n  set radius(value: number) {\n    this.#radius = positive(\"radius\", value);\n  }\n  get area() {\n    return Math.PI * this.#radius ** 2;\n  }\n  protected data() {\n    return { radius: this.#radius };\n  }\n}\n\nexport class Rect extends Shape {\n  static type = \"rect\";\n  static {\n    Shape.register(this);\n  }\n  #width = 0;\n  #height = 0;\n  constructor({ width, height }: { width: number; height: number }) {\n    super();\n    this.width = width;\n    this.height = height;\n  }\n  get width() {\n    return this.#width;\n  }\n  set width(value: number) {\n    this.#width = positive(\"width\", value);\n  }\n  get height() {\n    return this.#height;\n  }\n  set height(value: number) {\n    this.#height = positive(\"height\", value);\n  }\n  get area() {\n    return this.#width * this.#height;\n  }\n  protected data(): Record<string, unknown> {\n    return { width: this.#width, height: this.#height };\n  }\n}\n"}'::jsonb),
  ('col-same-value-zero', array['a']::text[], '{"en":"`Set` and `Map` use SameValueZero: like `===`, except that `NaN` equals `NaN`. So the two `NaN`s collapse into one, `0` and `-0` are the same, and the string `\"0\"` is different from the number `0`: `NaN`, `0`, `\"0\"`.","uk":"`Set` і `Map` використовують SameValueZero: як `===`, але `NaN` дорівнює `NaN`. Тож два `NaN` зливаються в один, `0` і `-0` однакові, а рядок `\"0\"` відрізняється від числа `0`: `NaN`, `0`, `\"0\"`."}'::jsonb, null::jsonb),
  ('col-object-keys-by-reference', array['a']::text[], '{"en":"Object keys are compared **by reference**. Each `{ id: 1 }` literal is a new object, so the map holds two entries, and `get` with a third new object finds neither. Keep the original reference, or key by a primitive like the `id`.","uk":"Ключі-об''єкти порівнюються **за посиланням**. Кожен літерал `{ id: 1 }` є новим об''єктом, тож мапа містить два записи, а `get` із третім новим об''єктом не знаходить жодного. Зберігайте початкове посилання або використовуйте ключем примітив, як-от `id`."}'::jsonb, null::jsonb),
  ('col-object-as-dictionary', array['a']::text[], '{"en":"Plain-object keys are strings (or symbols), so both objects are converted to the same string `\"[object Object]\"` and the second write overwrites the first. That''s the main reason to use a `Map` (or `WeakMap`) when keys are objects.","uk":"Ключі звичайного об''єкта є рядками (чи символами), тож обидва об''єкти перетворюються на той самий рядок `\"[object Object]\"`, і другий запис перезаписує перший. Це головна причина використовувати `Map` (чи `WeakMap`), коли ключі є об''єктами."}'::jsonb, null::jsonb),
  ('col-json-map', array['a']::text[], '{"en":"A `Map` keeps its entries in internal slots, not properties, so `JSON.stringify` sees an object with no enumerable properties: `{}`. That silently drops data in API responses and `localStorage`. Convert explicitly: `Object.fromEntries(map)` for string keys, or `[...map]` to keep entries of any key type.","uk":"`Map` тримає записи у внутрішніх слотах, а не у властивостях, тож `JSON.stringify` бачить об''єкт без перелічуваних властивостей: `{}`. Це мовчки втрачає дані у відповідях API і `localStorage`. Перетворюйте явно: `Object.fromEntries(map)` для рядкових ключів або `[...map]`, щоб зберегти записи з ключами будь-якого типу."}'::jsonb, null::jsonb),
  ('col-key-order', array['a']::text[], '{"en":"A `Map` keeps pure insertion order: re-setting `b` keeps its position, while deleting and re-adding `a` moves it to the end (the trick LRU caches use). Plain objects list integer-like keys first in ascending order, then string keys in insertion order, which surprises people who use numeric ids as keys.","uk":"`Map` зберігає чистий порядок вставлення: повторне присвоєння `b` зберігає його позицію, а видалення й повторне додавання `a` переносить його в кінець (цей прийом використовують LRU-кеші). Звичайні об''єкти спершу перелічують цілочисельні ключі за зростанням, а потім рядкові в порядку вставлення, і це дивує тих, хто використовує числові id як ключі."}'::jsonb, null::jsonb),
  ('col-live-iteration', array['a']::text[], '{"en":"Map and Set iterators are **live**: entries added during iteration are visited too (and entries deleted before they''re reached are skipped). Here each visit adds the next number until `x < 4` is false, so the loop ends after 4. Unlike Java, there''s no concurrent-modification error, so a careless loop can run forever if it keeps adding new values.","uk":"Ітератори Map і Set **живі**: записи, додані під час перебору, теж відвідуються (а записи, видалені до того, як до них дійшли, пропускаються). Тут кожне відвідування додає наступне число, доки `x < 4` не стане хибним, тож цикл завершується після 4. На відміну від Java, помилки одночасної зміни немає, тож необережний цикл може працювати вічно, якщо постійно додає нові значення."}'::jsonb, null::jsonb),
  ('col-weakmap-api', array['a']::text[], '{"en":"A `WeakMap` has no `size` and isn''t iterable, because its contents depend on when the garbage collector runs: exposing them would make programs non-deterministic. Its keys must be objects (or non-registered symbols), since a primitive like `\"key\"` can always be recreated and so could never be collected; `set` throws a `TypeError`.","uk":"`WeakMap` не має `size` і не ітерований, бо його вміст залежить від того, коли спрацює збирач сміття: показ вмісту зробив би програми недетермінованими. Його ключами мають бути об''єкти (чи незареєстровані символи), бо примітив на кшталт `\"key\"` завжди можна створити знову, тож його ніколи не можна було б прибрати; `set` кидає `TypeError`."}'::jsonb, null::jsonb),
  ('col-set-methods', array['a']::text[], '{"en":"`intersection` keeps values in both sets, `difference` keeps values of `a` that aren''t in `b` (it''s not symmetric), and `symmetricDifference` keeps values in exactly one of them. `isSubsetOf` checks that every value of `a` is in the argument. These methods return new Sets and replace the old `[...a].filter((x) => b.has(x))` idioms.","uk":"`intersection` залишає значення, що є в обох множинах, `difference` залишає значення `a`, яких немає в `b` (вона не симетрична), а `symmetricDifference` залишає значення, що є рівно в одній з них. `isSubsetOf` перевіряє, що кожне значення `a` є в аргументі. Ці методи повертають нові Set і замінюють старі ідіоми `[...a].filter((x) => b.has(x))`."}'::jsonb, null::jsonb),
  ('col-typed-array-overflow', array['a']::text[], '{"en":"Typed arrays convert every value to their element type. `Uint8Array` takes values modulo 256 after dropping the fraction (`256` → `0`, `-1` → `255`, `3.7` → `3`). `Uint8ClampedArray`, made for canvas pixel data, clamps to 0–255 and rounds half to even (`1.5` → `2`). Neither throws on bad input, so validate data before writing it.","uk":"Типізовані масиви перетворюють кожне значення на тип свого елемента. `Uint8Array` бере значення за модулем 256 після відкидання дробової частини (`256` → `0`, `-1` → `255`, `3.7` → `3`). `Uint8ClampedArray`, створений для пікселів canvas, обмежує значення діапазоном 0–255 і округлює половину до парного (`1.5` → `2`). Жоден не кидає помилку на хибних даних, тож перевіряйте дані перед записом."}'::jsonb, null::jsonb),
  ('col-subarray-vs-slice', array['a']::text[], '{"en":"`subarray` creates a new **view** over the same `ArrayBuffer`, so writes to the original show through it. `slice` **copies** the bytes into a new buffer. Views are what make zero-copy parsing of binary data possible (and also what makes accidental sharing bugs possible).","uk":"`subarray` створює нове **представлення** того самого `ArrayBuffer`, тож записи в початковий масив видно через нього. `slice` **копіює** байти в новий буфер. Представлення роблять можливим розбір бінарних даних без копіювання (і так само роблять можливими помилки через випадкове спільне використання)."}'::jsonb, null::jsonb),
  ('col-weakmap-use', array['a']::text[], '{"en":"A `Map` holds its keys strongly, so every element ever measured (and its subtree) stays in memory as a detached node: a classic leak. A `WeakMap` doesn''t keep keys alive, so once the element is removed and unreferenced, the entry can be collected. Keying by `el.id` would only work for elements with unique ids and still never clean up.","uk":"`Map` тримає свої ключі сильно, тож кожен елемент, який колись вимірювали (і його піддерево), лишається в пам''яті як від''єднаний вузол: класичний витік. `WeakMap` не тримає ключі живими, тож щойно елемент видалено й на нього ніщо не посилається, запис можна прибрати. Ключ `el.id` спрацював би лише для елементів з унікальними id і все одно ніколи б не очищувався."}'::jsonb, null::jsonb),
  ('col-memoize-any-args', null::text[], '{"en":"Instead of serialising arguments into one string key, walk a trie: the first level is keyed by the argument count, then one level per argument. Each node stores primitive keys in a `Map` (SameValueZero, so `NaN` matches itself and types stay distinct) and object or function keys in a `WeakMap`, so the cache never prevents garbage collection of arguments. A separate `hasResult` flag lets `undefined` results be cached, and storing the result only after `fn` returns means errors aren''t cached.","uk":"Замість серіалізації аргументів в один рядковий ключ пройдіть префіксним деревом: перший рівень має ключем кількість аргументів, далі по рівню на кожен аргумент. Кожен вузол зберігає примітивні ключі в `Map` (SameValueZero, тож `NaN` збігається сам із собою, а типи лишаються різними), а ключі-об''єкти й функції у `WeakMap`, тож кеш ніколи не заважає збирачу сміття прибрати аргументи. Окремий прапорець `hasResult` дозволяє кешувати результати `undefined`, а збереження результату лише після повернення з `fn` означає, що помилки не кешуються."}'::jsonb, '{"/src/memoize.ts":"// One trie node per argument position. Objects go in a WeakMap so cached entries\n// don''t keep them alive; primitives go in a Map (SameValueZero: NaN finds NaN).\nclass Node {\n  primitives = new Map<unknown, Node>();\n  objects = new WeakMap<object, Node>();\n  hasResult = false;\n  result: unknown;\n\n  child(key: unknown): Node {\n    const isObject = (typeof key === \"object\" && key !== null) || typeof key === \"function\";\n    const store: Map<unknown, Node> | WeakMap<object, Node> = isObject ? this.objects : this.primitives;\n    let next = (store as Map<unknown, Node>).get(key);\n    if (!next) {\n      next = new Node();\n      (store as Map<unknown, Node>).set(key, next);\n    }\n    return next;\n  }\n}\n\nexport function memoize<A extends unknown[], R>(fn: (...args: A) => R): ((...args: A) => R) & { clear(): void } {\n  let root = new Node();\n  const memoized = (...args: A): R => {\n    // The argument count is the first key, so f(1) and f(1, undefined) are different calls.\n    let node = root.child(args.length);\n    for (const arg of args) node = node.child(arg);\n    if (node.hasResult) return node.result as R;\n    const result = fn(...args); // if this throws, nothing is cached\n    node.result = result;\n    node.hasResult = true;\n    return result;\n  };\n  return Object.assign(memoized, {\n    clear() {\n      root = new Node();\n    },\n  });\n}\n"}'::jsonb),
  ('col-tag-index', null::text[], '{"en":"Two `Map<string, Set<string>>` indexes give O(1) membership checks in both directions: `tag → ids` answers \"does this item have this tag\" without scanning the item''s tags, and `id → tags` makes removal cheap. Iterating the `id → tags` map keeps results in insertion order for free, because Maps remember it. Sets deduplicate merged tags automatically, and deleting a tag''s entry when its set becomes empty keeps `tags()` accurate.","uk":"Два індекси `Map<string, Set<string>>` дають перевірку належності за O(1) в обох напрямках: `tag → ids` відповідає на питання «чи має елемент цей тег» без сканування тегів елемента, а `id → tags` робить видалення дешевим. Перебір мапи `id → tags` безкоштовно зберігає порядок вставлення в результатах, бо Map його пам''ятає. Set автоматично прибирає дублікати під час злиття тегів, а видалення запису тегу, коли його множина спорожніла, тримає `tags()` точним."}'::jsonb, '{"/src/tags.ts":"export type Query = { all?: string[]; any?: string[]; none?: string[] };\n\nexport class TagIndex {\n  // Two maps of Sets: id → its tags, and tag → its ids. Map keeps insertion order for ids.\n  #tagsById = new Map<string, Set<string>>();\n  #idsByTag = new Map<string, Set<string>>();\n\n  add(id: string, tags: Iterable<string>): void {\n    if (!this.#tagsById.has(id)) this.#tagsById.set(id, new Set());\n    const own = this.#tagsById.get(id)!;\n    for (const tag of tags) {\n      own.add(tag);\n      if (!this.#idsByTag.has(tag)) this.#idsByTag.set(tag, new Set());\n      this.#idsByTag.get(tag)!.add(id);\n    }\n  }\n\n  untag(id: string, tag: string): void {\n    this.#tagsById.get(id)?.delete(tag);\n    const ids = this.#idsByTag.get(tag);\n    if (!ids) return;\n    ids.delete(id);\n    if (ids.size === 0) this.#idsByTag.delete(tag);\n  }\n\n  remove(id: string): void {\n    for (const tag of this.#tagsById.get(id) ?? []) this.untag(id, tag);\n    this.#tagsById.delete(id);\n  }\n\n  query({ all = [], any = [], none = [] }: Query = {}): string[] {\n    const idsFor = (tag: string) => this.#idsByTag.get(tag) ?? new Set<string>();\n    const result: string[] = [];\n    for (const id of this.#tagsById.keys()) {\n      if (!all.every((tag) => idsFor(tag).has(id))) continue;\n      if (any.length > 0 && !any.some((tag) => idsFor(tag).has(id))) continue;\n      if (none.some((tag) => idsFor(tag).has(id))) continue;\n      result.push(id);\n    }\n    return result;\n  }\n\n  tags(): [string, number][] {\n    return [...this.#idsByTag]\n      .map(([tag, ids]): [string, number] => [tag, ids.size])\n      .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));\n  }\n}\n"}'::jsonb),
  ('eng-jit-warmup', array['a']::text[], '{"en":"Engines start by interpreting bytecode, which is quick to produce but slow to run. They record which types and object shapes each operation sees, and when a function is hot, an optimising JIT compiles it to machine code specialised for those types. That''s also why benchmarks need warm-up runs.","uk":"Рушії починають з інтерпретації байткоду, який швидко отримати, але повільно виконувати. Вони записують, які типи й форми об''єктів бачить кожна операція, а коли функція гаряча, оптимізувальний JIT компілює її в машинний код, спеціалізований для цих типів. Тому ж бенчмаркам потрібні розігрівальні запуски."}'::jsonb, null::jsonb),
  ('eng-deopt', array['a']::text[], '{"en":"Optimised code contains cheap checks (guards) for its assumptions. When a guard fails, the engine **deoptimises**: it reconstructs the interpreter state and continues there, so results are always correct, only slower. Functions that keep receiving mixed types can bounce between tiers, which is why consistent types on hot paths help.","uk":"Оптимізований код містить дешеві перевірки (guards) своїх припущень. Коли перевірка не проходить, рушій **деоптимізує** функцію: відновлює стан інтерпретатора й продовжує там, тож результати завжди правильні, лише повільніші. Функції, що постійно отримують змішані типи, можуть стрибати між рівнями, тому сталі типи на гарячих шляхах допомагають."}'::jsonb, null::jsonb),
  ('eng-hidden-classes', array['a']::text[], '{"en":"A shape records which properties an object has **and the order they were added**. Starting from the same empty shape, `p1` and `p3` follow the same transitions (`+x`, then `+y`), so they share a shape; the values don''t matter. `p2` adds `y` first and ends on a different branch of the transition tree. Code that sees both kinds becomes polymorphic. Creating objects the same way, ideally in one constructor or factory, keeps them uniform. (Object literals get their own starting shapes, so even `{ x: 1, y: 2 }` wouldn''t match `p1`.)","uk":"Форма записує, які властивості має об''єкт, **і в якому порядку їх додано**. Починаючи з тієї самої порожньої форми, `p1` і `p3` проходять ті самі переходи (`+x`, потім `+y`), тож мають спільну форму; значення не мають значення. `p2` спершу додає `y` і опиняється на іншій гілці дерева переходів. Код, що бачить обидва види, стає поліморфним. Створення об''єктів однаково, найкраще в одному конструкторі чи фабриці, тримає їх однорідними. (Літерали об''єктів отримують власні початкові форми, тож навіть `{ x: 1, y: 2 }` не збігся б із `p1`.)"}'::jsonb, null::jsonb),
  ('eng-delete-property', array['a']::text[], '{"en":"Removing a property (other than the last one added) usually can''t be expressed as a shape transition, so V8 switches the object to **dictionary mode**, a hash table that''s slower to access and defeats inline caches. Setting the property to `undefined` keeps the fast shape. The behavioural difference matters: `in`, `hasOwn`, `Object.keys` and JSON (which drops `undefined` values) treat the two differently. Outside hot paths, prefer clarity.","uk":"Видалення властивості (крім останньої доданої) зазвичай не можна виразити як перехід форми, тож V8 перемикає об''єкт у **режим словника**, хеш-таблицю, доступ до якої повільніший і яка зводить нанівець inline-кеші. Присвоєння властивості `undefined` зберігає швидку форму. Відмінність у поведінці важлива: `in`, `hasOwn`, `Object.keys` і JSON (що відкидає значення `undefined`) обробляють ці два випадки по-різному. Поза гарячими шляхами віддавайте перевагу зрозумілості."}'::jsonb, null::jsonb),
  ('eng-megamorphic', array['a']::text[], '{"en":"Each property access site has an inline cache. With one shape it''s monomorphic and compiles to a direct offset load; with a few (V8 allows 4) it''s polymorphic and checks each; beyond that it''s megamorphic and uses a generic hash lookup. Normalising data into one shape (a single factory or class) at the boundary keeps hot loops monomorphic.","uk":"Кожне місце доступу до властивості має inline-кеш. З однією формою він мономорфний і компілюється в пряме завантаження за зміщенням; з кількома (V8 дозволяє 4) він поліморфний і перевіряє кожну; понад те він мегаморфний і використовує загальний пошук у хеш-таблиці. Нормалізація даних в одну форму (одна фабрика чи клас) на межі системи тримає гарячі цикли мономорфними."}'::jsonb, null::jsonb),
  ('eng-holey-arrays', array['a']::text[], '{"en":"V8 tracks an array''s **elements kind**: packed or holey, and small integers, doubles or generic objects. `new Array(n)` and writing past the end create **holes**, and the array stays \"holey\" even after it''s filled, so reads must check for holes and the prototype chain. Element kinds only move towards more general ones, so pushing into `[]` (or using `Array.from({ length: n }, fn)`) keeps arrays packed and fast. It matters for large hot arrays only.","uk":"V8 відстежує **вид елементів** масиву: щільний (packed) чи дірявий (holey), і малі цілі, дробові чи загальні об''єкти. `new Array(n)` і запис за межі кінця створюють **дірки**, і масив лишається «дірявим» навіть після заповнення, тож читання мають перевіряти дірки й ланцюжок прототипів. Види елементів змінюються лише в бік загальніших, тож додавання в `[]` (чи `Array.from({ length: n }, fn)`) тримає масиви щільними й швидкими. Це важливо лише для великих гарячих масивів."}'::jsonb, null::jsonb),
  ('eng-generational-gc', array['a']::text[], '{"en":"The generational hypothesis says most objects die young. V8 allocates them in a small young generation with a fast bump pointer and cleans it with a **scavenger** that copies only live objects, so dead temporary objects cost almost nothing to collect. Objects that survive a couple of scavenges move to the old generation, which is collected less often by mark-sweep-compact. Long-lived caches and retained objects are what make GC expensive.","uk":"Гіпотеза поколінь каже, що більшість об''єктів помирає молодими. V8 виділяє їх у невеликому молодому поколінні швидким зсувом вказівника й чистить його **scavenger**-ом, що копіює лише живі об''єкти, тож прибирання мертвих тимчасових об''єктів майже нічого не коштує. Об''єкти, що пережили кілька прибирань, переходять у старе покоління, яке mark-sweep-compact збирає рідше. Дорогим GC роблять довгоживучі кеші й утримувані об''єкти."}'::jsonb, null::jsonb),
  ('eng-listener-leak', array['a']::text[], '{"en":"`window` lives as long as the page, and it holds strong references to its listeners; active timers are also GC roots. Their closures capture the widget (and through it, its DOM and data), so none of it can be collected, and each copy keeps polling and reacting to resizes. Pair every subscription with a cleanup: `{ signal }` from an `AbortController`, `removeEventListener`, `clearInterval`, `unsubscribe`, or React''s effect cleanup.","uk":"`window` живе стільки, скільки сторінка, і тримає сильні посилання на своїх слухачів; активні таймери теж є коренями GC. Їхні замикання захоплюють віджет (а через нього його DOM і дані), тож нічого з цього не можна прибрати, а кожна копія продовжує опитувати сервер і реагувати на зміну розміру. Поєднуйте кожну підписку з очищенням: `{ signal }` з `AbortController`, `removeEventListener`, `clearInterval`, `unsubscribe` чи функція очищення ефекту в React."}'::jsonb, null::jsonb),
  ('eng-shared-closure-context', array['a']::text[], '{"en":"Engines don''t give each closure its own copy of the variables it uses. Variables captured by **any** inner function go into a single context object for that scope, and every closure from that scope references it. Because `debug` mentions `big`, `big` lives in the shared context, and the returned handler keeps it alive even though it never uses it. Fix it by not capturing large values in long-lived scopes, extracting only what''s needed (`const size = big.length`) or setting `big = null` when done.","uk":"Рушії не дають кожному замиканню власну копію змінних, які воно використовує. Змінні, захоплені **будь-якою** внутрішньою функцією, потрапляють в один об''єкт контексту для цієї області видимості, і кожне замикання з неї посилається на нього. Оскільки `debug` згадує `big`, `big` живе в спільному контексті, і повернений обробник тримає його живим, хоча ніколи не використовує. Виправлення: не захоплюйте великі значення в довгоживучих областях видимості, витягуйте лише потрібне (`const size = big.length`) або присвойте `big = null`, коли закінчите."}'::jsonb, null::jsonb),
  ('eng-dead-code-benchmark', array['a']::text[], '{"en":"Optimising compilers remove computations whose results have no observable effect, and `Math.sqrt` has none. The benchmark then measures an empty loop. Make the result observable (accumulate it and use it afterwards, or store it in a \"black hole\" variable), and prefer a benchmarking library that does this, warms up and reports a margin of error.","uk":"Оптимізувальні компілятори видаляють обчислення, чиї результати не мають помітного ефекту, а `Math.sqrt` такого ефекту не має. Тоді бенчмарк вимірює порожній цикл. Зробіть результат помітним (накопичуйте його й використайте потім або зберігайте в змінній-«чорній дірі») і віддавайте перевагу бібліотеці для бенчмарків, що робить це, розігріває код і показує похибку."}'::jsonb, null::jsonb),
  ('eng-benchmark-order', array['a']::text[], '{"en":"Whatever runs first pays for JIT warm-up, lazy compilation, cache misses and maybe a GC triggered by earlier allocations, so one-shot sequential timings mostly measure order. Warm up each candidate, collect many samples, alternate or isolate them, and look at medians and confidence intervals. If the difference is within the noise, it doesn''t exist for practical purposes.","uk":"Те, що виконується першим, платить за розігрів JIT, ліниву компіляцію, промахи кешу й, можливо, GC, спричинений попередніми виділеннями пам''яті, тож одноразові послідовні виміри здебільшого вимірюють порядок. Розігрійте кожного кандидата, зберіть багато вимірів, чергуйте чи ізолюйте їх і дивіться на медіани й довірчі інтервали. Якщо різниця в межах шуму, на практиці її не існує."}'::jsonb, null::jsonb),
  ('eng-tail-calls', array['a']::text[], '{"en":"The recursive call is in tail position, and ES2015 specifies proper tail calls that would reuse the stack frame, but only Safari''s JavaScriptCore implements them. V8 and SpiderMonkey keep a frame per call, so a million levels overflow the stack with `RangeError: Maximum call stack size exceeded`. Write deep recursion as a loop (or use an explicit stack or a trampoline).","uk":"Рекурсивний виклик стоїть у хвостовій позиції, і ES2015 визначає правильні хвостові виклики, що повторно використовували б кадр стеку, але реалізує їх лише JavaScriptCore у Safari. V8 і SpiderMonkey тримають по кадру на виклик, тож мільйон рівнів переповнює стек із `RangeError: Maximum call stack size exceeded`. Пишіть глибоку рекурсію як цикл (або використайте явний стек чи трамплін)."}'::jsonb, null::jsonb),
  ('eng-bench-stats', null::text[], '{"en":"Each piece addresses a benchmarking pitfall. Warm-up runs let the JIT optimise before measuring; batching many calls per timer read beats coarse timer resolution; writing results to a black hole prevents dead-code elimination; and summarising many samples with a median and a margin of error exposes noise. `compare` only reports a winner when the confidence intervals are separate, which stops you from \"optimising\" based on random variation. Injecting the clock makes the timing logic itself testable.","uk":"Кожна частина відповідає на пастку бенчмарків. Розігрівальні запуски дають JIT оптимізувати код до вимірювання; групування багатьох викликів на одне зчитування таймера долає грубу роздільну здатність таймера; запис результатів у «чорну діру» запобігає видаленню мертвого коду; а підсумок багатьох вимірів медіаною й похибкою показує шум. `compare` називає переможця, лише коли довірчі інтервали не перетинаються, і це не дає «оптимізувати» на основі випадкових коливань. Підміна годинника робить саму логіку вимірювання придатною для тестування."}'::jsonb, '{"/src/bench.ts":"export type Summary = {\n  n: number;\n  mean: number;\n  median: number;\n  min: number;\n  max: number;\n  stdDev: number;\n  p95: number;\n  moe: number;\n  rme: number;\n};\n\nexport function summarize(samples: number[]): Summary {\n  const n = samples.length;\n  if (n === 0) throw new RangeError(\"No samples\");\n  const sorted = [...samples].sort((a, b) => a - b);\n  const mean = samples.reduce((sum, x) => sum + x, 0) / n;\n  const mid = Math.floor(n / 2);\n  const median = n % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;\n  const variance = n > 1 ? samples.reduce((sum, x) => sum + (x - mean) ** 2, 0) / (n - 1) : 0;\n  const stdDev = Math.sqrt(variance);\n  const p95 = sorted[Math.ceil(0.95 * n) - 1];\n  const moe = (1.96 * stdDev) / Math.sqrt(n);\n  const rme = mean === 0 ? 0 : (moe / mean) * 100;\n  return { n, mean, median, min: sorted[0], max: sorted[n - 1], stdDev, p95, moe, rme };\n}\n\nexport function compare(a: number[], b: number[]): \"faster\" | \"slower\" | \"same\" {\n  const sa = summarize(a);\n  const sb = summarize(b);\n  // Only call it a difference when the 95% confidence intervals don''t overlap.\n  if (sa.mean + sa.moe < sb.mean - sb.moe) return \"faster\";\n  if (sa.mean - sa.moe > sb.mean + sb.moe) return \"slower\";\n  return \"same\";\n}\n\nexport const blackhole: { value: unknown } = { value: undefined };\n\nexport type MeasureOptions = { warmup?: number; runs?: number; batch?: number; now?: () => number };\n\nexport function measure(fn: () => unknown, { warmup = 5, runs = 20, batch = 1, now = () => performance.now() }: MeasureOptions = {}): number[] {\n  if (runs < 1 || batch < 1) throw new RangeError(\"runs and batch must be at least 1\");\n  // Warm-up calls let the JIT optimise before we start measuring.\n  for (let i = 0; i < warmup; i++) blackhole.value = fn();\n  const samples: number[] = [];\n  for (let r = 0; r < runs; r++) {\n    const start = now();\n    // Batching measures many calls per timer read, beating coarse timer resolution.\n    for (let i = 0; i < batch; i++) blackhole.value = fn();\n    samples.push((now() - start) / batch);\n  }\n  return samples;\n}\n"}'::jsonb),
  ('eng-disposer', null::text[], '{"en":"Pairing every setup with its teardown at the moment of setup makes leaks hard to write: the cleanup can''t be forgotten later. Running cleanups LIFO undoes things in the reverse order they were built, like a stack unwinding. Catching each cleanup''s error and rethrowing them together as an `AggregateError` guarantees that one failure doesn''t leave other resources alive. Running late additions immediately covers async setup that finishes after the component is gone. This is the same idea as React effect cleanups, RxJS subscriptions and the `DisposableStack` / `using` proposal.","uk":"Поєднання кожного налаштування з його демонтажем у момент налаштування ускладнює написання витоків: очищення неможливо забути пізніше. Виконання очищень за принципом LIFO скасовує дії у зворотному до побудови порядку, як розмотування стеку. Перехоплення помилки кожного очищення й повторне кидання їх разом як `AggregateError` гарантує, що одна невдача не залишить інші ресурси живими. Негайне виконання пізніх додавань покриває асинхронне налаштування, що завершується після зникнення компонента. Це та сама ідея, що й функції очищення ефектів у React, підписки RxJS і пропозиція `DisposableStack` / `using`."}'::jsonb, '{"/src/disposer.ts":"export class Disposer {\n  #cleanups: Array<() => void> = [];\n  #disposed = false;\n\n  add(cleanup: () => void): () => void {\n    // Registering after dispose (e.g. when an await finishes late) cleans up right away instead of leaking.\n    if (this.#disposed) cleanup();\n    else this.#cleanups.push(cleanup);\n    return cleanup;\n  }\n\n  listen(target: EventTarget, type: string, handler: (event: Event) => void): void {\n    target.addEventListener(type, handler);\n    this.add(() => target.removeEventListener(type, handler));\n  }\n\n  interval(callback: () => void, ms: number): void {\n    const id = setInterval(callback, ms);\n    this.add(() => clearInterval(id));\n  }\n\n  child(): Disposer {\n    const child = new Disposer();\n    const disposeChild = this.add(() => child.dispose());\n    // If the child is disposed on its own, stop tracking it.\n    child.add(() => {\n      const i = this.#cleanups.indexOf(disposeChild);\n      if (i !== -1) this.#cleanups.splice(i, 1);\n    });\n    return child;\n  }\n\n  get disposed(): boolean {\n    return this.#disposed;\n  }\n\n  dispose(): void {\n    if (this.#disposed) return;\n    this.#disposed = true;\n    const errors: unknown[] = [];\n    // Last in, first out: undo things in the reverse order they were set up.\n    while (this.#cleanups.length > 0) {\n      const cleanup = this.#cleanups.pop()!;\n      try {\n        cleanup();\n      } catch (error) {\n        errors.push(error);\n      }\n    }\n    if (errors.length > 0) throw new AggregateError(errors, \"Some cleanups failed\");\n  }\n}\n"}'::jsonb),
  ('mp-symbol-unique', array['a']::text[], '{"en":"Every `Symbol()` call creates a new, unique value; the description is only a label for debugging. `Symbol.for(key)` looks the key up in a global registry and returns the same symbol for the same string everywhere (even across iframes), which is how separate libraries can agree on a shared symbol.","uk":"Кожен виклик `Symbol()` створює нове унікальне значення; опис є лише міткою для налагодження. `Symbol.for(key)` шукає ключ у глобальному реєстрі й повертає той самий символ для того самого рядка будь-де (навіть між iframe), і так окремі бібліотеки можуть домовитися про спільний символ."}'::jsonb, null::jsonb),
  ('mp-symbol-keys-hidden', array['a']::text[], '{"en":"Symbol keys are skipped by `JSON.stringify`, `Object.keys`, `for…in` and `Object.entries`, which makes them good for metadata that shouldn''t leak into serialisation or iteration. They aren''t truly private, though: `Reflect.ownKeys` and `Object.getOwnPropertySymbols` list them. For real privacy, use `#private` fields or closures.","uk":"Ключі-символи пропускають `JSON.stringify`, `Object.keys`, `for…in` і `Object.entries`, тож вони добре підходять для метаданих, що не повинні потрапляти в серіалізацію чи перебір. Однак вони не справді приватні: `Reflect.ownKeys` і `Object.getOwnPropertySymbols` їх показують. Для справжньої приватності використовуйте поля `#private` чи замикання."}'::jsonb, null::jsonb),
  ('mp-freeze-shallow', array['a']::text[], '{"en":"`Object.freeze` is shallow: `cfg.retries` can''t change (and in strict code the attempt throws a `TypeError`), but `cfg.api` is a separate object that isn''t frozen, so its `url` changes. Freeze nested objects recursively if you need deep immutability, or use libraries like Immer.","uk":"`Object.freeze` поверхневий: `cfg.retries` змінити не можна (у строгому коді спроба кидає `TypeError`), але `cfg.api` є окремим незамороженим об''єктом, тож його `url` змінюється. Якщо потрібна глибока незмінність, заморожуйте вкладені об''єкти рекурсивно або використовуйте бібліотеки на кшталт Immer."}'::jsonb, null::jsonb),
  ('mp-define-property-defaults', array['a']::text[], '{"en":"Properties created with `Object.defineProperty` default to `writable: false`, `enumerable: false` and `configurable: false`, unlike properties created by assignment or literals, where all three are `true`. So `hidden` exists and can be read, but it''s invisible to `Object.keys` and `JSON.stringify`, and it''s read-only.","uk":"Властивості, створені через `Object.defineProperty`, за замовчуванням мають `writable: false`, `enumerable: false` і `configurable: false`, на відміну від властивостей, створених присвоєнням чи в літералах, де всі три `true`. Тож `hidden` існує й читається, але невидима для `Object.keys` і `JSON.stringify` та доступна лише для читання."}'::jsonb, null::jsonb),
  ('mp-getter-setter', array['a']::text[], '{"en":"Assigning `temp.f` runs the setter, which stores the Celsius value (212 °F = 100 °C) in `_c`; reading `temp.f` runs the getter, which converts back. Accessors defined in an object literal are enumerable, so `f` appears in `Object.keys` alongside the backing field.","uk":"Присвоєння `temp.f` виконує сетер, що зберігає значення в Цельсіях (212 °F = 100 °C) у `_c`; читання `temp.f` виконує гетер, що перетворює назад. Аксесори, визначені в літералі об''єкта, перелічувані, тож `f` з''являється в `Object.keys` поряд із полем для зберігання."}'::jsonb, null::jsonb),
  ('mp-tostringtag', array['a']::text[], '{"en":"`Object.prototype.toString` builds `[object Tag]` from the value''s `Symbol.toStringTag` (built-ins like `Array` have internal tags, and `null`/`undefined` are special-cased). Defining the symbol on a class customises the tag for its instances, and `String(obj)` uses `toString` when there''s no `toPrimitive` or custom `toString`.","uk":"`Object.prototype.toString` будує `[object Tag]` із `Symbol.toStringTag` значення (вбудовані типи на кшталт `Array` мають внутрішні мітки, а `null`/`undefined` обробляються окремо). Визначення символу в класі налаштовує мітку його екземплярів, а `String(obj)` використовує `toString`, коли немає `toPrimitive` чи власного `toString`."}'::jsonb, null::jsonb),
  ('mp-proxy-defaults', array['a']::text[], '{"en":"The `get` trap only intercepts property reads, so a missing key reads as `0` without being created. The `in` operator uses the `has` trap and `Object.keys` uses `ownKeys`; neither is defined, so they fall through to the target, which has only `ada`. A convincing proxy needs consistent traps for every operation it pretends to change.","uk":"Пастка `get` перехоплює лише читання властивостей, тож відсутній ключ читається як `0`, не створюючись. Оператор `in` використовує пастку `has`, а `Object.keys` пастку `ownKeys`; жодну не визначено, тож вони переходять до цільового об''єкта, де є лише `ada`. Переконливий проксі потребує узгоджених пасток для кожної операції, яку він нібито змінює."}'::jsonb, null::jsonb),
  ('mp-reflect-receiver', array['a']::text[], '{"en":"`t[k]` runs the `full` getter with `this` = the **target**, so its reads of `first` and `last` bypass the proxy: only `full` is logged. `Reflect.get(t, k, r)` runs the getter with `this` = the **receiver** (the proxy), so `first` and `last` go through the trap too: 3 reads. Reactivity systems like Vue''s rely on this to track every dependency.","uk":"`t[k]` виконує гетер `full` з `this` = **цільовий об''єкт**, тож його читання `first` і `last` оминають проксі: записується лише `full`. `Reflect.get(t, k, r)` виконує гетер з `this` = **receiver** (проксі), тож `first` і `last` теж проходять крізь пастку: 3 читання. Системи реактивності, як-от у Vue, спираються на це, щоб відстежити кожну залежність."}'::jsonb, null::jsonb),
  ('mp-proxy-invariant', array['a']::text[], '{"en":"Traps can customise almost anything, but they must not contradict facts the engine guarantees. `id` is frozen (non-writable and non-configurable), so a `get` trap reporting a different value would break the guarantee that it never changes, and the engine throws a `TypeError`. Similar invariants apply to `has`, `ownKeys`, `deleteProperty` and `getOwnPropertyDescriptor`.","uk":"Пастки можуть налаштувати майже все, але не можуть суперечити фактам, які гарантує рушій. `id` заморожено (недоступне для запису й неналаштовуване), тож пастка `get`, що повідомляє інше значення, порушила б гарантію, що воно ніколи не змінюється, і рушій кидає `TypeError`. Подібні інваріанти діють для `has`, `ownKeys`, `deleteProperty` і `getOwnPropertyDescriptor`."}'::jsonb, null::jsonb),
  ('mp-observe', null::text[], '{"en":"The `get` trap wraps nested objects on access, extending the path, so depth costs nothing until it''s used and objects added later are covered automatically. The `set` trap compares old and new values with `Object.is` and only reports real changes; that also removes the redundant `length` write from `push`, because by then the index assignment has already updated the length. Forwarding with `Reflect` and the receiver keeps default semantics, including getters.","uk":"Пастка `get` загортає вкладені об''єкти під час доступу, подовжуючи шлях, тож глибина нічого не коштує, доки не використовується, а об''єкти, додані пізніше, покриваються автоматично. Пастка `set` порівнює старе й нове значення через `Object.is` і повідомляє лише про справжні зміни; це прибирає й зайвий запис `length` під час `push`, бо на той момент присвоєння індексу вже оновило довжину. Перенаправлення через `Reflect` з receiver зберігає типову семантику, зокрема гетери."}'::jsonb, '{"/src/observe.ts":"export type Change = {\n  type: \"set\" | \"delete\";\n  /** Keys from the observed root to the changed property, e.g. [\"user\", \"name\"]. */\n  path: string[];\n  oldValue: unknown;\n  newValue: unknown;\n};\n\nconst isObject = (v: unknown): v is object => typeof v === \"object\" && v !== null;\n\nexport function observe<T extends object>(target: T, onChange: (change: Change) => void): T {\n  const wrap = (obj: object, path: string[]): any =>\n    new Proxy(obj, {\n      get(t, key, receiver) {\n        // Pass the receiver so getters run with this = proxy; wrap nested objects lazily.\n        const value = Reflect.get(t, key, receiver);\n        return isObject(value) && typeof key === \"string\" ? wrap(value, [...path, key]) : value;\n      },\n      set(t, key, value, receiver) {\n        const had = Object.prototype.hasOwnProperty.call(t, key);\n        const oldValue = had ? (t as Record<PropertyKey, unknown>)[key] : undefined;\n        const ok = Reflect.set(t, key, value, receiver);\n        if (ok && typeof key === \"string\" && (!had || !Object.is(oldValue, value))) {\n          onChange({ type: \"set\", path: [...path, key], oldValue, newValue: value });\n        }\n        return ok;\n      },\n      deleteProperty(t, key) {\n        const had = Object.prototype.hasOwnProperty.call(t, key);\n        const oldValue = (t as Record<PropertyKey, unknown>)[key];\n        const ok = Reflect.deleteProperty(t, key);\n        if (ok && had && typeof key === \"string\") {\n          onChange({ type: \"delete\", path: [...path, key], oldValue, newValue: undefined });\n        }\n        return ok;\n      },\n    });\n  return wrap(target, []);\n}\n"}'::jsonb),
  ('mp-typed-model', null::text[], '{"en":"Each field is an enumerable accessor whose setter validates before writing to a private store, so invalid values never land and serialisation still sees normal fields. `Object.seal` blocks adding and deleting properties (strict code turns those attempts into `TypeError`s), while accessors keep working because sealing doesn''t make properties read-only. A non-enumerable `Symbol.toStringTag` brands the objects without showing up in keys or JSON.","uk":"Кожне поле є перелічуваним аксесором, чий сетер перевіряє значення перед записом у приватне сховище, тож хибні значення ніколи не потрапляють усередину, а серіалізація все одно бачить звичайні поля. `Object.seal` блокує додавання й видалення властивостей (строгий код перетворює ці спроби на `TypeError`), а аксесори працюють, бо запечатування не робить властивості доступними лише для читання. Неперелічуваний `Symbol.toStringTag` позначає об''єкти, не з''являючись у ключах чи JSON."}'::jsonb, '{"/src/model.ts":"export type FieldType = \"string\" | \"number\" | \"boolean\";\n\nexport function defineModel(schema: Record<string, FieldType>) {\n  const check = (key: string, value: unknown) => {\n    const expected = schema[key];\n    if (typeof value !== expected || (expected === \"number\" && Number.isNaN(value))) {\n      throw new TypeError(key + \" must be a \" + expected);\n    }\n  };\n\n  return function create(values: Record<string, unknown>): Record<string, unknown> {\n    for (const key of Object.keys(values)) {\n      if (!Object.prototype.hasOwnProperty.call(schema, key)) throw new TypeError(\"Unknown field: \" + key);\n    }\n    const store: Record<string, unknown> = {};\n    const model: Record<string, unknown> = {};\n    for (const key of Object.keys(schema)) {\n      if (!(key in values)) throw new TypeError(\"Missing field: \" + key);\n      check(key, values[key]);\n      store[key] = values[key];\n      // An enumerable accessor: shows up in keys/JSON, validates every write.\n      Object.defineProperty(model, key, {\n        enumerable: true,\n        get: () => store[key],\n        set: (value: unknown) => {\n          check(key, value);\n          store[key] = value;\n        },\n      });\n    }\n    Object.defineProperty(model, Symbol.toStringTag, { value: \"Model\" }); // non-enumerable\n    return Object.seal(model); // no new fields, no deleting\n  };\n}\n"}'::jsonb),
  ('vg-float-sum', array['a']::text[], '{"en":"Numbers are binary IEEE 754 doubles, and 0.1 and 0.2 have no exact binary representation, so their sum is `0.30000000000000004`. Compare floats with a tolerance; `Number.EPSILON` (about 2.2 × 10⁻¹⁶) works for values around 1. For money, calculate in integer cents instead.","uk":"Числа є двійковими подвійними числами IEEE 754, а 0.1 і 0.2 не мають точного двійкового представлення, тож їхня сума дорівнює `0.30000000000000004`. Порівнюйте дробові числа з допуском; `Number.EPSILON` (близько 2,2 × 10⁻¹⁶) підходить для значень близько 1. Гроші краще рахувати в цілих копійках."}'::jsonb, null::jsonb),
  ('vg-safe-integers', array['a']::text[], '{"en":"Doubles represent integers exactly only up to 2⁵³ − 1 (`Number.MAX_SAFE_INTEGER`); 2⁵³ + 1 rounds back to 2⁵³, so the comparison is `true`. `BigInt` (`n` suffix) has arbitrary precision. That''s why 64-bit IDs from APIs should be strings or BigInts, never plain numbers.","uk":"Подвійні числа точно представляють цілі лише до 2⁵³ − 1 (`Number.MAX_SAFE_INTEGER`); 2⁵³ + 1 округлюється назад до 2⁵³, тож порівняння дає `true`. `BigInt` (суфікс `n`) має довільну точність. Тому 64-бітні ID з API мають бути рядками чи BigInt, а не звичайними числами."}'::jsonb, null::jsonb),
  ('vg-asi-return', array['a']::text[], '{"en":"Automatic semicolon insertion puts a semicolon right after `return` when a line break follows it, so the function returns `undefined`. The next lines are then parsed as an unreachable block containing the label `debug:`. Keep the returned value (or its opening brace) on the same line as `return`.","uk":"Автоматична вставка крапки з комою ставить її одразу після `return`, коли за ним іде перенос рядка, тож функція повертає `undefined`. Наступні рядки тоді розбираються як недосяжний блок із міткою `debug:`. Тримайте значення, що повертається (чи його відкривну дужку), на одному рядку з `return`."}'::jsonb, null::jsonb),
  ('vg-wrapper-objects', array['a']::text[], '{"en":"With `new`, `Boolean`, `String` and `Number` create wrapper **objects**, and every object is truthy, even one wrapping `false`. They''re also a different type from the primitive, so `===` fails. Call these functions without `new` to convert values (`Boolean(x)`, `String(x)`), and let JavaScript box primitives automatically when you call methods.","uk":"З `new` функції `Boolean`, `String` і `Number` створюють **об''єкти**-обгортки, а кожен об''єкт істинний, навіть той, що загортає `false`. Ще й тип відрізняється від примітиву, тож `===` не спрацьовує. Викликайте ці функції без `new` для перетворення значень (`Boolean(x)`, `String(x)`), а примітиви JavaScript загорне сам, коли ви викликаєте методи."}'::jsonb, null::jsonb),
  ('vg-arrow-object-literal', array['a']::text[], '{"en":"After `=>`, a `{` starts a function body (a block), not an object literal. So `{ id: 1 }` is a block with a statement labelled `id:` and no `return`, giving `undefined`. Wrapping the literal in parentheses forces it to be parsed as an expression.","uk":"Після `=>` символ `{` починає тіло функції (блок), а не літерал об''єкта. Тож `{ id: 1 }` є блоком з інструкцією з міткою `id:` і без `return`, що дає `undefined`. Дужки навколо літерала змушують розібрати його як вираз."}'::jsonb, null::jsonb),
  ('vg-array-holes', array['a']::text[], '{"en":"Assigning index 10 makes `length` 11 and leaves holes. `indexOf`, `map` and `filter` skip holes (so `indexOf(undefined)` is -1 and only three values survive), and the `in` operator shows that index 1 doesn''t exist. `includes`, however, treats holes as `undefined`. Holes behave inconsistently, so avoid creating them.","uk":"Присвоєння індексу 10 робить `length` рівним 11 і лишає дірки. `indexOf`, `map` і `filter` пропускають дірки (тож `indexOf(undefined)` дає -1, а лишаються лише три значення), а оператор `in` показує, що індексу 1 не існує. Натомість `includes` вважає дірки `undefined`. Дірки поводяться непослідовно, тож краще їх не створювати."}'::jsonb, null::jsonb),
  ('vg-precedence', array['a']::text[], '{"en":"`&&` binds tighter than `||`, so the first is `true || (false && false)`. `+` is evaluated left to right: `1 + 2` is `3`, then `3 + \"3\"` concatenates to `\"33\"`, while `\"1\" + 2` is already a string, giving `\"123\"`. `2 ** -1` is 0.5. Add parentheses whenever precedence isn''t obvious.","uk":"`&&` зв''язує сильніше за `||`, тож перший вираз означає `true || (false && false)`. `+` обчислюється зліва направо: `1 + 2` дає `3`, потім `3 + \"3\"` з''єднується в `\"33\"`, а `\"1\" + 2` уже рядок, тож виходить `\"123\"`. `2 ** -1` дорівнює 0,5. Додавайте дужки щоразу, коли пріоритет неочевидний."}'::jsonb, null::jsonb),
  ('vg-rounding', array['a']::text[], '{"en":"1.005 is stored as 1.00499999999999989…, so rounding to two decimals gives `1.00`. 2.5 is exact and `toFixed` rounds it up to `3`. `Math.round` rounds .5 towards +∞, so `-2.5` becomes `-2`. Display rounding belongs in `Intl.NumberFormat`; calculations that must be exact belong in integers.","uk":"1.005 зберігається як 1.00499999999999989…, тож округлення до двох знаків дає `1.00`. 2.5 представлено точно, і `toFixed` округлює його вгору до `3`. `Math.round` округлює .5 у бік +∞, тож `-2.5` стає `-2`. Округлення для показу належить до `Intl.NumberFormat`; обчислення, що мають бути точними, роблять у цілих числах."}'::jsonb, null::jsonb),
  ('vg-negative-zero', array['a']::text[], '{"en":"`-0` is a real value in IEEE 754. `===`, `includes` and string conversion all treat it as `0`, but `Object.is` distinguishes it, and dividing by it gives `-Infinity`. It appears from things like `-1 * 0` or `Math.round(-0.4)`; if the sign matters (direction of motion), check it with `Object.is(x, -0)`.","uk":"`-0` є справжнім значенням в IEEE 754. `===`, `includes` і перетворення на рядок вважають його `0`, але `Object.is` його розрізняє, а ділення на нього дає `-Infinity`. Він виникає з виразів на кшталт `-1 * 0` чи `Math.round(-0.4)`; якщо знак важливий (напрямок руху), перевіряйте через `Object.is(x, -0)`."}'::jsonb, null::jsonb),
  ('vg-nullish-mixing', array['a']::text[], '{"en":"The language deliberately has no precedence between `??` and `||`/`&&`, because the intent is ambiguous, so the combination doesn''t parse at all and the whole file fails to load. Add parentheses to say what you mean, e.g. `(config.port || env.PORT) ?? 3000`.","uk":"Мова навмисно не має пріоритету між `??` і `||`/`&&`, бо намір неоднозначний, тож таке поєднання взагалі не розбирається, і весь файл не завантажується. Додайте дужки, щоб показати намір, наприклад `(config.port || env.PORT) ?? 3000`."}'::jsonb, null::jsonb),
  ('vg-labels-comma', array['a']::text[], '{"en":"The comma operator evaluates each operand and yields the last, so `x` is 3. `continue outer` skips the rest of the inner loop **and** moves to the next outer iteration, so for each `i` only `j = 1` is logged. When `i` is 3, `break outer` exits both loops before anything is logged.","uk":"Оператор кома обчислює кожен операнд і дає останній, тож `x` дорівнює 3. `continue outer` пропускає решту внутрішнього циклу **й** переходить до наступної ітерації зовнішнього, тож для кожного `i` виводиться лише `j = 1`. Коли `i` дорівнює 3, `break outer` виходить з обох циклів, перш ніж щось буде виведено."}'::jsonb, null::jsonb),
  ('vg-money', null::text[], '{"en":"Treating the amount as text and combining whole units and cents with integer arithmetic avoids binary rounding entirely; checking `Number.isSafeInteger` keeps every result exact. Allocation can''t round each share independently (three times 3333.33 rounds to 9999), so it floors every share and hands out the remaining cents by largest fractional part, which guarantees the parts sum to the total and stay as fair as possible.","uk":"Обробка суми як тексту й поєднання цілих одиниць і копійок цілочисельною арифметикою повністю уникає двійкового округлення; перевірка `Number.isSafeInteger` тримає кожен результат точним. Розподіл не може округлювати кожну частку окремо (тричі 3333,33 округлюється до 9999), тож він округлює кожну частку вниз і роздає залишкові копійки за найбільшою дробовою часткою, що гарантує точну суму частин і максимальну справедливість."}'::jsonb, '{"/src/money.ts":"const AMOUNT = /^(-)?(\\d+)(?:\\.(\\d{1,2}))?$/;\n\nexport function toCents(value: string): number {\n  // Parse the digits as text: never multiply a float by 100.\n  const m = AMOUNT.exec(value.trim());\n  if (!m) throw new RangeError(\"Invalid amount: \" + value);\n  const cents = Number(m[2]) * 100 + Number((m[3] ?? \"\").padEnd(2, \"0\"));\n  if (!Number.isSafeInteger(cents)) throw new RangeError(\"Amount too large: \" + value);\n  return m[1] && cents !== 0 ? -cents : cents; // no -0\n}\n\nexport function fromCents(cents: number): string {\n  if (!Number.isSafeInteger(cents)) throw new RangeError(\"cents must be a safe integer\");\n  const abs = Math.abs(cents);\n  return (cents < 0 ? \"-\" : \"\") + Math.floor(abs / 100) + \".\" + String(abs % 100).padStart(2, \"0\");\n}\n\nexport function allocate(totalCents: number, ratios: number[]): number[] {\n  const sum = ratios.reduce((a, b) => a + b, 0);\n  if (!Number.isSafeInteger(totalCents) || ratios.length === 0 || ratios.some((r) => !(r >= 0)) || !(sum > 0)) {\n    throw new RangeError(\"Invalid allocation\");\n  }\n  const exact = ratios.map((r) => (totalCents * r) / sum);\n  const parts = exact.map((x) => Math.floor(x));\n  let remainder = totalCents - parts.reduce((a, b) => a + b, 0);\n  // Largest-remainder method: hand out the leftover cents by biggest fractional part, earlier parts first on ties.\n  const order = exact\n    .map((x, i) => ({ i, fraction: x - Math.floor(x) }))\n    .sort((a, b) => b.fraction - a.fraction || a.i - b.i);\n  for (const { i } of order) {\n    if (remainder <= 0) break;\n    parts[i]++;\n    remainder--;\n  }\n  return parts;\n}\n"}'::jsonb),
  ('json-omitted-values', array['a']::text[], '{"en":"JSON has no `undefined`, functions or symbols, so properties holding them are **omitted** entirely; only `null` is a real JSON value. That''s why a field set to `undefined` disappears from a request body, while `null` is sent and can mean \"clear this field\" in a PATCH.","uk":"У JSON немає `undefined`, функцій чи символів, тож властивості з ними **пропускаються** повністю; лише `null` є справжнім значенням JSON. Тому поле зі значенням `undefined` зникає з тіла запиту, а `null` надсилається й може означати «очистити це поле» в PATCH."}'::jsonb, null::jsonb),
  ('json-array-null', array['a']::text[], '{"en":"Arrays can''t drop elements without shifting the indexes of everything after them, so `undefined`, functions and symbols become `null` there instead of disappearing. `NaN` and `±Infinity` aren''t valid JSON numbers, so they become `null` everywhere. Either way the original value is lost silently.","uk":"Масиви не можуть відкинути елементи, не зсунувши індекси всього, що після них, тож `undefined`, функції й символи там стають `null`, а не зникають. `NaN` і `±Infinity` не є коректними числами JSON, тож вони всюди стають `null`. Так чи інакше початкове значення мовчки втрачається."}'::jsonb, null::jsonb),
  ('json-top-level', array['a']::text[], '{"en":"With nothing serialisable at the top level, `JSON.stringify` returns `undefined` itself, not a string, so code like `JSON.stringify(x).length` or `res.send(JSON.stringify(x))` can blow up or send nothing. `NaN` becomes the string `\"null\"`. Type the return value as `string | undefined`.","uk":"Коли на верхньому рівні немає нічого, що можна серіалізувати, `JSON.stringify` повертає саме `undefined`, а не рядок, тож код на кшталт `JSON.stringify(x).length` чи `res.send(JSON.stringify(x))` може впасти чи нічого не надіслати. `NaN` стає рядком `\"null\"`. Типізуйте результат як `string | undefined`."}'::jsonb, null::jsonb),
  ('json-bigint', array['a']::text[], '{"en":"`JSON.stringify` throws a `TypeError` for BigInt values instead of guessing: writing it as a number would lose precision in other parsers, and as a string would change its type. Decide explicitly, usually by sending big ids as strings (with a replacer, or `BigInt.prototype.toJSON` if you control the whole app) and reviving them on the other side.","uk":"`JSON.stringify` кидає `TypeError` для значень BigInt, а не вгадує: запис числом втратив би точність в інших розбирачах, а рядком змінив би тип. Вирішуйте явно, зазвичай надсилаючи великі ідентифікатори рядками (через replacer чи `BigInt.prototype.toJSON`, якщо ви контролюєте весь застосунок) і відновлюючи їх на іншому боці."}'::jsonb, null::jsonb),
  ('json-tojson', array['a']::text[], '{"en":"If a value has a `toJSON` method, `JSON.stringify` serialises whatever it returns. `Date.prototype.toJSON` returns the ISO string, which is why dates become strings, and a custom `toJSON` can control a type''s wire format, for example to leave out a password. Note that after `JSON.parse`, `at` is just a string again.","uk":"Якщо значення має метод `toJSON`, `JSON.stringify` серіалізує те, що він повертає. `Date.prototype.toJSON` повертає рядок ISO, тому дати стають рядками, а власний `toJSON` може керувати форматом типу для передавання, наприклад, щоб пропустити пароль. Зверніть увагу: після `JSON.parse` `at` знову є просто рядком."}'::jsonb, null::jsonb),
  ('json-replacer-order', array['a']::text[], '{"en":"The replacer is first called for the **root**, with an empty key (`this` is a wrapper object `{ \"\": value }`), then for every property depth-first, top-down, before descending into it. That top-down order lets a replacer drop or replace a whole subtree before it''s visited. A reviver in `JSON.parse` goes the other way: children first, root last.","uk":"Replacer спершу викликається для **кореня** з порожнім ключем (`this` є обгорткою `{ \"\": value }`), а потім для кожної властивості в глибину, згори донизу, до заходу всередину неї. Такий порядок згори донизу дає replacer відкинути чи замінити ціле піддерево ще до його відвідування. Reviver у `JSON.parse` іде навпаки: спершу дочірні значення, корінь останнім."}'::jsonb, null::jsonb),
  ('json-replacer-array', array['a']::text[], '{"en":"An array replacer is a **whitelist of property names** applied at every level, not just the top. `meta` is kept because it''s listed, and inside it only `id` survives. Whitelisting is a safer way to log or return objects than blacklisting secrets, because new sensitive fields stay hidden by default.","uk":"Масив replacer є **білим списком назв властивостей**, що діє на кожному рівні, а не лише на верхньому. `meta` зберігається, бо його перелічено, а всередині нього виживає лише `id`. Білий список є безпечнішим способом журналювати чи повертати об''єкти, ніж чорний список секретів, бо нові чутливі поля за замовчуванням лишаються прихованими."}'::jsonb, null::jsonb),
  ('json-reviver-order', array['a']::text[], '{"en":"A reviver works **bottom-up**: it''s called for the deepest values first, then their parents, and finally for the root with key `\"\"`. That ordering means when the reviver sees an object, its children have already been revived, so you can rebuild containers like `Map` or class instances from already-restored contents.","uk":"Reviver працює **знизу вгору**: він викликається спершу для найглибших значень, потім для їхніх батьків і нарешті для кореня з ключем `\"\"`. Такий порядок означає, що коли reviver бачить об''єкт, його дочірні значення вже відновлено, тож можна відбудовувати контейнери на кшталт `Map` чи екземпляри класів із уже відновленого вмісту."}'::jsonb, null::jsonb),
  ('json-big-number', array['a']::text[], '{"en":"JSON numbers have no size limit, but `JSON.parse` turns them into JavaScript numbers (64-bit floats), and integers above `Number.MAX_SAFE_INTEGER` (2^53 − 1) can''t all be represented, so this id silently becomes its even neighbour. Database ids, Twitter/X ids and money in minor units hit this. Send such values as **strings**, or use a parser that supports BigInt.","uk":"Числа в JSON не мають обмеження розміру, але `JSON.parse` перетворює їх на числа JavaScript (64-бітні дробові), а цілі понад `Number.MAX_SAFE_INTEGER` (2^53 − 1) не всі можна представити, тож цей ідентифікатор мовчки стає своїм парним сусідом. Із цим стикаються ідентифікатори баз даних, ідентифікатори Twitter/X і гроші в дрібних одиницях. Надсилайте такі значення **рядками** або використовуйте розбирач із підтримкою BigInt."}'::jsonb, null::jsonb),
  ('json-prototype-pollution', array['a']::text[], '{"en":"`JSON.parse` creates an ordinary **own** property named `__proto__`, which is harmless on its own. The naive merge then does `target[\"__proto__\"]`, which reads the **prototype accessor** and returns `Object.prototype`, and recursing into it writes `isAdmin` there, so every object in the process now has `isAdmin: true`. Skip `__proto__`, `constructor` and `prototype` keys in merges, validate input against a schema, or merge into `Object.create(null)` or a `Map`.","uk":"`JSON.parse` створює звичайну **власну** властивість на ім''я `__proto__`, що сама по собі нешкідлива. Потім наївне злиття робить `target[\"__proto__\"]`, що читає **аксесор прототипу** й повертає `Object.prototype`, а рекурсія в нього записує туди `isAdmin`, тож тепер кожен об''єкт у процесі має `isAdmin: true`. Пропускайте ключі `__proto__`, `constructor` і `prototype` під час злиття, валідуйте вхідні дані за схемою або зливайте в `Object.create(null)` чи `Map`."}'::jsonb, null::jsonb),
  ('json-circular', array['a']::text[], '{"en":"JSON is a tree, so it can''t represent an object that contains itself; `JSON.stringify` detects the cycle and throws a `TypeError` (\"Converting circular structure to JSON\"). This often happens when logging objects like requests, DOM nodes or ORM entities. Serialise a plain projection of the data, or use a replacer with a `WeakSet` to replace repeated objects.","uk":"JSON є деревом, тож не може представити об''єкт, що містить сам себе; `JSON.stringify` виявляє цикл і кидає `TypeError` («Converting circular structure to JSON»). Це часто трапляється під час журналювання об''єктів на кшталт запитів, вузлів DOM чи сутностей ORM. Серіалізуйте просту проєкцію даних або використайте replacer з `WeakSet`, щоб замінювати повторні об''єкти."}'::jsonb, null::jsonb),
  ('json-typed-codec', null::text[], '{"en":"The replacer runs top-down with `this` bound to the containing object, so `this[key]` gives the value **before** `toJSON` (that''s the only way to see a `Date` as a `Date`). Replacing special values with tag objects lets `JSON.stringify` keep recursing into their contents, such as Map entries. The reviver runs bottom-up, so when it rebuilds a `Map`, `Set` or escaped object, everything inside has already been restored. Escaping user objects that contain the tag key avoids ambiguity, the same idea as escaping quotes inside a string.","uk":"Replacer працює згори донизу з `this`, прив''язаним до об''єкта-контейнера, тож `this[key]` дає значення **до** `toJSON` (це єдиний спосіб побачити `Date` як `Date`). Заміна особливих значень об''єктами-мітками дає `JSON.stringify` продовжувати рекурсію в їхній вміст, як-от записи Map. Reviver працює знизу вгору, тож коли він відбудовує `Map`, `Set` чи екранований об''єкт, усе всередині вже відновлено. Екранування об''єктів користувача, що містять ключ мітки, усуває неоднозначність, як і екранування лапок усередині рядка."}'::jsonb, '{"/src/codec.ts":"const TAG = \"$type\";\n\nconst tag = (type: string, value: unknown) => ({ [TAG]: type, value });\n\nexport function serialize(value: unknown, space?: number): string {\n  return JSON.stringify(\n    value,\n    function (this: any, key: string, current: unknown) {\n      // this[key] is the original value; current has already been through toJSON (Dates are strings by now).\n      const original = this[key];\n      if (original instanceof Date) return tag(\"Date\", Number.isNaN(original.getTime()) ? null : original.toISOString());\n      if (typeof original === \"bigint\") return tag(\"BigInt\", original.toString());\n      if (original instanceof Map) return tag(\"Map\", [...original]);\n      if (original instanceof Set) return tag(\"Set\", [...original]);\n      if (typeof original === \"number\" && (!Number.isFinite(original) || Object.is(original, -0))) {\n        return tag(\"Number\", Object.is(original, -0) ? \"-0\" : String(original));\n      }\n      // A user object that happens to have a \"$type\" key is escaped, so it can''t be mistaken for a tag.\n      if (current === original && original !== null && typeof original === \"object\" && !Array.isArray(original) && Object.prototype.hasOwnProperty.call(original, TAG)) {\n        return tag(\"Object\", Object.entries(original));\n      }\n      return current;\n    },\n    space,\n  );\n}\n\nexport function deserialize(text: string): unknown {\n  // The reviver runs bottom-up, so values inside Maps, Sets and escaped objects are already restored.\n  return JSON.parse(text, (_key, value) => {\n    if (value === null || typeof value !== \"object\" || Array.isArray(value) || typeof value[TAG] !== \"string\") return value;\n    switch (value[TAG]) {\n      case \"Date\":\n        return new Date(value.value === null ? NaN : value.value);\n      case \"BigInt\":\n        return BigInt(value.value);\n      case \"Map\":\n        return new Map(value.value);\n      case \"Set\":\n        return new Set(value.value);\n      case \"Number\":\n        return Number(value.value);\n      case \"Object\":\n        return Object.fromEntries(value.value);\n      default:\n        return value;\n    }\n  });\n}\n"}'::jsonb),
  ('json-safe-parse', null::text[], '{"en":"`JSON.parse` only proves the text is syntactically valid; the schema check proves it has the shape your code assumes. Walking the schema (not the data) to build the output is what makes it safe: only known keys are copied, so an attacker''s `__proto__` or `constructor` keys never reach a merge or an assignment, and `hasOwnProperty` stops inherited names like `toString` from counting as present. Collecting all errors with paths, instead of stopping at the first, gives clients something they can actually fix. This is exactly what libraries like Zod, Valibot and Ajv do at production scale.","uk":"`JSON.parse` лише доводить, що текст синтаксично коректний; перевірка схеми доводить, що він має форму, на яку розраховує ваш код. Безпечним це робить обхід схеми (а не даних) для побудови результату: копіюються лише відомі ключі, тож ключі зловмисника `__proto__` чи `constructor` ніколи не доходять до злиття чи присвоєння, а `hasOwnProperty` не дає успадкованим іменам на кшталт `toString` вважатися присутніми. Збирання всіх помилок зі шляхами, а не зупинка на першій, дає клієнтам те, що вони справді можуть виправити. Саме це роблять бібліотеки на кшталт Zod, Valibot і Ajv у масштабі продакшену."}'::jsonb, '{"/src/safe-parse.ts":"export type Schema =\n  | { type: \"string\"; minLength?: number; maxLength?: number; enum?: string[] }\n  | { type: \"number\"; integer?: boolean; min?: number; max?: number }\n  | { type: \"boolean\" }\n  | { type: \"array\"; items: Schema; maxItems?: number }\n  | { type: \"object\"; properties: Record<string, Schema>; required?: string[] };\n\nexport type Issue = { path: string; message: string };\nexport type Result = { ok: true; value: unknown } | { ok: false; errors: Issue[] };\n\nconst join = (path: string, key: string | number) =>\n  typeof key === \"number\" ? path + \"[\" + key + \"]\" : path ? path + \".\" + key : key;\n\nfunction check(data: any, schema: Schema, path: string, errors: Issue[]): unknown {\n  const fail = (message: string) => {\n    errors.push({ path, message });\n    return undefined;\n  };\n  switch (schema.type) {\n    case \"string\":\n      if (typeof data !== \"string\") return fail(\"Expected string\");\n      if (schema.minLength !== undefined && data.length < schema.minLength) return fail(\"Too short\");\n      if (schema.maxLength !== undefined && data.length > schema.maxLength) return fail(\"Too long\");\n      if (schema.enum && !schema.enum.includes(data)) return fail(\"Must be one of: \" + schema.enum.join(\", \"));\n      return data;\n    case \"number\":\n      if (typeof data !== \"number\" || !Number.isFinite(data)) return fail(\"Expected number\");\n      if (schema.integer && !Number.isInteger(data)) return fail(\"Expected integer\");\n      if (schema.min !== undefined && data < schema.min) return fail(\"Too small\");\n      if (schema.max !== undefined && data > schema.max) return fail(\"Too large\");\n      return data;\n    case \"boolean\":\n      return typeof data === \"boolean\" ? data : fail(\"Expected boolean\");\n    case \"array\":\n      if (!Array.isArray(data)) return fail(\"Expected array\");\n      if (schema.maxItems !== undefined && data.length > schema.maxItems) return fail(\"Too many items\");\n      return data.map((item, i) => check(item, schema.items, join(path, i), errors));\n    case \"object\": {\n      if (typeof data !== \"object\" || data === null || Array.isArray(data)) return fail(\"Expected object\");\n      // Build a fresh object from the schema''s keys only: unknown keys (including \"__proto__\") are dropped.\n      const out: Record<string, unknown> = {};\n      for (const [key, propSchema] of Object.entries(schema.properties)) {\n        if (Object.prototype.hasOwnProperty.call(data, key)) {\n          out[key] = check(data[key], propSchema, join(path, key), errors);\n        } else if (schema.required?.includes(key)) {\n          errors.push({ path: join(path, key), message: \"Required\" });\n        }\n      }\n      return out;\n    }\n  }\n}\n\nexport function safeParse(text: string, schema: Schema): Result {\n  let data: unknown;\n  try {\n    data = JSON.parse(text);\n  } catch {\n    return { ok: false, errors: [{ path: \"\", message: \"Invalid JSON\" }] };\n  }\n  const errors: Issue[] = [];\n  const value = check(data, schema, \"\", errors);\n  return errors.length > 0 ? { ok: false, errors } : { ok: true, value };\n}\n"}'::jsonb),
  ('jwt-decode-is-not-verify', array['a']::text[], '{"en":"A JWT is base64url-encoded, not encrypted, so the payload is readable by anyone. The signature is the only part that proves the issuer and that nothing was altered. Verify the signature first, and only then trust `exp`, `aud` and the other claims.","uk":"JWT закодований у base64url, а не зашифрований, тож payload може прочитати будь-хто. Лише підпис доводить, хто видав токен і що його ніхто не змінював. Спершу перевірте підпис, і лише потім довіряйте `exp`, `aud` та іншим claims."}'::jsonb, null::jsonb),
  ('jwt-claims-scope', array['a']::text[], '{"en":"A signature only proves who issued the token. `aud` says which service it''s meant for, and checking it stops a token from one service being replayed against another. `exp` limits how long a leaked token stays useful.","uk":"Підпис лише доводить, хто видав токен. `aud` вказує, для якого сервісу він призначений, і її перевірка не дає токену з одного сервісу бути використаним в іншому. `exp` обмежує, як довго витеклий токен залишається корисним."}'::jsonb, null::jsonb),
  ('jwt-claims-check', null::text[], '{"en":"Decoding and verifying are different jobs. `decodePayload` only undoes the encoding, and anyone can produce a token with any payload they like, so the claims are just data until the signature checks out (with `crypto.subtle.verify` and the issuer''s public key, in a real system). Once the signature is trusted, the claims decide whether this token applies here and now: `exp` and `nbf` bound its lifetime, with a small clock-skew allowance because servers'' clocks disagree, `iss` says who issued it, and `aud` says who it''s for. Rejecting a missing `exp` is the safe default, since a token without an expiry never stops working. Checking `aud` is what stops a token issued for one service from being replayed against another.","uk":"Декодування і перевірка — різні роботи. `decodePayload` лише скасовує кодування, і будь-хто може створити токен з будь-яким payload, тож claims є просто даними, доки підпис не перевірено (у реальній системі через `crypto.subtle.verify` і публічний ключ видавця). Коли підпису довірено, claims визначають, чи підходить цей токен тут і зараз: `exp` і `nbf` обмежують його строк, з невеликим допуском на розбіжність годинників серверів, `iss` каже, хто видав, а `aud` — для кого він. Відхилення токена без `exp` — безпечний вибір за замовчуванням, бо токен без терміну дії не перестає працювати. Перевірка `aud` не дає токену, виданому для одного сервісу, бути використаним в іншому."}'::jsonb, '{"/src/jwt.ts":"export type Claims = {\n  iss?: string;\n  sub?: string;\n  aud?: string | string[];\n  exp?: number;\n  nbf?: number;\n  iat?: number;\n  [key: string]: unknown;\n};\n\nexport function decodePayload(token: string): Claims {\n  const parts = token.split(\".\");\n  if (parts.length !== 3 || parts[1] === \"\") throw new Error(\"Malformed token\");\n  // base64url uses - and _ instead of + and /, and the padding is optional.\n  const base64 = parts[1].replace(/-/g, \"+\").replace(/_/g, \"/\").padEnd(Math.ceil(parts[1].length / 4) * 4, \"=\");\n  let json: string;\n  let payload: unknown;\n  try {\n    // atob gives one character per byte; turning the bytes into %XX escapes and decoding them reads UTF-8.\n    json = decodeURIComponent(Array.from(atob(base64), (c) => \"%\" + c.charCodeAt(0).toString(16).padStart(2, \"0\")).join(\"\"));\n    payload = JSON.parse(json);\n  } catch {\n    throw new Error(\"Malformed token\");\n  }\n  if (typeof payload !== \"object\" || payload === null || Array.isArray(payload)) throw new Error(\"Malformed token\");\n  return payload as Claims;\n}\n\nexport type CheckOptions = { now: number; issuer?: string; audience?: string; clockSkew?: number };\nexport type CheckResult = { valid: true; claims: Claims } | { valid: false; reason: string };\n\nexport function checkClaims(token: string, { now, issuer, audience, clockSkew = 30 }: CheckOptions): CheckResult {\n  let claims: Claims;\n  try {\n    claims = decodePayload(token);\n  } catch {\n    return { valid: false, reason: \"malformed\" };\n  }\n  if (claims.exp === undefined) return { valid: false, reason: \"missing exp\" };\n  if (now >= claims.exp + clockSkew) return { valid: false, reason: \"expired\" };\n  if (claims.nbf !== undefined && now + clockSkew < claims.nbf) return { valid: false, reason: \"not yet valid\" };\n  if (issuer !== undefined && claims.iss !== issuer) return { valid: false, reason: \"wrong issuer\" };\n  if (audience !== undefined) {\n    const audiences: unknown[] = Array.isArray(claims.aud) ? claims.aud : [claims.aud];\n    if (!audiences.includes(audience)) return { valid: false, reason: \"wrong audience\" };\n  }\n  return { valid: true, claims };\n}\n"}'::jsonb),
  ('log-structured-fields', array['a']::text[], '{"en":"A sentence like \"user ada failed to pay\" has to be parsed with regexes that break when someone rewords it. A structured entry keeps the event name and the values as separate fields, so a query like `user_id = 42 AND level = error` works on every service, and redaction can act on known field names.","uk":"Речення на кшталт \"user ada failed to pay\" доводиться розбирати регулярними виразами, які ламаються, коли його переформулюють. Структурований запис тримає назву події та значення окремими полями, тож запит на кшталт `user_id = 42 AND level = error` працює в кожному сервісі, а маскування може діяти за відомими назвами полів."}'::jsonb, null::jsonb),
  ('logging-redacting-logger', null::text[], '{"en":"Two things make this logger safe to use everywhere: every entry goes through one `clean` function, and that function builds a new object instead of editing the input. That''s where redaction and error serialisation live, so nothing bypasses them, including fields bound by `child`, which are merged before cleaning. Stack traces are left out on purpose: they''re useful for developers but can reveal file paths and internals, so they belong in error tracking, not in every log line. Levels are compared as positions in a list, which keeps the threshold check to one comparison. Production loggers add more (sampling, async writes), but the shape of the entry and the redaction rule stay the same.","uk":"Два речі роблять цей логер безпечним скрізь: кожен запис проходить через одну функцію `clean`, і вона будує новий об''єкт замість зміни вхідного. Саме тут живуть маскування і серіалізація помилок, тож нічого їх не обходить, зокрема поля, прив''язані через `child`, які зливаються до очищення. Стек викликів навмисно не записується: він корисний розробникам, але може розкрити шляхи до файлів і внутрішні деталі, тож місце йому в системі відстеження помилок, а не в кожному рядку журналу. Рівні порівнюються як позиції в списку, тож перевірка порога — одне порівняння. Логери у продакшені мають більше можливостей (вибірка, асинхронний запис), але форма запису і правило маскування лишаються тими самими."}'::jsonb, '{"/src/logger.ts":"export type Level = \"debug\" | \"info\" | \"warn\" | \"error\";\nexport type Entry = { level: Level; message: string; time: string; fields: Record<string, unknown> };\nexport type Sink = (entry: Entry) => void;\n\nexport type Logger = {\n  debug(message: string, fields?: Record<string, unknown>): void;\n  info(message: string, fields?: Record<string, unknown>): void;\n  warn(message: string, fields?: Record<string, unknown>): void;\n  error(message: string, fields?: Record<string, unknown>): void;\n  child(fields: Record<string, unknown>): Logger;\n};\n\nexport type LoggerOptions = {\n  level?: Level;\n  sink: Sink;\n  now?: () => string;\n  redactKeys?: string[];\n};\n\nconst ORDER: Level[] = [\"debug\", \"info\", \"warn\", \"error\"];\n\nexport function createLogger(options: LoggerOptions): Logger {\n  const threshold = ORDER.indexOf(options.level ?? \"info\");\n  const now = options.now ?? (() => new Date().toISOString());\n  const secret = new Set((options.redactKeys ?? []).map((key) => key.toLowerCase()));\n\n  // Copies the value, so the caller''s objects are never changed or leaked by reference.\n  const clean = (value: unknown): unknown => {\n    if (value instanceof Error) return { name: value.name, message: value.message }; // no stack traces in the output\n    if (Array.isArray(value)) return value.map(clean);\n    if (value !== null && typeof value === \"object\") {\n      const out: Record<string, unknown> = {};\n      for (const [key, inner] of Object.entries(value)) {\n        out[key] = secret.has(key.toLowerCase()) ? \"[REDACTED]\" : clean(inner);\n      }\n      return out;\n    }\n    return value;\n  };\n\n  const make = (bound: Record<string, unknown>): Logger => {\n    const write = (level: Level) => (message: string, fields: Record<string, unknown> = {}) => {\n      if (ORDER.indexOf(level) < threshold) return;\n      options.sink({\n        level,\n        message,\n        time: now(),\n        fields: clean({ ...bound, ...fields }) as Record<string, unknown>,\n      });\n    };\n    return {\n      debug: write(\"debug\"),\n      info: write(\"info\"),\n      warn: write(\"warn\"),\n      error: write(\"error\"),\n      child: (extra) => make({ ...bound, ...extra }),\n    };\n  };\n\n  return make({});\n}\n"}'::jsonb),
  ('sched-long-task', array['a']::text[], '{"en":"A task over 50 ms is a long task. The threshold comes from the RAIL model: to respond to input within about 100 ms, work has to be split into chunks of about 50 ms, so input waiting behind a chunk is still handled quickly. 16.7 ms is one frame at 60 Hz, and 200 ms is the \"good\" threshold for INP, which measures whole interactions.","uk":"Задача понад 50 мс є довгою. Поріг походить із моделі RAIL: щоб відповідати на введення приблизно за 100 мс, роботу треба ділити на частини близько 50 мс, тоді введення, що чекає за такою частиною, все одно обробляється швидко. 16,7 мс є одним кадром при 60 Гц, а 200 мс є порогом «доброго» INP, що вимірює взаємодії цілком."}'::jsonb, null::jsonb),
  ('sched-inp', array['a']::text[], '{"en":"INP observes interactions throughout the visit and reports roughly the worst one. Each interaction''s latency has three parts: **input delay** (waiting for whatever task is running), **processing** (your event handlers) and **presentation** (style, layout, paint). Long tasks inflate the first, heavy handlers the second, and large DOM updates the third. The other options describe LCP, CLS and TTFB.","uk":"INP спостерігає за взаємодіями протягом усього візиту й повідомляє приблизно найгіршу. Затримка кожної взаємодії має три частини: **затримка введення** (очікування задачі, що виконується), **обробка** (ваші обробники подій) і **показ** (стилі, розмітка, малювання). Довгі задачі збільшують першу, важкі обробники другу, а великі оновлення DOM третю. Інші варіанти описують LCP, CLS і TTFB."}'::jsonb, null::jsonb),
  ('sched-microtasks-dont-yield', array['a']::text[], '{"en":"`await Promise.resolve()` continues in a **microtask**, and microtasks run before the event loop picks the next task, so the timer (and, in a browser, input handling and rendering) can''t run until the whole loop finishes. Making a function `async` doesn''t make it cooperative. To really yield, wait for a new task: `scheduler.yield()`, `setTimeout`, or a `MessageChannel` message.","uk":"`await Promise.resolve()` продовжується в **мікрозадачі**, а мікрозадачі виконуються до того, як цикл подій візьме наступну задачу, тож таймер (а в браузері й обробка введення та рендер) не може виконатися, доки не завершиться весь цикл. Позначення функції як `async` не робить її кооперативною. Щоб справді поступитися потоком, чекайте на нову задачу: `scheduler.yield()`, `setTimeout` чи повідомлення `MessageChannel`."}'::jsonb, null::jsonb),
  ('sched-timeout-yields', array['a']::text[], '{"en":"Awaiting a `setTimeout` ends the current task, and the continuation is queued **behind** tasks that were already waiting, so the earlier timer runs after the first chunk. In a browser, pending input events and rendering get their turn at the same point. The downside is that the continuation waits behind everything else; `scheduler.yield()` lets the browser handle input but resumes your work ahead of other queued tasks.","uk":"Очікування `setTimeout` завершує поточну задачу, а продовження стає в чергу **за** задачами, що вже чекали, тож попередній таймер виконується після першої частини. У браузері в цей самий момент свою чергу отримують події введення, що очікують, і рендер. Недолік у тому, що продовження чекає за всім іншим; `scheduler.yield()` дає браузеру обробити введення, але продовжує вашу роботу перед іншими задачами в черзі."}'::jsonb, null::jsonb),
  ('sched-raf', array['a']::text[], '{"en":"`requestAnimationFrame` runs right before each paint, at the display''s refresh rate, and pauses in background tabs. A 16 ms interval drifts out of sync with frames (causing skipped or doubled frames) and keeps running in the background. Idle callbacks may not run at all on a busy page, and a microtask loop blocks rendering entirely. Better still, animate `transform` with CSS when you can.","uk":"`requestAnimationFrame` виконується безпосередньо перед кожним малюванням із частотою оновлення екрана й призупиняється у фонових вкладках. Інтервал 16 мс розсинхронізується з кадрами (кадри пропускаються чи дублюються) і продовжує працювати у фоні. Idle-колбеки на зайнятій сторінці можуть не виконатися взагалі, а цикл мікрозадач повністю блокує рендер. Ще краще анімувати `transform` через CSS, коли це можливо."}'::jsonb, null::jsonb),
  ('sched-idle-callback', array['a']::text[], '{"en":"Idle callbacks run when the browser has nothing more important to do, so they don''t delay interactions or frames. The `timeout` guarantees the callback runs eventually even on a page that''s never idle; without it, events could be delayed indefinitely. `requestAnimationFrame` is for visual work. Also flush pending events on `visibilitychange` (with `navigator.sendBeacon`), because idle callbacks may never fire before the user leaves.","uk":"Idle-колбеки виконуються, коли браузерові немає чого важливішого робити, тож не затримують взаємодії чи кадри. `timeout` гарантує, що колбек колись виконається навіть на сторінці, яка ніколи не простоює; без нього події могли б затримуватися безкінечно. `requestAnimationFrame` призначений для візуальної роботи. Також надсилайте події, що очікують, на `visibilitychange` (через `navigator.sendBeacon`), бо idle-колбеки можуть так і не спрацювати до того, як користувач піде."}'::jsonb, null::jsonb),
  ('sched-layout-thrashing', array['a']::text[], '{"en":"In the first loop, each write (`style.height`) invalidates layout, and the next read (`offsetWidth`) forces the browser to compute it again synchronously: N layouts instead of one. Reading everything first and then writing everything (the second option) needs at most one layout. Pure writes, like adding classes or setting transforms, are batched by the browser until the next frame.","uk":"У першому циклі кожен запис (`style.height`) робить розмітку недійсною, а наступне читання (`offsetWidth`) змушує браузер знову синхронно її обчислити: N перерахунків замість одного. Спершу прочитати все, а потім усе записати (другий варіант) потребує щонайбільше одного перерахунку. Самі лише записи, як-от додавання класів чи встановлення трансформацій, браузер групує до наступного кадру."}'::jsonb, null::jsonb),
  ('sched-time-budget', array['a']::text[], '{"en":"Responsiveness is about time, not item count: 1,000 cheap items might take 1 ms on a laptop, and 1,000 expensive ones 300 ms on a low-end phone. Checking the clock after each item (it''s cheap) and yielding once the budget is spent keeps every task short everywhere, while avoiding the overhead of yielding too often. Always process at least one item per chunk so the loop makes progress.","uk":"Чутливість залежить від часу, а не від кількості елементів: 1000 дешевих елементів можуть зайняти 1 мс на ноутбуці, а 1000 дорогих 300 мс на слабкому телефоні. Перевірка годинника після кожного елемента (вона дешева) і поступка потоком після вичерпання бюджету тримають кожну задачу короткою всюди, уникаючи накладних витрат від надто частих поступок. Завжди обробляйте щонайменше один елемент за частину, щоб цикл просувався."}'::jsonb, null::jsonb),
  ('sched-background-tabs', array['a']::text[], '{"en":"Browsers save battery by not rendering hidden tabs (so no animation frames) and by throttling timers, with intensive throttling after several minutes in some browsers. Don''t rely on timers for exact timing in the background; compute elapsed time from timestamps, and pause polling on `visibilitychange` or switch to push (WebSockets, SSE).","uk":"Браузери економлять батарею, не рендерячи приховані вкладки (тож кадрів анімації немає) і пригальмовуючи таймери, а в деяких браузерах через кілька хвилин вмикається інтенсивне пригальмовування. Не покладайтеся на таймери для точного відліку у фоні; обчислюйте минулий час за часовими позначками, а на `visibilitychange` призупиняйте опитування чи переходьте на push (WebSockets, SSE)."}'::jsonb, null::jsonb),
  ('sched-worker-or-chunk', array['a']::text[], '{"en":"Yielding only helps between steps you control; a single native call like `JSON.parse` is one indivisible 600 ms task wherever you schedule it. Move it off the main thread (a worker parses and posts back the result; transferring structured data has a cost, so post back only what the UI needs), use a streaming parser, or reduce the payload with pagination.","uk":"Поступка потоком допомагає лише між кроками, якими ви керуєте; один нативний виклик на кшталт `JSON.parse` є неподільною задачею на 600 мс, хоч би де ви її запланували. Перенесіть його з головного потоку (воркер розбирає й надсилає назад результат; передача структурованих даних має ціну, тож надсилайте лише те, що потрібно інтерфейсу), використайте потоковий розбір або зменште обсяг даних пагінацією."}'::jsonb, null::jsonb),
  ('sched-chunked-processing', null::text[], '{"en":"Driving the iterator manually lets the loop know whether more items remain, so it never yields after the last item. Checking the clock after each item gives time-based chunks that adapt to item cost and device speed, and guarantees progress even with a zero budget. Checking the signal right after each yield is the natural cancellation point: the user''s click to cancel is exactly the kind of input that the yield lets the browser process. Injecting `now` and `yieldToMain` makes the timing logic deterministic in tests.","uk":"Ручне керування ітератором дає циклу знати, чи лишилися елементи, тож він ніколи не поступається потоком після останнього елемента. Перевірка годинника після кожного елемента дає частини за часом, що підлаштовуються під вартість елементів і швидкість пристрою, і гарантує просування навіть з нульовим бюджетом. Перевірка сигналу одразу після кожної поступки є природною точкою скасування: натискання користувачем кнопки скасування є саме тим введенням, яке поступка дає браузеру обробити. Підміна `now` і `yieldToMain` робить логіку відліку часу детермінованою в тестах."}'::jsonb, '{"/src/chunks.ts":"export type ChunkOptions = {\n  budgetMs?: number;\n  now?: () => number;\n  yieldToMain?: () => Promise<void>;\n  signal?: AbortSignal;\n  onProgress?: (done: number) => void;\n};\n\nexport function defaultYield(): Promise<void> {\n  const scheduler = (globalThis as any).scheduler;\n  if (typeof scheduler?.yield === \"function\") return scheduler.yield();\n  return new Promise((resolve) => setTimeout(resolve, 0));\n}\n\nexport async function processInChunks<T, R>(\n  items: Iterable<T>,\n  fn: (item: T, index: number) => R,\n  { budgetMs = 8, now = () => performance.now(), yieldToMain = defaultYield, signal, onProgress }: ChunkOptions = {},\n): Promise<R[]> {\n  signal?.throwIfAborted();\n  const results: R[] = [];\n  const iterator = items[Symbol.iterator]();\n  let next = iterator.next();\n  let deadline = now() + budgetMs;\n  while (!next.done) {\n    results.push(fn(next.value, results.length));\n    next = iterator.next();\n    // Check the clock after each item (so every chunk makes progress), and only yield if work remains.\n    if (!next.done && now() >= deadline) {\n      onProgress?.(results.length);\n      await yieldToMain();\n      signal?.throwIfAborted();\n      deadline = now() + budgetMs;\n    }\n  }\n  onProgress?.(results.length);\n  return results;\n}\n"}'::jsonb),
  ('sched-frame-batcher', null::text[], '{"en":"Two queues and a `scheduled` flag are enough. Swapping in fresh queues at the start of a flush means jobs added during the flush land in the next frame, which prevents a read/write ping-pong inside one frame and guarantees the flush terminates. Running every read before any write lets the browser compute layout once per frame instead of once per element. Wrapping each job in `try/catch` and settling its own promise isolates failures, so one broken component can''t stop the others from updating.","uk":"Двох черг і прапорця `scheduled` достатньо. Заміна черг на нові на початку обробки кадру означає, що задачі, додані під час обробки, потрапляють у наступний кадр; це запобігає «пінг-понгу» читань і записів в одному кадрі й гарантує, що обробка завершиться. Виконання всіх читань перед будь-яким записом дає браузеру обчислювати розмітку раз на кадр, а не раз на елемент. Загортання кожної задачі в `try/catch` і завершення її власного промісу ізолює збої, тож один зламаний компонент не може завадити оновленню інших."}'::jsonb, '{"/src/batcher.ts":"type Entry = { job: () => unknown; resolve: (value: any) => void; reject: (reason: unknown) => void };\n\nexport function createFrameBatcher(requestFrame: (cb: () => void) => void = (cb) => requestAnimationFrame(() => cb())) {\n  let reads: Entry[] = [];\n  let writes: Entry[] = [];\n  let scheduled = false;\n\n  const run = (entries: Entry[]) => {\n    for (const { job, resolve, reject } of entries) {\n      try {\n        resolve(job());\n      } catch (error) {\n        reject(error); // one failing job doesn''t stop the others\n      }\n    }\n  };\n\n  const flush = () => {\n    scheduled = false;\n    // Take the current queues; anything queued while flushing waits for the next frame.\n    const currentReads = reads;\n    const currentWrites = writes;\n    reads = [];\n    writes = [];\n    run(currentReads); // all reads first: layout is computed at most once\n    run(currentWrites); // then all writes\n  };\n\n  const enqueue = <T>(queue: () => Entry[], job: () => T) =>\n    new Promise<T>((resolve, reject) => {\n      queue().push({ job, resolve, reject });\n      if (!scheduled) {\n        scheduled = true;\n        requestFrame(flush);\n      }\n    });\n\n  return {\n    measure: <T>(job: () => T) => enqueue(() => reads, job),\n    mutate: <T>(job: () => T) => enqueue(() => writes, job),\n  };\n}\n"}'::jsonb),
  ('mjs-default-null', array['a']::text[], '{"en":"A default applies only when the argument is `undefined`, whether it''s missing or passed explicitly. `null` and `\"\"` are real values, so they''re kept. If you want `null` to fall back too, use `name ?? \"guest\"` inside the function.","uk":"Значення за замовчуванням застосовується, лише коли аргумент `undefined`, чи то пропущений, чи переданий явно. `null` і `\"\"` є справжніми значеннями, тож вони зберігаються. Якщо треба, щоб і `null` давав запасне значення, використайте `name ?? \"guest\"` усередині функції."}'::jsonb, null::jsonb),
  ('mjs-destructure-defaults', array['a']::text[], '{"en":"Destructuring defaults follow the same rule as parameter defaults: they kick in only for `undefined`. `a` is `null` and `c` is `0`, both real values, so only `b` takes its default.","uk":"Значення за замовчуванням у деструктуризації підкоряються тому самому правилу, що й у параметрах: вони спрацьовують лише для `undefined`. `a` дорівнює `null`, а `c` дорівнює `0`, і обидва є справжніми значеннями, тож значення за замовчуванням отримує лише `b`."}'::jsonb, null::jsonb),
  ('mjs-nullish-vs-or', array['a']::text[], '{"en":"`||` falls back for every falsy value, so a deliberate volume of `0` or an empty title gets overwritten. `??` falls back only for `null` and `undefined`, which is almost always what you want for settings and optional values.","uk":"`||` бере запасне значення для будь-якого хибного значення, тож навмисна гучність `0` чи порожній заголовок перезаписуються. `??` бере запасне значення лише для `null` і `undefined`, і це майже завжди те, що потрібно для налаштувань і необов''язкових значень."}'::jsonb, null::jsonb),
  ('mjs-spread-shallow', array['a']::text[], '{"en":"Spread makes a **shallow** copy: `copy.n` is a separate property, but `copy.tags` points to the same array as `base.tags`, so pushing to it changes both. In immutable updates, copy every level you change: `{ ...base, tags: [...base.tags, \"b\"] }`, or use `structuredClone` for a full deep copy.","uk":"Spread робить **поверхневу** копію: `copy.n` є окремою властивістю, але `copy.tags` вказує на той самий масив, що й `base.tags`, тож додавання в нього змінює обидва. У незмінних оновленнях копіюйте кожен рівень, який змінюєте: `{ ...base, tags: [...base.tags, \"b\"] }`, або використайте `structuredClone` для повної глибокої копії."}'::jsonb, null::jsonb),
  ('mjs-spread-undefined-overrides', array['a']::text[], '{"en":"Spread copies every own enumerable property, including ones whose value is `undefined`, and later properties win. So an explicit `retries: undefined` (common when forwarding optional arguments) wipes out the default. Drop undefined keys first, or merge per key with `??`.","uk":"Spread копіює кожну власну перелічувану властивість, зокрема ті, чиє значення `undefined`, і пізніші властивості перемагають. Тож явне `retries: undefined` (часто трапляється під час передавання необов''язкових аргументів) стирає значення за замовчуванням. Спершу приберіть ключі зі значенням undefined або зливайте по ключах через `??`."}'::jsonb, null::jsonb),
  ('mjs-destructure-iterables', array['a']::text[], '{"en":"Array destructuring uses the iteration protocol, not indexes, so it works with Sets (which have already removed the duplicate `\"x\"`), strings, Maps and generators. A rest element always collects into a real array, even when the source is a string.","uk":"Деструктуризація масиву використовує протокол ітерації, а не індекси, тож працює з Set (який уже прибрав дублікат `\"x\"`), рядками, Map і генераторами. Rest-елемент завжди збирає в справжній масив, навіть коли джерелом є рядок."}'::jsonb, null::jsonb),
  ('mjs-default-per-call', array['a']::text[], '{"en":"JavaScript evaluates default expressions **on every call** that needs them, so each call gets a fresh array. (Python evaluates defaults once at definition time, which is why the same code there would print `[1] [1, 2]`, a well-known gotcha.)","uk":"JavaScript обчислює вирази значень за замовчуванням **під час кожного виклику**, що їх потребує, тож кожен виклик отримує новий масив. (Python обчислює значення за замовчуванням один раз під час визначення, тому той самий код там вивів би `[1] [1, 2]`, і це відома пастка.)"}'::jsonb, null::jsonb),
  ('mjs-function-length', array['a']::text[], '{"en":"A function''s `length` counts the parameters **before the first one with a default** or the rest parameter. A destructuring pattern counts as one parameter. Libraries that dispatch on `length` (currying helpers, Express error middleware with 4 parameters) break silently when someone adds a default.","uk":"`length` функції рахує параметри **до першого зі значенням за замовчуванням** чи rest-параметра. Шаблон деструктуризації рахується як один параметр. Бібліотеки, що розгалужуються за `length` (помічники каррінгу, middleware для помилок у Express із 4 параметрами), непомітно ламаються, коли хтось додає значення за замовчуванням."}'::jsonb, null::jsonb),
  ('mjs-optional-chaining-short-circuit', array['a']::text[], '{"en":"When `user` is nullish, `?.` skips the **whole rest of the chain**: `.profile.name.toUpperCase(...)` isn''t evaluated, so the argument `next()` never runs, and the result is `undefined` (not `null`). You only need `?.` at the points that can actually be nullish.","uk":"Коли `user` є nullish, `?.` пропускає **всю решту ланцюжка**: `.profile.name.toUpperCase(...)` не обчислюється, тож аргумент `next()` ніколи не виконується, а результатом є `undefined` (не `null`). `?.` потрібен лише там, де значення справді може бути nullish."}'::jsonb, null::jsonb),
  ('mjs-default-param-tdz', array['a']::text[], '{"en":"Parameters are initialised left to right, like `let` declarations in their own scope. `f(1)` never evaluates `a`''s default. `f()` evaluates `a = b` while `b` is still in its temporal dead zone, which throws a `ReferenceError`. Defaults may only refer to parameters declared **before** them.","uk":"Параметри ініціалізуються зліва направо, як оголошення `let` у власній області видимості. `f(1)` ніколи не обчислює значення за замовчуванням для `a`. `f()` обчислює `a = b`, коли `b` ще в тимчасовій мертвій зоні, і це кидає `ReferenceError`. Значення за замовчуванням можуть посилатися лише на параметри, оголошені **перед** ними."}'::jsonb, null::jsonb),
  ('mjs-tagged-template-raw', array['a']::text[], '{"en":"A tag receives the literal parts and the values separately. With two `${}` slots there are always **three** strings, so the last one is `\"\"`, and joining gives a trailing `|`. `strings.raw` keeps escapes as written, so `\\n` stays a backslash and an `n` instead of a newline (that''s how `String.raw` works).","uk":"Тег отримує літеральні частини й значення окремо. З двома слотами `${}` рядків завжди **три**, тож останній дорівнює `\"\"`, і з''єднання дає `|` у кінці. `strings.raw` зберігає екранування як написано, тож `\\n` лишається зворотною скісною рискою й `n`, а не переходом на новий рядок (саме так працює `String.raw`)."}'::jsonb, null::jsonb),
  ('mjs-logical-assignment', array['a']::text[], '{"en":"Logical assignment operators short-circuit **the assignment itself**. `??=` sees `\"x\"`, which isn''t nullish, and `||=` sees a truthy value, so neither calls the setter. `&&=` sees a truthy value and assigns `\"w\"`: one setter call. `o.v = o.v ?? \"y\"` would have called the setter every time, which matters for proxies, reactive state and expensive setters.","uk":"Оператори логічного присвоєння обривають **саме присвоєння**. `??=` бачить `\"x\"`, що не є nullish, а `||=` бачить істинне значення, тож жоден не викликає сетер. `&&=` бачить істинне значення й присвоює `\"w\"`: один виклик сетера. `o.v = o.v ?? \"y\"` викликав би сетер щоразу, а це важливо для проксі, реактивного стану й дорогих сетерів."}'::jsonb, null::jsonb),
  ('mjs-path-get-set', null::text[], '{"en":"Parsing the path once into keys (numbers for bracketed indexes) makes both functions simple loops or recursions. `getPath` stops as soon as it meets `null` or `undefined` and applies the fallback only for `undefined`, mirroring `??`-style defaults. `setPath` recurses to the leaf and, on the way back up, copies each container with spread (`[...arr]` or `{ ...obj }`), so only the changed path gets new references. Returning the original node when nothing changed below avoids needless re-renders.","uk":"Одноразовий розбір шляху на ключі (числа для індексів у дужках) робить обидві функції простими циклами чи рекурсіями. `getPath` зупиняється, щойно зустрічає `null` чи `undefined`, і застосовує запасне значення лише для `undefined`, як значення за замовчуванням у стилі `??`. `setPath` рекурсивно доходить до листка й на зворотному шляху копіює кожен контейнер через spread (`[...arr]` чи `{ ...obj }`), тож нові посилання отримує лише змінений шлях. Повернення початкового вузла, коли нижче нічого не змінилося, запобігає зайвим рендерам."}'::jsonb, '{"/src/path.ts":"export type Path = string | Array<string | number>;\n\ntype Key = string | number;\n\nfunction toKeys(path: Path): Key[] {\n  if (Array.isArray(path)) return path;\n  const keys: Key[] = [];\n  // \"a.b[0].c\" → [\"a\", \"b\", 0, \"c\"]: bracketed digits become numbers, everything else stays a string.\n  for (const [, name, index] of path.matchAll(/([^.[\\]]+)|\\[(\\d+)\\]/g)) {\n    keys.push(index !== undefined ? Number(index) : name!);\n  }\n  return keys;\n}\n\nexport function getPath(obj: unknown, path: Path, fallback?: unknown): unknown {\n  let current: any = obj;\n  for (const key of toKeys(path)) {\n    if (current === null || current === undefined) return fallback;\n    current = current[key];\n  }\n  return current === undefined ? fallback : current;\n}\n\nexport function setPath<T>(obj: T, path: Path, value: unknown): T {\n  const keys = toKeys(path);\n  const write = (node: any, i: number): any => {\n    if (i === keys.length) return value;\n    const key = keys[i];\n    const child = node?.[key];\n    const next = write(child ?? (typeof keys[i + 1] === \"number\" ? [] : {}), i + 1);\n    if (node != null && Object.is(child, next)) return node; // nothing changed below: keep the reference\n    const copy: any = Array.isArray(node) ? [...node] : node != null ? { ...node } : typeof key === \"number\" ? [] : {};\n    copy[key] = next;\n    return copy;\n  };\n  return write(obj, 0);\n}\n"}'::jsonb),
  ('mjs-sql-tag', null::text[], '{"en":"A tag function receives the literal parts and the interpolated values separately, which is exactly what parameterised SQL needs: the parts are trusted code written by the developer, the values are data. `toQuery` walks the parts and values in order with one shared `values` array, so placeholder numbers continue through nested fragments. Registering fragments in a `WeakSet` (instead of checking their shape) means attacker-controlled objects can never be inlined as SQL, and the `WeakSet` doesn''t keep old fragments alive.","uk":"Функція-тег отримує літеральні частини й підставлені значення окремо, а саме це й потрібно параметризованому SQL: частини є довіреним кодом розробника, а значення є даними. `toQuery` обходить частини й значення по черзі з одним спільним масивом `values`, тож номери заповнювачів продовжуються крізь вкладені фрагменти. Реєстрація фрагментів у `WeakSet` (замість перевірки їхньої форми) означає, що об''єкти під контролем зловмисника ніколи не вбудуються як SQL, а `WeakSet` не тримає старі фрагменти живими."}'::jsonb, '{"/src/sql.ts":"export type Query = { text: string; values: unknown[] };\n\ntype Fragment = { strings: readonly string[]; values: unknown[] };\n\n// Only objects created by the sql tag count as SQL; a look-alike object from user input is just a value.\nconst fragments = new WeakSet<object>();\n\nexport function sql(strings: TemplateStringsArray, ...values: unknown[]): Fragment {\n  const fragment = { strings, values };\n  fragments.add(fragment);\n  return fragment;\n}\n\nexport function toQuery(fragment: Fragment): Query {\n  const values: unknown[] = [];\n  const param = (value: unknown) => {\n    if (value === undefined) throw new TypeError(\"undefined can''t be sent as a SQL parameter\");\n    values.push(value);\n    return \"$\" + values.length;\n  };\n  const build = (f: Fragment): string => {\n    let text = f.strings[0];\n    f.values.forEach((value, i) => {\n      if (typeof value === \"object\" && value !== null && fragments.has(value)) {\n        text += build(value as Fragment);\n      } else if (Array.isArray(value)) {\n        if (value.length === 0) throw new RangeError(\"Can''t expand an empty list\");\n        text += value.map(param).join(\", \");\n      } else {\n        text += param(value);\n      }\n      text += f.strings[i + 1];\n    });\n    return text;\n  };\n  return { text: build(fragment), values };\n}\n"}'::jsonb),
  ('mod-iife-private', array['a']::text[], '{"en":"The IIFE runs once and returns an object whose method closes over `count`. The variable lives on in that closure (so the second call returns 2), but it''s not reachable from outside: `typeof count` sees no such name in this scope (and `typeof` doesn''t throw for undeclared names). That''s the whole module pattern: private state, public methods.","uk":"IIFE виконується один раз і повертає об''єкт, чий метод замикає `count`. Змінна продовжує жити в цьому замиканні (тож другий виклик повертає 2), але ззовні до неї не дістатися: `typeof count` не бачить такого імені в цій області (а `typeof` не кидає помилку для неоголошених імен). У цьому й полягає весь шаблон модуля: приватний стан, публічні методи."}'::jsonb, null::jsonb),
  ('mod-iife-forms', array['a', 'b', 'c']::text[], '{"en":"At the start of a statement, `function` begins a function **declaration**, which needs a name and can''t be called in place, so the last form is a `SyntaxError`. Anything that puts the parser in expression position works: wrapping parentheses (either placement) or a unary operator like `!` or `void`. Arrow functions need the parentheses: `(() => { … })()`.","uk":"На початку інструкції `function` починає **оголошення** функції, що потребує імені й не може бути викликане на місці, тож остання форма є `SyntaxError`. Працює все, що переводить розбирач у позицію виразу: дужки навколо (будь-яке розташування) чи унарний оператор на кшталт `!` або `void`. Стрілочні функції потребують дужок: `(() => { … })()`."}'::jsonb, null::jsonb),
  ('mod-singleton-vs-factory', array['a']::text[], '{"en":"The IIFE runs once, so `shared` is a single instance with one `n` (a singleton). `create` is the same pattern without the immediate call: every call creates a new scope with its own `n`, so `a` and `b` count independently. Choose a factory whenever you might need more than one instance, for example per user, per request, or per test.","uk":"IIFE виконується один раз, тож `shared` є єдиним екземпляром з одним `n` (синглтоном). `create` є тим самим шаблоном без негайного виклику: кожен виклик створює нову область видимості з власним `n`, тож `a` і `b` рахують незалежно. Обирайте фабрику завжди, коли може знадобитися більше одного екземпляра, наприклад для кожного користувача, запиту чи тесту."}'::jsonb, null::jsonb),
  ('mod-revealing-patch', array['a']::text[], '{"en":"The revealing module returns references to its private functions, but `add` calls the **private** `total` directly, not `cart.total`. Replacing the public property only changes what outside callers see. It''s a known drawback of the pattern when you try to stub methods in tests; inject dependencies instead, or call through the public object if overriding is intended.","uk":"Revealing module повертає посилання на свої приватні функції, але `add` викликає **приватну** `total` напряму, а не `cart.total`. Заміна публічної властивості змінює лише те, що бачать зовнішні виклики. Це відомий недолік шаблону, коли намагаєтеся підмінити методи в тестах; натомість впроваджуйте залежності або викликайте через публічний об''єкт, якщо перевизначення задумане."}'::jsonb, null::jsonb),
  ('mod-leaking-internals', array['a']::text[], '{"en":"`items` is private, but `all()` returns **the same array**, so any caller can mutate the module''s internal state and skip every check `add` might do. Encapsulation leaks through returned references. Return a copy (`[...items]`), a frozen copy, or an iterator.","uk":"`items` приватний, але `all()` повертає **той самий масив**, тож будь-хто може змінити внутрішній стан модуля й оминути всі перевірки, які могла б робити `add`. Інкапсуляція протікає через повернені посилання. Повертайте копію (`[...items]`), заморожену копію чи ітератор."}'::jsonb, null::jsonb),
  ('mod-weakmap-private', array['a']::text[], '{"en":"The data lives in a `WeakMap` keyed by the instance, so the object itself has **no own properties** at all: nothing for `Object.keys`, `JSON.stringify` or `Reflect.ownKeys` to find. Only code that can see `priv` (this module) can read it, and because the map holds keys weakly, discarded instances can still be garbage-collected. This was the standard privacy technique before `#private` fields.","uk":"Дані живуть у `WeakMap` з ключем-екземпляром, тож сам об''єкт узагалі **не має власних властивостей**: `Object.keys`, `JSON.stringify` і `Reflect.ownKeys` нічого не знаходять. Прочитати їх може лише код, що бачить `priv` (цей модуль), а оскільки мапа тримає ключі слабко, непотрібні екземпляри все одно можна прибрати збирачем сміття. Це була стандартна техніка приватності до появи полів `#private`."}'::jsonb, null::jsonb),
  ('mod-symbol-not-private', array['a']::text[], '{"en":"Symbol-keyed properties are hidden from `Object.keys`, `for…in` and JSON, but anyone can list them with `Object.getOwnPropertySymbols` (or `Reflect.ownKeys`) and read them. They prevent accidental clashes and casual access, not deliberate access. For real privacy use closures, `#private` fields or a module-scoped `WeakMap`.","uk":"Властивості з ключами-символами приховані від `Object.keys`, `for…in` і JSON, але будь-хто може перелічити їх через `Object.getOwnPropertySymbols` (чи `Reflect.ownKeys`) і прочитати. Вони запобігають випадковим конфліктам і побіжному доступу, а не навмисному. Для справжньої приватності використовуйте замикання, поля `#private` чи `WeakMap` в області видимості модуля."}'::jsonb, null::jsonb),
  ('mod-detached-methods', array['a']::text[], '{"en":"The factory''s method uses a closure variable, not `this`, so it keeps working when detached and passed around as a callback. The class method relies on `this`; called without a receiver (in strict class code) `this` is `undefined`, and reading `this.n` throws a `TypeError`. That''s one practical advantage of the module/factory pattern, at the cost of a method copy per instance.","uk":"Метод фабрики використовує змінну замикання, а не `this`, тож продовжує працювати, коли його від''єднують і передають як колбек. Метод класу покладається на `this`; без отримувача (у строгому коді класу) `this` дорівнює `undefined`, і читання `this.n` кидає `TypeError`. Це одна з практичних переваг шаблону модуля/фабрики, ціною копії методу для кожного екземпляра."}'::jsonb, null::jsonb),
  ('mod-esm-singleton-server', array['a']::text[], '{"en":"Module scope is a natural singleton: the module body runs once, and every importer shares the same bindings. That''s fine for configuration or caches of public data, but per-user state on a server leaks between requests (and is lost on restart or split across instances). Keep per-request state in a factory instance, the request context, or a database or session store.","uk":"Область видимості модуля є природним синглтоном: тіло модуля виконується один раз, і всі, хто імпортує, ділять ті самі зв''язування. Це прийнятно для конфігурації чи кешів публічних даних, але стан окремого користувача на сервері протікає між запитами (а ще губиться після перезапуску чи розділяється між екземплярами). Тримайте стан запиту в екземплярі фабрики, контексті запиту чи базі даних або сховищі сесій."}'::jsonb, null::jsonb),
  ('mod-cjs-wrapper', array['a']::text[], '{"en":"Node''s CommonJS loader wraps each file in a function, so top-level declarations are local to that function''s scope, and the module''s tools arrive as parameters. The wrapper runs once and the result (`module.exports`) is cached, which is why modules behave like singletons and why `this` at the top level of a CommonJS file is `module.exports`. ES modules get the same isolation natively from the language.","uk":"Завантажувач CommonJS у Node загортає кожен файл у функцію, тож оголошення верхнього рівня локальні для області видимості цієї функції, а інструменти модуля приходять параметрами. Обгортка виконується один раз, а результат (`module.exports`) кешується, тому модулі поводяться як синглтони, а `this` на верхньому рівні файлу CommonJS дорівнює `module.exports`. ES-модулі отримують ту саму ізоляцію нативно від мови."}'::jsonb, null::jsonb),
  ('mod-session-manager', null::text[], '{"en":"The `Map` lives only in the factory''s scope, so the returned methods are the sole way to reach it, and each call to the factory creates an independent store. Encapsulation also has to hold at the **edges**: returning stored objects or arrays would hand out mutable references, so every result is a frozen copy, and the API object itself is frozen so methods can''t be swapped. Injecting `now` and `generateId` keeps the module deterministic in tests without exposing any internals.","uk":"`Map` живе лише в області видимості фабрики, тож повернені методи є єдиним способом до неї дістатися, а кожен виклик фабрики створює незалежне сховище. Інкапсуляція також має триматися на **межах**: повернення збережених об''єктів чи масивів видало б змінні посилання, тож кожен результат є замороженою копією, а сам об''єкт API заморожений, щоб методи не можна було підмінити. Підміна `now` і `generateId` тримає модуль детермінованим у тестах, не відкриваючи внутрішніх деталей."}'::jsonb, '{"/src/sessions.ts":"export type Session = Readonly<{ id: string; userId: string; createdAt: number; expiresAt: number }>;\n\nexport type SessionOptions = { ttlMs?: number; now?: () => number; generateId?: () => string };\n\ntype Stored = { id: string; userId: string; createdAt: number; expiresAt: number };\n\nexport function createSessionManager({ ttlMs = 30 * 60_000, now = () => Date.now(), generateId = () => crypto.randomUUID() }: SessionOptions = {}) {\n  // Private: only the closures below can reach it.\n  const sessions = new Map<string, Stored>();\n\n  // Callers get frozen copies, never the stored objects.\n  const snapshot = (s: Stored): Session => Object.freeze({ ...s });\n  const alive = (s: Stored) => s.expiresAt > now();\n  const purge = () => {\n    for (const [id, s] of sessions) if (!alive(s)) sessions.delete(id);\n  };\n\n  return Object.freeze({\n    create(userId: string): Session {\n      if (typeof userId !== \"string\" || userId === \"\") throw new TypeError(\"userId is required\");\n      const t = now();\n      const session: Stored = { id: generateId(), userId, createdAt: t, expiresAt: t + ttlMs };\n      sessions.set(session.id, session);\n      return snapshot(session);\n    },\n    get(id: string): Session | undefined {\n      const s = sessions.get(id);\n      if (!s) return undefined;\n      if (!alive(s)) {\n        sessions.delete(id);\n        return undefined;\n      }\n      return snapshot(s);\n    },\n    touch(id: string): boolean {\n      const s = sessions.get(id);\n      if (!s || !alive(s)) {\n        sessions.delete(id);\n        return false;\n      }\n      s.expiresAt = now() + ttlMs;\n      return true;\n    },\n    revoke(id: string): boolean {\n      return sessions.delete(id);\n    },\n    revokeAll(userId: string): number {\n      let count = 0;\n      for (const [id, s] of sessions) {\n        if (s.userId === userId) {\n          sessions.delete(id);\n          count++;\n        }\n      }\n      return count;\n    },\n    activeCount(): number {\n      purge();\n      return sessions.size;\n    },\n    sessionsFor(userId: string): Session[] {\n      purge();\n      return [...sessions.values()].filter((s) => s.userId === userId).map(snapshot);\n    },\n  });\n}\n"}'::jsonb),
  ('mod-private-account', null::text[], '{"en":"Each technique stores the balance somewhere only trusted code can reach: a factory''s scope, a class''s private slot, or a module-scoped `WeakMap`. The interesting part is `transfer`, which needs to recognise genuine accounts: duck typing would accept any object with a `deposit` method. The closure version brands accounts in a `WeakSet`, the class can read `#balance` on **any** instance of the same class (privacy is per class, not per object) and uses a failed private-field read as a brand check, and the `WeakMap` version checks `balances.has(to)`. Withdrawing first makes transfers atomic, since it''s the only step that can fail.","uk":"Кожна техніка зберігає баланс там, куди може дістатися лише довірений код: в області видимості фабрики, в приватному слоті класу чи у `WeakMap` в області видимості модуля. Найцікавіша частина є `transfer`, якому треба розпізнавати справжні рахунки: «качина типізація» прийняла б будь-який об''єкт із методом `deposit`. Версія на замиканнях позначає рахунки у `WeakSet`, клас може читати `#balance` у **будь-якому** екземплярі того самого класу (приватність діє на рівні класу, а не об''єкта) і використовує невдале читання приватного поля як перевірку бренду, а версія з `WeakMap` перевіряє `balances.has(to)`. Зняття першим робить перекази атомарними, бо це єдиний крок, що може не вдатися."}'::jsonb, '{"/src/accounts.ts":"export interface Account {\n  deposit(amount: number): number;\n  withdraw(amount: number): number;\n  getBalance(): number;\n  transfer(to: Account, amount: number): void;\n}\n\nfunction checkAmount(amount: number) {\n  if (typeof amount !== \"number\" || !Number.isFinite(amount) || amount <= 0) throw new RangeError(\"Amount must be a positive number\");\n}\nfunction checkInitial(initial: number) {\n  if (typeof initial !== \"number\" || !Number.isFinite(initial) || initial < 0) throw new RangeError(\"Initial balance can''t be negative\");\n}\n\n// 1. Closures: the balance lives in the factory''s scope. A module-level WeakSet brands real accounts.\nconst closureAccounts = new WeakSet<object>();\n\nexport function createClosureAccount(initial = 0): Account {\n  checkInitial(initial);\n  let balance = initial;\n  const account: Account = Object.freeze({\n    deposit(amount: number) {\n      checkAmount(amount);\n      return (balance += amount);\n    },\n    withdraw(amount: number) {\n      checkAmount(amount);\n      if (amount > balance) throw new RangeError(\"Insufficient funds\");\n      return (balance -= amount);\n    },\n    getBalance: () => balance,\n    transfer(to: Account, amount: number) {\n      if (!closureAccounts.has(to)) throw new TypeError(\"Can only transfer to another closure account\");\n      account.withdraw(amount); // throws before anything changes\n      to.deposit(amount);\n    },\n  });\n  closureAccounts.add(account);\n  return account;\n}\n\n// 2. #private fields: class code can read #balance on any instance of the same class.\nexport class PrivateFieldAccount implements Account {\n  #balance: number;\n  constructor(initial = 0) {\n    checkInitial(initial);\n    this.#balance = initial;\n  }\n  deposit(amount: number) {\n    checkAmount(amount);\n    return (this.#balance += amount);\n  }\n  withdraw(amount: number) {\n    checkAmount(amount);\n    if (amount > this.#balance) throw new RangeError(\"Insufficient funds\");\n    return (this.#balance -= amount);\n  }\n  getBalance() {\n    return this.#balance;\n  }\n  transfer(to: Account, amount: number) {\n    if (!(to instanceof PrivateFieldAccount) || !PrivateFieldAccount.#isReal(to)) {\n      throw new TypeError(\"Can only transfer to another PrivateFieldAccount\");\n    }\n    this.withdraw(amount);\n    to.#balance += amount;\n  }\n  static #isReal(value: object) {\n    try {\n      (value as PrivateFieldAccount).#balance; // brand check: throws if the field isn''t there\n      return true;\n    } catch {\n      return false;\n    }\n  }\n}\n\n// 3. A WeakMap keyed by instance, visible only inside this module.\nconst balances = new WeakMap<object, number>();\n\nexport class WeakMapAccount implements Account {\n  constructor(initial = 0) {\n    checkInitial(initial);\n    balances.set(this, initial);\n  }\n  deposit(amount: number) {\n    checkAmount(amount);\n    const next = balances.get(this)! + amount;\n    balances.set(this, next);\n    return next;\n  }\n  withdraw(amount: number) {\n    checkAmount(amount);\n    const current = balances.get(this)!;\n    if (amount > current) throw new RangeError(\"Insufficient funds\");\n    balances.set(this, current - amount);\n    return current - amount;\n  }\n  getBalance() {\n    return balances.get(this)!;\n  }\n  transfer(to: Account, amount: number) {\n    if (!balances.has(to)) throw new TypeError(\"Can only transfer to another WeakMapAccount\");\n    this.withdraw(amount);\n    balances.set(to, balances.get(to)! + amount);\n  }\n}\n"}'::jsonb),
  ('mon-percentiles-vs-average', array['a']::text[], '{"en":"Latency distributions are long-tailed: most requests are fast, and a few very slow ones barely move the mean. Percentiles describe the tail directly, which is where users notice problems and where timeouts and queues hurt. Histograms with fixed buckets, as in this task, let you compute percentiles across many servers without storing every sample.","uk":"Розподіли затримок мають довгий хвіст: більшість запитів швидкі, а кілька дуже повільних майже не рухають середнє. Перцентилі описують хвіст безпосередньо, саме там користувачі помічають проблеми і там шкодять тайм-аути та черги. Гістограми з фіксованими коробками, як у цій задачі, дають рахувати перцентилі на багатьох серверах без зберігання кожного виміру."}'::jsonb, null::jsonb),
  ('mon-latency-histogram', null::text[], '{"en":"A histogram trades precision for constant memory: a few counters regardless of traffic, and the percentile is only known to the resolution of the buckets. The percentile is the bound of the first cumulative bucket that reaches the rank, so it''s an upper estimate (\"at most 10 ms\"), which is the conservative direction for alerting. Because bucket counts simply add up, histograms from many servers merge into one by summing counters, which averages and percentiles of raw samples cannot do. Choose bounds around your SLO: a bucket edge exactly at the target tells you whether you meet it.","uk":"Гістограма обмінює точність на сталу пам''ять: кілька лічильників незалежно від трафіку, а перцентиль відомий лише з точністю до коробок. Перцентиль — це межа першої накопичувальної коробки, яка досягає рангу, тож це верхня оцінка («не більше 10 мс»), а для сповіщень це консервативний напрямок. Оскільки підрахунки коробок просто додаються, гістограми з багатьох серверів зливаються в одну простим сумуванням лічильників, чого не можна зробити з середніми чи перцентилями сирих вимірів. Вибирайте межі навколо свого SLO: межа коробки саме на цільовому значенні показує, чи ви його дотримуєтесь."}'::jsonb, '{"/src/histogram.ts":"export function createHistogram(bounds: number[]) {\n  if (bounds.length === 0 || bounds.some((b, i) => i > 0 && b <= bounds[i - 1])) {\n    throw new RangeError(\"Bucket bounds must be strictly ascending\");\n  }\n  // One counter per bound, plus the overflow bucket for values above the last bound.\n  const counts: number[] = new Array(bounds.length + 1).fill(0);\n  let count = 0;\n  let sum = 0;\n\n  const histogram = {\n    observe(value: number): void {\n      count++;\n      sum += value;\n      const index = bounds.findIndex((bound) => value <= bound); // inclusive upper bound\n      counts[index === -1 ? bounds.length : index]++;\n    },\n    get count(): number {\n      return count;\n    },\n    mean(): number {\n      return count === 0 ? NaN : sum / count;\n    },\n    buckets(): Array<{ le: number; count: number }> {\n      let running = 0;\n      return [...bounds, Infinity].map((le, i) => {\n        running += counts[i];\n        return { le, count: running };\n      });\n    },\n    percentile(p: number): number {\n      if (count === 0) return NaN;\n      const rank = Math.max(1, Math.ceil(p * count));\n      const found = histogram.buckets().find((bucket) => bucket.count >= rank);\n      return found ? found.le : Infinity;\n    },\n  };\n  return histogram;\n}\n"}'::jsonb),
  ('net-http-request-parser', null::text[], '{"en":"HTTP/1.x is a text protocol on top of TCP, which delivers a byte stream with no message boundaries. The blank line that ends the head and the `Content-Length` header are how the receiver finds where the request stops, and it must not run into the next request on the same connection (keep-alive). The parser is strict on purpose: a request-smuggling attack depends on two servers disagreeing about where a body ends, so rejecting malformed lengths and truncated bodies is a security decision, not just validation. Header names are case-insensitive by specification, and repeated headers are combined rather than overwritten, so a value like `Accept` isn''t lost. The `hasOwnProperty` check keeps a header named `constructor` from reading the prototype.","uk":"HTTP/1.x — це текстовий протокол поверх TCP, який доставляє потік байтів без меж повідомлень. Порожній рядок, що завершує заголовки, і заголовок `Content-Length` — це те, як отримувач знаходить, де закінчується запит, і він не повинен заходити в наступний запит на тому самому з''єднанні (keep-alive). Розбирач навмисно суворий: атака з контрабандою запитів залежить від того, що два сервери по-різному розуміють, де закінчується тіло, тож відхилення некоректних довжин і обрізаних тіл — це рішення безпеки, а не лише перевірка. Назви заголовків за специфікацією не чутливі до регістру, а повторювані заголовки об''єднуються, а не перезаписуються, тож значення на кшталт `Accept` не губиться. Перевірка `hasOwnProperty` не дає заголовку з назвою `constructor` читати прототип."}'::jsonb, '{"/src/http.ts":"export type ParsedRequest = {\n  method: string;\n  path: string;\n  query: Record<string, string>;\n  headers: Record<string, string>;\n  body: string;\n};\n\n/** Query strings use + for spaces and percent-encoding for everything else. */\nconst decode = (text: string) => decodeURIComponent(text.replace(/\\+/g, \" \"));\n\nexport function parseRequest(raw: string): ParsedRequest {\n  const headEnd = raw.indexOf(\"\\r\\n\\r\\n\");\n  if (headEnd === -1) throw new Error(\"Incomplete request head\");\n\n  const [requestLine, ...headerLines] = raw.slice(0, headEnd).split(\"\\r\\n\");\n  const match = /^([A-Z]+) (\\S+) (HTTP\\/\\d\\.\\d)$/.exec(requestLine);\n  if (match === null) throw new Error(\"Bad request line\");\n  const [, method, target, version] = match;\n  if (version !== \"HTTP/1.1\" && version !== \"HTTP/1.0\") throw new Error(\"Unsupported HTTP version\");\n\n  const question = target.indexOf(\"?\");\n  const path = question === -1 ? target : target.slice(0, question);\n  const query: Record<string, string> = {};\n  if (question !== -1) {\n    for (const pair of target.slice(question + 1).split(\"&\")) {\n      if (pair === \"\") continue;\n      const equals = pair.indexOf(\"=\");\n      const key = decode(equals === -1 ? pair : pair.slice(0, equals));\n      query[key] = equals === -1 ? \"\" : decode(pair.slice(equals + 1));\n    }\n  }\n\n  const headers: Record<string, string> = {};\n  for (const line of headerLines) {\n    const colon = line.indexOf(\":\");\n    if (colon <= 0) throw new Error(\"Bad header: \" + line);\n    const name = line.slice(0, colon).toLowerCase(); // header names are case-insensitive\n    const value = line.slice(colon + 1).trim();\n    // Repeated headers are combined with a comma, as RFC 9110 describes.\n    headers[name] = Object.prototype.hasOwnProperty.call(headers, name) ? headers[name] + \", \" + value : value;\n  }\n\n  const rest = raw.slice(headEnd + 4);\n  const declared = headers[\"content-length\"];\n  if (declared === undefined) return { method, path, query, headers, body: \"\" };\n  if (!/^\\d+$/.test(declared)) throw new Error(\"Bad content-length\");\n  const length = Number(declared);\n  if (rest.length < length) throw new Error(\"Truncated body\");\n  // Bytes after the declared length belong to the next request on the connection.\n  return { method, path, query, headers, body: rest.slice(0, length) };\n}\n"}'::jsonb),
  ('next-page-file', array['a']::text[], '{"en":"Folders define URL segments and `page.tsx` makes a segment publicly routable. `layout.tsx`, `loading.tsx` and `error.tsx` in the same folder wrap it. `route.ts` would define an API endpoint for that URL instead of a page; `index.tsx` and `dashboard.tsx` are Pages Router conventions.","uk":"Папки задають сегменти URL, а `page.tsx` робить сегмент публічно доступним. `layout.tsx`, `loading.tsx` і `error.tsx` у тій самій папці його обгортають. `route.ts` натомість визначив би API-ендпоінт для цього URL; `index.tsx` і `dashboard.tsx` є домовленостями Pages Router."}'::jsonb, null::jsonb),
  ('next-use-client', array['a']::text[], '{"en":"Components in `app/` are Server Components by default and can''t hold state or handle events. `\"use client\"` at the top of a module makes it, and everything it imports, part of the client bundle. Put it on the small interactive component, not on a layout, or you''d ship the whole tree as client JavaScript.","uk":"Компоненти в `app/` за замовчуванням серверні й не можуть мати стан чи обробляти події. `\"use client\"` на початку модуля робить його та все, що він імпортує, частиною клієнтського бандла. Ставте директиву на невеликий інтерактивний компонент, а не на макет, інакше все дерево піде в браузер як клієнтський JavaScript."}'::jsonb, null::jsonb),
  ('next-async-params', array['a']::text[], '{"en":"`params` (and `searchParams`) are Promises in current Next.js, so a page awaits them. Synchronous access was deprecated in v15. `useParams` is a client hook, and `window` doesn''t exist in Server Components.","uk":"`params` (і `searchParams`) у поточному Next.js є промісами, тож сторінка на них чекає через `await`. Синхронний доступ застарів у v15. `useParams` є клієнтським хуком, а `window` у серверних компонентах не існує."}'::jsonb, null::jsonb),
  ('next-env-secret', array['a']::text[], '{"en":"At build time Next.js replaces `process.env.NEXT_PUBLIC_*` in client code with the values and replaces other variables with empty strings, so secrets never leak into the bundle. Adding the prefix would publish the secret key to every visitor. Call Stripe from server code and mark such modules with `import \"server-only\"`.","uk":"Під час збірки Next.js замінює `process.env.NEXT_PUBLIC_*` у клієнтському коді значеннями, а інші змінні порожніми рядками, тож секрети ніколи не потрапляють у бандл. Префікс опублікував би секретний ключ для кожного відвідувача. Викликайте Stripe із серверного коду й позначайте такі модулі через `import \"server-only\"`."}'::jsonb, null::jsonb),
  ('next-loading-streaming', array['a']::text[], '{"en":"`loading.tsx` is shorthand for wrapping the segment''s page in `<Suspense fallback={<Loading />}>`. The server sends the shell first and streams the rest over the same response, so users see something useful immediately and navigation stays responsive. Finer-grained `<Suspense>` boundaries let independent parts stream separately.","uk":"`loading.tsx` є скороченням для обгортання сторінки сегмента в `<Suspense fallback={<Loading />}>`. Сервер спершу надсилає каркас, а решту передає потоком у тій самій відповіді, тож користувачі одразу бачать щось корисне, а навігація лишається чуйною. Дрібніші межі `<Suspense>` дають незалежним частинам надходити окремо."}'::jsonb, null::jsonb),
  ('next-server-action-auth', array['a']::text[], '{"en":"Anyone who can load a page that references the action can call it with any arguments, so hiding UI is not access control. Treat every action like an API route: authenticate, authorise (ownership or role), validate input with a schema, and only then mutate. Checks in `proxy.ts` or layouts don''t run for every action call.","uk":"Будь-хто, хто може завантажити сторінку, що посилається на дію, може викликати її з будь-якими аргументами, тож приховування UI не є контролем доступу. Ставтеся до кожної дії як до API-маршруту: автентифікуйте, авторизуйте (власність чи роль), валідуйте дані схемою і лише потім змінюйте дані. Перевірки в `proxy.ts` чи макетах не виконуються для кожного виклику дії."}'::jsonb, null::jsonb),
  ('next-revalidate-after-write', array['a']::text[], '{"en":"On-demand revalidation invalidates exactly what the mutation affected: `revalidatePath` for a route, `revalidateTag` or `updateTag` for data you tagged when caching it (`updateTag` gives read-your-own-writes inside actions). `router.refresh()` is a client API, and disabling caching everywhere throws away the benefits of static rendering.","uk":"Ревалідація на вимогу інвалідує саме те, на що вплинула зміна: `revalidatePath` для маршруту, `revalidateTag` чи `updateTag` для даних, яким ви дали тег під час кешування (`updateTag` дає змогу одразу бачити власні зміни в діях). `router.refresh()` є клієнтським API, а вимкнення кешу всюди позбавляє переваг статичного рендерингу."}'::jsonb, null::jsonb),
  ('next-boundary-props', array['a', 'c', 'd']::text[], '{"en":"Props sent from server to client are serialised into the RSC payload. Plain data, JSX (already rendered on the server) and Server Actions (sent as references the client can call) work. Ordinary functions and class instances like `Intl.NumberFormat` can''t be serialised: define the handler or create the formatter inside the Client Component instead.","uk":"Пропси, що передаються з сервера на клієнт, серіалізуються в RSC payload. Звичайні дані, JSX (уже відрендерений на сервері) і Server Actions (передаються як посилання, які клієнт може викликати) працюють. Звичайні функції й екземпляри класів на кшталт `Intl.NumberFormat` серіалізувати не можна: оголосіть обробник або створіть форматер усередині клієнтського компонента."}'::jsonb, null::jsonb),
  ('next-route-matcher', null::text[], '{"en":"Parsing each pattern into typed segments separates the rules from the matching. Sorting candidates by a per-segment rank makes `/blog/new` win over `/blog/[slug]` no matter how the list is ordered, which is how Next.js resolves conflicts. Catch-alls consume the remaining parts (requiring at least one unless optional), groups are dropped before matching, and the pathname is normalised and decoded once up front.","uk":"Розбір кожного шаблону на типізовані сегменти відокремлює правила від зіставлення. Сортування кандидатів за рангом кожного сегмента робить так, що `/blog/new` переважає `/blog/[slug]` незалежно від порядку списку; так Next.js і розв''язує конфлікти. Catch-all забирає решту частин (вимагаючи щонайменше одну, якщо він не необов''язковий), групи відкидаються до зіставлення, а шлях нормалізується й декодується один раз на початку."}'::jsonb, '{"/src/router.ts":"export type Params = Record<string, string | string[]>;\nexport type Match = { route: string; params: Params };\n\ntype Segment =\n  | { kind: \"static\"; value: string }\n  | { kind: \"dynamic\" | \"catchAll\" | \"optionalCatchAll\"; name: string };\n\n/** Higher ranks are more specific and are tried first. */\nconst RANK = { static: 4, dynamic: 3, catchAll: 2, optionalCatchAll: 0 } as const;\nconst MISSING = 1; // a route that has already ended beats an optional catch-all\n\nfunction parse(route: string): Segment[] {\n  return route\n    .split(\"/\")\n    .filter((s) => s && !(s.startsWith(\"(\") && s.endsWith(\")\"))) // route groups aren''t part of the URL\n    .map((s): Segment => {\n      let m: RegExpExecArray | null;\n      if ((m = /^\\[\\[\\.\\.\\.(\\w+)\\]\\]$/.exec(s))) return { kind: \"optionalCatchAll\", name: m[1] };\n      if ((m = /^\\[\\.\\.\\.(\\w+)\\]$/.exec(s))) return { kind: \"catchAll\", name: m[1] };\n      if ((m = /^\\[(\\w+)\\]$/.exec(s))) return { kind: \"dynamic\", name: m[1] };\n      return { kind: \"static\", value: s };\n    });\n}\n\nfunction compare(a: Segment[], b: Segment[]) {\n  for (let i = 0; i < Math.max(a.length, b.length); i++) {\n    const ra = a[i] ? RANK[a[i].kind] : MISSING;\n    const rb = b[i] ? RANK[b[i].kind] : MISSING;\n    if (ra !== rb) return rb - ra;\n  }\n  return 0;\n}\n\nfunction match(segments: Segment[], parts: string[]): Params | null {\n  const params: Params = {};\n  for (let i = 0; i < segments.length; i++) {\n    const seg = segments[i];\n    if (seg.kind === \"catchAll\" || seg.kind === \"optionalCatchAll\") {\n      const rest = parts.slice(i);\n      if (seg.kind === \"catchAll\" && rest.length === 0) return null;\n      if (rest.length) params[seg.name] = rest;\n      return params; // a catch-all is always the last segment\n    }\n    const part = parts[i];\n    if (part === undefined) return null;\n    if (seg.kind === \"static\" && seg.value !== part) return null;\n    if (seg.kind === \"dynamic\") params[seg.name] = part;\n  }\n  return parts.length === segments.length ? params : null;\n}\n\nexport function matchRoute(routes: string[], pathname: string): Match | null {\n  let parts: string[];\n  try {\n    parts = pathname.split(/[?#]/)[0].split(\"/\").filter(Boolean).map(decodeURIComponent);\n  } catch {\n    return null; // malformed percent-encoding\n  }\n  const candidates = routes.map((route) => ({ route, segments: parse(route) })).sort((x, y) => compare(x.segments, y.segments));\n  for (const { route, segments } of candidates) {\n    const params = match(segments, parts);\n    if (params) return { route, params };\n  }\n  return null;\n}\n"}'::jsonb),
  ('node-type-module', array['b']::text[], '{"en":"`\"type\": \"module\"` makes `.js` files in the package ES modules; `.cjs` stays CommonJS and `.mjs` is always ESM. In ESM, use `import`, `import.meta.dirname` (or `fileURLToPath(import.meta.url)`) and `createRequire` when you really need `require`.","uk":"`\"type\": \"module\"` робить файли `.js` у пакеті ES-модулями; `.cjs` лишається CommonJS, а `.mjs` — завжди ESM. В ESM використовуйте `import`, `import.meta.dirname` (або `fileURLToPath(import.meta.url)`) і `createRequire`, коли `require` справді потрібен."}'::jsonb, null::jsonb),
  ('node-backpressure', array['b']::text[], '{"en":"`write()` returns `false` when the writable''s buffer is full. A correct producer pauses until `drain`. Ignoring it buffers everything in memory. `pipeline` handles the pause/resume for you, propagates errors and destroys every stream on failure, which a manual `.pipe()` chain doesn''t.","uk":"`write()` повертає `false`, коли буфер записуваного потоку заповнений. Коректний виробник призупиняється до події `drain`. Якщо це ігнорувати, усе буферизується в пам''яті. `pipeline` сам призупиняє й відновлює, передає помилки й знищує всі потоки в разі збою — чого ручний ланцюжок `.pipe()` не робить."}'::jsonb, null::jsonb),
  ('node-immediate-vs-timeout', array['b']::text[], '{"en":"The callback runs in the poll phase. The event loop moves on to the check phase (where `setImmediate` callbacks run) before it wraps around to the timers phase, so `immediate` always comes first. At the top level of the main module, the order of these two is not deterministic, because it depends on whether 1 ms has passed when the loop starts.","uk":"Колбек виконується у фазі poll. Цикл подій переходить до фази check (де виконуються колбеки `setImmediate`) раніше, ніж повертається до фази timers, тож `immediate` завжди перший. На верхньому рівні головного модуля порядок цих двох не детермінований, бо залежить від того, чи минула 1 мс на старті циклу."}'::jsonb, null::jsonb),
  ('node-promisify', null::text[], '{"en":"Wrap the call in `new Promise`: its executor already turns synchronous throws into rejections, and the error-first callback maps to `reject`/`resolve`. A regular `function` (not an arrow) receives the caller''s `this`, which `fn.call(this, ...)` forwards. Today you''d usually import `promisify` from `node:util` or use the `node:fs/promises` APIs directly.","uk":"Обгорніть виклик у `new Promise`: його виконавець уже перетворює синхронні винятки на відхилення, а колбек з помилкою першим аргументом зіставляється з `reject`/`resolve`. Звичайна `function` (не стрілкова) отримує `this` викликача, який `fn.call(this, ...)` передає далі. Сьогодні зазвичай імпортують `promisify` з `node:util` або одразу використовують API `node:fs/promises`."}'::jsonb, '{"/src/promisify.js":"export function promisify(fn) {\n  return function (...args) {\n    return new Promise((resolve, reject) => {\n      const callback = (err, value) => (err ? reject(err) : resolve(value));\n      fn.call(this, ...args, callback);\n    });\n  };\n}\n"}'::jsonb),
  ('node-blocking', array['a']::text[], '{"en":"JavaScript callbacks run on one thread, so a long synchronous computation stalls every other request and timer. Move CPU work to worker threads, another service or a job queue.","uk":"Колбеки JavaScript виконуються в одному потоці, тож довге синхронне обчислення зупиняє всі інші запити й таймери. Виносьте CPU-роботу у worker threads, інший сервіс або чергу задач."}'::jsonb, null::jsonb),
  ('node-microtask-order', array['a']::text[], '{"en":"After the current operation completes, Node drains the `process.nextTick` queue first, then the promise microtask queue, and only then moves on to timers and `setImmediate` (whose relative order in the main module can vary).","uk":"Після завершення поточної операції Node спершу вичерпує чергу `process.nextTick`, потім чергу мікрозадач промісів, і лише тоді переходить до таймерів і `setImmediate` (їхній взаємний порядок у головному модулі може відрізнятися)."}'::jsonb, null::jsonb),
  ('node-streams', array['a']::text[], '{"en":"Streams process chunks with constant memory, and `pipeline` handles backpressure and error propagation. Reading the whole file would exceed memory, and synchronous zlib would block the event loop.","uk":"Потоки обробляють частини даних зі сталим обсягом пам''яті, а `pipeline` обробляє зворотний тиск і передає помилки. Читання всього файлу перевищило б пам''ять, а синхронний zlib заблокував би цикл подій."}'::jsonb, null::jsonb),
  ('node-unhandled-rejection', array['a']::text[], '{"en":"Since Node 15 the default `--unhandled-rejections=throw` mode turns an unhandled rejection into an uncaught exception, which crashes the process. Always `await` inside `try/catch` or attach `.catch`.","uk":"Починаючи з Node 15 типовий режим `--unhandled-rejections=throw` перетворює необроблене відхилення на неперехоплений виняток, що завершує процес. Завжди використовуйте `await` усередині `try/catch` або додавайте `.catch`."}'::jsonb, null::jsonb),
  ('node-scaling-cores', array['a']::text[], '{"en":"Each Node process runs JavaScript on one core, so you scale horizontally with multiple processes. Keep them stateless (sessions and caches in Redis or a database) so any instance can serve any request. The libuv thread pool size only affects certain I/O and crypto work.","uk":"Кожен процес Node виконує JavaScript на одному ядрі, тож масштабуються горизонтально, кількома процесами. Тримайте їх без стану (сесії й кеші в Redis чи базі даних), щоб будь-який екземпляр міг обслужити будь-який запит. Розмір пулу потоків libuv впливає лише на певні операції вводу-виводу й криптографії."}'::jsonb, null::jsonb),
  ('npm-ci-vs-install', array['b']::text[], '{"en":"`npm ci` is built for repeatable builds: it deletes `node_modules` and installs from the lockfile without changing it. `npm install` may rewrite the lockfile, so two runs on different days can build different code, which is exactly what CI must avoid.","uk":"`npm ci` створений для повторюваних збирань: він видаляє `node_modules` і встановлює з lock-файлу, не змінюючи його. `npm install` може переписати lock-файл, тож два запуски в різні дні можуть зібрати різний код, а саме цього CI має уникати."}'::jsonb, null::jsonb),
  ('npm-semver-range', null::text[], '{"en":"A range is a set of versions, and each operator just defines bounds on that set. The caret rule is the subtle one: npm treats `0.x` as unstable, so the first non-zero part is what''s protected (`^0.2.3` may change patch versions, not minor ones), which is why the function looks at which parts are zero instead of always locking the major. Partial versions matter too: `^1` and `~1` carry less information, so their bounds widen. Comparing as a tuple of numbers (not strings, where `\"10\"` sorts before `\"9\"`) is the other trap. This is why `npm install` and `npm ci` can disagree about what \"4.17\" means without a lockfile to pin the exact version.","uk":"Діапазон — це множина версій, а кожен оператор задає межі цієї множини. Правило для `^` найтонше: npm вважає `0.x` нестабільним, тож захищається перша ненульова частина (`^0.2.3` може змінювати версії патча, але не мінорні), тому функція дивиться, які частини нульові, а не завжди фіксує мажорну. Неповні версії теж важливі: `^1` і `~1` несуть менше інформації, тому їхні межі ширші. Ще одна пастка — порівняння як кортежу чисел, а не рядків, де `\"10\"` іде перед `\"9\"`. Тому без lock-файла, що фіксує точну версію, `npm install` і `npm ci` можуть по-різному трактувати «4.17»."}'::jsonb, '{"/src/semver.ts":"type V = [number, number, number];\n\nfunction parseVersion(text: string): V {\n  const m = /^(\\d+)\\.(\\d+)\\.(\\d+)$/.exec(text);\n  if (m === null) throw new SyntaxError(\"Invalid version: \" + text);\n  return [Number(m[1]), Number(m[2]), Number(m[3])];\n}\n\n/** A partial version such as \"1\", \"1.2\" or \"1.2.3\", remembering how many parts were written. */\nfunction parsePartial(text: string): { v: V; parts: number } {\n  const pieces = text.split(\".\");\n  if (pieces.length > 3 || pieces.some((p) => !/^\\d+$/.test(p))) throw new SyntaxError(\"Invalid version: \" + text);\n  const nums = pieces.map(Number);\n  return { v: [nums[0] ?? 0, nums[1] ?? 0, nums[2] ?? 0], parts: nums.length };\n}\n\nconst compare = (a: V, b: V) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2];\n\n/** ^ keeps everything that doesn''t change the first non-zero part: ^1.2.3 is <2.0.0, ^0.2.3 is <0.3.0, ^0.0.3 is <0.0.4. */\nfunction caretBounds(text: string): [V, V] {\n  const { v, parts } = parsePartial(text);\n  const [major, minor, patch] = v;\n  if (parts === 1 || major > 0) return [v, [major + 1, 0, 0]];\n  if (parts === 2 || minor > 0) return [v, [0, minor + 1, 0]];\n  return [v, [0, 0, patch + 1]];\n}\n\n/** ` allows patch-level changes when a minor is given, and minor-level changes when only a major is. */\nfunction tildeBounds(text: string): [V, V] {\n  const { v, parts } = parsePartial(text);\n  const [major, minor] = v;\n  return [v, parts === 1 ? [major + 1, 0, 0] : [major, minor + 1, 0]];\n}\n\nexport function satisfies(version: string, range: string): boolean {\n  const v = parseVersion(version);\n  const comparators = range.trim().split(/\\s+/).filter((c) => c !== \"\");\n  return comparators.every((c) => {\n    if (c === \"*\") return true;\n    if (c.startsWith(\"^\") || c.startsWith(\"`\")) {\n      const [lo, hi] = c.startsWith(\"^\") ? caretBounds(c.slice(1)) : tildeBounds(c.slice(1));\n      return compare(v, lo) >= 0 && compare(v, hi) < 0;\n    }\n    const op = /^(>=|<=|>|<|=)?(.*)$/.exec(c)!;\n    const diff = compare(v, parsePartial(op[2]).v);\n    switch (op[1]) {\n      case \">=\":\n        return diff >= 0;\n      case \"<=\":\n        return diff <= 0;\n      case \">\":\n        return diff > 0;\n      case \"<\":\n        return diff < 0;\n      default:\n        return diff === 0;\n    }\n  });\n}\n"}'::jsonb),
  ('oop-four-pillars', array['c']::text[], '{"en":"The four pillars are encapsulation, abstraction, inheritance and polymorphism. Memoisation is a caching technique for function results and has nothing to do with OOP specifically.","uk":"Чотири принципи: інкапсуляція, абстракція, успадкування й поліморфізм. Мемоізація є технікою кешування результатів функцій і з ООП безпосередньо не пов''язана."}'::jsonb, null::jsonb),
  ('oop-private-fields', array['a']::text[], '{"en":"TypeScript''s `private` and `protected` are checked only by the compiler and disappear in the emitted JavaScript. `#fields` are a JavaScript feature: the engine rejects access from outside the class body (it''s a syntax error), and they don''t show up in `Object.keys` or `JSON.stringify`.","uk":"`private` і `protected` у TypeScript перевіряє лише компілятор, і в отриманому JavaScript їх немає. Поля `#` є можливістю самого JavaScript: рушій забороняє доступ поза тілом класу (це синтаксична помилка), і вони не потрапляють в `Object.keys` чи `JSON.stringify`."}'::jsonb, null::jsonb),
  ('oop-super-before-this', array['a']::text[], '{"en":"In a derived class the parent constructor creates the object, so `this` is uninitialised until `super(...)` returns. Accessing it earlier throws a `ReferenceError`. Call `super(name)` first, then set subclass fields.","uk":"У похідному класі об''єкт створює батьківський конструктор, тож `this` не ініціалізований, доки `super(...)` не повернеться. Звернення раніше кидає `ReferenceError`. Спершу викличте `super(name)`, а потім встановлюйте поля підкласу."}'::jsonb, null::jsonb),
  ('oop-detached-method', array['a']::text[], '{"en":"`this` is decided by how a function is called. Passing `counter.increment` passes only the function; the DOM calls it with `this` set to the element, and in other detached calls (strict class code) it''s `undefined`. Use `counter.increment.bind(counter)`, `() => counter.increment()`, or define `increment = () => { ... }` as a class field.","uk":"`this` визначається способом виклику функції. Передаючи `counter.increment`, ви передаєте лише функцію; DOM викликає її з `this`, що вказує на елемент, а в інших відірваних викликах (строгий код класу) це `undefined`. Використайте `counter.increment.bind(counter)`, `() => counter.increment()` або визначте `increment = () => { ... }` як поле класу."}'::jsonb, null::jsonb),
  ('oop-polymorphic-dispatch', array['a']::text[], '{"en":"`speak` in `Animal` calls `this.sound()`, and `this` is the actual object, so `Cat`''s override is used. `Kitten` inherits `sound` from `Cat` and overrides `speak`, calling the parent version through `super.speak()` (which still uses `this.sound()` → `\"meow\"`) and upper-casing the result.","uk":"`speak` в `Animal` викликає `this.sound()`, а `this` є конкретним об''єктом, тож використовується перевизначення з `Cat`. `Kitten` успадковує `sound` від `Cat` і перевизначає `speak`, викликаючи батьківську версію через `super.speak()` (яка й далі використовує `this.sound()` → `\"meow\"`) і переводячи результат у верхній регістр."}'::jsonb, null::jsonb),
  ('oop-composition', array['a']::text[], '{"en":"`Penguin` breaks the Liskov substitution principle: it can''t stand in for a `Bird` as callers expect. Type checks and empty overrides hide the broken contract instead of fixing it. Splitting the capability out (composition or a narrower interface) means only objects that really fly are passed to code that calls `fly()`.","uk":"`Penguin` порушує принцип підстановки Лісков: він не може заступити `Bird` так, як очікують викликачі. Перевірки типу й порожні перевизначення ховають порушений контракт, а не виправляють його. Винесення здібності окремо (композиція або вужчий інтерфейс) означає, що в код, який викликає `fly()`, потрапляють лише об''єкти, що справді літають."}'::jsonb, null::jsonb),
  ('oop-own-keys', array['a']::text[], '{"en":"Methods such as `bark` are defined on `Dog.prototype` and shared, so they''re not own keys. Class fields, including the arrow-function field `wag`, are created on each instance, and in a base class they''re initialised right before the constructor body runs, which is why `wag` comes before `name`.","uk":"Методи на кшталт `bark` визначені в `Dog.prototype` і спільні, тож не є власними ключами. Поля класу, зокрема поле-стрілочна функція `wag`, створюються в кожному екземплярі, а в базовому класі ініціалізуються безпосередньо перед тілом конструктора, тому `wag` іде перед `name`."}'::jsonb, null::jsonb),
  ('oop-fragile-base', array['a']::text[], '{"en":"`CountingList.addAll` adds 3, then calls `super.addAll`, which calls `this.add` for each item, and `this.add` is the overridden, counting version: 3 more. The subclass silently depends on how the parent implements `addAll`. That''s the fragile base class problem; wrapping a list (composition) and delegating avoids it.","uk":"`CountingList.addAll` додає 3, потім викликає `super.addAll`, який для кожного елемента викликає `this.add`, а `this.add` є перевизначеною версією з підрахунком: ще 3. Підклас непомітно залежить від того, як батько реалізує `addAll`. Це проблема крихкого базового класу; обгортання списку (композиція) з делегуванням її уникає."}'::jsonb, null::jsonb),
  ('oop-bank-account', null::text[], '{"en":"`#balance` and `#history` can only change through the class''s own methods, so validation can''t be bypassed. A getter without a setter makes `balance` read-only, and returning copies stops callers from editing the ledger. Subclasses don''t touch private state: they override the `canWithdraw` rule and use the protected `apply` method, which keeps balance and history consistent in one place.","uk":"`#balance` і `#history` можуть змінюватися лише через методи самого класу, тож обійти валідацію неможливо. Гетер без сетера робить `balance` доступним лише для читання, а повернення копій не дає викликачам редагувати журнал. Підкласи не чіпають приватний стан: вони перевизначають правило `canWithdraw` і користуються захищеним методом `apply`, що тримає баланс та історію узгодженими в одному місці."}'::jsonb, '{"/src/account.ts":"export type Entry = { type: \"deposit\" | \"withdraw\" | \"interest\"; amount: number };\n\nconst toCents = (n: number) => Math.round(n * 100) / 100;\n\nexport class Account {\n  #balance = 0;\n  #history: Entry[] = [];\n\n  constructor(readonly owner: string) {}\n\n  get balance(): number {\n    return this.#balance;\n  }\n\n  /** A copy, so callers can''t rewrite the ledger. */\n  get history(): Entry[] {\n    return this.#history.map((e) => ({ ...e }));\n  }\n\n  deposit(amount: number): void {\n    assertAmount(amount);\n    this.apply(\"deposit\", amount);\n  }\n\n  withdraw(amount: number): void {\n    assertAmount(amount);\n    if (!this.canWithdraw(amount)) throw new Error(\"Insufficient funds\");\n    this.apply(\"withdraw\", amount);\n  }\n\n  /** Subclasses override this to change the withdrawal rule. */\n  protected canWithdraw(amount: number): boolean {\n    return amount <= this.#balance;\n  }\n\n  /** The only place the balance changes, so history and balance never disagree. */\n  protected apply(type: Entry[\"type\"], amount: number): void {\n    this.#balance = toCents(this.#balance + (type === \"withdraw\" ? -amount : amount));\n    this.#history.push({ type, amount });\n  }\n}\n\nfunction assertAmount(amount: number) {\n  if (typeof amount !== \"number\" || !Number.isFinite(amount) || amount <= 0) {\n    throw new RangeError(\"Amount must be a positive number\");\n  }\n}\n\nexport class SavingsAccount extends Account {\n  constructor(owner: string, readonly rate: number) {\n    super(owner);\n  }\n\n  addInterest(): void {\n    const interest = toCents(this.balance * this.rate);\n    if (interest > 0) this.apply(\"interest\", interest);\n  }\n}\n\nexport class CheckingAccount extends Account {\n  constructor(owner: string, readonly overdraft: number) {\n    super(owner);\n  }\n\n  protected canWithdraw(amount: number): boolean {\n    return this.balance - amount >= -this.overdraft;\n  }\n}\n"}'::jsonb),
  ('oop-shapes', null::text[], '{"en":"`describe` lives only on `Shape.prototype` and calls `this.area()` and `this.perimeter()`, which resolve to each subclass''s override at runtime. `abstract` disappears after compilation, so a `new.target === Shape` check enforces it at runtime. `Square` reuses `Rectangle` by passing the side twice to `super`.","uk":"`describe` живе лише в `Shape.prototype` і викликає `this.area()` і `this.perimeter()`, які під час виконання ведуть до перевизначень кожного підкласу. `abstract` зникає після компіляції, тож перевірка `new.target === Shape` забезпечує його під час виконання. `Square` повторно використовує `Rectangle`, передаючи сторону двічі в `super`."}'::jsonb, '{"/src/shapes.ts":"function assertPositive(...values: number[]) {\n  for (const v of values) {\n    if (!Number.isFinite(v) || v <= 0) throw new RangeError(\"Dimensions must be positive numbers\");\n  }\n}\n\nexport abstract class Shape {\n  constructor() {\n    // \"abstract\" is compile-time only; this guard also stops casts and plain JS callers.\n    if (new.target === Shape) throw new TypeError(\"Shape is abstract\");\n  }\n\n  abstract area(): number;\n  abstract perimeter(): number;\n\n  /** Written once: this.area() dispatches to the subclass (polymorphism). */\n  describe(): string {\n    return this.constructor.name + \" area=\" + this.area().toFixed(2) + \" perimeter=\" + this.perimeter().toFixed(2);\n  }\n}\n\nexport class Circle extends Shape {\n  constructor(readonly radius: number) {\n    super();\n    assertPositive(radius);\n  }\n  area() {\n    return Math.PI * this.radius ** 2;\n  }\n  perimeter() {\n    return 2 * Math.PI * this.radius;\n  }\n}\n\nexport class Rectangle extends Shape {\n  constructor(readonly width: number, readonly height: number) {\n    super();\n    assertPositive(width, height);\n  }\n  area() {\n    return this.width * this.height;\n  }\n  perimeter() {\n    return 2 * (this.width + this.height);\n  }\n}\n\nexport class Square extends Rectangle {\n  constructor(side: number) {\n    super(side, side);\n  }\n  get side() {\n    return this.width;\n  }\n}\n\nexport function largest(shapes: Shape[]): Shape | undefined {\n  let best: Shape | undefined;\n  for (const s of shapes) if (!best || s.area() > best.area()) best = s;\n  return best;\n}\n"}'::jsonb),
  ('pw-locators-autowait', array['a']::text[], '{"en":"Pages change while a test runs: elements re-render, get replaced, or appear late. A locator is a query that Playwright re-evaluates before each action, and actions wait for the element to be actionable, which removes most manual `waitFor` calls and most flakiness. An element handle points at one DOM node, so after a re-render it can refer to something that is gone.","uk":"Сторінки змінюються, поки виконується тест: елементи перемальовуються, замінюються або з''являються пізно. Локатор — це запит, який Playwright повторно виконує перед кожною дією, а дії чекають, доки елемент стане доступним для взаємодії, тож зникає більшість ручних викликів `waitFor` і більшість нестабільності. Дескриптор вказує на один вузол DOM, тож після перемальовування він може посилатися на щось, чого вже немає."}'::jsonb, null::jsonb),
  ('pw-resilient-selectors', array['b']::text[], '{"en":"Role and accessible name describe what the user sees and what assistive technology announces, so they change only when the behaviour changes. Positional selectors break when a sibling is added, and generated class names change on every build. Role-based locators also double as an accessibility check: a button without an accessible name won''t be found.","uk":"Роль і доступна назва описують те, що бачить користувач і що озвучують допоміжні технології, тож вони змінюються, лише коли змінюється поведінка. Позиційні селектори ламаються, коли додають сусідній елемент, а згенеровані назви класів змінюються при кожній збірці. Локатори за роллю водночас є перевіркою доступності: кнопку без доступної назви не знайти."}'::jsonb, null::jsonb),
  ('pw-what-to-e2e', array['a']::text[], '{"en":"E2E tests are slow and comparatively brittle, so spend them on critical journeys that cross pages and services. Pure logic (formatting, sorting, validation rules) is cheaper and more precise to test with unit or component tests. Keep a thin E2E layer on top of many fast lower-level tests.","uk":"Наскрізні тести повільні й відносно крихкі, тож витрачайте їх на критичні сценарії, що проходять через сторінки й сервіси. Чисту логіку (форматування, сортування, правила валідації) дешевше й точніше тестувати модульними чи компонентними тестами. Тримайте тонкий шар E2E поверх багатьох швидких тестів нижчого рівня."}'::jsonb, null::jsonb),
  ('pw-locators', array['a']::text[], '{"en":"Role-based locators match what users and assistive technology perceive, survive markup and styling changes, and fail if the button loses its accessible name. Structural CSS/XPath selectors and generated class names break with every refactor. Use `getByTestId` when no user-facing attribute is stable.","uk":"Локатори за роллю відповідають тому, що сприймають користувачі й допоміжні технології, переживають зміни розмітки та стилів і падають, якщо кнопка втратила доступну назву. Структурні CSS/XPath-селектори й згенеровані назви класів ламаються з кожним рефакторингом. Використовуйте `getByTestId`, коли жоден атрибут, видимий користувачу, не стабільний."}'::jsonb, null::jsonb),
  ('pw-web-first-assertions', array['a']::text[], '{"en":"`textContent()` reads the value once, immediately, so the assertion races the app. `expect(locator).toHaveText()` polls until the condition holds. Fixed sleeps make tests slow and still flaky on slow machines; retries only hide the problem.","uk":"`textContent()` читає значення один раз і одразу, тож перевірка змагається із застосунком. `expect(locator).toHaveText()` опитує, доки умова не виконається. Фіксовані паузи роблять тести повільними й однаково нестабільними на повільних машинах; повтори лише ховають проблему."}'::jsonb, null::jsonb),
  ('pw-strict-mode', array['a']::text[], '{"en":"Strict mode protects you from acting on the wrong element when a locator is ambiguous. Narrowing by a meaningful container (the row for invoice 42) states exactly which button the test means. `.first()` silences the error but makes the test depend on row order.","uk":"Суворий режим захищає від дій над неправильним елементом, коли локатор неоднозначний. Звуження до змістовного контейнера (рядка рахунку 42) точно вказує, яку кнопку має на увазі тест. `.first()` приглушує помилку, але робить тест залежним від порядку рядків."}'::jsonb, null::jsonb),
  ('pw-storage-state', array['a']::text[], '{"en":"`storageState` captures cookies and local storage after logging in; each test then gets a fresh, isolated context that''s already authenticated. Tests stay independent and parallelisable. Keep one test that goes through the real login form, and keep credentials in environment variables, not in code.","uk":"`storageState` зберігає cookie й локальне сховище після входу; кожен тест потім отримує новий ізольований контекст, що вже автентифікований. Тести лишаються незалежними й можуть іти паралельно. Лишіть один тест, що проходить справжню форму входу, а облікові дані тримайте в змінних оточення, а не в коді."}'::jsonb, null::jsonb),
  ('pw-ci-only-failure', array['a']::text[], '{"en":"Intermittent CI failures usually come from timing, shared data between parallel tests, or environment differences (slower machines, fonts, time zones). A trace shows exactly what the page looked like and which requests were pending at each step, which points to the real cause. Skipping, sleeping and retrying hide the problem.","uk":"Нестабільні падіння в CI зазвичай спричинені таймінгом, спільними даними між паралельними тестами чи відмінностями середовища (повільніші машини, шрифти, часові пояси). Трасування показує, як саме виглядала сторінка і які запити очікували на кожному кроці, що вказує на справжню причину. Пропуск, паузи й повтори ховають проблему."}'::jsonb, null::jsonb),
  ('pi-settle-once', array['a']::text[], '{"en":"A promise settles once: the first `resolve(1)` wins, and the later `reject`, `resolve` and even the `throw` are ignored (the throw is caught by the executor wrapper and turned into a `reject` call, which does nothing now). This is one of the trust guarantees callbacks can''t give you.","uk":"Проміс завершується один раз: перемагає перший `resolve(1)`, а пізніші `reject`, `resolve` і навіть `throw` ігноруються (`throw` перехоплює обгортка виконавця й перетворює на виклик `reject`, що тепер нічого не робить). Це одна з гарантій довіри, яких колбеки дати не можуть."}'::jsonb, null::jsonb),
  ('pi-then-passthrough', array['a']::text[], '{"en":"`then` ignores arguments that aren''t functions and passes the value (or rejection) through unchanged to the next promise. That''s also how `catch(fn)` works: it''s `then(undefined, fn)`, so fulfilled values pass through it.","uk":"`then` ігнорує аргументи, що не є функціями, і передає значення (чи відхилення) далі без змін наступному промісу. Так само працює й `catch(fn)`: це `then(undefined, fn)`, тож виконані значення проходять крізь нього."}'::jsonb, null::jsonb),
  ('pi-then-two-args', array['a']::text[], '{"en":"The second argument of `then` only handles a rejection of the promise **before** it, which was fulfilled. The error thrown inside the success handler rejects the promise **returned** by that `then`, so only the following `catch` sees it. Use `then(onOk).catch(onErr)` when errors from `onOk` should be handled too.","uk":"Другий аргумент `then` обробляє лише відхилення промісу **перед** ним, а той був виконаний. Помилка, кинута в обробнику успіху, відхиляє проміс, **повернений** цим `then`, тож бачить її лише наступний `catch`. Використовуйте `then(onOk).catch(onErr)`, коли помилки з `onOk` теж треба обробити."}'::jsonb, null::jsonb),
  ('pi-resolve-rejected', array['a']::text[], '{"en":"Calling `resolve` doesn''t necessarily fulfil a promise: resolving with another promise (or any thenable) makes it **adopt** that promise''s outcome. Here the inner promise is rejected, so the outer one is too. \"Resolved\" means \"locked in\", not \"succeeded\".","uk":"Виклик `resolve` не обов''язково виконує проміс: розв''язання іншим промісом (чи будь-яким thenable) змушує його **перейняти** результат того промісу. Тут внутрішній проміс відхилений, тож зовнішній теж. «Розв''язаний» означає «зафіксований», а не «успішний»."}'::jsonb, null::jsonb),
  ('pi-promise-resolve-identity', array['a']::text[], '{"en":"`Promise.resolve(p)` returns `p` itself when `p` is a native promise from the same constructor, so it''s cheap to normalise values. `new Promise((r) => r(p))` always creates a **new** promise that adopts `p`''s outcome, which also costs extra microtask ticks.","uk":"`Promise.resolve(p)` повертає сам `p`, коли `p` є нативним промісом від того самого конструктора, тож нормалізувати значення дешево. `new Promise((r) => r(p))` завжди створює **новий** проміс, що переймає результат `p`, і це ще й коштує додаткових тактів мікрозадач."}'::jsonb, null::jsonb),
  ('pi-thenable', array['a']::text[], '{"en":"Any object with a `then` method is a **thenable**, and promises adopt thenables instead of fulfilling with them. The thenable''s `then` is called in a microtask (a \"resolve thenable job\"), never synchronously, so `sync end` comes first. This duck typing is what lets promises interoperate across libraries, and it''s also why an object with an unrelated `then` method behaves strangely when returned from `async` functions.","uk":"Будь-який об''єкт із методом `then` є **thenable**, і проміси переймають thenable замість того, щоб виконуватися з ним як значенням. `then` такого об''єкта викликається в мікрозадачі («resolve thenable job»), ніколи синхронно, тож `sync end` іде першим. Саме ця «качина типізація» дає промісам взаємодіяти між бібліотеками, і через неї ж об''єкт зі стороннім методом `then` дивно поводиться, коли його повертають з `async`-функцій."}'::jsonb, null::jsonb),
  ('pi-misbehaving-thenable', array['a']::text[], '{"en":"The resolution procedure passes a thenable a fresh pair of callbacks guarded by a shared \"called\" flag, so only the first call counts and the rest are ignored. That protects promise chains from buggy or malicious thenables, which is exactly the trust problem raw callbacks have.","uk":"Процедура розв''язання передає thenable нову пару колбеків, захищених спільним прапорцем «викликано», тож рахується лише перший виклик, а решта ігнорується. Це захищає ланцюжки промісів від хибних чи зловмисних thenable, а це якраз та проблема довіри, яку мають сирі колбеки."}'::jsonb, null::jsonb),
  ('pi-resolve-self', array['a']::text[], '{"en":"Adopting itself would mean waiting for itself forever, so the resolution procedure checks for this case first and rejects with a `TypeError` (\"Chaining cycle detected\"). The same happens when a `then` callback returns the very promise that `then` returned.","uk":"Перейняти самого себе означало б чекати на себе вічно, тож процедура розв''язання спершу перевіряє цей випадок і відхиляє з `TypeError` («Chaining cycle detected»). Те саме стається, коли колбек `then` повертає той самий проміс, що повернув цей `then`."}'::jsonb, null::jsonb),
  ('pi-zalgo', array['a']::text[], '{"en":"The same call site sees two different orders: on the first (cache miss) call the callback runs after the following line, and on the second (cache hit) call it runs before it. Code that depends on that order (for example, \"show a spinner after the call\") breaks only some of the time. Always calling back asynchronously, as promises do, removes the inconsistency.","uk":"Те саме місце виклику бачить два різні порядки: під час першого виклику (промах кешу) колбек виконується після наступного рядка, а під час другого (влучання в кеш) перед ним. Код, що залежить від цього порядку (наприклад, «показати спінер після виклику»), ламається лише іноді. Завжди асинхронний виклик колбека, як у промісах, прибирає цю непослідовність."}'::jsonb, null::jsonb),
  ('pi-unhandled-late-catch', array['a']::text[], '{"en":"A rejection counts as unhandled if no handler is attached once the current macrotask''s microtasks have run. The `catch` is attached in a later timer, which is too late: since Node 15 the default is to treat unhandled rejections like uncaught exceptions and exit. Browsers instead fire `unhandledrejection` (and later `rejectionhandled`). Attach handlers in the same tick you create the promise.","uk":"Відхилення вважається необробленим, якщо після виконання мікрозадач поточної макрозадачі обробника не приєднано. `catch` приєднується в пізнішому таймері, а це запізно: від Node 15 за замовчуванням необроблені відхилення обробляються як неперехоплені винятки, і процес завершується. Браузери натомість запускають `unhandledrejection` (а згодом `rejectionhandled`). Приєднуйте обробники в тому самому такті, в якому створюєте проміс."}'::jsonb, null::jsonb),
  ('pi-my-promise', null::text[], '{"en":"The core is three pieces of state (`state`, `value`, pending `handlers`) and two operations. `#settle` changes state exactly once and schedules handlers; `#resolve` implements the resolution procedure: a self-check, then reading `then` once (the getter could throw) and calling it in a microtask with callbacks guarded by a `called` flag. Each `then` creates the next promise and, when the current one settles, runs the matching handler in a microtask and feeds its result back through the same procedure, which is what makes returned promises and thenables chain. `finally` is just a `then` that runs the callback and passes the original outcome through.","uk":"Основа складається з трьох частин стану (`state`, `value`, очікувані `handlers`) і двох операцій. `#settle` змінює стан рівно один раз і планує обробники; `#resolve` реалізує процедуру розв''язання: перевірка на себе, потім однократне читання `then` (гетер може кинути помилку) і його виклик у мікрозадачі з колбеками, захищеними прапорцем `called`. Кожен `then` створює наступний проміс і, коли поточний завершується, виконує відповідний обробник у мікрозадачі й передає його результат через ту саму процедуру, і саме це дає змогу зв''язувати в ланцюжки повернені проміси й thenable. `finally` є просто `then`, що виконує колбек і передає початковий результат далі."}'::jsonb, '{"/src/my-promise.ts":"type Executor = (resolve: (value?: any) => void, reject: (reason?: any) => void) => void;\ntype Handler = {\n  onFulfilled?: (value: any) => any;\n  onRejected?: (reason: any) => any;\n  resolve: (value: any) => void;\n  reject: (reason: any) => void;\n};\n\nexport class MyPromise {\n  #state: \"pending\" | \"fulfilled\" | \"rejected\" = \"pending\";\n  #value: any;\n  #handlers: Handler[] = [];\n\n  constructor(executor: Executor) {\n    // Only the first call to resolve/reject counts, including a resolve that''s still adopting a thenable.\n    let done = false;\n    const resolve = (value: any) => {\n      if (done) return;\n      done = true;\n      this.#resolve(value);\n    };\n    const reject = (reason: any) => {\n      if (done) return;\n      done = true;\n      this.#settle(\"rejected\", reason);\n    };\n    try {\n      executor(resolve, reject);\n    } catch (error) {\n      reject(error);\n    }\n  }\n\n  // The promise resolution procedure.\n  #resolve(x: any) {\n    if (x === this) {\n      this.#settle(\"rejected\", new TypeError(\"A promise can''t be resolved with itself\"));\n      return;\n    }\n    if (x !== null && (typeof x === \"object\" || typeof x === \"function\")) {\n      let then: any;\n      try {\n        then = x.then;\n      } catch (error) {\n        this.#settle(\"rejected\", error);\n        return;\n      }\n      if (typeof then === \"function\") {\n        let called = false; // a thenable may call both callbacks, or call one twice\n        queueMicrotask(() => {\n          try {\n            then.call(\n              x,\n              (y: any) => {\n                if (called) return;\n                called = true;\n                this.#resolve(y);\n              },\n              (r: any) => {\n                if (called) return;\n                called = true;\n                this.#settle(\"rejected\", r);\n              },\n            );\n          } catch (error) {\n            if (!called) {\n              called = true;\n              this.#settle(\"rejected\", error);\n            }\n          }\n        });\n        return;\n      }\n    }\n    this.#settle(\"fulfilled\", x);\n  }\n\n  #settle(state: \"fulfilled\" | \"rejected\", value: any) {\n    if (this.#state !== \"pending\") return;\n    this.#state = state;\n    this.#value = value;\n    const handlers = this.#handlers;\n    this.#handlers = [];\n    handlers.forEach((h) => this.#run(h));\n  }\n\n  #run(h: Handler) {\n    // Always asynchronous, even for an already-settled promise: no Zalgo.\n    queueMicrotask(() => {\n      const fulfilled = this.#state === \"fulfilled\";\n      const callback = fulfilled ? h.onFulfilled : h.onRejected;\n      if (typeof callback !== \"function\") {\n        (fulfilled ? h.resolve : h.reject)(this.#value); // pass through\n        return;\n      }\n      try {\n        h.resolve(callback(this.#value));\n      } catch (error) {\n        h.reject(error);\n      }\n    });\n  }\n\n  then(onFulfilled?: any, onRejected?: any): MyPromise {\n    return new MyPromise((resolve, reject) => {\n      const handler = { onFulfilled, onRejected, resolve, reject };\n      if (this.#state === \"pending\") this.#handlers.push(handler);\n      else this.#run(handler);\n    });\n  }\n\n  catch(onRejected?: any): MyPromise {\n    return this.then(undefined, onRejected);\n  }\n\n  finally(onFinally?: () => unknown): MyPromise {\n    return this.then(\n      (value: any) => MyPromise.resolve(onFinally?.()).then(() => value),\n      (reason: any) =>\n        MyPromise.resolve(onFinally?.()).then(() => {\n          throw reason;\n        }),\n    );\n  }\n\n  static resolve(value?: any): MyPromise {\n    return value instanceof MyPromise ? value : new MyPromise((resolve) => resolve(value));\n  }\n\n  static reject(reason?: any): MyPromise {\n    return new MyPromise((_, reject) => reject(reason));\n  }\n}\n"}'::jsonb),
  ('pi-promisify', null::text[], '{"en":"`promisify` gets most guarantees for free from the `Promise` constructor: the executor catches synchronous throws, and only the first settle counts. Using a regular `function` and `fn.call(this, …)` preserves method receivers. `callbackify` starts from `Promise.resolve().then(…)` so that both sync throws and rejections flow into one handler and the callback is never called synchronously; invoking `cb` via `queueMicrotask` keeps errors thrown by the callback from being swallowed as rejections. `dezalgo` flips a flag after the current synchronous run and defers any call that happens before then.","uk":"`promisify` отримує більшість гарантій безкоштовно від конструктора `Promise`: виконавець перехоплює синхронні винятки, а рахується лише перше завершення. Звичайна `function` і `fn.call(this, …)` зберігають отримувача методу. `callbackify` починає з `Promise.resolve().then(…)`, тож і синхронні винятки, і відхилення потрапляють в один обробник, а колбек ніколи не викликається синхронно; виклик `cb` через `queueMicrotask` не дає помилкам, кинутим колбеком, бути проковтнутими як відхилення. `dezalgo` перемикає прапорець після поточного синхронного виконання й відкладає будь-який виклик, що стається до того."}'::jsonb, '{"/src/promisify.ts":"type Callback = (err: unknown, value?: any) => void;\n\nexport function promisify(fn: (...args: any[]) => void) {\n  return function (this: unknown, ...args: any[]) {\n    // The executor catches sync throws, and a promise ignores every settle after the first.\n    return new Promise((resolve, reject) => {\n      fn.call(this, ...args, (err: unknown, value: unknown) => (err ? reject(err) : resolve(value)));\n    });\n  };\n}\n\nexport function callbackify(fn: (...args: any[]) => unknown) {\n  return function (this: unknown, ...args: any[]) {\n    const cb = args.pop() as Callback;\n    // Starting from a resolved promise makes sync throws into rejections, and keeps the callback async.\n    Promise.resolve()\n      .then(() => fn.apply(this, args))\n      .then(\n        (value) => queueMicrotask(() => cb(null, value)),\n        (reason) => {\n          const err = reason || Object.assign(new Error(\"Promise was rejected with a falsy value\"), { reason });\n          // Calling cb outside the chain means an exception in cb isn''t swallowed as a rejection.\n          queueMicrotask(() => cb(err));\n        },\n      );\n  };\n}\n\nexport function dezalgo<A extends unknown[]>(cb: (...args: A) => void): (...args: A) => void {\n  let sync = true;\n  queueMicrotask(() => {\n    sync = false;\n  });\n  return (...args: A) => {\n    if (sync) queueMicrotask(() => cb(...args));\n    else cb(...args);\n  };\n}\n"}'::jsonb),
  ('pwa-cache-strategy-choice', array['b']::text[], '{"en":"Network first always tries for fresh content and keeps the last successful copy for offline use. Cache first would keep serving old headlines until the entry is replaced, and network-only breaks offline entirely.","uk":"Спершу мережа завжди намагається отримати свіжий вміст і зберігає останню успішну копію для роботи офлайн. Спершу кеш віддавав би старі заголовки, доки запис не замінять, а лише мережа повністю ламає роботу офлайн."}'::jsonb, null::jsonb),
  ('pwa-cache-only-successful', array['a']::text[], '{"en":"A cache hit short-circuits the network, so one cached 500 page would replace the real content on every later visit until the entry is removed. Checking the status before `put` keeps errors out of the cache.","uk":"Попадання в кеш оминає мережу, тож одна збережена сторінка з помилкою 500 замінювала б справжній вміст при кожному наступному відвідуванні, доки запис не видалять. Перевірка статусу перед `put` не пускає помилки в кеш."}'::jsonb, null::jsonb),
  ('vite-env-exposure', array['b']::text[], '{"en":"Vite exposes only variables with the VITE_ prefix (configurable with envPrefix). Everything else stays in the build process, so server-side secrets without the prefix are not shipped.","uk":"Vite відкриває лише змінні з префіксом VITE_ (це можна змінити через envPrefix). Усе інше лишається в процесі збирання, тож серверні секрети без префікса в бандл не потрапляють."}'::jsonb, null::jsonb),
  ('vite-secrets-client', array['a']::text[], '{"en":"Values with the prefix are replaced into the client bundle at build time, so they become public the moment the site is deployed. Secrets belong on a server or edge function, which calls the third-party API for the browser.","uk":"Значення з префіксом підставляються в клієнтський бандл під час збирання, тож стають публічними щойно сайт розгорнуто. Секрети належать серверу чи edge-функції, яка звертається до сторонього API від імені браузера."}'::jsonb, null::jsonb),
  ('rxjs-retry-cold', array['a']::text[], '{"en":"`retry` unsubscribes from the failed source and subscribes to it again, so the side effects (the HTTP request) run again. This is why retries need idempotent operations, and why a delay between attempts (`retry({ count, delay })`) is usually added.","uk":"`retry` відписується від невдалого джерела і підписується знову, тож побічні ефекти (HTTP-запит) виконуються знову. Тому повтори потрібні для ідемпотентних операцій, і зазвичай між спробами додають затримку (`retry({ count, delay })`)."}'::jsonb, null::jsonb),
  ('pwa-cache-strategies', null::text[], '{"en":"Each strategy is a trade-off between freshness and speed. `cacheFirst` is fastest and works offline, but can serve stale content for as long as the entry lives, so it suits fingerprinted assets. `networkFirst` is freshest, and the cache is only a fallback, so it suits content that changes often. `staleWhileRevalidate` gives instant answers and eventual freshness, at the cost of showing one visit''s old data. All three store only successful responses, because a cached error would be served again later. Notice how `staleWhileRevalidate` keeps the background refresh from becoming an unhandled rejection: once an answer exists, a failed refresh is not the user''s problem.","uk":"Кожна стратегія є компромісом між свіжістю і швидкістю. `cacheFirst` найшвидша й працює офлайн, але може віддавати застарілий вміст, доки живе запис, тож підходить для ресурсів з хешем у назві. `networkFirst` найсвіжіша, а кеш лише запасний варіант, тож підходить для вмісту, що часто змінюється. `staleWhileRevalidate` дає миттєві відповіді і зрештою свіжі дані, ціною показу старих даних при одному відвідуванні. Усі три зберігають лише успішні відповіді, бо кешована помилка віддавалася б знову пізніше. Зверніть увагу, як `staleWhileRevalidate` не дає фоновому оновленню стати необробленим відхиленням: коли відповідь уже є, невдале оновлення не проблема користувача."}'::jsonb, '{"/src/strategies.ts":"export type Req = { url: string };\nexport type Res = { url: string; body: string; ok: boolean; source?: \"cache\" | \"network\" };\nexport type Fetcher = (req: Req) => Promise<Res>;\n\nexport interface CacheLike {\n  match(req: Req): Promise<Res | undefined>;\n  put(req: Req, res: Res): Promise<void>;\n}\n\n/** Only successful responses are cached: caching an error would serve it again later. */\nexport async function cacheFirst(req: Req, cache: CacheLike, fetcher: Fetcher): Promise<Res> {\n  const hit = await cache.match(req);\n  if (hit) return { ...hit, source: \"cache\" };\n  const res = await fetcher(req);\n  if (res.ok) await cache.put(req, res);\n  return { ...res, source: \"network\" };\n}\n\nexport async function networkFirst(req: Req, cache: CacheLike, fetcher: Fetcher): Promise<Res> {\n  let res: Res;\n  try {\n    res = await fetcher(req);\n  } catch (error) {\n    const hit = await cache.match(req);\n    if (hit) return { ...hit, source: \"cache\" };\n    throw error; // offline and nothing stored: the caller has to handle it\n  }\n  if (!res.ok) {\n    const hit = await cache.match(req);\n    if (hit) return { ...hit, source: \"cache\" };\n    return { ...res, source: \"network\" };\n  }\n  await cache.put(req, res);\n  return { ...res, source: \"network\" };\n}\n\nexport async function staleWhileRevalidate(req: Req, cache: CacheLike, fetcher: Fetcher): Promise<Res> {\n  const hit = await cache.match(req);\n  // Start the refresh either way; it updates the cache when it succeeds.\n  const refresh = fetcher(req).then(async (res) => {\n    if (res.ok) await cache.put(req, res);\n    return res;\n  });\n  if (hit) {\n    refresh.catch(() => {}); // the user already has an answer; a failed refresh is not their problem\n    return { ...hit, source: \"cache\" };\n  }\n  const res = await refresh; // nothing cached yet: wait for the network\n  return { ...res, source: \"network\" };\n}\n"}'::jsonb),
  ('vite-public-env', null::text[], '{"en":"Vite replaces `import.meta.env.VITE_*` references with literal values when it builds, which is why anything with the prefix is public: it ends up in a file anyone can download. The safe pattern is an explicit allowlist (the prefix) plus a guard for secret-looking names that **fails the build**, rather than quietly filtering. `JSON.stringify` makes the replacement a valid JavaScript string literal, so a value containing quotes or a closing script tag can''t break out of the code. Secrets themselves belong in server-side environment variables, read by code that never reaches the browser.","uk":"Vite під час збирання замінює посилання `import.meta.env.VITE_*` на буквальні значення, тому все з цим префіксом публічне: воно опиняється у файлі, який може завантажити будь-хто. Безпечний шаблон: явний список дозволених (префікс) плюс захист від назв, схожих на секрети, який **зупиняє збирання**, а не тихо фільтрує. `JSON.stringify` робить заміну коректним рядковим літералом JavaScript, тож значення з лапками чи закриваючим тегом script не може вирватися з коду. Самі секрети мають бути в серверних змінних середовища, які читає код, що ніколи не потрапляє в браузер."}'::jsonb, '{"/src/env.ts":"export type Env = Record<string, string | undefined>;\n\nexport const PREFIX = \"VITE_\";\n\nconst SECRET_LIKE = /SECRET|PRIVATE|PASSWORD/i;\n\nexport function publicEnv(env: Env, prefix = PREFIX): Record<string, string> {\n  const out: Record<string, string> = {};\n  for (const name of Object.keys(env)) {\n    const value = env[name];\n    if (!name.startsWith(prefix) || value === undefined) continue;\n    if (SECRET_LIKE.test(name)) {\n      throw new Error(\"Refusing to expose \" + name + \" to the browser: its name looks like a secret\");\n    }\n    out[name] = value;\n  }\n  return out;\n}\n\nexport function defineEnv(env: Env, prefix = PREFIX): Record<string, string> {\n  const out: Record<string, string> = {};\n  for (const [name, value] of Object.entries(publicEnv(env, prefix))) {\n    out[\"import.meta.env.\" + name] = JSON.stringify(value);\n  }\n  return out;\n}\n"}'::jsonb),
  ('rxjs-retry-backoff', null::text[], '{"en":"`defer(source)` creates a fresh observable on each subscription, so the request function runs again on every attempt. `retry({ count, delay })` does the rest: `delay` receives the error and the retry number (starting at 1), so `timer(delayMs * factor ** (retryCount - 1))` produces the exponential waits, and the count limits the attempts. Retrying a failure without a delay hammers a struggling server; backoff spreads the load. Real systems add random jitter to the delay so many clients don''t retry in lockstep.","uk":"`defer(source)` створює новий observable при кожній підписці, тож функція запиту виконується знову на кожній спробі. `retry({ count, delay })` робить решту: `delay` отримує помилку й номер повтору (починаючи з 1), тож `timer(delayMs * factor ** (retryCount - 1))` дає експоненційні паузи, а count обмежує спроби. Повтор без затримки б''є по сервері, що вже не справляється; backoff розподіляє навантаження. У реальних системах до затримки додають випадковий розкид, щоб багато клієнтів не повторювали запити синхронно."}'::jsonb, '{"/src/retry.ts":"import { defer, Observable, retry, timer } from \"rxjs\";\n\nexport type BackoffOptions = { retries: number; delayMs: number; factor?: number };\n\nexport function retryWithBackoff<T>(source: () => Observable<T>, { retries, delayMs, factor = 2 }: BackoffOptions): Observable<T> {\n  return defer(source).pipe(\n    retry({\n      count: retries,\n      // retryCount is 1 for the first retry, so the first wait is delayMs and the next is delayMs * factor.\n      delay: (_error, retryCount) => timer(delayMs * factor ** (retryCount - 1)),\n    }),\n  );\n}\n"}'::jsonb),
  ('pwa-requirements', array['a']::text[], '{"en":"HTTPS is required for service workers. The manifest describes how the installed app looks and launches. The service worker enables offline support, caching and push. No framework or app store is needed.","uk":"HTTPS потрібен для service worker. Маніфест описує, як виглядає й запускається встановлений застосунок. Service worker дає офлайн-підтримку, кешування й push. Жоден фреймворк чи магазин застосунків не потрібен."}'::jsonb, null::jsonb),
  ('pwa-sw-scope', array['a']::text[], '{"en":"A service worker controls pages within its scope, which defaults to the directory of the script''s URL. A worker at `/js/sw.js` can only control URLs under `/js/`. Put the file at the root (a broader scope can also be allowed with the `Service-Worker-Allowed` header). Note that a page registered for the first time is only controlled after a reload, unless the worker calls `clients.claim()`.","uk":"Service worker контролює сторінки в межах своєї області дії, яка за замовчуванням дорівнює каталогу URL скрипта. Worker за адресою `/js/sw.js` може контролювати лише URL у `/js/`. Покладіть файл у корінь (ширшу область також можна дозволити заголовком `Service-Worker-Allowed`). Зверніть увагу: сторінка, що реєструє worker уперше, стає контрольованою лише після перезавантаження, якщо worker не викликає `clients.claim()`."}'::jsonb, null::jsonb),
  ('pwa-update-waiting', array['a']::text[], '{"en":"To avoid two versions controlling the app at once, a new worker stays in the waiting state until no client uses the old one. Asking the user, then calling `skipWaiting()` and reloading on `controllerchange`, rolls out updates quickly without breaking open forms. Also serve `sw.js` with `Cache-Control: no-cache` so the browser checks it.","uk":"Щоб застосунком не керували дві версії одночасно, новий worker перебуває в стані очікування, доки жоден клієнт не використовує старий. Запит користувачу, а потім виклик `skipWaiting()` і перезавантаження при `controllerchange` швидко розгортають оновлення, не ламаючи відкритих форм. Також віддавайте `sw.js` з `Cache-Control: no-cache`, щоб браузер його перевіряв."}'::jsonb, null::jsonb),
  ('pwa-caching-strategies', array['a']::text[], '{"en":"Hashed assets never change, so the cache is always right. HTML must point to the latest assets, so try the network and fall back to cache offline. Stale-while-revalidate suits content where slightly old data is fine. Sensitive or mutating requests (payments, POSTs) shouldn''t be cached at all.","uk":"Хешовані ресурси ніколи не змінюються, тож кеш завжди правий. HTML має посилатися на найновіші ресурси, тож спершу пробуйте мережу, а офлайн повертайтеся до кешу. Stale-while-revalidate підходить для вмісту, де трохи застарілі дані прийнятні. Чутливі чи змінні запити (платежі, POST) взагалі не варто кешувати."}'::jsonb, null::jsonb),
  ('pwa-html-cache-first', array['a']::text[], '{"en":"Old HTML plus new server is a version mismatch: the referenced `index-abc123.js` no longer exists. Fixes: network-first for navigations, precaching the full set of assets for each version (so the old version stays self-consistent offline), keeping old assets on the CDN for a while, and prompting users to reload when a new version is ready.","uk":"Старий HTML плюс новий сервер дають невідповідність версій: згаданого `index-abc123.js` більше не існує. Виправлення: «спершу мережа» для навігації, попереднє кешування повного набору ресурсів кожної версії (щоб стара версія лишалася узгодженою офлайн), зберігання старих ресурсів на CDN деякий час і пропозиція перезавантажити, коли нова версія готова."}'::jsonb, null::jsonb),
  ('pwa-storage-in-worker', array['a']::text[], '{"en":"`localStorage` and `document.cookie` are synchronous, DOM-bound APIs that don''t exist in service workers. Global variables disappear because the browser stops idle workers at any time. IndexedDB is asynchronous, persistent and available in workers; Background Sync can then retry sending when connectivity returns.","uk":"`localStorage` і `document.cookie` є синхронними API, прив''язаними до DOM, і в service worker їх немає. Глобальні змінні зникають, бо браузер будь-коли зупиняє worker у простої. IndexedDB асинхронна, постійна й доступна у worker; Background Sync потім може повторити надсилання, коли з''єднання повернеться."}'::jsonb, null::jsonb),
  ('react-and-zero', array['b']::text[], '{"en":"`unread && <Badge />` evaluates to `0` when `unread` is 0. React skips `false`, `null` and `undefined`, but numbers are valid children, so a literal 0 appears on the page. Use a real boolean: `unread > 0 && <Badge />` or a ternary.","uk":"`unread && <Badge />` дає `0`, коли `unread` дорівнює 0. React пропускає `false`, `null` і `undefined`, але числа — коректні дочірні елементи, тож на сторінці з''являється 0. Використовуйте справжнє булеве значення: `unread > 0 && <Badge />` або тернарний оператор."}'::jsonb, null::jsonb),
  ('react-nested-component', array['b']::text[], '{"en":"React compares element types by reference. Declaring `Field` inside `Parent` creates a new function on every render, so React sees a different component type, destroys the old subtree with its state and DOM, and mounts a fresh one. Move component definitions to module level and pass data through props.","uk":"React порівнює типи елементів за посиланням. Оголошення `Field` усередині `Parent` створює нову функцію при кожному рендері, тож React бачить інший тип компонента, знищує старе піддерево разом зі станом і DOM та монтує нове. Виносьте оголошення компонентів на рівень модуля й передавайте дані через props."}'::jsonb, null::jsonb),
  ('react-deferred-value', array['a']::text[], '{"en":"`useDeferredValue` lets React render the urgent update (the input) first and re-render the expensive list with the new value in an interruptible background render. It only helps if `<Results>` is memoized, so the urgent render can skip it while the deferred value is unchanged. `useCallback` doesn''t reduce the work, an effect adds an extra render, and `flushSync` forces the slow render to happen synchronously.","uk":"`useDeferredValue` дозволяє React спершу відрендерити термінове оновлення (поле), а дорогий список перемалювати з новим значенням у фоновому рендері, який можна перервати. Це працює лише тоді, коли `<Results>` мемоїзовано, щоб терміновий рендер пропускав його, поки відкладене значення не змінилося. `useCallback` не зменшує роботу, ефект додає зайвий рендер, а `flushSync` змушує повільний рендер виконатися синхронно."}'::jsonb, null::jsonb),
  ('react-profile-cards', null::text[], '{"en":"Components are functions of their props. `children` is just another prop: whatever you nest between a component''s tags arrives there, which is how a `Card` can wrap any content without knowing it. Lists come from `map` over data, and each item needs a `key` that is stable and unique among siblings (an id, not the array index) so React can match old and new items when the list changes. Conditional rendering is plain JavaScript: a ternary chooses between the list and the fallback, and derived values like the online count are computed during render instead of being stored in state.","uk":"Компоненти є функціями від пропсів. `children` це просто ще один проп: усе, що вкладено між тегами компонента, потрапляє туди, тому `Card` може обгортати будь-який вміст, не знаючи його. Списки утворюються через `map` по даних, і кожному елементу потрібен `key`, стабільний та унікальний серед сусідів (id, а не індекс масиву), щоб React міг зіставити старі й нові елементи при зміні списку. Умовний рендер це звичайний JavaScript: тернарний оператор обирає між списком і запасним варіантом, а похідні значення, як-от кількість онлайн, обчислюються під час рендеру, а не зберігаються в стані."}'::jsonb, '{"/App.tsx":"import type { ReactNode } from \"react\";\n\nexport type Person = { id: number; name: string; role: string; online: boolean; skills: string[] };\n\nexport const PEOPLE: Person[] = [\n  { id: 1, name: \"Ada Lovelace\", role: \"Engineer\", online: true, skills: [\"Math\", \"Algorithms\"] },\n  { id: 2, name: \"Grace Hopper\", role: \"Rear admiral\", online: false, skills: [\"COBOL\", \"Compilers\", \"Leadership\"] },\n  { id: 3, name: \"Linus Torvalds\", role: \"Maintainer\", online: true, skills: [] },\n];\n\nfunction Card({ title, children }: { title: string; children: ReactNode }) {\n  return (\n    <section>\n      <h2>{title}</h2>\n      {children}\n    </section>\n  );\n}\n\nfunction PersonCard({ person }: { person: Person }) {\n  return (\n    <article data-testid={\"person-\" + person.id}>\n      <h3>{person.name}</h3>\n      <p>{person.role}</p>\n      <span data-testid={\"status-\" + person.id}>{person.online ? \"Online\" : \"Offline\"}</span>\n      {person.skills.length > 0 ? (\n        <ul>\n          {person.skills.map((skill) => (\n            <li key={skill}>{skill}</li>\n          ))}\n        </ul>\n      ) : (\n        <p>No skills listed</p>\n      )}\n    </article>\n  );\n}\n\nexport default function App() {\n  const onlineCount = PEOPLE.filter((p) => p.online).length;\n  return (\n    <main>\n      <p data-testid=\"online-count\">{onlineCount} online</p>\n      <Card title=\"Team\">\n        {PEOPLE.map((person) => (\n          <PersonCard key={person.id} person={person} />\n        ))}\n      </Card>\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-todo-immutable-state', null::text[], '{"en":"React decides whether to re-render by comparing the new state with the old one by reference. `todos.push(x); setTodos(todos)` hands React the same array, so it bails out (and with frozen data it throws before that). Treat state as read-only and always produce new values: `[...todos, newTodo]` to add, `todos.map(t => t.id === id ? { ...t, done: !t.done } : t)` to change one item (only the changed object is copied, the rest keep their identity, which also helps memoisation), and `todos.filter(...)` to remove. The new id comes from the current maximum, because `length + 1` collides after a removal.","uk":"React вирішує, чи ререндерити, порівнюючи новий стан зі старим за посиланням. `todos.push(x); setTodos(todos)` віддає React той самий масив, тож він пропускає оновлення (а із замороженими даними помилка виникає ще раніше). Ставтеся до стану як до лише для читання й завжди створюйте нові значення: `[...todos, newTodo]` для додавання, `todos.map(t => t.id === id ? { ...t, done: !t.done } : t)` для зміни одного елемента (копіюється лише змінений об''єкт, решта зберігають ідентичність, що допомагає й мемоізації) та `todos.filter(...)` для видалення. Новий id береться з поточного максимуму, бо `length + 1` дає колізію після видалення."}'::jsonb, '{"/App.tsx":"import { useState } from \"react\";\n\ntype Todo = { id: number; title: string; done: boolean };\n\n// Frozen on purpose: mutating this data throws, just as mutating state is a bug in React.\nconst INITIAL: readonly Todo[] = Object.freeze([\n  Object.freeze({ id: 1, title: \"Learn React\", done: true }),\n  Object.freeze({ id: 2, title: \"Build a project\", done: false }),\n  Object.freeze({ id: 3, title: \"Read the docs\", done: false }),\n]);\n\nexport default function App() {\n  const [todos, setTodos] = useState<Todo[]>(INITIAL as Todo[]);\n  const [text, setText] = useState(\"\");\n\n  function add() {\n    const title = text.trim();\n    if (!title) return;\n    const id = Math.max(0, ...todos.map((t) => t.id)) + 1;\n    setTodos([...todos, { id, title, done: false }]);\n    setText(\"\");\n  }\n  function toggle(id: number) {\n    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));\n  }\n  function remove(id: number) {\n    setTodos(todos.filter((t) => t.id !== id));\n  }\n  function clearCompleted() {\n    setTodos(todos.filter((t) => !t.done));\n  }\n\n  const left = todos.filter((t) => !t.done).length;\n\n  return (\n    <main>\n      <h1>Todos</h1>\n      <form\n        onSubmit={(e) => {\n          e.preventDefault();\n          add();\n        }}\n      >\n        <label htmlFor=\"new-todo\">New todo</label>\n        <input id=\"new-todo\" value={text} onChange={(e) => setText(e.target.value)} />\n        <button type=\"submit\">Add</button>\n      </form>\n      <ul>\n        {todos.map((t) => (\n          <li key={t.id}>\n            <label>\n              <input type=\"checkbox\" checked={t.done} onChange={() => toggle(t.id)} /> {t.title}\n            </label>{\" \"}\n            <button type=\"button\" aria-label={\"Remove \" + t.title} onClick={() => remove(t.id)}>\n              ×\n            </button>\n          </li>\n        ))}\n      </ul>\n      <p data-testid=\"left\">{left} left</p>\n      <button type=\"button\" onClick={clearCompleted} disabled={!todos.some((t) => t.done)}>\n        Clear completed\n      </button>\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-accordion-lift-state', null::text[], '{"en":"When two components need to coordinate, move the state to their closest common parent and pass it down as props, with callbacks to change it. The parent is now the single source of truth for \"which panel is open\", which makes the rule \"only one\" trivial: a single `openIndex` can''t describe two open panels, whereas separate booleans in each child could. Storing an index (or id) rather than a boolean per panel is the same principle as avoiding impossible states. `Panel` turned into a plain, reusable, controlled component.","uk":"Коли двом компонентам треба узгоджувати стан, перенесіть його до найближчого спільного батька й передавайте вниз як пропси разом із колбеками для зміни. Тепер батько є єдиним джерелом правди про те, яка панель відкрита, і правило \"лише одна\" стає тривіальним: один `openIndex` не може описати дві відкриті панелі, тоді як окремі булеві значення в дітях могли б. Зберігання індексу (чи id) замість булевого значення на кожну панель відповідає тому самому принципу уникнення неможливих станів. `Panel` перетворилася на звичайний багаторазовий контрольований компонент."}'::jsonb, '{"/App.tsx":"import { useState, type ReactNode } from \"react\";\n\nfunction Panel({\n  title,\n  isOpen,\n  onToggle,\n  children,\n}: {\n  title: string;\n  isOpen: boolean;\n  onToggle: () => void;\n  children: ReactNode;\n}) {\n  return (\n    <section>\n      <h3>\n        <button type=\"button\" aria-expanded={isOpen} onClick={onToggle}>\n          {title}\n        </button>\n      </h3>\n      {isOpen && <p>{children}</p>}\n    </section>\n  );\n}\n\nconst PANELS = [\n  { title: \"About\", body: \"About body\" },\n  { title: \"Details\", body: \"Details body\" },\n  { title: \"Contact\", body: \"Contact body\" },\n];\n\nexport default function App() {\n  // The parent owns the state: at most one open panel, identified by its index.\n  const [openIndex, setOpenIndex] = useState<number | null>(0);\n  return (\n    <main>\n      <h1>FAQ</h1>\n      {PANELS.map((panel, index) => (\n        <Panel\n          key={panel.title}\n          title={panel.title}\n          isOpen={openIndex === index}\n          onToggle={() => setOpenIndex(openIndex === index ? null : index)}\n        >\n          {panel.body}\n        </Panel>\n      ))}\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-signup-form-validation', null::text[], '{"en":"In a controlled input React is the source of truth: `value` comes from state and `onChange` writes back to it. That makes validation a pure function of the current values, so `errors` is computed on every render and can never go stale; only a `submitted` flag is real state, and it decides when to reveal them. `onSubmit` calls `preventDefault`, and `noValidate` turns off the browser''s own bubbles so the app''s messages are the ones the user sees. Linking each message to its field (a `<label htmlFor>` for the input, `role=\"alert\"` for the error) keeps the form usable with a screen reader; in production you would also set `aria-describedby` and `aria-invalid`.","uk":"У контрольованому полі джерелом правди є React: `value` береться зі стану, а `onChange` записує назад. Тому валідація стає чистою функцією від поточних значень: `errors` обчислюється на кожному рендері й ніколи не застаріває; справжнім станом є лише прапорець `submitted`, що вирішує, коли їх показати. `onSubmit` викликає `preventDefault`, а `noValidate` вимикає власні підказки браузера, щоб користувач бачив повідомлення застосунку. Прив''язка кожного повідомлення до поля (`<label htmlFor>` для поля, `role=\"alert\"` для помилки) залишає форму придатною для читачів екрана; у продакшені варто додати й `aria-describedby` та `aria-invalid`."}'::jsonb, '{"/App.tsx":"import { useState, type FormEvent } from \"react\";\n\nfunction validate(email: string, password: string, confirm: string) {\n  const errors: { email?: string; password?: string; confirm?: string } = {};\n  if (!/^\\S+@\\S+\\.\\S+$/.test(email)) errors.email = \"Enter a valid email\";\n  if (password.length < 8) errors.password = \"Password must be at least 8 characters\";\n  if (confirm !== password) errors.confirm = \"Passwords do not match\";\n  return errors;\n}\n\nexport default function App() {\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [confirm, setConfirm] = useState(\"\");\n  const [submitted, setSubmitted] = useState(false); // has the user tried to submit yet?\n  const [done, setDone] = useState(false);\n\n  // Derived during render, so the messages always match the current values.\n  const errors = validate(email, password, confirm);\n  const show = submitted ? errors : {};\n\n  function handleSubmit(e: FormEvent) {\n    e.preventDefault();\n    setSubmitted(true);\n    if (Object.keys(errors).length === 0) setDone(true);\n  }\n\n  if (done) {\n    return (\n      <main>\n        <p data-testid=\"success\">Welcome, {email}!</p>\n      </main>\n    );\n  }\n\n  return (\n    <main>\n      <h1>Sign up</h1>\n      <form noValidate onSubmit={handleSubmit}>\n        <label htmlFor=\"email\">Email</label>\n        <input id=\"email\" type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} />\n        {show.email && <p role=\"alert\">{show.email}</p>}\n\n        <label htmlFor=\"password\">Password</label>\n        <input id=\"password\" type=\"password\" value={password} onChange={(e) => setPassword(e.target.value)} />\n        {show.password && <p role=\"alert\">{show.password}</p>}\n\n        <label htmlFor=\"confirm\">Confirm password</label>\n        <input id=\"confirm\" type=\"password\" value={confirm} onChange={(e) => setConfirm(e.target.value)} />\n        {show.confirm && <p role=\"alert\">{show.confirm}</p>}\n\n        <button type=\"submit\">Create account</button>\n      </form>\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-reset-state-with-key', null::text[], '{"en":"React keeps a component''s state as long as it renders the same component type at the same position in the tree. Changing a prop doesn''t change that identity. Giving the component a different `key` does: when the key changes React discards the old instance (state and DOM) and mounts a new one. That''s usually better than a `useEffect` that resets state after the render, which would paint the stale draft first. The flip side, which the react.dev guide stresses, is that you don''t need a key to *keep* state: just render the same thing in the same place.","uk":"React зберігає стан компонента, доки той самий тип компонента рендериться на тій самій позиції в дереві. Зміна пропса цієї ідентичності не змінює. Інший `key` змінює: коли ключ змінюється, React відкидає старий екземпляр (стан і DOM) і монтує новий. Це зазвичай краще, ніж `useEffect`, що скидає стан після рендеру, бо тоді спершу б відмалювалася застаріла чернетка. Зворотний бік, на якому наголошує посібник react.dev: щоб *зберегти* стан, ключ не потрібен, просто рендеріть те саме на тому самому місці."}'::jsonb, '{"/App.tsx":"import { useState } from \"react\";\n\ntype Contact = { id: number; name: string };\n\nconst CONTACTS: Contact[] = [\n  { id: 1, name: \"Alice\" },\n  { id: 2, name: \"Bob\" },\n];\n\nfunction Chat({ contact }: { contact: Contact }) {\n  const [draft, setDraft] = useState(\"\");\n  const [sent, setSent] = useState<string[]>([]);\n\n  function send() {\n    const message = draft.trim();\n    if (!message) return;\n    setSent([...sent, message]);\n    setDraft(\"\");\n  }\n\n  return (\n    <section>\n      <h2>Chat with {contact.name}</h2>\n      <ul aria-label=\"Sent messages\">\n        {sent.map((message, i) => (\n          <li key={i}>{message}</li>\n        ))}\n      </ul>\n      <label htmlFor=\"draft\">Message to {contact.name}</label>\n      <textarea id=\"draft\" value={draft} onChange={(e) => setDraft(e.target.value)} />\n      <button type=\"button\" onClick={send}>\n        Send\n      </button>\n    </section>\n  );\n}\n\nexport default function App() {\n  const [selected, setSelected] = useState(CONTACTS[0]);\n  return (\n    <main>\n      <nav>\n        {CONTACTS.map((c) => (\n          <button key={c.id} type=\"button\" onClick={() => setSelected(c)}>\n            {c.name}\n          </button>\n        ))}\n      </nav>\n      {/* A different key tells React this is a different Chat: its state starts from scratch. */}\n      <Chat key={selected.id} contact={selected} />\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-stopwatch-refs', null::text[], '{"en":"State is for what the screen shows; a ref is for values React doesn''t need to render but that must persist between renders, like a timer id. Changing `ref.current` doesn''t re-render, which is exactly right for the interval id and the start timestamp, while `elapsed` is state because it is displayed. Resuming works by recomputing the start time as `Date.now() - elapsed`. Subtracting from the clock instead of adding 50 ms per tick keeps the time accurate even when ticks are delayed. A timer started in a handler must also be cleared when the component goes away, which is what the effect''s cleanup function is for. You could equally put the interval in an effect keyed on `running`; the ref version is what react.dev uses to show refs.","uk":"Стан призначений для того, що показує екран; ref потрібен для значень, які React не потрібно рендерити, але які мають зберігатися між рендерами, як-от id таймера. Зміна `ref.current` не спричиняє ререндеру, що саме те, що потрібно для id інтервалу й мітки початку, тоді як `elapsed` є станом, бо його показують. Продовження працює через перерахунок часу старту як `Date.now() - elapsed`. Віднімання від годинника замість додавання 50 мс на кожен тік зберігає точність, навіть коли тіки запізнюються. Таймер, запущений в обробнику, також треба очистити, коли компонент зникає, і саме для цього існує функція очищення ефекту. Можна й помістити інтервал в ефект із залежністю від `running`; версія з ref це те, що react.dev використовує, щоб показати refs."}'::jsonb, '{"/App.tsx":"import { useEffect, useRef, useState } from \"react\";\n\nexport default function App() {\n  const [elapsed, setElapsed] = useState(0); // milliseconds, shown on screen\n  const [running, setRunning] = useState(false);\n  const startRef = useRef(0);\n  const intervalRef = useRef<number | undefined>(undefined);\n\n  function start() {\n    if (intervalRef.current !== undefined) return;\n    // Pretend we started \"elapsed\" ms ago, so resuming continues where we stopped.\n    startRef.current = Date.now() - elapsed;\n    intervalRef.current = window.setInterval(() => setElapsed(Date.now() - startRef.current), 50);\n    setRunning(true);\n  }\n  function stop() {\n    window.clearInterval(intervalRef.current);\n    intervalRef.current = undefined;\n    setRunning(false);\n  }\n  function reset() {\n    stop();\n    setElapsed(0);\n  }\n\n  useEffect(() => {\n    return () => window.clearInterval(intervalRef.current);\n  }, []);\n\n  return (\n    <main>\n      <h1>Stopwatch</h1>\n      <p data-testid=\"time\">{(elapsed / 1000).toFixed(1)}</p>\n      <button type=\"button\" onClick={running ? stop : start}>\n        {running ? \"Stop\" : \"Start\"}\n      </button>\n      <button type=\"button\" onClick={reset}>\n        Reset\n      </button>\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-fetch-effect-race', null::text[], '{"en":"An effect that fetches synchronises the component with an external system, and each run of the effect has its own closure. When `id` changes, React runs the previous effect''s cleanup before the next effect. Setting `ignore = true` in that cleanup turns the stale request''s `.then` into a no-op, so responses can arrive in any order and only the latest one is applied. Modelling the result as one discriminated union (`loading | success | error`) rules out impossible combinations (an error together with old data) and makes the three UI branches explicit. Resetting to `loading` at the start of the effect is what removes the previous user. With `AbortController` you can also cancel the request itself when the API supports it, and in real apps a data library (TanStack Query, SWR, a framework loader) handles all this for you.","uk":"Ефект, що завантажує дані, синхронізує компонент із зовнішньою системою, і кожен запуск ефекту має власне замикання. Коли `id` змінюється, React викликає очищення попереднього ефекту перед наступним. Встановлення `ignore = true` у цьому очищенні перетворює `.then` застарілого запиту на порожню дію, тож відповіді можуть приходити в будь-якому порядку, а застосовується лише остання. Моделювання результату одним дискримінованим об''єднанням (`loading | success | error`) виключає неможливі комбінації (помилка разом зі старими даними) і робить три гілки UI явними. Скидання до `loading` на початку ефекту прибирає попереднього користувача. З `AbortController` можна скасувати й сам запит, якщо API це підтримує, а в реальних застосунках усе це бере на себе бібліотека даних (TanStack Query, SWR, завантажувач фреймворку)."}'::jsonb, '{"/App.tsx":"import { useEffect, useState } from \"react\";\nimport { fetchUser, type User } from \"./api\";\n\ntype State = { status: \"loading\" } | { status: \"success\"; user: User } | { status: \"error\"; message: string };\n\nfunction UserProfile({ id }: { id: number }) {\n  const [state, setState] = useState<State>({ status: \"loading\" });\n\n  useEffect(() => {\n    let ignore = false; // set by the cleanup when this effect is superseded\n    setState({ status: \"loading\" });\n    fetchUser(id).then(\n      (user) => {\n        if (!ignore) setState({ status: \"success\", user });\n      },\n      (error: Error) => {\n        if (!ignore) setState({ status: \"error\", message: error.message });\n      },\n    );\n    return () => {\n      ignore = true;\n    };\n  }, [id]);\n\n  if (state.status === \"loading\") return <p data-testid=\"loading\">Loading…</p>;\n  if (state.status === \"error\") return <p role=\"alert\">Error: {state.message}</p>;\n  return (\n    <article>\n      <h2>{state.user.name}</h2>\n      <p>{state.user.email}</p>\n    </article>\n  );\n}\n\nexport default function App() {\n  const [id, setId] = useState(3);\n  return (\n    <main>\n      <h1>Users</h1>\n      {[1, 2, 3, 4].map((n) => (\n        <button key={n} type=\"button\" onClick={() => setId(n)}>\n          User {n}\n        </button>\n      ))}\n      <UserProfile id={id} />\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-use-local-storage-hook', null::text[], '{"en":"A custom hook is a function whose name starts with `use` that calls other hooks; it shares **logic**, not state (each component calling it gets its own). Here it wraps `useState` and keeps it in sync with an external store. Reading in a lazy initialiser (`useState(() => ...)`) runs the parse only on the first render, and an effect keyed on `[key, value]` writes after each change. Returning `useState`''s own setter means functional updates work for free. Storage is an untrusted boundary: it can hold garbage or be unavailable (private mode, quota), so both sides are wrapped in `try/catch` and fall back to the in-memory state. Server rendering has no `window`, so a production version would guard for that, or use `useSyncExternalStore` to also react to the `storage` event from other tabs.","uk":"Власний хук це функція, чия назва починається з `use` і яка викликає інші хуки; він ділить **логіку**, а не стан (кожен компонент, що його викликає, має свій). Тут він обгортає `useState` і синхронізує його із зовнішнім сховищем. Читання в лінивому ініціалізаторі (`useState(() => ...)`) виконує розбір лише на першому рендері, а ефект із залежностями `[key, value]` записує після кожної зміни. Повернення власного сеттера `useState` означає, що функціональні оновлення працюють безкоштовно. Сховище це недовірена межа: воно може містити сміття або бути недоступним (приватний режим, квота), тож обидві сторони обгорнуто в `try/catch` з поверненням до стану в пам''яті. На сервері немає `window`, тому продакшен-версія додала б перевірку або використала б `useSyncExternalStore`, щоб ще й реагувати на подію `storage` з інших вкладок."}'::jsonb, '{"/useLocalStorage.ts":"import { useEffect, useState, type Dispatch, type SetStateAction } from \"react\";\n\nexport function useLocalStorage<T>(key: string, initialValue: T): [T, Dispatch<SetStateAction<T>>] {\n  // Lazy initialiser: storage is read once, not on every render.\n  const [value, setValue] = useState<T>(() => {\n    try {\n      const raw = window.localStorage.getItem(key);\n      return raw === null ? initialValue : (JSON.parse(raw) as T);\n    } catch (error) {\n      return initialValue;\n    }\n  });\n\n  useEffect(() => {\n    try {\n      window.localStorage.setItem(key, JSON.stringify(value));\n    } catch (error) {\n      // quota exceeded or storage disabled: keep working in memory\n    }\n  }, [key, value]);\n\n  return [value, setValue];\n}\n"}'::jsonb),
  ('react-theme-context', null::text[], '{"en":"Context lets a component deep in the tree read a value from a distant ancestor without passing it through every layer in between. `createContext` makes the channel, the provider''s `value` prop fills it, and `useContext` reads the nearest provider''s value. Wrapping that in a custom `useTheme` hook hides the context object, gives a single place to type it, and lets you fail loudly when the provider is missing (using `null` as the default and throwing is clearer than a silent wrong default). Every consumer re-renders when the provided value changes by reference, so the value is memoised; otherwise a new object on each provider render would re-render all consumers. For state that changes often or is needed by many unrelated parts, pair context with `useReducer` or use a dedicated store.","uk":"Контекст дозволяє компоненту глибоко в дереві прочитати значення від далекого предка, не передаючи його крізь кожен проміжний рівень. `createContext` створює канал, проп `value` провайдера його наповнює, а `useContext` читає значення найближчого провайдера. Обгортання в власний хук `useTheme` ховає об''єкт контексту, дає єдине місце для типізації й дозволяє гучно впасти, коли провайдера немає (`null` за замовчуванням із викиданням помилки зрозуміліший за мовчазне хибне значення). Кожен споживач ререндериться, коли надане значення змінюється за посиланням, тому значення мемоізоване; інакше новий об''єкт на кожному рендері провайдера ререндерив би всіх споживачів. Для стану, що змінюється часто або потрібен багатьом непов''язаним частинам, поєднуйте контекст з `useReducer` або беріть окреме сховище."}'::jsonb, '{"/ThemeContext.tsx":"import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from \"react\";\n\nexport type Theme = \"light\" | \"dark\";\n\ntype ThemeValue = { theme: Theme; toggleTheme: () => void };\n\nconst ThemeContext = createContext<ThemeValue | null>(null);\n\nexport function ThemeProvider({ children }: { children: ReactNode }) {\n  const [theme, setTheme] = useState<Theme>(\"light\");\n  const toggleTheme = useCallback(() => setTheme((t) => (t === \"light\" ? \"dark\" : \"light\")), []);\n  // Memoised so consumers don''t re-render just because the provider did.\n  const value = useMemo(() => ({ theme, toggleTheme }), [theme, toggleTheme]);\n  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;\n}\n\nexport function useTheme(): ThemeValue {\n  const value = useContext(ThemeContext);\n  if (!value) throw new Error(\"useTheme must be used inside a <ThemeProvider>\");\n  return value;\n}\n"}'::jsonb),
  ('react-cart-reducer', null::text[], '{"en":"A reducer gathers every way the state can change into one pure function `(state, action) => newState`, so the logic lives outside the component, is easy to read as a list of cases, and can be unit-tested without rendering anything (the first four tests don''t touch the DOM). Components only describe *what happened* by dispatching actions such as `{ type: \"add\", product }`. As with `useState`, never mutate: `map` for per-line changes, `filter` to remove (this also implements \"decrement to zero removes the line\"), and spreads for new objects. Money is kept as integer cents and formatted only for display, which avoids floating-point surprises like `0.1 + 0.2`. When many distant components need the dispatch or state, the same reducer pairs naturally with context.","uk":"Редюсер збирає всі способи зміни стану в одну чисту функцію `(state, action) => newState`, тож логіка живе поза компонентом, добре читається як список випадків і тестується без рендеру (перші чотири тести не торкаються DOM). Компоненти лише описують, *що сталося*, відправляючи дії на кшталт `{ type: \"add\", product }`. Як і з `useState`, ніколи не мутуйте: `map` для змін окремого рядка, `filter` для видалення (він же реалізує \"зменшення до нуля видаляє рядок\") та spread для нових об''єктів. Гроші зберігаються як цілі центи й форматуються лише для показу, що уникає сюрпризів з плаваючою комою на кшталт `0.1 + 0.2`. Коли dispatch або стан потрібні багатьом віддаленим компонентам, той самий редюсер природно поєднується з контекстом."}'::jsonb, '{"/cartReducer.ts":"export type CartItem = { id: string; name: string; price: number; qty: number };\nexport type CartState = { items: CartItem[] };\n\nexport type CartAction =\n  | { type: \"add\"; product: { id: string; name: string; price: number } }\n  | { type: \"increment\"; id: string }\n  | { type: \"decrement\"; id: string }\n  | { type: \"remove\"; id: string }\n  | { type: \"clear\" };\n\nexport const initialCart: CartState = { items: [] };\n\nexport function cartReducer(state: CartState, action: CartAction): CartState {\n  switch (action.type) {\n    case \"add\": {\n      const exists = state.items.some((i) => i.id === action.product.id);\n      return {\n        items: exists\n          ? state.items.map((i) => (i.id === action.product.id ? { ...i, qty: i.qty + 1 } : i))\n          : [...state.items, { ...action.product, qty: 1 }],\n      };\n    }\n    case \"increment\":\n      return { items: state.items.map((i) => (i.id === action.id ? { ...i, qty: i.qty + 1 } : i)) };\n    case \"decrement\":\n      return {\n        items: state.items\n          .map((i) => (i.id === action.id ? { ...i, qty: i.qty - 1 } : i))\n          .filter((i) => i.qty > 0),\n      };\n    case \"remove\":\n      return { items: state.items.filter((i) => i.id !== action.id) };\n    case \"clear\":\n      return initialCart;\n    default:\n      return state;\n  }\n}\n\nexport function cartTotal(state: CartState): number {\n  return state.items.reduce((sum, i) => sum + i.price * i.qty, 0);\n}\n"}'::jsonb),
  ('react-memo-callback-rows', null::text[], '{"en":"By default a component re-renders whenever its parent does, even with identical props. `memo` makes React skip a component when all its props are shallowly equal to the previous render''s. That only works if the props are stable: `item` objects keep their identity because updates copy only the changed one, but an inline `toggle` function is a new object every render, so the check fails. `useCallback` keeps the same function between renders; reading the latest list via the updater form `setItems(current => ...)` lets it have an empty dependency array, so it never changes. Use this when profiling shows a real cost; memoisation isn''t free, and the React Compiler can add it automatically. Often the better fix is to move state down (the `note` input into its own component) so the expensive tree isn''t re-rendered at all.","uk":"За замовчуванням компонент ререндериться щоразу, коли ререндериться його батько, навіть з однаковими пропсами. `memo` змушує React пропустити компонент, коли всі його пропси поверхнево дорівнюють пропсам попереднього рендеру. Це працює лише зі стабільними пропсами: об''єкти `item` зберігають ідентичність, бо оновлення копіює лише змінений, але вбудована функція `toggle` щоразу новий об''єкт, і перевірка не проходить. `useCallback` зберігає ту саму функцію між рендерами; читання актуального списку через форму-оновлювач `setItems(current => ...)` дозволяє мати порожній масив залежностей, тож вона ніколи не змінюється. Застосовуйте це, коли профілювання показує реальну вартість; мемоізація не безкоштовна, а React Compiler може додавати її автоматично. Часто кращим виправленням є опустити стан нижче (поле `note` в окремий компонент), щоб дороге дерево взагалі не ререндерилося."}'::jsonb, '{"/Row.tsx":"import { memo } from \"react\";\n\nexport type Item = { id: number; label: string; done: boolean };\n\nexport const renders = { count: 0 };\n\n// memo skips re-rendering when every prop is shallowly equal to the last render''s.\nexport const Row = memo(function Row({ item, onToggle }: { item: Item; onToggle: (id: number) => void }) {\n  renders.count++;\n  return (\n    <li>\n      <label>\n        <input type=\"checkbox\" checked={item.done} onChange={() => onToggle(item.id)} /> {item.label}\n      </label>\n    </li>\n  );\n});\n","/App.tsx":"import { useCallback, useState } from \"react\";\nimport { Row, type Item } from \"./Row\";\n\nconst INITIAL: Item[] = Array.from({ length: 20 }, (_, i) => ({ id: i + 1, label: \"Task \" + (i + 1), done: false }));\n\nexport default function App() {\n  const [items, setItems] = useState(INITIAL);\n  const [note, setNote] = useState(\"\");\n\n  // Stable identity (no dependencies): the updater form reads the latest items itself.\n  const toggle = useCallback((id: number) => {\n    setItems((current) => current.map((it) => (it.id === id ? { ...it, done: !it.done } : it)));\n  }, []);\n\n  return (\n    <main>\n      <label htmlFor=\"note\">Note</label>\n      <input id=\"note\" value={note} onChange={(e) => setNote(e.target.value)} />\n      <ul>\n        {items.map((item) => (\n          <Row key={item.id} item={item} onToggle={toggle} />\n        ))}\n      </ul>\n    </main>\n  );\n}\n"}'::jsonb),
  ('react-online-status-effect', null::text[], '{"en":"Effects synchronise a component with something outside React, here the browser''s connectivity events. The effect sets the subscription up and returns a cleanup function that tears it down; React calls the cleanup on unmount and before re-running the effect. Without it every mount would add another listener that keeps calling `setOnline` on a component that no longer exists. The cleanup must remove the very same function references that were added, which is why the handlers are named constants rather than inline arrows created twice. In development, StrictMode deliberately mounts, cleans up and mounts again to expose missing cleanups. For subscribing to an external store, React also offers `useSyncExternalStore`, which handles tearing and server rendering for you.","uk":"Ефекти синхронізують компонент із чимось поза React, тут із подіями з''єднання браузера. Ефект налаштовує підписку й повертає функцію очищення, що її знімає; React викликає очищення при розмонтуванні та перед повторним запуском ефекту. Без цього кожне монтування додавало б ще одного слухача, який і далі викликав би `setOnline` на неіснуючому компоненті. Очищення має зняти саме ті самі посилання на функції, що були додані, тому обробники є іменованими константами, а не вбудованими стрілками, створеними двічі. У розробці StrictMode навмисно монтує, очищає й монтує знову, щоб виявити відсутні очищення. Для підписки на зовнішнє сховище React пропонує також `useSyncExternalStore`, що сам дбає про tearing і серверний рендеринг."}'::jsonb, '{"/useOnlineStatus.ts":"import { useEffect, useState } from \"react\";\n\nexport function useOnlineStatus(): boolean {\n  const [online, setOnline] = useState(() => navigator.onLine);\n\n  useEffect(() => {\n    const goOnline = () => setOnline(true);\n    const goOffline = () => setOnline(false);\n    window.addEventListener(\"online\", goOnline);\n    window.addEventListener(\"offline\", goOffline);\n    // Cleanup: runs on unmount (and before the effect re-runs), so no listener leaks.\n    return () => {\n      window.removeEventListener(\"online\", goOnline);\n      window.removeEventListener(\"offline\", goOffline);\n    };\n  }, []);\n\n  return online;\n}\n"}'::jsonb),
  ('react-state-snapshot', array['b']::text[], '{"en":"Both `setCount(count + 1)` calls read the same snapshot (`0`) and queue `1`. The updater function then receives the latest queued value (`1`) and returns `2`. Use updater functions when the next state depends on the previous one.","uk":"Обидва виклики `setCount(count + 1)` читають той самий знімок (`0`) і ставлять у чергу `1`. Функція-оновлювач отримує останнє значення в черзі (`1`) і повертає `2`. Використовуйте оновлювачі, коли новий стан залежить від попереднього."}'::jsonb, null::jsonb),
  ('react-keys-index', array['b']::text[], '{"en":"Keys identify items across renders. After an insertion at the top, every index points at a different item, so React keeps the old component instances (with their state and uncontrolled input values) under the wrong data. Use a stable unique ID.","uk":"Ключі ідентифікують елементи між рендерами. Після вставки згори кожен індекс вказує на інший елемент, тож React зберігає старі екземпляри компонентів (з їхнім станом і значеннями некерованих полів) під хибними даними. Використовуйте стабільний унікальний ID."}'::jsonb, null::jsonb),
  ('react-effect-cleanup', array['a', 'b']::text[], '{"en":"Cleanup runs before the next execution of the effect (when a dependency changed) and once on unmount. In development, Strict Mode also runs an extra mount→cleanup→mount cycle to surface missing cleanups.","uk":"Очищення виконується перед наступним запуском ефекту (коли змінилася залежність) і один раз при демонтуванні. У розробці Strict Mode також робить додатковий цикл mount→cleanup→mount, щоб виявити відсутні очищення."}'::jsonb, null::jsonb),
  ('react-derived-state', array['a']::text[], '{"en":"`visible` is derived from props/state, so storing it in state creates a second source of truth and an extra render (render → effect → setState → render). Compute it during render instead.","uk":"`visible` є похідним від пропсів/стану, тож зберігання його в стані створює друге джерело правди й зайвий рендер (render → effect → setState → render). Обчислюйте його під час рендеру."}'::jsonb, null::jsonb),
  ('react-memo-callback', array['a']::text[], '{"en":"`memo` compares props shallowly. An inline arrow function creates a new identity every render, so the comparison fails. `useCallback` keeps the same function between renders while its dependencies are unchanged.","uk":"`memo` порівнює пропси поверхнево. Вбудована стрілкова функція щоразу створює нову ідентичність, тож порівняння не проходить. `useCallback` зберігає ту саму функцію між рендерами, поки залежності не змінилися."}'::jsonb, null::jsonb),
  ('react-searchable-list', null::text[], '{"en":"Keep only `query` in state and derive `visible` during render. A `<label htmlFor>` connected to the input''s `id` gives it an accessible name, which is also how the tests find it. Render the empty state conditionally.","uk":"Зберігайте у стані лише `query`, а `visible` обчислюйте під час рендеру. `<label htmlFor>`, пов''язаний з `id` поля, дає йому доступне ім''я, за яким його знаходять і тести. Порожній стан рендерте умовно."}'::jsonb, '{"/App.tsx":"import { useState } from \"react\";\n\nexport const FRUITS = [\"Apple\", \"Apricot\", \"Banana\", \"Cherry\", \"Grape\", \"Mango\"];\n\nexport default function App() {\n  const [query, setQuery] = useState(\"\");\n  const q = query.trim().toLowerCase();\n  const visible = FRUITS.filter((f) => f.toLowerCase().includes(q));\n\n  return (\n    <main>\n      <h1>Fruits</h1>\n      <label htmlFor=\"search\">Search</label>\n      <input id=\"search\" value={query} onChange={(e) => setQuery(e.target.value)} />\n      <p data-testid=\"count\">\n        {visible.length} of {FRUITS.length}\n      </p>\n      {visible.length ? (\n        <ul>\n          {visible.map((f) => (\n            <li key={f}>{f}</li>\n          ))}\n        </ul>\n      ) : (\n        <p>No results</p>\n      )}\n    </main>\n  );\n}\n"}'::jsonb),
  ('rec-frame-count', array['b']::text[], '{"en":"`factorial(4)` calls `factorial(3)`, then 2, then 1, which hits the base case. Each call waits for the next one, so 4 frames are stacked at the deepest point. Stack depth grows linearly with `n`, which is why very large inputs overflow.","uk":"`factorial(4)` викликає `factorial(3)`, потім 2, потім 1, що досягає базового випадку. Кожен виклик чекає на наступний, тож у найглибшій точці в стеку 4 кадри. Глибина стеку зростає лінійно з `n`, тому дуже великі вхідні дані його переповнюють."}'::jsonb, null::jsonb),
  ('rec-tail-calls', array['b']::text[], '{"en":"ES2015 specifies proper tail calls in strict mode, but V8 (Chrome, Node.js) and Firefox never shipped them; only Safari''s JavaScriptCore does. Each call still uses a stack frame, so a million calls overflow. Rewrite deep recursion as a loop, use an explicit stack, or use a trampoline.","uk":"ES2015 визначає оптимізацію хвостових викликів у строгому режимі, але V8 (Chrome, Node.js) і Firefox її так і не впровадили; лише JavaScriptCore у Safari. Кожен виклик досі займає кадр стеку, тож мільйон викликів переповнює стек. Перепишіть глибоку рекурсію циклом, використайте явний стек або трамплін."}'::jsonb, null::jsonb),
  ('rec-trampoline', array['b']::text[], '{"en":"Instead of recursing, each step returns a function describing the next step. The `while` loop calls these thunks one after another, so only one frame is on the stack at a time and depth no longer depends on `n`. The cost is an allocation per step, and results that are themselves functions need a different marker.","uk":"Замість рекурсії кожен крок повертає функцію, що описує наступний крок. Цикл `while` викликає ці thunk-и по черзі, тож у стеку одночасно лише один кадр, і глибина не залежить від `n`. Ціна — одна алокація на крок, а результатам, що самі є функціями, потрібен інший маркер."}'::jsonb, null::jsonb),
  ('rec-unique-permutations', null::text[], '{"en":"Backtracking fills one position per recursion level: mark an unused item, recurse, then undo the choice. A `Set` of values already tried **at this level** prunes duplicate branches before they are explored, so equal values never start two identical subtrees. There are n!/(k₁!·k₂!·…) results, each copied in O(n).","uk":"Пошук із поверненням заповнює одну позицію на кожному рівні рекурсії: позначити невикористаний елемент, рекурсивно продовжити, потім скасувати вибір. `Set` значень, уже випробуваних **на цьому рівні**, відсікає дубльовані гілки ще до їх обходу, тож рівні значення ніколи не породжують два однакові піддерева. Результатів n!/(k₁!·k₂!·…), кожен копіюється за O(n)."}'::jsonb, '{"/src/permutations.ts":"export function permutations<T>(items: T[]): T[][] {\n  const result: T[][] = [];\n  const used = new Array<boolean>(items.length).fill(false);\n  const current: T[] = [];\n\n  const build = () => {\n    if (current.length === items.length) {\n      result.push([...current]);\n      return;\n    }\n    const triedHere = new Set<T>();\n    for (let i = 0; i < items.length; i++) {\n      if (used[i] || triedHere.has(items[i])) continue;\n      triedHere.add(items[i]);\n      used[i] = true;\n      current.push(items[i]);\n      build();\n      current.pop();\n      used[i] = false;\n    }\n  };\n\n  build();\n  return result;\n}\n"}'::jsonb),
  ('rec-base-case', array['b']::text[], '{"en":"There is no base case, so every call recurses again and the call stack overflows. Add `if (n < 0) return;` before the recursive call.","uk":"Базового випадку немає, тож кожен виклик знову рекурсує, і стек викликів переповнюється. Додайте `if (n < 0) return;` перед рекурсивним викликом."}'::jsonb, null::jsonb),
  ('rec-fib-complexity', array['c']::text[], '{"en":"Each call spawns two more and the same sub-problems are recomputed many times, so the number of calls grows exponentially (≈ φⁿ). Memoisation or a bottom-up loop brings it down to O(n).","uk":"Кожен виклик породжує ще два, а ті самі підзадачі обчислюються багато разів, тож кількість викликів зростає експоненційно (≈ φⁿ). Мемоізація або цикл «знизу вгору» знижує складність до O(n)."}'::jsonb, null::jsonb),
  ('rec-stack-depth', array['a']::text[], '{"en":"Each recursive call consumes a stack frame, and engines cap the depth (typically ~10k). Proper tail calls are in the spec but only Safari ships them, so don''t rely on them. An iterative loop uses constant stack space.","uk":"Кожен рекурсивний виклик займає кадр стеку, а рушії обмежують глибину (зазвичай ~10 тис.). Правильні хвостові виклики є в специфікації, але реалізовані лише в Safari, тож покладатися на них не варто. Ітеративний цикл використовує сталий обсяг стеку."}'::jsonb, null::jsonb),
  ('rec-subsets-count', array['c']::text[], '{"en":"Each item is either in or out of a subset, so there are 2ⁿ subsets: 2²⁰ = 1,048,576. Permutations would be n! (option D), which is astronomically larger.","uk":"Кожен елемент або входить до підмножини, або ні, тож підмножин 2ⁿ: 2²⁰ = 1 048 576. Перестановок було б n! (варіант D), що астрономічно більше."}'::jsonb, null::jsonb),
  ('rec-tree-traversal', array['b']::text[], '{"en":"In a BST every value in the left subtree is smaller and every value in the right subtree is larger. Visiting left, then the node, then right yields sorted output.","uk":"У BST усі значення лівого піддерева менші, а правого більші. Обхід «ліве, вузол, праве» дає відсортований вивід."}'::jsonb, null::jsonb),
  ('rec-flatten-depth', null::text[], '{"en":"Walk the array. When an item is an array and there is depth left, recurse with `depth - 1` and append its result; otherwise append the item as is. The base case is implicit: a call on an array without nested arrays (or with depth 0) just copies its items.","uk":"Пройдіть масив. Якщо елемент є масивом і глибина ще лишилася, рекурсивно викличте функцію з `depth - 1` і додайте її результат; інакше додайте елемент як є. Базовий випадок неявний: виклик на масиві без вкладених масивів (або з глибиною 0) просто копіює елементи."}'::jsonb, '{"/src/flatten.js":"export function flatten(array, depth = Infinity) {\n  const out = [];\n  for (const item of array) {\n    if (Array.isArray(item) && depth > 0) {\n      for (const inner of flatten(item, depth - 1)) out.push(inner);\n    } else {\n      out.push(item);\n    }\n  }\n  return out;\n}\n"}'::jsonb),
  ('redux-three-principles', array['d']::text[], '{"en":"Redux is built on a single source of truth, read-only state changed through actions, and pure reducers. Private copies of shared state are exactly the drift Redux is meant to prevent; components read the store through selectors instead.","uk":"Redux спирається на єдине джерело правди, стан лише для читання, що змінюється через дії, і чисті редʼюсери. Приватні копії спільного стану призводять саме до розбіжностей, яким Redux має запобігати; компоненти читають стор через селектори."}'::jsonb, null::jsonb),
  ('redux-immer-return', array['a']::text[], '{"en":"With Immer you either mutate the `state` draft (and return nothing) or return a brand-new state. Doing both is ambiguous, so Immer throws. Write `reset: () => ({ items: [], loading: false })` or only mutate the draft.","uk":"З Immer ви або змінюєте чернетку `state` (і нічого не повертаєте), або повертаєте зовсім новий стан. Обидва варіанти разом неоднозначні, тож Immer кидає помилку. Пишіть `reset: () => ({ items: [], loading: false })` або лише змінюйте чернетку."}'::jsonb, null::jsonb),
  ('redux-vs-context', array['a']::text[], '{"en":"Context is a transport: any change to the provided value re-renders every `useContext` consumer, even those that only use one field. `useSelector` subscribes to the store and compares only the selected slice with `===`, so unrelated updates are skipped.","uk":"Context є лише способом передачі: будь-яка зміна значення перерендерює всіх споживачів `useContext`, навіть тих, що використовують одне поле. `useSelector` підписується на стор і порівнює через `===` лише вибрану частину, тож непов''язані оновлення пропускаються."}'::jsonb, null::jsonb),
  ('redux-selector-new-object', array['a']::text[], '{"en":"`useSelector` compares the result with `===`. An object literal is a new reference on every call, so every store update looks like a change. Use two selectors (`useSelector(s => s.user.name)`), `useSelector(fn, shallowEqual)`, or a memoised `createSelector`. `React.memo` doesn''t help: the re-render comes from the hook, not from props.","uk":"`useSelector` порівнює результат через `===`. Літерал об''єкта є новим посиланням при кожному виклику, тож кожне оновлення стору виглядає як зміна. Використайте два селектори (`useSelector(s => s.user.name)`), `useSelector(fn, shallowEqual)` або мемоізований `createSelector`. `React.memo` не допоможе: рендер спричиняє хук, а не пропси."}'::jsonb, null::jsonb),
  ('redux-middleware-order', array['a']::text[], '{"en":"Middlewares compose like an onion: the first one wraps the second, which wraps the real dispatch. Each runs its code before `next(action)` on the way in, and its code after `next` on the way out, in reverse order.","uk":"Middleware складаються як цибулина: перший обгортає другий, а той обгортає справжній dispatch. Кожен виконує код перед `next(action)` на шляху всередину і код після `next` на шляху назовні, у зворотному порядку."}'::jsonb, null::jsonb),
  ('redux-thunk-mechanics', array['a']::text[], '{"en":"The whole middleware is a few lines: `({ dispatch, getState }) => next => action => typeof action === ''function'' ? action(dispatch, getState) : next(action)`. Reducers stay pure and synchronous; the async work happens in the thunk, which dispatches plain actions when it''s done.","uk":"Увесь middleware займає кілька рядків: `({ dispatch, getState }) => next => action => typeof action === ''function'' ? action(dispatch, getState) : next(action)`. Редʼюсери лишаються чистими й синхронними; асинхронна робота відбувається в thunk, який після завершення надсилає звичайні дії."}'::jsonb, null::jsonb),
  ('redux-combine-identity', array['a']::text[], '{"en":"`combineReducers` tracks whether any slice returned a different reference. If none did, it returns the previous state object, so subscribers and `useSelector` can skip work. That only holds if every slice reducer returns its own state unchanged for actions it ignores.","uk":"`combineReducers` відстежує, чи повернув якийсь слайс інше посилання. Якщо ні, він повертає попередній об''єкт стану, і підписники та `useSelector` можуть пропустити роботу. Це працює, лише якщо кожен редʼюсер слайсу повертає власний стан без змін для дій, які ігнорує."}'::jsonb, null::jsonb),
  ('redux-async-race', array['a', 'c']::text[], '{"en":"Responses can arrive in any order, so the reducer must know which request is current. `createAsyncThunk` gives every call a `meta.requestId` you can compare, and the dispatched promise has `.abort()`, which sends an `AbortSignal` to your payload creator (pass it to `fetch`). RTK Query and `switchMap` in RxJS solve the same race. Reducers can never be async.","uk":"Відповіді можуть приходити в будь-якому порядку, тож редʼюсер має знати, який запит актуальний. `createAsyncThunk` дає кожному виклику `meta.requestId` для порівняння, а надісланий проміс має `.abort()`, що передає `AbortSignal` у ваш payload creator (передайте його у `fetch`). RTK Query і `switchMap` у RxJS розв''язують ту саму гонку. Редʼюсери ніколи не бувають асинхронними."}'::jsonb, null::jsonb),
  ('redux-mini-store', null::text[], '{"en":"The store is a closure over `state` and a listener list. Initial state comes from running the reducer once with an internal action. Notifying a copy of the listener array means (un)subscribing mid-dispatch can''t skip anyone. `combineReducers` runs every slice and keeps the previous object unless at least one slice returned a new reference, which is what makes `===` checks downstream cheap.","uk":"Стор є замиканням над `state` і списком підписників. Початковий стан отримуємо, один раз запустивши редʼюсер із внутрішньою дією. Сповіщення копії масиву підписників означає, що відписка під час dispatch нікого не пропустить. `combineReducers` запускає кожен слайс і зберігає попередній об''єкт, якщо жоден слайс не повернув нове посилання; саме це робить перевірки `===` далі дешевими."}'::jsonb, '{"/src/store.ts":"export type Action = { type: string; [key: string]: unknown };\nexport type Reducer<S> = (state: S | undefined, action: Action) => S;\nexport type Store<S> = {\n  getState(): S;\n  dispatch(action: Action): Action;\n  subscribe(listener: () => void): () => void;\n};\n\nexport function createStore<S>(reducer: Reducer<S>, preloadedState?: S): Store<S> {\n  let state = preloadedState as S;\n  let listeners: (() => void)[] = [];\n\n  function dispatch(action: Action) {\n    if (typeof action !== \"object\" || action === null || typeof action.type !== \"string\") {\n      throw new Error(\"Actions must be plain objects with a string type\");\n    }\n    state = reducer(state, action);\n    // Snapshot, so (un)subscribing inside a listener doesn''t affect this notification round.\n    for (const listener of [...listeners]) listener();\n    return action;\n  }\n\n  function subscribe(listener: () => void) {\n    listeners.push(listener);\n    let active = true;\n    return () => {\n      if (!active) return;\n      active = false;\n      listeners = listeners.filter((l) => l !== listener);\n    };\n  }\n\n  // Let every reducer fill in its initial state.\n  dispatch({ type: \"@@redux/INIT\" });\n  return { getState: () => state, dispatch, subscribe };\n}\n\nexport function combineReducers<S extends Record<string, unknown>>(reducers: { [K in keyof S]: Reducer<S[K]> }): Reducer<S> {\n  const keys = Object.keys(reducers) as (keyof S)[];\n  return (state, action) => {\n    const prev = (state ?? {}) as S;\n    let changed = state === undefined;\n    const next = {} as S;\n    for (const key of keys) {\n      next[key] = reducers[key](prev[key], action);\n      if (next[key] !== prev[key]) changed = true;\n    }\n    return changed ? next : prev;\n  };\n}\n"}'::jsonb),
  ('redux-thunk-middleware', null::text[], '{"en":"`reduceRight` composes the chain so the first middleware wraps all the others and the innermost `next` is the store''s real `dispatch`. Middlewares receive a `dispatch` that forwards to the final composed function, so actions dispatched from a thunk pass through the logger too. Thunk is a type check; the logger reads state before and after calling `next`.","uk":"`reduceRight` компонує ланцюжок так, що перший middleware обгортає всі інші, а найглибший `next` є справжнім `dispatch` стору. Middleware отримують `dispatch`, який перенаправляє до остаточної скомпонованої функції, тож дії, надіслані з thunk, теж проходять крізь logger. Thunk є лише перевіркою типу; logger читає стан до і після виклику `next`."}'::jsonb, '{"/src/middleware.ts":"import type { Store } from \"./store\";\n\nexport type MiddlewareAPI<S> = { getState(): S; dispatch(action: any): any };\nexport type Middleware<S> = (api: MiddlewareAPI<S>) => (next: (action: any) => any) => (action: any) => any;\n\nexport function applyMiddleware<S>(store: Store<S>, ...middlewares: Middleware<S>[]): Store<S> {\n  let dispatch: (action: any) => any = () => {\n    throw new Error(\"Dispatching while constructing middleware is not allowed\");\n  };\n  // Middlewares get a dispatch that always goes through the whole chain (needed by thunks).\n  const api: MiddlewareAPI<S> = { getState: store.getState, dispatch: (action) => dispatch(action) };\n  const chain = middlewares.map((m) => m(api));\n  dispatch = chain.reduceRight<(action: any) => any>((next, mw) => mw(next), store.dispatch);\n  return { ...store, dispatch };\n}\n\nexport const thunk: Middleware<any> =\n  ({ dispatch, getState }) =>\n  (next) =>\n  (action) =>\n    typeof action === \"function\" ? action(dispatch, getState) : next(action);\n\nexport function createLogger(log: (line: string) => void): Middleware<any> {\n  return ({ getState }) =>\n    (next) =>\n    (action) => {\n      const before = getState();\n      const result = next(action);\n      log(action.type + \": \" + JSON.stringify(before) + \" -> \" + JSON.stringify(getState()));\n      return result;\n    };\n}\n"}'::jsonb),
  ('regex-anchors', array['a']::text[], '{"en":"`^` and `$` anchor the pattern to the start and end of the input, so `/^\\d{3}$/` matches exactly three digits and rejects `\"1234\"`. Without anchors, `/\\d{3}/` finds three digits anywhere, so it matches inside `\"1234\"`. Forgetting anchors is the most common validation bug.","uk":"`^` і `$` прив''язують шаблон до початку й кінця вхідних даних, тож `/^\\d{3}$/` відповідає рівно трьом цифрам і відхиляє `\"1234\"`. Без якорів `/\\d{3}/` знаходить три цифри будь-де, тож збігається всередині `\"1234\"`. Забуті якорі є найпоширенішим багом валідації."}'::jsonb, null::jsonb),
  ('regex-greedy-lazy', array['a']::text[], '{"en":"`.*` is greedy: it runs to the end of the string and backtracks only as far as needed to match the final `</b>`, which is the last one. `.*?` is lazy: it extends one character at a time and stops at the first `</b>`. `[^<]*` is often clearer and faster than a lazy dot.","uk":"`.*` жадібний: доходить до кінця рядка й відступає лише настільки, щоб збігся завершальний `</b>`, тобто останній. `.*?` лінивий: розширюється по одному символу й зупиняється на першому `</b>`. `[^<]*` часто зрозуміліший і швидший за ліниву крапку."}'::jsonb, null::jsonb),
  ('regex-lastindex', array['a']::text[], '{"en":"With the `g` flag, `test` starts searching at `re.lastIndex` and updates it. After the first match `lastIndex` is 1, so the second search starts past the end of `\"a\"`, fails, and resets `lastIndex` to 0, so the third call succeeds again. Don''t use `g` with `test` on a shared regex.","uk":"З прапорцем `g` метод `test` починає пошук із `re.lastIndex` і оновлює його. Після першого збігу `lastIndex` дорівнює 1, тож другий пошук починається за кінцем `\"a\"`, не вдається й скидає `lastIndex` до 0, тож третій виклик знову успішний. Не використовуйте `g` з `test` для спільного регулярного виразу."}'::jsonb, null::jsonb),
  ('regex-named-replace', array['a']::text[], '{"en":"`(?<name>…)` names a capture group, and `$<name>` inserts it in the replacement string (`$1`, `$2` work for numbered groups). Names make patterns self-documenting and survive reordering. For logic, pass a function: `(match, …groups) => …`.","uk":"`(?<name>…)` дає назву групі із захопленням, а `$<name>` вставляє її в рядок заміни (для нумерованих груп працюють `$1`, `$2`). Назви роблять шаблони самодокументованими й не ламаються при перестановці. Для логіки передавайте функцію: `(match, …groups) => …`."}'::jsonb, null::jsonb),
  ('regex-match-global', array['a']::text[], '{"en":"With `g`, `match` returns every full match but no groups. Without `g`, it returns the first match as an array of `[fullMatch, group1, group2, …]` (plus `index` and `groups`), so `.slice(1)` gives the captures. Use `matchAll` when you need all matches **with** their groups.","uk":"З `g` метод `match` повертає всі повні збіги, але без груп. Без `g` він повертає перший збіг як масив `[повний збіг, група1, група2, …]` (плюс `index` і `groups`), тож `.slice(1)` дає захоплення. Використовуйте `matchAll`, коли потрібні всі збіги **разом** із групами."}'::jsonb, null::jsonb),
  ('regex-user-input', array['a']::text[], '{"en":"`new RegExp(text)` parses the text as a pattern: `+` after `+` has nothing to repeat, so it throws, and `.` matches any character, so `\"a.b\"` matches `\"axb\"`. Always escape user input first (`s.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\")`), or use string methods like `includes` when you don''t need patterns.","uk":"`new RegExp(text)` розбирає текст як шаблон: `+` після `+` не має що повторювати, тож кидається помилка, а `.` відповідає будь-якому символу, тож `\"a.b\"` збігається з `\"axb\"`. Завжди спершу екрануйте дані користувача (`s.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\")`) або використовуйте рядкові методи на кшталт `includes`, коли шаблони не потрібні."}'::jsonb, null::jsonb),
  ('regex-lookahead', array['a']::text[], '{"en":"Each `(?=…)` checks a condition from the start without consuming characters: at least one digit, one lowercase and one uppercase letter; then `.{8,}$` requires 8+ characters. `password` has no digit or uppercase, `PASSWORD1` has no lowercase, and `Pass1` is too short. For real forms, separate checks give better error messages than one regex.","uk":"Кожна `(?=…)` перевіряє умову з початку, не споживаючи символів: щонайменше одна цифра, одна мала й одна велика літера; потім `.{8,}$` вимагає 8+ символів. У `password` немає цифри й великої літери, у `PASSWORD1` немає малої, а `Pass1` закороткий. У реальних формах окремі перевірки дають кращі повідомлення про помилки, ніж один вираз."}'::jsonb, null::jsonb),
  ('regex-unicode', array['a']::text[], '{"en":"JavaScript strings are UTF-16, and 😀 is a surrogate pair: length 2, and a plain `.` matches only half of it. The `u` flag makes the regex work on code points, so `.` matches the whole emoji, and it enables property escapes like `\\p{L}` (any letter in any script, including Cyrillic).","uk":"Рядки JavaScript є UTF-16, а 😀 є сурогатною парою: довжина 2, а звичайна `.` відповідає лише половині. Прапорець `u` змушує вираз працювати з кодовими точками, тож `.` відповідає всьому емодзі, і вмикає екранування властивостей на кшталт `\\p{L}` (будь-яка літера будь-якої писемності, зокрема кирилиця)."}'::jsonb, null::jsonb),
  ('regex-redos', array['a']::text[], '{"en":"On a failing input, a backtracking engine tries every way of dividing `aaaa…` into `(\\w+\\s?)` repetitions, and that number grows exponentially with the length. With user-controlled input this is a ReDoS vulnerability. Rewrite without nested or overlapping quantifiers (`/^\\w+(\\s\\w+)*$/`), cap input length, or validate in steps.","uk":"На вхідних даних без збігу рушій із бектрекінгом перебирає всі способи поділити `aaaa…` на повторення `(\\w+\\s?)`, і їхня кількість зростає експоненційно з довжиною. З даними, які контролює користувач, це вразливість ReDoS. Перепишіть без вкладених чи перекривних квантифікаторів (`/^\\w+(\\s\\w+)*$/`), обмежте довжину або перевіряйте поетапно."}'::jsonb, null::jsonb),
  ('regex-search-query', null::text[], '{"en":"One pattern does the work: `(?<=^|\\s)` and `(?=\\s|$)` make a filter a complete token, `[a-z][\\w-]*` keeps times like `10:30` out, and the alternation `\"(?<quoted>[^\"]*)\"|(?<bare>[^\\s\"]+)` handles both value styles (an unclosed quote matches neither). `matchAll` with named groups collects the filters, and `replace` with the same global regex removes them to leave the free text.","uk":"Усю роботу робить один шаблон: `(?<=^|\\s)` і `(?=\\s|$)` роблять фільтр цілим токеном, `[a-z][\\w-]*` не пропускає час на кшталт `10:30`, а альтернатива `\"(?<quoted>[^\"]*)\"|(?<bare>[^\\s\"]+)` обробляє обидва види значень (незакриті лапки не збігаються з жодним). `matchAll` з іменованими групами збирає фільтри, а `replace` з тим самим глобальним виразом прибирає їх, лишаючи вільний текст."}'::jsonb, '{"/src/query.ts":"export type ParsedQuery = { filters: Record<string, string[]>; text: string };\n\n// key:value or key:\"quoted value\", as a whole whitespace-separated token. Keys start with a letter.\nconst FILTER = /(?<=^|\\s)(?<key>[a-z][\\w-]*):(?:\"(?<quoted>[^\"]*)\"|(?<bare>[^\\s\"]+))(?=\\s|$)/gi;\n\nexport function parseQuery(input: string): ParsedQuery {\n  const filters: Record<string, string[]> = {};\n  for (const match of input.matchAll(FILTER)) {\n    const key = match.groups!.key.toLowerCase();\n    const value = match.groups!.quoted ?? match.groups!.bare;\n    (filters[key] ??= []).push(value);\n  }\n  const text = input.replace(FILTER, \" \").replace(/\\s+/g, \" \").trim();\n  return { filters, text };\n}\n"}'::jsonb),
  ('regex-highlight', null::text[], '{"en":"Escaping turns user text into a literal pattern, so `c++` neither throws nor matches unexpected strings. Sorting words by length makes the alternation try `javascript` before `java` at each position. Walking the matches with `matchAll` and escaping the text between and inside them builds the HTML piece by piece, so neither the text nor the query can inject markup.","uk":"Екранування перетворює текст користувача на буквальний шаблон, тож `c++` не кидає помилку й не збігається з несподіваними рядками. Сортування слів за довжиною змушує альтернативу пробувати `javascript` раніше за `java` на кожній позиції. Прохід збігами через `matchAll` з екрануванням тексту між ними й усередині будує HTML частинами, тож ні текст, ні запит не можуть вставити розмітку."}'::jsonb, '{"/src/highlight.ts":"export function escapeRegExp(s: string): string {\n  return s.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n}\n\nconst HTML_ESCAPES: Record<string, string> = { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", ''\"'': \"&quot;\", \"''\": \"&#39;\" };\nconst escapeHtml = (s: string) => s.replace(/[&<>\"'']/g, (c) => HTML_ESCAPES[c]);\n\nexport function highlight(text: string, query: string): string {\n  // Longest words first, so \"javascript\" wins over \"java\" at the same position.\n  const words = query.split(/\\s+/).filter(Boolean).sort((a, b) => b.length - a.length);\n  if (!words.length) return escapeHtml(text);\n  const re = new RegExp(words.map(escapeRegExp).join(\"|\"), \"gi\");\n  let out = \"\";\n  let last = 0;\n  for (const match of text.matchAll(re)) {\n    const start = match.index!;\n    out += escapeHtml(text.slice(last, start)) + \"<mark>\" + escapeHtml(match[0]) + \"</mark>\";\n    last = start + match[0].length;\n  }\n  return out + escapeHtml(text.slice(last));\n}\n"}'::jsonb),
  ('rd-container-queries', array['b']::text[], '{"en":"A media query knows only the viewport, so the same card would stay horizontal in a narrow sidebar on a wide screen. A container query (`@container` on the parent, `@container (min-width: …)` in the card) measures the component''s own space, which makes components reusable in any layout.","uk":"Медіазапит знає лише вікно браузера, тож та сама картка залишалася б горизонтальною у вузькому сайдбарі на широкому екрані. Container query (`@container` на батьківському елементі, `@container (min-width: …)` у картці) вимірює власний простір компонента, тож компоненти можна використовувати в будь-якому макеті."}'::jsonb, null::jsonb),
  ('rd-fluid-type', array['a']::text[], '{"en":"`clamp(min, preferred, max)` sets a value that follows the preferred size (here, 4% of the viewport width) but never drops below the minimum or rises above the maximum. A single declaration does the work of several breakpoints, and it scales with the user''s browser settings where `rem` is used.","uk":"`clamp(min, preferred, max)` задає значення, яке слідує за бажаним розміром (тут 4% ширини вікна), але ніколи не опускається нижче мінімуму чи не піднімається вище максимуму. Одна декларація робить роботу кількох брейкпоінтів, а використання `rem` масштабується разом з налаштуваннями браузера користувача."}'::jsonb, null::jsonb),
  ('rwd-viewport-meta', array['a']::text[], '{"en":"Without the viewport tag, mobile browsers lay the page out at a virtual width of about 980 px and scale it down, so `min-width`/`max-width` queries see a \"desktop\" width. `width=device-width` makes the layout viewport match the screen. Never add `user-scalable=no`: it blocks zooming, which users with low vision rely on.","uk":"Без теґу viewport мобільні браузери розкладають сторінку на віртуальній ширині близько 980 px і зменшують її, тож запити `min-width`/`max-width` бачать «десктопну» ширину. `width=device-width` вирівнює вікно розмітки з екраном. Ніколи не додавайте `user-scalable=no`: це блокує масштабування, на яке покладаються люди зі слабким зором."}'::jsonb, null::jsonb),
  ('rwd-mobile-first-cascade', array['a']::text[], '{"en":"48rem is 768px and 64rem is 1024px. At 900px only the first `min-width` query matches, so `flex` overrides the base `none`; the `grid` rule starts at 1024px. In mobile-first CSS the base styles are for the smallest screens, and each `min-width` query layers on as space grows.","uk":"48rem дорівнює 768px, а 64rem дорівнює 1024px. На 900px спрацьовує лише перший запит `min-width`, тож `flex` перекриває базове `none`; правило `grid` починається з 1024px. У CSS за принципом mobile-first базові стилі призначені для найменших екранів, а кожен запит `min-width` додає шар із появою місця."}'::jsonb, null::jsonb),
  ('rwd-srcset-choice', array['a']::text[], '{"en":"`sizes` says the image is displayed at `100vw` below 64rem, i.e. 400 CSS px. At DPR 2 that needs about 800 device pixels, so the browser picks the smallest candidate that covers it: the 800w file. `src` is only the fallback for browsers without `srcset`, and only one file is downloaded.","uk":"`sizes` каже, що нижче 64rem зображення показується на `100vw`, тобто 400 CSS px. За щільності 2 це близько 800 фізичних пікселів, тож браузер обирає найменший варіант, якого достатньо: файл 800w. `src` є лише запасним варіантом для браузерів без `srcset`, а завантажується лише один файл."}'::jsonb, null::jsonb),
  ('rwd-container-queries', array['a']::text[], '{"en":"Media queries only know the viewport, so the same card would switch layouts in both places at once. Container queries let a component respond to the size of its container, which makes it reusable anywhere. JavaScript listeners work but are heavier and run after layout; `vw` is still viewport-relative.","uk":"Медіазапити знають лише вікно перегляду, тож та сама картка перемикалася б в обох місцях одночасно. Контейнерні запити дають компоненту реагувати на розмір його контейнера, що робить його придатним будь-де. Слухачі на JavaScript працюють, але важчі й спрацьовують після розкладки; `vw` усе одно залежить від вікна."}'::jsonb, null::jsonb),
  ('rwd-dvh', array['a']::text[], '{"en":"On mobile, `100vh` equals the largest viewport (with the address bar hidden), so content is cut off while the bar is visible. `dvh` follows the currently visible height; `svh` and `lvh` give the smallest and largest. `100%` depends on every ancestor having a height, and hiding overflow just hides the problem.","uk":"На мобільних `100vh` дорівнює найбільшому вікну (з прихованим адресним рядком), тож вміст обрізається, поки рядок видно. `dvh` відповідає поточній видимій висоті; `svh` і `lvh` дають найменшу й найбільшу. `100%` залежить від висоти кожного предка, а приховування переповнення лише ховає проблему."}'::jsonb, null::jsonb),
  ('rwd-auto-fill-fit', array['a']::text[], '{"en":"Both create as many 200px+ tracks as fit (six here). With `auto-fill`, the four unused tracks still exist and take their share of the `1fr`, so items stay narrow. `auto-fit` collapses empty tracks to zero, so the two items expand. Use `auto-fill` to keep a consistent column size, `auto-fit` to let few items fill the row.","uk":"Обидва створюють стільки стовпців від 200px, скільки вміщається (тут шість). З `auto-fill` чотири невикористані стовпці все одно існують і забирають свою частку `1fr`, тож елементи лишаються вузькими. `auto-fit` згортає порожні стовпці до нуля, тож два елементи розширюються. Використовуйте `auto-fill` для сталого розміру стовпців, а `auto-fit`, щоб кілька елементів заповнювали рядок."}'::jsonb, null::jsonb),
  ('rwd-rem-breakpoints', array['a']::text[], '{"en":"In media queries `rem`/`em` are based on the browser''s default font size (not your CSS). If a user sets 20px text, `48rem` becomes 960px, so layouts switch to fewer columns before text gets cramped. `px` breakpoints ignore that preference. Both units work fine on high-DPI screens because CSS pixels are already density-independent.","uk":"У медіазапитах `rem`/`em` спираються на типовий розмір шрифту браузера (а не на ваш CSS). Якщо користувач обрав текст 20px, `48rem` стає 960px, тож макет переходить на меншу кількість стовпців раніше, ніж текст стане тісним. Контрольні точки в `px` ігнорують це налаштування. Обидві одиниці добре працюють на екранах з високою щільністю, бо CSS-пікселі й так не залежать від щільності."}'::jsonb, null::jsonb),
  ('rest-created-status', array['b']::text[], '{"en":"`201 Created` says a resource now exists, and the `Location` header tells the client where to find it. `200` is for a plain success, `204` means success with no body, and `302` is a redirect for the browser, which is not what an API creating data should answer with.","uk":"`201 Created` каже, що ресурс тепер існує, а заголовок `Location` підказує клієнту, де його шукати. `200` — звичайний успіх, `204` означає успіх без тіла, а `302` — перенаправлення для браузера, чим API, що створює дані, відповідати не повинен."}'::jsonb, null::jsonb),
  ('rest-safe-idempotent', array['a']::text[], '{"en":"Safe means the request doesn''t change server state, and idempotent means repeating it gives the same result as doing it once. GET is both. DELETE is idempotent but not safe, and PATCH and POST are neither in general, which is why retrying them needs an idempotency key.","uk":"Безпечний означає, що запит не змінює стан сервера, а ідемпотентний — що повтор дає той самий результат, що й одноразове виконання. GET є обома. DELETE ідемпотентний, але не безпечний, а PATCH і POST загалом не є жодним з них, тому повтори для них потребують ключа ідемпотентності."}'::jsonb, null::jsonb),
  ('rest-problem-details', null::text[], '{"en":"RFC 9457 (which replaces RFC 7807) standardises the error body: a machine-readable `type`, a human `title`, the `status`, and optional `detail`, `instance` and extension members like `errors`. Using `about:blank` as the type says that the title alone describes the problem, which is right for standard HTTP statuses. Field errors belong in a list so a form can highlight each field, and copying them keeps later changes to the caller''s array from leaking into an already-built response. Serving the body as `application/problem+json` tells clients it''s an error to parse, not a normal payload.","uk":"RFC 9457 (який замінює RFC 7807) стандартизує тіло помилки: машинно-читаний `type`, людський `title`, `status` і необов''язкові `detail`, `instance` та розширення на кшталт `errors`. Вказання `about:blank` як типу означає, що сам заголовок описує проблему, що правильно для стандартних HTTP-статусів. Помилки полів мають бути списком, щоб форма могла підсвітити кожне поле, а їх копіювання не дає подальшим змінам масиву викликача потрапити у вже побудовану відповідь. Подання тіла як `application/problem+json` каже клієнтам, що це помилку треба розібрати, а не звичайні дані."}'::jsonb, '{"/src/problem.ts":"export const CONTENT_TYPE = \"application/problem+json\";\n\nexport type FieldError = { field: string; message: string };\nexport type ProblemDetails = {\n  type: string;\n  title: string;\n  status: number;\n  detail?: string;\n  instance?: string;\n  errors?: FieldError[];\n};\n\nconst TITLES: Record<number, string> = {\n  400: \"Bad Request\",\n  401: \"Unauthorized\",\n  403: \"Forbidden\",\n  404: \"Not Found\",\n  405: \"Method Not Allowed\",\n  409: \"Conflict\",\n  422: \"Unprocessable Content\",\n  429: \"Too Many Requests\",\n  500: \"Internal Server Error\",\n  503: \"Service Unavailable\",\n};\n\nexport function problemDetails(\n  status: number,\n  detail: string | FieldError[] | null,\n  options: { instance?: string } = {},\n): ProblemDetails {\n  if (!Number.isInteger(status) || status < 400 || status > 599) {\n    throw new RangeError(\"Problem details are for 4xx and 5xx statuses, got \" + status);\n  }\n  // \"about:blank\" means the title alone describes the problem, which is what RFC 9457 suggests for standard statuses.\n  const problem: ProblemDetails = { type: \"about:blank\", title: TITLES[status] ?? \"Error\", status };\n  if (typeof detail === \"string\") problem.detail = detail;\n  // Copy the field errors, so the response can''t change the caller''s list later.\n  if (Array.isArray(detail) && detail.length > 0) {\n    problem.errors = detail.map((error) => ({ field: error.field, message: error.message }));\n  }\n  if (options.instance !== undefined) problem.instance = options.instance;\n  return problem;\n}\n"}'::jsonb),
  ('rx-vs-promise', array['a']::text[], '{"en":"A Promise represents a single future value and starts its work immediately (eager). A typical (cold) Observable is lazy, runs once per subscriber, can emit zero to many values, and can be torn down with `unsubscribe()`. That makes it a good fit for events, streams and cancellable requests.","uk":"Promise представляє одне майбутнє значення й починає роботу одразу (енергійно). Типовий (холодний) Observable лінивий, виконується окремо для кожного підписника, може випромінити від нуля до багатьох значень і зупиняється через `unsubscribe()`. Тож він добре підходить для подій, потоків і запитів, які можна скасувати."}'::jsonb, null::jsonb),
  ('rx-share-replay', array['b']::text[], '{"en":"`share()` multicasts but doesn''t replay, so late subscribers miss the value. `shareReplay(1)` replays, but with `refCount: false` (the default) it keeps the inner subscription alive forever, a classic leak with long-lived sources. `refCount: true` unsubscribes from the source when the last subscriber leaves. `take(1)` alone doesn''t share anything.","uk":"`share()` робить мультикаст, але не повторює значення, тож пізні підписники його пропускають. `shareReplay(1)` повторює, але з `refCount: false` (типово) тримає внутрішню підписку назавжди — класичний витік із довгоживучими джерелами. `refCount: true` відписується від джерела, коли йде останній підписник. Сам `take(1)` нічого не робить спільним."}'::jsonb, null::jsonb),
  ('rx-switchmap-sync', array['b']::text[], '{"en":"`of(1, 2, 3)` emits all three values synchronously. Each value makes `switchMap` subscribe to a new `timer(0)` and unsubscribe from the previous one before it can fire. Only the last inner timer survives, so the output is `3`. `mergeMap` would emit `1, 2, 3`, and `exhaustMap` would emit only `1`.","uk":"`of(1, 2, 3)` випромінює всі три значення синхронно. Кожне значення змушує `switchMap` підписатися на новий `timer(0)` і відписатися від попереднього, перш ніж той спрацює. Виживає лише останній внутрішній таймер, тож результат — `3`. `mergeMap` випромінив би `1, 2, 3`, а `exhaustMap` — лише `1`."}'::jsonb, null::jsonb),
  ('rx-cold-http', array['b']::text[], '{"en":"HttpClient observables are cold: every subscriber triggers its own request. Share the result with `shareReplay({ bufferSize: 1, refCount: true })`, or subscribe once (e.g. `@if (user$ | async; as user)`).","uk":"Observable з HttpClient холодні: кожен підписник запускає власний запит. Поділіть результат через `shareReplay({ bufferSize: 1, refCount: true })` або підпишіться один раз (наприклад, `@if (user$ | async; as user)`)."}'::jsonb, null::jsonb),
  ('rx-switchmap-search', array['c']::text[], '{"en":"`switchMap` unsubscribes from the previous inner observable when a new value arrives, which cancels the stale request and prevents out-of-order results. `mergeMap` would let old responses overwrite new ones, `concatMap` would queue every keystroke, and `exhaustMap` would ignore new queries.","uk":"`switchMap` відписується від попереднього внутрішнього observable, коли надходить нове значення: це скасовує застарілий запит і запобігає результатам не в тому порядку. `mergeMap` дозволив би старим відповідям перезаписати нові, `concatMap` ставив би в чергу кожне натискання, а `exhaustMap` ігнорував би нові запити."}'::jsonb, null::jsonb),
  ('rx-exhaustmap-submit', array['b']::text[], '{"en":"`exhaustMap` ignores source values while the inner observable is still active, so extra clicks are dropped until the payment completes. `switchMap` would cancel the first request client-side, but the server may already have processed it.","uk":"`exhaustMap` ігнорує значення джерела, поки внутрішній observable ще активний, тож зайві кліки відкидаються до завершення оплати. `switchMap` скасував би перший запит на клієнті, але сервер міг уже його обробити."}'::jsonb, null::jsonb),
  ('rx-behaviorsubject', array['b']::text[], '{"en":"BehaviorSubject requires an initial value, exposes `.value`, and emits the latest value to each new subscriber, which makes it a minimal state container. A plain Subject has no memory, and AsyncSubject emits only the last value on completion.","uk":"BehaviorSubject потребує початкового значення, має `.value` і видає останнє значення кожному новому підписнику, що робить його мінімальним контейнером стану. Звичайний Subject нічого не пам''ятає, а AsyncSubject видає лише останнє значення при завершенні."}'::jsonb, null::jsonb),
  ('rx-catcherror-placement', array['a']::text[], '{"en":"An error terminates the stream it reaches. Here it reaches the outer pipeline, and `catchError` swaps the whole stream for `of([])`, which emits once and completes. Move `catchError` inside `switchMap` (`search(q).pipe(catchError(() => of([])))`) so only that inner request is replaced.","uk":"Помилка завершує потік, до якого доходить. Тут вона доходить до зовнішнього конвеєра, і `catchError` замінює весь потік на `of([])`, що видає одне значення й завершується. Перенесіть `catchError` усередину `switchMap` (`search(q).pipe(catchError(() => of([])))`), щоб замінювався лише той внутрішній запит."}'::jsonb, null::jsonb),
  ('rx-typeahead', null::text[], '{"en":"`map(trim)` → `debounceTime` waits for a pause → `filter` drops short queries → `distinctUntilChanged` skips repeats → `switchMap` unsubscribes from the previous search, which cancels it. `catchError` must sit inside `switchMap`: there it only replaces the failed inner search with `[]`, while the outer stream keeps listening.","uk":"`map(trim)` → `debounceTime` чекає паузи → `filter` відкидає короткі запити → `distinctUntilChanged` пропускає повтори → `switchMap` відписується від попереднього пошуку й тим скасовує його. `catchError` має бути всередині `switchMap`: там він замінює на `[]` лише невдалий внутрішній пошук, а зовнішній потік продовжує слухати."}'::jsonb, '{"/src/typeahead.ts":"import { Observable, of } from \"rxjs\";\nimport { catchError, debounceTime, distinctUntilChanged, filter, map, switchMap } from \"rxjs/operators\";\n\nexport function createTypeahead(\n  query$: Observable<string>,\n  search: (q: string) => Observable<string[]>,\n  debounceMs: number,\n): Observable<string[]> {\n  return query$.pipe(\n    map((q) => q.trim()),\n    debounceTime(debounceMs),\n    filter((q) => q.length >= 2),\n    distinctUntilChanged(),\n    // switchMap cancels the previous inner search; catchError inside keeps the outer stream alive.\n    switchMap((q) => search(q).pipe(catchError(() => of([] as string[])))),\n  );\n}\n"}'::jsonb),
  ('scope-implicit-global', array['a']::text[], '{"en":"In sloppy mode, assigning to a name that isn''t declared anywhere creates a property on the global object instead of failing, so the typo silently leaks a global (and `counter` never changes). In strict mode, which includes every ES module and class, the same line throws a `ReferenceError`.","uk":"У нестрогому режимі присвоєння імені, що ніде не оголошене, створює властивість глобального об''єкта замість помилки, тож одрук мовчки створює глобальну змінну (а `counter` ніколи не змінюється). У строгому режимі, зокрема в кожному ES-модулі й класі, той самий рядок кидає `ReferenceError`."}'::jsonb, null::jsonb),
  ('scope-var-let-global', array['a']::text[], '{"en":"In a classic script, top-level `var` and function declarations become properties of the global object. Top-level `let`, `const` and `class` are global **variables** too (`typeof b` sees it), but they live in a separate declarative record and don''t create properties. In a module, none of them would touch `globalThis`.","uk":"У класичному скрипті `var` і оголошення функцій верхнього рівня стають властивостями глобального об''єкта. `let`, `const` і `class` верхнього рівня теж є глобальними **змінними** (`typeof b` її бачить), але живуть в окремому декларативному записі й властивостей не створюють. У модулі жодна з них не торкнулася б `globalThis`."}'::jsonb, null::jsonb),
  ('scope-typeof-undeclared', array['a']::text[], '{"en":"`typeof` is the one operator that tolerates an **undeclared** name and returns `\"undefined\"`, which is why feature checks like `typeof window !== \"undefined\"` work. Reading an undeclared name throws. A `let` declared later in the same scope is declared but uninitialised (TDZ), and even `typeof` throws for it.","uk":"`typeof` є єдиним оператором, що терпить **неоголошене** ім''я й повертає `\"undefined\"`, тому працюють перевірки на кшталт `typeof window !== \"undefined\"`. Читання неоголошеного імені кидає помилку. `let`, оголошена пізніше в тій самій області, оголошена, але не ініціалізована (TDZ), і для неї кидає навіть `typeof`."}'::jsonb, null::jsonb),
  ('scope-early-error', array['a']::text[], '{"en":"The engine parses and analyses scopes for the whole file before executing it. Redeclaring a `let` in the same scope is an **early error**, so the file is rejected as a whole and even the first `console.log` never runs. This is direct evidence that scopes are decided before execution.","uk":"Рушій розбирає й аналізує області видимості всього файлу до його виконання. Повторне оголошення `let` в тій самій області є **ранньою помилкою**, тож файл відхиляється повністю, і навіть перший `console.log` не виконується. Це пряме свідчення того, що області видимості визначаються до виконання."}'::jsonb, null::jsonb),
  ('scope-hoisting-precedence', array['a']::text[], '{"en":"Both declarations are hoisted to the top of `demo`, and the function declaration wins: a `var` declaration never resets an existing binding to `undefined`. So `foo` starts as the function. When execution reaches `var foo = \"bar\"`, only the **assignment** part runs, replacing it with a string. The function declaration line itself does nothing at runtime.","uk":"Обидва оголошення піднімаються на початок `demo`, і перемагає оголошення функції: оголошення `var` ніколи не скидає наявне зв''язування в `undefined`. Тож спершу `foo` є функцією. Коли виконання доходить до `var foo = \"bar\"`, виконується лише частина **присвоєння**, що замінює її рядком. Сам рядок з оголошенням функції під час виконання нічого не робить."}'::jsonb, null::jsonb),
  ('scope-duplicate-functions', array['a']::text[], '{"en":"Both declarations are hoisted before any code runs, and the later one overwrites the earlier one, so even the call above them gets `second`. In an ES module (or with `let`/`const`), the duplicate would be a `SyntaxError` instead, one more reason to prefer modules.","uk":"Обидва оголошення піднімаються до виконання будь-якого коду, і пізніше перезаписує раннє, тож навіть виклик над ними отримує `second`. В ES-модулі (чи з `let`/`const`) дублікат натомість був би `SyntaxError`, і це ще одна причина віддавати перевагу модулям."}'::jsonb, null::jsonb),
  ('scope-strict-this', array['a']::text[], '{"en":"In sloppy mode, a plain call gets the global object as `this`, and a primitive passed with `call` is **boxed** into an object (`Number {5}`). In strict mode, `this` is exactly what the call provides: `undefined` for a plain call and the raw number `5` with `call`. That''s why forgetting `new` or losing a method''s receiver throws in strict code instead of silently touching the global object.","uk":"У нестрогому режимі звичайний виклик отримує глобальний об''єкт як `this`, а примітив, переданий через `call`, **загортається** в об''єкт (`Number {5}`). У строгому режимі `this` є саме тим, що дає виклик: `undefined` для звичайного виклику й саме число `5` з `call`. Тому забутий `new` чи втрачений отримувач методу у строгому коді кидає помилку, а не мовчки змінює глобальний об''єкт."}'::jsonb, null::jsonb),
  ('scope-strict-silent-failures', array['a']::text[], '{"en":"All three writes target read-only properties: a frozen object''s property, the non-writable global `undefined`, and a string''s `length`. In sloppy mode each would be **silently ignored**; in strict mode (every module) each throws a `TypeError`. Turning silent no-ops into errors is the main practical benefit of strict mode.","uk":"Усі три записи спрямовані у властивості, доступні лише для читання: властивість замороженого об''єкта, недоступна для запису глобальна `undefined` і `length` рядка. У нестрогому режимі кожен запис **мовчки ігнорувався б**; у строгому режимі (кожен модуль) кожен кидає `TypeError`. Перетворення тихих холостих операцій на помилки є головною практичною перевагою строгого режиму."}'::jsonb, null::jsonb),
  ('scope-named-function-expression', array['a']::text[], '{"en":"A named function expression''s name is bound in a tiny scope **only visible inside the function**, so `typeof fact` outside is `\"undefined\"`. That binding is also read-only: `fact = null` is silently ignored in sloppy mode (and throws a `TypeError` in strict mode), so the recursion still works. That makes named function expressions a safe way to recurse even if the outer variable is reassigned.","uk":"Ім''я іменованого функціонального виразу зв''язується в маленькій області видимості, **видимій лише всередині функції**, тож `typeof fact` ззовні дає `\"undefined\"`. Це зв''язування ще й доступне лише для читання: `fact = null` мовчки ігнорується в нестрогому режимі (і кидає `TypeError` у строгому), тож рекурсія все одно працює. Через це іменовані функціональні вирази є безпечним способом рекурсії, навіть якщо зовнішній змінній присвоять інше значення."}'::jsonb, null::jsonb),
  ('scope-arguments-mapping', array['a']::text[], '{"en":"In a sloppy function with simple parameters, `arguments` is **mapped**: its slots alias the parameters, so writing `arguments[0]` changes `a`. Strict functions get an unmapped copy, and so does any function with default, rest or destructured parameters, even in sloppy mode. Use rest parameters instead of `arguments` and the question never comes up.","uk":"У нестрогій функції з простими параметрами `arguments` **пов''язаний**: його комірки є псевдонімами параметрів, тож запис `arguments[0]` змінює `a`. Строгі функції отримують непов''язану копію, як і будь-яка функція з параметрами за замовчуванням, rest чи деструктуризацією, навіть у нестрогому режимі. Використовуйте rest-параметри замість `arguments`, і це питання ніколи не виникне."}'::jsonb, null::jsonb),
  ('scope-block-function', array['a']::text[], '{"en":"Legacy web compatibility rules (Annex B) give a block-level function declaration in sloppy code **two** bindings: a block-scoped one inside the block, and a `var`-like one in the enclosing scope, which starts as `undefined` and is only assigned when the block is evaluated. In strict code there''s only the block binding, so both checks would print `undefined`. Use `const inner = () => {}` instead.","uk":"Застарілі правила сумісності вебу (Annex B) дають оголошенню функції на рівні блоку в нестрогому коді **два** зв''язування: блокове всередині блоку й схоже на `var` у зовнішній області, яке спершу дорівнює `undefined` і присвоюється лише під час виконання блоку. У строгому коді є лише блокове зв''язування, тож обидві перевірки вивели б `undefined`. Натомість використовуйте `const inner = () => {}`."}'::jsonb, null::jsonb),
  ('scope-eval-var', array['a']::text[], '{"en":"Direct `eval` in sloppy code runs in the caller''s scope and can **add** `var` declarations to it at runtime, so `leaked` appears in `f`. Strict-mode `eval` gets its own variable scope, so declarations stay inside the evaluated code. Because sloppy `eval` (and `with`) can change scopes at runtime, engines can''t optimise functions that use them; and evaluating strings is an injection risk anyway.","uk":"Прямий `eval` у нестрогому коді виконується в області видимості того, хто його викликав, і може **додати** до неї оголошення `var` під час виконання, тож `leaked` з''являється у `f`. Строгий `eval` отримує власну область змінних, тож оголошення лишаються всередині обчисленого коду. Оскільки нестрогий `eval` (і `with`) може змінювати області видимості під час виконання, рушії не можуть оптимізувати функції, що їх використовують; до того ж обчислення рядків є ризиком ін''єкцій."}'::jsonb, null::jsonb),
  ('scope-resolver', null::text[], '{"en":"The solution mirrors the engine''s two phases. First it registers every declaration in its scope (hoisting `var` past blocks), which is why lookups don''t depend on the order of code. Then each reference walks outwards through parent scopes until it finds a declaration. The checks after that encode the language rules: TDZ only applies when the reference runs in the same function before the declaration, `const` rejects writes, and a failed write only becomes an implicit global when no enclosing scope is strict.","uk":"Розв''язок повторює дві фази рушія. Спершу він реєструє кожне оголошення в його області (піднімаючи `var` за межі блоків), тому пошук не залежить від порядку коду. Потім кожне посилання йде назовні через батьківські області, доки не знайде оголошення. Перевірки після цього кодують правила мови: TDZ діє лише тоді, коли посилання виконується в тій самій функції до оголошення, `const` відхиляє записи, а невдалий запис стає неявною глобальною змінною, лише коли жодна зовнішня область не строга."}'::jsonb, '{"/src/resolver.ts":"export type DeclKind = \"var\" | \"let\" | \"const\" | \"function\" | \"param\";\nexport type Declaration = { name: string; kind: DeclKind; at: number };\nexport type Reference = { id: string; name: string; mode: \"read\" | \"write\"; at: number };\nexport type Scope = {\n  kind: \"global\" | \"function\" | \"block\";\n  /** \"use strict\" in this scope; applies to everything nested inside it. */\n  strict?: boolean;\n  declarations?: Declaration[];\n  references?: Reference[];\n  children?: Scope[];\n};\n/** A scope path (\"0\", \"0.1\", \"0.1.0\": child indexes from the root) or an outcome. */\nexport type Resolution = string;\n\ntype Node = { scope: Scope; path: string; parent: Node | null; strict: boolean; names: Map<string, Declaration> };\n\nexport function resolve(program: Scope): Record<string, Resolution> {\n  const nodes: Node[] = [];\n  const build = (scope: Scope, path: string, parent: Node | null) => {\n    const node: Node = { scope, path, parent, strict: Boolean(scope.strict || parent?.strict), names: new Map() };\n    nodes.push(node);\n    (scope.children ?? []).forEach((child, i) => build(child, path + \".\" + i, node));\n  };\n  build(program, \"0\", null);\n\n  // Phase 1 (\"compile\"): register every declaration. var skips blocks and lands in the nearest function or global scope.\n  for (const node of nodes) {\n    for (const decl of node.scope.declarations ?? []) {\n      let target = node;\n      if (decl.kind === \"var\") while (target.scope.kind === \"block\" && target.parent) target = target.parent;\n      if (!target.names.has(decl.name)) target.names.set(decl.name, decl);\n    }\n  }\n\n  // Phase 2 (\"execute\"): resolve each reference by walking outwards.\n  const out: Record<string, Resolution> = {};\n  for (const node of nodes) {\n    for (const ref of node.scope.references ?? []) {\n      let current: Node | null = node;\n      let crossedFunction = false;\n      let decl: Declaration | undefined;\n      while (current) {\n        decl = current.names.get(ref.name);\n        if (decl) break;\n        if (current.scope.kind === \"function\") crossedFunction = true;\n        current = current.parent;\n      }\n      if (!current || !decl) {\n        out[ref.id] = ref.mode === \"write\" && !node.strict ? \"implicit-global\" : \"not-defined\";\n      } else if ((decl.kind === \"let\" || decl.kind === \"const\") && !crossedFunction && decl.at > ref.at) {\n        // Same function, used before the declaration ran. Inside a nested function it may run later, so it''s fine.\n        out[ref.id] = \"tdz\";\n      } else if (decl.kind === \"const\" && ref.mode === \"write\") {\n        out[ref.id] = \"const-assignment\";\n      } else {\n        out[ref.id] = current.path;\n      }\n    }\n  }\n  return out;\n}\n"}'::jsonb),
  ('scope-global-leaks', null::text[], '{"en":"`Object.getOwnPropertyNames` sees non-enumerable properties that `Object.keys` misses, and storing full **descriptors** instead of values lets the tracker notice replaced accessors and restore properties exactly, including their enumerability and writability. Comparing with `Object.is` avoids false positives for `NaN`. `Reflect.deleteProperty` and `Reflect.defineProperty` return `false` instead of throwing for non-configurable properties, which keeps `restore()` from crashing a test run.","uk":"`Object.getOwnPropertyNames` бачить неперелічувані властивості, які пропускає `Object.keys`, а збереження повних **дескрипторів** замість значень дає змогу помітити замінені аксесори й точно відновити властивості, зокрема їхню перелічуваність і доступність для запису. Порівняння через `Object.is` уникає хибних спрацювань для `NaN`. `Reflect.deleteProperty` і `Reflect.defineProperty` повертають `false` замість кидання помилки для неналаштовуваних властивостей, і через це `restore()` не обвалює запуск тестів."}'::jsonb, '{"/src/globals.ts":"export type GlobalTracker = {\n  added(): string[];\n  changed(): string[];\n  removed(): string[];\n  restore(): void;\n};\n\nexport function trackGlobals(target: object = globalThis, { ignore = [] as string[] } = {}): GlobalTracker {\n  const ignored = new Set(ignore);\n  // Descriptors, not just values: catches non-enumerable globals and replaced getters/setters too.\n  const snapshot = new Map<string, PropertyDescriptor>();\n  for (const name of Object.getOwnPropertyNames(target)) {\n    if (!ignored.has(name)) snapshot.set(name, Object.getOwnPropertyDescriptor(target, name)!);\n  }\n  const current = () => Object.getOwnPropertyNames(target).filter((name) => !ignored.has(name));\n  const same = (a: PropertyDescriptor, b: PropertyDescriptor) =>\n    \"value\" in a ? \"value\" in b && Object.is(a.value, b.value) : a.get === b.get && a.set === b.set;\n\n  const added = () => current().filter((name) => !snapshot.has(name)).sort();\n  const removed = () => [...snapshot.keys()].filter((name) => !Object.prototype.hasOwnProperty.call(target, name)).sort();\n  const changed = () =>\n    current()\n      .filter((name) => snapshot.has(name) && !same(snapshot.get(name)!, Object.getOwnPropertyDescriptor(target, name)!))\n      .sort();\n\n  return {\n    added,\n    changed,\n    removed,\n    restore() {\n      for (const name of added()) Reflect.deleteProperty(target, name);\n      for (const name of [...changed(), ...removed()]) Reflect.defineProperty(target, name, snapshot.get(name)!);\n    },\n  };\n}\n"}'::jsonb),
  ('scroll-end-detection', null::text[], '{"en":"The bottom is reached when the visible bottom edge (`scrollTop + clientHeight`) meets the content''s total height. Browsers round scroll positions to fractional pixels, so an exact equality check can fail at the bottom; a small tolerance fixes that. Content that fits without scrolling is already \"at the bottom\", which is why the no-overflow case must return true, or the button would stay locked on short content.","uk":"Низ досягнуто, коли нижній край видимої області (`scrollTop + clientHeight`) збігається із загальною висотою вмісту. Браузери округлюють позицію прокрутки до дробових пікселів, тому точна рівність може не спрацювати внизу; невеликий допуск вирішує це. Вміст, що вміщується без прокрутки, уже «внизу», тому для випадку без переповнення має повертатися true, інакше кнопка на короткому вмісті лишилася б заблокованою."}'::jsonb, '{"/src/scroll.ts":"export interface ScrollMetrics {\n  scrollTop: number;\n  clientHeight: number;\n  scrollHeight: number;\n}\n\nexport function isAtBottom(m: ScrollMetrics, tolerance = 1): boolean {\n  if (m.scrollHeight <= m.clientHeight) return true;\n  return m.scrollTop + m.clientHeight >= m.scrollHeight - tolerance;\n}\n\nexport function scrollProgress(m: ScrollMetrics): number {\n  const overflow = m.scrollHeight - m.clientHeight;\n  if (overflow <= 0) return 1;\n  const ratio = m.scrollTop / overflow;\n  return Math.min(1, Math.max(0, ratio));\n}\n"}'::jsonb),
  ('offsetheight-vs-clientheight', array['b']::text[], '{"en":"`offsetHeight` is the rendered box height, including the border and the horizontal scrollbar. `clientHeight` is the visible area inside the padding, excluding the border and scrollbars. `scrollHeight` is the full content height, including overflow, and `window.innerHeight` is the viewport, not an element.","uk":"`offsetHeight` це висота відрендереної коробки, включно з рамкою та горизонтальною смугою прокрутки. `clientHeight` це видима область всередині padding, без рамки та смуг прокрутки. `scrollHeight` це повна висота вмісту з переповненням, а `window.innerHeight` це viewport, а не елемент."}'::jsonb, null::jsonb),
  ('scroll-end-condition', array['b']::text[], '{"en":"The visible bottom edge is `scrollTop + clientHeight`, and the content ends at `scrollHeight`. When they meet, the reader is at the bottom. In practice, fractional scroll positions on high-DPI screens can make the sum fall just short, so a small tolerance is usually added.","uk":"Видимий нижній край це `scrollTop + clientHeight`, а вміст закінчується на `scrollHeight`. Коли вони збігаються, читач унизу. На практиці дробові позиції прокрутки на екранах з високою щільністю можуть дати суму, трохи меншу, тому зазвичай додають невеликий допуск."}'::jsonb, null::jsonb),
  ('inline-element-size', array['b']::text[], '{"en":"Inline boxes size themselves to their content, so width and height are ignored. Switching to `display: inline-block` keeps the element on one line while letting width and height apply, or use `display: block` (or flex) when it should take its own row.","uk":"Інлайнові бокси розміщуються за вмістом, тому width і height ігноруються. Перехід на `display: inline-block` тримає елемент в одному рядку й дозволяє width і height працювати, а `display: block` (або flex), коли елемент має займати окремий рядок."}'::jsonb, null::jsonb),
  ('flex-child-min-height-scroll', array['b']::text[], '{"en":"Flex items default to `min-height: auto`, which means they never shrink below their content. Setting `min-height: 0` lets the middle item shrink to the free space, and `overflow: auto` on it then creates the scrollbar. The header and footer keep their size, so buttons pinned in the footer stay visible while the body scrolls.","uk":"Flex-елементи за замовчуванням мають `min-height: auto`, тобто ніколи не стискаються нижче свого вмісту. Встановлення `min-height: 0` дозволяє середньому елементу стиснутися до вільного місця, а `overflow: auto` на ньому створює смугу прокрутки. Шапка й футер зберігають розмір, тож кнопки у футері лишаються видимими, поки прокручується тіло."}'::jsonb, null::jsonb),
  ('disabled-initial-state', array['b']::text[], '{"en":"Markup is the only place that works without JavaScript, and it renders before the script runs, so the button never flashes enabled. The script then only has to update the state when the reader scrolls or the layout changes. Waiting for `load` or using a timer adds a visible delay for no benefit here.","uk":"Розмітка єдине місце, що працює без JavaScript, і вона відображається до запуску скрипта, тож кнопка ніколи не блимає як активна. Скрипт потім лише оновлює стан при прокрутці або зміні макета. Очікування `load` або таймер дають помітну затримку без користі."}'::jsonb, null::jsonb),
  ('resize-affects-scroll-end', array['a']::text[], '{"en":"Scroll events only fire when the scroll position changes. If the window grows, content may suddenly fit without any scrolling, so the reader is at the bottom with no scroll event at all. Running the same check on `resize` keeps the button in sync with the actual layout.","uk":"Події scroll спрацьовують лише коли змінюється позиція прокрутки. Якщо вікно збільшилося, вміст може раптом вміститися без жодної прокрутки, і читач уже внизу, а події scroll не буде. Та сама перевірка на `resize` тримає кнопку синхронізованою з реальним макетом."}'::jsonb, null::jsonb),
  ('search-bfs-shortest', array['b']::text[], '{"en":"BFS explores cells in order of distance from the start (all cells 1 move away, then 2, …), so the first time it reaches the exit is via a shortest path. DFS finds a path, not necessarily the shortest. With different move costs, use Dijkstra''s algorithm instead.","uk":"BFS обходить клітинки в порядку віддаленості від старту (усі на відстані 1 хід, потім 2, …), тож уперше він досягає виходу найкоротшим шляхом. DFS знаходить якийсь шлях, не обов''язково найкоротший. Якщо ходи мають різну вартість, використовуйте алгоритм Дейкстри."}'::jsonb, null::jsonb),
  ('search-galloping', array['b']::text[], '{"en":"Doubling the probe index takes about log p steps to overshoot the target, and the final range [i/2, i] has size O(p), so the binary search adds another O(log p). Searching up to `MAX_SAFE_INTEGER` costs a constant ~53 steps, but it''s O(log max), not proportional to where the target is, and jump search needs a known n. TimSort uses galloping when merging runs.","uk":"Подвоєння індексу перевірки потребує близько log p кроків, щоб перескочити ціль, а останній діапазон [i/2, i] має розмір O(p), тож бінарний пошук додає ще O(log p). Пошук до `MAX_SAFE_INTEGER` коштує сталі ~53 кроки, але це O(log max), а не пропорційно положенню цілі, а стрибковому пошуку потрібне відоме n. TimSort використовує галопування під час злиття серій."}'::jsonb, null::jsonb),
  ('search-binary-precondition', array['a']::text[], '{"en":"Binary search discards half of the range by comparing with the middle element, which only works if the data is ordered by the key. Duplicates are allowed (use lower/upper bound to handle them), any length works and any comparable type works.","uk":"Бінарний пошук відкидає половину діапазону, порівнюючи з середнім елементом, а це працює лише для впорядкованих за ключем даних. Дублікати допустимі (для них є нижня/верхня межа), довжина може бути будь-якою, тип — будь-який порівнюваний."}'::jsonb, null::jsonb),
  ('search-binary-complexity', array['a']::text[], '{"en":"Each comparison halves the range, so the count is about log₂(1,000,000) ≈ 20. That is the whole point of O(log n).","uk":"Кожне порівняння вдвічі зменшує діапазон, тож потрібно близько log₂(1 000 000) ≈ 20 порівнянь. У цьому вся суть O(log n)."}'::jsonb, null::jsonb),
  ('search-infinite-loop-bug', array['a']::text[], '{"en":"When `hi - lo === 1`, `mid === lo`. If `a[mid] < x`, assigning `lo = mid` leaves the range unchanged forever. Since `a[mid]` is known to be too small, it can be excluded: `lo = mid + 1`. The other options break the half-open invariant or return wrong positions.","uk":"Коли `hi - lo === 1`, то `mid === lo`. Якщо `a[mid] < x`, присвоєння `lo = mid` назавжди залишає діапазон незмінним. Оскільки `a[mid]` точно замалий, його можна виключити: `lo = mid + 1`. Інші варіанти порушують інваріант напіввідкритого діапазону або повертають хибні позиції."}'::jsonb, null::jsonb),
  ('search-many-lookups', array['b']::text[], '{"en":"`includes`/`find` are O(n) each, so 50,000 lookups cost about 5·10⁹ operations. Building a `Set` is O(n) once, and each `has` is O(1) on average. Sorting once plus binary search (O(n log n + m log n)) would also work, but sorting before every lookup is far worse.","uk":"`includes`/`find` коштують O(n) кожен, тож 50 000 пошуків — це близько 5·10⁹ операцій. Побудова `Set` — O(n) один раз, а кожен `has` — у середньому O(1). Одноразове сортування з бінарним пошуком (O(n log n + m log n)) теж підійде, але сортувати перед кожним пошуком — значно гірше."}'::jsonb, null::jsonb),
  ('search-two-pointers', array['a', 'b', 'd']::text[], '{"en":"On sorted input, a sum that is too small means the left element cannot pair with anything to its right except larger values, so it is discarded and the pointer moves right (and symmetrically for the right pointer). That gives O(n) time with constant space. Without ordering the discard argument fails; use a hash map instead.","uk":"На відсортованих даних замала сума означає, що лівий елемент не утворить пари з жодним елементом, тож його відкидаємо й зсуваємо вказівник праворуч (симетрично для правого вказівника). Звідси O(n) часу та константна пам''ять. Без упорядкування аргумент про відкидання не працює, тому для невідсортованих даних беріть хеш-таблицю."}'::jsonb, null::jsonb),
  ('search-on-answer', array['a']::text[], '{"en":"We binary search over capacities between `max(w)` and `sum(w)`. A greedy O(n) check tells whether a capacity fits in D days, and the answer flips from ''no'' to ''yes'' exactly once, which is the monotonic predicate binary search needs. The weights do not need to be sorted.","uk":"Ми шукаємо бінарно серед місткостей від `max(w)` до `sum(w)`. Жадібна перевірка за O(n) показує, чи вкладається місткість у D днів, а відповідь змінюється з «ні» на «так» рівно один раз. Саме такий монотонний предикат потрібен бінарному пошуку. Ваги відсортовувати не потрібно."}'::jsonb, null::jsonb),
  ('search-implement-binary-search', null::text[], '{"en":"Keep the invariant ''if target exists, it is within [lo, hi]''. Compare with the middle element and shrink the range by excluding `mid` on each side. The loop runs at most ⌈log₂(n+1)⌉ times.","uk":"Тримайте інваріант «якщо target існує, він у [lo, hi]». Порівнюйте з середнім елементом і звужуйте діапазон, виключаючи `mid` з відповідного боку. Цикл виконується не більше ⌈log₂(n+1)⌉ разів."}'::jsonb, '{"/src/binarySearch.ts":"export function binarySearch(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length - 1;\n  while (lo <= hi) {\n    const mid = lo + ((hi - lo) >> 1);\n    const value = items[mid];\n    if (value === target) return mid;\n    if (value < target) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}\n"}'::jsonb),
  ('search-count-occurrences', null::text[], '{"en":"The first index with value ≥ x and the first index with value ≥ x+1 bracket the run of x. Two lower-bound searches cost O(log n), regardless of how many duplicates there are. (For non-integers, use an ''upper bound'' with `<=` instead of x+1.)","uk":"Перший індекс зі значенням ≥ x і перший індекс зі значенням ≥ x+1 обмежують серію x. Два пошуки нижньої межі коштують O(log n) незалежно від кількості дублікатів. (Для нецілих чисел використайте «верхню межу» з `<=` замість x+1.)"}'::jsonb, '{"/src/count.ts":"function lowerBound(a: number[], x: number) {\n  let lo = 0;\n  let hi = a.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (a[mid] < x) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;\n}\n\nexport function countOccurrences(sorted: number[], x: number): number {\n  return lowerBound(sorted, x + 1) - lowerBound(sorted, x);\n}\n"}'::jsonb),
  ('http2-multiplexing', array['a']::text[], '{"en":"HTTP/2 keeps the same semantics (methods, status codes, headers) but changes the wire format: it is **binary**, uses **multiplexed streams** on a single connection, and compresses headers with **HPACK**. HTTP/1.1 could reuse a connection (keep-alive) but handled one request at a time on it, so browsers opened about six connections per host and developers resorted to bundling and domain sharding. Moving to UDP is HTTP/3''s change.","uk":"HTTP/2 зберігає ту саму семантику (методи, коди стану, заголовки), але змінює формат передачі: він **бінарний**, використовує **мультиплексовані потоки** в одному з''єднанні та стискає заголовки через **HPACK**. HTTP/1.1 міг повторно використовувати з''єднання (keep-alive), але обробляв у ньому один запит за раз, тому браузери відкривали близько шести з''єднань на хост, а розробники вдавалися до бандлінгу та domain sharding. Перехід на UDP це зміна HTTP/3."}'::jsonb, null::jsonb),
  ('http3-quic', array['a']::text[], '{"en":"In HTTP/2 all streams share one TCP connection, and TCP delivers bytes in order, so one lost packet blocks every stream behind it. HTTP/3 runs over **QUIC**, which is built on UDP, implements reliability **per stream**, has TLS 1.3 built in, and can resume or migrate connections faster (for example when switching from Wi-Fi to mobile data).","uk":"У HTTP/2 усі потоки ділять одне TCP-з''єднання, а TCP доставляє байти по порядку, тож один втрачений пакет блокує всі потоки за ним. HTTP/3 працює поверх **QUIC**, який побудований на UDP, забезпечує надійність **для кожного потоку окремо**, має вбудований TLS 1.3 і швидше відновлює чи переносить з''єднання (наприклад, при переході з Wi-Fi на мобільний інтернет)."}'::jsonb, null::jsonb),
  ('https-tls-guarantees', array['a', 'b', 'c']::text[], '{"en":"TLS provides encryption, integrity and server authentication (the certificate chain proves the server owns the domain), and HTTPS uses port 443 by default (HTTP uses 80). It does not make your own code safe: XSS and injection happen inside the encrypted channel. The hostname usually still leaks through DNS and the TLS SNI field, although Encrypted Client Hello and DoH reduce that.","uk":"TLS забезпечує шифрування, цілісність і автентифікацію сервера (ланцюжок сертифікатів доводить, що сервер володіє доменом), а HTTPS за замовчуванням використовує порт 443 (HTTP використовує 80). Він не робить ваш код безпечним: XSS та ін''єкції відбуваються всередині зашифрованого каналу. Ім''я хоста зазвичай усе одно «витікає» через DNS і поле SNI в TLS, хоча Encrypted Client Hello та DoH це зменшують."}'::jsonb, null::jsonb),
  ('cors-browser-enforced', array['a', 'b', 'c']::text[], '{"en":"CORS is a **browser** policy: the server states, through response headers, which origins may read its responses, and the browser enforces it. So the real fixes are on the server (allow the origin), or by making the request same-origin (a proxy), or by not making it from a browser at all. `no-cors` just returns an opaque response you can''t read, and `Access-Control-Allow-Origin` is a *response* header, so setting it on the request does nothing. Browser extensions that \"disable CORS\" only change your own machine.","uk":"CORS це політика **браузера**: сервер через заголовки відповіді повідомляє, яким джерелам дозволено читати його відповіді, а браузер це примусово застосовує. Тож справжні виправлення на сервері (дозволити джерело), або перетворення запиту на same-origin (проксі), або взагалі не робити запит із браузера. `no-cors` лише повертає непрозору відповідь, яку не прочитати, а `Access-Control-Allow-Origin` це заголовок *відповіді*, тож його встановлення в запиті нічого не дає. Розширення браузера, що «вимикають CORS», змінюють лише вашу машину."}'::jsonb, null::jsonb),
  ('fouc-late-css', array['a']::text[], '{"en":"By default a stylesheet in `<head>` blocks rendering, so the browser won''t paint until it has loaded. FOUC appears when styles arrive late: a `<link>` after the content, CSS injected by JavaScript after first paint, or a non-blocking pattern like `media=\"print\"` with a delayed swap. Fixes are to load the stylesheet in the head, inline the critical (above-the-fold) CSS and load the rest asynchronously, or, in CSS-in-JS apps, extract the styles during server rendering. For web fonts the similar effects are FOUT (fallback font shows first) and FOIT (invisible text), controlled by `font-display`.","uk":"За замовчуванням таблиця стилів у `<head>` блокує рендер, тож браузер нічого не малює, доки вона не завантажиться. FOUC виникає, коли стилі приходять пізно: `<link>` після вмісту, CSS, вставлений JavaScript після першого малювання, або неблокувальні прийоми на кшталт `media=\"print\"` із відкладеною заміною. Виправлення: завантажувати таблицю в head, вбудувати критичний CSS (для першого екрана), а решту завантажити асинхронно, або в застосунках із CSS-in-JS витягувати стилі під час серверного рендеру. Для вебшрифтів схожі ефекти це FOUT (спершу показується запасний шрифт) і FOIT (невидимий текст), якими керує `font-display`."}'::jsonb, null::jsonb),
  ('browser-storage-compare', array['a', 'b', 'd']::text[], '{"en":"`sessionStorage` is scoped to a single tab (or window) and cleared when it closes, `HttpOnly` cookies are hidden from JavaScript by design (which limits what XSS can steal), and `localStorage` isn''t available in workers (IndexedDB is). Choose by need: cookies for server-visible session state (with `HttpOnly`, `Secure` and `SameSite`), `localStorage` for small preferences, IndexedDB for large or structured offline data. Never put secrets in `localStorage`: any XSS can read it.","uk":"`sessionStorage` обмежений однією вкладкою (чи вікном) і очищується при її закритті, cookies з `HttpOnly` приховані від JavaScript за задумом (що обмежує, що може викрасти XSS), а `localStorage` недоступний у воркерах (IndexedDB доступний). Обирайте за потребою: cookies для стану сесії, видимого серверу (з `HttpOnly`, `Secure` і `SameSite`), `localStorage` для невеликих налаштувань, IndexedDB для великих чи структурованих офлайн-даних. Ніколи не зберігайте секрети в `localStorage`: будь-який XSS може їх прочитати."}'::jsonb, null::jsonb),
  ('ts-type-vs-interface', array['a', 'b', 'e']::text[], '{"en":"Interfaces describe object shapes, can be extended with `extends` and are open to **declaration merging** (useful for augmenting library types). A `type` alias can name anything: primitives, unions, tuples, mapped and conditional types, but it can''t be re-opened, and a duplicate name is an error. For plain object shapes the two are largely interchangeable, so follow the project''s convention; reach for `type` when you need unions or computed types.","uk":"Інтерфейси описують форми об''єктів, розширюються через `extends` і відкриті для **злиття оголошень** (корисно для розширення типів бібліотек). Аліас `type` може іменувати що завгодно: примітиви, об''єднання, кортежі, mapped- і conditional-типи, але його не можна «перевідкрити», а дубль імені є помилкою. Для звичайних форм об''єктів вони здебільшого взаємозамінні, тож дотримуйтеся угод проєкту; `type` обирайте, коли потрібні об''єднання чи обчислювані типи."}'::jsonb, null::jsonb),
  ('ts-as-const-vs-enum', array['a']::text[], '{"en":"A regular `enum` emits extra runtime code (an object with, for numeric enums, reverse mappings) and isn''t just type syntax, so it conflicts with tools that only strip types (such as `erasableSyntaxOnly` or Node''s type stripping). `const Status = { Ok: \"ok\", Fail: \"fail\" } as const; type Status = (typeof Status)[keyof typeof Status];` gives the same autocomplete and a union type, with plain string values you can send as JSON. Enums are not wrong, and string enums work fine; nothing is checked at runtime in either approach.","uk":"Звичайний `enum` генерує додатковий код часу виконання (об''єкт, для числових enum ще й зворотні відображення) і не є лише синтаксисом типів, тож конфліктує з інструментами, що лише стирають типи (як-от `erasableSyntaxOnly` чи видалення типів у Node). `const Status = { Ok: \"ok\", Fail: \"fail\" } as const; type Status = (typeof Status)[keyof typeof Status];` дає ті самі підказки й тип-об''єднання, з простими рядковими значеннями, які можна надсилати як JSON. Enum не є помилкою, а рядкові enum працюють добре; жоден підхід нічого не перевіряє під час виконання."}'::jsonb, null::jsonb),
  ('react-setstate-in-render', array['a']::text[], '{"en":"Calling a state setter unconditionally in the component body schedules another render, which calls it again, and so on until React throws \"Too many re-renders\". Rendering must be pure. `rows` is just a function of `data`, so compute it during render: `const rows = useMemo(() => data.map(parse), [data])` (or without `useMemo` when it''s cheap). Don''t mirror props into state, and don''t reach for `useEffect` + `setState` either: that adds an extra render and a flash of stale data.","uk":"Безумовний виклик сеттера стану в тілі компонента планує ще один рендер, який знову його викликає, і так далі, доки React не кине «Too many re-renders». Рендер має бути чистим. `rows` це просто функція від `data`, тож обчислюйте її під час рендеру: `const rows = useMemo(() => data.map(parse), [data])` (або без `useMemo`, коли це дешево). Не дублюйте пропси в стані й не вдавайтеся до `useEffect` + `setState`: це додає зайвий рендер і мерехтіння застарілих даних."}'::jsonb, null::jsonb),
  ('react-effect-once-event', array['b']::text[], '{"en":"Rendering has to be pure: React may render a component more than once (re-renders, StrictMode, concurrent features) and discard results, so sending a network event from the body fires it far too often. An effect runs after the commit, and an empty dependency array limits it to once per mount. In development StrictMode deliberately mounts, unmounts and re-mounts, so you may see the event twice there; that is expected and doesn''t happen in production. If the event must be strictly once, dedupe it in the analytics layer. An event tied to a user action belongs in the event handler, not in an effect.","uk":"Рендер має бути чистим: React може рендерити компонент більше одного разу (ререндери, StrictMode, конкурентні можливості) і відкидати результати, тож надсилання мережевої події з тіла спрацьовує занадто часто. Ефект виконується після коміту, а порожній масив залежностей обмежує його одним разом на монтування. У розробці StrictMode навмисно монтує, розмонтовує й монтує знову, тож ви можете бачити подію двічі; це очікувано і не стається в продакшені. Якщо подія має бути строго одна, дедублікуйте її в шарі аналітики. Подія, пов''язана з дією користувача, належить в обробник події, а не в ефект."}'::jsonb, null::jsonb),
  ('mf-runtime-composition', array['a']::text[], '{"en":"With Module Federation, a **host** application loads code from **remotes**: other builds, deployed independently, that declare what they `expose`. The host resolves them at runtime (usually from a `remoteEntry.js` URL), which is what makes it a popular way to build micro-frontends: each team ships on its own schedule, and a remote can itself consume other remotes (chains of federated modules). The trade-offs are version and dependency management between teams, and runtime failures when a remote is down.","uk":"У Module Federation **хост**-застосунок завантажує код із **remote**-ів: інших збірок, розгорнутих незалежно, що оголошують, що вони `expose`. Хост розв''язує їх під час виконання (зазвичай за URL `remoteEntry.js`), тому це популярний спосіб будувати мікрофронтенди: кожна команда випускає у власному темпі, а remote сам може споживати інші remote-и (ланцюжки федеративних модулів). Компроміси: керування версіями й залежностями між командами та збої під час виконання, коли remote недоступний."}'::jsonb, null::jsonb),
  ('mf-shared-singleton', array['a']::text[], '{"en":"Each federated build bundles its own dependencies unless told otherwise, and hooks rely on a single React instance (a second copy has its own internal dispatcher, so hooks fail). Listing packages under `shared` makes the apps negotiate at runtime and use **one** copy; `singleton: true` forbids loading a second one, and `requiredVersion` states which versions are acceptable. Libraries with global state (React, a router, a design-system context) are the usual candidates, and mismatched major versions are the typical source of trouble.","uk":"Кожна федеративна збірка пакує власні залежності, якщо не вказано інакше, а хуки покладаються на єдиний екземпляр React (друга копія має власний внутрішній dispatcher, тож хуки ламаються). Перелік пакетів у `shared` змушує застосунки домовлятися під час виконання й використовувати **одну** копію; `singleton: true` забороняє завантажувати другу, а `requiredVersion` визначає прийнятні версії. Типові кандидати: бібліотеки з глобальним станом (React, роутер, контекст дизайн-системи), а джерелом проблем зазвичай є різні мажорні версії."}'::jsonb, null::jsonb),
  ('closure-counter-factory', null::text[], '{"en":"A closure is a function that keeps access to the variables of the scope it was created in. Each call of `createCounter` creates a new scope with its own `count`, and the returned methods close over it, so counters are independent and the variable is unreachable from outside (unlike a module-level `let`, which every counter would share, or a public `this.count` property that anyone could assign). `count` is declared with `let` because it is reassigned (a `const` couldn''t change); `value` is exposed through a getter so callers can read but not write it. Parameters can be defaulted with destructuring, and validating up front means a bad configuration fails at creation, not on the first click.","uk":"Замикання це функція, що зберігає доступ до змінних області, у якій її створено. Кожен виклик `createCounter` створює нову область зі своїм `count`, а повернені методи замикаються на неї, тож лічильники незалежні, а змінна недосяжна ззовні (на відміну від `let` рівня модуля, яку ділили б усі лічильники, чи публічної властивості `this.count`, яку будь-хто міг би присвоїти). `count` оголошено через `let`, бо його перепризначають (`const` не змінити); `value` відкрито через getter, щоб викликач міг читати, але не записувати. Параметри можна задавати за замовчуванням через деструктуризацію, а перевірка наперед означає, що погана конфігурація падає при створенні, а не при першому кліку."}'::jsonb, '{"/src/counter.ts":"export interface CounterOptions {\n  start?: number;\n  step?: number;\n  min?: number;\n  max?: number;\n}\n\nexport interface Counter {\n  increment(): number;\n  decrement(): number;\n  reset(): number;\n  readonly value: number;\n}\n\nexport function createCounter({ start = 0, step = 1, min = -Infinity, max = Infinity }: CounterOptions = {}): Counter {\n  if (!Number.isFinite(step) || step === 0) throw new RangeError(\"step must be a finite, non-zero number\");\n  if (min > max) throw new RangeError(\"min must not be greater than max\");\n\n  const clamp = (n: number) => Math.min(max, Math.max(min, n));\n\n  // Private state: only the functions below can see or change it.\n  let count = clamp(start);\n\n  return {\n    increment() {\n      count = clamp(count + step);\n      return count;\n    },\n    decrement() {\n      count = clamp(count - step);\n      return count;\n    },\n    reset() {\n      count = clamp(start);\n      return count;\n    },\n    get value() {\n      return count;\n    },\n  };\n}\n"}'::jsonb),
  ('cookie-serialize-parse', null::text[], '{"en":"A cookie travels in two directions: the server sets it with a `Set-Cookie` response header (one cookie plus attributes), and the browser returns only the `name=value` pairs in the `Cookie` request header, which is why the two functions look so different. The attributes are the security model: `HttpOnly` hides the cookie from `document.cookie` (limiting what XSS can steal), `Secure` restricts it to HTTPS, `SameSite` controls cross-site sending (and browsers require `Secure` with `SameSite=None`), while `Max-Age`/`Expires` set the lifetime and `Max-Age=0` deletes it. Values are percent-encoded because `;`, `,` and spaces would otherwise end the pair, and anything user-controlled that is placed into a header (`domain`, `path`) has to be checked for separators, or an attacker can add their own attributes or even whole headers (header injection). When parsing, split at the first `=` only, since values such as base64 tokens end with `=` signs.","uk":"Cookie подорожує в двох напрямках: сервер встановлює її заголовком відповіді `Set-Cookie` (одна cookie з атрибутами), а браузер повертає лише пари `name=value` у заголовку запиту `Cookie`, тому ці дві функції так відрізняються. Атрибути це модель безпеки: `HttpOnly` ховає cookie від `document.cookie` (обмежуючи, що може викрасти XSS), `Secure` обмежує її HTTPS, `SameSite` керує міжсайтовим надсиланням (і браузери вимагають `Secure` разом із `SameSite=None`), а `Max-Age`/`Expires` задають час життя, і `Max-Age=0` її видаляє. Значення кодуються у відсотковому форматі, бо `;`, `,` і пробіли інакше обірвали б пару, а все, що контролює користувач і потрапляє в заголовок (`domain`, `path`), треба перевіряти на роздільники, інакше зловмисник додасть власні атрибути чи навіть цілі заголовки (header injection). Під час розбору ділите лише за першим `=`, бо значення на кшталт base64-токенів закінчуються знаками `=`."}'::jsonb, '{"/src/cookies.ts":"export interface CookieOptions {\n  maxAge?: number;\n  expires?: Date;\n  domain?: string;\n  path?: string;\n  httpOnly?: boolean;\n  secure?: boolean;\n  sameSite?: \"strict\" | \"lax\" | \"none\" | \"Strict\" | \"Lax\" | \"None\";\n}\n\n// RFC 6265 \"token\": no spaces, separators or control characters.\nconst TOKEN = /^[\\w!#$%&''*+.^\\x60|~-]+$/;\nconst SAME_SITE: Record<string, string> = { strict: \"Strict\", lax: \"Lax\", none: \"None\" };\n\nfunction safeAttribute(label: string, value: string) {\n  // A \";\" or a newline would let a caller smuggle in extra attributes or headers.\n  if (/[;\\r\\n]/.test(value)) throw new TypeError(\"Invalid \" + label + \": \" + value);\n  return value;\n}\n\nexport function serializeCookie(name: string, value: string, options: CookieOptions = {}): string {\n  if (!TOKEN.test(name)) throw new TypeError(\"Invalid cookie name: \" + name);\n  const { maxAge, expires, domain, path, httpOnly, secure, sameSite } = options;\n  const parts = [name + \"=\" + encodeURIComponent(value)];\n\n  if (maxAge !== undefined) {\n    if (!Number.isInteger(maxAge)) throw new RangeError(\"maxAge must be an integer number of seconds\");\n    parts.push(\"Max-Age=\" + maxAge);\n  }\n  if (expires) {\n    if (Number.isNaN(expires.getTime())) throw new RangeError(\"Invalid expires date\");\n    parts.push(\"Expires=\" + expires.toUTCString());\n  }\n  if (domain) parts.push(\"Domain=\" + safeAttribute(\"domain\", domain));\n  if (path) parts.push(\"Path=\" + safeAttribute(\"path\", path));\n  if (httpOnly) parts.push(\"HttpOnly\");\n  if (secure) parts.push(\"Secure\");\n  if (sameSite !== undefined) {\n    const normalised = SAME_SITE[String(sameSite).toLowerCase()];\n    if (!normalised) throw new TypeError(\"Invalid SameSite value: \" + sameSite);\n    // Browsers reject SameSite=None cookies that are not Secure.\n    if (normalised === \"None\" && !secure) throw new Error(\"SameSite=None requires the Secure attribute\");\n    parts.push(\"SameSite=\" + normalised);\n  }\n  return parts.join(\"; \");\n}\n\nexport function parseCookies(header: string): Map<string, string> {\n  const cookies = new Map<string, string>();\n  for (const pair of header.split(\";\")) {\n    const eq = pair.indexOf(\"=\");\n    if (eq === -1) continue; // no \"=\": not a cookie\n    const name = pair.slice(0, eq).trim();\n    if (!name || cookies.has(name)) continue; // the first occurrence wins\n    let value = pair.slice(eq + 1).trim();\n    if (value.length >= 2 && value.startsWith(''\"'') && value.endsWith(''\"'')) value = value.slice(1, -1);\n    try {\n      value = decodeURIComponent(value);\n    } catch (error) {\n      // malformed percent-encoding: keep the raw value\n    }\n    cookies.set(name, value);\n  }\n  return cookies;\n}\n"}'::jsonb),
  ('deep-freeze-lock-props', null::text[], '{"en":"`Object.freeze` makes an object''s own properties non-writable and non-configurable and stops new ones being added, but a nested object is just a value, so it stays mutable. A deep version has to walk the graph, and three details matter: a `WeakSet` of visited objects (so cycles and shared children are processed once and don''t loop forever; checking `Object.isFrozen` instead would wrongly skip the children of an object frozen earlier), `Reflect.ownKeys` (to include symbols and non-enumerable keys, which `Object.keys` misses), and reading property **descriptors** rather than `node[key]`, so accessors aren''t executed. `lockProps` shows the finer-grained tool: `writable: false` stops value changes, and `configurable: false` stops deleting or redefining the property, so you need both for a truly fixed field (setting only `configurable: false` still lets a writable value change). In strict mode, writes to such properties throw a `TypeError`; in sloppy mode they fail silently. Note that `Map`, `Set` and `Date` keep their data in internal slots, which freezing cannot protect.","uk":"`Object.freeze` робить власні властивості об''єкта незаписуваними й неконфігурованими та забороняє додавати нові, але вкладений об''єкт це лише значення, тож він залишається змінюваним. Глибока версія мусить обходити граф, і важливі три деталі: `WeakSet` відвіданих об''єктів (щоб цикли та спільні дочірні об''єкти оброблялися раз і не зациклювалися; перевірка `Object.isFrozen` натомість помилково пропустила б нащадків раніше замороженого об''єкта), `Reflect.ownKeys` (щоб охопити символи й неперелічувані ключі, яких `Object.keys` не бачить) і читання **дескрипторів** властивостей замість `node[key]`, щоб аксесори не виконувалися. `lockProps` показує тонший інструмент: `writable: false` зупиняє зміну значення, а `configurable: false` зупиняє видалення чи перевизначення властивості, тож для справді незмінного поля потрібні обидва (одного `configurable: false` замало, записуване значення все одно можна змінити). У строгому режимі запис у такі властивості кидає `TypeError`, у нестрогому мовчки не діє. Зауважте, що `Map`, `Set` і `Date` тримають дані у внутрішніх слотах, яких заморозка не захищає."}'::jsonb, '{"/src/freeze.ts":"export function deepFreeze<T>(value: T): Readonly<T> {\n  const seen = new WeakSet<object>(); // makes cycles and shared references safe\n\n  const visit = (node: unknown): void => {\n    if (node === null || typeof node !== \"object\" || seen.has(node)) return;\n    seen.add(node);\n    Object.freeze(node);\n    // Reflect.ownKeys includes symbols and non-enumerable keys.\n    for (const key of Reflect.ownKeys(node)) {\n      const descriptor = Object.getOwnPropertyDescriptor(node, key)!;\n      // Read the descriptor, not node[key]: accessor properties must never be invoked.\n      if (\"value\" in descriptor) visit(descriptor.value);\n    }\n  };\n\n  visit(value);\n  return value;\n}\n\nexport function lockProps<T extends object>(obj: T, ...keys: (keyof T)[]): T {\n  for (const key of keys) {\n    if (!Object.prototype.hasOwnProperty.call(obj, key)) {\n      throw new TypeError(\"Cannot lock missing property: \" + String(key));\n    }\n    Object.defineProperty(obj, key, { writable: false, configurable: false });\n  }\n  return obj;\n}\n"}'::jsonb),
  ('react-refactor-status-table', null::text[], '{"en":"This is the shape of a typical \"find what''s wrong\" review. (1) `useState(props.rows.map(...))` only uses the prop on the first render, so later changes are ignored: derive values from props and state while rendering (add `useMemo` only if it is measurably expensive), and don''t copy props into state. (2) Calling `track()` in the body is a side effect in render, which React may run many times; it belongs in `useEffect(..., [])` (and in StrictMode development you will see it twice, by design). (3) A component declared inside another is a *new type* on every render, so React unmounts and remounts it, destroying state and DOM, and the lookup tables or helpers are also rebuilt each time; declare components at module level and pass data as props. (4) With `key={index}`, when the list is filtered React matches rows by position, so a row''s local state can jump to a different item; a stable `id` identifies each row. (5) A `const` object (or a small function) beats a chain of conditions, and the `hasOwnProperty` check prevents `STATUS[\"constructor\"]` returning a function. An `enum` would be overkill here since the values are only used for display.","uk":"Так виглядає типове рев''ю «знайди, що не так». (1) `useState(props.rows.map(...))` використовує проп лише на першому рендері, тож пізніші зміни ігноруються: обчислюйте значення з пропсів і стану під час рендеру (`useMemo` додавайте лише коли це помітно дорого) і не копіюйте пропси в стан. (2) Виклик `track()` у тілі це побічний ефект у рендері, який React може виконати багато разів; йому місце в `useEffect(..., [])` (а в розробці зі StrictMode ви побачите його двічі, і це задумано). (3) Компонент, оголошений усередині іншого, є *новим типом* на кожному рендері, тож React розмонтовує й монтує його знову, знищуючи стан і DOM, а таблиці пошуку чи помічники теж перебудовуються щоразу; оголошуйте компоненти на рівні модуля й передавайте дані пропсами. (4) З `key={index}` при фільтрації React зіставляє рядки за позицією, тож локальний стан рядка може «перестрибнути» на інший елемент; стабільний `id` ідентифікує кожен рядок. (5) `const`-об''єкт (або невелика функція) кращий за ланцюжок умов, а перевірка `hasOwnProperty` не дає `STATUS[\"constructor\"]` повернути функцію. `enum` тут був би надмірним, бо значення потрібні лише для показу."}'::jsonb, '{"/StatusTable.tsx":"import { useEffect, useMemo, useState } from \"react\";\nimport { track } from \"./analytics\";\nimport type { RawRow } from \"./data\";\n\nconst STATUS = { ok: \"Operational\", warn: \"Degraded\", fail: \"Down\" } as const;\n\nconst labelOf = (status: string) =>\n  Object.prototype.hasOwnProperty.call(STATUS, status) ? STATUS[status as keyof typeof STATUS] : \"Unknown\";\n\n// Declared at module level: one stable component type, so rows keep their state across renders.\nfunction Row({ row }: { row: RawRow }) {\n  const [open, setOpen] = useState(false);\n  return (\n    <>\n      <tr data-testid={\"row-\" + row.id}>\n        <td>{row.name}</td>\n        <td>{labelOf(row.status)}</td>\n        <td>\n          <button type=\"button\" aria-expanded={open} onClick={() => setOpen((o) => !o)}>\n            Details\n          </button>\n        </td>\n      </tr>\n      {open && (\n        <tr>\n          <td colSpan={3} data-testid={\"details-\" + row.id}>\n            Details for {row.name}\n          </td>\n        </tr>\n      )}\n    </>\n  );\n}\n\nexport function StatusTable({ rows }: { rows: RawRow[] }) {\n  const [query, setQuery] = useState(\"\");\n\n  // A side effect belongs in an effect, with [] so it runs once per mount, not once per render.\n  useEffect(() => {\n    track(\"table_opened\");\n  }, []);\n\n  // Derived from props and state during render: no copy of props in state, so new rows show up.\n  const visible = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return rows.filter((r) => r.name.toLowerCase().includes(q));\n  }, [rows, query]);\n\n  return (\n    <section>\n      <label htmlFor=\"q\">Filter services</label>\n      <input id=\"q\" value={query} onChange={(e) => setQuery(e.target.value)} />\n      {visible.length === 0 ? (\n        <p>No services match</p>\n      ) : (\n        <table>\n          <tbody>\n            {visible.map((row) => (\n              <Row key={row.id} row={row} />\n            ))}\n          </tbody>\n        </table>\n      )}\n    </section>\n  );\n}\n"}'::jsonb),
  ('plugin-command-dispatcher', null::text[], '{"en":"The core keeps plugins behind a narrow interface: load, unload, execute and history. Validation happens at load time so that execute can assume a well-formed registry. Timing wraps the awaited call, and the log is written in both the success and failure paths, which is why the error is recorded and then rethrown. Returning a copy from history keeps callers from mutating the log.","uk":"Ядро тримає плагіни за вузьким інтерфейсом: load, unload, execute і history. Перевірка відбувається під час load, тож execute може вважати реєстр коректним. Вимір часу обгортає очікуваний виклик, а запис робиться і в разі успіху, і в разі помилки, тому помилка спершу журналюється, а потім перекидається далі. Повернення копії з history не дає викликачам змінювати журнал."}'::jsonb, '{"/src/dispatcher.ts":"export interface CommandDef {\n  id: string;\n  name: string;\n  run(payload?: unknown): unknown;\n}\n\nexport interface PluginDef {\n  id: string;\n  version: string;\n  commands: CommandDef[];\n}\n\nexport interface CallRecord {\n  commandId: string;\n  pluginId: string;\n  status: \"success\" | \"error\";\n  startedAt: number;\n  finishedAt: number;\n  error?: string;\n}\n\nexport interface Dispatcher {\n  load(plugin: PluginDef): void;\n  unload(pluginId: string): void;\n  execute(pluginId: string, commandId: string, payload?: unknown): Promise<unknown>;\n  history(): CallRecord[];\n}\n\nexport function createDispatcher(now: () => number = Date.now): Dispatcher {\n  const plugins = new Map<string, PluginDef>();\n  const calls: CallRecord[] = [];\n\n  return {\n    load(plugin) {\n      if (plugins.has(plugin.id)) throw new Error(\"plugin already loaded: \" + plugin.id);\n      const seen = new Set<string>();\n      for (const command of plugin.commands) {\n        if (seen.has(command.id)) throw new Error(\"duplicate command id: \" + command.id);\n        seen.add(command.id);\n      }\n      plugins.set(plugin.id, plugin);\n    },\n    unload(pluginId) {\n      plugins.delete(pluginId);\n    },\n    async execute(pluginId, commandId, payload) {\n      const plugin = plugins.get(pluginId);\n      if (!plugin) throw new Error(\"unknown plugin: \" + pluginId);\n      const command = plugin.commands.find((c) => c.id === commandId);\n      if (!command) throw new Error(\"unknown command: \" + commandId);\n\n      const startedAt = now();\n      try {\n        const result = await command.run(payload);\n        calls.push({ commandId, pluginId, status: \"success\", startedAt, finishedAt: now() });\n        return result;\n      } catch (err) {\n        const error = err instanceof Error ? err.message : String(err);\n        calls.push({ commandId, pluginId, status: \"error\", startedAt, finishedAt: now(), error });\n        throw err;\n      }\n    },\n    history() {\n      return calls.slice();\n    },\n  };\n}\n"}'::jsonb),
  ('plugin-manifest-validation', null::text[], '{"en":"Treat uploaded data as hostile: check its shape before trusting any field, and keep only the fields you know about so that extra keys cannot slip into storage. Collecting all errors (instead of stopping at the first) gives the uploader a complete list in one attempt. Normalizing at the end means the rest of the system only ever sees the trimmed, validated shape.","uk":"Вважайте завантажені дані ворожими: перевіряйте форму, перш ніж довіряти якомусь полю, і залишайте лише відомі поля, щоб зайві ключі не потрапили в сховище. Збір усіх помилок (замість зупинки на першій) дає авторові повний список за одну спробу. Нормалізація в кінці означає, що решта системи бачить лише обрізану, перевірену форму."}'::jsonb, '{"/src/manifest.ts":"export interface Manifest {\n  id: string;\n  version: string;\n  commands: { id: string; name: string }[];\n}\n\nexport type ValidationResult = { ok: true; manifest: Manifest } | { ok: false; errors: string[] };\n\nconst SLUG = /^[a-z][a-z0-9-]*$/;\nconst SEMVER = /^\\d+\\.\\d+\\.\\d+$/;\nconst TOP_FIELDS = [\"id\", \"version\", \"commands\"];\nconst COMMAND_FIELDS = [\"id\", \"name\"];\n\nconst isRecord = (v: unknown): v is Record<string, unknown> => typeof v === \"object\" && v !== null && !Array.isArray(v);\n\nexport function validateManifest(input: unknown): ValidationResult {\n  if (!isRecord(input)) return { ok: false, errors: [\"manifest must be an object\"] };\n\n  const errors: string[] = [];\n\n  for (const key of Object.keys(input)) {\n    if (!TOP_FIELDS.includes(key)) errors.push(\"unknown field: \" + key);\n  }\n  if (typeof input.id !== \"string\" || !SLUG.test(input.id)) errors.push(\"id must be a lowercase slug\");\n  if (typeof input.version !== \"string\" || !SEMVER.test(input.version)) errors.push(\"version must be x.y.z\");\n\n  if (!Array.isArray(input.commands) || input.commands.length === 0) {\n    errors.push(\"commands must be a non-empty array\");\n  } else {\n    const seen = new Set<string>();\n    input.commands.forEach((raw: unknown, i: number) => {\n      if (!isRecord(raw)) {\n        errors.push(\"command \" + i + \" must be an object\");\n        return;\n      }\n      for (const key of Object.keys(raw)) {\n        if (!COMMAND_FIELDS.includes(key)) errors.push(\"command \" + i + \" has unknown field: \" + key);\n      }\n      if (typeof raw.id !== \"string\" || !SLUG.test(raw.id)) {\n        errors.push(\"command \" + i + \" id must be a lowercase slug\");\n      } else if (seen.has(raw.id)) {\n        errors.push(\"duplicate command id: \" + raw.id);\n      } else {\n        seen.add(raw.id);\n      }\n      if (typeof raw.name !== \"string\" || raw.name.trim() === \"\") {\n        errors.push(\"command \" + i + \" name must be a non-empty string\");\n      }\n    });\n  }\n\n  if (errors.length > 0) return { ok: false, errors };\n\n  const commands = (input.commands as Record<string, unknown>[]).map((c) => ({\n    id: c.id as string,\n    name: (c.name as string).trim(),\n  }));\n  return { ok: true, manifest: { id: input.id as string, version: input.version as string, commands } };\n}\n"}'::jsonb),
  ('symbol-iterator-protocol', array['b']::text[], '{"en":"A symbol is a unique primitive, and `Symbol.iterator` is a built-in one that the language looks up when it needs to iterate. Objects that define a method under this key work with for...of, spread and destructuring. Symbols do not make a property private: `Object.getOwnPropertySymbols` still reveals them.","uk":"Символ це унікальний примітив, а `Symbol.iterator` вбудований; мова шукає його, коли потрібно перебрати значення. Об''єкти, що визначають метод під цим ключем, працюють з for...of, spread і деструктуризацією. Символи не роблять властивість приватною: `Object.getOwnPropertySymbols` їх усе одно показує."}'::jsonb, null::jsonb),
  ('bind-call-apply-this', array['b']::text[], '{"en":"`call` and `apply` invoke the function right away with the given `this` (arguments as a list, or as an array for `apply`). `bind` returns a new function whose `this` is fixed. A bound function keeps its original `this` even if you bind it again.","uk":"`call` і `apply` одразу викликають функцію з заданим `this` (аргументи списком, а для `apply` масивом). `bind` повертає нову функцію з фіксованим `this`. Прив''язана функція зберігає початковий `this`, навіть якщо її прив''язати повторно."}'::jsonb, null::jsonb),
  ('typescript-numeric-enum-output', array['c']::text[], '{"en":"A numeric enum compiles to an object that maps names to values and values back to names, which is why `Color[0]` gives `\"Red\"`. String enums do not get the reverse mapping. Interfaces and type aliases are erased entirely, and classes stay classes.","uk":"Числовий enum компілюється в об''єкт, який зіставляє назви зі значеннями і значення назад із назвами, тому `Color[0]` дає `\"Red\"`. У строкових enum зворотного зіставлення немає. Інтерфейси і псевдоніми типів повністю стираються, а класи лишаються класами."}'::jsonb, null::jsonb),
  ('interface-declaration-merging', array['a']::text[], '{"en":"Interfaces support declaration merging, so repeated declarations add members together. Type aliases do not merge; declaring the same `type` name twice is an error. This is one of the practical differences between `interface` and `type` that the interview touched on.","uk":"Інтерфейси підтримують злиття оголошень, тож повторні оголошення додають члени разом. Псевдоніми типів не зливаються: двічі оголосити одне й те саме ім''я `type` це помилка. Це одна з практичних відмінностей між `interface` і `type`."}'::jsonb, null::jsonb),
  ('filter-callback-arguments', array['d']::text[], '{"en":"`filter`, like `map`, `forEach` and `reduce`, passes the current element, its index and the array being traversed. The third argument is the source array, not the result, which is only built from the callback''s return values.","uk":"`filter`, як і `map`, `forEach` та `reduce`, передає поточний елемент, його індекс і масив, по якому йде обхід. Третій аргумент це вихідний масив, а не результат; результат формується лише з того, що повертає колбек."}'::jsonb, null::jsonb),
  ('event-loop-order-node', array['b']::text[], '{"en":"Synchronous code runs first (A, E). Then Node drains the `process.nextTick` queue (D), before promise callbacks (C). The `setTimeout` callback is a macrotask that runs last (B). In the browser `process.nextTick` does not exist, which is why the interview asked where it is available.","uk":"Спершу виконується синхронний код (A, E). Далі Node виконує чергу `process.nextTick` (D), перед колбеками промісів (C). Колбек `setTimeout` це макрозадача, яка йде останньою (B). У браузері `process.nextTick` немає, тому це питання про те, де він доступний."}'::jsonb, null::jsonb),
  ('nestjs-request-pipeline-order', array['d']::text[], '{"en":"Request flow in NestJS is: middleware, guards, interceptors (before part), pipes, then the handler. After the handler, interceptors run again on the response, and exception filters handle errors. Knowing the order tells you where authentication, validation and logging belong.","uk":"Потік запиту в NestJS такий: middleware, guards, interceptors (частина до), pipes, потім обробник. Після обробника interceptors знову працюють з відповіддю, а exception filters обробляють помилки. Знання порядку підказує, де мають бути автентифікація, валідація та логування."}'::jsonb, null::jsonb),
  ('nestjs-pipes-purpose', array['d']::text[], '{"en":"Pipes receive the route arguments and either transform them (for example parse a string into a number) or validate them and throw. Exception filters handle errors, and guards decide access. Validation and transformation are the two usual answers for pipes.","uk":"Pipes отримують аргументи маршруту і або перетворюють їх (наприклад, рядок у число), або валідують і викидають помилку. Exception filters обробляють помилки, а guards вирішують доступ. Для pipes типові дві відповіді: валідація і трансформація."}'::jsonb, null::jsonb),
  ('solid-liskov-substitution', array['c']::text[], '{"en":"A subtype should keep the contract of its parent: it may add behaviour, but it must not strengthen preconditions, weaken postconditions or throw where the parent does not. A classic violation is a `Square` that extends `Rectangle` and breaks the width/height contract. The other four principles are the single responsibility, interface segregation and dependency inversion ones.","uk":"Підтип має зберігати контракт батька: він може додати поведінку, але не може посилити передумови, послабити постумови або викидати винятки там, де батько цього не робить. Класичне порушення це `Square`, що наслідує `Rectangle` і ламає контракт ширини й висоти. Решта принципів SOLID це єдина відповідальність, розділення інтерфейсів та інверсія залежностей."}'::jsonb, null::jsonb),
  ('shared-database-microservices', array['a']::text[], '{"en":"Services that share tables share their data model, so the database becomes the hidden integration point. Each service should own its data, and other services should get it through APIs or published events. Events on Kafka help only if the data is not also shared through the database.","uk":"Сервіси, що ділять таблиці, ділять і модель даних, тож база стає прихованою точкою інтеграції. Кожен сервіс має володіти своїми даними, а інші мають отримувати їх через API або опубліковані події. Події в Kafka допомагають лише тоді, коли дані не діляться через базу."}'::jsonb, null::jsonb),
  ('plugin-isolation-untrusted-code', array['b']::text[], '{"en":"Uploaded code should never share the core''s memory or privileges. Isolation (containers, separate workers or processes) limits what a plugin can reach, and a narrow command interface limits what it can ask the core to do. Sanitizing the upload and checking its manifest are still needed, but they are not a sandbox on their own.","uk":"Завантажений код ніколи не повинен мати спільну пам''ять або привілеї з ядром. Ізоляція (контейнери, окремі worker або процеси) обмежує, до чого плагін може дістатися, а вузький інтерфейс команд обмежує, що він може попросити ядро зробити. Санітизація і перевірка маніфесту все ще потрібні, але самі по собі вони не є пісочницею."}'::jsonb, null::jsonb),
  ('command-call-log-schema', array['d']::text[], '{"en":"A call row references the command and the external system it was sent to, records its outcome and timing, and stores the error when it fails. Foreign keys are enough to get the plugin and system back, so there is no need to duplicate configuration or code on every row. This is the one-to-many relationship the interview sketched out.","uk":"Рядок виклику посилається на команду і зовнішню систему, куди її надіслано, фіксує результат і час, а при збої зберігає помилку. Зовнішні ключі дозволяють відновити плагін і систему, тож немає потреби дублювати конфігурацію чи код у кожному рядку. Це зв''язок «один до багатьох», який накидали на співбесіді."}'::jsonb, null::jsonb),
  ('solid-srp', array['a']::text[], '{"en":"Responsibility means a reason to change: one concern or one stakeholder. A component that fetches data, applies business rules and renders has at least three. It''s not about counting methods or functions; a module can have many methods that all serve the same purpose.","uk":"Обов''язок означає причину для змін: одну задачу чи одну зацікавлену сторону. Компонент, що отримує дані, застосовує бізнес-правила й рендерить, має щонайменше три. Ідеться не про кількість методів чи функцій; модуль може мати багато методів, які служать одній меті."}'::jsonb, null::jsonb),
  ('solid-srp-component', array['a']::text[], '{"en":"Each part now changes for one reason: the API (hook), finance rules (pure functions, easy to unit-test), or design (table). Splitting markup alone keeps the responsibilities tangled, a catch-all `utils.ts` just moves the problem, and memoisation is about performance, not design.","uk":"Тепер кожна частина змінюється з однієї причини: API (хук), фінансові правила (чисті функції, які легко тестувати) чи дизайн (таблиця). Розбиття лише розмітки лишає обов''язки переплутаними, загальний `utils.ts` просто переносить проблему, а мемоізація стосується продуктивності, а не дизайну."}'::jsonb, null::jsonb),
  ('solid-ocp', array['a']::text[], '{"en":"Open/closed means new behaviour is added by adding code, not by editing working code in many places. A registry like `paymentMethods: Record<Method, PaymentMethod>` with `charge`, `refund` and `label` keeps the checkout closed for modification: a new method is one new entry.","uk":"Відкритість/закритість означає, що нова поведінка додається новим кодом, а не правками робочого коду в багатьох місцях. Реєстр на кшталт `paymentMethods: Record<Method, PaymentMethod>` з `charge`, `refund` і `label` лишає оформлення замовлення закритим для змін: новий спосіб є одним новим записом."}'::jsonb, null::jsonb),
  ('solid-lsp-square', array['a']::text[], '{"en":"`resize` relies on the rectangle contract: setting the height doesn''t change the width. `Square` keeps its own invariant by changing both, so the final `setHeight(4)` also sets the width to 4. A subtype that can''t be substituted for its base without surprising callers violates LSP. Model squares and rectangles as separate (possibly immutable) shapes instead.","uk":"`resize` покладається на контракт прямокутника: зміна висоти не змінює ширину. `Square` зберігає власний інваріант, змінюючи обидві, тож останній `setHeight(4)` також встановлює ширину 4. Підтип, який не можна підставити замість бази, не здивувавши викликачів, порушує LSP. Моделюйте квадрати й прямокутники як окремі (можливо, незмінні) фігури."}'::jsonb, null::jsonb),
  ('solid-isp', array['a']::text[], '{"en":"Interface segregation: clients shouldn''t be forced to depend on methods they don''t use. Implementations that throw \"not supported\" also break substitutability. Small role interfaces let `LocalCache` implement only `KeyValue`, while code that needs querying asks for `Queryable` explicitly. Optional methods and runtime checks push the problem onto every caller.","uk":"Розділення інтерфейсів: клієнти не повинні залежати від методів, якими не користуються. Реалізації, що кидають «не підтримується», ще й порушують замінність. Невеликі рольові інтерфейси дають `LocalCache` реалізувати лише `KeyValue`, а код, якому потрібні запити, явно просить `Queryable`. Необов''язкові методи й перевірки під час виконання перекладають проблему на кожного викликача."}'::jsonb, null::jsonb),
  ('solid-dip', array['a']::text[], '{"en":"Without inversion, business logic (`ReportService`) imports concrete infrastructure (`PostgresRepo`), so changes and tests ripple upwards. With it, the service declares an interface (`ReportRepo`) it needs, and the composition root wires a concrete implementation. Dependency injection is the usual mechanism.","uk":"Без інверсії бізнес-логіка (`ReportService`) імпортує конкретну інфраструктуру (`PostgresRepo`), тож зміни й тести поширюються вгору. З інверсією сервіс оголошує потрібний йому інтерфейс (`ReportRepo`), а корінь композиції під''єднує конкретну реалізацію. Звичайний механізм для цього: впровадження залежностей."}'::jsonb, null::jsonb),
  ('solid-lsp-contract', array['a']::text[], '{"en":"A subtype may accept more and promise more, but not demand more or deliver less. Rejecting inputs the base accepted (a stronger precondition) breaks callers that were written against the base. Caching keeps the contract, extra methods don''t affect existing callers, and a more specific return type still satisfies `Response`.","uk":"Підтип може приймати більше й обіцяти більше, але не може вимагати більшого чи давати менше. Відмова від вхідних даних, які приймала база (сильніша передумова), ламає викликачів, написаних під базу. Кешування зберігає контракт, додаткові методи не впливають на наявних викликачів, а конкретніший тип результату все одно задовольняє `Response`."}'::jsonb, null::jsonb),
  ('solid-yagni', array['a']::text[], '{"en":"Abstractions have a cost: more files, indirection and names to learn. With one implementation, the factory and registry solve a problem that doesn''t exist yet. SOLID helps when change actually happens; until then KISS and YAGNI win. Extracting an interface later, when a second channel arrives, is a small, safe refactor.","uk":"Абстракції мають ціну: більше файлів, непрямості й назв, які треба вивчити. З однією реалізацією фабрика й реєстр розв''язують проблему, якої ще немає. SOLID допомагає, коли зміни справді стаються; доти перемагають KISS і YAGNI. Виділити інтерфейс пізніше, коли з''явиться другий канал, є невеликим і безпечним рефакторингом."}'::jsonb, null::jsonb),
  ('solid-spot-violations', array['a', 'b', 'd']::text[], '{"en":"The service has many reasons to change (SRP). A subclass that throws from an inherited method can''t stand in for its base (LSP). Repeated type switches for a frequently growing set of cases force edits everywhere (OCP). Injecting a `Clock` is dependency inversion done right, and narrow props are interface segregation.","uk":"Сервіс має багато причин для змін (SRP). Підклас, що кидає помилку з успадкованого методу, не може заступити базу (LSP). Повторювані switch за типом для набору випадків, що часто росте, вимагають правок усюди (OCP). Впровадження `Clock` є правильною інверсією залежностей, а вузькі пропси є розділенням інтерфейсів."}'::jsonb, null::jsonb),
  ('solid-pricing-rules', null::text[], '{"en":"The engine depends only on the `PricingRule` abstraction (dependency inversion), so adding a promotion means writing a new rule object (open/closed) instead of editing a growing function. Each rule has one job (single responsibility) and can be unit-tested alone. Computing every rule from the original subtotal makes results independent of rule order, and rounding in one place avoids floating-point drift.","uk":"Рушій залежить лише від абстракції `PricingRule` (інверсія залежностей), тож нова акція означає новий об''єкт-правило (відкритість/закритість), а не правки функції, що постійно росте. Кожне правило має одну задачу (єдиний обов''язок) і тестується окремо. Обчислення кожного правила від початкової суми робить результат незалежним від порядку правил, а округлення в одному місці запобігає накопиченню похибок."}'::jsonb, '{"/src/pricing.ts":"export type Line = { sku: string; price: number; qty: number; category: string };\nexport type Order = { lines: Line[]; tier: \"regular\" | \"gold\"; coupon?: string };\nexport type Adjustment = { rule: string; amount: number };\nexport type Quote = { subtotal: number; adjustments: Adjustment[]; total: number };\n\n/** A pricing rule returns an adjustment (negative = discount, positive = fee, 0 = not applicable). */\nexport interface PricingRule {\n  readonly name: string;\n  apply(order: Order, subtotal: number): number;\n}\n\nconst cents = (n: number) => Math.round(n * 100) / 100;\n\n/** The engine knows nothing about specific discounts: new rules plug in without editing it. */\nexport function createPricing(rules: PricingRule[]) {\n  return {\n    quote(order: Order): Quote {\n      const subtotal = cents(order.lines.reduce((sum, l) => sum + l.price * l.qty, 0));\n      const adjustments = rules\n        .map((rule) => ({ rule: rule.name, amount: cents(rule.apply(order, subtotal)) }))\n        .filter((a) => a.amount !== 0);\n      const total = Math.max(0, cents(subtotal + adjustments.reduce((sum, a) => sum + a.amount, 0)));\n      return { subtotal, adjustments, total };\n    },\n  };\n}\n\nexport const goldMember: PricingRule = {\n  name: \"gold-member\",\n  apply: (order, subtotal) => (order.tier === \"gold\" ? -subtotal * 0.1 : 0),\n};\n\nexport const bookBundle: PricingRule = {\n  name: \"book-bundle\",\n  apply: (order) => -5 * order.lines.filter((l) => l.category === \"books\" && l.qty >= 3).length,\n};\n\nexport function coupon(code: string, amount: number): PricingRule {\n  const normalized = code.toUpperCase();\n  return {\n    name: \"coupon:\" + normalized,\n    apply: (order) => (order.coupon?.toUpperCase() === normalized ? -amount : 0),\n  };\n}\n"}'::jsonb),
  ('sort-n-log-n', array['c']::text[], '{"en":"Merge sort always splits the input in half (log n levels) and merges each level in O(n). Bubble, insertion and selection sort are O(n²) in the worst case, although insertion sort is fast on small or nearly sorted inputs.","uk":"Сортування злиттям завжди ділить дані навпіл (log n рівнів) і зливає кожен рівень за O(n). Сортування бульбашкою, вставками й вибором мають O(n²) у найгіршому випадку, хоча сортування вставками швидке на малих або майже відсортованих даних."}'::jsonb, null::jsonb),
  ('sort-random-shuffle', array['b']::text[], '{"en":"Sorting algorithms assume a consistent comparator (if a < b and b < c, then a < c). A random one breaks that, and the result depends on the engine''s algorithm, which gives a strongly non-uniform distribution. Use Fisher–Yates: walk from the end and swap each element with a random index at or before it, which is O(n) and unbiased.","uk":"Алгоритми сортування розраховують на узгоджений компаратор (якщо a < b і b < c, то a < c). Випадковий порушує це, і результат залежить від алгоритму рушія, що дає дуже нерівномірний розподіл. Використовуйте Фішера–Єйтса: ідіть з кінця й міняйте кожен елемент з випадковим індексом не далі за нього — це O(n) і без упередження."}'::jsonb, null::jsonb),
  ('sort-external', array['b']::text[], '{"en":"External merge sort reads memory-sized chunks, sorts each in RAM and writes sorted runs to disk. A k-way merge then streams all runs at once, using a min-heap of the current head of each run to output records in order. Disk access stays sequential, which is what makes it fast. Timestamps have far too large a range for counting sort.","uk":"Зовнішнє сортування злиттям читає частини розміром із пам''ять, сортує кожну в RAM і записує відсортовані серії на диск. Потім k-шляхове злиття читає всі серії потоково, використовуючи мін-купу з поточних перших елементів серій, щоб виводити записи по порядку. Доступ до диска лишається послідовним — саме це робить підхід швидким. Діапазон міток часу завеликий для сортування підрахунком."}'::jsonb, null::jsonb),
  ('sort-by-keys', null::text[], '{"en":"One comparator walks the keys in priority order and returns the first non-zero comparison, flipping the sign for descending keys. `Array.prototype.sort` is guaranteed stable since ES2019, so returning 0 for full ties keeps the input order. Copying with `[...items]` avoids mutating the caller''s array (or use `toSorted`).","uk":"Один компаратор проходить ключі за пріоритетом і повертає перше ненульове порівняння, змінюючи знак для спадних ключів. `Array.prototype.sort` гарантовано стабільний з ES2019, тож повернення 0 для повних збігів зберігає вхідний порядок. Копія через `[...items]` не дає змінити масив викликача (або використайте `toSorted`)."}'::jsonb, '{"/src/sort-by.ts":"export type SortKey<T> = { key: keyof T; dir?: \"asc\" | \"desc\" };\n\nfunction compareValues(a: unknown, b: unknown): number {\n  if (typeof a === \"number\" && typeof b === \"number\") return a - b;\n  return String(a).localeCompare(String(b));\n}\n\nexport function sortBy<T>(items: T[], keys: SortKey<T>[]): T[] {\n  return [...items].sort((a, b) => {\n    for (const { key, dir = \"asc\" } of keys) {\n      const result = compareValues(a[key], b[key]);\n      if (result !== 0) return dir === \"desc\" ? -result : result;\n    }\n    return 0;\n  });\n}\n"}'::jsonb),
  ('sort-stability', array['a']::text[], '{"en":"Stability is about ties. It lets you sort by a secondary key, then by a primary key, and keep the secondary order inside each primary group. `Array.prototype.sort` has been stable since ES2019.","uk":"Стабільність стосується рівних елементів. Вона дозволяє відсортувати за другорядним ключем, потім за основним і зберегти другорядний порядок усередині кожної групи. `Array.prototype.sort` стабільний з ES2019."}'::jsonb, null::jsonb),
  ('sort-quick-worst', array['a']::text[], '{"en":"On sorted input the first element is the minimum, so each partition peels off only one element and recursion depth becomes n. Random or median-of-three pivots make this practically impossible.","uk":"На відсортованих даних перший елемент є мінімумом, тож кожне розбиття відокремлює лише один елемент, і глибина рекурсії стає n. Випадковий опорний елемент або медіана трьох роблять це практично неможливим."}'::jsonb, null::jsonb),
  ('sort-lower-bound', array['b']::text[], '{"en":"The O(n log n) lower bound applies only to comparison sorts. With a tiny key range, count how many times each score occurs (101 buckets) and write them out in order: linear time.","uk":"Нижня межа O(n log n) стосується лише сортувань порівнянням. Коли діапазон ключів крихітний, порахуйте, скільки разів трапляється кожен бал (101 комірка), і випишіть їх по порядку: лінійний час."}'::jsonb, null::jsonb),
  ('sort-multi-key', array['a']::text[], '{"en":"When ages differ, `a.age - b.age` is non-zero and decides the order. When they''re equal it''s 0 (falsy), so `||` falls through to the name comparison. Comparators must return numbers, not booleans.","uk":"Коли вік різний, `a.age - b.age` ненульове й визначає порядок. Коли однаковий, результат 0 (хибне значення), тож `||` переходить до порівняння імен. Компаратор має повертати числа, а не булеві значення."}'::jsonb, null::jsonb),
  ('sort-merge-memory', array['b']::text[], '{"en":"Heapsort guarantees O(n log n) worst case with O(1) extra memory (in place). Merge sort needs O(n) buffers, quicksort''s worst case is O(n²), and counting sort needs a small key range.","uk":"Пірамідальне сортування гарантує O(n log n) у найгіршому випадку з O(1) додаткової пам''яті (на місці). Злиття потребує буферів O(n), найгірший випадок quicksort дорівнює O(n²), а сортування підрахунком вимагає малого діапазону ключів."}'::jsonb, null::jsonb),
  ('sort-merge-sort', null::text[], '{"en":"Split in half, sort each half recursively, and merge by repeatedly taking the smaller head. Taking from the right half only when it''s *strictly* smaller keeps ties in input order, which makes the sort stable. Depth is log n with O(n) work per level, so O(n log n) total, with O(n) extra memory.","uk":"Розділіть навпіл, рекурсивно відсортуйте кожну половину й злийте, щоразу беручи менший перший елемент. Беріть із правої половини лише коли він *строго* менший: так рівні елементи зберігають вхідний порядок, і сортування стабільне. Глибина log n і O(n) роботи на рівень дають разом O(n log n) з O(n) додаткової пам''яті."}'::jsonb, '{"/src/mergeSort.ts":"export function mergeSort<T>(items: T[], compare: (a: T, b: T) => number): T[] {\n  if (items.length <= 1) return items.slice();\n  const mid = items.length >> 1;\n  const left = mergeSort(items.slice(0, mid), compare);\n  const right = mergeSort(items.slice(mid), compare);\n\n  const out: T[] = [];\n  let i = 0;\n  let j = 0;\n  while (i < left.length && j < right.length) {\n    // Take from the right only if strictly smaller: ties keep left first (stable).\n    if (compare(right[j], left[i]) < 0) out.push(right[j++]);\n    else out.push(left[i++]);\n  }\n  while (i < left.length) out.push(left[i++]);\n  while (j < right.length) out.push(right[j++]);\n  return out;\n}\n"}'::jsonb),
  ('sql-where-vs-having', array['a']::text[], '{"en":"`WHERE` filters individual rows **before** grouping, so aggregates don''t exist yet there. `HAVING` filters groups **after** `GROUP BY`, which is where `count(*)` is known. Use `WHERE` for row conditions (it also makes the query cheaper) and `HAVING` only for conditions on aggregates.","uk":"`WHERE` фільтрує окремі рядки **до** групування, тож агрегатів там ще немає. `HAVING` фільтрує групи **після** `GROUP BY`, де `count(*)` уже відомий. Використовуйте `WHERE` для умов на рядки (так запит ще й дешевший), а `HAVING` лише для умов на агрегати."}'::jsonb, null::jsonb),
  ('sql-null-equals', array['a']::text[], '{"en":"`NULL` means \"unknown\", so `deleted_at = NULL` evaluates to `NULL` (unknown) for every row, even when `deleted_at` is `NULL`. `WHERE` keeps only rows where the condition is **true**. Use `deleted_at IS NULL`, or `IS NOT DISTINCT FROM` to compare two values that may both be `NULL`.","uk":"`NULL` означає «невідомо», тож `deleted_at = NULL` дає `NULL` (невідомо) для кожного рядка, навіть коли `deleted_at` дорівнює `NULL`. `WHERE` лишає тільки рядки, де умова **істинна**. Використовуйте `deleted_at IS NULL` або `IS NOT DISTINCT FROM`, щоб порівняти два значення, які обидва можуть бути `NULL`."}'::jsonb, null::jsonb),
  ('sql-left-join-rows', array['a']::text[], '{"en":"A join produces one row per matching pair, so a user with two orders appears twice. `LEFT JOIN` additionally keeps left rows without any match, filling the right side with `NULL`s, which is why Bob appears once. An `INNER JOIN` would return 3 rows (no Bob), and a `CROSS JOIN` would return 3 × 3 = 9.","uk":"З''єднання дає по рядку на кожну відповідну пару, тож користувач із двома замовленнями з''являється двічі. `LEFT JOIN` додатково зберігає ліві рядки без збігу, заповнюючи праву частину `NULL`, тому Bob з''являється один раз. `INNER JOIN` повернув би 3 рядки (без Bob), а `CROSS JOIN` повернув би 3 × 3 = 9."}'::jsonb, null::jsonb),
  ('sql-count-variants', array['a']::text[], '{"en":"`count(*)` counts rows, whatever they contain. `count(email)` counts only non-`NULL` values. `count(DISTINCT email)` also removes duplicates, leaving `a@x.io` and `b@x.io`. Aggregates other than `count(*)` skip `NULL`s, so `avg(score)` averages only the known scores.","uk":"`count(*)` рахує рядки, незалежно від їхнього вмісту. `count(email)` рахує лише значення, що не є `NULL`. `count(DISTINCT email)` ще й прибирає дублікати, лишаючи `a@x.io` і `b@x.io`. Агрегати, окрім `count(*)`, пропускають `NULL`, тож `avg(score)` усереднює лише відомі оцінки."}'::jsonb, null::jsonb),
  ('sql-alias-in-where', array['a']::text[], '{"en":"Logically a query runs `FROM` → `WHERE` → `GROUP BY` → `HAVING` → `SELECT` → `ORDER BY` → `LIMIT`. Aliases are created in `SELECT`, so `WHERE` can''t see them, but `ORDER BY` can. Write `WHERE price * qty > 100`, or wrap the query in a subquery or CTE and filter on `total` outside.","uk":"Логічно запит виконується так: `FROM` → `WHERE` → `GROUP BY` → `HAVING` → `SELECT` → `ORDER BY` → `LIMIT`. Псевдоніми створюються в `SELECT`, тож `WHERE` їх не бачить, а `ORDER BY` бачить. Напишіть `WHERE price * qty > 100` або обгорніть запит у підзапит чи CTE і фільтруйте за `total` ззовні."}'::jsonb, null::jsonb),
  ('sql-injection', array['a']::text[], '{"en":"With a parameterised query the driver sends the SQL text and the values separately, so input can never change the query''s structure, whatever characters it contains. Hand-written escaping misses edge cases (encodings, backslashes, other contexts), and client-side validation is trivially bypassed. Column names can''t be parameters; map them through an allow-list.","uk":"У параметризованому запиті драйвер надсилає текст SQL і значення окремо, тож дані ніколи не змінять структуру запиту, хоч які символи вони містять. Саморобне екранування пропускає крайні випадки (кодування, зворотні слеші, інші контексти), а перевірку на клієнті легко обійти. Назви стовпців не можуть бути параметрами; пропускайте їх крізь білий список."}'::jsonb, null::jsonb),
  ('sql-left-join-where-trap', array['a']::text[], '{"en":"For users without matching orders, `o.status` is `NULL`, and `NULL = ''paid''` isn''t true, so `WHERE` drops them, which makes the query behave like an inner join. A condition in `ON` decides which orders match while still keeping every user: `LEFT JOIN orders o ON o.user_id = u.id AND o.status = ''paid''`. (`LEFT OUTER JOIN` is the same thing as `LEFT JOIN`.)","uk":"Для користувачів без відповідних замовлень `o.status` дорівнює `NULL`, а `NULL = ''paid''` не є істинним, тож `WHERE` їх відкидає, і запит поводиться як внутрішнє з''єднання. Умова в `ON` визначає, які замовлення підходять, і при цьому зберігає кожного користувача: `LEFT JOIN orders o ON o.user_id = u.id AND o.status = ''paid''`. (`LEFT OUTER JOIN` означає те саме, що й `LEFT JOIN`.)"}'::jsonb, null::jsonb),
  ('sql-index-expression', array['a']::text[], '{"en":"An index on `email` stores the raw values, so it can''t answer a question about `lower(email)`: the database would have to compute `lower` for every row. Index the expression itself (or store emails normalised, or use the case-insensitive `citext` type). The same applies to casts and other functions wrapped around indexed columns.","uk":"Індекс на `email` зберігає сирі значення, тож не може відповісти на питання про `lower(email)`: базі довелося б обчислити `lower` для кожного рядка. Проіндексуйте сам вираз (або зберігайте email нормалізованими чи використайте нечутливий до регістру тип `citext`). Те саме стосується приведень типів та інших функцій навколо індексованих стовпців."}'::jsonb, null::jsonb),
  ('sql-not-in-null', array['a']::text[], '{"en":"`x NOT IN (1, 2, NULL)` means `x <> 1 AND x <> 2 AND x <> NULL`. The last comparison is `NULL` (unknown), so the whole condition is never true and every row is filtered out. Use `WHERE NOT EXISTS (SELECT 1 FROM employees r WHERE r.manager_id = e.id)`, or filter `NULL`s out of the subquery.","uk":"`x NOT IN (1, 2, NULL)` означає `x <> 1 AND x <> 2 AND x <> NULL`. Останнє порівняння дає `NULL` (невідомо), тож уся умова ніколи не буває істинною, і кожен рядок відкидається. Використайте `WHERE NOT EXISTS (SELECT 1 FROM employees r WHERE r.manager_id = e.id)` або відфільтруйте `NULL` у підзапиті."}'::jsonb, null::jsonb),
  ('sql-query-builder', null::text[], '{"en":"Keeping the query as a list of text chunks and value slots, and numbering placeholders only when `text` is read, is what makes nested fragments compose: each fragment doesn''t need to know its position in the final query. Values travel separately to the database, so no input can alter the SQL. Identifiers can''t be parameters, so they''re validated against a strict pattern and quoted. Libraries such as `postgres`, `slonik` and Prisma''s `$queryRaw` work this way.","uk":"Зберігання запиту як списку текстових шматків і місць для значень із нумерацією заповнювачів лише під час читання `text` дає змогу комбінувати вкладені фрагменти: кожен фрагмент не мусить знати свою позицію в остаточному запиті. Значення йдуть до бази окремо, тож жодні дані не змінять SQL. Ідентифікатори не можуть бути параметрами, тому їх перевіряють за суворим шаблоном і беруть у лапки. Так працюють бібліотеки `postgres`, `slonik` і `$queryRaw` у Prisma."}'::jsonb, '{"/src/sql.ts":"type Chunk = string | { value: unknown };\n\nexport class Sql {\n  constructor(readonly chunks: readonly Chunk[]) {}\n\n  /** SQL text with $1, $2, … placeholders, numbered across nested fragments. */\n  get text(): string {\n    let n = 0;\n    return this.chunks.map((c) => (typeof c === \"string\" ? c : \"$\" + ++n)).join(\"\");\n  }\n\n  get values(): unknown[] {\n    return this.chunks.filter((c): c is { value: unknown } => typeof c !== \"string\").map((c) => c.value);\n  }\n}\n\nexport function sql(strings: TemplateStringsArray, ...values: unknown[]): Sql {\n  const chunks: Chunk[] = [strings[0]];\n  values.forEach((value, i) => {\n    if (value instanceof Sql) {\n      chunks.push(...value.chunks); // nested fragment: keep its parameters, renumber later\n    } else if (Array.isArray(value)) {\n      if (value.length === 0) throw new RangeError(\"Can''t build an empty IN () list\");\n      chunks.push(\"(\");\n      value.forEach((item, j) => {\n        if (j > 0) chunks.push(\", \");\n        chunks.push({ value: item });\n      });\n      chunks.push(\")\");\n    } else if (value === undefined) {\n      throw new TypeError(\"Value #\" + (i + 1) + \" is undefined\");\n    } else {\n      chunks.push({ value }); // values never become part of the SQL text\n    }\n    chunks.push(strings[i + 1]);\n  });\n  return new Sql(chunks);\n}\n\nexport function identifier(name: string): Sql {\n  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) throw new Error(\"Invalid identifier: \" + name);\n  return new Sql([''\"'' + name + ''\"'']);\n}\n"}'::jsonb),
  ('state-context-rerenders', array['a']::text[], '{"en":"`useContext` subscribes to the whole value; a new object means every consumer re-renders. Split rarely and frequently changing data into separate contexts, memoize the provider value, or use a store with selector subscriptions (Zustand, Redux, `useSyncExternalStore`) so components re-render only when their slice changes.","uk":"`useContext` підписується на все значення; новий об''єкт означає перемальовування кожного споживача. Розділіть дані, що змінюються рідко й часто, на окремі контексти, мемоїзуйте значення провайдера або використайте сховище з підписками через селектори (Zustand, Redux, `useSyncExternalStore`), щоб компоненти перемальовувались лише при зміні їхнього зрізу."}'::jsonb, null::jsonb),
  ('state-normalize', array['b']::text[], '{"en":"Normalised state stores each entity once, keyed by id, and references it by id everywhere else, like database tables. Updates touch one place, lookups are O(1), and memoized selectors join the data for the UI. Redux Toolkit''s `createEntityAdapter` and query caches use this pattern.","uk":"Нормалізований стан зберігає кожну сутність один раз за ключем id і посилається на неї за id всюди, як таблиці бази даних. Оновлення торкаються одного місця, пошук — O(1), а мемоїзовані селектори поєднують дані для UI. Цей шаблон використовують `createEntityAdapter` у Redux Toolkit і кеші запитів."}'::jsonb, null::jsonb),
  ('state-optimistic-race', array['b']::text[], '{"en":"Responses can arrive in any order, so tag each mutation (a counter per item) and ignore responses from superseded requests, or cancel them with `AbortController`. On failure, roll back only if the failed request is still the latest. Debouncing makes the race less likely but doesn''t eliminate it. Libraries such as TanStack Query provide `onMutate`/rollback helpers for this.","uk":"Відповіді можуть надходити в будь-якому порядку, тож позначайте кожну мутацію (лічильник для кожного елемента) і ігноруйте відповіді від замінених запитів або скасовуйте їх через `AbortController`. При помилці відкочуйте лише тоді, коли невдалий запит досі останній. Debounce робить гонку менш імовірною, але не усуває її. Бібліотеки на кшталт TanStack Query мають для цього `onMutate` і засоби відкату."}'::jsonb, null::jsonb),
  ('state-create-store', null::text[], '{"en":"Keep listeners in a `Set` and notify from a copy (`[...listeners]`), so unsubscribing during notification can''t skip anyone. Skipping notification when the reducer returns the same object relies on immutable updates, which is why reducers must never mutate. `select` is just a subscriber that remembers the previous selected value and compares with `Object.is`, the same idea behind `useSelector` and `useSyncExternalStore`.","uk":"Тримайте слухачів у `Set` і сповіщайте з копії (`[...listeners]`), щоб відписка під час сповіщення нікого не пропустила. Пропуск сповіщення, коли редюсер повертає той самий об''єкт, спирається на незмінні оновлення — тому редюсери ніколи не мають змінювати стан. `select` — це просто підписник, що пам''ятає попереднє вибране значення й порівнює через `Object.is`; та сама ідея лежить в основі `useSelector` і `useSyncExternalStore`."}'::jsonb, '{"/src/store.ts":"export type Reducer<S, A> = (state: S, action: A) => S;\n\nexport function createStore<S, A>(reducer: Reducer<S, A>, initialState: S) {\n  let state = initialState;\n  const listeners = new Set<(state: S) => void>();\n\n  const subscribe = (listener: (state: S) => void) => {\n    listeners.add(listener);\n    return () => {\n      listeners.delete(listener);\n    };\n  };\n\n  return {\n    getState: () => state,\n    dispatch(action: A) {\n      const next = reducer(state, action);\n      if (Object.is(next, state)) return;\n      state = next;\n      for (const listener of [...listeners]) listener(state);\n    },\n    subscribe,\n    select<T>(selector: (state: S) => T, listener: (value: T) => void) {\n      let current = selector(state);\n      return subscribe((nextState) => {\n        const value = selector(nextState);\n        if (Object.is(value, current)) return;\n        current = value;\n        listener(value);\n      });\n    },\n  };\n}\n"}'::jsonb),
  ('state-derive-not-store', array['a']::text[], '{"en":"Duplicated state needs every update path to keep both values consistent, and sooner or later one forgets. Store the source of truth (`items`) and derive `total` in render or a memoised selector.","uk":"Продубльований стан вимагає, щоб кожен шлях оновлення тримав обидва значення узгодженими, і рано чи пізно якийсь шлях про це забуде. Зберігайте джерело правди (`items`) і обчислюйте `total` під час рендеру чи в мемоізованому селекторі."}'::jsonb, null::jsonb),
  ('state-mutation-bug', array['a']::text[], '{"en":"React''s `useReducer`, Redux and OnPush compare references. Returning the same object tells them nothing changed. Return new objects along the changed path: `{ ...state, todos: state.todos.map(t => t.id === id ? { ...t, done: !t.done } : t) }`.","uk":"`useReducer` у React, Redux і OnPush порівнюють посилання. Повернення того самого об''єкта повідомляє, що нічого не змінилося. Повертайте нові об''єкти вздовж зміненого шляху: `{ ...state, todos: state.todos.map(t => t.id === id ? { ...t, done: !t.done } : t) }`."}'::jsonb, null::jsonb),
  ('state-server-cache', array['a']::text[], '{"en":"Server data is a cache of someone else''s state: it needs deduplication, background refetching, invalidation and retries. Query libraries provide this, and hand-rolled copies in a client store tend to go stale.","uk":"Серверні дані є кешем чужого стану: їм потрібні дедуплікація, фонове оновлення, інвалідація й повторні спроби. Бібліотеки запитів дають це з коробки, а саморобні копії в клієнтському сторі зазвичай застарівають."}'::jsonb, null::jsonb),
  ('state-url-state', array['a']::text[], '{"en":"The URL is shareable, bookmarkable and survives reloads and back/forward navigation. Read filters from it (e.g. `useSearchParams`) as the single source of truth, rather than syncing a separate copy.","uk":"URL можна поширювати, додавати в закладки, і він переживає перезавантаження та навігацію назад/вперед. Читайте фільтри з нього (наприклад, `useSearchParams`) як із єдиного джерела правди, а не синхронізуйте окрему копію."}'::jsonb, null::jsonb),
  ('state-memoized-selector', array['a']::text[], '{"en":"`useSelector` compares the result with `===`. A fresh array is never equal to the previous one, so every dispatch triggers a render. A memoised selector returns the same array until `state.items` actually changes. Alternatively, select raw data and derive it in `useMemo`.","uk":"`useSelector` порівнює результат через `===`. Новий масив ніколи не дорівнює попередньому, тож кожне надсилання дії спричиняє рендер. Мемоізований селектор повертає той самий масив, доки `state.items` справді не зміниться. Як варіант, вибирайте сирі дані й обчислюйте похідні в `useMemo`."}'::jsonb, null::jsonb),
  ('state-cart-reducer', null::text[], '{"en":"Every branch returns new objects only along the changed path: `map` copies the one updated line and keeps the others by reference, `filter` and spread create new arrays, and nothing touches the old state. No-op actions return the original object so `===` checks skip work. The total is derived by a selector instead of being stored.","uk":"Кожна гілка повертає нові об''єкти лише вздовж зміненого шляху: `map` копіює один оновлений рядок і зберігає інші за посиланням, `filter` і spread створюють нові масиви, а старий стан ніхто не чіпає. Дії, що нічого не змінюють, повертають початковий об''єкт, щоб перевірки `===` пропускали роботу. Сума обчислюється селектором, а не зберігається."}'::jsonb, '{"/src/cart.ts":"export type Item = { id: string; name: string; price: number };\nexport type Line = Item & { qty: number };\nexport type Cart = { items: Line[] };\nexport type Action =\n  | { type: \"add\"; item: Item }\n  | { type: \"remove\"; id: string }\n  | { type: \"setQty\"; id: string; qty: number }\n  | { type: \"clear\" };\n\nexport const initialCart: Cart = { items: [] };\n\nexport function cartReducer(state: Cart, action: Action): Cart {\n  switch (action.type) {\n    case \"add\": {\n      const exists = state.items.some((l) => l.id === action.item.id);\n      return {\n        ...state,\n        items: exists\n          ? state.items.map((l) => (l.id === action.item.id ? { ...l, qty: l.qty + 1 } : l))\n          : [...state.items, { ...action.item, qty: 1 }],\n      };\n    }\n    case \"remove\": {\n      if (!state.items.some((l) => l.id === action.id)) return state;\n      return { ...state, items: state.items.filter((l) => l.id !== action.id) };\n    }\n    case \"setQty\": {\n      if (action.qty <= 0) return cartReducer(state, { type: \"remove\", id: action.id });\n      if (!state.items.some((l) => l.id === action.id)) return state;\n      return { ...state, items: state.items.map((l) => (l.id === action.id ? { ...l, qty: action.qty } : l)) };\n    }\n    case \"clear\":\n      return state.items.length ? { ...state, items: [] } : state;\n    default:\n      return state;\n  }\n}\n\nexport function selectTotal(state: Cart): number {\n  return state.items.reduce((sum, l) => sum + l.price * l.qty, 0);\n}\n"}'::jsonb),
  ('sd-cap-partition', array['c']::text[], '{"en":"With a partition, two sides can''t reliably coordinate. A system either refuses or delays requests to stay consistent, or answers from possibly stale replicas to stay available. Partition tolerance isn''t optional in a real network, which is why the practical choice is between C and A during a partition.","uk":"За розділу дві сторони не можуть надійно узгоджуватися. Система або відхиляє чи затримує запити, щоб лишатися узгодженою, або відповідає з, можливо, застарілих реплік, щоб лишатися доступною. Стійкість до розділів у реальній мережі не є необов''язковою, тому практичний вибір за розділу — між C і A."}'::jsonb, null::jsonb),
  ('sd-consistent-hashing', array['a']::text[], '{"en":"With modular hashing, changing N reassigns almost every key. On a ring, each key belongs to the next node clockwise, so adding a node only takes over the keys between it and its predecessor. Virtual nodes spread that load evenly across the ring.","uk":"За модульного хешування зміна N перепризначає майже всі ключі. На кільці кожен ключ належить наступному вузлу за годинниковою стрілкою, тож новий вузол забирає лише ключі між собою і своїм попередником. Віртуальні вузли рівномірно розподіляють це навантаження по кільцю."}'::jsonb, null::jsonb),
  ('sd-cache-aside', array['d']::text[], '{"en":"In cache-aside the application owns the logic: it reads the cache, falls back to the database on a miss, and writes the result back. Writes usually update the database and then delete or refresh the cached entry, so the cache doesn''t keep serving the old value.","uk":"У cache-aside логіку веде застосунок: він читає кеш, у разі промаху звертається до бази даних і записує результат назад. Записи зазвичай оновлюють базу, а потім видаляють або оновлюють запис у кеші, щоб кеш не віддавав старе значення."}'::jsonb, null::jsonb),
  ('sd-idempotency-key', array['b']::text[], '{"en":"The client can''t know whether the first request was processed, so it must retry. An idempotency key makes the retry safe: the server remembers the outcome of the first attempt for that key and replays it, so the side effect happens once. Keys must be stored durably and expire after a sensible window.","uk":"Клієнт не може знати, чи обробили перший запит, тому мусить повторити його. Ключ ідемпотентності робить повтор безпечним: сервер пам''ятає результат першої спроби для цього ключа і повертає його знову, тож побічний ефект відбувається один раз. Ключі мають зберігатися надійно і спливати через розумний проміжок часу."}'::jsonb, null::jsonb),
  ('sd-at-least-once', array['c']::text[], '{"en":"A broker that waits for acknowledgements can redeliver a message whose ack was lost, so duplicates are normal, not a bug. Exactly-once processing across a network is not achievable in general, so the practical approach is at-least-once delivery combined with idempotent handlers, for example by storing processed message IDs.","uk":"Брокер, що чекає підтверджень, може повторно доставити повідомлення, підтвердження якого загубилося, тож дублікати — це норма, а не помилка. Точної доставки один раз через мережу загалом не досягти, тому практичний підхід — доставка принаймні один раз разом з ідемпотентними обробниками, наприклад зі зберіганням ідентифікаторів оброблених повідомлень."}'::jsonb, null::jsonb),
  ('sd-saga-compensation', array['b']::text[], '{"en":"Two-phase commit across independent services holds locks while every participant votes, which blocks throughput and fails badly when a coordinator crashes. A saga breaks the work into local transactions, each committed on its own, and defines a compensating action for each step, such as refunding a payment when the reservation fails. The trade-off is that the system is briefly inconsistent and the compensation must be correct.","uk":"Двофазний коміт між незалежними сервісами тримає блокування, поки кожен учасник голосує, що знижує пропускну здатність і погано ламається, коли координатор падає. Сага розбиває роботу на локальні транзакції, кожна з яких фіксується окремо, і визначає компенсуючу дію для кожного кроку, наприклад повернення платежу, коли резервування не вдалося. Ціна в тому, що система на короткий час неузгоджена, а компенсація має бути правильною."}'::jsonb, null::jsonb),
  ('sd-circuit-breaker-open', array['c']::text[], '{"en":"A breaker stops the damage from spreading: callers stop waiting on a dead dependency, threads and connections are freed, and the struggling service isn''t buried under retries. After a timeout it lets a few trial requests through (half-open) and closes again only if they succeed. Retrying every request, as one option suggests, does the opposite and amplifies the load.","uk":"Запобіжник не дає збою поширюватися: викликачі перестають чекати на мертву залежність, звільняються потоки й з''єднання, а сервіс, що не справляється, не завалюють повторами. Після тайм-ауту він пропускає кілька пробних запитів (half-open) і замикається знову, лише якщо вони успішні. Повторювати кожен запит, як пропонує один з варіантів, означає робити навпаки і посилювати навантаження."}'::jsonb, null::jsonb),
  ('sd-hot-shard', array['a']::text[], '{"en":"Monotonic keys send all current writes to one range, so one shard does almost all the work while the others sit idle. Hashing spreads writes evenly, though it makes range queries across shards harder. Choosing a key means balancing write distribution against the queries you need to run.","uk":"Монотонно зростаючі ключі надсилають усі поточні записи в один діапазон, тож один шард робить майже всю роботу, а інші простоюють. Хешування рівномірно розподіляє записи, хоча ускладнює запити за діапазоном між шардами. Вибір ключа — це баланс між рівномірністю записів і запитами, які треба виконувати."}'::jsonb, null::jsonb),
  ('sd-quorum-overlap', array['b']::text[], '{"en":"With five replicas, three acknowledged the write and any three read replicas must include at least one of them (3 + 3 > 5), so the read sees the newest value. The overlap guarantees freshness only while the write succeeded; a failed or partial write, and sloppy quorum options, weaken this, which is why the exact rules matter.","uk":"За п''яти реплік три підтвердили запис, і будь-які три репліки для читання мусять містити принаймні одну з них (3 + 3 > 5), тож читання бачить найновіше значення. Перетин гарантує свіжість, лише якщо запис пройшов успішно; невдалий чи частковий запис і «нестрогі» кворуми це послаблюють, тому точні правила важливі."}'::jsonb, null::jsonb),
  ('sd-fencing-token', array['b']::text[], '{"en":"A lock can expire while its holder is paused, and the holder can''t tell. A fencing token makes stale writes detectable at the resource itself: every grant carries a larger number, and the storage rejects requests carrying an older one. Clocks can''t provide this, which is why the check belongs at the resource rather than in the lock service.","uk":"Блокування може закінчитися, поки його власник зупинений, і власник цього не помітить. Токен огородження робить застарілі записи видимими на самому ресурсі: кожна видача несе більше число, а сховище відхиляє запити зі старішим. Годинники такого не забезпечують, тому перевірка має бути на ресурсі, а не в службі блокувань."}'::jsonb, null::jsonb),
  ('sd-consistent-hash-ring', null::text[], '{"en":"Modular hashing reassigns almost every key when the server count changes, because `hash mod N` depends on N. On a ring both keys and servers hash onto the same circle, and a key belongs to the next server clockwise, so a change only affects the arc between the new or removed server and its neighbour. Virtual nodes (many points per server) smooth out the arcs, so one server doesn''t own a disproportionate share. Sorting the points once on change keeps `get` at O(log n) with a binary search. Production systems add weights per server and replicate each key to the next few distinct nodes on the ring. The hash function matters too: plain FNV-1a placed names like \"a#1\" and \"a#2\" close together, which skewed the load until a final mixing step was added.","uk":"Модульне хешування перепризначає майже всі ключі, коли змінюється кількість серверів, бо `hash mod N` залежить від N. На кільці і ключі, і сервери хешуються на те саме коло, а ключ належить наступному серверу за годинниковою стрілкою, тож зміна впливає лише на дугу між новим чи видаленим сервером і його сусідом. Віртуальні вузли (багато точок на сервер) вирівнюють дуги, тож один сервер не отримує непропорційної частки. Сортування точок під час зміни тримає `get` на O(log n) через бінарний пошук. У продакшені сервери мають ваги, а кожен ключ реплікується на кілька наступних різних вузлів кільця. Хеш також важливий: звичайний FNV-1a розміщував близькі назви на кшталт \"a#1\" і \"a#2\" поруч, через що навантаження перекошувалося, доки не додали фінальний крок змішування."}'::jsonb, '{"/src/ring.ts":"/** A stable 32-bit string hash: FNV-1a, then a final mixing step so similar names (a#1, a#2) land far apart. */\nexport function hash(text: string): number {\n  let h = 0x811c9dc5;\n  for (let i = 0; i < text.length; i++) {\n    h ^= text.charCodeAt(i);\n    h = Math.imul(h, 0x01000193) >>> 0;\n  }\n  h ^= h >>> 16;\n  h = Math.imul(h, 0x85ebca6b);\n  h ^= h >>> 13;\n  h = Math.imul(h, 0xc2b2ae35);\n  h ^= h >>> 16;\n  return h >>> 0;\n}\n\nexport function createRing(initialNodes: string[] = [], replicas = 100) {\n  let points: Array<{ hash: number; node: string }> = [];\n  const nodes = new Set<string>();\n\n  const add = (node: string): void => {\n    if (nodes.has(node)) return;\n    nodes.add(node);\n    // Each node gets many points, so load spreads evenly and a node''s share is small when it joins or leaves.\n    for (let i = 0; i < replicas; i++) points.push({ hash: hash(node + \"#\" + i), node });\n    points.sort((a, b) => a.hash - b.hash || (a.node < b.node ? -1 : a.node > b.node ? 1 : 0));\n  };\n\n  const remove = (node: string): void => {\n    if (!nodes.delete(node)) return;\n    points = points.filter((p) => p.node !== node);\n  };\n\n  initialNodes.forEach(add);\n\n  return {\n    add,\n    remove,\n    get(key: string): string | null {\n      if (points.length === 0) return null;\n      const h = hash(key);\n      // Binary search for the first point at or after h; past the end, wrap to the first point.\n      let lo = 0;\n      let hi = points.length;\n      while (lo < hi) {\n        const mid = (lo + hi) >> 1;\n        if (points[mid].hash < h) lo = mid + 1;\n        else hi = mid;\n      }\n      return points[lo === points.length ? 0 : lo].node;\n    },\n    nodes(): string[] {\n      return [...nodes].sort();\n    },\n  };\n}\n"}'::jsonb),
  ('sd-token-bucket', null::text[], '{"en":"The bucket refills by elapsed time instead of running a timer: on every call it adds `elapsed * refillPerSecond` tokens, capped at capacity, and records the new time. That''s O(1) per request and needs no background work, which is why it''s the usual choice. Keeping tokens fractional means slow rates still accumulate, and flooring only in `available()` keeps the public numbers whole. Taking tokens all-or-nothing matters for batch requests: a rejected request should not burn tokens. `retryAfterMs` gives clients a `Retry-After` value, so they back off instead of hammering the endpoint. In production the bucket usually lives in a shared store such as Redis, updated atomically, so every server enforces the same limit.","uk":"Кошик поповнюється за минулим часом, без таймера: при кожному виклику він додає `elapsed * refillPerSecond` токенів, обмежених ємністю, і запам''ятовує новий час. Це O(1) на запит і не потребує фонової роботи, тому його зазвичай обирають. Дробові токени дають повільним швидкостям накопичуватися, а округлення лише в `available()` тримає публічні числа цілими. Усе-або-нічого важливо для пакетних запитів: відхилений запит не має витрачати токени. `retryAfterMs` дає клієнтам значення для `Retry-After`, тож вони відступають, а не б''ють по ендпоінту. У продакшені кошик зазвичай живе в спільному сховищі, як Redis, з атомарними оновленнями, щоб кожен сервер застосовував однаковий ліміт."}'::jsonb, '{"/src/bucket.ts":"export type BucketOptions = { capacity: number; refillPerSecond: number; now?: () => number };\n\nexport function createTokenBucket({ capacity, refillPerSecond, now = () => Date.now() }: BucketOptions) {\n  // Tokens are fractional so slow refill rates still add up; callers only ever see whole tokens.\n  let tokens = capacity;\n  let last = now();\n\n  const refill = () => {\n    const t = now();\n    const elapsedSeconds = (t - last) / 1000;\n    if (elapsedSeconds > 0) {\n      tokens = Math.min(capacity, tokens + elapsedSeconds * refillPerSecond);\n      last = t;\n    }\n  };\n\n  return {\n    available(): number {\n      refill();\n      return Math.floor(tokens);\n    },\n    tryTake(n = 1): boolean {\n      refill();\n      if (n > tokens) return false; // all-or-nothing: a rejected request takes no tokens\n      tokens -= n;\n      return true;\n    },\n    retryAfterMs(n = 1): number {\n      refill();\n      if (n <= tokens) return 0;\n      if (n > capacity) return Infinity; // the bucket can never hold that many\n      return Math.ceil(((n - tokens) / refillPerSecond) * 1000);\n    },\n  };\n}\n"}'::jsonb),
  ('sd-first-step', array['a']::text[], '{"en":"Requirements drive every later decision: whether SEO matters (rendering strategy), how many items there are (virtualisation), whether real-time or offline support is needed. Spending the first few minutes clarifying and writing them down also gives you a checklist and shows structured thinking.","uk":"Вимоги визначають кожне подальше рішення: чи важливе SEO (стратегія рендерингу), скільки елементів (віртуалізація), чи потрібні реальний час чи офлайн-підтримка. Кілька перших хвилин на уточнення й запис вимог також дають вам чекліст і показують структуроване мислення."}'::jsonb, null::jsonb),
  ('sd-cursor-pagination', array['a']::text[], '{"en":"With an offset, five new posts at the top push everything down, so \"items 40–59\" now contains five items the user already saw. A cursor (the last seen ID or timestamp) asks for \"items after this one\", which stays stable. It''s also faster for databases with large offsets. The trade-off: you can''t jump to page 37.","uk":"Зі зсувом п''ять нових дописів угорі зсувають усе вниз, тож «елементи 40–59» тепер містять п''ять уже побачених. Курсор (останній побачений ID чи час) просить «елементи після цього», що лишається стабільним. Для баз даних він також швидший на великих зсувах. Компроміс: перейти одразу на сторінку 37 не вийде."}'::jsonb, null::jsonb),
  ('sd-optimistic-update', array['a']::text[], '{"en":"Optimistic updates assume success for low-risk, reversible actions, so the UI responds in the same frame. Keep the previous value to roll back on error, de-duplicate rapid toggles, and reconcile with the server''s response (the real count may differ). Don''t do this for actions where failure is common or costly, like payments.","uk":"Оптимістичні оновлення припускають успіх для малоризикових, оборотних дій, тож інтерфейс реагує в тому ж кадрі. Зберігайте попереднє значення для відкату при помилці, усувайте дублювання швидких перемикань і звіряйтеся з відповіддю сервера (справжній лічильник може відрізнятися). Не робіть так для дій, де невдача часта чи дорога, як-от платежі."}'::jsonb, null::jsonb),
  ('sd-virtualization', array['a']::text[], '{"en":"The cost is in the number of DOM nodes and layout, not in re-renders, so memoisation doesn''t help much. Windowing keeps the DOM small regardless of data size. It breaks Ctrl+F for off-screen rows and needs care for screen readers (`aria-rowcount`, `aria-rowindex`) and dynamic heights. Pagination or `content-visibility: auto` are lighter alternatives.","uk":"Вартість у кількості DOM-вузлів і розкладці, а не в повторних рендерах, тож мемоізація мало допомагає. Віконний рендеринг тримає DOM малим незалежно від обсягу даних. Він ламає Ctrl+F для рядків поза екраном і потребує уваги до зчитувачів екрана (`aria-rowcount`, `aria-rowindex`) і змінної висоти. Легші альтернативи: пагінація чи `content-visibility: auto`."}'::jsonb, null::jsonb),
  ('sd-autocomplete-race', array['a']::text[], '{"en":"Network responses can arrive in any order. Aborting saves bandwidth, and tracking a request ID (or comparing against the current query) guarantees that a late response can''t overwrite newer results, even if the server ignores cancellation. Debounce reduces the number of requests but can''t prevent the race on its own.","uk":"Мережеві відповіді можуть приходити в будь-якому порядку. Скасування заощаджує трафік, а відстеження ID запиту (чи порівняння з поточним запитом) гарантує, що пізня відповідь не перезапише новіші результати, навіть якщо сервер ігнорує скасування. Debounce зменшує кількість запитів, але сам по собі гонитві не запобігає."}'::jsonb, null::jsonb),
  ('sd-new-items-banner', array['a']::text[], '{"en":"Content moving on its own is disorienting and hurts CLS and accessibility. Buffer the new items, show a banner announced politely to screen readers (`aria-live`), and on click insert them and move focus/scroll to the top. Items arriving when the user is already at the top can be inserted directly.","uk":"Вміст, що рухається сам по собі, дезорієнтує й погіршує CLS і доступність. Буферизуйте нові елементи, показуйте банер, ввічливо оголошений для зчитувачів екрана (`aria-live`), а по кліку вставляйте їх і переносіть фокус чи прокрутку вгору. Елементи, що приходять, коли користувач і так угорі, можна вставляти одразу."}'::jsonb, null::jsonb),
  ('sd-autocomplete', null::text[], '{"en":"Every input first cancels everything in progress: the debounce timer, the in-flight request (via `AbortController`), and, by bumping a request counter, any response that''s still on its way. A response is applied only if its ID is still the latest, which handles servers that ignore cancellation. Short queries and cache hits short-circuit before the timer, so they''re instant. The result is a small state machine that a UI can subscribe to.","uk":"Кожне введення спершу скасовує все, що триває: таймер debounce, запит у дорозі (через `AbortController`) і, завдяки збільшенню лічильника запитів, будь-яку відповідь, що ще в дорозі. Відповідь застосовується, лише якщо її ID досі останній, що працює й із серверами, які ігнорують скасування. Короткі запити й влучання в кеш обробляються до таймера, тож миттєві. У результаті виходить невеликий скінченний автомат, на який може підписатися інтерфейс."}'::jsonb, '{"/src/autocomplete.ts":"export type SearchFn = (query: string, signal: AbortSignal) => Promise<string[]>;\nexport type AutocompleteState = { query: string; results: string[]; status: \"idle\" | \"loading\" | \"done\" | \"error\" };\nexport type AutocompleteOptions = { debounceMs?: number; minChars?: number };\n\nexport function createAutocomplete(search: SearchFn, options: AutocompleteOptions = {}) {\n  const { debounceMs = 200, minChars = 2 } = options;\n  let state: AutocompleteState = { query: \"\", results: [], status: \"idle\" };\n  const listeners = new Set<(s: AutocompleteState) => void>();\n  const cache = new Map<string, string[]>();\n  let timer: ReturnType<typeof setTimeout> | undefined;\n  let controller: AbortController | null = null;\n  let requestId = 0;\n\n  const set = (patch: Partial<AutocompleteState>) => {\n    state = { ...state, ...patch };\n    for (const listener of [...listeners]) listener(state);\n  };\n\n  /** Drops the pending debounce and the in-flight request; bumping the id makes any late result stale. */\n  const cancel = () => {\n    clearTimeout(timer);\n    controller?.abort();\n    controller = null;\n    requestId++;\n  };\n\n  function run(query: string) {\n    const id = ++requestId;\n    controller = new AbortController();\n    const { signal } = controller;\n    set({ status: \"loading\" });\n    search(query, signal).then(\n      (results) => {\n        if (id !== requestId) return; // a newer input superseded this request\n        controller = null;\n        cache.set(query, results);\n        set({ results, status: \"done\" });\n      },\n      () => {\n        if (id !== requestId || signal.aborted) return;\n        controller = null;\n        set({ results: [], status: \"error\" });\n      },\n    );\n  }\n\n  return {\n    get state() {\n      return state;\n    },\n    subscribe(listener: (s: AutocompleteState) => void) {\n      listeners.add(listener);\n      return () => {\n        listeners.delete(listener);\n      };\n    },\n    input(query: string) {\n      cancel();\n      const q = query.trim();\n      if (q.length < minChars) {\n        set({ query, results: [], status: \"idle\" });\n        return;\n      }\n      const cached = cache.get(q);\n      if (cached) {\n        set({ query, results: cached, status: \"done\" });\n        return;\n      }\n      set({ query });\n      timer = setTimeout(() => run(q), debounceMs);\n    },\n  };\n}\n"}'::jsonb),
  ('tw-jit-scanning', array['a']::text[], '{"en":"Tailwind''s JIT engine reads your content files as text and emits only the utilities it finds, which keeps CSS small. It doesn''t execute your code, so a class assembled from parts never appears in the text it scans. Keep full class names in the source, for example by mapping states to complete class strings in an object.","uk":"Рушій JIT у Tailwind читає ваші файли вмісту як текст і видає лише знайдені утиліти, тож CSS лишається маленьким. Він не виконує ваш код, тому клас, зібраний з частин, ніколи не з''являється в тексті, який він сканує. Записуйте повні назви класів у вихідному коді, наприклад, зіставляючи стани з повними рядками класів у об''єкті."}'::jsonb, null::jsonb),
  ('tw-responsive-prefixes', array['a']::text[], '{"en":"Unprefixed utilities apply everywhere, and each prefix applies from its breakpoint upward (`min-width` queries). That''s mobile-first: set the small-screen default, then add changes for larger screens. Writing `md:` only ever adds or overrides at medium and up, so you never need to undo styles for phones.","uk":"Утиліти без префікса застосовуються скрізь, а кожен префікс — від свого брейкпоінта вгору (запити `min-width`). Це мобільний підхід: задайте стиль для малих екранів, а потім додайте зміни для більших. `md:` завжди додає або перевизначає лише від середнього розміру і вище, тому стилі для телефонів ніколи не треба скасовувати."}'::jsonb, null::jsonb),
  ('tw-utility-first', array['a']::text[], '{"en":"Each utility does one thing and comes from the theme scale. Unlike inline styles, utilities support variants (hover, breakpoints, dark mode) and share consistent values; unlike component libraries, Tailwind provides building blocks rather than finished components.","uk":"Кожна утиліта робить одну річ і бере значення зі шкали теми. На відміну від інлайн-стилів, утиліти підтримують варіанти (hover, контрольні точки, темна тема) і мають узгоджені значення; на відміну від бібліотек компонентів, Tailwind дає будівельні блоки, а не готові компоненти."}'::jsonb, null::jsonb),
  ('tw-responsive-prefix', array['a']::text[], '{"en":"Tailwind is mobile-first: unprefixed utilities apply everywhere, and `md:` means \"from 768px up\". So `w-full` applies on small screens and `md:w-1/2` overrides it from `md`. There''s no `max-` meaning unless you use `max-md:`.","uk":"Tailwind працює за принципом mobile-first: утиліти без префікса діють усюди, а `md:` означає «від 768px і ширше». Тож `w-full` діє на малих екранах, а `md:w-1/2` перекриває його від `md`. Значення «до певної ширини» з''являється лише з `max-md:`."}'::jsonb, null::jsonb),
  ('tw-dynamic-classes', array['a']::text[], '{"en":"The scanner reads files as plain text and never runs your code. Map values to complete class names (`{ red: \"bg-red-500\", green: \"bg-green-500\" }[color]`) so every class appears literally, or safelist them in configuration if they truly come from data.","uk":"Сканер читає файли як звичайний текст і ніколи не виконує ваш код. Зіставляйте значення з повними назвами класів (`{ red: \"bg-red-500\", green: \"bg-green-500\" }[color]`), щоб кожен клас було записано буквально, або додайте їх до safelist у конфігурації, якщо вони справді приходять із даних."}'::jsonb, null::jsonb),
  ('tw-class-conflicts', array['a']::text[], '{"en":"Both classes have the same specificity, so the cascade picks the one defined later in the CSS file, and the order of classes in the HTML attribute doesn''t matter. `tailwind-merge` removes conflicting utilities so the caller''s `px-2` replaces `px-4` reliably (usually combined with `clsx` in a `cn()` helper).","uk":"Обидва класи мають однакову специфічність, тож каскад обирає той, що визначений пізніше у файлі CSS, а порядок класів в атрибуті HTML не важливий. `tailwind-merge` прибирає конфліктні утиліти, тож `px-2` від викликача надійно замінює `px-4` (зазвичай разом із `clsx` у помічнику `cn()`)."}'::jsonb, null::jsonb),
  ('tw-group-hover', array['a']::text[], '{"en":"Mark the parent with `group`, then use `group-hover:` (or `group-focus-visible:`) on descendants. `hover:` on the icon only reacts when the pointer is over the icon itself. `peer` works for **following siblings** of the marked element, not for its children.","uk":"Позначте батька класом `group`, а для нащадків використайте `group-hover:` (або `group-focus-visible:`). `hover:` на іконці реагує лише тоді, коли вказівник над самою іконкою. `peer` працює для **наступних сусідів** позначеного елемента, а не для його дітей."}'::jsonb, null::jsonb),
  ('tw-apply-overuse', array['a']::text[], '{"en":"`@apply` is useful for a few base styles or markup you don''t control, but using it everywhere recreates the problems utility-first avoids: inventing names, keeping CSS and markup in sync, and changes in one class affecting many places. In component-based apps the component is the unit of reuse.","uk":"`@apply` корисний для кількох базових стилів чи розмітки, яку ви не контролюєте, але використання всюди відтворює проблеми, яких уникає utility-first: вигадування назв, синхронізація CSS і розмітки, вплив зміни одного класу на багато місць. У застосунках на компонентах одиницею повторного використання є компонент."}'::jsonb, null::jsonb),
  ('tp-call-site', array['a']::text[], '{"en":"`this` is a runtime binding, set fresh on every call by how the call is made. The same function can see a different `this` each time (`obj.fn()`, `fn()`, `fn.call(other)`). Only arrow functions take `this` lexically from where they''re written.","uk":"`this` є прив''язкою часу виконання, що встановлюється заново при кожному виклику залежно від способу виклику. Та сама функція може щоразу бачити інший `this` (`obj.fn()`, `fn()`, `fn.call(other)`). Лише стрілочні функції беруть `this` лексично, з місця, де їх написано."}'::jsonb, null::jsonb),
  ('tp-call-apply-bind', array['a']::text[], '{"en":"All three set `this` explicitly. `call` takes the arguments one by one, `apply` takes them as an array, and `bind` returns a new function with `this` (and here the first argument) fixed, which is then called with the rest.","uk":"Усі три явно встановлюють `this`. `call` приймає аргументи по одному, `apply` масивом, а `bind` повертає нову функцію з фіксованим `this` (і тут першим аргументом), яку потім викликають з рештою."}'::jsonb, null::jsonb),
  ('tp-arrow-callback', array['a']::text[], '{"en":"The arrow callback has no `this` of its own, so it uses the `this` of `startArrow`, which is `timer`: +3. The regular callback is called by `forEach` without a receiver, so its `this` is `undefined` in strict code (the guard skips the increment); in a sloppy script it would be the global object. Either way `timer` only gets the 3 from the arrow version.","uk":"Стрілочний колбек не має власного `this`, тож використовує `this` методу `startArrow`, тобто `timer`: +3. Звичайний колбек `forEach` викликає без отримувача, тож його `this` у строгому коді дорівнює `undefined` (перевірка пропускає збільшення); у нестрогому скрипті це був би глобальний об''єкт. Так чи інакше `timer` отримує лише 3 від стрілочної версії."}'::jsonb, null::jsonb),
  ('tp-binding-precedence', array['a']::text[], '{"en":"A bound function ignores the `this` passed to `call`, so explicit `bind` beats `call`: `a`. But `new` beats `bind`: `new BoundCtor(\"c\")` creates a fresh object as `this`, sets its `id` to `\"c\"`, and leaves `a` untouched. Precedence: `new` > `bind`/`call`/`apply` > method call > plain call.","uk":"Прив''язана функція ігнорує `this`, переданий через `call`, тож явний `bind` сильніший за `call`: `a`. Але `new` сильніший за `bind`: `new BoundCtor(\"c\")` створює новий об''єкт як `this`, встановлює його `id` у `\"c\"` і не чіпає `a`. Пріоритет: `new` > `bind`/`call`/`apply` > виклик методу > простий виклик."}'::jsonb, null::jsonb),
  ('tp-new-return', array['a']::text[], '{"en":"`new` creates an object, links it to the prototype, runs the constructor with that object as `this`, and returns it, unless the constructor returns another **object**, which then replaces it. A returned primitive like `\"ignored\"` is discarded. (In classes, returning an object works the same way.)","uk":"`new` створює об''єкт, прив''язує його до прототипу, виконує конструктор із цим об''єктом як `this` і повертає його, якщо конструктор не повертає інший **об''єкт**, який тоді його замінює. Повернений примітив на кшталт `\"ignored\"` відкидається. (У класах повернення об''єкта працює так само.)"}'::jsonb, null::jsonb),
  ('tp-shadowing', array['a']::text[], '{"en":"`child.count++` means `child.count = child.count + 1`. The read finds `1` on the prototype; the write then creates an **own** `count` on `child` (shadowing), leaving `base.count` unchanged. Reads delegate up the chain, but ordinary writes land on the object itself.","uk":"`child.count++` означає `child.count = child.count + 1`. Читання знаходить `1` у прототипі; потім запис створює **власну** `count` у `child` (затінення), не змінюючи `base.count`. Читання делегується вгору ланцюжком, а звичайний запис потрапляє на сам об''єкт."}'::jsonb, null::jsonb),
  ('tp-readonly-inherited', array['a']::text[], '{"en":"Normally a write creates an own property that shadows the prototype''s. But if the inherited property is non-writable, assignment is forbidden (a `TypeError` in strict code; silently ignored in sloppy scripts), so no own property is created. Shadowing still works with `Object.defineProperty`, which doesn''t consult the prototype.","uk":"Зазвичай запис створює власну властивість, що затіняє властивість прототипу. Але якщо успадкована властивість недоступна для запису, присвоєння заборонене (`TypeError` у строгому коді; мовчки ігнорується в нестрогих скриптах), тож власна властивість не створюється. Затінення все ще можливе через `Object.defineProperty`, що не зважає на прототип."}'::jsonb, null::jsonb),
  ('tp-prototype-property', array['a']::text[], '{"en":"`Dog.prototype` is just a property of the function, used as the prototype for objects created by `new Dog()`; instances don''t have a `.prototype` property themselves. Replacing `Dog.prototype` later doesn''t relink existing objects: `rex` still points at the old object, so `instanceof` (which compares against the current `Dog.prototype`) is `false`, and `bark` isn''t reachable.","uk":"`Dog.prototype` є просто властивістю функції, що стає прототипом об''єктів, створених через `new Dog()`; самі екземпляри не мають властивості `.prototype`. Заміна `Dog.prototype` пізніше не перепривʼязує наявні об''єкти: `rex` і далі вказує на старий об''єкт, тож `instanceof` (що порівнює з поточним `Dog.prototype`) дає `false`, а `bark` недосяжний."}'::jsonb, null::jsonb),
  ('tp-super-home-object', array['a']::text[], '{"en":"Unlike `this`, `super` isn''t decided by the call site. A method defined with method syntax remembers its **home object** (here `dog`), and `super.speak` means \"`speak` on the prototype of the home object\", i.e. `animal.speak`. Copying the method to `robot` doesn''t change that, so it never reaches robot''s own prototype. (`this` inside `animal.speak` would still be `robot`.)","uk":"На відміну від `this`, `super` не визначається місцем виклику. Метод, визначений синтаксисом методу, пам''ятає свій **домашній об''єкт** (тут `dog`), і `super.speak` означає «`speak` у прототипі домашнього об''єкта», тобто `animal.speak`. Копіювання методу в `robot` цього не змінює, тож він ніколи не дістається власного прототипу robot. (`this` усередині `animal.speak` усе одно був би `robot`.)"}'::jsonb, null::jsonb),
  ('tp-call-bind', null::text[], '{"en":"`myCall` turns explicit binding into implicit binding: storing `fn` under a fresh `Symbol` (non-enumerable, so nothing observes it) and calling `target[key]()` makes the object the call-site receiver; `finally` removes it again. `myBind` closes over `thisArg` and the preset arguments, so later calls can''t change them, and checks `new.target` to give `new` priority, as the language does.","uk":"`myCall` перетворює явну прив''язку на неявну: збереження `fn` під новим `Symbol` (неперелічуваним, тож ніхто цього не помітить) і виклик `target[key]()` робить об''єкт отримувачем у місці виклику; `finally` прибирає його назад. `myBind` замикає `thisArg` і попередні аргументи, тож пізніші виклики не можуть їх змінити, і перевіряє `new.target`, щоб надати пріоритет `new`, як це робить мова."}'::jsonb, '{"/src/bind.ts":"export function myCall<T>(fn: (...args: any[]) => T, thisArg: unknown, ...args: unknown[]): T {\n  // Default binding: a plain call gives strict-mode functions this === undefined.\n  if (thisArg === null || thisArg === undefined) return fn(...args);\n  // Implicit binding: temporarily make fn a method of the object, then call it as obj[key]().\n  const target = Object(thisArg);\n  const key = Symbol(\"myCall\");\n  Object.defineProperty(target, key, { value: fn, configurable: true }); // non-enumerable, unique key\n  try {\n    return target[key](...args);\n  } finally {\n    delete target[key];\n  }\n}\n\nexport function myBind(fn: (...args: any[]) => any, thisArg: unknown, ...preset: unknown[]) {\n  function bound(...args: unknown[]) {\n    // new beats bind: construct a real instance of fn and ignore thisArg.\n    if (new.target) return new (fn as any)(...preset, ...args);\n    return myCall(fn, thisArg, ...preset, ...args);\n  }\n  Object.defineProperty(bound, \"name\", { value: \"bound \" + fn.name });\n  return bound;\n}\n"}'::jsonb),
  ('tp-new-from-scratch', null::text[], '{"en":"All three come down to the `[[Prototype]]` link. `myCreate` sets it directly (including to `null`). `myNew` performs the four steps of `new`: create, link, call with `this`, and return the object unless the constructor returned its own. `myInstanceof` walks `Object.getPrototypeOf` until `null`, comparing each link with `Ctor.prototype`, which is exactly what `instanceof` does (ignoring `Symbol.hasInstance`), and why a forged `constructor` property can''t fool it.","uk":"Усі три зводяться до посилання `[[Prototype]]`. `myCreate` встановлює його напряму (зокрема в `null`). `myNew` виконує чотири кроки `new`: створити, прив''язати, викликати з `this` і повернути об''єкт, якщо конструктор не повернув власний. `myInstanceof` іде через `Object.getPrototypeOf` до `null`, порівнюючи кожне посилання з `Ctor.prototype`, що саме й робить `instanceof` (без урахування `Symbol.hasInstance`), і тому підроблена властивість `constructor` його не обдурить."}'::jsonb, '{"/src/proto.ts":"const isObjectLike = (v: unknown): v is object => (typeof v === \"object\" && v !== null) || typeof v === \"function\";\n\nexport function myCreate(proto: object | null): any {\n  if (proto !== null && !isObjectLike(proto)) throw new TypeError(\"Object prototype may only be an Object or null\");\n  const obj = {};\n  Object.setPrototypeOf(obj, proto);\n  return obj;\n}\n\nexport function myNew(Ctor: (...args: any[]) => any, ...args: unknown[]): any {\n  if (typeof Ctor !== \"function\") throw new TypeError(\"Not a constructor\");\n  // 1-2: a fresh object linked to Ctor.prototype (or Object.prototype if that isn''t an object)\n  const obj = myCreate(isObjectLike(Ctor.prototype) ? Ctor.prototype : Object.prototype);\n  // 3: run the constructor with this = obj\n  const result = Ctor.apply(obj, args);\n  // 4: an explicitly returned object wins; primitives are ignored\n  return isObjectLike(result) ? result : obj;\n}\n\nexport function myInstanceof(value: unknown, Ctor: { prototype: unknown }): boolean {\n  if (!isObjectLike(value)) return false;\n  for (let p = Object.getPrototypeOf(value); p !== null; p = Object.getPrototypeOf(p)) {\n    if (p === Ctor.prototype) return true;\n  }\n  return false;\n}\n"}'::jsonb),
  ('poly-syntax-vs-api', array['a', 'b']::text[], '{"en":"New **APIs** are just functions and objects, so code can define them at runtime when they''re missing. New **syntax** can''t be polyfilled: an engine that doesn''t understand `?.` or `async` fails to parse the whole file, before any polyfill could run. Syntax has to be rewritten at build time by a transpiler.","uk":"Нові **API** є просто функціями й об''єктами, тож код може визначити їх під час виконання, якщо їх немає. Новий **синтаксис** поліфілити не можна: рушій, що не розуміє `?.` чи `async`, не може розібрати весь файл ще до того, як міг би виконатися будь-який поліфіл. Синтаксис має переписати транспілятор під час збирання."}'::jsonb, null::jsonb),
  ('poly-parse-failure', array['a']::text[], '{"en":"Scripts are parsed completely before they run, and a syntax error anywhere rejects the whole file. That''s why unsupported syntax is more dangerous than a missing API: a missing API breaks one code path at runtime, but unsupported syntax silently breaks the entire bundle for those users. Configure transpiler targets for every browser you support, and monitor errors from old browsers.","uk":"Скрипти повністю розбираються до виконання, і синтаксична помилка будь-де відхиляє весь файл. Тому непідтримуваний синтаксис небезпечніший за відсутній API: відсутній API ламає один шлях коду під час виконання, а непідтримуваний синтаксис непомітно ламає весь бандл для цих користувачів. Налаштуйте цілі транспілятора для кожного браузера, який ви підтримуєте, і відстежуйте помилки зі старих браузерів."}'::jsonb, null::jsonb),
  ('poly-enumerable', array['a']::text[], '{"en":"Assigning a method to `Array.prototype` creates an **enumerable** property, so every `for…in` loop over every array in the app now sees `last`, which breaks code (and libraries) that iterate with `for…in`. `Object.defineProperty` defaults to non-enumerable, like built-in methods, so `first` stays invisible. Polyfills must be defined that way.","uk":"Присвоєння методу в `Array.prototype` створює **перелічувану** властивість, тож кожен цикл `for…in` по кожному масиву в застосунку тепер бачить `last`, і це ламає код (і бібліотеки), що перебирають через `for…in`. `Object.defineProperty` за замовчуванням створює неперелічувані властивості, як у вбудованих методів, тож `first` лишається невидимим. Поліфіли треба визначати саме так."}'::jsonb, null::jsonb),
  ('poly-overwrite-native', array['a']::text[], '{"en":"The \"polyfill\" replaces the native `includes` unconditionally with an `indexOf`-based version. `indexOf` uses `===`, and `NaN !== NaN`, while the real `includes` uses SameValueZero and finds `NaN`. A polyfill must check whether the feature exists first and implement the spec exactly, or it silently changes behaviour even in browsers that had it right.","uk":"«Поліфіл» безумовно замінює нативний `includes` версією на основі `indexOf`. `indexOf` використовує `===`, а `NaN !== NaN`, тоді як справжній `includes` використовує SameValueZero і знаходить `NaN`. Поліфіл має спершу перевірити, чи можливість існує, і точно реалізувати специфікацію, інакше він непомітно змінює поведінку навіть у браузерах, де все працювало правильно."}'::jsonb, null::jsonb),
  ('poly-at-edge-cases', array['a']::text[], '{"en":"The spec converts the index with ToIntegerOrInfinity: `1.7` is truncated to `1`, and `\"x\"` becomes `NaN`, which becomes `0`. Negative indexes count from the end, and `-4` is still out of range for a 3-element array, so it returns `undefined`. A polyfill that just does `this[i < 0 ? len + i : i]` gets the fractional and non-numeric cases wrong.","uk":"Специфікація перетворює індекс через ToIntegerOrInfinity: `1.7` обрізається до `1`, а `\"x\"` стає `NaN`, що стає `0`. Від''ємні індекси рахуються з кінця, а `-4` все одно поза межами масиву з 3 елементів, тож повертається `undefined`. Поліфіл, що просто робить `this[i < 0 ? len + i : i]`, помиляється в дробових і нечислових випадках."}'::jsonb, null::jsonb),
  ('poly-ua-sniffing', array['a']::text[], '{"en":"Feature detection tests the capability you need, so it works in every engine, including ones you''ve never heard of, and automatically starts using the feature when a browser adds it. User-agent strings lie (browsers impersonate each other), are being frozen and reduced, and require maintaining version tables. Combine detection with a graceful fallback (progressive enhancement).","uk":"Визначення можливостей перевіряє саме потрібну можливість, тож працює в будь-якому рушії, зокрема в тих, про які ви ніколи не чули, і автоматично починає використовувати можливість, щойно браузер її додає. Рядки user-agent брешуть (браузери видають себе один за одного), їх заморожують і скорочують, і вони потребують підтримки таблиць версій. Поєднуйте визначення з плавним запасним варіантом (прогресивне покращення)."}'::jsonb, null::jsonb),
  ('poly-module-nomodule', array['a']::text[], '{"en":"Support for `type=\"module\"` arrived together with most ES2015+ syntax, so it''s a cheap proxy for \"modern browser\". Modern browsers get a smaller, less-transpiled bundle, and legacy browsers get the fully transpiled and polyfilled one. (A few old Safari and Edge versions downloaded both, which bundler plugins work around.) As old browsers disappear, many sites now ship only the module build.","uk":"Підтримка `type=\"module\"` з''явилася разом із більшістю синтаксису ES2015+, тож це дешевий спосіб визначити «сучасний браузер». Сучасні браузери отримують менший, менш транспільований бандл, а застарілі отримують повністю транспільований і поліфілений. (Кілька старих версій Safari й Edge завантажували обидва, і плагіни бандлерів це обходять.) Оскільки старі браузери зникають, багато сайтів тепер постачають лише збирання з модулями."}'::jsonb, null::jsonb),
  ('poly-browserslist', array['a']::text[], '{"en":"Babel''s preset-env, SWC, core-js, Autoprefixer and Lightning CSS all read browserslist to decide what to transform and polyfill. Narrower targets mean less code, but nothing stops other browsers from loading the result: they just hit syntax errors or missing APIs. Choose targets from your real analytics, not convenience.","uk":"Preset-env у Babel, SWC, core-js, Autoprefixer і Lightning CSS читають browserslist, щоб вирішити, що перетворювати й поліфілити. Вужчі цілі означають менше коду, але ніщо не заважає іншим браузерам завантажити результат: вони просто натраплять на синтаксичні помилки чи відсутні API. Обирайте цілі за реальною аналітикою, а не за зручністю."}'::jsonb, null::jsonb),
  ('poly-ponyfill', array['a']::text[], '{"en":"Global polyfills are the **application''s** decision: a library that patches globals can conflict with the app''s polyfills, ship duplicate code, or change behaviour for unrelated code. A ponyfill keeps the dependency local and side-effect free. Applications then choose their polyfill strategy (for example core-js with `useBuiltIns: \"usage\"`) once, for the whole bundle.","uk":"Глобальні поліфіли є рішенням **застосунку**: бібліотека, що латає глобальні об''єкти, може конфліктувати з поліфілами застосунку, дублювати код чи змінювати поведінку стороннього коду. Поніфіл тримає залежність локальною й без побічних ефектів. Застосунки потім обирають свою стратегію поліфілів (наприклад, core-js з `useBuiltIns: \"usage\"`) один раз для всього бандла."}'::jsonb, null::jsonb),
  ('poly-transpile-cost', array['a']::text[], '{"en":"Down-levelled `async` functions become generator-style state machines with runtime helpers, classes become helper-heavy functions, and broad targets pull in many polyfills. All of it is shipped to everyone, increasing download, parse and execution time, often by tens of percent. Drop targets you don''t need, or serve a separate legacy bundle only to old browsers.","uk":"Знижені до старого стандарту `async`-функції стають скінченними автоматами в стилі генераторів з допоміжними функціями під час виконання, класи стають функціями з багатьма помічниками, а широкі цілі підтягують багато поліфілів. Усе це постачається всім, збільшуючи час завантаження, розбору й виконання, часто на десятки відсотків. Відмовтеся від непотрібних цілей або віддавайте окремий застарілий бандл лише старим браузерам."}'::jsonb, null::jsonb),
  ('poly-spec-polyfills', null::text[], '{"en":"Spec compliance lives in the details: the abstract operations ToIntegerOrInfinity and ToLength explain every edge case of `at`, `Object(this)` makes it work on strings and array-likes, and a null-prototype result means keys like `\"toString\"` or `\"__proto__\"` can''t clash with inherited properties. Matching `name` and `length` (plain function declarations with exactly the spec''s parameters) keeps feature checks and introspection honest. `install` uses `Object.defineProperty` with `enumerable: false`, like real built-ins, and refuses to overwrite existing functions, so it never downgrades a native implementation.","uk":"Відповідність специфікації живе в деталях: абстрактні операції ToIntegerOrInfinity і ToLength пояснюють кожен крайній випадок `at`, `Object(this)` змушує її працювати з рядками й масивоподібними об''єктами, а результат із прототипом null означає, що ключі на кшталт `\"toString\"` чи `\"__proto__\"` не можуть конфліктувати з успадкованими властивостями. Відповідність `name` і `length` (звичайні оголошення функцій саме з параметрами специфікації) тримає чесними перевірки можливостей та інтроспекцію. `install` використовує `Object.defineProperty` з `enumerable: false`, як справжні вбудовані методи, і відмовляється перезаписувати наявні функції, тож ніколи не погіршує нативну реалізацію."}'::jsonb, '{"/src/polyfills.ts":"function toIntegerOrInfinity(value: unknown): number {\n  const n = Number(value); // throws for symbols, like the spec\n  return Number.isNaN(n) ? 0 : Math.trunc(n);\n}\n\nfunction toLength(value: unknown): number {\n  const n = toIntegerOrInfinity(value);\n  return n <= 0 ? 0 : Math.min(n, Number.MAX_SAFE_INTEGER);\n}\n\n// A function declaration with exactly one parameter, so at.name === \"at\" and at.length === 1 like the built-in.\nexport function at(this: any, index: number): unknown {\n  if (this === null || this === undefined) throw new TypeError(\"Array.prototype.at called on null or undefined\");\n  const o = Object(this);\n  const len = toLength(o.length);\n  const relative = toIntegerOrInfinity(index);\n  const k = relative >= 0 ? relative : len + relative;\n  return k < 0 || k >= len ? undefined : o[k];\n}\n\nexport function groupBy(items: Iterable<unknown>, callback: (value: any, index: number) => PropertyKey): Record<PropertyKey, unknown[]> {\n  if (typeof callback !== \"function\") throw new TypeError(\"callback is not a function\");\n  const result: Record<PropertyKey, unknown[]> = Object.create(null); // no inherited keys like \"toString\"\n  let index = 0;\n  for (const value of items) {\n    const raw = callback(value, index++);\n    const key = typeof raw === \"symbol\" ? raw : String(raw);\n    (result[key as any] ??= []).push(value);\n  }\n  return result;\n}\n\nexport function withResolvers(this: any) {\n  const C = this === undefined ? Promise : this;\n  if (typeof C !== \"function\") throw new TypeError(\"withResolvers must be called on a constructor\");\n  let resolve!: (value?: unknown) => void;\n  let reject!: (reason?: unknown) => void;\n  const promise = new C((res: (value?: unknown) => void, rej: (reason?: unknown) => void) => {\n    resolve = res;\n    reject = rej;\n  });\n  return { promise, resolve, reject };\n}\n\nexport type InstallTargets = { arrayPrototype?: object; objectConstructor?: object; promiseConstructor?: object };\n\nfunction define(target: object | undefined, name: string, fn: Function, label: string, installed: string[]) {\n  if (!target || typeof (target as any)[name] === \"function\") return; // never replace a native or earlier polyfill\n  Object.defineProperty(target, name, { value: fn, writable: true, configurable: true, enumerable: false });\n  installed.push(label);\n}\n\nexport function install(targets: InstallTargets): string[] {\n  const installed: string[] = [];\n  define(targets.arrayPrototype, \"at\", at, \"Array.prototype.at\", installed);\n  define(targets.objectConstructor, \"groupBy\", groupBy, \"Object.groupBy\", installed);\n  define(targets.promiseConstructor, \"withResolvers\", withResolvers, \"Promise.withResolvers\", installed);\n  return installed;\n}\n"}'::jsonb),
  ('poly-compat-targets', null::text[], '{"en":"Version strings must be compared numerically per segment; string comparison puts `\"100\"` before `\"99\"` and `\"15.10\"` before `\"15.4\"`, a classic bug. Treating missing segments as zero makes `\"15\"` and `\"15.0\"` equal. When data is missing for a target browser, the safe default for polyfills is to include them: an unneeded polyfill costs bytes, while a missing one breaks the app. A strict parser that throws on malformed entries surfaces configuration mistakes at build time instead of silently shipping the wrong code.","uk":"Рядки версій треба порівнювати як числа посегментно; порівняння рядків ставить `\"100\"` перед `\"99\"` і `\"15.10\"` перед `\"15.4\"`, і це класична помилка. Нульові значення для відсутніх сегментів роблять `\"15\"` і `\"15.0\"` рівними. Коли даних для цільового браузера немає, безпечне рішення для поліфілів полягає в тому, щоб їх включити: непотрібний поліфіл коштує байтів, а відсутній ламає застосунок. Суворий розбір, що кидає помилку на некоректних записах, показує помилки конфігурації під час збирання, а не мовчки постачає неправильний код."}'::jsonb, '{"/src/compat.ts":"export type Target = { browser: string; version: string };\nexport type CompatData = Record<string, Record<string, string>>;\n\nexport function parseTargets(query: string): Target[] {\n  return query\n    .split(\",\")\n    .map((part) => part.trim())\n    .filter(Boolean)\n    .map((part) => {\n      const match = /^([a-z_]+)\\s+(\\d+(?:\\.\\d+)*)$/i.exec(part);\n      if (!match) throw new SyntaxError(\"Invalid target: \" + part);\n      return { browser: match[1].toLowerCase(), version: match[2] };\n    });\n}\n\nexport function compareVersions(a: string, b: string): number {\n  const pa = a.split(\".\").map(Number);\n  const pb = b.split(\".\").map(Number);\n  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {\n    const diff = (pa[i] ?? 0) - (pb[i] ?? 0); // missing segments count as 0\n    if (diff !== 0) return diff;\n  }\n  return 0;\n}\n\nexport function requiredPolyfills(compat: CompatData, targets: Target[]): string[] {\n  return Object.keys(compat)\n    .filter((feature) =>\n      targets.some((t) => {\n        const since = compat[feature][t.browser];\n        // No data for this browser: assume it''s missing, the safe choice for a polyfill.\n        return since === undefined || compareVersions(t.version, since) < 0;\n      }),\n    )\n    .sort();\n}\n"}'::jsonb),
  ('coerce-plus-minus', array['a']::text[], '{"en":"Binary `+` concatenates as soon as either operand is a string, so `\"5\" + 3` is `\"53\"`. Every other arithmetic operator converts both sides to numbers: `\"5\" - 3` is `2` and `\"5\" * \"2\"` is `10`. With no strings involved, `+` adds numbers, and `true` becomes `1`.","uk":"Бінарний `+` виконує конкатенацію, щойно хоч один операнд є рядком, тож `\"5\" + 3` дає `\"53\"`. Усі інші арифметичні оператори перетворюють обидва боки на числа: `\"5\" - 3` дає `2`, а `\"5\" * \"2\"` дає `10`. Якщо рядків немає, `+` додає числа, і `true` стає `1`."}'::jsonb, null::jsonb),
  ('coerce-or-vs-nullish', array['a']::text[], '{"en":"`||` falls back for any falsy value, so the legitimate `0` and `\"\"` are replaced. `??` falls back only for `null` and `undefined`, so it keeps `0` and `\"\"`. Use `??` for defaults whenever `0`, `\"\"` or `false` are valid values.","uk":"`||` підставляє запасне значення для будь-якого хибного значення, тож цілком законні `0` і `\"\"` замінюються. `??` підставляє його лише для `null` і `undefined`, тож зберігає `0` і `\"\"`. Використовуйте `??` для значень за замовчуванням, коли `0`, `\"\"` чи `false` є допустимими."}'::jsonb, null::jsonb),
  ('coerce-number-vs-parseint', array['a']::text[], '{"en":"`Number` converts the whole string after trimming whitespace: an empty string is `0`, and any stray character (`\"12px\"`) gives `NaN`. `parseInt` reads a numeric prefix and stops at the first invalid character. `null` converts to `0` but `undefined` to `NaN`. To validate input, check the format first or use `Number.isFinite` and treat `\"\"` specially.","uk":"`Number` перетворює весь рядок після обрізання пробілів: порожній рядок дає `0`, а будь-який зайвий символ (`\"12px\"`) дає `NaN`. `parseInt` читає числовий префікс і зупиняється на першому недопустимому символі. `null` перетворюється на `0`, а `undefined` на `NaN`. Для валідації спершу перевіряйте формат або використовуйте `Number.isFinite` і окремо обробляйте `\"\"`."}'::jsonb, null::jsonb),
  ('coerce-null-comparisons', array['a']::text[], '{"en":"`==` has a special rule: `null` and `undefined` equal each other and nothing else, so `null == 0` and `undefined == 0` are `false`. Relational operators use a different algorithm that converts to numbers: `null` becomes `0`, so `null >= 0` is `true`. That inconsistency is why `== null` is the only common use of loose equality.","uk":"`==` має окреме правило: `null` і `undefined` дорівнюють одне одному й нічому іншому, тож `null == 0` і `undefined == 0` дають `false`. Оператори порівняння використовують інший алгоритм, що перетворює на числа: `null` стає `0`, тож `null >= 0` дає `true`. Саме через цю непослідовність `== null` лишається єдиним поширеним використанням нестрогої рівності."}'::jsonb, null::jsonb),
  ('coerce-array-plus', array['a']::text[], '{"en":"`+` first turns objects into primitives. Arrays and plain objects return themselves from `valueOf`, so `toString` is used: `[1, 2]` → `\"1,2\"`, `[]` → `\"\"`, `{}` → `\"[object Object]\"`. Once one side is a string, `+` concatenates: `\"1,2\" + \"3\"` is `\"1,23\"` and `1 + \"2\"` is `\"12\"`.","uk":"`+` спершу перетворює об''єкти на примітиви. Масиви й звичайні об''єкти повертають себе з `valueOf`, тож використовується `toString`: `[1, 2]` → `\"1,2\"`, `[]` → `\"\"`, `{}` → `\"[object Object]\"`. Щойно один бік стає рядком, `+` виконує конкатенацію: `\"1,2\" + \"3\"` дає `\"1,23\"`, а `1 + \"2\"` дає `\"12\"`."}'::jsonb, null::jsonb),
  ('coerce-unary-plus', array['a']::text[], '{"en":"Unary `+` is `Number(x)`. Objects become primitives first, via `toString` for arrays and plain objects: `[]` → `\"\"` → `0`, `[5]` → `\"5\"` → `5`, `[1, 2]` → `\"1,2\"` → `NaN`, `{}` → `\"[object Object]\"` → `NaN`. A whitespace-only string trims to `\"\"`, which is `0`, and `true` is `1`.","uk":"Унарний `+` еквівалентний `Number(x)`. Об''єкти спершу стають примітивами, для масивів і звичайних об''єктів через `toString`: `[]` → `\"\"` → `0`, `[5]` → `\"5\"` → `5`, `[1, 2]` → `\"1,2\"` → `NaN`, `{}` → `\"[object Object]\"` → `NaN`. Рядок лише з пробілів обрізається до `\"\"`, тобто `0`, а `true` дає `1`."}'::jsonb, null::jsonb),
  ('coerce-loose-equality', array['a', 'c', 'e']::text[], '{"en":"With `==`, a boolean is first converted to a number (`false` → `0`). Then `\"0\" == 0` compares as numbers, and `[] == 0` turns `[]` into `\"\"` and then `0`. `\"1\" == [1]` converts the array to `\"1\"`. `null` only equals `null` and `undefined`, and `NaN` equals nothing, not even itself.","uk":"З `==` булеве значення спершу перетворюється на число (`false` → `0`). Далі `\"0\" == 0` порівнюється як числа, а `[] == 0` перетворює `[]` на `\"\"`, а потім на `0`. `\"1\" == [1]` перетворює масив на `\"1\"`. `null` дорівнює лише `null` і `undefined`, а `NaN` не дорівнює нічому, навіть собі."}'::jsonb, null::jsonb),
  ('coerce-string-compare', array['a']::text[], '{"en":"When both sides are strings, `<` compares them character by character by UTF-16 code: `\"1\"` (49) is less than `\"9\"` (57), so `\"10\" < \"9\"`. If one side is a number, both become numbers, so `10 < \"9\"` is `false`. Upper-case letters come before lower-case (`\"B\"` is 66, `\"a\"` is 97). Use `localeCompare` or `Intl.Collator` for human sorting.","uk":"Коли обидва боки рядки, `<` порівнює їх посимвольно за кодами UTF-16: `\"1\"` (49) менше за `\"9\"` (57), тож `\"10\" < \"9\"`. Якщо один бік число, обидва стають числами, тож `10 < \"9\"` дає `false`. Великі літери йдуть перед малими (`\"B\"` має код 66, `\"a\"` має 97). Для людського сортування використовуйте `localeCompare` або `Intl.Collator`."}'::jsonb, null::jsonb),
  ('coerce-valueof-tostring', array['a']::text[], '{"en":"Binary `+` and `>` ask for a primitive with the \"default\" and \"number\" hints, which try `valueOf` first, so `price` acts as `42`. Template literals and `String()` use the \"string\" hint, which tries `toString` first. (Dates are the exception: their \"default\" hint behaves like \"string\".)","uk":"Бінарний `+` і `>` запитують примітив із підказками \"default\" і \"number\", що спершу пробують `valueOf`, тож `price` поводиться як `42`. Шаблонні рядки й `String()` використовують підказку \"string\", що спершу пробує `toString`. (Виняток становлять дати: їхня підказка \"default\" поводиться як \"string\".)"}'::jsonb, null::jsonb),
  ('coerce-symbol-toprimitive', array['a']::text[], '{"en":"`Symbol.toPrimitive` receives the hint directly. Unary `+` and `*` pass `\"number\"`, a template literal passes `\"string\"`, and binary `+` passes `\"default\"` (it doesn''t know yet whether it will add or concatenate), so `temp + \"!\"` becomes `\"default!\"`.","uk":"`Symbol.toPrimitive` отримує підказку напряму. Унарний `+` і `*` передають `\"number\"`, шаблонний рядок передає `\"string\"`, а бінарний `+` передає `\"default\"` (він ще не знає, додаватиме чи з''єднуватиме), тож `temp + \"!\"` стає `\"default!\"`."}'::jsonb, null::jsonb),
  ('coerce-a-equals-1-2-3', array['a', 'b']::text[], '{"en":"Each `==` against a number converts the object with ToPrimitive again, so a method with a side effect returns `1`, `2`, `3` on successive calls. With only `toString`, `valueOf` (inherited) returns the object itself, so `toString` is used and also counts. `[1, 2, 3]` becomes `\"1,2,3\"` → `NaN`, and a constant `valueOf` only matches `1`. With `===` no conversion happens and none of these could work.","uk":"Кожне `==` з числом заново перетворює об''єкт через ToPrimitive, тож метод із побічним ефектом повертає `1`, `2`, `3` при послідовних викликах. Якщо є лише `toString`, успадкований `valueOf` повертає сам об''єкт, тож використовується `toString`, який теж рахує. `[1, 2, 3]` стає `\"1,2,3\"` → `NaN`, а сталий `valueOf` збігається лише з `1`. З `===` перетворення немає, і жоден варіант не спрацював би."}'::jsonb, null::jsonb),
  ('coerce-parse-inputs', null::text[], '{"en":"`Number` is too lenient for input validation: it turns `\"\"` and `null` into `0`, accepts hex and `Infinity`, and converts arrays through their strings. `Boolean(\"false\")` is `true` because every non-empty string is truthy. Checking the type first and validating the string format with a regex before converting makes the rules explicit, and returning `null` (rather than guessing) lets callers show a validation error.","uk":"`Number` занадто поблажливий для валідації: перетворює `\"\"` і `null` на `0`, приймає шістнадцяткові числа й `Infinity` і перетворює масиви через їхні рядки. `Boolean(\"false\")` дає `true`, бо кожен непорожній рядок істинний. Перевірка типу й формату рядка регулярним виразом перед перетворенням робить правила явними, а повернення `null` (замість здогадок) дає змогу показати помилку валідації."}'::jsonb, '{"/src/parse.ts":"const DECIMAL = /^[+-]?(\\d+\\.?\\d*|\\.\\d+)([eE][+-]?\\d+)?$/;\n\nexport function parseNumber(input: unknown): number | null {\n  if (typeof input === \"number\") return Number.isFinite(input) ? input : null;\n  if (typeof input !== \"string\") return null; // no null → 0, true → 1, [5] → 5 surprises\n  const text = input.trim();\n  // Number(\"\") is 0 and Number(\"0x1F\") is 31, so validate the format before converting.\n  if (!DECIMAL.test(text)) return null;\n  const value = Number(text);\n  return Number.isFinite(value) ? value : null;\n}\n\nconst TRUE = new Set([\"true\", \"1\", \"yes\", \"on\"]);\nconst FALSE = new Set([\"false\", \"0\", \"no\", \"off\", \"\"]);\n\nexport function parseBoolean(input: unknown): boolean | null {\n  if (typeof input === \"boolean\") return input;\n  if (typeof input === \"number\") return input === 1 ? true : input === 0 ? false : null;\n  if (typeof input !== \"string\") return null;\n  const text = input.trim().toLowerCase();\n  if (TRUE.has(text)) return true;\n  if (FALSE.has(text)) return false;\n  return null;\n}\n"}'::jsonb),
  ('coerce-loose-equals', null::text[], '{"en":"Loose equality isn''t magic, just a short recursive algorithm: equal types compare strictly, `null`/`undefined` form a closed pair, booleans become numbers, objects become primitives, and strings meet numbers as numbers. Seeing it written out explains every famous puzzle: `[] == false` is `[]` → `\"\"` → `0` versus `false` → `0`. It''s also the best argument for using `===` everywhere except `x == null`.","uk":"Нестрога рівність не є магією, а лише коротким рекурсивним алгоритмом: однакові типи порівнюються строго, `null`/`undefined` утворюють замкнену пару, булеві значення стають числами, об''єкти стають примітивами, а рядки з числами порівнюються як числа. Записаний явно, він пояснює кожну відому загадку: `[] == false` означає `[]` → `\"\"` → `0` проти `false` → `0`. І це найкращий аргумент на користь `===` всюди, крім `x == null`."}'::jsonb, '{"/src/equals.ts":"export type Hint = \"default\" | \"number\" | \"string\";\n\nconst isObject = (v: unknown): v is object => (typeof v === \"object\" && v !== null) || typeof v === \"function\";\n\nexport function toPrimitive(value: object, hint: Hint = \"default\"): unknown {\n  const exotic = (value as Record<symbol, unknown>)[Symbol.toPrimitive];\n  if (exotic !== undefined && exotic !== null) {\n    if (typeof exotic !== \"function\") throw new TypeError(\"Symbol.toPrimitive is not a function\");\n    const result = exotic.call(value, hint);\n    if (isObject(result)) throw new TypeError(\"Cannot convert object to primitive value\");\n    return result;\n  }\n  const order = hint === \"string\" ? [\"toString\", \"valueOf\"] : [\"valueOf\", \"toString\"];\n  for (const name of order) {\n    const method = (value as Record<string, unknown>)[name];\n    if (typeof method === \"function\") {\n      const result = method.call(value);\n      if (!isObject(result)) return result;\n    }\n  }\n  throw new TypeError(\"Cannot convert object to primitive value\");\n}\n\n/** null gets its own type here (typeof says \"object\"), functions count as objects. */\nconst typeOf = (v: unknown) => (v === null ? \"null\" : typeof v === \"function\" ? \"object\" : typeof v);\n\nexport function looseEquals(a: unknown, b: unknown): boolean {\n  const ta = typeOf(a);\n  const tb = typeOf(b);\n  if (ta === tb) return a === b;\n  const nullish = (t: string) => t === \"null\" || t === \"undefined\";\n  if (nullish(ta) || nullish(tb)) return nullish(ta) && nullish(tb);\n  if (ta === \"number\" && tb === \"string\") return a === Number(b);\n  if (ta === \"string\" && tb === \"number\") return Number(a) === b;\n  if (ta === \"boolean\") return looseEquals(Number(a), b);\n  if (tb === \"boolean\") return looseEquals(a, Number(b));\n  if (ta === \"object\" && (tb === \"string\" || tb === \"number\")) return looseEquals(toPrimitive(a as object), b);\n  if (tb === \"object\" && (ta === \"string\" || ta === \"number\")) return looseEquals(a, toPrimitive(b as object));\n  return false;\n}\n"}'::jsonb),
  ('ts-as-const', array['c']::text[], '{"en":"`as const` stops literal widening and makes the result deeply readonly, so an array literal becomes a readonly tuple of literal types. `typeof directions[number]` then gives the union `\"up\" | \"down\"`, a common way to derive a union from a list of values.","uk":"`as const` вимикає розширення літералів і робить результат глибоко readonly, тож літерал масиву стає readonly-кортежем літеральних типів. Тоді `typeof directions[number]` дає об''єднання `\"up\" | \"down\"` — поширений спосіб вивести union зі списку значень."}'::jsonb, null::jsonb),
  ('ts-distributive-conditional', array['b']::text[], '{"en":"A conditional type whose checked type is a naked type parameter distributes over unions: `ToArray<string | number>` becomes `ToArray<string> | ToArray<number>`. To get `(string | number)[]` instead, wrap both sides in a tuple: `[T] extends [unknown] ? T[] : never`.","uk":"Умовний тип, у якому перевіряється «голий» параметр типу, розподіляється по об''єднанню: `ToArray<string | number>` стає `ToArray<string> | ToArray<number>`. Щоб отримати `(string | number)[]`, обгорніть обидві сторони в кортеж: `[T] extends [unknown] ? T[] : never`."}'::jsonb, null::jsonb),
  ('ts-function-variance', array['b']::text[], '{"en":"Function-type parameters are checked contravariantly: a handler that accepts any `Event` can stand in for one that expects a `MouseEvent` (`a` is fine), but not the reverse (`b` errors, since it could receive a `KeyboardEvent`). Method-shorthand members are deliberately exempt and stay bivariant, so `c` compiles even though it''s equally unsafe. Prefer property syntax (`handle: (e: Event) => void`) when you want the strict check.","uk":"Параметри типів-функцій перевіряються контраваріантно: обробник, що приймає будь-яку `Event`, може замінити той, що очікує `MouseEvent` (`a` коректне), але не навпаки (`b` — помилка, бо він може отримати `KeyboardEvent`). Члени, оголошені як методи, свідомо винятки й лишаються біваріантними, тож `c` компілюється, хоч воно так само небезпечне. Якщо потрібна строга перевірка, оголошуйте властивістю (`handle: (e: Event) => void`)."}'::jsonb, null::jsonb),
  ('ts-schema-validator', null::text[], '{"en":"Every schema is a small object with a `parse` closure, and composite schemas call their children''s `parse` with an extended path (`path.key`, `path[i]`). A shared `fail(): never` helper keeps the ternaries well-typed. `object` builds a fresh output from the shape''s keys only, which is what strips unknown keys, and `Infer` lets callers derive static types from the runtime schema.","uk":"Кожна схема — невеликий об''єкт із замиканням `parse`, а складені схеми викликають `parse` дочірніх із подовженим шляхом (`path.key`, `path[i]`). Спільний хелпер `fail(): never` зберігає коректну типізацію тернарних виразів. `object` будує новий результат лише з ключів форми — саме це відкидає невідомі ключі, а `Infer` дозволяє виводити статичні типи з runtime-схеми."}'::jsonb, '{"/src/schema.ts":"export class ValidationError extends Error {\n  path: string;\n  constructor(path: string, message: string) {\n    super((path || \"value\") + \": \" + message);\n    this.name = \"ValidationError\";\n    this.path = path;\n  }\n}\n\nexport type Schema<T> = { parse(value: unknown, path?: string): T };\nexport type Infer<S> = S extends Schema<infer T> ? T : never;\n\nfunction kind(value: unknown) {\n  if (value === null) return \"null\";\n  if (Array.isArray(value)) return \"array\";\n  if (Number.isNaN(value)) return \"NaN\";\n  return typeof value;\n}\n\nfunction fail(path: string, expected: string, value: unknown): never {\n  throw new ValidationError(path, \"expected \" + expected + \", got \" + kind(value));\n}\n\nexport function string(): Schema<string> {\n  return { parse: (value, path = \"\") => (typeof value === \"string\" ? value : fail(path, \"string\", value)) };\n}\n\nexport function number(): Schema<number> {\n  return {\n    parse: (value, path = \"\") => (typeof value === \"number\" && !Number.isNaN(value) ? value : fail(path, \"number\", value)),\n  };\n}\n\nexport function optional<T>(schema: Schema<T>): Schema<T | undefined> {\n  return { parse: (value, path) => (value === undefined ? undefined : schema.parse(value, path)) };\n}\n\nexport function array<T>(item: Schema<T>): Schema<T[]> {\n  return {\n    parse(value, path = \"\") {\n      if (!Array.isArray(value)) return fail(path, \"array\", value);\n      return value.map((entry, i) => item.parse(entry, path + \"[\" + i + \"]\"));\n    },\n  };\n}\n\nexport function object<S extends Record<string, Schema<unknown>>>(shape: S): Schema<{ [K in keyof S]: Infer<S[K]> }> {\n  return {\n    parse(value, path = \"\") {\n      if (typeof value !== \"object\" || value === null || Array.isArray(value)) return fail(path, \"object\", value);\n      const input = value as Record<string, unknown>;\n      const out: Record<string, unknown> = {};\n      for (const key of Object.keys(shape)) {\n        const parsed = shape[key].parse(input[key], path ? path + \".\" + key : key);\n        if (parsed !== undefined || key in input) out[key] = parsed;\n      }\n      return out as { [K in keyof S]: Infer<S[K]> };\n    },\n  };\n}\n"}'::jsonb),
  ('ts-unknown-vs-any', array['a']::text[], '{"en":"Both accept any value, but `unknown` is type-safe: you can''t call methods or access properties until you narrow it with `typeof`, `instanceof` or a type guard. `any` silently turns off checking and spreads.","uk":"Обидва приймають будь-яке значення, але `unknown` безпечний: не можна викликати методи чи читати властивості, доки ви не звузите тип через `typeof`, `instanceof` або type guard. `any` непомітно вимикає перевірку й поширюється."}'::jsonb, null::jsonb),
  ('ts-structural-typing', array['b']::text[], '{"en":"Line 3 assigns a variable that has extra properties, which is allowed because shapes are compatible. Line 4 assigns an object literal directly, so TypeScript runs an excess property check and rejects `z`.","uk":"Рядок 3 присвоює змінну із зайвими властивостями, і це дозволено, бо форми сумісні. Рядок 4 присвоює об''єктний літерал напряму, тож TypeScript перевіряє зайві властивості й відхиляє `z`."}'::jsonb, null::jsonb),
  ('ts-generic-constraint', array['a']::text[], '{"en":"`keyof T` is the union of T''s property names, and the constraint limits `K` to that union. That''s why `T[K]` is a valid, precise return type. It says nothing about runtime: an object typed as T could still miss the key.","uk":"`keyof T` є об''єднанням назв властивостей T, і обмеження зводить `K` до цього об''єднання. Тому `T[K]` є коректним і точним типом результату. Про час виконання це нічого не каже: об''єкт типу T все одно може не мати ключа."}'::jsonb, null::jsonb),
  ('ts-utility-types', array['a']::text[], '{"en":"`Omit<User, \"id\">` drops the key, and `Partial<…>` makes the rest optional. (`Omit<Partial<User>, \"id\">` would also work; the `| undefined` key in option B makes no sense.)","uk":"`Omit<User, \"id\">` прибирає ключ, а `Partial<…>` робить решту необов''язковими. (`Omit<Partial<User>, \"id\">` теж спрацював би; ключ `| undefined` у варіанті B не має сенсу.)"}'::jsonb, null::jsonb),
  ('ts-exhaustive-never', array['b']::text[], '{"en":"In the `default` branch the type of `s` is narrowed to whatever variants remain. With all cases handled that is `never`. After adding `triangle` it is the triangle type, which is not assignable to `never`, so the compiler points you to the missing case.","uk":"У гілці `default` тип `s` звужується до варіантів, що залишилися. Коли всі випадки оброблено, це `never`. Після додавання `triangle` це тип трикутника, який не можна присвоїти `never`, тож компілятор вкаже на пропущений випадок."}'::jsonb, null::jsonb),
  ('ts-typed-event-emitter', null::text[], '{"en":"Keep a `Map<event, Set<handler>>`. A Set preserves insertion order and makes `off` O(1). `on` returns a closure that calls `off`. In `emit`, iterate over a copy, so handlers that subscribe or unsubscribe during the loop don''t skip or repeat calls.","uk":"Зберігайте `Map<подія, Set<обробник>>`. Set зберігає порядок вставки й робить `off` за O(1). `on` повертає замикання, що викликає `off`. У `emit` проходьте по копії, щоб обробники, які підписуються чи відписуються під час циклу, не пропускали й не повторювали викликів."}'::jsonb, '{"/src/emitter.ts":"type Handler<P> = (payload: P) => void;\n\nexport function createEmitter<Events extends Record<string, unknown>>() {\n  const handlers = new Map<keyof Events, Set<Handler<any>>>();\n\n  function on<E extends keyof Events>(event: E, handler: Handler<Events[E]>): () => void {\n    if (!handlers.has(event)) handlers.set(event, new Set());\n    handlers.get(event)!.add(handler);\n    return () => off(event, handler);\n  }\n\n  function off<E extends keyof Events>(event: E, handler: Handler<Events[E]>): void {\n    handlers.get(event)?.delete(handler);\n  }\n\n  function emit<E extends keyof Events>(event: E, payload: Events[E]): void {\n    // Copy first, so (un)subscribing during emit doesn''t affect this round.\n    for (const handler of [...(handlers.get(event) ?? [])]) handler(payload);\n  }\n\n  return { on, off, emit };\n}\n"}'::jsonb),
  ('uni-length', array['a']::text[], '{"en":"`length` counts UTF-16 **code units**. 😀 is one code point above `U+FFFF`, so it takes a surrogate pair (2). The family emoji is three person emoji (2 units each) joined by two zero-width joiners (1 each): 8 units. Spreading a string iterates **code points**: 3 emoji + 2 joiners = 5. To a user it''s still one character, which only `Intl.Segmenter` counts.","uk":"`length` рахує **кодові одиниці** UTF-16. 😀 є однією кодовою точкою вище `U+FFFF`, тож займає сурогатну пару (2). Емодзі родини складається з трьох емодзі людей (по 2 одиниці), з''єднаних двома символами нульової ширини (по 1): 8 одиниць. Розгортання рядка перебирає **кодові точки**: 3 емодзі + 2 з''єднувачі = 5. Для користувача це все одно один символ, і порахувати його так уміє лише `Intl.Segmenter`."}'::jsonb, null::jsonb),
  ('uni-codepoint-vs-charcode', array['a']::text[], '{"en":"`charCodeAt(0)` returns the first code unit, the high surrogate `d83d`. `codePointAt(0)` sees that it starts a surrogate pair and combines both units into the real code point `1f600`. At index 1 there''s only the low surrogate left, so it returns `de00`. Iterate with `for…of` (which steps by code points) to avoid landing in the middle of a pair.","uk":"`charCodeAt(0)` повертає першу кодову одиницю, верхній сурогат `d83d`. `codePointAt(0)` бачить, що з нього починається сурогатна пара, і поєднує обидві одиниці в справжню кодову точку `1f600`. На індексі 1 лишається тільки нижній сурогат, тож вона повертає `de00`. Перебирайте через `for…of` (він іде по кодових точках), щоб не потрапити в середину пари."}'::jsonb, null::jsonb),
  ('uni-normalize', array['a']::text[], '{"en":"`\\u00e9` is the precomposed é (NFC), while `e` + `\\u0301` is a base letter plus a combining accent (NFD). They render identically but are different code point sequences, so `===` fails and the lengths differ. `normalize()` (NFC by default) converts both to the same form. Normalise user input before comparing, storing or using it as a key.","uk":"`\\u00e9` є готовою літерою é (NFC), а `e` + `\\u0301` є базовою літерою з комбінованим наголосом (NFD). Вони виглядають однаково, але є різними послідовностями кодових точок, тож `===` не проходить, а довжини різні. `normalize()` (за замовчуванням NFC) перетворює обидва в ту саму форму. Нормалізуйте введення користувача перед порівнянням, збереженням чи використанням як ключа."}'::jsonb, null::jsonb),
  ('uni-sharp-s', array['a']::text[], '{"en":"Unicode''s default case mapping turns German `ß` into two letters, `SS`, so the string grows from 6 to 7 characters. Code that uppercases and then reuses indexes or lengths from the original string breaks. Case mapping can also depend on the language (Turkish i), so compare case-insensitively with `localeCompare` or `Intl.Collator` instead of uppercasing both sides.","uk":"Типове перетворення регістру в Unicode перетворює німецьку `ß` на дві літери `SS`, тож рядок зростає з 6 до 7 символів. Код, що переводить у верхній регістр, а потім використовує індекси чи довжини з початкового рядка, ламається. Перетворення регістру може ще й залежати від мови (турецька i), тож порівнюйте без урахування регістру через `localeCompare` чи `Intl.Collator`, а не переводячи обидва боки у верхній регістр."}'::jsonb, null::jsonb),
  ('uni-turkish-i', array['a']::text[], '{"en":"Turkish and Azerbaijani have both dotted (`i`/`İ`) and dotless (`ı`/`I`) letters. `toUpperCase` uses language-neutral rules, while `toLocaleUpperCase(\"tr\")` maps `i` to `İ` and `toLocaleLowerCase(\"tr\")` maps `I` to `ı`. Using locale-neutral mapping for Turkish user names, or locale-specific mapping for identifiers and protocol keywords, are both real bugs.","uk":"У турецькій та азербайджанській є літери з крапкою (`i`/`İ`) і без неї (`ı`/`I`). `toUpperCase` використовує мовно-нейтральні правила, а `toLocaleUpperCase(\"tr\")` перетворює `i` на `İ`, і `toLocaleLowerCase(\"tr\")` перетворює `I` на `ı`. Нейтральне перетворення для турецьких імен користувачів і локальне для ідентифікаторів чи ключових слів протоколу є реальними помилками."}'::jsonb, null::jsonb),
  ('uni-default-sort', array['a']::text[], '{"en":"Without a comparator, `sort` compares UTF-16 code units: uppercase letters (`Z` = 90) come before lowercase (`a` = 97), accented letters (`é` = 233) after all ASCII letters, and digits character by character, so `\"item10\" < \"item2\"`. For text shown to people, sort with `new Intl.Collator(locale, { numeric: true }).compare`.","uk":"Без функції порівняння `sort` порівнює кодові одиниці UTF-16: великі літери (`Z` = 90) йдуть перед малими (`a` = 97), літери з наголосами (`é` = 233) після всіх літер ASCII, а цифри посимвольно, тож `\"item10\" < \"item2\"`. Для тексту, який бачать люди, сортуйте через `new Intl.Collator(locale, { numeric: true }).compare`."}'::jsonb, null::jsonb),
  ('uni-collator', array['a']::text[], '{"en":"`numeric: true` compares digit runs as numbers (2 < 10), and `sensitivity: \"base\"` ignores case and accents, so `Item2` sorts as `item2` and `\"resume\"` equals `\"Résumé\"` (compare returns `0`). Create the collator once and reuse its `compare`: constructing one per comparison is slow.","uk":"`numeric: true` порівнює послідовності цифр як числа (2 < 10), а `sensitivity: \"base\"` ігнорує регістр і наголоси, тож `Item2` сортується як `item2`, а `\"resume\"` дорівнює `\"Résumé\"` (порівняння повертає `0`). Створюйте колатор один раз і повторно використовуйте його `compare`: створення нового для кожного порівняння повільне."}'::jsonb, null::jsonb),
  ('uni-lone-surrogate', array['a']::text[], '{"en":"`slice` works on code units, so `slice(0, 3)` keeps `h`, `i` and only the high surrogate of 😀. The result is a **lone surrogate**, which isn''t valid Unicode: `isWellFormed()` reports it, `JSON.stringify` escapes it as `\\ud83d`, and encoding it to UTF-8 produces a replacement character. Cut by graphemes (or at least code points) instead, or repair with `toWellFormed()`.","uk":"`slice` працює з кодовими одиницями, тож `slice(0, 3)` зберігає `h`, `i` і лише верхній сурогат 😀. Результатом є **самотній сурогат**, що не є коректним Unicode: `isWellFormed()` це показує, `JSON.stringify` екранує його як `\\ud83d`, а кодування в UTF-8 дає символ заміни. Ріжте за графемами (чи хоча б за кодовими точками) або виправляйте через `toWellFormed()`."}'::jsonb, null::jsonb),
  ('uni-regex-flags', array['a']::text[], '{"en":"Without `u`, `.` matches one code unit, so it can''t match the two units of 😀 as a whole. With `u`, the regex works on code points. But `\\w` stays ASCII-only (`[A-Za-z0-9_]`) even with `u`, so it doesn''t match `é`. Unicode property escapes like `\\p{L}` (any letter in any script) need the `u` or `v` flag and are the right tool for international text.","uk":"Без `u` `.` збігається з однією кодовою одиницею, тож не може збігтися з двома одиницями 😀 як цілим. З `u` регулярний вираз працює з кодовими точками. Але `\\w` лишається лише ASCII (`[A-Za-z0-9_]`) навіть з `u`, тож не збігається з `é`. Екранування властивостей Unicode на кшталт `\\p{L}` (будь-яка літера будь-якої писемності) потребують прапорця `u` чи `v` і є правильним інструментом для міжнародного тексту."}'::jsonb, null::jsonb),
  ('uni-segmenter', array['a']::text[], '{"en":"👍🏽 is a thumbs-up plus a skin-tone modifier (2 code points, 4 units), 🇺🇦 is two regional-indicator letters (2 code points, 4 units), and é here is `e` plus a combining accent (2 code points, 2 units). So: 10 code units, 6 code points, and 3 graphemes, the number a person would count. Use the grapheme count for character limits and cursor movement.","uk":"👍🏽 складається з піднятого пальця й модифікатора тону шкіри (2 кодові точки, 4 одиниці), 🇺🇦 з двох регіональних літер-індикаторів (2 кодові точки, 4 одиниці), а é тут є `e` з комбінованим наголосом (2 кодові точки, 2 одиниці). Тож: 10 кодових одиниць, 6 кодових точок і 3 графеми, тобто стільки, скільки нарахувала б людина. Використовуйте кількість графем для обмежень символів і переміщення курсора."}'::jsonb, null::jsonb),
  ('uni-utf8-bytes', array['a']::text[], '{"en":"`TextEncoder` produces UTF-8, where ASCII takes 1 byte, Latin accents and Cyrillic 2, most other BMP characters like `€` 3, and emoji 4. Byte sizes, not `length`, matter for database column limits, HTTP header sizes, `Content-Length`, and storage quotas.","uk":"`TextEncoder` створює UTF-8, де ASCII займає 1 байт, латинські літери з наголосами й кирилиця 2, більшість інших символів BMP на кшталт `€` 3, а емодзі 4. Для обмежень стовпців бази даних, розмірів заголовків HTTP, `Content-Length` і квот сховища важливий розмір у байтах, а не `length`."}'::jsonb, null::jsonb),
  ('uni-graphemes', null::text[], '{"en":"`Intl.Segmenter` with grapheme granularity implements Unicode''s text segmentation rules: it keeps surrogate pairs, zero-width-joiner sequences, skin-tone modifiers, regional-indicator pairs and combining marks together. Once text is an array of graphemes, counting, slicing and reversing are plain array operations that can''t produce lone surrogates or detached accents. Create the segmenter once at module level, since constructing `Intl` objects is relatively expensive.","uk":"`Intl.Segmenter` з гранулярністю графем реалізує правила сегментації тексту Unicode: він тримає разом сурогатні пари, послідовності з з''єднувачем нульової ширини, модифікатори тону шкіри, пари регіональних індикаторів і комбіновані знаки. Щойно текст стає масивом графем, підрахунок, вирізання й перевертання є звичайними операціями з масивом, що не можуть створити самотніх сурогатів чи відірваних наголосів. Створюйте сегментатор один раз на рівні модуля, бо створення об''єктів `Intl` відносно дороге."}'::jsonb, '{"/src/graphemes.ts":"const segmenter = new Intl.Segmenter(undefined, { granularity: \"grapheme\" });\n\nexport function graphemes(text: string): string[] {\n  return Array.from(segmenter.segment(text), (s) => s.segment);\n}\n\nexport function countGraphemes(text: string): number {\n  let count = 0;\n  for (const _ of segmenter.segment(text)) count++;\n  return count;\n}\n\nexport function truncate(text: string, max: number, { ellipsis = \"…\", wordBoundary = false } = {}): string {\n  const chars = graphemes(text);\n  if (chars.length <= max) return text;\n  const room = max - countGraphemes(ellipsis);\n  if (room <= 0) return graphemes(ellipsis).slice(0, Math.max(0, max)).join(\"\");\n  let kept = chars.slice(0, room);\n  if (wordBoundary) {\n    const lastSpace = kept.findLastIndex((c) => /^\\s+$/u.test(c));\n    if (lastSpace > 0) kept = kept.slice(0, lastSpace);\n  }\n  return kept.join(\"\").trimEnd() + ellipsis;\n}\n\nexport function reverse(text: string): string {\n  return graphemes(text).reverse().join(\"\");\n}\n"}'::jsonb),
  ('uni-fold-slugify', null::text[], '{"en":"NFKD normalisation splits letters from their combining marks and replaces compatibility characters with their plain equivalents. Removing marks blindly would turn `й` into `и` and `ї` into `і`, so the regex only strips marks that follow a Latin letter (`\\p{Script=Latin}`), and a final NFC recomposes the Cyrillic letters. `\\p{L}` and `\\p{N}` keep letters and digits of every script in slugs. For ordering, `Intl.Collator` with `numeric` and `sensitivity: \"base\"` implements the locale''s real alphabet, which raw code-unit comparison gets wrong.","uk":"Нормалізація NFKD відокремлює літери від комбінованих знаків і замінює символи сумісності їхніми звичайними відповідниками. Сліпе видалення знаків перетворило б `й` на `и`, а `ї` на `і`, тож регулярний вираз прибирає лише знаки після латинської літери (`\\p{Script=Latin}`), а фінальна NFC знову складає кириличні літери. `\\p{L}` і `\\p{N}` зберігають у слагах літери й цифри всіх писемностей. Для впорядкування `Intl.Collator` з `numeric` і `sensitivity: \"base\"` реалізує справжній алфавіт локалі, а сире порівняння кодових одиниць помиляється."}'::jsonb, '{"/src/fold.ts":"export function fold(text: string): string {\n  return (\n    text\n      // NFKD splits accents off their letters and maps compatibility forms (full-width, ligatures) to plain ones.\n      .normalize(\"NFKD\")\n      // Drop accents only from Latin letters: in Ukrainian, й and ї are distinct letters, not accented и and і.\n      .replace(/(\\p{Script=Latin})\\p{M}+/gu, \"$1\")\n      .toLowerCase()\n      // Recompose what''s left (й, ї) into single code points.\n      .normalize(\"NFC\")\n  );\n}\n\nexport function slugify(text: string): string {\n  return fold(text)\n    .replace(/[^\\p{L}\\p{N}]+/gu, \"-\")\n    .replace(/^-+|-+$/g, \"\");\n}\n\nexport function includesFolded(haystack: string, needle: string): boolean {\n  return fold(haystack).includes(fold(needle));\n}\n\nexport function sortNatural(list: string[], locale = \"en\"): string[] {\n  const collator = new Intl.Collator(locale, { numeric: true, sensitivity: \"base\" });\n  return [...list].sort(collator.compare);\n}\n"}'::jsonb),
  ('test-aaa', array['a']::text[], '{"en":"Unit tests should run in milliseconds, not depend on each other or on external services, give the same result every run, and fail for exactly one reason. The Arrange–Act–Assert structure helps: set up the inputs, call the code once, then check the outcome. Real databases belong in integration tests.","uk":"Модульні тести мають виконуватися за мілісекунди, не залежати один від одного чи від зовнішніх сервісів, давати той самий результат щоразу й падати рівно з однієї причини. Допомагає структура Arrange–Act–Assert: підготуйте вхідні дані, викличте код один раз, потім перевірте результат. Справжні бази даних — для інтеграційних тестів."}'::jsonb, null::jsonb),
  ('test-order-dependence', array['b']::text[], '{"en":"Order-dependent failures nearly always mean an earlier test changed shared state and didn''t restore it: a cached singleton, a spy that wasn''t restored, fake timers left on, or leftover DOM. Create fresh state in `beforeEach`, restore mocks in `afterEach` (or enable `restoreMocks` in the config), and run tests in random order to surface hidden coupling.","uk":"Падіння, залежні від порядку, майже завжди означають, що попередній тест змінив спільний стан і не відновив його: закешований синглтон, невідновлений шпигун, увімкнені фейкові таймери чи залишки DOM. Створюйте свіжий стан у `beforeEach`, відновлюйте моки в `afterEach` (або увімкніть `restoreMocks` у конфігурації) і запускайте тести у випадковому порядку, щоб виявити приховані зв''язки."}'::jsonb, null::jsonb),
  ('test-mutation', array['b']::text[], '{"en":"Coverage only proves code was executed. Mutation testing proves the tests notice when the code changes. A surviving boundary mutant means there''s no assertion at the edge, so add a test for exactly 18 (and 17). Some mutants are equivalent (no behaviour change) and can be ignored, but this one isn''t.","uk":"Покриття доводить лише те, що код виконувався. Мутаційне тестування доводить, що тести помічають зміну коду. Мутант межі, що вижив, означає відсутність перевірки на краю, тож додайте тест рівно для 18 (і 17). Деякі мутанти еквівалентні (поведінка не змінюється), їх можна ігнорувати, але цей — ні."}'::jsonb, null::jsonb),
  ('test-fake-clock', null::text[], '{"en":"Store each timer with an absolute due time and a monotonically increasing id. `tick` repeatedly picks the earliest due timer within the target time (the id breaks ties), sets the clock to its due time and runs it. Because the timer list is re-read on every step, timers that callbacks schedule are picked up within the same tick. This is what `vi.useFakeTimers()` and `jest.useFakeTimers()` do under the hood, using a heap for efficiency.","uk":"Зберігайте кожен таймер з абсолютним часом спрацювання й монотонно зростаючим id. `tick` раз за разом обирає найраніший таймер у межах цільового часу (id розв''язує рівність), встановлює годинник на його час і запускає. Оскільки список таймерів перечитується на кожному кроці, таймери, заплановані колбеками, підхоплюються в тому самому tick. Саме це під капотом роблять `vi.useFakeTimers()` і `jest.useFakeTimers()`, використовуючи купу для ефективності."}'::jsonb, '{"/src/fake-clock.ts":"export type FakeClock = {\n  now(): number;\n  setTimeout(fn: () => void, ms: number): number;\n  clearTimeout(id: number): void;\n  tick(ms: number): void;\n};\n\ntype Timer = { id: number; due: number; fn: () => void };\n\nexport function createFakeClock(): FakeClock {\n  let time = 0;\n  let nextId = 1;\n  let timers: Timer[] = [];\n\n  return {\n    now: () => time,\n    setTimeout(fn, ms) {\n      const id = nextId++;\n      timers.push({ id, due: time + Math.max(0, ms), fn });\n      return id;\n    },\n    clearTimeout(id) {\n      timers = timers.filter((timer) => timer.id !== id);\n    },\n    tick(ms) {\n      const end = time + ms;\n      for (;;) {\n        // Earliest due time first; ids increase, so they break ties in scheduling order.\n        let next: Timer | undefined;\n        for (const timer of timers) {\n          if (timer.due <= end && (!next || timer.due < next.due || (timer.due === next.due && timer.id < next.id))) next = timer;\n        }\n        if (!next) break;\n        const run = next;\n        timers = timers.filter((timer) => timer !== run);\n        time = run.due;\n        run.fn();\n      }\n      time = end;\n    },\n  };\n}\n"}'::jsonb),
  ('test-missing-await', array['a']::text[], '{"en":"The test function returns synchronously, the runner marks it as passed, and the assertion (or rejection) happens later. Use `async` + `await`, return the promise, or `await expect(p).resolves/rejects`.","uk":"Тестова функція повертається синхронно, раннер позначає її пройденою, а перевірка (чи відхилення) відбувається пізніше. Використайте `async` + `await`, поверніть проміс або `await expect(p).resolves/rejects`."}'::jsonb, null::jsonb),
  ('test-doubles', array['c']::text[], '{"en":"A fake has a working (simplified) implementation. A stub only returns canned answers, a spy/mock records calls for assertions, and fixtures are prepared test data.","uk":"Фейк має робочу (спрощену) реалізацію. Стаб лише повертає заготовлені відповіді, spy/mock записує виклики для перевірок, а фікстури є підготовленими тестовими даними."}'::jsonb, null::jsonb),
  ('test-query-priority', array['a']::text[], '{"en":"Role + accessible name is how users and assistive technology perceive the UI, and it survives refactors of classes and structure. Test IDs are a fallback, and class or position selectors couple tests to implementation details.","uk":"Роль + доступне ім''я відповідають тому, як інтерфейс сприймають користувачі й допоміжні технології, і це переживає рефакторинг класів і структури. Test ID є запасним варіантом, а селектори за класами чи позицією прив''язують тести до деталей реалізації."}'::jsonb, null::jsonb),
  ('test-fake-timers', array['a']::text[], '{"en":"Fake timers (`vi.useFakeTimers()` + `vi.advanceTimersByTime(30_000)`) make time-dependent tests instant and deterministic. Alternatively, inject the delay or a scheduler into the function.","uk":"Фейкові таймери (`vi.useFakeTimers()` + `vi.advanceTimersByTime(30_000)`) роблять тести, що залежать від часу, миттєвими й детермінованими. Як варіант, впровадьте затримку чи планувальник у функцію."}'::jsonb, null::jsonb),
  ('test-coverage-meaning', array['a']::text[], '{"en":"Coverage measures execution, not verification: a test without assertions still covers lines. Branch coverage, mutation testing and thoughtful edge cases say more about test quality.","uk":"Покриття вимірює виконання, а не перевірку: тест без перевірок усе одно покриває рядки. Покриття гілок, мутаційне тестування й продумані граничні випадки більше говорять про якість тестів."}'::jsonb, null::jsonb),
  ('test-injectable-reminders', null::text[], '{"en":"Injecting `now` and `send` makes the function deterministic and observable in tests: a fixed clock pins the 30-day boundary (exactly 30 days is not \"more than\"), and a mock `send` records calls and can simulate failures. A `for…of` loop with `await` sends sequentially, and `try/catch` per user isolates failures.","uk":"Впровадження `now` і `send` робить функцію детермінованою й спостережуваною в тестах: фіксований годинник закріплює межу 30 днів (рівно 30 днів не є «більше ніж»), а мок `send` записує виклики й може імітувати збої. Цикл `for…of` з `await` надсилає послідовно, а `try/catch` для кожного користувача ізолює збої."}'::jsonb, '{"/src/reminders.ts":"export type User = { email: string; lastActiveAt: number; optOut?: boolean };\nexport type Deps = { now: () => number; send: (email: string, message: string) => Promise<void> };\n\nexport const DAY = 24 * 60 * 60 * 1000;\n\nexport async function sendReminders(users: User[], deps: Deps): Promise<{ sent: string[]; failed: string[] }> {\n  const cutoff = deps.now() - 30 * DAY;\n  const sent: string[] = [];\n  const failed: string[] = [];\n\n  for (const user of users) {\n    if (user.optOut || user.lastActiveAt >= cutoff) continue;\n    try {\n      await deps.send(user.email, \"We miss you!\");\n      sent.push(user.email);\n    } catch {\n      failed.push(user.email);\n    }\n  }\n  return { sent, failed };\n}\n"}'::jsonb),
  ('vite-fast-dev', array['a']::text[], '{"en":"Instead of bundling the whole app before serving, Vite lets the browser request modules through `import` statements and transforms just those files (esbuild for TS/JSX). Only dependencies are pre-bundled once and cached. So start-up cost doesn''t grow with the number of source files.","uk":"Замість збирання всього застосунку перед віддачею Vite дає браузеру запитувати модулі через `import` і перетворює лише ці файли (esbuild для TS/JSX). Лише залежності один раз попередньо збираються й кешуються. Тож вартість запуску не зростає з кількістю вихідних файлів."}'::jsonb, null::jsonb),
  ('vite-env-vars', array['a']::text[], '{"en":"Vite deliberately exposes only `VITE_*` variables so server secrets in the same `.env` don''t leak into the bundle. Exposed values are replaced in the code at build time, so anyone can read them in the downloaded JavaScript: a maps key restricted by domain is fine, a database password is not.","uk":"Vite навмисно відкриває лише змінні `VITE_*`, щоб серверні секрети з того самого `.env` не потрапили в бандл. Відкриті значення підставляються в код під час збирання, тож будь-хто може прочитати їх у завантаженому JavaScript: ключ карт з обмеженням за доменом підходить, пароль до бази даних ні."}'::jsonb, null::jsonb),
  ('vite-dynamic-import', array['a']::text[], '{"en":"Each dynamic `import()` is a split point: the bundler creates a separate chunk, and the initial bundle gets smaller. It''s ideal for routes and heavy, rarely used features. Prefetch the chunk on hover or idle if the delay on first use is noticeable.","uk":"Кожен динамічний `import()` є точкою розбиття: бандлер створює окремий фрагмент, і початковий бандл меншає. Це ідеально для маршрутів і важких, рідко використовуваних можливостей. Попередньо завантажуйте фрагмент при наведенні чи в простої, якщо затримка під час першого використання помітна."}'::jsonb, null::jsonb),
  ('vite-hashed-caching', array['a']::text[], '{"en":"The hash changes whenever a file''s content changes, so a hashed file can never become stale and can be cached forever. `index.html` has a fixed name and points to the current hashes, so it must be revalidated; if it were cached for long, users would keep loading old asset references after a deploy.","uk":"Хеш змінюється щоразу, коли змінюється вміст файлу, тож хешований файл ніколи не застаріє й може кешуватися назавжди. `index.html` має незмінну назву й посилається на поточні хеші, тож його треба перевіряти; якби його кешували надовго, користувачі після розгортання й далі завантажували б старі посилання на ресурси."}'::jsonb, null::jsonb),
  ('vite-tree-shaking', array['a']::text[], '{"en":"Tree shaking relies on static `import`/`export` analysis. `require()` and `module.exports` are dynamic, and modules with possible side effects can''t be dropped unless the package declares `\"sideEffects\": false`. Prefer ESM builds (`lodash-es` over `lodash`) or per-function imports, and check the result with a bundle visualiser.","uk":"Tree shaking спирається на статичний аналіз `import`/`export`. `require()` і `module.exports` динамічні, а модулі з можливими побічними ефектами не можна викинути, якщо пакет не оголосив `\"sideEffects\": false`. Віддавайте перевагу ESM-збіркам (`lodash-es` замість `lodash`) чи імпортам окремих функцій і перевіряйте результат візуалізатором бандла."}'::jsonb, null::jsonb),
  ('vite-base-path', array['a']::text[], '{"en":"By default the build assumes the app is served from `/`, so `index.html` references `/assets/...`. Setting `base` rewrites those URLs (and `import.meta.env.BASE_URL`). If you use client-side routing, configure the router''s base path too, and the server must fall back to `index.html` for deep links.","uk":"За замовчуванням збірка вважає, що застосунок віддається з `/`, тож `index.html` посилається на `/assets/...`. Параметр `base` переписує ці URL (і `import.meta.env.BASE_URL`). Якщо використовуєте клієнтську маршрутизацію, налаштуйте базовий шлях і в роутері, а сервер має віддавати `index.html` для глибоких посилань."}'::jsonb, null::jsonb),
  ('vue-if-vs-show', array['a']::text[], '{"en":"`v-if` really adds and removes the element, running component setup and teardown each time: cheap when hidden, more expensive to toggle. `v-show` renders once and toggles `display: none`: a higher initial cost, cheap toggling, and inner state (inputs, scroll) survives. Use `v-if` for content that''s rarely shown or shouldn''t exist when hidden.","uk":"`v-if` справді додає й прибирає елемент, щоразу ініціалізуючи й знищуючи компоненти: дешево, коли приховано, але дорожче перемикати. `v-show` рендерить один раз і перемикає `display: none`: вища початкова вартість, дешеве перемикання, і внутрішній стан (поля, прокрутка) зберігається. Використовуйте `v-if` для вмісту, який показують рідко або який не повинен існувати, коли прихований."}'::jsonb, null::jsonb),
  ('vue-ref-value', array['a']::text[], '{"en":"A `ref` is an object whose `.value` is reactive; in script code you always go through `.value`. Templates unwrap top-level refs automatically, which is why `{{ count }}` and `@click=\"count++\"` work there. `count++` tries to reassign a `const`, and `this` isn''t used in `<script setup>`.","uk":"`ref` є об''єктом, чия властивість `.value` реактивна; у коді скрипта завжди звертайтеся через `.value`. Шаблони розгортають ref верхнього рівня автоматично, тому там працюють `{{ count }}` і `@click=\"count++\"`. `count++` намагається перепризначити `const`, а `this` у `<script setup>` не використовується."}'::jsonb, null::jsonb),
  ('vue-v-for-key', array['a']::text[], '{"en":"Vue reuses DOM nodes and component instances by key. With the index as key, after removing item 0 the old row 1 now has key 0, so Vue keeps the first DOM row (with its typed text) and drops the last. A stable id moves state with the item. Random keys recreate every row on each render, losing focus and state.","uk":"Vue повторно використовує DOM-вузли й екземпляри компонентів за ключем. Коли ключем є індекс, після видалення елемента 0 колишній рядок 1 отримує ключ 0, тож Vue лишає перший DOM-рядок (з введеним текстом) і прибирає останній. Стабільний id переносить стан разом з елементом. Випадкові ключі пересоздають кожен рядок на кожному рендері, втрачаючи фокус і стан."}'::jsonb, null::jsonb),
  ('vue-destructure-reactive', array['a']::text[], '{"en":"`reactive` tracks property access on the proxy. `const { count } = state` reads `state.count` once and stores the number `0` in a plain variable, which nothing can update. `toRefs(state)` turns each property into a ref linked to the original, so destructuring keeps reactivity (as do `computed(() => state.count)` and `storeToRefs` for Pinia).","uk":"`reactive` відстежує звернення до властивостей проксі. `const { count } = state` один раз читає `state.count` і зберігає число `0` у звичайній змінній, яку ніщо не оновить. `toRefs(state)` перетворює кожну властивість на ref, пов''язаний з оригіналом, тож деструктуризація зберігає реактивність (так само як `computed(() => state.count)` і `storeToRefs` для Pinia)."}'::jsonb, null::jsonb),
  ('vue-computed-vs-method', array['a']::text[], '{"en":"A computed remembers its result and its reactive dependencies, and recomputes lazily only after one of them changes. A method call in the template runs every time the component renders, three times here. Use computeds for derived data, and keep them free of side effects.","uk":"computed пам''ятає результат і свої реактивні залежності й ліниво переобчислюється лише після зміни однієї з них. Виклик методу в шаблоні виконується щоразу, коли компонент рендериться, тут тричі. Використовуйте computed для похідних даних і не робіть у них побічних ефектів."}'::jsonb, null::jsonb),
  ('vue-nexttick', array['a']::text[], '{"en":"Vue doesn''t patch the DOM synchronously on every change; it queues the component update and flushes it in a microtask, batching all changes from the same tick. Right after the push, the `<li>` doesn''t exist yet. `await nextTick()` resolves after the flush, when the DOM reflects the new state (useful for focusing or measuring new elements).","uk":"Vue не оновлює DOM синхронно при кожній зміні; він ставить оновлення компонента в чергу й виконує його в мікрозадачі, групуючи всі зміни одного «тіку». Одразу після push елемента `<li>` ще немає. `await nextTick()` завершується після оновлення, коли DOM уже відображає новий стан (корисно, щоб встановити фокус чи виміряти нові елементи)."}'::jsonb, null::jsonb),
  ('vue-prop-mutation', array['a']::text[], '{"en":"Data flows one way: the parent owns `query` and passes it down; the child asks for changes with events. `v-model` on a component is shorthand for `:modelValue` plus `@update:modelValue`, and `defineModel()` (Vue 3.4+) returns a ref that emits that event when written. If the child needs local, editable state, copy the prop into its own `ref`.","uk":"Дані течуть в один бік: батько володіє `query` і передає його вниз; дочірній компонент просить змін подіями. `v-model` на компоненті є скороченням для `:modelValue` плюс `@update:modelValue`, а `defineModel()` (Vue 3.4+) повертає ref, що надсилає цю подію під час запису. Якщо дочірньому компоненту потрібен локальний змінний стан, скопіюйте проп у власний `ref`."}'::jsonb, null::jsonb),
  ('vue-watch-immediate', array['a']::text[], '{"en":"`watch` only fires on changes after it''s created, unless `immediate: true`. `watchEffect` runs immediately and re-runs whenever any reactive value it read changes, which suits \"keep this in sync\" effects. Computeds are for pure derived values, not side effects like fetching, and `deep` is about nested object changes.","uk":"`watch` спрацьовує лише на зміни після створення, якщо не вказано `immediate: true`. `watchEffect` виконується одразу й перезапускається, коли змінюється будь-яке прочитане реактивне значення, тож підходить для ефектів «тримай це синхронним». computed призначені для чистих похідних значень, а не побічних ефектів на кшталт завантаження, а `deep` стосується змін у вкладених об''єктах."}'::jsonb, null::jsonb),
  ('vue-raw-vs-proxy', array['a']::text[], '{"en":"`reactive` returns a Proxy; only operations that go **through the proxy** are tracked and trigger effects. Writing to `raw` changes the same underlying object (so the count still ends at 2) but bypasses the proxy, so nothing re-renders until something else does. Vue caches one proxy per object, so `reactive(raw)` returns the same proxy every time.","uk":"`reactive` повертає Proxy; відстежуються й запускають ефекти лише операції, що йдуть **крізь проксі**. Запис у `raw` змінює той самий об''єкт (тож лічильник усе одно стає 2), але оминає проксі, тож нічого не перерендерюється, доки не станеться щось інше. Vue кешує один проксі на об''єкт, тож `reactive(raw)` щоразу повертає той самий проксі."}'::jsonb, null::jsonb),
  ('vue-mini-reactivity', null::text[], '{"en":"A global `activeEffect` plus a `WeakMap<target, Map<key, Set<effect>>>` is the whole trick: the proxy''s `get` records (effect, target, key) and `set` re-runs the effects stored for that key. Each effect clears its old dependencies before re-running, so branches switch cleanly. `ownKeys` and a special ITERATE key cover `Object.keys`. A computed is an effect whose scheduler only marks it dirty and notifies its own readers, which makes it lazy and cached. That''s the same design as `@vue/reactivity`.","uk":"Увесь секрет у глобальному `activeEffect` і `WeakMap<target, Map<key, Set<effect>>>`: `get` проксі записує (ефект, об''єкт, ключ), а `set` перезапускає ефекти, збережені для цього ключа. Кожен ефект очищає старі залежності перед повторним запуском, тож гілки перемикаються чисто. `ownKeys` і спеціальний ключ ITERATE покривають `Object.keys`. computed є ефектом, чий планувальник лише позначає його «брудним» і сповіщає власних читачів, що робить його лінивим і кешованим. Саме так влаштований `@vue/reactivity`."}'::jsonb, '{"/src/reactivity.ts":"type Dep = Set<ReactiveEffect>;\ntype ReactiveEffect = { run(): void; deps: Set<Dep> };\n\nlet activeEffect: ReactiveEffect | null = null;\nconst ITERATE = Symbol(\"iterate\");\nconst targetMap = new WeakMap<object, Map<PropertyKey, Dep>>(); // target → key → effects\nconst proxies = new WeakMap<object, object>();\n\nfunction track(target: object, key: PropertyKey) {\n  if (!activeEffect) return;\n  let deps = targetMap.get(target);\n  if (!deps) targetMap.set(target, (deps = new Map()));\n  let dep = deps.get(key);\n  if (!dep) deps.set(key, (dep = new Set()));\n  dep.add(activeEffect);\n  activeEffect.deps.add(dep); // so the effect can unsubscribe before its next run\n}\n\nfunction trigger(target: object, key: PropertyKey) {\n  const dep = targetMap.get(target)?.get(key);\n  if (!dep) return;\n  for (const e of [...dep]) if (e !== activeEffect) e.run();\n}\n\nconst isObject = (v: unknown): v is object => v !== null && typeof v === \"object\";\n\nexport function reactive<T extends object>(target: T): T {\n  const existing = proxies.get(target);\n  if (existing) return existing as T;\n  const proxy = new Proxy(target, {\n    get(obj, key, receiver) {\n      track(obj, key);\n      const value = Reflect.get(obj, key, receiver);\n      return isObject(value) ? reactive(value) : value; // deep, but lazy\n    },\n    set(obj, key, value, receiver) {\n      const had = Object.prototype.hasOwnProperty.call(obj, key);\n      const old = (obj as Record<PropertyKey, unknown>)[key];\n      const ok = Reflect.set(obj, key, value, receiver);\n      if (!had) {\n        trigger(obj, key);\n        if (Array.isArray(obj)) trigger(obj, \"length\"); // push adds an index; length is set afterwards with the same value\n        trigger(obj, ITERATE);\n      } else if (!Object.is(old, value)) {\n        trigger(obj, key);\n      }\n      return ok;\n    },\n    deleteProperty(obj, key) {\n      const had = Object.prototype.hasOwnProperty.call(obj, key);\n      const ok = Reflect.deleteProperty(obj, key);\n      if (had) {\n        trigger(obj, key);\n        trigger(obj, ITERATE);\n      }\n      return ok;\n    },\n    ownKeys(obj) {\n      track(obj, ITERATE); // Object.keys, for…in, spreading\n      return Reflect.ownKeys(obj);\n    },\n  });\n  proxies.set(target, proxy);\n  return proxy;\n}\n\nfunction cleanup(e: ReactiveEffect) {\n  for (const dep of e.deps) dep.delete(e);\n  e.deps.clear();\n}\n\nexport function effect(fn: () => void): () => void {\n  let active = true;\n  const e: ReactiveEffect = {\n    deps: new Set(),\n    run() {\n      if (!active) return;\n      cleanup(e); // re-collect dependencies on every run (branches may change)\n      const previous = activeEffect;\n      activeEffect = e;\n      try {\n        fn();\n      } finally {\n        activeEffect = previous;\n      }\n    },\n  };\n  e.run();\n  return () => {\n    active = false;\n    cleanup(e);\n  };\n}\n\nexport function computed<T>(getter: () => T): { readonly value: T } {\n  let value: T;\n  let dirty = true;\n  const self = {};\n  // Instead of recomputing on change, mark dirty and notify whoever reads .value.\n  const runner: ReactiveEffect = {\n    deps: new Set(),\n    run() {\n      if (dirty) return;\n      dirty = true;\n      trigger(self, \"value\");\n    },\n  };\n  return {\n    get value() {\n      if (dirty) {\n        cleanup(runner);\n        const previous = activeEffect;\n        activeEffect = runner;\n        try {\n          value = getter();\n        } finally {\n          activeEffect = previous;\n        }\n        dirty = false;\n      }\n      track(self, \"value\");\n      return value;\n    },\n  };\n}\n"}'::jsonb),
  ('a11y-aria-hidden-focusable', array['b']::text[], '{"en":"`aria-hidden` removes content from the accessibility tree but doesn''t stop keyboard focus, which leaves focusable elements that screen readers can''t describe. Use the `inert` attribute (it removes the content from both focus and the accessibility tree), or hide it with `display: none` / `hidden` when closed.","uk":"`aria-hidden` прибирає вміст із дерева доступності, але не блокує фокус клавіатури, тож лишаються фокусовані елементи, які зчитувачі екрана не можуть описати. Використовуйте атрибут `inert` (він прибирає вміст і з фокусу, і з дерева доступності) або ховайте панель через `display: none` / `hidden`, коли вона закрита."}'::jsonb, null::jsonb),
  ('a11y-name-precedence', array['c']::text[], '{"en":"The accessible name algorithm checks `aria-labelledby` first, then `aria-label`, then native labelling (content, `<label>`, `alt`), and `title` last. `aria-labelledby` wins here, so the name is the text of `#draft-title`. Keep the visible label inside the accessible name so speech-control users can say what they see (WCAG 2.5.3).","uk":"Алгоритм доступної назви спершу перевіряє `aria-labelledby`, далі `aria-label`, далі нативні мітки (вміст, `<label>`, `alt`), а `title` — останнім. Тут перемагає `aria-labelledby`, тож назва — це текст `#draft-title`. Тримайте видиму мітку в доступній назві, щоб користувачі голосового керування могли назвати те, що бачать (WCAG 2.5.3)."}'::jsonb, null::jsonb),
  ('a11y-focus-not-obscured', array['b']::text[], '{"en":"2.4.11 Focus Not Obscured (Minimum, AA) requires that a focused component is not entirely hidden by author-created content such as sticky headers or cookie banners. `scroll-padding-top` on the scroll container makes the browser leave room at the top when it scrolls focused elements into view. The outline is visible here; it''s just covered.","uk":"2.4.11 Focus Not Obscured (Minimum, AA) вимагає, щоб компонент із фокусом не був повністю схований вмістом автора, як-от липкими заголовками чи банерами cookie. `scroll-padding-top` на контейнері прокрутки змушує браузер лишати місце зверху, коли він прокручує елементи з фокусом у видиму область. Рамка тут видима — її просто перекрито."}'::jsonb, null::jsonb),
  ('a11y-roving-tabindex', null::text[], '{"en":"A roving tabindex keeps composite widgets to a single Tab stop: the active item gets `tabindex=\"0\"` and all the others get `-1`, so Tab moves past the toolbar while the arrow keys move within it. One delegated `keydown` listener maps keys to target indexes, and modulo arithmetic handles the wrapping. Handled keys call `preventDefault()` so arrows don''t also scroll the page.","uk":"Roving tabindex зводить складені віджети до однієї зупинки Tab: активний елемент отримує `tabindex=\"0\"`, а всі інші — `-1`, тож Tab проходить повз панель, а стрілки рухаються всередині неї. Один делегований обробник `keydown` зіставляє клавіші з цільовими індексами, а арифметика за модулем забезпечує перехід по колу. Оброблені клавіші викликають `preventDefault()`, щоб стрілки ще й не прокручували сторінку."}'::jsonb, '{"/src/toolbar.ts":"export function initToolbar(toolbar: HTMLElement): void {\n  const buttons = Array.from(toolbar.querySelectorAll<HTMLButtonElement>(\"button\"));\n  if (buttons.length === 0) return;\n\n  const makeTabStop = (target: HTMLButtonElement) => {\n    for (const button of buttons) button.tabIndex = button === target ? 0 : -1;\n  };\n  const focusAt = (index: number) => {\n    const target = buttons[(index + buttons.length) % buttons.length];\n    makeTabStop(target);\n    target.focus();\n  };\n\n  makeTabStop(buttons[0]);\n\n  toolbar.addEventListener(\"keydown\", (event) => {\n    const current = buttons.indexOf(document.activeElement as HTMLButtonElement);\n    if (current === -1) return;\n    const moves: Record<string, number> = {\n      ArrowRight: current + 1,\n      ArrowLeft: current - 1,\n      Home: 0,\n      End: buttons.length - 1,\n    };\n    if (!(event.key in moves)) return;\n    event.preventDefault();\n    focusAt(moves[event.key]);\n  });\n\n  toolbar.addEventListener(\"click\", (event) => {\n    const button = (event.target as HTMLElement).closest(\"button\");\n    if (button && buttons.includes(button as HTMLButtonElement)) makeTabStop(button as HTMLButtonElement);\n  });\n}\n"}'::jsonb),
  ('a11y-first-rule', array['a']::text[], '{"en":"ARIA changes semantics, not behaviour. You''d still need `tabindex=\"0\"`, key handlers and focus styles. That''s why the first rule of ARIA is to use the native element (`<button>`) whenever possible.","uk":"ARIA змінює семантику, а не поведінку. Вам усе одно знадобляться `tabindex=\"0\"`, обробники клавіш і стилі фокусу. Тому перше правило ARIA: використовувати нативний елемент (`<button>`), коли це можливо."}'::jsonb, null::jsonb),
  ('a11y-icon-button', array['a']::text[], '{"en":"`aria-label` (or visually hidden text) names the button, and `aria-hidden` on the decorative SVG prevents noise. A div isn''t a button, and an empty title gives no name.","uk":"`aria-label` (або візуально прихований текст) дає кнопці ім''я, а `aria-hidden` на декоративному SVG прибирає зайвий шум. Div не є кнопкою, а порожній title не дає імені."}'::jsonb, null::jsonb),
  ('a11y-contrast', array['b']::text[], '{"en":"AA requires 4.5:1 for normal text and 3:1 for large text (≈24px regular or 18.66px bold) and for UI component boundaries and focus indicators. 7:1 is the stricter AAA level.","uk":"AA вимагає 4,5:1 для звичайного тексту і 3:1 для великого (≈24px звичайного чи 18,66px жирного), а також для меж елементів інтерфейсу й індикаторів фокусу. 7:1 є суворішим рівнем AAA."}'::jsonb, null::jsonb),
  ('a11y-modal-focus', array['a', 'b', 'c']::text[], '{"en":"Keyboard and screen-reader users must land in the dialog, not tab into the page behind it, and get back where they were afterwards. The native `<dialog>` with `showModal()` provides inertness and Escape handling. Removing focus outlines breaks WCAG 2.4.7.","uk":"Користувачі клавіатури й зчитувачів екрана мають потрапити в діалог, а не переходити Tab на сторінку під ним, і після закриття повернутися туди, де були. Нативний `<dialog>` із `showModal()` забезпечує інертність фону й обробку Escape. Прибрання обведення фокусу порушує WCAG 2.4.7."}'::jsonb, null::jsonb),
  ('a11y-live-region', array['a']::text[], '{"en":"Live regions are announced when their content changes, but the region must already be in the DOM, otherwise some screen readers miss the first update. Use `polite` for non-urgent status and `role=\"alert\"` (assertive) for errors.","uk":"Живі регіони оголошуються, коли змінюється їхній вміст, але сам регіон має вже бути в DOM, інакше деякі зчитувачі пропустять перше оновлення. Використовуйте `polite` для нетермінових статусів і `role=\"alert\"` (assertive) для помилок."}'::jsonb, null::jsonb),
  ('a11y-accessible-switch', null::text[], '{"en":"`role=\"switch\"` with `aria-checked` tells assistive technology what the control is and its state, `aria-label` names it, and `tabIndex = 0` puts it in the tab order. Because ARIA adds no behaviour, you wire up Space and Enter yourself and prevent Space''s default scroll. Keeping state in `aria-checked` lets CSS style `[aria-checked=\"true\"]` from a single source of truth. A native `<button aria-pressed>` or `<input type=\"checkbox\" role=\"switch\">` would need less code.","uk":"`role=\"switch\"` разом з `aria-checked` повідомляє допоміжним технологіям, що це за елемент і в якому він стані, `aria-label` дає ім''я, а `tabIndex = 0` додає його в порядок табуляції. Оскільки ARIA не додає поведінки, Space і Enter треба під''єднати самостійно та скасувати прокрутку від Space. Стан в `aria-checked` дозволяє CSS стилізувати `[aria-checked=\"true\"]` з одного джерела правди. Нативні `<button aria-pressed>` або `<input type=\"checkbox\" role=\"switch\">` потребували б менше коду."}'::jsonb, '{"/src/switch.js":"export function enhanceSwitch(el, onChange) {\n  el.setAttribute(\"role\", \"switch\");\n  el.setAttribute(\"aria-label\", el.dataset.label ?? \"\");\n  el.setAttribute(\"aria-checked\", \"false\");\n  el.tabIndex = 0;\n\n  function toggle() {\n    const checked = el.getAttribute(\"aria-checked\") !== \"true\";\n    el.setAttribute(\"aria-checked\", String(checked));\n    onChange(checked);\n  }\n\n  el.addEventListener(\"click\", toggle);\n  el.addEventListener(\"keydown\", (event) => {\n    if (event.key === \" \" || event.key === \"Enter\") {\n      event.preventDefault(); // Space would otherwise scroll the page\n      toggle();\n    }\n  });\n}\n"}'::jsonb),
  ('perf-font-display', array['b']::text[], '{"en":"`swap` renders text in the fallback font right away and swaps in the web font when it loads, so text is never invisible (FOIT). Reduce the resulting layout shift by preloading the main font and tuning the fallback with `size-adjust`. `block` is the behaviour that hides text.","uk":"`swap` одразу рендерить текст резервним шрифтом і підміняє вебшрифт після завантаження, тож текст ніколи не буває невидимим (FOIT). Зменште зсув макета, що виникає, попереднім завантаженням основного шрифту й налаштуванням резервного через `size-adjust`. `block` — саме та поведінка, що ховає текст."}'::jsonb, null::jsonb),
  ('perf-content-visibility', array['a']::text[], '{"en":"`content-visibility: auto` skips rendering work for off-screen elements while keeping them in the DOM and accessibility tree, so find-in-page and anchor links still work. `contain-intrinsic-size` gives a placeholder size, so the scrollbar doesn''t jump. `display: none` removes content from the accessibility tree, and `will-change` adds layers instead of saving work.","uk":"`content-visibility: auto` пропускає роботу з рендерингу для елементів поза екраном, залишаючи їх у DOM і дереві доступності, тож пошук на сторінці та якорі працюють. `contain-intrinsic-size` задає розмір-заглушку, щоб смуга прокрутки не стрибала. `display: none` прибирає вміст із дерева доступності, а `will-change` додає шари замість економії роботи."}'::jsonb, null::jsonb),
  ('perf-detached-dom', array['b']::text[], '{"en":"Repeat the action several times so the leak stands out from one-time caches, then use the Memory panel''s comparison view or filter for \"Detached\". The retainers path shows what still references the removed nodes: typically a global listener, a timer, a cache map or a closure. Lighthouse measures page loads, not leaks during interaction.","uk":"Повторіть дію кілька разів, щоб витік вирізнявся на тлі одноразових кешів, потім скористайтеся порівнянням у панелі Memory або фільтром «Detached». Шлях утримувачів показує, що досі посилається на видалені вузли: зазвичай глобальний обробник, таймер, кеш-мапа чи замикання. Lighthouse вимірює завантаження сторінки, а не витоки під час взаємодії."}'::jsonb, null::jsonb),
  ('perf-throttle', null::text[], '{"en":"The closure tracks two things: whether a window is open (`timer`) and the latest arguments received during it. A call with no open window runs immediately and opens one. Calls during the window only overwrite `pendingArgs`. When the window ends, a pending call runs and opens a new window, so `fn` never runs more often than once per `wait`. Debounce waits for silence; throttle guarantees a steady rate.","uk":"Замикання відстежує дві речі: чи відкрите вікно (`timer`) і останні аргументи, отримані в ньому. Виклик без відкритого вікна виконується одразу й відкриває вікно. Виклики під час вікна лише перезаписують `pendingArgs`. Коли вікно закінчується, відкладений виклик виконується й відкриває нове вікно, тож `fn` ніколи не запускається частіше ніж раз на `wait`. Debounce чекає на тишу; throttle гарантує рівномірну частоту."}'::jsonb, '{"/src/throttle.ts":"export type Throttled<A extends unknown[]> = ((...args: A) => void) & { cancel(): void };\n\nexport function throttle<A extends unknown[]>(fn: (...args: A) => void, wait: number): Throttled<A> {\n  let timer: ReturnType<typeof setTimeout> | undefined;\n  let pendingArgs: A | undefined;\n\n  const endWindow = () => {\n    if (pendingArgs) {\n      const args = pendingArgs;\n      pendingArgs = undefined;\n      fn(...args);\n      timer = setTimeout(endWindow, wait); // the trailing call opens a new window\n    } else {\n      timer = undefined;\n    }\n  };\n\n  const throttled = (...args: A) => {\n    if (timer === undefined) {\n      fn(...args);\n      timer = setTimeout(endWindow, wait);\n    } else {\n      pendingArgs = args;\n    }\n  };\n\n  return Object.assign(throttled, {\n    cancel() {\n      clearTimeout(timer);\n      timer = undefined;\n      pendingArgs = undefined;\n    },\n  });\n}\n"}'::jsonb),
  ('perf-core-web-vitals', array['b']::text[], '{"en":"Interaction to Next Paint measures the delay from user input to the next frame being painted. LCP is about loading the main content, CLS about unexpected layout shifts, and TTFB about server response time.","uk":"Interaction to Next Paint вимірює затримку від дії користувача до наступного відмальованого кадру. LCP стосується завантаження основного вмісту, CLS неочікуваних зсувів розкладки, а TTFB часу відповіді сервера."}'::jsonb, null::jsonb),
  ('perf-transform-animation', array['c']::text[], '{"en":"`left`, `width` and `margin` change geometry and trigger layout and paint on every frame. `transform` (and `opacity`) can be handled by the compositor, often on the GPU, without re-running layout.","uk":"`left`, `width` і `margin` змінюють геометрію й запускають layout і paint на кожному кадрі. `transform` (і `opacity`) може обробити композитор, часто на GPU, без повторного layout."}'::jsonb, null::jsonb),
  ('perf-cls-images', array['a']::text[], '{"en":"Without dimensions the browser allocates 0 height until the image arrives, then pushes content down, which is CLS. Intrinsic dimensions let it reserve the right box upfront. Lazy loading or smaller formats help loading time but not shifts.","uk":"Без розмірів браузер виділяє нульову висоту, доки зображення не завантажиться, а потім зсуває вміст донизу: це і є CLS. Власні розміри дозволяють одразу зарезервувати правильний блок. Ліниве завантаження чи менші формати пришвидшують завантаження, але не прибирають зсувів."}'::jsonb, null::jsonb),
  ('perf-debounce-vs-throttle', array['b']::text[], '{"en":"Throttle gives regular updates during a continuous stream of events. Debounce waits for a pause, which suits search-as-you-type or saving drafts. For scroll-linked visuals, `requestAnimationFrame` or IntersectionObserver are even better.","uk":"Throttle дає регулярні оновлення під час безперервного потоку подій. Debounce чекає на паузу, що підходить для пошуку під час введення чи збереження чернеток. Для візуальних ефектів, пов''язаних із прокруткою, ще краще підходять `requestAnimationFrame` або IntersectionObserver."}'::jsonb, null::jsonb),
  ('perf-long-task', array['a', 'b', 'd']::text[], '{"en":"A long synchronous task blocks input and paint. A worker moves it off the main thread, and chunking with yields lets the browser handle events between chunks. Painting feedback first makes the interaction feel immediate. An `async` function without `await` still runs synchronously.","uk":"Довга синхронна задача блокує введення й відмальовування. Воркер виносить її з головного потоку, а розбиття на частини з поступками дозволяє браузеру обробляти події між ними. Якщо спершу відмалювати відгук, взаємодія здається миттєвою. `async`-функція без `await` все одно виконується синхронно."}'::jsonb, null::jsonb),
  ('perf-debounce', null::text[], '{"en":"Keep the pending timer in a closure. Each call clears it and schedules a new one with the latest arguments, so only the call after a quiet period fires. Use a regular `function` (not an arrow) so `this` comes from the caller, then forward it with `apply`. `cancel` simply clears the timer.","uk":"Тримайте відкладений таймер у замиканні. Кожен виклик очищає його й планує новий з останніми аргументами, тож спрацьовує лише виклик після паузи. Використайте звичайну `function` (не стрілкову), щоб `this` брався від викликача, і передайте його через `apply`. `cancel` просто очищає таймер."}'::jsonb, '{"/src/debounce.ts":"export type Debounced<A extends unknown[]> = ((...args: A) => void) & { cancel(): void };\n\nexport function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number): Debounced<A> {\n  let timer: ReturnType<typeof setTimeout> | undefined;\n\n  const debounced = function (this: unknown, ...args: A) {\n    clearTimeout(timer);\n    timer = setTimeout(() => {\n      timer = undefined;\n      fn.apply(this, args);\n    }, wait);\n  } as Debounced<A>;\n\n  debounced.cancel = () => {\n    clearTimeout(timer);\n    timer = undefined;\n  };\n\n  return debounced;\n}\n"}'::jsonb),
  ('sec-xss-what', array['a']::text[], '{"en":"XSS happens when untrusted input ends up executed as code in your page: stored in a database, reflected from a URL, or written into a DOM sink by your own JavaScript. Because it runs in your origin, the same-origin policy doesn''t protect you; the attacker can do anything the user can.","uk":"XSS стається, коли неперевірені дані зрештою виконуються як код на вашій сторінці: збережені в базі, відбиті з URL або записані у DOM-сток вашим же JavaScript. Оскільки він виконується у вашому джерелі, політика одного джерела не захищає; зловмисник може все, що може користувач."}'::jsonb, null::jsonb),
  ('sec-react-href', array['a']::text[], '{"en":"JSX escapes text and attribute values so they can''t become markup, but an attribute that *is* a URL can still carry the `javascript:` scheme. React only logs a warning about it. Validate the protocol (parse with `new URL` and allow-list schemes) before rendering user-supplied links.","uk":"JSX екранує текст і значення атрибутів, щоб вони не стали розміткою, але атрибут, який *є* URL, усе одно може містити схему `javascript:`. React лише виводить про це попередження. Перевіряйте протокол (розберіть через `new URL` і використайте білий список схем) перед рендером посилань від користувачів."}'::jsonb, null::jsonb),
  ('sec-samesite', array['a']::text[], '{"en":"CSRF works because the browser attaches cookies to requests another site triggers. `SameSite=Lax` withholds the cookie on cross-site subrequests and POSTs (it''s the default in modern browsers), and `Strict` also on cross-site navigations. `HttpOnly` hides the cookie from JavaScript and `Secure` limits it to HTTPS; neither affects cross-site sending.","uk":"CSRF працює, бо браузер додає cookie до запитів, які ініціює інший сайт. `SameSite=Lax` не надсилає cookie в міжсайтових підзапитах і POST (це типове значення в сучасних браузерах), а `Strict` ще й при міжсайтових переходах. `HttpOnly` ховає cookie від JavaScript, а `Secure` обмежує його HTTPS; жоден не впливає на міжсайтове надсилання."}'::jsonb, null::jsonb),
  ('sec-httponly-limits', array['a']::text[], '{"en":"`HttpOnly` stops scripts from reading the cookie, so it can''t be exfiltrated and reused elsewhere. But `fetch` from the page still attaches it automatically, so the injected script can act as the user for as long as it runs. That''s why preventing XSS (escaping, CSP) matters more than where the token lives.","uk":"`HttpOnly` не дає скриптам читати cookie, тож його не можна викрасти й використати деінде. Але `fetch` зі сторінки все одно автоматично його додає, тож вставлений скрипт може діяти від імені користувача, поки виконується. Тому запобігання XSS (екранування, CSP) важливіше за місце зберігання токена."}'::jsonb, null::jsonb),
  ('sec-csp-inline', array['a']::text[], '{"en":"Without `''unsafe-inline''`, CSP refuses inline `<script>` blocks and inline event-handler attributes, which is what most injected payloads use, while `''self''` still allows scripts from your origin. Adding `''unsafe-inline''` throws that protection away; use nonces or hashes for the few inline scripts you really need.","uk":"Без `''unsafe-inline''` CSP відмовляється виконувати вбудовані блоки `<script>` і атрибути-обробники подій, а саме їх використовує більшість вставлених атак, тоді як `''self''` дозволяє скрипти з вашого джерела. Додавання `''unsafe-inline''` зводить цей захист нанівець; для кількох справді потрібних вбудованих скриптів використовуйте nonce або хеші."}'::jsonb, null::jsonb),
  ('sec-cors-not-csrf', array['a']::text[], '{"en":"A form POST is a \"simple\" request: no preflight, and it has always been allowed cross-site. The same-origin policy and CORS govern whether the *page* can read the response, not whether the request reaches the server. Defend state-changing endpoints with `SameSite` cookies, CSRF tokens, or by requiring a custom header or JSON content type, which forces a preflight.","uk":"POST із форми є «простим» запитом: без preflight, і міжсайтово він дозволений завжди. Політика одного джерела й CORS визначають, чи може *сторінка* прочитати відповідь, а не чи дійде запит до сервера. Захищайте ендпоінти, що змінюють стан, cookie з `SameSite`, CSRF-токенами або вимогою власного заголовка чи JSON content type, що змушує робити preflight."}'::jsonb, null::jsonb),
  ('sec-open-redirect', array['a']::text[], '{"en":"String checks miss the parser''s tricks: `//evil.example` and `/\\evil.example` start with `/` but are protocol-relative URLs to another host; `https://evil.example/?x=app.example` contains your hostname. Resolving with the URL parser against your origin and comparing origins asks the same question the browser will. Then redirect to the parsed path, not the raw string.","uk":"Рядкові перевірки не враховують трюків парсера: `//evil.example` і `/\\evil.example` починаються з `/`, але є протокол-відносними URL на інший хост; `https://evil.example/?x=app.example` містить ваше ім''я хоста. Розбір через URL-парсер відносно вашого джерела й порівняння origin ставить те саме питання, що й браузер. Далі перенаправляйте на розібраний шлях, а не на сирий рядок."}'::jsonb, null::jsonb),
  ('sec-dom-sinks', array['a', 'c', 'e']::text[], '{"en":"`innerHTML` and `insertAdjacentHTML` parse markup, so `<img src=x onerror=…>` runs. Assigning `location.href` executes a `javascript:` URL. `textContent` always inserts text, and setting a non-event, non-URL attribute like `title` with `setAttribute` stores a plain string. (Event attributes like `onclick`, and URL attributes like `href` or `src`, would be sinks.)","uk":"`innerHTML` і `insertAdjacentHTML` розбирають розмітку, тож `<img src=x onerror=…>` виконається. Присвоєння `location.href` виконує URL `javascript:`. `textContent` завжди вставляє текст, а встановлення через `setAttribute` атрибута, що не є подією чи URL, як-от `title`, зберігає звичайний рядок. (Атрибути подій на кшталт `onclick` і URL-атрибути як `href` чи `src` були б стоками.)"}'::jsonb, null::jsonb),
  ('sec-safe-links', null::text[], '{"en":"Blocklists of strings lose to the parser: browsers ignore case, strip tabs and newlines inside the scheme, and skip leading control characters. Parsing with `new URL` and allow-listing the resulting `protocol` checks exactly what the browser will execute. Building the element with `textContent` and `setAttribute` means the label is never parsed as HTML and the URL can''t close the attribute quote.","uk":"Чорні списки рядків програють парсеру: браузери ігнорують регістр, прибирають табуляції й переноси в схемі й пропускають керівні символи на початку. Розбір через `new URL` і білий список для отриманого `protocol` перевіряють саме те, що виконає браузер. Побудова елемента через `textContent` і `setAttribute` означає, що підпис ніколи не розбирається як HTML, а URL не може закрити лапки атрибута."}'::jsonb, '{"/src/links.ts":"const ALLOWED_PROTOCOLS = new Set([\"http:\", \"https:\", \"mailto:\"]);\n\nexport function sanitizeUrl(input: string): string {\n  const trimmed = input.trim();\n  try {\n    // Let the URL parser decide the scheme, exactly as the browser will: it ignores case,\n    // strips tabs/newlines and leading control characters. Relative URLs resolve against a dummy base.\n    const url = new URL(trimmed, \"https://app.invalid\");\n    return ALLOWED_PROTOCOLS.has(url.protocol) ? trimmed : \"about:blank\";\n  } catch {\n    return \"about:blank\";\n  }\n}\n\nexport function renderLink(label: string, href: string): HTMLAnchorElement {\n  const a = document.createElement(\"a\");\n  a.textContent = label; // text, never HTML\n  a.setAttribute(\"href\", sanitizeUrl(href)); // an attribute value can''t break out into markup\n  a.setAttribute(\"target\", \"_blank\");\n  a.setAttribute(\"rel\", \"noopener noreferrer\");\n  return a;\n}\n"}'::jsonb),
  ('sec-html-template', null::text[], '{"en":"A tagged template receives the literal parts and the values separately, so it can escape only what came from data. Escaping all five characters makes values safe both as text and inside quoted attributes. Marking trusted output with a class (checked with `instanceof`) lets nested templates compose without double-escaping, and lookalike objects can''t forge that trust. This is the idea behind lit-html and JSX auto-escaping.","uk":"Тегований шаблон отримує літеральні частини й значення окремо, тож може екранувати лише те, що прийшло з даних. Екранування всіх п''яти символів робить значення безпечними і як текст, і всередині атрибутів у лапках. Позначення довіреного результату класом (перевірка через `instanceof`) дає змогу вкладати шаблони без подвійного екранування, а об''єкти-імітації не можуть підробити цю довіру. На цій ідеї побудовані lit-html і автоекранування в JSX."}'::jsonb, '{"/src/html.ts":"const ESCAPES: Record<string, string> = {\n  \"&\": \"&amp;\",\n  \"<\": \"&lt;\",\n  \">\": \"&gt;\",\n  ''\"'': \"&quot;\",\n  \"''\": \"&#39;\",\n};\n\nexport function escapeHtml(value: unknown): string {\n  return String(value).replace(/[&<>\"'']/g, (ch) => ESCAPES[ch]);\n}\n\nexport class SafeHtml {\n  constructor(private readonly value: string) {}\n  toString() {\n    return this.value;\n  }\n}\n\nfunction render(value: unknown): string {\n  if (value === null || value === undefined || value === false) return \"\";\n  // Only real SafeHtml instances are trusted; an object with a toString() is not.\n  if (value instanceof SafeHtml) return value.toString();\n  if (Array.isArray(value)) return value.map(render).join(\"\");\n  return escapeHtml(value);\n}\n\nexport function html(strings: TemplateStringsArray, ...values: unknown[]): SafeHtml {\n  let out = strings[0];\n  values.forEach((value, i) => {\n    out += render(value) + strings[i + 1];\n  });\n  return new SafeHtml(out);\n}\n"}'::jsonb),
  ('ww-why', array['a']::text[], '{"en":"A worker doesn''t make the work faster (it may even add copying overhead), but it takes it off the thread that handles clicks and paints frames, so the page stays responsive. The worker can''t touch the DOM: it posts the parsed result back, and the main thread renders it.","uk":"Worker не пришвидшує саму роботу (може навіть додати витрат на копіювання), але забирає її з потоку, що обробляє кліки й малює кадри, тож сторінка лишається чуйною. Worker не має доступу до DOM: він надсилає результат розбору назад, а головний потік його рендерить."}'::jsonb, null::jsonb),
  ('ww-no-dom', array['a']::text[], '{"en":"Workers have no DOM, no `window`, and none of the synchronous, DOM-bound storage APIs (`localStorage`, `sessionStorage`, `document.cookie`). They do have `fetch`, WebSockets, IndexedDB, timers, `crypto`, WebAssembly and `OffscreenCanvas`. To change the page, post a message and let the main thread update the DOM.","uk":"Worker не має DOM, `window` і жодного з синхронних API сховища, прив''язаних до DOM (`localStorage`, `sessionStorage`, `document.cookie`). Натомість у нього є `fetch`, WebSocket, IndexedDB, таймери, `crypto`, WebAssembly й `OffscreenCanvas`. Щоб змінити сторінку, надішліть повідомлення, і головний потік оновить DOM."}'::jsonb, null::jsonb),
  ('ww-clone-function', array['a']::text[], '{"en":"The structured clone algorithm copies data, not behaviour: functions (and DOM nodes) can''t be cloned, so the whole call throws a `DataCloneError` (unlike `JSON.stringify`, which silently drops functions). Send plain data and a message type, and keep the logic on each side.","uk":"Алгоритм структурованого клонування копіює дані, а не поведінку: функції (і DOM-вузли) клонувати не можна, тож увесь виклик кидає `DataCloneError` (на відміну від `JSON.stringify`, що мовчки відкидає функції). Надсилайте звичайні дані й тип повідомлення, а логіку тримайте на кожному боці."}'::jsonb, null::jsonb),
  ('ww-transfer', array['a']::text[], '{"en":"Listing the buffer in the transfer list moves ownership instead of copying: the receiver gets the memory, and the sender''s `ArrayBuffer` is detached, with `byteLength` 0. That makes sending large binary data (images, audio, WASM memory) nearly free. Without the transfer list, the data would be copied.","uk":"Перелік буфера у списку передачі переміщує володіння замість копіювання: отримувач отримує пам''ять, а `ArrayBuffer` відправника від''єднується, і `byteLength` стає 0. Так надсилання великих двійкових даних (зображень, аудіо, пам''яті WASM) стає майже безкоштовним. Без списку передачі дані скопіювалися б."}'::jsonb, null::jsonb),
  ('ww-class-instance', array['a']::text[], '{"en":"Structured clone copies an object''s own data properties into a plain object; the prototype (and therefore the class and its methods) is not transferred. On the receiving side, rebuild instances explicitly (`Point.from(data)`) or design messages as plain data.","uk":"Структуроване клонування копіює власні властивості з даними в звичайний об''єкт; прототип (а отже клас і його методи) не передається. На боці отримувача відтворюйте екземпляри явно (`Point.from(data)`) або проєктуйте повідомлення як звичайні дані."}'::jsonb, null::jsonb),
  ('ww-kinds', array['a']::text[], '{"en":"A dedicated worker belongs to one page. A SharedWorker is shared by every same-origin page that connects to it (via `port`), so it can own a single connection or cache. Service workers are event-driven network proxies that the browser stops when idle, so they can''t hold long-lived sockets. (Safari added SharedWorker support back in 16; check your targets.)","uk":"Dedicated worker належить одній сторінці. SharedWorker спільний для всіх сторінок того самого джерела, що під''єднуються до нього (через `port`), тож може володіти одним з''єднанням чи кешем. Service worker є мережевим проксі, що працює за подіями й зупиняється браузером у простої, тож не може тримати довготривалі сокети. (Safari повернув підтримку SharedWorker у версії 16; перевірте цільові браузери.)"}'::jsonb, null::jsonb),
  ('ww-shared-array-buffer', array['a']::text[], '{"en":"After the Spectre attacks, browsers expose shared memory (and high-resolution timers) only to cross-origin isolated pages, where no untrusted cross-origin content can be loaded without opting in. Set COOP and COEP headers, make sure embedded third-party resources send CORP/CORS headers, and check `self.crossOriginIsolated`.","uk":"Після атак Spectre браузери відкривають спільну пам''ять (і таймери високої точності) лише сторінкам, ізольованим між джерелами, де не можна завантажити недовірений міжджерельний вміст без згоди. Встановіть заголовки COOP і COEP, переконайтеся, що вбудовані сторонні ресурси надсилають заголовки CORP/CORS, і перевіряйте `self.crossOriginIsolated`."}'::jsonb, null::jsonb),
  ('ww-request-ids', array['a']::text[], '{"en":"Messages are a single stream; when work inside the worker finishes in a different order than it started, \"the next message\" belongs to a different request. Correlation ids are the standard fix (it''s what Comlink and JSON-RPC do), and they also enable timeouts and error responses per request. Serialising or spawning workers avoids the bug only by giving up concurrency.","uk":"Повідомлення є одним потоком; коли робота всередині worker завершується в іншому порядку, ніж почалася, «наступне повідомлення» належить іншому запиту. Ідентифікатори кореляції є стандартним виправленням (так роблять Comlink і JSON-RPC), а ще вони дають тайм-аути й відповіді з помилками для кожного запиту. Послідовне виконання чи створення нових worker уникають бага лише ціною відмови від паралельності."}'::jsonb, null::jsonb),
  ('ww-overhead', array['a']::text[], '{"en":"Offloading only pays off when the work saved is bigger than the cost of moving data. Cloning happens on the sending thread, so a large payload per message blocks the very thread you wanted to free. Keep large state inside the worker and send small commands; for binary data, transfer buffers or use `SharedArrayBuffer`. Always measure before and after.","uk":"Перенесення окуповується лише тоді, коли заощаджена робота більша за вартість переміщення даних. Клонування відбувається в потоці-відправнику, тож великий обсяг даних на кожне повідомлення блокує саме той потік, який ви хотіли звільнити. Тримайте великий стан усередині worker і надсилайте невеликі команди; для двійкових даних передавайте буфери чи використовуйте `SharedArrayBuffer`. Завжди вимірюйте до й після."}'::jsonb, null::jsonb),
  ('ww-rpc', null::text[], '{"en":"A map from request id to `{ resolve, reject, timer }` turns a single message stream into independent promises: each response finds its own caller, regardless of order. Deleting the entry on timeout means a late response finds nothing and is dropped. On the worker side, `try/catch` around an awaited handler turns both sync throws and rejections into error responses, and the own-property check stops callers from invoking `Object.prototype` methods.","uk":"Мапа з id запиту на `{ resolve, reject, timer }` перетворює один потік повідомлень на незалежні проміси: кожна відповідь знаходить свого викликача незалежно від порядку. Видалення запису після тайм-ауту означає, що пізня відповідь нічого не знайде й буде відкинута. На боці worker `try/catch` навколо обробника з `await` перетворює і синхронні винятки, і відхилення на відповіді з помилкою, а перевірка власних властивостей не дає викликати методи `Object.prototype`."}'::jsonb, '{"/src/rpc.ts":"/** The part of Worker / MessagePort this module needs. */\nexport interface PortLike {\n  postMessage(message: unknown): void;\n  onmessage: ((event: { data: any }) => void) | null;\n}\n\nexport type Handlers = Record<string, (...args: any[]) => unknown>;\n\ntype Pending = { resolve: (value: unknown) => void; reject: (error: Error) => void; timer: ReturnType<typeof setTimeout> };\n\nexport function createRpcClient(port: PortLike, options: { timeoutMs?: number } = {}) {\n  const { timeoutMs = 5000 } = options;\n  let nextId = 1;\n  const pending = new Map<number, Pending>();\n\n  port.onmessage = (event) => {\n    const msg = event.data;\n    if (!msg || typeof msg.id !== \"number\") return; // not one of ours\n    const entry = pending.get(msg.id);\n    if (!entry) return; // already timed out\n    pending.delete(msg.id);\n    clearTimeout(entry.timer);\n    if (msg.error !== undefined) entry.reject(new Error(msg.error));\n    else entry.resolve(msg.result);\n  };\n\n  return {\n    call<T = unknown>(method: string, ...args: unknown[]): Promise<T> {\n      const id = nextId++;\n      return new Promise<T>((resolve, reject) => {\n        const timer = setTimeout(() => {\n          pending.delete(id);\n          reject(new Error(\"Timed out: \" + method));\n        }, timeoutMs);\n        pending.set(id, { resolve: resolve as (value: unknown) => void, reject, timer });\n        port.postMessage({ id, method, args });\n      });\n    },\n  };\n}\n\nexport function exposeRpc(port: PortLike, handlers: Handlers) {\n  port.onmessage = async (event) => {\n    const msg = event.data;\n    if (!msg || typeof msg.id !== \"number\") return;\n    try {\n      // Own properties only, so \"toString\" or \"__proto__\" can''t reach Object.prototype.\n      if (!Object.prototype.hasOwnProperty.call(handlers, msg.method)) throw new Error(\"Unknown method: \" + msg.method);\n      const result = await handlers[msg.method](...(msg.args ?? []));\n      port.postMessage({ id: msg.id, result });\n    } catch (error) {\n      port.postMessage({ id: msg.id, error: error instanceof Error ? error.message : String(error) });\n    }\n  };\n}\n"}'::jsonb),
  ('ws-heartbeat-monitor', null::text[], '{"en":"TCP can take minutes to notice a connection that has died, so the application needs its own liveness check: the heartbeat. Each ping is a question with an expected answer, and counting unanswered questions (rather than reacting to the first one) tolerates a single lost packet. The timer and the clear function are passed in, which is what makes the logic testable without real waiting: the test ticks the clock by hand and checks exactly when `onDead` fires. Clearing the timer before calling `onDead` prevents a late tick from counting again after the connection was already declared dead. In production the reaction to `onDead` is the reconnection logic (with backoff, as in the reconnecting client task).","uk":"TCP може довго не помічати мертве з''єднання, тому застосунку потрібна власна перевірка живості: серцебиття. Кожен ping — це запитання з очікуваною відповіддю, і підрахунок без відповіді (а не реакція на перший пропуск) переносить втрату одного пакета. Таймер і функцію очищення передано ззовні, і саме це робить логіку придатною до тестування без реального очікування: тест вручну рухає годинник і перевіряє, коли саме спрацьовує `onDead`. Очищення таймера перед викликом `onDead` не дає запізнілому тіку зарахувати пропуск після того, як з''єднання вже визнано мертвим. У продакшені реакцією на `onDead` є логіка перепідключення (з backoff, як у задачі про reconnecting client)."}'::jsonb, '{"/src/heartbeat.ts":"export type HeartbeatOptions = {\n  intervalMs: number;\n  maxMissed: number;\n  send: () => void;\n  onDead: () => void;\n  setTimer?: (fn: () => void, ms: number) => unknown;\n  clearTimer?: (id: unknown) => void;\n};\n\nexport function createHeartbeat({\n  intervalMs,\n  maxMissed,\n  send,\n  onDead,\n  setTimer = (fn, ms) => setInterval(fn, ms),\n  clearTimer = (id) => clearInterval(id as ReturnType<typeof setInterval>),\n}: HeartbeatOptions) {\n  let timer: unknown = null;\n  let waiting = false; // a ping has been sent and no pong has come back yet\n  let missed = 0;\n\n  const stop = () => {\n    if (timer !== null) {\n      clearTimer(timer);\n      timer = null;\n    }\n  };\n\n  const beat = () => {\n    if (waiting) missed++;\n    if (missed >= maxMissed) {\n      stop();\n      onDead();\n      return;\n    }\n    waiting = true;\n    send();\n  };\n\n  return {\n    start() {\n      stop();\n      missed = 0;\n      waiting = false;\n      beat();\n      timer = setTimer(beat, intervalMs);\n    },\n    pong() {\n      waiting = false;\n      missed = 0;\n    },\n    stop,\n    get missed(): number {\n      return missed;\n    },\n  };\n}\n"}'::jsonb),
  ('ws-choose-sse', array['a']::text[], '{"en":"SSE is built for one-way server → client streams: plain HTTP (so cookies, proxies and HTTP/2 just work), automatic reconnection and resuming with `Last-Event-ID`. WebSockets add value when the client also sends frequent messages. Very fast polling wastes requests, and WebRTC is for peer-to-peer media and data.","uk":"SSE створено для однобічних потоків сервер → клієнт: звичайний HTTP (тож cookie, проксі й HTTP/2 просто працюють), автоматичне перепідключення й продовження з `Last-Event-ID`. WebSocket має сенс, коли клієнт теж часто надсилає повідомлення. Дуже часте опитування марнує запити, а WebRTC призначений для медіа й даних між учасниками напряму."}'::jsonb, null::jsonb),
  ('ws-handshake', array['a']::text[], '{"en":"WebSockets reuse HTTP for the opening handshake, so they work on ports 80/443 through most infrastructure. After `101 Switching Protocols`, the same TCP connection carries framed messages in both directions. Use `wss://` (over TLS) in production.","uk":"WebSocket використовує HTTP для початкового рукостискання, тож працює на портах 80/443 крізь більшість інфраструктури. Після `101 Switching Protocols` те саме TCP-з''єднання передає повідомлення кадрами в обох напрямках. У продакшені використовуйте `wss://` (поверх TLS)."}'::jsonb, null::jsonb),
  ('ws-thundering-herd', array['a']::text[], '{"en":"Fixed intervals synchronise clients, so they all hit the server at the same instants (a thundering herd). Doubling the delay after each failure reduces the load, and jitter spreads clients out in time. A cap keeps the delay reasonable. Reset the backoff after a successful connection.","uk":"Фіксовані інтервали синхронізують клієнтів, тож вони всі звертаються до сервера в ті самі миті (thundering herd). Подвоєння затримки після кожної невдачі зменшує навантаження, а випадковий розкид розносить клієнтів у часі. Верхня межа тримає затримку розумною. Скидайте наростання після успішного з''єднання."}'::jsonb, null::jsonb),
  ('ws-origin-check', array['a']::text[], '{"en":"The same-origin policy and CORS don''t apply to WebSockets, and cookies for the target site are attached to the handshake (subject to `SameSite`). Without an `Origin` allow-list, any site can open an authenticated socket. Check `Origin`, use `SameSite` cookies or a short-lived token, and authorise every action. TLS protects the transport, not against this.","uk":"Політика одного джерела й CORS не застосовуються до WebSocket, а cookie цільового сайту додаються до рукостискання (з урахуванням `SameSite`). Без білого списку `Origin` будь-який сайт може відкрити автентифікований сокет. Перевіряйте `Origin`, використовуйте cookie з `SameSite` чи короткоживучий токен і авторизуйте кожну дію. TLS захищає канал, але не від цього."}'::jsonb, null::jsonb),
  ('ws-duplicates-after-reconnect', array['a']::text[], '{"en":"A single connection is ordered, but a reconnect is a new connection: messages can be lost in between, and a client that retries a send can deliver it twice. Sequence numbers let the client ask \"what did I miss since #1042?\", and IDs make applying a message idempotent. Optimistic sends should carry a client-generated ID so the server echo can be matched.","uk":"Одне з''єднання впорядковане, але перепідключення є новим з''єднанням: повідомлення можуть загубитися між ними, а клієнт, що повторює надсилання, може доставити його двічі. Порядкові номери дають клієнту спитати «що я пропустив після №1042?», а ID роблять застосування повідомлення ідемпотентним. Оптимістичні надсилання мають нести ID, згенерований клієнтом, щоб зіставити відповідь сервера."}'::jsonb, null::jsonb),
  ('ws-scaling-pubsub', array['a']::text[], '{"en":"Each WebSocket lives on one server process, which only knows its own connections. A message bus fans messages out across servers. Sticky sessions keep a client on the same server but don''t share messages between servers; a single bigger server only postpones the problem.","uk":"Кожен WebSocket живе в одному серверному процесі, який знає лише власні з''єднання. Шина повідомлень розсилає повідомлення між серверами. «Липкі» сесії тримають клієнта на тому самому сервері, але не діляться повідомленнями між серверами; один більший сервер лише відкладає проблему."}'::jsonb, null::jsonb),
  ('ws-reconnecting-client', null::text[], '{"en":"The wrapper owns the lifecycle: `connect()` creates a socket and wires its handlers, `onclose` decides whether to reconnect, and `onopen` resets the backoff and drains the queue. A `closedByUser` flag distinguishes intentional closes from drops and is checked again when a scheduled reconnect fires. Injecting `createSocket`, `schedule` and `random` makes timing deterministic and testable.","uk":"Обгортка керує життєвим циклом: `connect()` створює сокет і під''єднує обробники, `onclose` вирішує, чи перепідключатися, а `onopen` скидає наростання затримки й спорожнює чергу. Прапорець `closedByUser` відрізняє навмисне закриття від обриву й перевіряється ще раз, коли спрацьовує заплановане перепідключення. Впровадження `createSocket`, `schedule` і `random` робить таймінг детермінованим і тестованим."}'::jsonb, '{"/src/socket.ts":"/** The subset of the WebSocket API this client needs (readyState: 0 connecting, 1 open, 3 closed). */\nexport interface SocketLike {\n  readyState: number;\n  send(data: string): void;\n  close(): void;\n  onopen: (() => void) | null;\n  onmessage: ((event: { data: string }) => void) | null;\n  onclose: ((event: { code: number }) => void) | null;\n}\n\nexport type ReconnectOptions = {\n  createSocket: (url: string) => SocketLike;\n  /** First retry delay in ms (default 500); doubles on each failed attempt. */\n  baseDelay?: number;\n  /** Upper bound for the delay in ms (default 10000). */\n  maxDelay?: number;\n  /** Jitter source in [0, 1) (default Math.random). */\n  random?: () => number;\n  /** Timer function (default setTimeout). */\n  schedule?: (fn: () => void, ms: number) => void;\n};\n\nexport type Status = \"connecting\" | \"open\" | \"closed\";\n\nexport function createReconnectingSocket(url: string, options: ReconnectOptions) {\n  const {\n    createSocket,\n    baseDelay = 500,\n    maxDelay = 10000,\n    random = Math.random,\n    schedule = (fn: () => void, ms: number) => {\n      setTimeout(fn, ms);\n    },\n  } = options;\n  const listeners = new Set<(data: string) => void>();\n  const queue: string[] = [];\n  let socket: SocketLike;\n  let status: Status = \"connecting\";\n  let attempt = 0;\n  let closedByUser = false;\n\n  function connect() {\n    status = \"connecting\";\n    socket = createSocket(url);\n    socket.onopen = () => {\n      status = \"open\";\n      attempt = 0; // a successful connection resets the backoff\n      while (queue.length) socket.send(queue.shift()!);\n    };\n    socket.onmessage = (event) => {\n      for (const listener of [...listeners]) listener(event.data);\n    };\n    socket.onclose = () => {\n      if (closedByUser) {\n        status = \"closed\";\n        return;\n      }\n      status = \"connecting\";\n      // Exponential backoff, capped, with jitter so clients don''t reconnect in lockstep.\n      const delay = Math.min(maxDelay, baseDelay * 2 ** attempt) * (0.5 + random() / 2);\n      attempt++;\n      schedule(() => {\n        if (!closedByUser) connect();\n      }, delay);\n    };\n  }\n\n  connect();\n\n  return {\n    get status(): Status {\n      return status;\n    },\n    send(data: string) {\n      if (status === \"open\") socket.send(data);\n      else if (!closedByUser) queue.push(data);\n    },\n    onMessage(listener: (data: string) => void) {\n      listeners.add(listener);\n      return () => {\n        listeners.delete(listener);\n      };\n    },\n    close() {\n      closedByUser = true;\n      status = \"closed\";\n      queue.length = 0;\n      socket.close();\n    },\n  };\n}\n"}'::jsonb)
) as v(task_slug, correct_option_ids, explanation, solution_files)
join public.tasks t on t.slug = v.task_slug and t.source = 'seed'
on conflict (task_id) do update set correct_option_ids = excluded.correct_option_ids,
  explanation = excluded.explanation, solution_files = excluded.solution_files;

update public.skills s set has_content = exists (
  select 1 from public.task_skills ts join public.tasks t on t.id = ts.task_id and t.published where ts.skill_id = s.id);

insert into public.courses as cur (slug, title, summary, topics, sort_order) values
  ('csharp', '{"en":"C#","uk":"C#"}'::jsonb, '{"en":"From your first class to async/await: the C# language and the .NET runtime that backend and desktop interviews test.","uk":"Від першого класу до async/await: мова C# і платформа .NET, які перевіряють на співбесідах для backend- та desktop-ролей."}'::jsonb, '[{"en":"Types, variables and nullable reference types","uk":"Типи, змінні та nullable-посилання"},{"en":"Classes, records and structs","uk":"Класи, record і struct"},{"en":"Interfaces, generics and LINQ","uk":"Інтерфейси, узагальнення та LINQ"},{"en":"async/await and Task","uk":"async/await і Task"},{"en":"Dependency injection and ASP.NET Core","uk":"Dependency injection та ASP.NET Core"},{"en":"Testing with xUnit","uk":"Тестування з xUnit"}]'::jsonb, 1),
  ('javascript', '{"en":"JavaScript","uk":"JavaScript"}'::jsonb, '{"en":"The language behind every frontend interview: how values, scope and the event loop really work, from the first line to modern async code.","uk":"Мова, на якій тримаються всі frontend-співбесіди: як насправді працюють значення, область видимості та event loop, від першого рядка до сучасного асинхронного коду."}'::jsonb, '[{"en":"Values, types and coercion","uk":"Значення, типи та приведення типів"},{"en":"Scope, closures and this","uk":"Область видимості, замикання та this"},{"en":"Prototypes and classes","uk":"Прототипи та класи"},{"en":"Promises, async/await and the event loop","uk":"Проміси, async/await і event loop"},{"en":"Modules and the DOM","uk":"Модулі та DOM"},{"en":"Testing and tooling","uk":"Тестування та інструменти"}]'::jsonb, 2)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, topics = excluded.topics,
