  ('csharp', 'arrays', '{"en":"Arrays","uk":"Масиви"}'::jsonb, 5),
  ('csharp', 'collections-strings-files', '{"en":"Collections, strings, files","uk":"Колекції, рядки, файли"}'::jsonb, 6),
